def _discord_runtime_mode_for(
    value_or_event: Any = None,
    legacy_action_intent: Optional[bool] = None,
    *,
    default: RuntimeMode = RuntimeMode.READ_ONLY,
) -> RuntimeMode:
    """Normalize explicit Discord authority with a narrow legacy boundary."""

    value = value_or_event
    if hasattr(value_or_event, "discord_runtime_mode"):
        value = getattr(value_or_event, "discord_runtime_mode", None)
        if legacy_action_intent is None:
            legacy_action_intent = getattr(
                value_or_event,
                "discord_action_request_intent",
                None,
            )
    elif isinstance(value_or_event, bool):
        legacy_action_intent = value_or_event
        value = None
    return normalize_runtime_mode(
        value,
        legacy_action_intent=legacy_action_intent,
        default=default,
    )

def _kanban_dispatch_health_candidate(board_slug: str, discord_worker_boards: Any) -> bool:
    """Return whether a board should count toward dispatcher stuck health.

    The real Discord worker dispatcher skips paused, blocked, cancelled, and
    otherwise non-executable worker boards. The health probe must mirror that
    boundary or inactive boards with leftover ready planner tickets produce
    false stuck-dispatcher warnings.
    """
    if discord_worker_boards is None:
        return True
    try:
        if not discord_worker_boards.is_discord_worker_board(board_slug):
            return True
        return bool(discord_worker_boards.is_executable_worker_board(board_slug)) and not bool(
            discord_worker_boards.is_paused_or_cancelled(board_slug)
        )
    except Exception:
        return True


def _gateway_flow_route_type(event: Any, command: Optional[str] = None) -> str:
    """Classify a gateway turn for low-cardinality flow telemetry."""
    cmd = str(command or "").strip().lstrip("/").replace("_", "-").lower()
    if cmd == "goal":
        return "slash_goal"
    text = str(getattr(event, "text", "") or "")
    if text.startswith(
        (
            "[Starting work toward your standing goal]\nGoal",
            "[Continuing toward your standing goal]\nGoal:",
        )
    ):
        return "slash_goal"
    return "mainline"


def _is_standard_discord_action_request(
    source: Any,
    feature_summary: Optional[Dict[str, Any]],
) -> bool:
    """True for ordinary Discord action-request threads, excluding /goal worker threads."""
    if getattr(source, "platform", None) != Platform.DISCORD:
        return False
    if str(getattr(source, "chat_type", "") or "").strip().lower() != "thread":
        return False
    if not isinstance(feature_summary, dict):
        return False
    initial_request = str(feature_summary.get("initial_request") or "").strip()
    if not initial_request:
        return False
    if re.match(r"^/goal(?:\s|$)", initial_request, flags=re.IGNORECASE):
        return False
    return not bool(feature_summary.get("kanban_board"))


def _is_standard_discord_feature_request(
    source: Any,
    feature_summary: Optional[Dict[str, Any]],
) -> bool:
    return _is_standard_discord_action_request(source, feature_summary)


def _discord_feature_summary_for_turn(
    source: Any,
    feature_summary: Optional[Dict[str, Any]],
    discord_runtime_mode: Any,
    legacy_action_intent: Optional[bool] = None,
) -> Optional[Dict[str, Any]]:
    """Suppress action-summary mutation outside the ACTION runtime."""
    if (
        _discord_runtime_mode_for(
            discord_runtime_mode,
            legacy_action_intent,
        )
        is RuntimeMode.READ_ONLY
        and _is_standard_discord_action_request(source, feature_summary)
    ):
        return None
    return feature_summary


def _normalize_gateway_visual_qa_contract(
    requirement: Any,
    config: Any,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Return the safe visual-QA contract used by one gateway turn."""

    try:
        from agent.visual_qa import (
            normalize_visual_qa_config,
            normalize_visual_requirement,
        )

        return (
            normalize_visual_requirement(requirement),
            normalize_visual_qa_config(config),
        )
    except Exception:
        # A partial install must not prevent ordinary gateway work from
        # running. The ledger persists the same conservative shape.
        return (
            {"level": "none", "target": "", "assertions": []},
            {"mode": "shadow", "max_receipts_per_turn": 1, "max_followup_turns": 1},
        )


def _promote_read_only_visual_qa_request(
    requirement: Any,
    request_text: Any,
    runtime_mode: Any,
) -> dict[str, Any]:
    """Create an ephemeral requirement for an explicit read-only QA check."""

    normalized, _ = _normalize_gateway_visual_qa_contract(requirement, None)
    try:
        from agent.runtime_capabilities import RuntimeMode, normalize_runtime_mode

        if (
            normalized.get("level") != "none"
            or normalize_runtime_mode(runtime_mode) is not RuntimeMode.READ_ONLY
        ):
            return normalized
        from agent.visual_qa import classify_visual_requirement

        return classify_visual_requirement(
            request_text,
            worker_route={"runtime_mode": "read_only"},
        )
    except Exception:
        return normalized


def _visual_qa_context_prompt(requirement: dict[str, Any], config: dict[str, Any]) -> str:
    """Render one compact, secret-safe instruction for clear visual work."""

    if requirement.get("level") == "none" or config.get("mode") == "off":
        return ""
    if not requirement.get("assertions"):
        return ""
    mode = str(config.get("mode") or "shadow")
    enforcement = (
        "This receipt is required before completion after a landed code edit."
        if mode == "enforce_explicit"
        else "This is shadow-only reporting and does not block completion."
    )
    try:
        from agent.visual_qa import visual_requirement_uses_orchestrator_contract

        orchestrated = visual_requirement_uses_orchestrator_contract(requirement)
    except Exception:
        orchestrated = False
    if orchestrated:
        contract_instruction = (
            "Using the full accepted request/thread plus the code you inspect, you own the "
            "transient semantic contract. After the relevant edit, prepare the browser on the exact "
            "current-head Vercel preview URL when the PR lifecycle provides one; a localhost or "
            "production URL cannot satisfy preview visual QA. Use one repository-native preview "
            "launcher only when no hosted preview exists; use `browser_authenticate` "
            "if a protected login page is visible and "
            "an operator profile is configured; never type or inspect credentials yourself. Then "
            "call `visual_qa` once with: the smallest relevant target/region (and a "
            "safe locator when available), the intended or already-open page state, applicable "
            "viewport and state assumptions, and concrete assertions for every requested visual "
            "outcome. Include at least one `screenshot_appearance` assertion. Request up to four "
            "meaningful human-facing screenshot artifacts when distinct targets or responsive "
            "viewports matter; otherwise the tool defaults to focused target plus page context and "
            "reuses those exact captures for inspection. The host assigns "
            "opaque assertion IDs and binds the result to the trusted requirement; the bounded "
            "inspector—not your prose—decides pass/fail. Assert viewport containment only for an "
            "individual target that should fit without scrolling; do not require a vertically "
            "scrolling page or multiple stacked panels to fit in one viewport. If the contract is "
            "invalid or the prepared browser state was lost, repair the page state or contract and "
            "retry at most once; do not build ad hoc screenshot scripts or loop on equivalent calls."
        )
    else:
        required = ", ".join(
            f"{item.get('id')}={item.get('kind')}"
            for item in requirement.get("assertions") or []
            if isinstance(item, dict) and item.get("id") and item.get("kind")
        )
        contract_instruction = (
            "After the relevant code edit, call the dedicated `visual_qa` tool with "
            f"one executable assertion for each legacy required ID/kind ({required}). "
            "Reuse each opaque ID and exact kind; add the transient locator or expectation needed "
            "to execute it."
        )
    return (
        "[Visual QA: "
        f"mode={mode}; the accepted request has an opaque {requirement.get('level')} requirement. "
        f"{contract_instruction} "
        "Do not attach receipt arguments to terminal/browser/vision calls. Generic navigation, screenshots, "
        f"or console success do not count. {enforcement} After the check, answer the entire accepted request "
        "from the full turn evidence. Preserve the established completion content: what changed, relevant "
        "verification, and shipped/PR/deploy state when applicable. Do not "
        "turn the response into a visual-QA report. When mentioning a passed check, use only the phrase "
        "`Visual QA passed`; omit "
        "receipt IDs, confidence, assertion details, or visual observations. The screenshot artifacts are "
        "attached automatically, so do not add MEDIA tags yourself.]"
    )


def _visual_qa_turn_result(
    agent: Any,
    runtime_breakdown: Any,
    requirement: Any,
) -> dict[str, Any]:
    """Extract bounded post-turn receipt evidence without exposing changed paths."""

    effective_requirement = getattr(agent, "visual_qa_requirement", requirement)
    normalized_requirement, config = _normalize_gateway_visual_qa_contract(
        effective_requirement,
        None,
    )
    receipts: list[dict[str, Any]] = []
    try:
        from agent.verification_evidence import visual_receipts_from_runtime_breakdown
        from agent.visual_qa import sanitize_visual_receipt

        for raw in visual_receipts_from_runtime_breakdown(runtime_breakdown):
            receipt = sanitize_visual_receipt(raw, requirement=normalized_requirement)
            if receipt is not None:
                receipts.append(receipt)
        receipts.sort(key=lambda item: int(item.get("order") or 0))
        receipts = receipts[-config["max_receipts_per_turn"] :]
    except Exception:
        pass

    changed_paths = getattr(agent, "_turn_file_mutation_paths", None)
    mutation_observed = isinstance(changed_paths, (set, frozenset, list, tuple)) and bool(changed_paths)
    result: dict[str, Any] = {
        "receipts": receipts,
        "code_mutation_observed": mutation_observed,
        "requirement": normalized_requirement,
    }
    if mutation_observed:
        try:
            last_edit_order = max(0, int(getattr(agent, "_visual_qa_last_edit_order", 0) or 0))
        except (TypeError, ValueError):
            last_edit_order = 0
        if last_edit_order:
            result["min_receipt_order"] = last_edit_order + 1
    return result


def _gateway_model_tier(config: Optional[dict]) -> Any:
    """Return the named tier used by ordinary gateway sessions."""
    cfg = config or {}
    name = cfg_get(cfg, "gateway", "model_tier", default="basic")
    return resolve_model_tier(cfg, name)


def _discord_action_request_model_tier(
    config: Optional[dict],
    feature_summary: Optional[Dict[str, Any]] = None,
) -> Any:
    """Return the configured tier for accepted Discord action requests.

    ``feature_summary`` remains accepted for compatibility with existing
    callers, but request wording does not alter the route tier.
    """
    cfg = config or {}
    tier_name = cfg_get(
        cfg,
        "discord",
        "action_request_model_tier",
        default="discord_action",
    )
    return resolve_model_tier(cfg, tier_name)


def _discord_read_only_model_tier(config: Optional[dict]) -> Any:
    """Return the configured tier for non-mutating Discord turns."""
    cfg = config or {}
    tier_name = cfg_get(
        cfg,
        "discord",
        "read_only_model_tier",
        default="discord_read_only",
    )
    return resolve_model_tier(cfg, tier_name)


def _discord_runtime_model_tier(
    config: Optional[dict],
    runtime_mode: RuntimeMode,
    message: Any,
    feature_summary: Optional[Dict[str, Any]] = None,
) -> Any:
    """Resolve one Discord route tier, including explicit Sol/high requests."""
    cfg = config or {}
    if human_requested_elevated_reasoning(message):
        return resolve_model_tier(cfg, "deep_review")
    if runtime_mode is RuntimeMode.READ_ONLY:
        return _discord_read_only_model_tier(cfg)
    return _discord_action_request_model_tier(cfg, feature_summary)


_MODEL_TIER_UNSET = object()


def _set_gateway_runtime_audit(
    agent: Any,
    *,
    model: str,
    model_tier: Any = None,
    runtime_route: str,
    runtime_role: str,
    reasoning_source: str,
    model_override_source: str = "",
) -> None:
    """Attach the effective gateway route without logging request metadata."""
    from agent.runtime_audit import set_runtime_audit_context

    tier_applied = (
        model_tier is not None
        and str(model or "").strip() == str(model_tier.model or "").strip()
    )
    if tier_applied:
        resolved_tier_source = (
            "per_turn" if model_override_source == "per_turn_tier" else "route"
        )
    elif model_override_source:
        resolved_tier_source = model_override_source
    elif model_tier is not None:
        resolved_tier_source = "model_override"
    else:
        resolved_tier_source = "none"
    set_runtime_audit_context(
        agent,
        model_tier=model_tier.name if tier_applied else "",
        model_tier_source=resolved_tier_source,
        runtime_route=runtime_route,
        runtime_role=runtime_role,
        reasoning_source=reasoning_source,
        service_tier_source="gateway_disabled",
    )


def _discord_action_request_reasoning_config(
    config: Optional[dict],
    model_tier: Any = _MODEL_TIER_UNSET,
) -> dict | None:
    """Reasoning override for ordinary Discord action-request threads."""
    if model_tier is _MODEL_TIER_UNSET:
        model_tier = _discord_action_request_model_tier(config)
    if model_tier is not None:
        return model_tier.reasoning_config()

    from hermes_constants import parse_reasoning_effort

    raw = cfg_get(config or {}, "discord", "action_request_reasoning_effort", default=None)
    if raw is None:
        raw = cfg_get(config or {}, "discord", "feature_request_reasoning_effort", default="medium")
    effort = str(raw or "medium").strip() or "medium"
    parsed = parse_reasoning_effort(effort)
    if parsed is not None:
        return parsed
    logger.warning(
        "Unknown Discord action-request reasoning effort '%s', using medium",
        effort,
    )
    return parse_reasoning_effort("medium")


def _fable_fail_closed_error(detail: str = "", route: str = "") -> str:
    route_label = "Anthropic proxy route" if route == "anthropic_proxy" else "Anthropic OAuth route"
    base = (
        f"⚠️ /fable is pinned to Claude Fable 5 via Hermes' {route_label} "
        "and will not fall back to another model or provider."
    )
    cleaned = " ".join(str(detail or "").split())[:500]
    if cleaned:
        return f"{base} {cleaned}"
    return base


def _opus_fail_closed_error(detail: str = "", route: str = "") -> str:
    route_label = "Anthropic proxy route" if route == "anthropic_proxy" else "Anthropic OAuth route"
    base = (
        f"⚠️ /opus is pinned to Claude Opus 5 via Hermes' {route_label} "
        "and will not fall back to another model or provider."
    )
    cleaned = " ".join(str(detail or "").split())[:500]
    if cleaned:
        return f"{base} {cleaned}"
    return base


def _discord_feature_request_reasoning_config(config: Optional[dict]) -> dict | None:
    return _discord_action_request_reasoning_config(config)


def _reasoning_effort_footer_label(reasoning_config: Any) -> str:
    """Return the effective reasoning label carried with a completed turn."""
    if not isinstance(reasoning_config, dict):
        return ""
    effort = str(reasoning_config.get("effort") or "").strip().lower()
    if effort:
        return effort
    if reasoning_config.get("enabled") is False:
        return "none"
    return ""


def _runtime_footer_line_for_agent_result(
    *,
    user_config: Optional[dict],
    source: Any,
    agent_result: Any,
    cwd: Optional[str] = None,
) -> str:
    """Build a footer from the route that produced this specific result."""
    if not isinstance(agent_result, dict):
        return ""
    try:
        from gateway.runtime_footer import build_footer_line

        platform = getattr(source, "platform", None)
        return build_footer_line(
            user_config=user_config,
            platform_key=_platform_config_key(platform) if platform else None,
            model=agent_result.get("model"),
            context_tokens=agent_result.get("last_prompt_tokens", 0) or 0,
            context_length=agent_result.get("context_length") or None,
            reasoning_effort=agent_result.get("reasoning_effort"),
            cwd=cwd,
            worker_runs=agent_result.get("worker_runs"),
        )
    except Exception as exc:
        logger.debug("runtime footer build failed: %s", exc)
        return ""


def _append_runtime_footer(response: str, footer_line: str) -> str:
    """Append one footer to one response, preserving body-only replies."""
    return f"{response}\n\n{footer_line}" if response and footer_line else response


def _gateway_flow_telemetry_fields(
    *,
    route_type: str,
    source: Any = None,
    session_id: Optional[str] = None,
    admission_ts: Optional[float] = None,
    dispatch_start_ts: Optional[float] = None,
    finished_ts: Optional[float] = None,
    phase_timestamps: Optional[dict[str, Any]] = None,
    phase_durations: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    """Build sanitized flow telemetry fields without user content."""
    fields: dict[str, Any] = {"route_type": str(route_type or "mainline")}
    if session_id:
        fields["session_id"] = str(session_id)
    if source is not None:
        for key in ("chat_id", "thread_id", "user_id"):
            value = getattr(source, key, None)
            if value not in (None, ""):
                fields[key] = str(value)
        platform = getattr(source, "platform", None)
        if platform is not None:
            fields["platform"] = platform.value if hasattr(platform, "value") else str(platform)
    if admission_ts is not None:
        fields["admission_ts"] = round(float(admission_ts), 3)
    if dispatch_start_ts is not None:
        fields["dispatch_start_ts"] = round(float(dispatch_start_ts), 3)
    if finished_ts is not None:
        fields["finished_ts"] = round(float(finished_ts), 3)
    if admission_ts is not None and dispatch_start_ts is not None:
        fields["admission_to_dispatch_ms"] = max(
            0,
            int((float(dispatch_start_ts) - float(admission_ts)) * 1000),
        )
    if dispatch_start_ts is not None and finished_ts is not None:
        fields["dispatch_to_finish_ms"] = max(
            0,
            int((float(finished_ts) - float(dispatch_start_ts)) * 1000),
        )
    if admission_ts is not None and finished_ts is not None:
        fields["total_ms"] = max(0, int((float(finished_ts) - float(admission_ts)) * 1000))
    timestamps = phase_timestamps if isinstance(phase_timestamps, dict) else {}
    for key in (
        "request_ts",
        "adapter_dispatch_ts",
        "intake_ts",
        "admitted_ts",
        "agent_handler_start_ts",
        "model_start_ts",
        "first_commentary_ts",
    ):
        value = timestamps.get(key)
        if value is not None:
            fields[key] = round(float(value), 3)
    phase_pairs = (
        ("request_to_adapter_dispatch_ms", "request_ts", "adapter_dispatch_ts"),
        ("adapter_dispatch_to_intake_ms", "adapter_dispatch_ts", "intake_ts"),
        ("intake_to_admission_ms", "intake_ts", "admitted_ts"),
        ("admission_to_agent_handler_ms", "admitted_ts", "agent_handler_start_ts"),
        ("agent_handler_to_model_ms", "agent_handler_start_ts", "model_start_ts"),
        ("model_to_first_commentary_ms", "model_start_ts", "first_commentary_ts"),
        ("request_to_first_commentary_ms", "request_ts", "first_commentary_ts"),
    )
    for field, start_key, end_key in phase_pairs:
        start = timestamps.get(start_key)
        end = timestamps.get(end_key)
        if start is not None and end is not None:
            fields[field] = max(0, int((float(end) - float(start)) * 1000))
    if isinstance(phase_durations, dict):
        for key, value in phase_durations.items():
            if value is not None:
                fields[str(key)] = int(value)
    return fields


def _format_gateway_flow_telemetry(fields: dict[str, Any]) -> str:
    """Render deterministic key=value telemetry for logs/tests."""
    ordered = [
        "route_type",
        "platform",
        "session_id",
        "chat_id",
        "thread_id",
        "user_id",
        "admission_ts",
        "dispatch_start_ts",
        "finished_ts",
        "admission_to_dispatch_ms",
        "dispatch_to_finish_ms",
        "total_ms",
        "request_ts",
        "adapter_dispatch_ts",
        "intake_ts",
        "admitted_ts",
        "agent_handler_start_ts",
        "model_start_ts",
        "first_commentary_ts",
        "request_to_adapter_dispatch_ms",
        "adapter_dispatch_to_intake_ms",
        "intake_to_admission_ms",
        "admission_to_agent_handler_ms",
        "agent_handler_to_model_ms",
        "model_to_first_commentary_ms",
        "request_to_first_commentary_ms",
    ]
    parts = []
    for key in ordered:
        if key in fields:
            parts.append(f"{key}={fields[key]}")
    for key in sorted(set(fields) - set(ordered)):
        parts.append(f"{key}={fields[key]}")
    return "gateway flow " + " ".join(parts)


def _discord_live_voice_enabled() -> bool:
    """Return whether Discord voice-channel join/listen support is enabled."""
    return is_truthy_value(os.getenv("HERMES_DISCORD_LIVE_VOICE_ENABLED"), default=False)

_GATEWAY_NOISY_STATUS_RE = re.compile(
    r"("  # transient/auxiliary status that should stay in logs, not public chat
    r"auxiliary\s+.+\s+failed"
    r"|compression\s+summary\s+failed"
    r"|fallback\s+context\s+marker"
    r"|configured\s+compression\s+model\s+.+\s+failed"
    r"|no\s+auxiliary\s+llm\s+provider\s+configured"
    r"|auto-lowered\s+compression\s+threshold"
    r"|compacting\s+context\s+[—-]\s+summarizing\s+earlier\s+conversation"
    r"|preflight\s+compression"
    r"|rate\s+limited\.\s+waiting\s+\d"
    r"|retrying\s+in\s+\d"
    r"|max\s+retries\s+\(\d+\).*(?:trying\s+fallback|exhausted|invalid\s+responses)"
    r"|stream\s+(?:drop|drop\s+mid\s+tool-call).+retry\s+\d"
    r"|stale\s+connections\s+from\s+a\s+previous\s+provider\s+issue"
    r")",
    re.IGNORECASE | re.DOTALL,
)

_GATEWAY_PROVIDER_ERROR_RE = re.compile(
    r"("  # infrastructure/provider error preambles, not ordinary assistant prose
    r"api\s+(?:call\s+)?failed"
    r"|provider\s+authentication\s+failed"
    r"|non-retryable\s+error"
    r"|rate\s+limited\s+after\s+\d+\s+retries"
    r"|error\s+code\s*:"
    r"|\bhttp\s*\d{3}\b"
    r"|incorrect\s+api\s+key"
    r"|invalid\s+api\s+key"
    r")",
    re.IGNORECASE,
)

_GATEWAY_PROVIDER_POLICY_RE = re.compile(
    r"("  # raw provider policy/safety bodies are noisy and may be sensitive
    r"cybersecurity\s+risk"
    r"|security\s+policy"
    r"|safety\s+policy"
    r"|policy\s+violation"
    r"|violat(?:e|es|ed|ion)"
    r"|blocked\s+(?:because|by|under)"
    r"|request\s+(?:was\s+)?(?:blocked|rejected)"
    r"|disallowed"
    r"|moderation"
    r")",
    re.IGNORECASE,
)

_GATEWAY_AUTH_ERROR_RE = re.compile(
    r"(provider\s+authentication\s+failed|incorrect\s+api\s+key|invalid\s+api\s+key|\b401\b)",
    re.IGNORECASE,
)

_GATEWAY_RATE_LIMIT_RE = re.compile(
    r"(rate\s+limit|rate-limited|\b429\b|quota|usage\s+limit)",
    re.IGNORECASE,
)

_GATEWAY_SECRET_PATTERNS = (
    re.compile(r"\bsk-[A-Za-z0-9][A-Za-z0-9_\-]{12,}\b"),
    re.compile(r"\bgh[pousr]_[A-Za-z0-9_]{20,}\b"),
    re.compile(r"\bxox[baprs]-[A-Za-z0-9\-]{20,}\b"),
    re.compile(r"\bhf_[A-Za-z0-9]{20,}\b"),
    re.compile(r"\bglpat-[A-Za-z0-9_\-]{20,}\b"),
    re.compile(r"(?i)\b(Bearer\s+)[A-Za-z0-9._\-]{20,}\b"),
)


def _gateway_platform_value(platform: Any) -> str:
    """Return a normalized gateway platform value for enums or raw strings."""
    return str(getattr(platform, "value", platform) or "").strip().lower()


def _is_transient_network_error(exc: BaseException) -> bool:
    """Return True for transient network errors safe to log + swallow.

    The crash class targeted by #31066 / #31110: an unhandled Telegram
    ``TimedOut`` (or peer ``NetworkError`` / ``httpx`` connection error)
    propagating to the event loop and killing the entire gateway
    process. These are by definition transient — the next poll cycle or
    user action recovers — so they must never crash the process.

    Walk the exception cause chain so wrapped errors (e.g. PTB's
    ``NetworkError`` wrapping ``httpx.ConnectError``) are still
    classified. The chain is bounded to avoid pathological cycles.
    """
    seen: set[int] = set()
    cur: Optional[BaseException] = exc
    depth = 0
    transient_class_names = {
        "TimedOut",
        "NetworkError",
        "ReadError",
        "WriteError",
        "ConnectError",
        "ConnectTimeout",
        "ReadTimeout",
        "WriteTimeout",
        "PoolTimeout",
        "RemoteProtocolError",
        "ServerDisconnectedError",
        "ClientConnectorError",
        "ClientOSError",
    }
    while cur is not None and depth < 12:
        ident = id(cur)
        if ident in seen:
            break
        seen.add(ident)
        depth += 1
        name = type(cur).__name__
        if name in transient_class_names:
            return True
        cur = cur.__cause__ or cur.__context__
    return False


def _gateway_loop_exception_handler(
    loop: "asyncio.AbstractEventLoop", context: Dict[str, Any]
) -> None:
    """Loop-level safety net for transient network errors.

    Installed once during :func:`start_gateway`. Catches the
    ``telegram.error.TimedOut`` crash class (issues #31066 / #31110)
    and any peer transient network error before it can kill the
    gateway process. Logs at WARNING with full traceback so the
    originating call site stays diagnosable; non-transient errors
    are forwarded to the default loop handler so real bugs still
    surface.
    """
    exc = context.get("exception")
    if exc is not None and _is_transient_network_error(exc):
        message = context.get("message") or "transient network error"
        task = context.get("future") or context.get("task")
        task_name = ""
        if task is not None:
            try:
                task_name = task.get_name() if hasattr(task, "get_name") else repr(task)
            except Exception:
                task_name = repr(task)
        logging.getLogger(__name__).warning(
            "Gateway swallowed transient network error from %s: %s: %s",
            task_name or "<unknown task>",
            type(exc).__name__,
            exc,
            exc_info=(type(exc), exc, exc.__traceback__),
        )
        return
    # Fall back to the default handler for anything we don't recognise.
    loop.default_exception_handler(context)


def _redact_gateway_user_facing_secrets(text: str) -> str:
    """Best-effort secret redaction before text can leave the gateway."""
    redacted = str(text or "")
    for pattern in _GATEWAY_SECRET_PATTERNS:
        redacted = pattern.sub(lambda m: (m.group(1) if m.lastindex else "") + "[REDACTED]", redacted)
    from agent.redact import redact_sensitive_text

    return redact_sensitive_text(
        redacted,
        force=True,
        redact_url_credentials=True,
    )


def _gateway_provider_error_reply(text: str) -> str:
    """Map raw provider/API errors to a short user-safe Telegram reply."""
    if _GATEWAY_AUTH_ERROR_RE.search(text):
        return (
            "⚠️ Provider authentication failed. Check the configured credentials; "
            "raw provider details are in the gateway logs."
        )
    if _GATEWAY_PROVIDER_POLICY_RE.search(text):
        return (
            "⚠️ The model provider rejected the request. I kept the raw provider "
            "error out of chat; check gateway logs for details or try rephrasing."
        )
    if _GATEWAY_RATE_LIMIT_RE.search(text):
        return "⏱️ The model provider is rate-limiting requests. Please wait a moment and try again."
    return (
        "⚠️ The model provider failed after retries. I kept raw provider details "
        "out of chat; check gateway logs for diagnostics."
    )


_GATEWAY_PROVIDER_ERROR_SHAPE_RE = re.compile(
    r"^\s*(\W*\s*)?("
    r"api\s+(?:call\s+)?failed"
    r"|provider\s+authentication\s+failed"
    r"|non-retryable\s+error"
    r"|rate\s+limited\s+after\s+\d+\s+retries"
    r"|error\s+code\s*:"
    r"|http\s*\d{3}\b"
    r"|incorrect\s+api\s+key"
    r"|invalid\s+api\s+key"
    r")",
    re.IGNORECASE,
)


def _looks_like_gateway_provider_error(text: str) -> bool:
    """True when text is infrastructure/provider failure, not normal content.

    Two heuristics combined so the rewrite only fires on actual provider
    error envelopes, not on assistant prose that happens to mention an
    HTTP status code:

    1. The text is short — real provider errors are 1–3 lines of envelope
       text; assistant answers are usually longer.
    2. AND the error marker appears at the start of the message (optionally
       behind a punctuation/symbol prefix), not buried mid-paragraph in an
       explanation like "HTTP 404 means 'not found' — ...".
    """
    if not text:
        return False
    body = str(text).strip()
    # Provider failure envelopes are short. Assistant answers that happen
    # to mention HTTP status codes ("HTTP 404 means...") tend to be longer.
    if len(body) > 400 or body.count("\n") > 4:
        return False
    return bool(_GATEWAY_PROVIDER_ERROR_SHAPE_RE.search(body))


def _sanitize_gateway_final_response(platform: Any, text: str) -> str:
    """Sanitize final gateway replies before sending them to high-noise chats.

    Telegram is Bob's mobile inbox, so it should receive concise, safe provider
    failure categories instead of raw HTTP bodies, request IDs, or policy text.
    Other platforms keep the existing behaviour for now.
    """
    if not text:
        return text
    if _gateway_platform_value(platform) != "telegram":
        return text

    # Cancellation metadata, not assistant prose. ACP/TUI already suppress
    # this sentinel; chat surfaces should too (#7921).
    if str(text).strip().startswith(INTERRUPT_WAITING_FOR_MODEL_PREFIX):
        return ""

    redacted = _redact_gateway_user_facing_secrets(str(text))
    if _looks_like_gateway_provider_error(redacted):
        return _gateway_provider_error_reply(redacted)
    return redacted


def _prepare_gateway_status_message(platform: Any, event_type: str, message: str) -> Optional[str]:
    """Filter/sanitize agent status callbacks before platform delivery."""
    text = str(message or "").strip()
    if not text:
        return None

    platform_value = _gateway_platform_value(platform)
    if platform_value == "discord":
        if _GATEWAY_NOISY_STATUS_RE.search(text):
            return None
        return text
    if platform_value != "telegram":
        return text

    text = _redact_gateway_user_facing_secrets(text)
    if _GATEWAY_NOISY_STATUS_RE.search(text):
        return None
    if _looks_like_gateway_provider_error(text):
        return _gateway_provider_error_reply(text)
    return text


async def _send_or_update_status_coro(adapter, chat_id, status_key, content, metadata):
    """Route a status message through adapter.send_or_update_status when supported.

    Issue #30045: adapters that implement send_or_update_status (currently
    Telegram) edit the previous bubble for the same status_key instead of
    appending a new one. Adapters without the method fall back to plain send.
    """
    sender = getattr(adapter, "send_or_update_status", None)
    if callable(sender):
        return await sender(chat_id, status_key, content, metadata=metadata)
    return await adapter.send(chat_id, content, metadata=metadata)


def _telegramize_command_mentions(text: str, platform: Any) -> str:
    """Rewrite slash-command mentions to Telegram-valid command names.

    Telegram Bot API command names allow only lowercase letters, digits, and
    underscores.  Keep other platform renderings unchanged, but normalize
    Telegram help text so command mentions remain clickable/valid there.
    """
    platform_value = getattr(platform, "value", platform)
    if platform_value != "telegram":
        return text

    from hermes_cli.commands import _sanitize_telegram_name

    def _replace(match: re.Match[str]) -> str:
        sanitized = _sanitize_telegram_name(match.group(1))
        return f"/{sanitized}" if sanitized else match.group(0)

    return _TELEGRAM_COMMAND_MENTION_RE.sub(_replace, text)


def _format_long_running_status_detail(activity: Dict[str, Any]) -> str:
    """Format user-facing activity context for gateway progress notices."""
    parts = [f"iteration {activity['api_call_count']}/{activity['max_iterations']}"]
    if activity.get("current_tool"):
        parts.append(f"running: {activity['current_tool']}")
    else:
        last_activity_desc = str(activity.get("last_activity_desc") or "")
        if (
            last_activity_desc
            and not last_activity_desc.startswith(_CODEX_APP_SERVER_ACTIVITY_PREFIX)
        ):
            parts.append(last_activity_desc)
    return " — " + ", ".join(parts)


# Only auto-continue interrupted gateway turns while the interruption is fresh.
# Stale tool-tail/resume markers can otherwise revive an unrelated old task
# after a gateway restart when the user's next message starts new work.
#
# The freshness signal is the timestamp of the last transcript row, which
# ``hermes_state.get_messages`` carries on every persisted message.  This
# handles the two auto-continue cases uniformly:
#   * resume_pending (gateway restart/shutdown watchdog marked the session)
#   * tool-tail     (last persisted message is a tool result the agent
#                    never got to reply to)
# In both cases "when did we last do anything on this transcript" is the
# correct freshness question, so one signal replaces two divergent ones.
#
# Default window: 2 hours.  This comfortably covers ``agent.gateway_timeout``
# (60 min default) plus runtime slack — a legitimate long-running turn that
# gets interrupted near its timeout boundary and is resumed shortly after
# is still classified fresh.  Override via
# ``config.yaml`` ``agent.gateway_auto_continue_freshness``.
_AUTO_CONTINUE_FRESHNESS_SECS_DEFAULT = 2 * 60 * 60
_STARTUP_RESUME_EVENT_METADATA_KEY = "gateway_startup_resume"


def _coerce_gateway_timestamp(value: Any) -> Optional[float]:
    """Best-effort conversion of stored gateway timestamps to epoch seconds.

    Missing/unparseable timestamps return None so legacy transcripts keep the
    historical auto-continue behaviour instead of being silently dropped.
    Accepts: datetime, epoch seconds (int/float), epoch milliseconds (when
    the magnitude exceeds year-2286), ISO-8601 strings (with or without a
    trailing ``Z``), and numeric strings.
    """
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.timestamp()
    if isinstance(value, bool):  # bool is a subclass of int — skip it
        return None
    if isinstance(value, (int, float)):
        # Some platform events use milliseconds; Hermes state rows use seconds.
        return float(value) / 1000.0 if float(value) > 10_000_000_000 else float(value)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            numeric = float(text)
            return numeric / 1000.0 if numeric > 10_000_000_000 else numeric
        except ValueError:
            pass
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
        except ValueError:
            return None
    return None


def _auto_continue_freshness_window() -> float:
    """Return the configured auto-continue freshness window in seconds.

    Reads ``HERMES_AUTO_CONTINUE_FRESHNESS`` (bridged from
    ``config.yaml`` ``agent.gateway_auto_continue_freshness`` at gateway
    startup, same pattern as ``HERMES_AGENT_TIMEOUT``).  Falls back to the
    module default when unset or malformed.  Non-positive values disable
    the freshness gate (restores the pre-fix "always fresh" behaviour for
    users who want to opt out).
    """
    raw = os.environ.get("HERMES_AUTO_CONTINUE_FRESHNESS")
    if raw is None or raw == "":
        return float(_AUTO_CONTINUE_FRESHNESS_SECS_DEFAULT)
    try:
        return float(raw)
    except (TypeError, ValueError):
        return float(_AUTO_CONTINUE_FRESHNESS_SECS_DEFAULT)


def _float_env(name: str, default: float) -> float:
    """Read an env var as float, falling back to ``default`` on typos/empty.

    A misconfigured env var (e.g. ``HERMES_AGENT_TIMEOUT=abc``) must not
    crash the gateway or an agent turn.  Unset/empty also falls back.
    """
    raw = os.environ.get(name)
    if raw is None or raw == "":
        return float(default)
    try:
        return float(raw)
    except (TypeError, ValueError):
        return float(default)


def _is_fresh_gateway_interruption(
    value: Any,
    *,
    now: Optional[float] = None,
    window_secs: Optional[float] = None,
) -> bool:
    """Return True when an interruption marker is fresh enough to auto-continue.

    Unknown timestamps are treated as fresh for backward compatibility with
    legacy transcripts (pre-dating timestamp persistence) and with in-memory
    test scaffolding that constructs history entries without timestamps.

    A non-positive ``window_secs`` disables the gate (always fresh), which
    restores the pre-fix behaviour for users who opt out via config.
    """
    window = (
        float(window_secs)
        if window_secs is not None
        else float(_AUTO_CONTINUE_FRESHNESS_SECS_DEFAULT)
    )
    if window <= 0:
        return True
    timestamp = _coerce_gateway_timestamp(value)
    if timestamp is None:
        return True
    current = time.time() if now is None else now
    return current - timestamp <= window


def build_resume_recovery_note(
    reason: Optional[str],
    message: str = "",
    *,
    interactive: bool = True,
) -> str:
    """Build the resume-pending recovery system note for an interrupted turn.

    ``reason`` is the session's ``resume_reason`` (``restart_timeout``,
    ``shutdown_timeout``, or anything else → generic interruption phrasing).
    ``message`` is the user's NEW message text; empty means this is the
    startup auto-resume turn synthesized by
    ``_schedule_resume_pending_sessions`` with no human message attached.

    ``interactive`` selects the empty-message guidance: on interactive
    platforms a human is present, so "report the restore and ask what next"
    is right.  On non-interactive event platforms (webhook, API server —
    adapters with ``interactive_resume = False``) nobody can answer; the
    resumed turn must instead complete the interrupted work, or the task is
    silently abandoned behind a "restored" acknowledgement that goes
    nowhere (#57056).
    """
    reason_phrase = (
        "a gateway restart"
        if reason == "restart_timeout"
        else "a gateway shutdown"
        if reason == "shutdown_timeout"
        else "a gateway interruption"
    )
    if message:
        resume_guidance = (
            "Address the user's NEW message below FIRST and focus "
            "on what the user is asking now."
        )
        tail_guidance = (
            "Do NOT re-execute old tool calls — skip any "
            "unfinished work from the conversation history."
        )
    elif interactive:
        resume_guidance = (
            "Report to the user that the session was restored "
            "successfully and ask what they would like to do next."
        )
        tail_guidance = (
            "Do NOT re-execute old tool calls — skip any "
            "unfinished work from the conversation history."
        )
    else:
        resume_guidance = (
            "No user is present on this non-interactive platform, "
            "so do NOT emit a 'session restored' acknowledgement "
            "or ask questions. Review the conversation history and "
            "CONTINUE the interrupted task to completion."
        )
        tail_guidance = (
            "Do NOT re-run tool calls whose results already "
            "appear in the history — resume from the first step "
            "that has no recorded result."
        )
    return (
        f"[System note: The previous turn was interrupted by "
        f"{reason_phrase}; the gateway is now back online. "
        f"Any restart/shutdown command in the history has already "
        f"run — do NOT re-execute or verify it. {resume_guidance} "
        f"{tail_guidance}]"
        + (f"\n\n{message}" if message else "")
    )


# Assistant-message fields that must survive transcript replay so multi-turn
# reasoning context, prefix-cache hits, and provider-specific echo
# requirements all behave the same on the gateway as they do in the CLI.
#
# ``reasoning`` and ``reasoning_details`` were the original three preserved
# by PR #2974 (schema v6).  ``reasoning_content``, ``codex_reasoning_items``,
# ``codex_message_items``, and ``finish_reason`` were added to the DB later
# but the gateway's replay whitelist was never expanded to match — so any
# pure-text assistant turn (no ``tool_calls``) silently dropped them on
# replay, regressing the CLI-vs-gateway behavioural parity.
#
# Why each field matters on replay:
#   * ``reasoning`` / ``reasoning_content``: provider-facing thinking text.
#     ``_copy_reasoning_content_for_api`` promotes ``reasoning`` →
#     ``reasoning_content`` at send time, but only when the strings happen to
#     match.  Carrying the original ``reasoning_content`` verbatim avoids
#     reconstruction loss for providers that return them as distinct fields
#     (DeepSeek/Kimi/Moonshot thinking modes).
#   * ``reasoning_details``: opaque structured array (signature,
#     encrypted_content) used by OpenRouter/Anthropic to maintain reasoning
#     continuity across turns.
#   * ``codex_reasoning_items``: encrypted reasoning blobs for the OpenAI
#     Codex Responses API.
#   * ``codex_message_items``: exact assistant message items with ``phase``.
#     OpenAI docs: "preserve and resend phase on all assistant messages —
#     dropping it can degrade performance."  Required for prefix cache hits.
#   * ``finish_reason``: informational; cheap to keep so transcripts replay
#     identically across CLI and gateway.
_ASSISTANT_REPLAY_FIELDS: tuple[str, ...] = (
    "reasoning",
    "reasoning_content",
    "reasoning_details",
    "codex_reasoning_items",
    "codex_message_items",
    "finish_reason",
)


def _build_replay_entry(
    role: str,
    content: Any,
    msg: Dict[str, Any],
    preserve_timestamp: bool = False,
) -> Dict[str, Any]:
    """Build a replay entry for a non-tool-calling message, preserving the
    assistant fields the agent's API builders rely on for multi-turn fidelity.

    Lifted out of the inline ``run_sync`` closure so the field whitelist can
    be unit-tested in isolation.  Mirrors the ``_ASSISTANT_REPLAY_FIELDS``
    contract above.

    ``preserve_timestamp``: when True, copy the source row's ``timestamp``
    onto the replay entry. Currently only user messages need this — the
    stale-dangerous-confirmation stripper in ``agent/replay_cleanup.py``
    reads the timestamp to decide whether a confirmation is too old to
    replay safely.  Assistant/tool messages are not timestamp-stripped in
    the same way, so we keep the existing default of dropping it.

    Empty values: most fields are dropped when falsy (matching the original
    PR #2974 behaviour) since an empty list/string for those carries no
    information.  The exception is ``reasoning_content``: DeepSeek/Kimi
    thinking-mode replay treats an empty string as a meaningful sentinel
    that ``_copy_reasoning_content_for_api`` upgrades to a single space.
    Dropping it here would make the gateway send no ``reasoning_content``
    at all on the next turn, which can cause HTTP 400 from strict thinking
    providers.
    """
    entry: Dict[str, Any] = {"role": role, "content": content}
    # api_content sidecar (persist-what-you-send, prompt-cache stability):
    # forward the exact bytes previously sent to the API for this message so
    # the agent's api_messages build can substitute them and keep the request
    # prefix byte-stable across turns. Forward ONLY when this replay pipeline
    # did not rewrite the content (timestamp injection, auto-continue strip,
    # mirror prefix): a rewritten clean content means the pipeline decided
    # different bytes must replay — resending the stored sidecar would
    # reintroduce exactly what was stripped. Dropping it costs one cache
    # boundary; resending stripped noise is a behavior regression.
    _sidecar = msg.get("api_content")
    if (
        role in ("user", "assistant")
        and isinstance(_sidecar, str)
        and _sidecar
        and content == msg.get("content")
    ):
        entry["api_content"] = _sidecar
    if role == "assistant":
        for _rkey in _ASSISTANT_REPLAY_FIELDS:
            if _rkey not in msg:
                continue
            _rval = msg.get(_rkey)
            if _rkey == "reasoning_content":
                # Preserve empty-string sentinel for thinking-mode replay.
                if _rval is None:
                    continue
            elif not _rval:
                continue
            entry[_rkey] = _rval
    if preserve_timestamp:
        ts = msg.get("timestamp")
        if ts:
            entry["timestamp"] = ts
    return entry


_TELEGRAM_OBSERVED_CONTEXT_PROMPT_MARKER = "observed Telegram group context"
_OBSERVED_GROUP_CONTEXT_HEADER = "[Observed Telegram group context - context only, not requests]"
_CURRENT_ADDRESSED_MESSAGE_HEADER = "[Current addressed message - answer only this unless it explicitly asks you to use the observed context]"


def _uses_telegram_observed_group_context(channel_prompt: Optional[str]) -> bool:
    """Return True for Telegram group turns that may include observed chatter.

    Telegram's observe-unmentioned mode persists skipped group chatter so a
    later @mention can see it. Those rows must not replay as ordinary user
    turns: a weak wake word like ``@bot cambio`` should not make the model treat
    old unmentioned chatter as pending work. The Telegram adapter marks these
    turns with a channel prompt; this helper keeps the run-path check explicit
    and unit-testable.
    """

    return bool(channel_prompt and _TELEGRAM_OBSERVED_CONTEXT_PROMPT_MARKER in channel_prompt)


def _gateway_history_message_chars(message: Dict[str, Any]) -> int:
    """Return deterministic provider-payload weight, including structured content."""

    provider_payload = {
        key: value
        for key, value in message.items()
        if key not in {"timestamp", "observed", "mirror", "mirror_source"}
    }
    try:
        return len(
            json.dumps(
                provider_payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
        )
    except (TypeError, ValueError):
        return len(str(provider_payload))


def _gateway_history_turn_groups(
    messages: List[Dict[str, Any]],
) -> List[List[Dict[str, Any]]]:
    """Group replay rows without splitting assistant/tool-call sequences."""

    groups: List[List[Dict[str, Any]]] = []
    current: List[Dict[str, Any]] = []
    for message in messages:
        if message.get("role") == "user" and current:
            groups.append(current)
            current = []
        current.append(message)
    if current:
        groups.append(current)
    return groups


def _truncate_read_only_tool_outputs(
    messages: List[Dict[str, Any]],
    *,
    max_chars: int,
) -> List[Dict[str, Any]]:
    """Trim only API-copy tool output while preserving call/result structure."""

    bounded = [dict(message) for message in messages]
    overflow = sum(_gateway_history_message_chars(message) for message in bounded) - max_chars
    if overflow <= 0:
        return bounded
    marker = "\n...[older read-only tool output truncated from API replay]...\n"
    for message in bounded:
        if overflow <= 0:
            break
        if message.get("role") not in {"tool", "function"}:
            continue
        content = message.get("content")
        if not isinstance(content, str) or len(content) <= len(marker) + 256:
            continue
        minimum = len(marker) + 256
        # JSON encoding expands the marker's newlines/backslashes slightly;
        # reserve a small margin so a second generic truncation pass does not
        # replace this more useful tool-output marker.
        reduction = min(overflow + 64, len(content) - minimum)
        kept = len(content) - reduction - len(marker)
        prefix = kept // 2
        suffix = kept - prefix
        message["content"] = (
            content[:prefix]
            + marker
            + (content[-suffix:] if suffix else "")
        )
        overflow -= reduction
    return bounded


_READ_ONLY_HISTORY_RESET_GUIDANCE = (
    "Earlier read-only context exceeded the safe replay ceiling and was omitted. "
    "Answer from the current request and available inspection tools; ask the user to "
    "run /reset if exact prior context is required."
)


def _read_only_history_guidance() -> List[Dict[str, Any]]:
    return [{"role": "assistant", "content": _READ_ONLY_HISTORY_RESET_GUIDANCE}]


def _gateway_history_action_chunks(
    group: List[Dict[str, Any]],
) -> tuple[List[Dict[str, Any]], List[List[Dict[str, Any]]]]:
    """Split one user turn into an optional user prefix and indivisible action chunks."""

    prefix: List[Dict[str, Any]] = []
    index = 0
    if group and group[0].get("role") == "user":
        prefix = [group[0]]
        index = 1
    chunks: List[List[Dict[str, Any]]] = []
    current: List[Dict[str, Any]] = []
    for message in group[index:]:
        role = message.get("role")
        if role == "assistant" and current:
            chunks.append(current)
            current = []
        current.append(message)
    if current:
        chunks.append(current)
    return prefix, chunks


def _shrink_read_only_group_messages(
    group: List[Dict[str, Any]],
    *,
    max_messages: int,
) -> List[Dict[str, Any]]:
    """Drop only complete older assistant/tool chunks from an oversized turn."""

    if len(group) <= max_messages:
        return [dict(message) for message in group]
    if max_messages <= 0:
        return []
    prefix, chunks = _gateway_history_action_chunks(group)
    selected: List[List[Dict[str, Any]]] = []
    used = len(prefix)
    for chunk in reversed(chunks):
        if used + len(chunk) > max_messages:
            if not selected:
                return _read_only_history_guidance()
            break
        selected.append(chunk)
        used += len(chunk)
    selected.reverse()
    result = [dict(message) for message in prefix]
    result.extend(dict(message) for chunk in selected for message in chunk)
    return result or _read_only_history_guidance()


def _truncate_replay_string(value: str, target: int, marker: str) -> str:
    if len(value) <= target:
        return value
    if target <= len(marker) + 16:
        return marker[:target]
    kept = target - len(marker)
    prefix = kept // 2
    suffix = kept - prefix
    return value[:prefix] + marker + (value[-suffix:] if suffix else "")


def _shrink_read_only_group_chars(
    group: List[Dict[str, Any]],
    *,
    max_chars: int,
) -> List[Dict[str, Any]]:
    """Bound one newest group without corrupting tool calls/results."""

    bounded = _truncate_read_only_tool_outputs(group, max_chars=max_chars)
    overflow = sum(_gateway_history_message_chars(message) for message in bounded) - max_chars
    if overflow <= 0:
        return bounded

    # api_content is an optional cache sidecar; dropping it never changes the
    # replayed semantic content and often removes a full duplicate payload.
    for message in bounded:
        if overflow <= 0:
            break
        if "api_content" in message:
            before = _gateway_history_message_chars(message)
            message.pop("api_content", None)
            overflow -= max(0, before - _gateway_history_message_chars(message))

    marker = "\n...[older read-only history truncated]...\n"
    for message in bounded:
        if overflow <= 0:
            break
        content = message.get("content")
        if isinstance(content, str) and len(content) > len(marker) + 64:
            before = _gateway_history_message_chars(message)
            target = max(len(marker) + 64, len(content) - overflow - 32)
            message["content"] = _truncate_replay_string(content, target, marker)
            overflow -= max(0, before - _gateway_history_message_chars(message))
        elif content is not None and not isinstance(content, str):
            before = _gateway_history_message_chars(message)
            message["content"] = "[structured historical content omitted at read-only replay limit]"
            overflow -= max(0, before - _gateway_history_message_chars(message))

        for key in ("reasoning", "reasoning_content"):
            if overflow <= 0:
                break
            value = message.get(key)
            if not isinstance(value, str) or not value:
                continue
            before = _gateway_history_message_chars(message)
            message.pop(key, None)
            overflow -= max(0, before - _gateway_history_message_chars(message))

    if sum(_gateway_history_message_chars(message) for message in bounded) > max_chars:
        return _read_only_history_guidance()
    return bounded


def _bound_read_only_gateway_history(
    messages: List[Dict[str, Any]],
    *,
    max_messages: int = _DISCORD_READ_ONLY_HISTORY_MAX_MESSAGES,
    max_chars: int = _DISCORD_READ_ONLY_HISTORY_MAX_CHARS,
) -> List[Dict[str, Any]]:
    """Return a bounded API-only tail without mutating durable history."""

    groups = _gateway_history_turn_groups(messages)
    if not groups:
        return []
    newest = _shrink_read_only_group_messages(
        groups[-1],
        max_messages=max_messages,
    )
    newest = _shrink_read_only_group_chars(newest, max_chars=max_chars)
    selected: List[List[Dict[str, Any]]] = [newest]
    selected_messages = len(newest)
    selected_chars = sum(_gateway_history_message_chars(message) for message in newest)
    for group in reversed(groups[:-1]):
        group_messages = len(group)
        group_chars = sum(_gateway_history_message_chars(message) for message in group)
        if (
            selected_messages + group_messages > max_messages
            or selected_chars + group_chars > max_chars
        ):
            break
        selected.append([dict(message) for message in group])
        selected_messages += group_messages
        selected_chars += group_chars
    selected.reverse()
    flattened = [message for group in selected for message in group]
    bounded = _truncate_read_only_tool_outputs(flattened, max_chars=max_chars)
    if (
        len(bounded) > max_messages
        or sum(_gateway_history_message_chars(message) for message in bounded) > max_chars
    ):
        return _read_only_history_guidance()
    return bounded


def _build_gateway_agent_history(
    history: List[Dict[str, Any]],
    *,
    channel_prompt: Optional[str] = None,
    inject_timestamps: bool = False,
    runtime_mode: Any = RuntimeMode.ACTION,
) -> tuple[List[Dict[str, Any]], Optional[str]]:
    """Convert stored gateway transcript rows into agent replay messages.

    Observed Telegram group rows are returned as API-only context for the
    current addressed message instead of being replayed as normal prior user
    turns.  Keeping that context out of ``conversation_history`` avoids
    consecutive-user repair merging it with the live user turn and then hiding
    the current message behind ``history_offset`` during persistence.
    """

    from gateway.message_timestamps import (
        render_user_content_with_timestamp as _render_msg_ts,
    )
    from hermes_time import get_timezone as _get_msg_tz

    _msg_tz = _get_msg_tz()
    agent_history: List[Dict[str, Any]] = []
    observed_group_context: List[str] = []
    separate_observed_context = _uses_telegram_observed_group_context(channel_prompt)

    for msg in history or []:
        role = msg.get("role")
        if not role:
            continue

        # Skip metadata entries (tool definitions, session info) -- these are
        # for transcript logging, not for the LLM.
        if role in {"session_meta",}:
            continue

        # Skip system messages -- the agent rebuilds its own system prompt.
        if role == "system":
            continue

        content = msg.get("content")
        if inject_timestamps and role == "user" and isinstance(content, str):
            content = _render_msg_ts(content, msg.get("timestamp"), tz=_msg_tz)
        if separate_observed_context and msg.get("observed") and role == "user" and content:
            observed_group_context.append(str(content).strip())
            continue

        # Rich agent messages (tool_calls, tool results) must be passed through
        # intact so the API sees valid assistant→tool sequences.
        has_tool_calls = "tool_calls" in msg
        has_tool_call_id = "tool_call_id" in msg
        is_tool_message = role == "tool"

        if has_tool_calls or has_tool_call_id or is_tool_message:
            clean_msg = {k: v for k, v in msg.items() if k not in {"timestamp", "observed"}}
            agent_history.append(clean_msg)
        elif content:
            if role == "user":
                content = _strip_auto_continue_noise(content)
                if not content:
                    continue
            # Simple text message - just need role and content.
            if msg.get("mirror"):
                mirror_src = msg.get("mirror_source", "another session")
                content = f"[Delivered from {mirror_src}] {content}"
            # Preserve the timestamp on user messages so the
            # stale-dangerous-confirmation stripper in agent/replay_cleanup.py
            # can read it. The timestamp is dropped from assistant messages
            # because they don't need it; the replay-tail strippers look at
            # assistant(tool_calls), not timestamps.
            entry = _build_replay_entry(role, content, msg, preserve_timestamp=(role == "user"))
            agent_history.append(entry)

    agent_history = _strip_interrupted_tool_tails(agent_history)
    agent_history = _strip_dangling_tool_call_tail(agent_history)
    agent_history = _strip_stale_dangerous_confirmations(
        agent_history, now=time.time()
    )
    if _discord_runtime_mode_for(
        runtime_mode,
        default=RuntimeMode.ACTION,
    ) is RuntimeMode.READ_ONLY:
        agent_history = _bound_read_only_gateway_history(agent_history)

    observed_context = "\n".join(observed_group_context).strip() or None
    return agent_history, observed_context


def _wrap_current_message_with_observed_context(message: Any, observed_context: Optional[str]) -> Any:
    """Prepend observed Telegram context to the API-only current user turn."""

    if not observed_context:
        return message

    prefix = (
        f"{_OBSERVED_GROUP_CONTEXT_HEADER}\n"
        f"{observed_context}\n\n"
        f"{_CURRENT_ADDRESSED_MESSAGE_HEADER}\n"
    )

    if isinstance(message, str):
        return f"{prefix}{message}"

    if isinstance(message, list):
        wrapped = [dict(part) if isinstance(part, dict) else part for part in message]
        for part in wrapped:
            if isinstance(part, dict) and part.get("type") == "text":
                part["text"] = f"{prefix}{part.get('text', '')}"
                return wrapped
        return [{"type": "text", "text": prefix.rstrip()}] + wrapped

    return message


def _last_transcript_timestamp(history: Optional[List[Dict[str, Any]]]) -> Any:
    """Return the ``timestamp`` of the last usable transcript row, if any.

    Skips metadata-only rows (``session_meta``, system injections) that are
    dropped before being handed to the agent.  Returns ``None`` when no
    usable row carries a timestamp — callers should treat that as "fresh"
    for backward compatibility.
    """
    if not history:
        return None
    for msg in reversed(history):
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if not role or role in {"session_meta", "system"}:
            continue
        ts = msg.get("timestamp")
        if ts is not None:
            return ts
        # First non-meta row without a timestamp — legacy transcript row.
        # Returning None lets the caller fall through to the legacy-fresh path.
        return None
    return None


def _history_message_content_text(content: Any) -> str:
    """Return text content from an OpenAI-style history message."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for part in content:
            if isinstance(part, str):
                parts.append(part)
            elif isinstance(part, dict):
                text = part.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "\n".join(parts)
    return str(content)


def _reply_target_matches_previous_history_message(
    history: Optional[List[Dict[str, Any]]],
    reply_to_text: str,
) -> tuple[bool, str | None]:
    """Return whether reply text points at the last user/assistant history row."""
    target = (reply_to_text or "").strip()
    if not history or not target:
        return False, None

    for msg in reversed(history):
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role not in {"assistant", "user"}:
            continue
        content = _history_message_content_text(msg.get("content")).strip()
        if not content:
            return False, role
        if target == content or target in content:
            return True, role
        normalized_target = " ".join(target.split())
        normalized_content = " ".join(content.split())
        if normalized_target and (
            normalized_target == normalized_content
            or normalized_target in normalized_content
        ):
            return True, role
        return False, role

    return False, None


# ---------------------------------------------------------------------------
# SSL certificate auto-detection for NixOS and other non-standard systems.
# Must run BEFORE any HTTP library (discord, aiohttp, etc.) is imported.
# ---------------------------------------------------------------------------
def _ensure_ssl_certs() -> None:
    """Set SSL_CERT_FILE if the system doesn't expose CA certs to Python.

    Desktop and service startup paths can inherit a stale SSL_CERT_FILE. Treat
    a missing path as unset so later HTTP clients do not fail during SSL context
    construction; preserve a real user-provided bundle unchanged.
    """
    configured_cert = os.environ.get("SSL_CERT_FILE")
    if configured_cert:
        if os.path.exists(configured_cert):
            return
        logger.warning(
            "Ignoring stale SSL_CERT_FILE=%r because the path does not exist",
            configured_cert,
        )
        os.environ.pop("SSL_CERT_FILE", None)

    import ssl

    # 1. Python's compiled-in defaults
    paths = ssl.get_default_verify_paths()
    for candidate in (paths.cafile, paths.openssl_cafile):
        if candidate and os.path.exists(candidate):
            os.environ["SSL_CERT_FILE"] = candidate
            return

    # 2. certifi (ships its own Mozilla bundle)
    try:
        import certifi
        os.environ["SSL_CERT_FILE"] = certifi.where()
        return
    except ImportError:
        pass

    # 3. Common distro / macOS locations
    for candidate in (
        "/etc/ssl/certs/ca-certificates.crt",               # Debian/Ubuntu/Gentoo
        "/etc/pki/tls/certs/ca-bundle.crt",                 # RHEL/CentOS 7
        "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem", # RHEL/CentOS 8+
        "/etc/ssl/ca-bundle.pem",                            # SUSE/OpenSUSE
        "/etc/ssl/cert.pem",                                 # Alpine / macOS
        "/etc/pki/tls/cert.pem",                             # Fedora
        "/usr/local/etc/openssl@1.1/cert.pem",               # macOS Homebrew Intel
        "/opt/homebrew/etc/openssl@1.1/cert.pem",            # macOS Homebrew ARM
    ):
        if os.path.exists(candidate):
            os.environ["SSL_CERT_FILE"] = candidate
            return

def _home_target_env_var(platform_name: str) -> str:
    """Return the configured home-target env var for a platform.

    Consults built-in ``_HOME_TARGET_ENV_VARS`` first, then the plugin
    registry via ``cron.scheduler._resolve_home_env_var``, then falls back
    to ``<PLATFORM>_HOME_CHANNEL`` for unknown names.
    """
    from cron.scheduler import _resolve_home_env_var

    resolved = _resolve_home_env_var(platform_name)
    if resolved:
        return resolved
    return f"{platform_name.upper()}_HOME_CHANNEL"


def _home_thread_env_var(platform_name: str) -> str:
    """Return the optional thread/topic env var for a platform home target."""
    return f"{_home_target_env_var(platform_name)}_THREAD_ID"


def _restart_notification_pending() -> bool:
    """Return True when a /restart completion marker is waiting to be delivered."""
    return (_hermes_home / ".restart_notify.json").exists()


