# Feishu is mode-conditional (websocket is outbound; webhook binds), while
# WhatsApp Cloud and LINE always own inbound HTTP listeners.
from gateway.config import (
    PORT_BINDING_PLATFORM_VALUES as _PORT_BINDING_PLATFORM_VALUES,
    platform_binds_port as _platform_binds_port,
)


from agent.secret_scope import set_multiplex_active


class MultiplexConfigError(RuntimeError):
    """A profile multiplexer config is invalid (fail-fast at startup)."""


class SecondaryPortBindingConfigError(MultiplexConfigError):
    """A secondary profile conflicts with the multiplexer's shared listener."""


@_contextmanager
def _profile_runtime_scope(profile_home: "Path"):
    """Scope config/skills/memory and credentials to a profile for one turn."""
    from hermes_constants import set_hermes_home_override, reset_hermes_home_override
    from agent.secret_scope import (
        build_profile_secret_scope,
        set_secret_scope,
        reset_secret_scope,
    )

    profile_path = Path(profile_home)
    home_token = set_hermes_home_override(str(profile_path))
    secret_token = set_secret_scope(build_profile_secret_scope(profile_path))
    try:
        yield
    finally:
        reset_secret_scope(secret_token)
        reset_hermes_home_override(home_token)


def load_gateway_config_for_runner() -> "GatewayConfig":
    """Load gateway config for the process-level GatewayRunner.

    When ``gateway.multiplex_profiles`` is off, this is identical to
    ``load_gateway_config()`` (legacy single-profile path).

    When multiplexing is on, reload under the default/active profile's
    ``_profile_runtime_scope`` so platform tokens in that profile's ``.env``
    resolve through the secret scope — the same path secondary profiles use
    in ``_start_one_profile_adapters``. Without this, primary startup calls
    ``load_gateway_config()`` unscoped: ``_getenv`` falls through to
    ``os.environ``, which often has no ``TELEGRAM_BOT_TOKEN`` once the token
    lives only under ``profiles/<name>/.env`` (#64674).

    Single-profile gateways never set ``multiplex_profiles``, so they keep the
    unscoped load and are unaffected.
    """
    cfg = load_gateway_config()
    if not getattr(cfg, "multiplex_profiles", False):
        return cfg
    try:
        home = get_hermes_home()
    except Exception:
        return cfg
    try:
        with _profile_runtime_scope(Path(home)):
            return load_gateway_config()
    except Exception:
        logger.debug(
            "multiplex default-scope config reload failed; using unscoped load",
            exc_info=True,
        )
        return cfg


def _platform_has_bot_credential(platform: "Platform", platform_config: "PlatformConfig") -> bool:
    """Return True when a token-authenticated platform has a usable bot credential.

    Platforms that do not use ``PlatformConfig.token`` always return True so we
    never skip them here (Signal session paths, port-binding HTTP adapters, etc.).
    """
    from gateway.config import PLATFORM_TOKEN_ENV_NAMES

    if platform not in PLATFORM_TOKEN_ENV_NAMES:
        return True
    token = getattr(platform_config, "token", None) or ""
    if isinstance(token, str) and token.strip():
        return True
    # Some adapters also accept api_key as the primary credential.
    api_key = getattr(platform_config, "api_key", None) or ""
    if isinstance(api_key, str) and api_key.strip():
        return True
    return False


_DOCKER_VOLUME_SPEC_RE = re.compile(r"^(?P<host>.+):(?P<container>/[^:]+?)(?::(?P<options>[^:]+))?$")
_DOCKER_MEDIA_OUTPUT_CONTAINER_PATHS = {"/output", "/outputs"}


def _bridge_gateway_config_to_env(
    cfg: dict,
    env: Optional[dict] = None,
    hermes_home: Optional[Path | str] = None,
) -> dict:
    """Bridge gateway config values into environment variables.

    ``config.yaml`` is authoritative for terminal settings.  Top-level
    ``cwd``/``backend`` are convenience aliases, but nested ``terminal``
    values take precedence when present. Placeholder cwd values are resolved
    with backend-aware semantics so container/SSH gateways do not inherit the
    host Hermes home as a bogus remote working directory.
    """
    from gateway.cwd_placeholder import CWD_PLACEHOLDERS, resolve_placeholder_terminal_cwd

    target_env = env if env is not None else os.environ

    # Top-level simple values (fallback only — don't override .env)
    for key, val in cfg.items():
        if isinstance(val, (str, int, float, bool)) and key not in target_env:
            target_env[key] = str(val)

    terminal_cfg = cfg.get("terminal", {})
    if terminal_cfg and isinstance(terminal_cfg, dict):
        terminal_backend = str(
            terminal_cfg.get("backend")
            or terminal_cfg.get("env_type")
            or target_env.get("TERMINAL_ENV")
            or ""
        ).strip().lower()
        terminal_env_map = {
            "backend": "TERMINAL_ENV",
            "cwd": "TERMINAL_CWD",
            "timeout": "TERMINAL_TIMEOUT",
            "home_mode": "TERMINAL_HOME_MODE",
            "lifetime_seconds": "TERMINAL_LIFETIME_SECONDS",
            "docker_image": "TERMINAL_DOCKER_IMAGE",
            "docker_forward_env": "TERMINAL_DOCKER_FORWARD_ENV",
            "singularity_image": "TERMINAL_SINGULARITY_IMAGE",
            "modal_image": "TERMINAL_MODAL_IMAGE",
            "daytona_image": "TERMINAL_DAYTONA_IMAGE",
            "vercel_runtime": "TERMINAL_VERCEL_RUNTIME",
            "ssh_host": "TERMINAL_SSH_HOST",
            "ssh_user": "TERMINAL_SSH_USER",
            "ssh_port": "TERMINAL_SSH_PORT",
            "ssh_key": "TERMINAL_SSH_KEY",
            "container_cpu": "TERMINAL_CONTAINER_CPU",
            "container_memory": "TERMINAL_CONTAINER_MEMORY",
            "container_disk": "TERMINAL_CONTAINER_DISK",
            "container_persistent": "TERMINAL_CONTAINER_PERSISTENT",
            "docker_volumes": "TERMINAL_DOCKER_VOLUMES",
            "docker_env": "TERMINAL_DOCKER_ENV",
            "docker_extra_args": "TERMINAL_DOCKER_EXTRA_ARGS",
            "docker_mount_cwd_to_workspace": "TERMINAL_DOCKER_MOUNT_CWD_TO_WORKSPACE",
            "docker_network": "TERMINAL_DOCKER_NETWORK",
            "docker_run_as_host_user": "TERMINAL_DOCKER_RUN_AS_HOST_USER",
            "docker_persist_across_processes": "TERMINAL_DOCKER_PERSIST_ACROSS_PROCESSES",
            "docker_orphan_reaper": "TERMINAL_DOCKER_ORPHAN_REAPER",
            "sandbox_dir": "TERMINAL_SANDBOX_DIR",
            "persistent_shell": "TERMINAL_PERSISTENT_SHELL",
        }
        for cfg_key, env_var in terminal_env_map.items():
            if cfg_key in terminal_cfg:
                val = terminal_cfg[cfg_key]
                if cfg_key == "cwd" and str(val) in CWD_PLACEHOLDERS:
                    continue
                if cfg_key == "cwd" and isinstance(val, str):
                    stripped = val.strip()
                    ssh_remote_tilde = terminal_backend == "ssh" and (
                        stripped == "~" or stripped.startswith("~/")
                    )
                    if not ssh_remote_tilde:
                        val = os.path.expanduser(stripped)
                if isinstance(val, (list, dict)):
                    target_env[env_var] = json.dumps(val)
                else:
                    target_env[env_var] = str(val)

        # Legacy nested spelling used by older gateway configs.
        if "backend" not in terminal_cfg and "env_type" in terminal_cfg:
            val = terminal_cfg["env_type"]
            if isinstance(val, (list, dict)):
                target_env["TERMINAL_ENV"] = json.dumps(val)
            else:
                target_env["TERMINAL_ENV"] = str(val)

    # Top-level aliases are fallback config spellings.  Nested terminal.* wins
    # even over stale env values, so only apply aliases when the nested key is
    # absent (including legacy terminal.env_type for backend).
    terminal_has_cwd = isinstance(terminal_cfg, dict) and "cwd" in terminal_cfg
    terminal_has_backend = isinstance(terminal_cfg, dict) and (
        "backend" in terminal_cfg or "env_type" in terminal_cfg
    )
    if not terminal_has_cwd:
        alias_val = cfg.get("cwd")
        if isinstance(alias_val, str) and alias_val.strip():
            target_env["TERMINAL_CWD"] = os.path.expanduser(alias_val.strip())
    if not terminal_has_backend:
        alias_val = cfg.get("backend")
        if isinstance(alias_val, str) and alias_val.strip():
            target_env["TERMINAL_ENV"] = alias_val.strip()

    gateway_cfg = cfg.get("gateway", {})
    if isinstance(gateway_cfg, dict):
        # This env var is an explicit operator escape hatch, unlike the
        # config-authoritative agent/display bridges. Preserve a non-empty
        # existing value; otherwise let gateway.platform_connect_timeout
        # supply the connect and Discord ready-wait timeout.
        if (
            "platform_connect_timeout" in gateway_cfg
            and not str(
                target_env.get("HERMES_GATEWAY_PLATFORM_CONNECT_TIMEOUT", "")
            ).strip()
        ):
            target_env["HERMES_GATEWAY_PLATFORM_CONNECT_TIMEOUT"] = str(
                gateway_cfg["platform_connect_timeout"]
            )

    configured_cwd = str(target_env.get("TERMINAL_CWD", "")).strip()
    if not configured_cwd or configured_cwd in CWD_PLACEHOLDERS:
        resolved_cwd = resolve_placeholder_terminal_cwd(
            configured_cwd=configured_cwd,
            terminal_backend=str(target_env.get("TERMINAL_ENV", "")),
            messaging_cwd=target_env.get("MESSAGING_CWD"),
            docker_mount_cwd_to_workspace=str(
                target_env.get("TERMINAL_DOCKER_MOUNT_CWD_TO_WORKSPACE", "false")
            ).lower()
            in {"true", "1", "yes"},
            home_fallback=str(hermes_home or get_hermes_home()),
        )
        if resolved_cwd is None:
            target_env.pop("TERMINAL_CWD", None)
        else:
            target_env["TERMINAL_CWD"] = resolved_cwd

    return target_env


# Bridge config.yaml values into the environment so os.getenv() picks them up.
# config.yaml is authoritative for terminal settings — overrides .env.
_config_path = _hermes_home / 'config.yaml'
if _config_path.exists():
    try:
        import yaml as _yaml
        with open(_config_path, encoding="utf-8") as _f:
            _cfg = _yaml.safe_load(_f) or {}
        # Expand ${ENV_VAR} references before bridging to env vars.
        from hermes_cli.config import _expand_env_vars
        _cfg = _expand_env_vars(_cfg)
        _bridge_gateway_config_to_env(_cfg, os.environ, _hermes_home)
        # Compression config is read directly from config.yaml by run_agent.py
        # and auxiliary_client.py — no env var bridging needed.
        # Auxiliary model/direct-endpoint overrides (vision, web_extract,
        # approval, plus any plugin-registered auxiliary tasks).
        # Each task has provider/model/base_url/api_key; bridge non-default
        # values to env vars named AUXILIARY_<KEY_UPPER>_*. The legacy
        # hard-coded list (vision/web_extract/approval) is replaced by a
        # dynamic loop so plugin-registered tasks benefit from the same
        # config→env bridging without core knowing about each one.
        _auxiliary_cfg = _cfg.get("auxiliary", {})
        if _auxiliary_cfg and isinstance(_auxiliary_cfg, dict):
            # Built-in tasks that previously had explicit env-var bridging.
            # Kept here as the canonical bridged set; plugin tasks are added
            # below via the plugin auxiliary registry.
            _aux_bridged_keys = {"vision", "web_extract", "approval"}
            try:
                from hermes_cli.plugins import get_plugin_auxiliary_tasks
                for _entry in get_plugin_auxiliary_tasks():
                    _aux_bridged_keys.add(_entry["key"])
            except Exception:
                # Plugin discovery failure must not break gateway startup;
                # built-in bridging stays intact.
                pass

            for _task_key in _aux_bridged_keys:
                _task_cfg = _auxiliary_cfg.get(_task_key, {})
                if not isinstance(_task_cfg, dict):
                    continue
                _prov = str(_task_cfg.get("provider", "")).strip()
                _model = str(_task_cfg.get("model", "")).strip()
                _base_url = str(_task_cfg.get("base_url", "")).strip()
                _api_key = str(_task_cfg.get("api_key", "")).strip()
                _upper = _task_key.upper()
                if _prov and _prov != "auto":
                    os.environ[f"AUXILIARY_{_upper}_PROVIDER"] = _prov
                if _model:
                    os.environ[f"AUXILIARY_{_upper}_MODEL"] = _model
                if _base_url:
                    os.environ[f"AUXILIARY_{_upper}_BASE_URL"] = _base_url
                if _api_key:
                    os.environ[f"AUXILIARY_{_upper}_API_KEY"] = _api_key
        # config.yaml is the documented, authoritative source for these
        # settings — it unconditionally wins over .env values. Previously
        # the guards below read `if X not in os.environ` and let stale
        # .env entries (e.g. HERMES_MAX_ITERATIONS=60 written by an old
        # `hermes setup` run) silently shadow the user's current config.
        # See PR #18413 / the 60-vs-500 max_turns incident.
        _agent_cfg = _cfg.get("agent", {})
        if _agent_cfg and isinstance(_agent_cfg, dict):
            if "max_turns" in _agent_cfg:
                os.environ["HERMES_MAX_ITERATIONS"] = str(_agent_cfg["max_turns"])
            if "gateway_timeout" in _agent_cfg:
                os.environ["HERMES_AGENT_TIMEOUT"] = str(_agent_cfg["gateway_timeout"])
            if "gateway_timeout_warning" in _agent_cfg:
                os.environ["HERMES_AGENT_TIMEOUT_WARNING"] = str(_agent_cfg["gateway_timeout_warning"])
            if "gateway_notify_interval" in _agent_cfg:
                os.environ["HERMES_AGENT_NOTIFY_INTERVAL"] = str(_agent_cfg["gateway_notify_interval"])
            if "restart_drain_timeout" in _agent_cfg:
                os.environ["HERMES_RESTART_DRAIN_TIMEOUT"] = str(_agent_cfg["restart_drain_timeout"])
            if "gateway_auto_continue_freshness" in _agent_cfg:
                os.environ["HERMES_AUTO_CONTINUE_FRESHNESS"] = str(
                    _agent_cfg["gateway_auto_continue_freshness"]
                )
        _display_cfg = _cfg.get("display", {})
        if _display_cfg and isinstance(_display_cfg, dict):
            if "busy_input_mode" in _display_cfg:
                os.environ["HERMES_GATEWAY_BUSY_INPUT_MODE"] = str(_display_cfg["busy_input_mode"])
            if "busy_text_mode" in _display_cfg:
                os.environ["HERMES_GATEWAY_BUSY_TEXT_MODE"] = str(_display_cfg["busy_text_mode"])
            if "busy_ack_enabled" in _display_cfg:
                os.environ["HERMES_GATEWAY_BUSY_ACK_ENABLED"] = str(_display_cfg["busy_ack_enabled"])
            # This process-level env var is documented as an override for
            # service managers, so preserve it when already set. Other display
            # bridges stay config-authoritative for backwards compatibility.
            if (
                "busy_steer_ack_enabled" in _display_cfg
                and "HERMES_GATEWAY_BUSY_STEER_ACK_ENABLED" not in os.environ
            ):
                os.environ["HERMES_GATEWAY_BUSY_STEER_ACK_ENABLED"] = str(
                    _display_cfg["busy_steer_ack_enabled"]
                )
        # Timezone: bridge config.yaml → HERMES_TIMEZONE env var.
        _tz_cfg = _cfg.get("timezone", "")
        if _tz_cfg and isinstance(_tz_cfg, str):
            os.environ["HERMES_TIMEZONE"] = _tz_cfg.strip()
        # Security settings
        _security_cfg = _cfg.get("security", {})
        if isinstance(_security_cfg, dict):
            _redact = _security_cfg.get("redact_secrets")
            if _redact is not None:
                os.environ["HERMES_REDACT_SECRETS"] = str(_redact).lower()
        # Gateway settings (media delivery allowlist + recency trust + strict mode)
        _gateway_cfg = _cfg.get("gateway", {})
        if isinstance(_gateway_cfg, dict):
            _strict = _gateway_cfg.get("strict")
            if _strict is not None:
                os.environ["HERMES_MEDIA_DELIVERY_STRICT"] = (
                    "1" if _strict else "0"
                )
            _allow_dirs = _gateway_cfg.get("media_delivery_allow_dirs")
            if _allow_dirs:
                if isinstance(_allow_dirs, str):
                    _allow_dirs_str = _allow_dirs
                elif isinstance(_allow_dirs, (list, tuple)):
                    _allow_dirs_str = os.pathsep.join(str(p) for p in _allow_dirs if p)
                else:
                    _allow_dirs_str = ""
                if _allow_dirs_str:
                    os.environ["HERMES_MEDIA_ALLOW_DIRS"] = _allow_dirs_str
            _trust_recent = _gateway_cfg.get("trust_recent_files")
            if _trust_recent is not None:
                os.environ["HERMES_MEDIA_TRUST_RECENT_FILES"] = (
                    "1" if _trust_recent else "0"
                )
            _trust_recent_seconds = _gateway_cfg.get("trust_recent_files_seconds")
            if _trust_recent_seconds is not None:
                os.environ["HERMES_MEDIA_TRUST_RECENT_SECONDS"] = str(_trust_recent_seconds)
    except Exception as _bridge_err:
        # Previously this was silent (`except Exception: pass`), which
        # hid partial bridge failures and let .env defaults shadow
        # config.yaml values — users observed max_turns=500 in config
        # but a 60-iteration cap in practice. Surface the failure to
        # stderr so operators see it even though `logger` is not yet
        # initialized at module-import time (logger is defined further
        # down this module).
        print(
            f"  Warning: config.yaml → env bridge failed: "
            f"{type(_bridge_err).__name__}: {_bridge_err}",
            file=sys.stderr,
        )
        print(
            "  Gateway will fall back to .env values, which may not match "
            "your current config.yaml. Run `hermes doctor` to investigate.",
            file=sys.stderr,
        )

