def _is_control_interrupt_message(message: Optional[str]) -> bool:
    """Return True when an interrupt message is internal control flow."""
    if not message:
        return False
    normalized = " ".join(str(message).strip().split()).lower()
    return normalized in _CONTROL_INTERRUPT_MESSAGES


def _skill_slug_from_frontmatter(skill_md: Path) -> tuple[str | None, str | None]:
    """Derive the /command slug and declared frontmatter name from a SKILL.md.

    Matches the exact normalization used by
    :func:`agent.skill_commands.scan_skill_commands` so the slug here is the
    same string a user types after the leading ``/`` (e.g. a skill with
    frontmatter ``name: Stable Diffusion Image Generation`` resolves to
    ``stable-diffusion-image-generation`` — NOT the parent directory name,
    which is commonly shorter/different, e.g. ``stable-diffusion``).

    Using the directory name silently broke :func:`_check_unavailable_skill`
    for every skill whose directory name drifted from its frontmatter name
    (19 such skills on a standard install as of 2026-05), causing a generic
    "unknown command" response where a "disabled — enable with …" or
    "not installed — install with …" hint was expected.

    Returns ``(slug, declared_name)`` or ``(None, None)`` when the file
    can't be read or lacks a ``name:`` in its frontmatter.
    """
    try:
        content = skill_md.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None, None
    content = content.lstrip("\ufeff")  # tolerate UTF-8 BOM (Windows editors)
    if not content.startswith("---"):
        return None, None
    end = content.find("\n---", 3)
    if end < 0:
        return None, None
    declared_name: str | None = None
    for line in content[3:end].splitlines():
        line = line.strip()
        if line.startswith("name:"):
            raw = line.split(":", 1)[1].strip()
            # Strip YAML quote wrappers if present
            if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {'"', "'"}:
                raw = raw[1:-1]
            declared_name = raw.strip()
            break
    if not declared_name:
        return None, None
    slug = declared_name.lower().replace(" ", "-").replace("_", "-")
    # Mirror _SKILL_INVALID_CHARS and _SKILL_MULTI_HYPHEN from skill_commands
    import re as _re
    slug = _re.sub(r"[^a-z0-9-]", "", slug)
    slug = _re.sub(r"-{2,}", "-", slug).strip("-")
    if not slug:
        return None, declared_name
    return slug, declared_name


def _check_unavailable_skill(command_name: str) -> str | None:
    """Check if a command matches a known-but-inactive skill.

    Returns a helpful message if the skill exists but is disabled or only
    available as an optional install. Returns None if no match found.

    The slug for each on-disk skill is derived from its frontmatter ``name:``
    (via :func:`_skill_slug_from_frontmatter`), NOT from its containing
    directory name — because the two can differ (e.g. directory
    ``stable-diffusion`` + frontmatter ``Stable Diffusion Image Generation``
    yields slug ``stable-diffusion-image-generation``). Matching on
    directory name would miss that slug entirely and fall through to the
    generic "unknown command" path.
    """
    # Normalize: command uses hyphens, skill names may use hyphens or underscores
    normalized = command_name.lower().replace("_", "-")
    try:
        from tools.skills_tool import _get_disabled_skill_names
        from agent.skill_utils import get_all_skills_dirs, is_excluded_skill_path
        disabled = _get_disabled_skill_names()

        # Check disabled skills across all dirs (local + external)
        for skills_dir in get_all_skills_dirs():
            if not skills_dir.exists():
                continue
            for skill_md in skills_dir.rglob("SKILL.md"):
                if is_excluded_skill_path(skill_md):
                    continue
                slug, declared_name = _skill_slug_from_frontmatter(skill_md)
                if not slug or not declared_name:
                    continue
                # disabled is keyed by the declared frontmatter name (what
                # skills.disabled / skills.platform_disabled store).
                if slug == normalized and declared_name in disabled:
                    return (
                        f"The **{command_name}** skill is installed but disabled.\n"
                        f"Enable it with: `hermes skills config`"
                    )

        # Check optional skills (shipped with repo but not installed)
        from hermes_constants import get_optional_skills_dir
        repo_root = Path(__file__).resolve().parent.parent
        optional_dir = get_optional_skills_dir(repo_root / "optional-skills")
        if optional_dir.exists():
            for skill_md in optional_dir.rglob("SKILL.md"):
                if is_excluded_skill_path(skill_md):
                    continue
                slug, _declared = _skill_slug_from_frontmatter(skill_md)
                if not slug:
                    continue
                if slug == normalized:
                    # Build install path: official/<category>/<name>
                    rel = skill_md.parent.relative_to(optional_dir)
                    parts = list(rel.parts)
                    install_path = f"official/{'/'.join(parts)}"
                    return (
                        f"The **{command_name}** skill is available but not installed.\n"
                        f"Install it with: `hermes skills install {install_path}`"
                    )
    except Exception:
        pass
    return None


def _platform_config_key(platform: "Platform") -> str:
    """Map a Platform enum to its config.yaml key (LOCAL→"cli", rest→enum value)."""
    return "cli" if platform == Platform.LOCAL else platform.value


def _teams_pipeline_plugin_enabled() -> bool:
    """Return True when the standalone Teams pipeline plugin is enabled."""
    config = _load_gateway_config()
    enabled = cfg_get(config, "plugins", "enabled", default=[])
    if not isinstance(enabled, list):
        return False
    return "teams_pipeline" in enabled or "teams-pipeline" in enabled


def _gateway_config_home() -> Path:
    """Return the Hermes home that gateway config reads should use."""
    override = get_hermes_home_override()
    if override:
        return Path(override)
    return _hermes_home


def _load_gateway_config() -> dict:
    """Load and parse the active profile's config.yaml, returning {} on error.

    Honors a live ``HERMES_HOME`` override while retaining the module-level
    ``_hermes_home`` fallback (so tests that monkeypatch it still see their
    fixture), and shares the mtime-keyed raw-yaml cache from
    ``hermes_cli.config.read_raw_config`` when the paths match. Administrator-
    managed values are overlaid after either raw-load path so profile routing,
    plugin config, environment expansion, and secret resolution keep their
    existing lifecycle while managed leaves remain authoritative.
    """
    config_path = _gateway_config_home() / 'config.yaml'
    raw: dict = {}
    used_canonical = False
    try:
        from hermes_cli.config import get_config_path, read_raw_config
        # Fast path: if _hermes_home agrees with the canonical config
        # location, reuse the shared cache. Otherwise fall through to a
        # direct read (keeps test fixtures with a monkeypatched
        # _hermes_home working).
        if config_path == get_config_path():
            raw = read_raw_config()
            used_canonical = True
    except Exception:
        pass

    if not used_canonical:
        try:
            if config_path.exists():
                import yaml
                with open(config_path, 'r', encoding='utf-8') as f:
                    raw = yaml.safe_load(f) or {}
        except Exception:
            logger.debug("Could not load gateway config from %s", config_path)
            raw = {}

    # read_raw_config() and direct YAML reads intentionally return only the
    # user's raw profile config. Apply administrator-pinned leaves here on both
    # paths; the helper is fail-open and a no-op when managed scope is absent.
    try:
        from hermes_cli import managed_scope

        raw = managed_scope.apply_managed_overlay(
            raw if isinstance(raw, dict) else {}
        )
    except Exception:
        pass
    return raw if isinstance(raw, dict) else {}


def _expand_configured_cwd(value: Any, *, fallback: Optional[str] = None) -> str:
    raw = str(value or "").strip()
    if not raw or raw in {".", "auto", "cwd"}:
        raw = fallback or str(get_hermes_home())
    return os.path.expanduser(os.path.expandvars(raw))


def _default_gateway_session_cwd(config: Optional[dict] = None) -> str:
    cfg = config or {}
    configured = cfg_get(cfg, "terminal", "cwd", default="")
    return _expand_configured_cwd(configured, fallback=str(get_hermes_home()))


def _configured_channel_cwds(config: Optional[dict] = None) -> dict[str, str]:
    raw = cfg_get(config or {}, "discord", "channel_cwds", default={})
    if not isinstance(raw, dict):
        return {}
    out: dict[str, str] = {}
    for key, value in raw.items():
        channel_id = str(key or "").strip()
        cwd = str(value or "").strip()
        if channel_id and cwd:
            out[channel_id] = _expand_configured_cwd(cwd)
    return out


def _discord_source_channel_ids(source: Any) -> list[str]:
    ids: list[str] = []
    for value in (
        getattr(source, "chat_id", None),
        getattr(source, "parent_chat_id", None),
        getattr(source, "project_channel_id", None),
    ):
        text = str(value or "").strip()
        if text and text not in ids:
            ids.append(text)
    return ids


def _configured_id_set(raw: Any) -> set[str]:
    """Normalize comma-separated/list config values containing platform ids."""
    if raw is None:
        return set()
    if isinstance(raw, str):
        values = re.split(r"[,\s]+", raw)
    elif isinstance(raw, (list, tuple, set)):
        values = list(raw)
    else:
        values = [raw]
    return {str(v).strip() for v in values if str(v or "").strip()}


def _discord_default_kanban_intake_channels(config: Optional[dict] = None) -> set[str]:
    cfg = config or {}
    raw = cfg_get(
        cfg,
        "kanban",
        "discord_intake",
        "default_board_channels",
        default=None,
    )
    if not raw:
        # Backward-compatible alias for early private configs.
        raw = cfg_get(cfg, "discord", "default_kanban_intake_channels", default="")
    return _configured_id_set(raw)


def _resolve_default_board_intake_assignee(config: Optional[dict] = None) -> str:
    """Return a valid profile for default-board Discord intake tasks."""
    cfg = config or {}
    raw_default = cfg_get(cfg, "kanban", "default_assignee", default="")
    candidates = [str(raw_default or "").strip()]
    try:
        from hermes_cli.profiles import get_active_profile_name

        candidates.append(get_active_profile_name())
    except Exception:
        pass
    candidates.append("default")

    try:
        from hermes_cli.profiles import normalize_profile_name, profile_exists
    except Exception:
        return "default"
    for candidate in candidates:
        if not candidate:
            continue
        try:
            normalized = normalize_profile_name(candidate)
        except Exception:
            continue
        try:
            if profile_exists(normalized):
                return normalized
        except Exception:
            continue
    return "default"


def _assign_default_board_intake_ready_tasks(
    conn: sqlite3.Connection,
    assignee: str,
) -> list[str]:
    """Assign legacy READY+unassigned default-board Discord intake tasks."""
    profile = str(assignee or "").strip()
    if not profile:
        return []
    rows = conn.execute(
        "SELECT id FROM tasks "
        "WHERE status = 'ready' AND claim_lock IS NULL "
        "AND (assignee IS NULL OR trim(assignee) = '') "
        "AND (created_by = 'discord-default-intake' "
        "OR tenant = 'discord-default-intake') "
        "ORDER BY priority DESC, created_at ASC"
    ).fetchall()
    if not rows:
        return []
    try:
        from hermes_cli import kanban_db as _kb
    except Exception:
        return []
    assigned: list[str] = []
    for row in rows:
        task_id = str(row["id"])
        try:
            if _kb.assign_task(conn, task_id, profile):
                assigned.append(task_id)
        except Exception:
            logger.debug(
                "kanban dispatcher: failed to assign default-board intake task %s",
                task_id,
                exc_info=True,
            )
    return assigned


def _resolve_gateway_session_cwd(
    source: Any,
    config: Optional[dict] = None,
) -> str:
    """Resolve the task-local cwd for one gateway turn.

    TERMINAL_CWD remains the process/global default.  This function handles
    per-message overrides without mutating process-global state, which matters
    because gateway turns can run concurrently.
    """
    cfg = config or {}
    default_cwd = _default_gateway_session_cwd(cfg)

    if getattr(source, "platform", None) != Platform.DISCORD:
        return default_cwd

    channel_ids = _discord_source_channel_ids(source)
    for channel_id, cwd in _configured_channel_cwds(cfg).items():
        if channel_id in channel_ids:
            return cwd

    mapped_project_path = str(getattr(source, "project_path", "") or "").strip()
    if mapped_project_path:
        mapped_project_path = os.path.expanduser(os.path.expandvars(mapped_project_path))
        if Path(mapped_project_path).is_dir():
            return mapped_project_path
        logger.warning(
            "Mapped Discord project path does not exist; using configured project fallback: %s",
            mapped_project_path,
        )

    if getattr(source, "project_channel_id", None):
        project_cwd = cfg_get(cfg, "discord", "project_channel_cwd", default="")
        if str(project_cwd or "").strip():
            return _expand_configured_cwd(project_cwd, fallback=default_cwd)

    return default_cwd


def _discord_action_worktree_slug(value: Any, *, fallback: str = "project") -> str:
    """Return a Git/path-safe lowercase slug for action worktree names."""
    slug = re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().lower()).strip("-")
    return (slug or fallback)[:48].rstrip("-") or fallback


def _discord_action_worktree_records(output: str) -> list[dict[str, str]]:
    """Parse the bounded fields needed from ``git worktree --porcelain``."""
    records: list[dict[str, str]] = []
    current: dict[str, str] = {}
    for raw_line in str(output or "").splitlines():
        line = raw_line.rstrip()
        if not line:
            if current:
                records.append(current)
                current = {}
            continue
        if line.startswith("worktree "):
            if current:
                records.append(current)
            current = {"path": line[len("worktree ") :]}
        elif line.startswith("branch "):
            branch = line[len("branch ") :]
            if branch.startswith("refs/heads/"):
                branch = branch[len("refs/heads/") :]
            current["branch"] = branch
    if current:
        records.append(current)
    return records


def _discord_action_worktree_warmup_command(
    worktree_root: Path,
) -> tuple[Optional[str], Optional[list[str]]]:
    """Return the unambiguous JS dependency warm-up command, if any."""
    if (worktree_root / "pnpm-lock.yaml").is_file():
        return "pnpm", [
            "pnpm",
            "install",
            "--frozen-lockfile",
            "--prefer-offline",
        ]
    if (worktree_root / "package-lock.json").is_file():
        return "npm", [
            "npm",
            "ci",
            "--prefer-offline",
            "--no-audit",
            "--no-fund",
        ]
    if (worktree_root / "yarn.lock").is_file():
        return "yarn", None
    return None, None


def _discord_action_worktree_warmup_targets(
    worktree_root: Path,
) -> list[tuple[Path, str, Optional[list[str]]]]:
    """Return root and nested JS package roots without traversing build output."""

    try:
        from hermes_cli.worktree_runtime import javascript_package_roots

        package_roots = javascript_package_roots(worktree_root)
    except Exception:
        package_roots = [worktree_root]
    root_manager, _root_command = _discord_action_worktree_warmup_command(worktree_root)
    if root_manager and worktree_root.resolve(strict=False) not in package_roots:
        package_roots.insert(0, worktree_root.resolve(strict=False))
    targets: list[tuple[Path, str, Optional[list[str]]]] = []
    for package_root in package_roots:
        manager, command = _discord_action_worktree_warmup_command(package_root)
        if manager:
            targets.append((package_root, manager, command))
    return targets


def _run_discord_action_worktree_warmup(
    command: list[str],
    *,
    cwd: Path,
    timeout: float,
) -> Any:
    """Run one dependency warm-up with output captured for bounded logging."""
    import subprocess

    with tempfile.TemporaryFile(mode="w+b") as output:
        try:
            completed = subprocess.run(
                command,
                cwd=str(cwd),
                stdout=output,
                stderr=subprocess.STDOUT,
                timeout=timeout,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            output.seek(0)
            exc.output = output.read(801)
            raise
        output.seek(0)
        captured = output.read(801)
    return subprocess.CompletedProcess(
        completed.args,
        completed.returncode,
        stdout=captured,
    )


def _discord_action_worktree_warmup_output(output: Any, *, limit: int = 800) -> str:
    """Return a single bounded log line from package-manager output."""
    if isinstance(output, bytes):
        output = output.decode("utf-8", errors="replace")
    detail = _redact_gateway_user_facing_secrets(
        " ".join(str(output or "").split())
    )
    if len(detail) <= limit:
        return detail
    return f"{detail[:limit]}..."


def _discord_action_worktree_warmup(
    worktree_root: Path,
    config: Optional[dict],
) -> None:
    """Best-effort JS dependency warm-up for a newly created action worktree."""
    mode = str(
        cfg_get(
            config or {},
            "discord",
            "action_worktree_warmup",
            default="auto",
        )
        or "auto"
    ).strip().lower()
    if mode == "off":
        logger.info(
            "Discord action worktree provisioning for %s: warmup skipped: off",
            worktree_root,
        )
        return

    targets = _discord_action_worktree_warmup_targets(worktree_root)
    if not targets:
        logger.info(
            "Discord action worktree provisioning for %s: warmup skipped: no lockfile",
            worktree_root,
        )
        return

    raw_timeout = cfg_get(
        config or {},
        "discord",
        "action_worktree_warmup_timeout_seconds",
        default=180,
    )
    try:
        timeout = float(raw_timeout)
        if timeout <= 0:
            raise ValueError
    except (TypeError, ValueError):
        timeout = 180.0

    import subprocess

    overall_started = time.monotonic()
    for package_root, manager, command in targets:
        if manager == "yarn":
            logger.info(
                "Discord action worktree provisioning for %s: warmup skipped: "
                "yarn.lock has ambiguous yarn variants",
                package_root,
            )
            continue
        modules = package_root / "node_modules"
        if modules.is_symlink():
            logger.info(
                "Discord action worktree provisioning for %s: warmup skipped: "
                "exact-lock node_modules link already prepared",
                package_root,
            )
            continue
        if command is None:
            continue
        elapsed_total = time.monotonic() - overall_started
        remaining = timeout - elapsed_total
        if remaining <= 0:
            logger.warning(
                "Discord action worktree provisioning for %s: warmup failed "
                "(continuing): total timeout %.1fs exhausted",
                package_root,
                timeout,
            )
            return
        started = time.monotonic()
        try:
            completed = _run_discord_action_worktree_warmup(
                command,
                cwd=package_root,
                timeout=remaining,
            )
        except subprocess.TimeoutExpired as exc:
            elapsed = time.monotonic() - started
            detail = _discord_action_worktree_warmup_output(
                getattr(exc, "stdout", None)
                or getattr(exc, "output", None)
                or getattr(exc, "stderr", None)
            )
            logger.warning(
                "Discord action worktree provisioning for %s: warmup failed "
                "(continuing): %s timed out after %.1fs (%.1fs elapsed)%s",
                package_root,
                manager,
                remaining,
                elapsed,
                f": {detail}" if detail else "",
            )
            return
        except Exception as exc:
            elapsed = time.monotonic() - started
            detail = _discord_action_worktree_warmup_output(exc)
            logger.warning(
                "Discord action worktree provisioning for %s: warmup failed "
                "(continuing): %s could not run after %.1fs: %s",
                package_root,
                manager,
                elapsed,
                detail,
            )
            continue

        elapsed = time.monotonic() - started
        if completed.returncode == 0:
            logger.info(
                "Discord action worktree provisioning for %s: warmup %s %.1fs ok",
                package_root,
                manager,
                elapsed,
            )
            continue

        detail = _discord_action_worktree_warmup_output(completed.stdout)
        logger.warning(
            "Discord action worktree provisioning for %s: warmup failed (continuing): "
            "%s exited %s after %.1fs%s",
            package_root,
            manager,
            completed.returncode,
            elapsed,
            f": {detail}" if detail else "",
        )


def _discord_action_worktree_target(
    repo_root: Path,
    source: Any,
    session_key: str,
    pr_generation: int = 1,
) -> tuple[str, Path]:
    """Return a stable branch/path pair for one thread PR generation."""
    repo_slug = _discord_action_worktree_slug(repo_root.name)
    thread_identity = (
        getattr(source, "thread_id", None)
        or getattr(source, "chat_id", None)
        or session_key
    )
    route_identity = "|".join(
        str(value or "").strip()
        for value in (
            repo_root,
            getattr(source, "guild_id", None),
            getattr(source, "project_channel_id", None),
            getattr(source, "parent_chat_id", None),
            thread_identity,
        )
    )
    digest = hashlib.sha256(route_identity.encode("utf-8", errors="replace")).hexdigest()[:12]
    try:
        generation = max(1, int(pr_generation))
    except (TypeError, ValueError, OverflowError):
        generation = 1
    generation_suffix = "" if generation == 1 else f"-pr{generation}"
    stem = f"{repo_slug}-discord-action-{digest}{generation_suffix}"
    return (
        f"discord-action/{repo_slug}-{digest}{generation_suffix}",
        _DISCORD_ACTION_WORKTREE_ROOT / stem,
    )


def _discord_action_worktree_preflight_prompt(worktree_cwd: str) -> str:
    """Return one bounded deterministic Git snapshot for the action model."""

    try:
        from hermes_cli.pr_workflow_preflight import collect_pr_workflow_preflight

        summary = collect_pr_workflow_preflight(
            worktree_cwd,
            base_branch="origin/main",
            max_output_chars=3_200,
        )
        output = str(summary.get("output") or "").strip()
    except Exception as exc:
        logger.warning(
            "Discord action worktree preflight unavailable for %s: %s",
            worktree_cwd,
            exc,
        )
        return ""
    if not output:
        return ""
    return (
        "Discord action worktree preflight (deterministic, bounded; do not repeat "
        "status/log/branches/diff/rebase discovery unless this snapshot shows a "
        "specific issue):\n" + output
    )


def _path_within(path: Path, root: Path) -> bool:
    try:
        path.resolve(strict=False).relative_to(root.resolve(strict=False))
        return True
    except Exception:
        return False


def _discord_action_worktree_cwd(
    source: Any,
    feature_summary: Optional[Dict[str, Any]],
    session_key: str,
    config: Optional[dict] = None,
    *,
    provision: bool = True,
    pr_generation: int = 1,
) -> tuple[Optional[str], Optional[str]]:
    """Resolve, and optionally create, a Discord action-thread worktree.

    Only protected canonical project mappings are redirected. Existing mutable
    mappings and every non-action gateway route keep their established CWD
    behavior. The branch/path identity is stable per Discord thread, so later
    turns reuse the same worktree while unrelated threads cannot collide.
    Read-only turns may observe an already-existing action worktree but never
    create directories, branches, worktrees, dependency links, or warmup state.
    """
    if not _is_standard_discord_action_request(source, feature_summary):
        return None, None

    mapped_value = str(getattr(source, "project_path", "") or "").strip()
    if not mapped_value:
        return None, None

    mapped_path = Path(mapped_value).expanduser().resolve(strict=False)
    workspace_root = _DISCORD_ACTION_WORKTREE_ROOT.expanduser().resolve(strict=False)
    relative_cwd: Optional[Path] = None
    import subprocess

    try:
        from tools.canonical_repo_guard import _repo_info_for_path

        info = _repo_info_for_path(mapped_value)
    except Exception as exc:
        return None, (
            "could not inspect the mapped project checkout before starting: "
            f"{exc}"
        )
    if info is None and _path_within(mapped_path, workspace_root):
        try:
            recovered = subprocess.run(
                [
                    "git",
                    "-C",
                    str(mapped_path),
                    "rev-parse",
                    "--path-format=absolute",
                    "--show-toplevel",
                    "--git-common-dir",
                ],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=10,
                check=False,
            )
            lines = str(recovered.stdout or "").splitlines()
            if recovered.returncode == 0 and len(lines) == 2:
                managed_root, common_dir = map(Path, lines)
                if common_dir.name == ".git":
                    info = _repo_info_for_path(common_dir.parent)
                    relative_cwd = mapped_path.relative_to(managed_root)
        except Exception:
            info = None
            relative_cwd = None
    if info is None:
        return None, None

    if relative_cwd is None:
        try:
            relative_cwd = mapped_path.relative_to(info.repo_root)
        except Exception:
            return None, (
                "the mapped Discord project path is not inside its protected canonical "
                f"repository: {mapped_value}"
            )

    if provision:
        try:
            workspace_root.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            return None, (
                f"could not prepare the mutable action-worktree root {workspace_root}: {exc}"
            )

    def _git(args: list[str], *, timeout: float = 30.0) -> subprocess.CompletedProcess:
        return subprocess.run(
            ["git", *args],
            cwd=str(info.repo_root),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            check=False,
        )

    try:
        inventory = _git(["worktree", "list", "--porcelain"], timeout=10.0)
    except Exception as exc:
        return None, f"Git could not list existing worktrees for {info.repo_root}: {exc}"
    if inventory.returncode != 0:
        detail = " ".join((inventory.stderr or inventory.stdout or "").split())[:600]
        return None, (
            f"Git could not list existing worktrees for {info.repo_root}"
            + (f": {detail}" if detail else ".")
        )

    try:
        generation = max(1, int(pr_generation))
    except (TypeError, ValueError, OverflowError):
        generation = 1
    base_branch, base_path = _discord_action_worktree_target(
        info.repo_root,
        source,
        session_key,
        generation,
    )

    base_start_point = "HEAD"
    base_resolved = False

    def _resolve_fresh_base() -> tuple[Optional[str], Optional[str]]:
        nonlocal base_resolved, base_start_point
        if base_resolved:
            return base_start_point, None
        base_resolved = True
        branch_result = _git(
            ["symbolic-ref", "--quiet", "--short", "HEAD"],
            timeout=10.0,
        )
        base_name = str(branch_result.stdout or "").strip()
        if branch_result.returncode != 0 or not base_name:
            if generation <= 1:
                return base_start_point, None
            return None, (
                "the protected canonical checkout has no branch to refresh for "
                f"Discord PR generation {generation}"
            )

        upstream_result = _git(
            ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"],
            timeout=10.0,
        )
        upstream = str(upstream_result.stdout or "").strip()
        remote, separator, remote_branch = upstream.partition("/")
        if upstream_result.returncode != 0 or not separator:
            remote, remote_branch = "origin", base_name
        remote_ref = f"refs/remotes/{remote}/{remote_branch}"
        fetched = _git(
            [
                "fetch",
                "--no-tags",
                remote,
                f"refs/heads/{remote_branch}:{remote_ref}",
            ],
            timeout=120.0,
        )
        verified = _git(
            ["rev-parse", "--verify", f"{remote_ref}^{{commit}}"],
            timeout=10.0,
        )
        if verified.returncode == 0:
            base_start_point = remote_ref
            if fetched.returncode != 0:
                logger.warning(
                    "Discord action worktree base refresh failed; using cached %s",
                    remote_ref,
                )
            return base_start_point, None
        if generation <= 1:
            logger.warning(
                "Discord action worktree base refresh unavailable; using canonical HEAD"
            )
            return base_start_point, None
        detail = " ".join((fetched.stderr or fetched.stdout or "").split())[:600]
        return None, (
            "Git could not refresh the merged base before starting the next PR"
            + (f": {detail}" if detail else ".")
        )

    def _resolved_record_path(record: dict[str, str]) -> Optional[Path]:
        raw = str(record.get("path") or "").strip()
        if not raw:
            return None
        try:
            return Path(raw).expanduser().resolve(strict=False)
        except Exception:
            return Path(raw).expanduser()

    def _reuse_cwd(worktree_path: Path) -> tuple[Optional[str], Optional[str]]:
        target_cwd = (worktree_path / relative_cwd).resolve(strict=False)
        if not target_cwd.is_dir():
            return None, (
                "the action worktree exists, but the mapped project subdirectory "
                f"is unavailable there: {target_cwd}"
            )
        return str(target_cwd), None

    records = _discord_action_worktree_records(inventory.stdout)
    for attempt in range(32):
        suffix = "" if attempt == 0 else f"-{attempt + 1}"
        branch = f"{base_branch}{suffix}"
        target_path = Path(f"{base_path}{suffix}")

        branch_record = next(
            (record for record in records if record.get("branch") == branch),
            None,
        )
        if branch_record is not None:
            existing_path = _resolved_record_path(branch_record)
            if (
                existing_path is not None
                and _path_within(existing_path, workspace_root)
                and existing_path.is_dir()
            ):
                return _reuse_cwd(existing_path)
            # The deterministic branch is attached elsewhere (or stale). Do
            # not hijack it; advance both branch and path together.
            continue

        path_record = next(
            (
                record
                for record in records
                if _resolved_record_path(record) == target_path.resolve(strict=False)
            ),
            None,
        )
        if path_record is not None or target_path.exists():
            continue

        if not provision:
            continue

        try:
            branch_exists = _git(
                ["show-ref", "--verify", "--quiet", f"refs/heads/{branch}"],
                timeout=10.0,
            ).returncode == 0
            if branch_exists:
                add_args = ["worktree", "add", str(target_path), branch]
            else:
                start_point, refresh_error = _resolve_fresh_base()
                if refresh_error:
                    return None, refresh_error
                add_args = [
                    "worktree",
                    "add",
                    "-b",
                    branch,
                    str(target_path),
                    str(start_point or "HEAD"),
                ]
            created = _git(add_args)
        except Exception as exc:
            return None, (
                f"Git could not create mutable action worktree {target_path}: {exc}"
            )
        if created.returncode == 0:
            try:
                from hermes_cli.worktree_runtime import prepare_worktree_dependency_links

                for note in prepare_worktree_dependency_links(target_path, config):
                    logger.info(
                        "Discord action worktree provisioning for %s: %s",
                        target_path,
                        note,
                    )
            except Exception as exc:
                logger.debug(
                    "Discord action worktree dependency reuse skipped for %s: %s",
                    target_path,
                    exc,
                )
            _discord_action_worktree_warmup(target_path, config)
            return _reuse_cwd(target_path)

        # A concurrent first message for the same thread may have won the
        # branch/path race. Refresh once and reuse it when present.
        try:
            refreshed = _git(["worktree", "list", "--porcelain"], timeout=10.0)
        except Exception:
            refreshed = None
        if refreshed is not None and refreshed.returncode == 0:
            records = _discord_action_worktree_records(refreshed.stdout)
            concurrent_record = next(
                (record for record in records if record.get("branch") == branch),
                None,
            )
            if concurrent_record is not None:
                concurrent_path = _resolved_record_path(concurrent_record)
                if (
                    concurrent_path is not None
                    and _path_within(concurrent_path, workspace_root)
                    and concurrent_path.is_dir()
                ):
                    return _reuse_cwd(concurrent_path)

        detail = " ".join((created.stderr or created.stdout or "").split())[:600]
        collision_markers = (
            "already exists",
            "already checked out",
            "is a missing but already registered worktree",
        )
        if any(marker in detail.lower() for marker in collision_markers):
            continue
        return None, (
            f"Git could not create mutable action worktree {target_path}"
            + (f": {detail}" if detail else ".")
        )

    if not provision:
        return None, None
    return None, (
        "could not allocate a collision-free Discord action worktree under "
        f"{workspace_root} after 32 attempts"
    )


def _resolve_gateway_turn_cwd(
    source: Any,
    feature_summary: Optional[Dict[str, Any]],
    config: Optional[dict],
    session_key: str,
    runtime_mode: Any = RuntimeMode.ACTION,
    pr_generation: int = 1,
) -> tuple[str, Optional[str], Optional[str]]:
    """Resolve a turn CWD, provisioning only for explicit ACTION authority."""
    fallback = _resolve_gateway_session_cwd(source, config)
    mode = _discord_runtime_mode_for(
        runtime_mode,
        default=RuntimeMode.ACTION,
    )
    worktree_cwd, error = _discord_action_worktree_cwd(
        source,
        feature_summary,
        session_key,
        config,
        provision=mode is RuntimeMode.ACTION,
        pr_generation=pr_generation,
    )
    if mode is RuntimeMode.READ_ONLY and error:
        logger.debug(
            "Read-only Discord turn could not reuse an existing action worktree; "
            "falling back to the mapped session cwd: %s",
            error,
        )
        return fallback, None, None
    return worktree_cwd or fallback, error, worktree_cwd


def _load_gateway_runtime_config() -> dict:
    """Load gateway config for runtime reads, expanding supported ``${VAR}`` refs.

    Runtime helpers should honor the same env-template expansion documented for
    ``config.yaml`` while still respecting tests that monkeypatch
    ``gateway.run._hermes_home``. Build on ``_load_gateway_config()`` rather
    than calling the canonical loader directly so both behaviors stay aligned.

    Expansion failures are intentionally NOT swallowed — silently returning
    the unexpanded dict would mask the very bug this helper exists to fix.
    """
    cfg = _load_gateway_config()
    if not isinstance(cfg, dict) or not cfg:
        return {}
    from hermes_cli.config import _expand_env_vars

    expanded = _expand_env_vars(cfg)
    return expanded if isinstance(expanded, dict) else {}


def _closeout_mapping(value: Any) -> dict[str, Any]:
    """Normalize untrusted raw closeout YAML sections to an owned mapping."""

    return dict(value) if isinstance(value, dict) else {}


def _closeout_repository_config(closeout_config: Any, repository: str) -> dict[str, Any]:
    closeout = _closeout_mapping(closeout_config)
    repositories = _closeout_mapping(closeout.get("repositories"))
    return _closeout_mapping(repositories.get(repository))


def _effective_closeout_repository_config(
    closeout_config: Any,
    repository: str,
) -> dict[str, Any]:
    """Overlay one repository's generic closeout policy onto global defaults."""

    closeout = _closeout_mapping(closeout_config)
    repository_config = _closeout_repository_config(closeout, repository)
    effective = {
        key: value
        for key, value in closeout.items()
        if key != "repositories"
    }
    for key, value in repository_config.items():
        if key in {"surfaces", "preview", "visual_qa"}:
            effective[key] = {
                **_closeout_mapping(effective.get(key)),
                **_closeout_mapping(value),
            }
        else:
            effective[key] = value
    return effective


def _gateway_repository_for_source(
    source: Any,
    *,
    workspace_path: str = "",
) -> str:
    """Resolve the actual target checkout's normalized GitHub identity.

    Discord mapping metadata is a fallback. Once a mutable action workspace is
    resolved, its origin is authoritative for repository-scoped closeout policy.
    """

    try:
        from hermes_cli.github_remote import (
            github_origin_repo,
            github_repo_from_value,
        )

        configured = github_repo_from_value(
            getattr(source, "project_github_url", "")
        )
        target_path = str(workspace_path or "").strip()
        if not target_path:
            target_path = str(getattr(source, "project_path", "") or "").strip()
        actual = github_origin_repo(target_path) if target_path else ""
        if actual:
            if configured and str(configured).lower() != str(actual).lower():
                logger.warning(
                    "Discord repository mapping mismatch; using target workspace origin "
                    "for closeout policy (configured=%s actual=%s workspace=%s)",
                    str(configured)[:160],
                    str(actual)[:160],
                    target_path[:240],
                )
            return str(actual)
        return str(configured or "")
    except Exception:
        return ""


def _repository_visual_qa_config(
    config: Any,
    repository: str,
) -> dict[str, Any]:
    """Return global visual limits with an optional repository mode override."""

    root = _closeout_mapping(config)
    agent_config = _closeout_mapping(root.get("agent"))
    visual_config = _closeout_mapping(agent_config.get("visual_qa"))
    closeout_config = _effective_closeout_repository_config(
        root.get("closeout"),
        repository,
    )
    return {
        **visual_config,
        **_closeout_mapping(closeout_config.get("visual_qa")),
    }


def _gateway_action_request_text(event: Any) -> str:
    """Return the original action request used for shared closeout policy."""

    feature_summary = getattr(event, "feature_summary", None)
    return (
        str(feature_summary.get("initial_request") or "").strip()
        if isinstance(feature_summary, dict)
        else ""
    ) or str(getattr(event, "text", "") or "").strip()


def _gateway_action_closeout_contract(
    config: dict[str, Any],
    *,
    repository: str,
    request: str,
    source: str = "direct",
    visual_requirement: Any = None,
    visual_config: Any = None,
) -> tuple[str, dict[str, Any]]:
    """Resolve the one trusted closeout contract for Discord action turns."""

    closeout_config = _effective_closeout_repository_config(
        config.get("closeout"),
        repository,
    )
    surfaces = _closeout_mapping(closeout_config.get("surfaces"))
    normalized_source = str(source or "direct").strip().lower()
    surface_enabled = surfaces.get("direct") is not False
    legacy_fable_lifecycle = ""
    if normalized_source in {"fable", "opus"}:
        surface_enabled = surface_enabled and surfaces.get(normalized_source) is not False
    if normalized_source == "fable":
        # Bounded migration compatibility for pre-unification installations.
        # New configs omit both legacy keys and use the ordinary direct policy.
        # Explicit old opt-outs remain authoritative and cannot silently gain
        # PR/merge authority after upgrade.
        fable_config = _closeout_mapping(config.get("fable"))
        if "git_lifecycle" in fable_config:
            legacy_fable_lifecycle = str(
                fable_config.get("git_lifecycle") or "none"
            ).strip().lower()
            if legacy_fable_lifecycle not in {"pr", "merge"}:
                surface_enabled = False
    mode = (
        str(closeout_config.get("mode") or "shadow").strip().lower()
        if surface_enabled
        else "off"
    )
    from hermes_cli.discord_worker_boards import pr_policy_for_request

    pr_lifecycle_policy = pr_policy_for_request(str(request or ""))
    preview_config = _closeout_mapping(closeout_config.get("preview"))
    require_preview = (
        preview_config.get("required") is not False
        and mode == "enforce"
        and pr_lifecycle_policy["pr_open_policy"] != "never"
    )
    policy = {
        "merge": "never",
        "pr_open": pr_lifecycle_policy["pr_open_policy"],
        "early_draft_pr": (
            closeout_config.get("early_draft_pr") is True or require_preview
        ),
        "require_preview": require_preview,
        "require_local_verification": True,
        "require_review": False,
        "require_visual_qa": bool(
            isinstance(visual_requirement, dict)
            and visual_requirement.get("level") in {"surface", "artifact"}
            and isinstance(visual_config, dict)
            and visual_config.get("mode") == "enforce_explicit"
        ),
    }
    if normalized_source == "fable" and legacy_fable_lifecycle in {"pr", "merge"}:
        policy.update(
            {
                "merge": "never",
                "pr_open": "after_review_approval",
                "early_draft_pr": True,
            }
        )
    return mode, policy


def _resolve_gateway_model(config: dict | None = None) -> str:
    """Read model from config.yaml — single source of truth.

    Without this, temporary AIAgent instances (e.g. /compress) fall
    back to the hardcoded default which fails when the active provider is
    openai-codex.
    """
    cfg = config if config is not None else _load_gateway_config()
    model_tier = _gateway_model_tier(cfg)
    if model_tier is not None:
        return model_tier.model
    model_cfg = cfg.get("model", {})
    if isinstance(model_cfg, str):
        return model_cfg
    elif isinstance(model_cfg, dict):
        return model_cfg.get("default") or model_cfg.get("model") or ""
    return ""


def _resolve_hermes_bin() -> Optional[list[str]]:
    """Resolve the Hermes update command as argv parts.

    Tries in order:
    1. ``shutil.which("hermes")`` — standard PATH lookup
    2. ``sys.executable -m hermes_cli.main`` — fallback when Hermes is running
       from a venv/module invocation and the ``hermes`` shim is not on PATH

    Returns argv parts ready for quoting/joining, or ``None`` if neither works.
    """
    import shutil

    hermes_bin = shutil.which("hermes")
    if hermes_bin:
        return [hermes_bin]

    try:
        import importlib.util

        if importlib.util.find_spec("hermes_cli") is not None:
            return [sys.executable, "-m", "hermes_cli.main"]
    except Exception:
        pass

    return None


def _parse_session_key(session_key: str) -> "dict | None":
    """Parse a session key into its component parts.

    Session keys follow the format
    ``agent:main:{platform}:{chat_type}:{chat_id}[:{extra}...]``.
    Returns a dict with ``platform``, ``chat_type``, ``chat_id``, and
    optionally ``thread_id`` keys, or None if the key doesn't match.

    The 6th element is only returned as ``thread_id`` for chat types where
    it is unambiguous (``dm`` and ``thread``).  For group/channel sessions
    the suffix may be a user_id (per-user isolation) rather than a
    thread_id, so we leave ``thread_id`` out to avoid mis-routing.
    """
    parts = session_key.split(":")
    if len(parts) >= 5 and parts[0] == "agent" and parts[1] == "main":
        result = {
            "platform": parts[2],
            "chat_type": parts[3],
            "chat_id": parts[4],
        }
        if len(parts) > 5 and parts[3] in {"dm", "thread"}:
            result["thread_id"] = parts[5]
        return result
    return None


def _format_gateway_process_notification(evt: dict) -> "str | None":
    """Format a watch pattern event from completion_queue into a [IMPORTANT:] message."""
    evt_type = evt.get("type", "completion")
    _sid = evt.get("session_id", "unknown")
    _cmd = evt.get("command", "unknown")

    if evt_type == "watch_disabled":
        return f"[IMPORTANT: {evt.get('message', '')}]"

    if evt_type == "watch_match":
        _pat = evt.get("pattern", "?")
        _out = evt.get("output", "")
        _sup = evt.get("suppressed", 0)
        text = (
            f"[IMPORTANT: Background process {_sid} matched "
            f"watch pattern \"{_pat}\".\n"
            f"Command: {_cmd}\n"
            f"Matched output:\n{_out}"
        )
        if _sup:
            text += f"\n({_sup} earlier matches were suppressed by rate limit)"
        text += "]"
        return text

    if evt_type == "async_delegation":
        delegation_id = str(evt.get("delegation_id") or "unknown")
        if evt.get("kind") == "coding_worker":
            result = evt.get("result") if isinstance(evt.get("result"), dict) else {}
            context_pack = (
                evt.get("context_pack")
                if isinstance(evt.get("context_pack"), dict)
                else {}
            )
            return "\n".join(
                [
                    f"[ASYNC CODING WORKER COMPLETE — {delegation_id}]",
                    "Trusted Hermes completion-time post-processing has already run. "
                    "Review the deterministic evidence below, verify scope_check and "
                    "parallel_merge when present, then report the outcome to the user. "
                    "Do not attribute trusted Git lifecycle actions to the coding worker.",
                    "",
                    f"Original task: {evt.get('task') or evt.get('goal') or ''}",
                    f"Worker cwd: {evt.get('worker_cwd') or ''}",
                    f"Model tier: {evt.get('model_tier') or 'default'}",
                    "Scope paths: " + json.dumps(evt.get("scope_paths") or []),
                    "Original context pack:",
                    json.dumps(context_pack, ensure_ascii=False, indent=2),
                    "--- DETERMINISTIC RESULT JSON ---",
                    json.dumps(result, ensure_ascii=False, indent=2),
                ]
            )

        from tools.process_registry import format_process_notification

        return format_process_notification(evt)

    return None


def _drain_gateway_watch_events(completion_queue) -> "list[dict]":
    """Drain watch events while leaving async completions for their watcher."""
    watch_events: list[dict] = []
    requeue: list[dict] = []
    while not completion_queue.empty():
        try:
            evt = completion_queue.get_nowait()
        except Exception:
            break
        evt_type = evt.get("type", "completion")
        if evt_type in {"watch_match", "watch_disabled"}:
            watch_events.append(evt)
        elif evt_type == "async_delegation":
            requeue.append(evt)
    for evt in requeue:
        completion_queue.put(evt)
    return watch_events


# Module-level weak reference to the active GatewayRunner instance.
# Used by tools (e.g. send_message) that need to route through a live
# adapter for plugin platforms.  Set in GatewayRunner.__init__().
import weakref as _weakref
_gateway_runner_ref: _weakref.ref = lambda: None


def _normalize_empty_agent_response(
    agent_result: dict,
    response: str,
    *,
    history_len: int = 0,
) -> str:
    """Normalize empty/None agent responses into user-facing messages.

    Consolidates the existing ``failed`` handler and adds a catch-all for
    the case where the agent did work (api_calls > 0) but returned no text.
    Fix for #18765.
    """
    if response:
        return response

    if agent_result.get("failed"):
        error_detail = agent_result.get("error", "unknown error")
        is_context_failure = _is_context_overflow_failure(agent_result)
        if is_context_failure:
            return (
                "⚠️ Session too large for the model's context window.\n"
                "Use /compact to compress the conversation, or "
                "/reset to start fresh."
            )
        return (
            f"The request failed: {str(error_detail)[:300]}\n"
            "Try again or use /reset to start a fresh session."
        )

    api_calls = int(agent_result.get("api_calls", 0) or 0)
    if agent_result.get("interrupted"):
        if api_calls == 0:
            return (
                "⚠️ Your message was interrupted before processing started "
                "(likely by a recent /stop). Please send it again."
            )
        return response

    if api_calls > 0:
        if _is_gateway_hidden_reasoning_incomplete_turn(agent_result):
            return ""
        if agent_result.get("partial"):
            err = agent_result.get("error", "processing incomplete")
            return f"⚠️ Processing stopped: {str(err)[:200]}. Try again."
        return (
            "⚠️ Processing completed but no response was generated. "
            "This may be a transient error — try sending your message again."
        )

    if not agent_result.get("interrupted") and history_len > 0:
        return (
            "⚠️ No response was generated before the turn started. "
            "This usually means the previous /stop or restart invalidated the "
            "session state; send it again or use /reset if it repeats."
        )

    return response


def _is_context_overflow_failure(agent_result: dict) -> bool:
    """Return whether a failed turn has explicit context-overflow evidence."""
    if not agent_result.get("failed"):
        return False
    error_text = str(agent_result.get("error", "")).lower()
    return bool(agent_result.get("compression_exhausted")) or any(
        phrase in error_text
        for phrase in (
            "context length",
            "context size",
            "context window",
            "maximum context",
            "token limit",
            "too many tokens",
            "reduce the length",
            "exceeds the limit",
            "request entity too large",
            "prompt is too long",
            "payload too large",
            "input is too long",
        )
    )


def _is_gateway_hidden_reasoning_incomplete_turn(agent_result: dict) -> bool:
    if not isinstance(agent_result, dict):
        return False
    if agent_result.get("failed") or agent_result.get("interrupted"):
        return False
    if not agent_result.get("partial"):
        return False
    error_text = str(agent_result.get("error", "") or "").strip()
    if "remained incomplete after" not in error_text.lower():
        return False
    final_response = str(agent_result.get("final_response") or "").strip()
    return not final_response or final_response == error_text


def _should_clear_resume_pending_after_turn(agent_result: dict) -> bool:
    """Return True only when a gateway turn really completed successfully.

    Restart recovery uses ``resume_pending`` as a durable marker for sessions
    interrupted during gateway drain.  A soft interrupt can still bubble out as
    a syntactically normal agent result with an empty final response; clearing
    the marker in that case loses the recovery signal and startup auto-resume
    has nothing to schedule.
    """
    if not isinstance(agent_result, dict):
        return False
    if agent_result.get("interrupted"):
        return False
    if agent_result.get("failed") or agent_result.get("partial") or agent_result.get("error"):
        return False
    if agent_result.get("completed") is False:
        return False
    return True


def _is_startup_resume_event(event: Any) -> bool:
    """Return whether ``event`` is the synthetic restart-recovery turn."""

    if event is None or not getattr(event, "internal", False):
        return False
    metadata = getattr(event, "metadata", None)
    return bool(
        isinstance(metadata, dict)
        and metadata.get(_STARTUP_RESUME_EVENT_METADATA_KEY) is True
    )


def _redundant_startup_resume_after_success(
    event: Any,
    agent_result: dict,
) -> bool:
    """Drop a queued restart replay when the supposedly interrupted turn won.

    A planned gateway restart can time out while an executor-backed model turn
    keeps running. The new startup recovery event then lands in the adapter's
    pending slot. If the original turn subsequently completes successfully,
    replaying the synthetic recovery note creates a second provider call and a
    second user-visible result even though no work remains to recover.
    """

    return _is_startup_resume_event(event) and _should_clear_resume_pending_after_turn(
        agent_result
    )


def _preserve_queued_followup_history_offset(
    current_result: dict,
    followup_result: dict,
) -> dict:
    """Carry the outer history offset through queued follow-up drains.

    ``_process_message_background()`` persists transcript rows only once, after the
    entire in-band queued-follow-up chain returns.  Each recursive ``_run_agent()``
    call advances ``history_offset`` to the history it received, so without
    correction the outermost persistence step sees only the *last* queued turn as
    "new" and silently drops earlier turns from the same drain chain.

    Preserve the earliest (outermost) history offset so the final transcript slice
    still includes every queued turn that ran during the chain.
    """
    if not isinstance(followup_result, dict):
        return followup_result
    if not isinstance(current_result, dict):
        return followup_result

    current_offset = current_result.get("history_offset")
    followup_offset = followup_result.get("history_offset")
    if not isinstance(current_offset, int):
        return followup_result
    if isinstance(followup_offset, int) and followup_offset <= current_offset:
        return followup_result

    merged = dict(followup_result)
    merged["history_offset"] = current_offset
    return merged


_RECONNECT_BACKOFF_CAP = 300


def _reconnect_backoff(attempt: int) -> int:
    return min(30 * (2 ** (attempt - 1)), _RECONNECT_BACKOFF_CAP)


class _GatewayRunnerCore(
    GatewayAuthorizationMixin,
    GatewaySlashCommandsMixin,
):
    _external_drain_active: bool = False
    _detached_restart_helper_started: bool = False
    _restart_command_source: Optional[SessionSource] = None
    _restart_task: Optional[asyncio.Task] = None
    _profile_failed_platforms: Optional[
        Dict[str, Dict[Platform, asyncio.Task]]
    ] = None
    _systemd_watchdog: Optional[Any] = None
    _pending_one_turn_model_restores: Dict[str, Dict[str, Any]] = {}
    _session_service_tier_overrides: Dict[str, Optional[str]] = {}
    _pending_turn_sidecar_notes: Dict[str, List[str]] = {}
    _pending_start_user_followups: Dict[str, Dict[int, List[str]]] = {}
    _session_ephemeral_pin: Dict[str, tuple] = {}
    _session_vc_last: Dict[str, str] = {}
    _startup_restore_in_progress: bool = False
    _loop_heartbeat_task: Optional["asyncio.Task"] = None
    _gateway_started_at: float = 0.0
    _shutdown_watchdog_done: Optional["threading.Event"] = None
    _BUSY_QUEUE_MAX_PENDING = 32
    _CLEANUP_TIMEOUT_S = 30.0
    _MAX_SUPERVISED_RESTARTS = 5
    _SUPERVISED_HEALTHY_SECS = 300
    """
    Main gateway controller.

    Manages the lifecycle of all platform adapters and routes
    messages to/from the agent.
    """

    # Class-level defaults so partial construction in tests doesn't
    # blow up on attribute access.
    _running_agents_ts: Dict[str, float] = {}
    _running_discord_pr_generations: Dict[str, int] = {}
    _running_discord_runtime_modes: Dict[str, str] = {}
    _busy_input_mode: str = "steer"
    _busy_text_mode: str = "steer"
    _restart_drain_timeout: float = DEFAULT_GATEWAY_RESTART_DRAIN_TIMEOUT
    _shutdown_delivery_grace_seconds: float = _SHUTDOWN_DELIVERY_GRACE_SECS_DEFAULT
    _exit_code: Optional[int] = None
    _draining: bool = False
    _restart_requested: bool = False
    _restart_task_started: bool = False
    _restart_detached: bool = False
    _restart_via_service: bool = False
    _stop_task: Optional[asyncio.Task] = None
    _session_model_overrides: Dict[str, Dict[str, str]] = {}
    _session_reasoning_overrides: Dict[str, Dict[str, Any]] = {}

    def __init__(self, config: Optional[GatewayConfig] = None):
        global _gateway_runner_ref
        self.config = config or load_gateway_config()
        # In multiplex mode this process serves multiple profile homes. Flip
        # secret resolution into fail-closed mode so any unscoped credential
        # read is caught instead of falling back to another profile's env.
        try:
            from agent.secret_scope import set_multiplex_active
            set_multiplex_active(bool(getattr(self.config, "multiplex_profiles", False)))
        except Exception:
            logger.debug("could not set multiplex-active flag", exc_info=True)
        self.adapters: Dict[Platform, BasePlatformAdapter] = {}
        # Secondary-profile adapters, keyed by profile then platform. The
        # primary profile remains in self.adapters to preserve legacy paths.
        self._profile_adapters: Dict[str, Dict[Platform, BasePlatformAdapter]] = {}
        self._warn_if_docker_media_delivery_is_risky()
        _gateway_runner_ref = _weakref.ref(self)

        # Load ephemeral config from config.yaml / env vars.
        # Both are injected at API-call time only and never persisted.
        self._prefill_messages = self._load_prefill_messages()
        self._ephemeral_system_prompt = self._load_ephemeral_system_prompt()
        self._reasoning_config = self._load_reasoning_config()
        self._service_tier = self._load_service_tier()
        self._show_reasoning = self._load_show_reasoning()
        self._busy_input_mode = self._load_busy_input_mode()
        self._busy_text_mode = self._load_busy_text_mode()
        self._restart_drain_timeout = self._load_restart_drain_timeout()
        self._provider_routing = self._load_provider_routing()
        self._fallback_model = self._load_fallback_model()

        # Wire process registry into session store for reset protection
        from tools.process_registry import process_registry
        self.session_store = SessionStore(
            self.config.sessions_dir, self.config,
            has_active_processes_fn=lambda key: process_registry.has_active_for_session(key),
        )
        # Async gateway handlers must keep synchronous SessionStore I/O off the
        # event loop. Sync-only helpers continue to use ``session_store``.
        self._async_session_store = AsyncSessionStore(self.session_store)
        from gateway.work_ledger import GatewayWorkLedger
        from gateway.trusted_closeout_watcher import TrustedCloseoutWatcher

        self.work_ledger = GatewayWorkLedger()
        closeout_config = _load_gateway_config().get("closeout")
        self.trusted_closeout_watcher = TrustedCloseoutWatcher(
            self.work_ledger,
            config=closeout_config if isinstance(closeout_config, dict) else {},
            is_agent_active=self._work_item_agent_run_active,
            on_preview=self._on_trusted_closeout_preview,
            on_terminal=self._on_trusted_closeout_terminal,
        )
        self.delivery_router = DeliveryRouter(self.config)
        self._process_epoch = _GATEWAY_PROCESS_EPOCH
        self._running = False
        self._gateway_loop: Optional[asyncio.AbstractEventLoop] = None
        self._shutdown_event = asyncio.Event()
        self._kanban_dispatch_dirty_event = asyncio.Event()
        self._kanban_dispatch_dirty_marker_ns = 0
        self._kanban_foreman_dirty_marker_ns = 0
        self._exit_cleanly = False
        self._exit_with_failure = False
        self._exit_reason: Optional[str] = None
        self._exit_code: Optional[int] = None
        self._draining = False
        self._restart_requested = False
        self._restart_task_started = False
        self._restart_detached = False
        self._restart_via_service = False
        self._startup_time: float = time.time()
        self._booted_from_restart: bool = False
        self._stop_task: Optional[asyncio.Task] = None

        # Track running agents per session for interrupt support
        # Key: session_key, Value: AIAgent instance
        self._running_agents: Dict[str, Any] = {}
        self._running_agents_ts: Dict[str, float] = {}  # start timestamp per session
        self._running_discord_pr_generations: Dict[str, int] = {}
        self._running_discord_runtime_modes: Dict[str, str] = {}
        self._active_session_leases: Dict[str, Any] = {}
        self._turn_leases = SessionTurnLeaseRegistry()
        self._turn_lease_tokens: Dict[tuple, Any] = {}
        self._pending_start_user_followups: Dict[str, Dict[int, List[str]]] = {}
        self._pending_start_user_followups_lock = threading.Lock()
        self._pending_messages: Dict[str, str] = {}  # Queued messages during interrupt
        # Last successfully-resolved (non-empty) model, keyed by session. Used
        # as a fallback when a fresh config read transiently returns an empty
        # model (e.g. an mtime-keyed config-cache miss during a post-interrupt
        # recovery turn). Without this, the agent is built with model="" and
        # every API call fails HTTP 400 "No models provided" — the session goes
        # silent until the user manually re-sends. See #35314. ``"*"`` holds a
        # process-wide last-known-good for sessions seen for the first time.
        self._last_resolved_model: Dict[str, str] = {}
        # Overflow buffer for explicit /queue commands.  The adapter-level
        # _pending_messages dict is a single slot per session (designed for
        # "next-turn" follow-ups where repeated sends collapse into one
        # event).  /queue has different semantics: each invocation must
        # produce its own full agent turn, in FIFO order, with no merging.
        # When the slot is occupied, additional /queue items land here and
        # are promoted one-at-a-time after each run's drain.  Cleared on
        # /new and /reset.  /model and other mid-session operations
        # preserve the queue.
        self._queued_events: Dict[str, List[MessageEvent]] = {}
        self._pending_native_image_paths_by_session: Dict[str, List[str]] = {}
        self._busy_ack_ts: Dict[str, float] = {}  # last busy-ack timestamp per session (debounce)
        self._session_run_generation: Dict[str, int] = {}
        # LRU cache of live SessionSources keyed by session_key. Used by
        # fallback routing paths (shutdown notifications, synthetic
        # background-process events) when the persisted origin is missing
        # and _parse_session_key can't recover thread_id. Capped so it
        # cannot grow unbounded over a long-running gateway lifetime.
        self._session_sources: "OrderedDict[str, SessionSource]" = OrderedDict()
        self._session_sources_max = 512
        self._async_completion_seen: set[str] = set()
        self._completion_delivery_lock = threading.Lock()
        self._completion_deliveries_inflight: set[tuple[str, str, object]] = set()
        self._completion_delivery_tasks: Dict[
            object, tuple[str, asyncio.Task]
        ] = {}
        self._completion_deliveries_delivered: "OrderedDict[tuple[str, str, object], None]" = OrderedDict()
        self._completion_delivery_retention = 2048

        # Cache AIAgent instances per session to preserve prompt caching.
        # Without this, a new AIAgent is created per message, rebuilding the
        # system prompt (including memory) every turn — breaking prefix cache
        # and costing ~10x more on providers with prompt caching (Anthropic).
        # Key: session_key, Value:
        #   (AIAgent, config_signature_str, message_count, session_id)
        # Legacy two-element entries omit both coherence fields, so they cannot
        # detect external transcript writes. Three-element entries retain the
        # count guard but lack the session snapshot needed to distinguish DB
        # rows. Both remain readable for in-process transition compatibility;
        # the live agent's session_id is the only available ownership signal.
        #
        # OrderedDict so _enforce_agent_cache_cap() can pop the least-recently-
        # used entry (move_to_end() on cache hits, popitem(last=False) for
        # eviction).  Hard cap via _AGENT_CACHE_MAX_SIZE, idle TTL enforced
        # from _session_expiry_watcher().
        import threading as _threading
        self._agent_cache: "OrderedDict[str, tuple]" = OrderedDict()
        self._agent_cache_lock = _threading.Lock()

        # Per-session model overrides from /model command.
        # Key: session_key, Value: dict with model/provider/api_key/base_url/api_mode
        self._session_model_overrides: Dict[str, Dict[str, str]] = {}
        # Per-session reasoning effort overrides from /reasoning.
        # Key: session_key, Value: parsed reasoning config dict.
        self._session_reasoning_overrides: Dict[str, Dict[str, Any]] = {}
        self._kanban_notifier_profile = self._active_profile_name()
        # Teams meeting pipeline runtime (bound later when msgraph_webhook adapter exists).
        self._teams_pipeline_runtime = None
        self._teams_pipeline_runtime_error: Optional[str] = None
        # Track pending exec approvals per session
        # Key: session_key, Value: {"command": str, "pattern_key": str, ...}
        self._pending_approvals: Dict[str, Dict[str, Any]] = {}

        # Track platforms that failed to connect for background reconnection.
        # Key: Platform enum, Value: {"config": platform_config, "attempts": int, "next_retry": float}
        self._failed_platforms: Dict[Platform, Dict[str, Any]] = {}

        # Track pending /update prompt responses per session.
        # Key: session_key, Value: True when a prompt is waiting for user input.
        self._update_prompt_pending: Dict[str, bool] = {}

        # Slash-confirm state lives in tools.slash_confirm (module-level),
        # so platform adapters can resolve callbacks without a backref to
        # this runner.  Keep a local counter for confirm_id generation so
        # IDs stay compact (button callback_data has a 64-byte cap on
        # some platforms).
        import itertools as _itertools
        self._slash_confirm_counter = _itertools.count(1)

        # Persistent Honcho managers keyed by gateway session key.
        # This preserves write_frequency="session" semantics across short-lived
        # per-message AIAgent instances.



        # Ensure tirith security scanner is available (downloads if needed)
        try:
            from tools.tirith_security import ensure_installed
            ensure_installed(log_failures=False)
        except Exception:
            pass  # Non-fatal — fail-open at scan time if unavailable

        # Startup heads-up (#30882): a gateway in manual approval mode with no
        # automated risk assessor (tirith disabled AND no auxiliary.approval
        # model) can only gate dangerous commands / execute_code scripts via
        # live in-chat approval. With approval routing fixed, those actions now
        # fail closed (block) rather than silently auto-running — surface that
        # so operators knowingly enable tirith or configure auxiliary.approval
        # for unattended gateways.
        try:
            from hermes_cli.config import load_config as _load_full_config
            _appr_cfg = _load_full_config()
            _appr_mode = str(
                cfg_get(_appr_cfg, "approvals", "mode", default="manual") or "manual"
            ).strip().lower()
            _tirith_on = bool(cfg_get(_appr_cfg, "security", "tirith_enabled", default=True))
            _aux_approval = cfg_get(_appr_cfg, "auxiliary", "approval", default=None)
            if _appr_mode == "manual" and not _tirith_on and not _aux_approval:
                logger.warning(
                    "Gateway approvals.mode=manual with no automated risk "
                    "assessor (security.tirith_enabled is false and "
                    "auxiliary.approval is unset): dangerous commands and "
                    "execute_code scripts will BLOCK until a human approves "
                    "them in chat. Enable security.tirith_enabled or configure "
                    "auxiliary.approval for unattended operation."
                )
        except Exception:
            logger.debug("approvals.mode startup check skipped", exc_info=True)

        # Initialize session database for session_search tool support
        self._session_db = None
        try:
            from hermes_state import AsyncSessionDB, SessionDB
            self._session_db = AsyncSessionDB(SessionDB())
        except Exception as e:
            # WARNING (not DEBUG) so the failure appears in errors.log — matches
            # cli.py's handling of the same init path.  Users hitting NFS-mounted
            # HERMES_HOME silently lost /resume, /title, /history, /branch, and
            # session search without this.  The underlying cause (usually
            # "locking protocol" from NFS) is now also captured by
            # hermes_state.get_last_init_error() for slash-command error strings.
            logger.warning("SQLite session store not available: %s", e)

        # Opportunistic state.db maintenance: prune ended sessions older
        # than sessions.retention_days + optional VACUUM. Tracks last-run
        # in state_meta so it only actually executes once per
        # sessions.min_interval_hours.  Gateway is long-lived so blocking
        # a few seconds once per day is acceptable; failures are logged
        # but never raised.
        if self._session_db is not None:
            try:
                from hermes_cli.config import load_config as _load_full_config
                _sess_cfg = (_load_full_config().get("sessions") or {})
                if _sess_cfg.get("auto_prune", False):
                    self._session_db._db.maybe_auto_prune_and_vacuum(
                        retention_days=int(_sess_cfg.get("retention_days", 90)),
                        min_interval_hours=int(_sess_cfg.get("min_interval_hours", 24)),
                        vacuum=bool(_sess_cfg.get("vacuum_after_prune", True)),
                        sessions_dir=self.config.sessions_dir,
                    )
            except Exception as exc:
                logger.debug("state.db auto-maintenance skipped: %s", exc)

        # Opportunistic shadow-repo cleanup — deletes orphan/stale
        # checkpoint repos under ~/.hermes/checkpoints/.  Opt-in via
        # checkpoints.auto_prune, idempotent via .last_prune marker.
        try:
            from hermes_cli.config import load_config as _load_full_config
            _ckpt_cfg = (_load_full_config().get("checkpoints") or {})
            if _ckpt_cfg.get("auto_prune", False):
                from tools.checkpoint_manager import maybe_auto_prune_checkpoints
                maybe_auto_prune_checkpoints(
                    retention_days=int(_ckpt_cfg.get("retention_days", 7)),
                    min_interval_hours=int(_ckpt_cfg.get("min_interval_hours", 24)),
                    delete_orphans=bool(_ckpt_cfg.get("delete_orphans", True)),
                    max_total_size_mb=int(_ckpt_cfg.get("max_total_size_mb", 500)),
                )
        except Exception as exc:
            logger.debug("checkpoint auto-maintenance skipped: %s", exc)

        # DM pairing store for code-based user authorization
        from gateway.pairing import PairingStore
        self.pairing_store = PairingStore()
        self.pairing_stores: Dict[str, "PairingStore"] = {}

        # Event hook system
        from gateway.hooks import HookRegistry
        self.hooks = HookRegistry()

        # Per-chat voice reply mode: "off" | "voice_only" | "all"
        self._voice_mode: Dict[str, str] = self._load_voice_modes()
        # Recent voice transcripts per (guild,user) for duplicate suppression.
        # Protects against the same utterance being emitted twice by the voice
        # capture / STT pipeline, which otherwise produces a second delayed reply.
        self._recent_voice_transcripts: Dict[tuple[int, int], List[tuple[float, str]]] = {}

        # Track background tasks to prevent garbage collection mid-execution
        self._background_tasks: set = set()
        # User-visible /background agents need stronger ownership than generic
        # infrastructure tasks: the outer asyncio task cannot stop its executor
        # thread, so retain the live AIAgent and an explicit cancellation fence.
        self._background_agent_lock = threading.Lock()
        self._background_agents: Dict[str, Dict[str, Any]] = {}
        # Long-lived gateway runners need both a strong reference and explicit
        # shutdown ownership.  A bare create_task() can otherwise be collected
        # while pending, which silently kills completion recovery.
        self._owned_runner_tasks: Dict[str, asyncio.Task] = {}
        self._required_async_item_tasks: Dict[str, asyncio.Task] = {}
        self._required_async_reconcile_event = asyncio.Event()
        self._terminal_delivery_retry_tasks: Dict[str, asyncio.Task] = {}


    def _wire_teams_pipeline_runtime(self) -> None:
        """Bind the Teams meeting pipeline runtime to Graph webhook ingress.

        No-op when the msgraph_webhook adapter isn't running or the
        teams_pipeline plugin isn't enabled — lets the gateway start cleanly
        whether or not the user has opted into the pipeline.
        """
        if Platform.MSGRAPH_WEBHOOK not in self.adapters:
            return
        if not _teams_pipeline_plugin_enabled():
            logger.debug("Teams pipeline plugin is disabled; skipping runtime wiring")
            return
        try:
            from plugins.teams_pipeline.runtime import bind_gateway_runtime
        except Exception as exc:
            logger.warning("Teams pipeline runtime import failed: %s", exc)
            return
        try:
            bound = bind_gateway_runtime(self)
        except Exception as exc:
            logger.warning("Teams pipeline runtime wiring failed: %s", exc)
            return
        if bound:
            logger.info("Teams pipeline runtime bound to msgraph webhook ingress")
        elif self._teams_pipeline_runtime_error:
            logger.warning(
                "Teams pipeline runtime unavailable: %s",
                self._teams_pipeline_runtime_error,
            )


    def _warn_if_docker_media_delivery_is_risky(self) -> None:
        """Warn when Docker-backed gateways lack an explicit export mount.

        MEDIA delivery happens in the gateway process, so paths emitted by the model
        must be readable from the host. A plain container-local path like
        `/workspace/report.txt` or `/output/report.txt` often exists only inside
        Docker, so users commonly need a dedicated export mount such as
        `host-dir:/output`.
        """
        if os.getenv("TERMINAL_ENV", "").strip().lower() != "docker":
            return

        connected = self.config.get_connected_platforms()
        messaging_platforms = [p for p in connected if p not in {Platform.LOCAL, Platform.API_SERVER, Platform.WEBHOOK}]
        if not messaging_platforms:
            return

        raw_volumes = os.getenv("TERMINAL_DOCKER_VOLUMES", "").strip()
        volumes: List[str] = []
        if raw_volumes:
            try:
                parsed = json.loads(raw_volumes)
                if isinstance(parsed, list):
                    volumes = [str(v) for v in parsed if isinstance(v, str)]
            except Exception:
                logger.debug("Could not parse TERMINAL_DOCKER_VOLUMES for gateway media warning", exc_info=True)

        has_explicit_output_mount = False
        for spec in volumes:
            match = _DOCKER_VOLUME_SPEC_RE.match(spec)
            if not match:
                continue
            container_path = match.group("container")
            if container_path in _DOCKER_MEDIA_OUTPUT_CONTAINER_PATHS:
                has_explicit_output_mount = True
                break

        if has_explicit_output_mount:
            return

        logger.warning(
            "Docker backend is enabled for the messaging gateway but no explicit host-visible "
            "output mount (for example '/home/user/.hermes/cache/documents:/output') is configured. "
            "This is fine if the model already emits host-visible paths, but MEDIA file delivery can fail "
            "for container-local paths like '/workspace/...' or '/output/...'."
        )



    # -- Setup skill availability ----------------------------------------

    def _has_setup_skill(self) -> bool:
        """Check if the hermes-agent-setup skill is installed."""
        try:
            from tools.skill_manager_tool import _find_skill
            return _find_skill("hermes-agent-setup") is not None
        except Exception:
            return False

    # -- Voice mode persistence ------------------------------------------

    _VOICE_MODE_PATH = _hermes_home / "gateway_voice_mode.json"

    def _voice_key(self, platform: Platform, chat_id: str) -> str:
        """Return a platform-namespaced key for voice mode state."""
        return f"{platform.value}:{chat_id}"

    def _load_voice_modes(self) -> Dict[str, str]:
        try:
            data = json.loads(self._VOICE_MODE_PATH.read_text())
        except (FileNotFoundError, json.JSONDecodeError, OSError):
            return {}

        if not isinstance(data, dict):
            return {}

        valid_modes = {"off", "voice_only", "all"}
        result = {}
        for chat_id, mode in data.items():
            if mode not in valid_modes:
                continue
            key = str(chat_id)
            # Skip legacy unprefixed keys (warn and skip)
            if ":" not in key:
                logger.warning(
                    "Skipping legacy unprefixed voice mode key %r during migration. "
                    "Re-enable voice mode on that chat to rebuild the prefixed key.",
                    key,
                )
                continue
            result[key] = mode
        return result

    def _save_voice_modes(self) -> None:
        try:
            self._VOICE_MODE_PATH.parent.mkdir(parents=True, exist_ok=True)
            self._VOICE_MODE_PATH.write_text(
                json.dumps(self._voice_mode, indent=2)
            )
        except OSError as e:
            logger.warning("Failed to save voice modes: %s", e)

    def _set_adapter_auto_tts_disabled(self, adapter, chat_id: str, disabled: bool) -> None:
        """Update an adapter's in-memory auto-TTS suppression set if present."""
        disabled_chats = getattr(adapter, "_auto_tts_disabled_chats", None)
        if not isinstance(disabled_chats, set):
            return
        if disabled:
            disabled_chats.add(chat_id)
            # ``/voice off`` also clears any explicit enable — it's a hard override.
            enabled_chats = getattr(adapter, "_auto_tts_enabled_chats", None)
            if isinstance(enabled_chats, set):
                enabled_chats.discard(chat_id)
        else:
            disabled_chats.discard(chat_id)

    def _set_adapter_auto_tts_enabled(self, adapter, chat_id: str, enabled: bool) -> None:
        """Update an adapter's per-chat auto-TTS opt-in set if present.

        Used for ``/voice on``/``/voice tts`` where the user explicitly wants
        auto-TTS even when ``voice.auto_tts`` is False globally.
        """
        enabled_chats = getattr(adapter, "_auto_tts_enabled_chats", None)
        if not isinstance(enabled_chats, set):
            return
        if enabled:
            enabled_chats.add(chat_id)
            # An explicit opt-in clears any stale /voice off for this chat.
            disabled_chats = getattr(adapter, "_auto_tts_disabled_chats", None)
            if isinstance(disabled_chats, set):
                disabled_chats.discard(chat_id)
        else:
            enabled_chats.discard(chat_id)

    def _sync_voice_mode_state_to_adapter(self, adapter) -> None:
        """Restore persisted /voice state into a live platform adapter.

        Populates three fields from config + ``self._voice_mode``:
          - ``_auto_tts_default``: global default from ``voice.auto_tts``
          - ``_auto_tts_enabled_chats``: chats with mode ``voice_only``/``all``
          - ``_auto_tts_disabled_chats``: chats with mode ``off``
        """
        platform = getattr(adapter, "platform", None)
        if not isinstance(platform, Platform):
            return

        disabled_chats = getattr(adapter, "_auto_tts_disabled_chats", None)
        enabled_chats = getattr(adapter, "_auto_tts_enabled_chats", None)
        if not isinstance(disabled_chats, set) and not isinstance(enabled_chats, set):
            return

        # Push the global voice.auto_tts default (config.yaml) onto the adapter.
        # Lazy import to avoid adding a module-level dep from gateway → hermes_cli.
        try:
            from hermes_cli.config import load_config as _load_full_config
            _full_cfg = _load_full_config()
            _auto_tts_default = bool(
                (_full_cfg.get("voice") or {}).get("auto_tts", False)
            )
        except Exception:
            _auto_tts_default = False
        if hasattr(adapter, "_auto_tts_default"):
            adapter._auto_tts_default = _auto_tts_default

        prefix = f"{platform.value}:"
        if isinstance(disabled_chats, set):
            disabled_chats.clear()
            disabled_chats.update(
                key[len(prefix):] for key, mode in self._voice_mode.items()
                if mode == "off" and key.startswith(prefix)
            )
        if isinstance(enabled_chats, set):
            enabled_chats.clear()
            enabled_chats.update(
                key[len(prefix):] for key, mode in self._voice_mode.items()
                if mode in {"voice_only", "all"} and key.startswith(prefix)
            )

    async def _safe_adapter_disconnect(self, adapter, platform) -> None:
        """Call adapter.disconnect() defensively, swallowing any error.

        Used when adapter.connect() failed or raised — the adapter may
        have allocated partial resources (aiohttp.ClientSession, poll
        tasks, child subprocesses) that would otherwise leak and surface
        as "Unclosed client session" warnings at process exit.

        Must tolerate partial-init state and never raise, since callers
        use it inside error-handling blocks.
        """
        timeout = self._adapter_disconnect_timeout_secs()
        try:
            completed = await self._await_adapter_cleanup_with_timeout(
                adapter.disconnect(), timeout
            )
            if not completed:
                logger.warning(
                    "Timed out after %.1fs while disconnecting %s adapter; continuing shutdown",
                    timeout,
                    platform.value if platform is not None else "adapter",
                )
        except Exception as e:
            logger.debug(
                "Defensive %s disconnect after failed connect raised: %s",
                platform.value if platform is not None else "adapter",
                e,
            )

    def _adapter_disconnect_timeout_secs(self) -> float:
        """Return the per-adapter disconnect timeout used during shutdown."""
        raw = os.getenv("HERMES_GATEWAY_ADAPTER_DISCONNECT_TIMEOUT", "").strip()
        if raw:
            try:
                timeout = float(raw)
            except ValueError:
                logger.warning(
                    "Ignoring invalid HERMES_GATEWAY_ADAPTER_DISCONNECT_TIMEOUT=%r",
                    raw,
                )
            else:
                return max(0.0, timeout)
        return _ADAPTER_DISCONNECT_TIMEOUT_SECS_DEFAULT

    def _platform_connect_timeout_secs(self) -> float:
        """Return the per-platform connect timeout used during startup/retry."""
        raw = os.getenv("HERMES_GATEWAY_PLATFORM_CONNECT_TIMEOUT", "").strip()
        if raw:
            try:
                timeout = float(raw)
            except ValueError:
                logger.warning(
                    "Ignoring invalid HERMES_GATEWAY_PLATFORM_CONNECT_TIMEOUT=%r",
                    raw,
                )
            else:
                return max(0.0, timeout)
        return _PLATFORM_CONNECT_TIMEOUT_SECS_DEFAULT

    async def _connect_adapter_with_timeout(
        self,
        adapter,
        platform,
        *,
        is_reconnect: bool = False,
    ) -> bool:
        """Connect an adapter without allowing one platform to block others.

        Reconnect attempts preserve server-side update queues; cold startup may
        intentionally discard stale updates according to adapter policy.
        """
        timeout = self._platform_connect_timeout_secs()
        if timeout <= 0:
            return await adapter.connect(is_reconnect=is_reconnect)
        try:
            return await asyncio.wait_for(
                adapter.connect(is_reconnect=is_reconnect),
                timeout=timeout,
            )
        except asyncio.TimeoutError as exc:
            raise TimeoutError(
                f"{platform.value} connect timed out after {timeout:g}s"
            ) from exc

    @property
    def should_exit_cleanly(self) -> bool:
        return self._exit_cleanly

    @property
    def should_exit_with_failure(self) -> bool:
        return self._exit_with_failure

    @property
    def exit_reason(self) -> Optional[str]:
        return self._exit_reason

    @property
    def exit_code(self) -> Optional[int]:
        return self._exit_code

    def _session_key_for_source(self, source: SessionSource) -> str:
        """Resolve the current session key for a source, honoring gateway config when available."""
        config = getattr(self, "config", None)
        group_sessions_per_user = getattr(config, "group_sessions_per_user", True)
        thread_sessions_per_user = getattr(config, "thread_sessions_per_user", False)

        platform_cfg = None
        if config is not None:
            try:
                platform_cfg = getattr(config, "platforms", {}).get(source.platform)
            except Exception:
                platform_cfg = None
        if platform_cfg is None:
            adapter = self._adapter_for_source(source)
            platform_cfg = getattr(adapter, "config", None)

        extra = getattr(platform_cfg, "extra", None)
        if isinstance(extra, dict):
            group_sessions_per_user = extra.get("group_sessions_per_user", group_sessions_per_user)
            thread_sessions_per_user = extra.get("thread_sessions_per_user", thread_sessions_per_user)

        return build_session_key(
            source,
            group_sessions_per_user=group_sessions_per_user,
            thread_sessions_per_user=thread_sessions_per_user,
            profile=(
                getattr(source, "profile", None)
                if getattr(config, "multiplex_profiles", False)
                else None
            ),
        )

    def _adapter_for_source(self, source: Optional[SessionSource]) -> Optional[BasePlatformAdapter]:
        """Return the adapter that owns ``source``, including multiplex profiles."""
        if source is None:
            return None
        profile = getattr(source, "profile", None)
        if profile and profile != "default":
            adapter = getattr(self, "_profile_adapters", {}).get(profile, {}).get(source.platform)
            if adapter is not None:
                return adapter
        return getattr(self, "adapters", {}).get(source.platform)

    def _telegram_topic_mode_enabled(self, source: SessionSource) -> bool:
        """Return whether Telegram DM topic mode is active for this chat."""
        if source.platform != Platform.TELEGRAM or source.chat_type != "dm":
            return False
        session_db = getattr(self, "_session_db", None)
        if session_db is None:
            return False
        # These helpers run off-loop via ``asyncio.to_thread``. The gateway
        # stores AsyncSessionDB, so use its synchronous backing handle here.
        session_db = getattr(session_db, "_db", session_db)
        try:
            raw = session_db.is_telegram_topic_mode_enabled(
                chat_id=str(source.chat_id),
                user_id=str(source.user_id),
            )
        except Exception:
            logger.debug("Failed to read Telegram topic mode state", exc_info=True)
            return False
        # Only honor a real True from the SessionDB. Any other value
        # (including MagicMock instances from test fixtures that didn't
        # opt into topic mode) means topic mode is off for this chat.
        return raw is True

    # Telegram's General (pinned top) topic in forum-enabled private chats.
    # Bot API behavior varies: some clients omit message_thread_id for
    # General, others send "1". Treat both as "root" for lobby/lane purposes.
    _TELEGRAM_GENERAL_TOPIC_IDS = frozenset({"", "1"})

    def _is_telegram_topic_root_lobby(self, source: SessionSource) -> bool:
        """True for the main Telegram DM (or General topic) when topic mode has made it a lobby."""
        if source.platform != Platform.TELEGRAM or source.chat_type != "dm":
            return False
        if not self._telegram_topic_mode_enabled(source):
            return False
        tid = str(source.thread_id or "")
        return tid in self._TELEGRAM_GENERAL_TOPIC_IDS

    def _is_telegram_topic_lane(self, source: SessionSource) -> bool:
        """True for a user-created Telegram private-chat topic lane."""
        if source.platform != Platform.TELEGRAM or source.chat_type != "dm":
            return False
        if not self._telegram_topic_mode_enabled(source):
            return False
        tid = str(source.thread_id or "")
        if not tid or tid in self._TELEGRAM_GENERAL_TOPIC_IDS:
            return False
        return True

    _TELEGRAM_LOBBY_REMINDER_COOLDOWN_S = 30.0

    def _should_send_telegram_lobby_reminder(self, source: SessionSource) -> bool:
        """Rate-limit root-DM lobby reminders to one message per cooldown window.

        A user who forgets multi-session mode is enabled and types several
        prompts in the root DM would otherwise get a reminder for every
        message. Cap it so the first one lands and the rest stay quiet.
        """
        if not hasattr(self, "_telegram_lobby_reminder_ts"):
            self._telegram_lobby_reminder_ts = {}
        chat_id = str(source.chat_id or "")
        if not chat_id:
            return True
        import time as _time
        now = _time.monotonic()
        last = self._telegram_lobby_reminder_ts.get(chat_id, 0.0)
        if now - last < self._TELEGRAM_LOBBY_REMINDER_COOLDOWN_S:
            return False
        self._telegram_lobby_reminder_ts[chat_id] = now
        return True

    def _telegram_topic_root_lobby_message(self) -> str:
        return (
            "This main chat is reserved for system commands.\n\n"
            "To start a new Hermes chat, open the All Messages topic at the top "
            "of this bot interface and send any message there. Telegram will "
            "create a new topic for that message; each topic works as an "
            "independent Hermes session."
        )

    def _telegram_topic_root_new_message(self) -> str:
        return (
            "To start a new parallel Hermes chat, open the All Messages topic "
            "at the top of this bot interface and send any message there. "
            "Telegram will create a new topic for it.\n\n"
            "Each topic is an independent Hermes session. Use /new inside an "
            "existing topic only if you want to replace that topic's current session."
        )

    def _telegram_topic_new_header(self, source: SessionSource) -> Optional[str]:
        if not self._is_telegram_topic_lane(source):
            return None
        return (
            "Started a new Hermes session in this topic.\n\n"
            "Tip: for parallel work, open All Messages and send a message there "
            "to create a separate topic instead of using /new here. /new replaces "
            "the session attached to the current topic."
        )

    def _record_telegram_topic_binding(
        self,
        source: SessionSource,
        session_entry,
    ) -> None:
        """Persist the Telegram topic -> Hermes session binding for topic lanes."""
        session_db = getattr(self, "_session_db", None)
        if session_db is None or not source.chat_id or not source.thread_id:
            return
        # Runs off-loop via ``asyncio.to_thread``; avoid returning an un-awaited
        # AsyncSessionDB forwarding coroutine from this synchronous helper.
        session_db = getattr(session_db, "_db", session_db)
        session_db.bind_telegram_topic(
            chat_id=str(source.chat_id),
            thread_id=str(source.thread_id),
            user_id=str(source.user_id or ""),
            session_key=session_entry.session_key,
            session_id=session_entry.session_id,
        )

    def _sync_telegram_topic_binding(
        self,
        source: SessionSource,
        session_entry,
        *,
        reason: str,
    ) -> None:
        """Update the topic binding to point at ``session_entry.session_id``.

        Telegram topic lanes persist a (chat_id, thread_id) -> session_id row
        so reopening a topic in a fresh process resumes the right Hermes
        session. When compression rotates ``session_entry.session_id`` mid-turn,
        the binding goes stale and the next inbound message in that topic
        reloads the oversized parent transcript instead of the compressed
        child, retriggering preflight compression — sometimes in a loop
        (#20470, #29712, #33414).
        """
        if not self._is_telegram_topic_lane(source):
            return
        try:
            self._record_telegram_topic_binding(source, session_entry)
        except Exception:
            logger.debug(
                "telegram topic binding refresh failed (%s)", reason, exc_info=True,
            )

    def _recover_telegram_topic_thread_id(
        self,
        source: SessionSource,
    ) -> Optional[str]:
        """Pin DM-topic routing to the user's last-active topic.

        Telegram can omit ``message_thread_id`` or surface General (``1``)
        for some topic-mode DM replies. In those lobby-shaped cases, keep the
        conversation attached to the user's most-recent bound topic.

        Do not rewrite a non-lobby, previously-unbound thread id: a newly
        created Telegram DM topic is also "unknown" until the first inbound
        message is recorded, and rewriting it would send that brand-new topic's
        answer into an older lane. Returns None to leave the source alone.
        """
        if (
            source.platform != Platform.TELEGRAM
            or source.chat_type != "dm"
            or not source.chat_id
            or not source.user_id
            or not self._telegram_topic_mode_enabled(source)
        ):
            return None
        inbound = str(source.thread_id or "")
        is_lobby = not inbound or inbound in self._TELEGRAM_GENERAL_TOPIC_IDS
        if not is_lobby:
            # A non-lobby, unknown thread_id is most likely the first message in
            # a brand-new Telegram DM topic. Preserve it so it can be recorded
            # as a new independent lane below instead of hijacking the latest
            # existing topic binding.
            return None
        session_db = getattr(self, "_session_db", None)
        if session_db is None:
            return None
        # Runs off-loop via ``asyncio.to_thread``; use the synchronous handle.
        session_db = getattr(session_db, "_db", session_db)
        try:
            bindings = session_db.list_telegram_topic_bindings_for_chat(
                chat_id=str(source.chat_id),
            )
        except Exception:
            logger.debug("topic-recover: read failed", exc_info=True)
            return None
        if not bindings:
            return None
        user_id = str(source.user_id)
        for b in bindings:  # newest-first
            if str(b.get("user_id") or "") == user_id:
                recovered = str(b.get("thread_id") or "")
                if recovered and recovered != inbound:
                    return recovered
                return None
        return None

    def _resolve_session_agent_runtime(
        self,
        *,
        source: Optional[SessionSource] = None,
        session_key: Optional[str] = None,
        user_config: Optional[dict] = None,
        model_override: Optional[str] = None,
        turn_model_override: Optional[str] = None,
    ) -> tuple[str, dict]:
        """Resolve model/runtime for a session, honoring session-scoped /model overrides.

        If the session override already contains a complete provider bundle
        (provider/api_key/base_url/api_mode), prefer it directly instead of
        resolving fresh global runtime state first.
        """
        resolved_session_key = session_key
        if not resolved_session_key and source is not None:
            try:
                resolved_session_key = self._session_key_for_source(source)
            except Exception:
                resolved_session_key = None

        forced_turn_model = str(turn_model_override or "").strip()
        model = forced_turn_model or str(model_override or "").strip() or _resolve_gateway_model(user_config)
        # A command-scoped tier must not inherit a persistent /model override.
        # It uses the normal gateway runtime but never mutates session state.
        if resolved_session_key and not forced_turn_model:
            self._rehydrate_session_model_override(resolved_session_key)
        override = (
            None
            if forced_turn_model
            else self._session_model_overrides.get(resolved_session_key)
            if resolved_session_key
            else None
        )
        if override:
            override_model = override.get("model", model)
            override_runtime = {
                "provider": override.get("provider"),
                "api_key": override.get("api_key"),
                "base_url": override.get("base_url"),
                "api_mode": override.get("api_mode"),
                "max_tokens": override.get("max_tokens"),
                "credential_pool": override.get("credential_pool"),
            }
            if override_runtime.get("api_key"):
                if override_runtime.get("credential_pool") is None:
                    override_runtime["credential_pool"] = _credential_pool_for_provider(
                        override.get("provider")
                    )
                logger.debug(
                    "Session model override (fast): session=%s config_model=%s -> override_model=%s provider=%s",
                    resolved_session_key or "", model, override_model,
                    override_runtime.get("provider"),
                )
                return override_model, override_runtime
            # Override exists but has no api_key — fall through to env-based
            # resolution and apply model/provider from the override on top.
            logger.debug(
                "Session model override (no api_key, fallback): session=%s config_model=%s override_model=%s",
                resolved_session_key or "", model, override_model,
            )
        else:
            logger.debug(
                "No session model override: session=%s config_model=%s override_keys=%s",
                resolved_session_key or "", model,
                list(self._session_model_overrides.keys())[:5] if self._session_model_overrides else "[]",
            )

        runtime_kwargs = _resolve_runtime_agent_kwargs()
        runtime_model = runtime_kwargs.pop("model", None)
        if runtime_model and not forced_turn_model:
            logger.info(
                "Runtime provider supplied explicit model override: %s -> %s",
                model,
                runtime_model,
            )
            model = runtime_model
        elif runtime_model:
            logger.debug(
                "Ignoring runtime model override %s for command-scoped model %s",
                runtime_model,
                forced_turn_model,
            )

        # Channel/thread overrides sit below an explicit session /model (which
        # is re-applied below) and below command-scoped per-turn tiers, but above
        # the global runtime. Parent-channel inheritance is resolved by
        # _get_channel_override for thread sources.
        cfg = getattr(self, "config", None)
        if cfg and source is not None and not forced_turn_model:
            chat_id = str(source.chat_id) if source.chat_id else ""
            thread_id = (
                str(source.thread_id)
                if getattr(source, "thread_id", None)
                else None
            )
            parent_id = (
                str(source.parent_chat_id)
                if getattr(source, "parent_chat_id", None)
                else None
            )
            channel_override = _get_channel_override(
                cfg,
                source.platform,
                chat_id,
                thread_id=thread_id,
                parent_id=parent_id,
            )
            if channel_override:
                if channel_override.model:
                    model = channel_override.model
                if channel_override.provider:
                    runtime_kwargs = _resolve_runtime_agent_kwargs_for_provider(
                        channel_override.provider
                    )
                    channel_runtime_model = runtime_kwargs.pop("model", None)
                    if channel_runtime_model and not channel_override.model:
                        model = channel_runtime_model
        if override and resolved_session_key:
            model, runtime_kwargs = self._apply_session_model_override(
                resolved_session_key, model, runtime_kwargs
            )

        # When the config has no model.default but a provider was resolved
        # (e.g. user ran `hermes auth add openai-codex` without `hermes model`),
        # fall back to the provider's first catalog model so the API call
        # doesn't fail with "model must be a non-empty string".
        if not model and runtime_kwargs.get("provider"):
            try:
                from hermes_cli.models import get_default_model_for_provider
                model = get_default_model_for_provider(runtime_kwargs["provider"])
                if model:
                    logger.info(
                        "No model configured — defaulting to %s for provider %s",
                        model, runtime_kwargs["provider"],
                    )
            except Exception:
                pass

        # Final safety net (#35314): if resolution still produced an empty
        # model — e.g. a transient config-cache miss during a post-interrupt
        # recovery turn returned an empty user_config — reuse the last model we
        # successfully resolved for this session (or, failing that, the most
        # recent one resolved process-wide). Building an agent with model=""
        # makes every API call fail HTTP 400 "No models provided" and the
        # session goes silent until the user manually re-sends. ``getattr``
        # guards against bare test runners built via ``object.__new__``.
        _last_good = getattr(self, "_last_resolved_model", None)
        if _last_good is not None:
            if not model:
                _recovered = _last_good.get(resolved_session_key or "") or _last_good.get("*")
                if _recovered:
                    logger.warning(
                        "Empty model resolved for session=%s — recovering "
                        "last-known-good model %s (config read likely returned "
                        "empty; see #35314)",
                        resolved_session_key or "", _recovered,
                    )
                    model = _recovered
            elif model:
                # Cache the good resolution for future recovery turns.
                if resolved_session_key:
                    _last_good[resolved_session_key] = model
                _last_good["*"] = model

        return model, runtime_kwargs

    def _resolve_turn_agent_config(
        self,
        user_message: str,
        model: str,
        runtime_kwargs: dict,
        user_config: Optional[dict] = None,
    ) -> dict:
        """Build the effective model/runtime config for a single turn.

        Always uses the session's primary model/provider. Session-scoped
        priority processing and Responses API text verbosity are applied as
        request overrides without changing provider/runtime selection.
        """
        runtime = {
            "api_key": runtime_kwargs.get("api_key"),
            "base_url": runtime_kwargs.get("base_url"),
            "provider": runtime_kwargs.get("provider"),
            "api_mode": runtime_kwargs.get("api_mode"),
            "command": runtime_kwargs.get("command"),
            "args": list(runtime_kwargs.get("args") or []),
            "credential_pool": runtime_kwargs.get("credential_pool"),
            "max_tokens": runtime_kwargs.get("max_tokens"),
        }
        from hermes_cli.models import resolve_fast_mode_overrides
        from hermes_constants import merge_model_verbosity_request_overrides

        agent_config = (user_config or {}).get("agent")
        verbosity = (
            agent_config.get("model_verbosity")
            if isinstance(agent_config, dict)
            else ""
        )
        service_tier = getattr(self, "_service_tier", None)
        fast_overrides = {}
        if service_tier:
            try:
                fast_overrides = resolve_fast_mode_overrides(model) or {}
            except Exception:
                fast_overrides = {}
        request_overrides = merge_model_verbosity_request_overrides(
            fast_overrides,
            api_mode=str(runtime.get("api_mode") or ""),
            verbosity=verbosity,
        )
        route = {
            "model": model,
            "runtime": runtime,
            "signature": (
                model,
                runtime["provider"],
                runtime["base_url"],
                runtime["api_mode"],
                runtime["command"],
                tuple(runtime["args"]),
            ),
            "request_overrides": request_overrides or {},
        }
        return route

    async def _handle_adapter_fatal_error(self, adapter: BasePlatformAdapter) -> None:
        """React to an adapter failure after startup.

        If the error is retryable (e.g. network blip, DNS failure), queue the
        platform for background reconnection instead of giving up permanently.
        """
        existing = self.adapters.get(adapter.platform)
        if existing is not None and existing is not adapter:
            logger.debug(
                "Ignoring stale fatal error from a superseded %s adapter instance: %s",
                adapter.platform.value,
                adapter.fatal_error_code or "unknown",
            )
            return

        logger.error(
            "Fatal %s adapter error (%s): %s",
            adapter.platform.value,
            adapter.fatal_error_code or "unknown",
            adapter.fatal_error_message or "unknown error",
        )
        if adapter.fatal_error_code == "relay_disabled":
            platform_state = "disabled"
        elif adapter.fatal_error_retryable:
            platform_state = "retrying"
        else:
            platform_state = "fatal"
        self._update_platform_runtime_status(
            adapter.platform.value,
            platform_state=platform_state,
            error_code=adapter.fatal_error_code,
            error_message=adapter.fatal_error_message,
        )

        if existing is adapter:
            self.adapters.pop(adapter.platform, None)
            self.delivery_router.adapters = self.adapters
            await self._safe_adapter_disconnect(adapter, adapter.platform)

        # Queue retryable failures for background reconnection
        if adapter.fatal_error_retryable:
            platform_config = self.config.platforms.get(adapter.platform)
            if platform_config and adapter.platform not in self._failed_platforms:
                self._failed_platforms[adapter.platform] = {
                    "config": platform_config,
                    "attempts": 0,
                    "next_retry": time.monotonic(),
                }
                logger.info(
                    "%s queued for background reconnection",
                    adapter.platform.value,
                )

        if not self.adapters and not self._failed_platforms:
            self._exit_reason = adapter.fatal_error_message or "All messaging adapters disconnected"
            if adapter.fatal_error_retryable:
                self._exit_with_failure = True
                logger.error("No connected messaging platforms remain. Shutting down gateway for service restart.")
            else:
                logger.error("No connected messaging platforms remain. Shutting down gateway cleanly.")
            await self.stop()
        elif not self.adapters and self._failed_platforms:
            # All platforms are down and queued for background reconnection.
            # Keep the gateway alive so:
            #   • cron jobs still run
            #   • the reconnect watcher can recover platforms when the
            #     underlying problem clears (proxy comes back, user runs
            #     `hermes whatsapp`, etc.)
            # We used to exit-with-failure here to trigger systemd restart,
            # but that converted a transient outage into a restart loop and
            # killed in-process state every time. The reconnect watcher
            # already handles long-running recovery — let it do its job.
            logger.warning(
                "No connected messaging platforms remain, but %d platform(s) "
                "queued for reconnection — gateway staying alive, watcher will "
                "retry in background.",
                len(self._failed_platforms),
            )

    def _request_clean_exit(self, reason: str) -> None:
        self._exit_cleanly = True
        self._exit_reason = reason
        self._shutdown_event.set()

    def _running_agent_count(self) -> int:
        return len(self._running_agents)

    def _status_action_label(self) -> str:
        return "restart" if self._restart_requested else "shutdown"

    def _status_action_gerund(self) -> str:
        return "restarting" if self._restart_requested else "shutting down"

    def _queue_during_drain_enabled(self) -> bool:
        # Both "queue" and "steer" modes imply the user doesn't want messages
        # to be lost during restart — queue them for the newly-spawned gateway
        # process to pick up.  "interrupt" mode drops them (current behaviour).
        return self._restart_requested and self._busy_input_mode in {"queue", "steer"}

    # -------- /queue FIFO helpers --------------------------------------
    # /queue must produce one full agent turn per invocation, in FIFO
    # order, with no merging.  The adapter's _pending_messages dict is a
    # single "next-up" slot (shared with photo-burst follow-ups), so we
    # use it for the head of the queue and an overflow list for the
    # tail.  Enqueue puts new items in the slot when free, otherwise in
    # the overflow.  Promotion (called after each run's drain) moves the
    # next overflow item into the slot so the following recursion picks
    # it up.  Clearing happens on /new and /reset via
    # _handle_reset_command.

    def _enqueue_fifo(self, session_key: str, queued_event: "MessageEvent", adapter: Any) -> None:
        """Append a /queue event to the FIFO chain for a session."""
        if adapter is None:
            return
        pending_slot = getattr(adapter, "_pending_messages", None)
        if pending_slot is None:
            return
        queued_events = getattr(self, "_queued_events", None)
        if queued_events is None:
            queued_events = {}
            self._queued_events = queued_events
        if session_key in pending_slot:
            queued_events.setdefault(session_key, []).append(queued_event)
        else:
            pending_slot[session_key] = queued_event

    @staticmethod
    def _queued_event_identity(event: Any) -> tuple[str, str] | None:
        """Return a durable identity only for replay-safe deduplication."""

        if not getattr(event, "work_replay", False):
            return None
        work_id = str(getattr(event, "work_item_id", "") or "").strip()
        if work_id:
            return ("work_item", work_id)
        message_id = str(getattr(event, "message_id", "") or "").strip()
        if message_id:
            return ("discord_message", message_id)
        return None

    def _queued_event_already_present(
        self,
        session_key: str,
        event: "MessageEvent",
        adapter: Any,
    ) -> bool:
        identity = self._queued_event_identity(event)
        if identity is None:
            return False
        pending_slot = getattr(adapter, "_pending_messages", None)
        head = pending_slot.get(session_key) if isinstance(pending_slot, dict) else None
        if self._queued_event_identity(head) == identity:
            return True
        overflow = (getattr(self, "_queued_events", None) or {}).get(session_key, [])
        return any(self._queued_event_identity(candidate) == identity for candidate in overflow)

    def _prepend_fifo(self, session_key: str, queued_event: "MessageEvent", adapter: Any) -> None:
        """Put an event back at the head without disturbing later FIFO order."""
        if adapter is None:
            return
        pending_slot = getattr(adapter, "_pending_messages", None)
        if not isinstance(pending_slot, dict):
            return
        queued_events = getattr(self, "_queued_events", None)
        if queued_events is None:
            queued_events = {}
            self._queued_events = queued_events
        existing_head = pending_slot.get(session_key)
        if existing_head is not None:
            queued_events.setdefault(session_key, []).insert(0, existing_head)
        pending_slot[session_key] = queued_event

    def _enqueue_internal_completion(
        self,
        session_key: str,
        event: "MessageEvent",
    ) -> None:
        """Queue a synthetic completion as its own turn after real pending input."""
        queued_events = getattr(self, "_queued_events", None)
        if queued_events is None:
            queued_events = {}
            self._queued_events = queued_events
        queued_events.setdefault(session_key, []).append(event)

    def _promote_queued_event(
        self,
        session_key: str,
        adapter: Any,
        pending_event: Optional["MessageEvent"],
    ) -> Optional["MessageEvent"]:
        """Promote the next overflow item after the slot was drained.

        Called at the drain site after _dequeue_pending_event consumed
        (or failed to consume) the slot.  If there's an overflow item:
          - When pending_event is None (slot was empty), return the
            overflow head as the new pending_event.
          - When pending_event already exists (slot was populated by an
            interrupt follow-up or similar), stage the overflow head in
            the slot so the NEXT recursion picks it up.
        Returns the (possibly updated) pending_event for drain to use.
        """
        queued_events = getattr(self, "_queued_events", None)
        if not queued_events:
            return pending_event
        overflow = queued_events.get(session_key)
        if not overflow:
            return pending_event
        next_queued = overflow.pop(0)
        if not overflow:
            queued_events.pop(session_key, None)
        if pending_event is None:
            return next_queued
        if adapter is not None and hasattr(adapter, "_pending_messages"):
            adapter._pending_messages[session_key] = next_queued
        else:
            # No adapter — push back so we don't silently drop the item.
            queued_events.setdefault(session_key, []).insert(0, next_queued)
        return pending_event

    def _queue_depth(self, session_key: str, *, adapter: Any = None) -> int:
        """Total pending /queue items for a session — slot + overflow."""
        queued_events = getattr(self, "_queued_events", None) or {}
        depth = len(queued_events.get(session_key, []))
        if adapter is not None and session_key in getattr(adapter, "_pending_messages", {}):
            depth += 1
        return depth

    @staticmethod
    def _is_goal_continuation_event(event_or_text: Any) -> bool:
        """Return True for synthetic /goal work turns.

        Goal kickoff/resume/continuation prompts are normal queued user-role
        events, so pause/clear must distinguish them from real user /queue
        messages before removing or suppressing them.
        """
        text = str(getattr(event_or_text, "text", event_or_text) or "")
        return text.startswith(
            (
                "[Starting work toward your standing goal]\nGoal",
                "[Continuing toward your standing goal]\nGoal:",
            )
        )

    @staticmethod
    def _goal_kickoff_prompt(goal: str) -> str:
        """Wrap a newly set goal so nested slash lines are agent work."""
        return f"[Starting work toward your standing goal]\nGoal:\n{goal}"

    def _enqueue_goal_work(self, event: "MessageEvent", prompt: str) -> None:
        """Queue a synthetic goal work turn for the event's session."""
        if not prompt or event.source is None:
            return
        adapter = self._adapter_for_source(event.source)
        session_key = self._session_key_for_source(event.source)
        if not adapter or not session_key:
            return
        goal_event = MessageEvent(
            text=prompt,
            message_type=MessageType.TEXT,
            source=event.source,
            message_id=event.message_id,
            channel_prompt=event.channel_prompt,
        )
        if isinstance(getattr(event, "feature_summary", None), dict):
            goal_event.feature_summary = event.feature_summary
        if isinstance(getattr(event, "project_summary", None), dict):
            goal_event.project_summary = event.project_summary
        self._enqueue_fifo(session_key, goal_event, adapter)

    def _clear_goal_pending_continuations(self, session_key: str, adapter: Any) -> int:
        """Remove queued synthetic /goal continuations for one session.

        User-issued /goal pause/clear can race with a continuation already
        queued by the judge.  Remove only synthetic goal continuations while
        preserving normal /queue and user follow-up events.
        """
        removed = 0
        pending_slot = getattr(adapter, "_pending_messages", None) if adapter is not None else None
        if isinstance(pending_slot, dict):
            pending_event = pending_slot.get(session_key)
            if self._is_goal_continuation_event(pending_event):
                pending_slot.pop(session_key, None)
                removed += 1

        queued_events = getattr(self, "_queued_events", None)
        if isinstance(queued_events, dict):
            overflow = queued_events.get(session_key) or []
            if overflow:
                kept = []
                for queued_event in overflow:
                    if self._is_goal_continuation_event(queued_event):
                        removed += 1
                    else:
                        kept.append(queued_event)
                if kept:
                    queued_events[session_key] = kept
                else:
                    queued_events.pop(session_key, None)
        return removed

    def _goal_still_active_for_session(self, session_id: str) -> bool:
        """Best-effort fresh DB check before running a queued continuation."""
        if not session_id:
            return False
        try:
            from hermes_cli.goals import GoalManager
            return GoalManager(session_id=session_id).is_active()
        except Exception as exc:
            logger.debug("goal continuation: active-state recheck failed: %s", exc)
            return False

    def _update_runtime_status(self, gateway_state: Optional[str] = None, exit_reason: Optional[str] = None) -> None:
        try:
            from gateway.status import write_runtime_status
            write_runtime_status(
                gateway_state=gateway_state,
                exit_reason=exit_reason,
                restart_requested=self._restart_requested,
                active_agents=self._active_work_count(),
            )
        except Exception:
            pass

    def _refresh_active_agent_runtime_status(self) -> None:
        self._update_runtime_status("draining" if getattr(self, "_draining", False) else "running")

    def _update_platform_runtime_status(
        self,
        platform: str,
        *,
        platform_state: Optional[str] = None,
        error_code: Optional[str] = None,
        error_message: Optional[str] = None,
    ) -> None:
        try:
            from gateway.status import write_runtime_status
            write_runtime_status(
                platform=platform,
                platform_state=platform_state,
                error_code=error_code,
                error_message=error_message,
            )
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Per-platform circuit breaker (pause/resume) — used by the reconnect
    # watcher when a retryable failure recurs past a threshold, and by the
    # /platform pause|resume slash command for manual control.
    # ------------------------------------------------------------------
    def _pause_failed_platform(self, platform, *, reason: str = "") -> None:
        """Mark a queued platform as paused — keep it in ``_failed_platforms``
        but stop the reconnect watcher from hammering it.

        Used by ``/platform pause <name>`` for manual operator intervention.
        Paused platforms are surfaced in ``/platform list`` and resumed with
        ``/platform resume <name>``.  Note: the reconnect watcher does NOT
        auto-pause — retryable (network/DNS) failures keep retrying at the
        backoff cap indefinitely so a transient outage self-heals without
        manual intervention.
        """
        info = getattr(self, "_failed_platforms", {}).get(platform)
        if info is None:
            return
        if info.get("paused"):
            return
        info["paused"] = True
        info["pause_reason"] = reason or "auto-paused after repeated failures"
        # Push next_retry far enough out that even if "paused" is missed
        # by a stale code path, the watcher won't fire on it.
        info["next_retry"] = float("inf")
        try:
            self._update_platform_runtime_status(
                platform.value,
                platform_state="paused",
                error_code=None,
                error_message=info["pause_reason"],
            )
        except Exception:
            pass
        logger.warning(
            "%s paused after %d consecutive failures (%s) — "
            "fix the underlying issue then run `/platform resume %s` "
            "to retry, or `hermes gateway restart` to restart the gateway.",
            platform.value, info.get("attempts", 0),
            info["pause_reason"], platform.value,
        )

    def _resume_paused_platform(self, platform) -> bool:
        """Unpause a platform — reset its attempt counter and schedule an
        immediate retry.  Returns True if the platform was paused and is
        now queued; False if it wasn't paused (or wasn't in the queue).
        """
        info = getattr(self, "_failed_platforms", {}).get(platform)
        if info is None:
            return False
        if not info.get("paused"):
            return False
        info["paused"] = False
        info.pop("pause_reason", None)
        info["attempts"] = 0
        info["next_retry"] = time.monotonic()  # retry on next watcher tick
        try:
            self._update_platform_runtime_status(
                platform.value,
                platform_state="retrying",
                error_code=None,
                error_message=None,
            )
        except Exception:
            pass
        logger.info("%s resumed — retrying on next watcher tick", platform.value)
        return True

    @staticmethod
    def _load_prefill_messages() -> List[Dict[str, Any]]:
        """Load ephemeral prefill messages from config or env var.

        Checks HERMES_PREFILL_MESSAGES_FILE env var first, then falls back to
        the top-level prefill_messages_file key in ~/.hermes/config.yaml.
        agent.prefill_messages_file is accepted as a legacy fallback.
        Relative paths are resolved from ~/.hermes/.
        """
        file_path = os.getenv("HERMES_PREFILL_MESSAGES_FILE", "")
        if not file_path:
            cfg = _load_gateway_runtime_config()
            file_path = str(cfg.get("prefill_messages_file", "") or "")
            if not file_path:
                file_path = str(
                    cfg_get(
                        cfg,
                        "agent",
                        "prefill_messages_file",
                        default="",
                    )
                    or ""
                )
        if not file_path:
            return []
        path = Path(file_path).expanduser()
        if not path.is_absolute():
            path = _hermes_home / path
        if not path.exists():
            logger.warning("Prefill messages file not found: %s", path)
            return []
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, list):
                logger.warning("Prefill messages file must contain a JSON array: %s", path)
                return []
            return data
        except Exception as e:
            logger.warning("Failed to load prefill messages from %s: %s", path, e)
            return []

    @staticmethod
    def _load_ephemeral_system_prompt() -> str:
        """Load ephemeral system prompt from config or env var.

        Checks HERMES_EPHEMERAL_SYSTEM_PROMPT env var first, then falls back to
        agent.system_prompt in ~/.hermes/config.yaml.
        """
        prompt = os.getenv("HERMES_EPHEMERAL_SYSTEM_PROMPT", "")
        if prompt:
            return prompt
        cfg = _load_gateway_runtime_config()
        return str(cfg_get(cfg, "agent", "system_prompt", default="") or "").strip()

    @staticmethod
    def _load_reasoning_config(model: str = "") -> dict | None:
        """Load reasoning effort from config.yaml, respecting per-model overrides.

        Thin wrapper over the shared chokepoint
        :func:`hermes_constants.resolve_reasoning_config` (per-model override >
        global ``agent.reasoning_effort``; YAML boolean False = disabled).
        Closes #21256.

        Args:
            model: The effective model for the calling session. When empty,
                   the config's ``model.default`` is used.
        """
        from hermes_constants import resolve_reasoning_config
        cfg = _load_gateway_runtime_config()
        model_tier = _gateway_model_tier(cfg)
        if model_tier is not None and (
            not model or str(model).strip() == str(model_tier.model).strip()
        ):
            return model_tier.reasoning_config()
        return resolve_reasoning_config(cfg, model)

    @staticmethod
    def _parse_reasoning_command_args(raw_args: str) -> tuple[str, bool]:
        """Parse `/reasoning` args into `(value, persist_global)`.

        `/reasoning <level>` is session-scoped by default. `--global` may be
        supplied in any position to persist the change to config.yaml.
        """
        import shlex

        text = str(raw_args or "").strip().replace("—", "--")
        if not text:
            return "", False
        try:
            tokens = shlex.split(text)
        except ValueError:
            tokens = text.split()

        persist_global = False
        value_tokens = []
        for token in tokens:
            if token == "--global":
                persist_global = True
            else:
                value_tokens.append(token)
        return " ".join(value_tokens).strip().lower(), persist_global

    def _resolve_session_reasoning_config(
        self,
        *,
        source: Optional[SessionSource] = None,
        session_key: Optional[str] = None,
        model: str = "",
    ) -> dict | None:
        """Resolve reasoning effort for a session, honoring session overrides.

        Priority: session-scoped ``/reasoning --session`` override >
        per-model override (``agent.reasoning_overrides``) > global
        ``agent.reasoning_effort``. ``model`` should be the session's
        *effective* model (session ``/model`` override included) so
        per-model overrides track what the session actually runs — when
        empty, the config's ``model.default`` is used.
        """
        resolved_session_key = session_key
        if not resolved_session_key and source is not None:
            try:
                resolved_session_key = self._session_key_for_source(source)
            except Exception:
                resolved_session_key = None

        overrides = getattr(self, "_session_reasoning_overrides", {}) or {}
        if resolved_session_key and resolved_session_key in overrides:
            return overrides[resolved_session_key]
        try:
            return self._load_reasoning_config(model)
        except TypeError as model_error:
            # Compatibility for tests/plugins that replace the historical
            # no-argument loader.  If the fallback also raises TypeError,
            # preserve the original failure instead of hiding a real bug in
            # the current loader implementation.
            try:
                return self._load_reasoning_config()
            except TypeError:
                raise model_error

    def _set_session_reasoning_override(
        self,
        session_key: str,
        reasoning_config: Optional[dict],
    ) -> None:
        """Set or clear the session-scoped reasoning override."""
        if not session_key:
            return
        if not hasattr(self, "_session_reasoning_overrides"):
            self._session_reasoning_overrides = {}
        if reasoning_config is None:
            self._session_reasoning_overrides.pop(session_key, None)
        else:
            self._session_reasoning_overrides[session_key] = dict(reasoning_config)

    @staticmethod
    def _load_service_tier() -> str | None:
        """Load Priority Processing from the shared agent configuration."""
        cfg = _load_gateway_runtime_config()
        raw = str(cfg_get(cfg, "agent", "service_tier", default="") or "").strip()
        value = raw.lower()
        if not value or value in {"normal", "default", "standard", "off", "none"}:
            return None
        if value in {"fast", "priority", "on"}:
            return "priority"
        logger.warning("Unknown service_tier '%s', ignoring", raw)
        return None

    @staticmethod
    def _load_show_reasoning() -> bool:
        """Load show_reasoning toggle from config.yaml display section."""
        cfg = _load_gateway_runtime_config()
        return is_truthy_value(
            cfg_get(cfg, "display", "show_reasoning"),
            default=False,
        )

    @staticmethod
    def _load_busy_input_mode() -> str:
        """Resolve explicit new/legacy settings before the steer default."""
        mode = os.getenv("HERMES_GATEWAY_BUSY_INPUT_MODE", "").strip().lower()
        cfg = _load_gateway_runtime_config()
        if not mode:
            mode = str(
                cfg_get(cfg, "display", "busy_input_mode", default="") or ""
            ).strip().lower()
        if mode in {"interrupt", "queue", "steer"}:
            return mode

        legacy = os.getenv("HERMES_GATEWAY_BUSY_TEXT_MODE", "").strip().lower()
        if not legacy:
            legacy = str(
                cfg_get(cfg, "display", "busy_text_mode", default="") or ""
            ).strip().lower()
        if legacy in {"interrupt", "queue"}:
            return legacy
        return "steer"

    @staticmethod
    def _load_busy_text_mode() -> str:
        """Resolve normal busy TEXT follow-up behavior.

        ``busy_input_mode`` is authoritative when explicitly set. The legacy
        ``busy_text_mode`` key is consulted only when the new key is absent so
        existing queue-based setups retain their behavior.
        """
        return GatewayRunner._load_busy_input_mode()

    @staticmethod
    def _load_restart_drain_timeout() -> float:
        """Load graceful gateway restart/stop drain timeout in seconds."""
        raw = os.getenv("HERMES_RESTART_DRAIN_TIMEOUT", "").strip()
        if not raw:
            cfg = _load_gateway_runtime_config()
            raw = str(cfg_get(cfg, "agent", "restart_drain_timeout", default="") or "").strip()
        value = parse_restart_drain_timeout(raw)
        if raw and value == DEFAULT_GATEWAY_RESTART_DRAIN_TIMEOUT:
            try:
                float(raw)
            except (TypeError, ValueError):
                logger.warning(
                    "Invalid restart_drain_timeout '%s', using default %.0fs",
                    raw,
                    DEFAULT_GATEWAY_RESTART_DRAIN_TIMEOUT,
                )
        return value

    @staticmethod
    def _load_background_notifications_mode() -> str:
        """Load background process notification mode from config or env var.

        Modes:
          - ``all``    — push running-output updates *and* the final message (default)
          - ``result`` — only the final completion message (regardless of exit code)
          - ``error``  — only the final message when exit code is non-zero
          - ``off``    — no watcher messages at all
        """
        mode = os.getenv("HERMES_BACKGROUND_NOTIFICATIONS", "")
        if not mode:
            cfg = _load_gateway_runtime_config()
            raw = cfg_get(cfg, "display", "background_process_notifications")
            if raw is False:
                mode = "off"
            elif raw not in {None, ""}:
                mode = str(raw)
        mode = (mode or "all").strip().lower()
        valid = {"all", "result", "error", "off"}
        if mode not in valid:
            logger.warning(
                "Unknown background_process_notifications '%s', defaulting to 'all'",
                mode,
            )
            return "all"
        return mode

    def _is_stale_discord_process_completion(
        self,
        event: MessageEvent,
        session_key: str,
    ) -> bool:
        """Return whether a terminal-process completion arrived after final delivery.

        ``notify_on_complete`` terminal jobs can finish while their originating
        Discord action is still running. The adapter correctly queues the
        synthetic completion behind that action, but it must not later reclaim
        a work item whose final response is already visible. Doing so turns a
        stale process result into a fresh model turn and produces misleading
        follow-up replies long after the task was closed.

        Keep ordinary completions and completions for still-active work items
        intact; only discard terminal-process events whose originating item is
        already past response delivery. The process registry remains the
        durable source for the actual command output.
        """
        if not getattr(event, "background_process_completion", False):
            return False
        if getattr(getattr(event, "source", None), "platform", None) != Platform.DISCORD:
            return False

        try:
            work_item_id = str(
                getattr(event, "work_item_id", "")
                or self._discord_work_item_id_for_event(event, session_key)
                or ""
            )
            item = self._ledger().get(work_item_id) if work_item_id else None
        except Exception:
            logger.debug(
                "Could not resolve Discord work item for process completion",
                exc_info=True,
            )
            return False
        if not isinstance(item, dict):
            return False

        status = str(item.get("status") or "").strip().lower()
        return status in {
            "response_delivered",
            "summary_updated",
            "completed",
            "failed",
            "blocked",
            "cancelled",
            "expired",
        }

    @staticmethod
    def _is_consumed_process_completion(event: Optional[MessageEvent]) -> bool:
        """Return whether a queued terminal completion was already read.

        A process may exit while its originating agent turn is still active.
        The watcher can queue the synthetic completion just before that turn
        consumes the same result via ``process wait`` or ``process log``. Recheck
        consumption when draining the queue so the raced event does not become a
        redundant second model turn.
        """
        if not event or not getattr(event, "background_process_completion", False):
            return False
        process_session_id = str(
            getattr(event, "background_process_session_id", "") or ""
        ).strip()
        if not process_session_id:
            return False
        try:
            from tools.process_registry import process_registry

            return process_registry.is_completion_consumed(process_session_id)
        except Exception:
            logger.debug(
                "Could not check consumed process completion %s",
                process_session_id,
                exc_info=True,
            )
            return False

    @staticmethod
    def _session_has_pending_background_workers(
        session_key: str,
        *,
        work_item_id: Optional[str] = None,
        origin_run_generation: Optional[int] = None,
        origin_attempt_id: Optional[str] = None,
        exclude_delegation_id: Optional[str] = None,
    ) -> bool:
        if not session_key:
            return False
        try:
            from tools.async_delegation import pending_count

            return pending_count(
                kind="coding_worker",
                session_key=session_key,
                origin_work_item_id=work_item_id,
                origin_run_generation=origin_run_generation,
                origin_attempt_id=origin_attempt_id,
                exclude_delegation_id=exclude_delegation_id,
            ) > 0
        except Exception:
            return False

    @staticmethod
    def _background_completion_success(evt: dict) -> bool:
        result = evt.get("result") if isinstance(evt.get("result"), dict) else {}
        return bool(
            evt.get("status") in {"completed", "success"}
            and result.get("success", True)
        )

    def _async_completion_lifecycle_state(self, event: MessageEvent) -> str:
        """Return the exact durable lifecycle state for Discord reactions."""
        kind = str(getattr(event, "background_completion_kind", "") or "")
        if kind:
            # Required coding results never become model turns.  Any completion
            # event that reaches an adapter is advisory and cannot repaint the
            # originating work-item reaction.
            return "advisory"
        try:
            ledger = self._ledger()
            session_key = self._session_key_for_source(event.source)
            work_item_id = str(getattr(event, "work_item_id", "") or "")
            if not work_item_id:
                work_item_id = str(ledger.id_for_event(event, session_key) or "")
            item = ledger.get(work_item_id) if work_item_id else None
            required = (
                ledger.required_async_completion_state(work_item_id)
                if work_item_id
                else None
            )
        except Exception:
            return "ordinary"
        if not isinstance(item, dict):
            return "ordinary"
        status = str(item.get("status") or "")
        summary_status = str(item.get("summary_status") or "").strip().lower()
        if status in {"failed", "blocked", "cancelled", "expired"} or summary_status in {
            "failed",
            "failure",
            "error",
            "errored",
            "interrupted",
            "blocked",
        }:
            return "failed"
        if status == "completed":
            return "succeeded"
        if isinstance(required, dict) and str(required.get("attempt_id") or ""):
            return "running"
        return "ordinary"

    def _install_background_worker_reaction_gate(self, adapter: Any) -> None:
        """Keep Discord action reactions pending while detached workers remain."""
        platform = getattr(adapter, "platform", None)
        platform_value = getattr(platform, "value", platform)
        if str(platform_value or "").lower() != "discord":
            return
        if getattr(adapter, "_hermes_background_worker_reaction_gate", False):
            return
        original_complete = getattr(adapter, "on_processing_complete", None)
        original_start = getattr(adapter, "on_processing_start", None)
        if not callable(original_complete):
            return

        async def _gated_processing_complete(event: MessageEvent, outcome: Any) -> None:
            lifecycle_state = self._async_completion_lifecycle_state(event)
            if lifecycle_state in {"advisory", "stale"}:
                return
            if lifecycle_state == "running":
                if callable(original_start):
                    await original_start(event)
                return
            if lifecycle_state == "failed":
                await original_complete(event, ProcessingOutcome.FAILURE)
                return
            if lifecycle_state == "succeeded":
                await original_complete(event, ProcessingOutcome.SUCCESS)
                return
            try:
                session_key = self._session_key_for_source(event.source)
            except Exception:
                session_key = ""
            completion_id = str(
                getattr(event, "background_completion_id", "") or ""
            ) or None
            if self._session_has_pending_background_workers(
                session_key,
                work_item_id=str(getattr(event, "work_item_id", "") or "") or None,
                origin_run_generation=getattr(
                    event,
                    "background_completion_generation",
                    None,
                ),
                origin_attempt_id=getattr(
                    event,
                    "background_completion_attempt_id",
                    None,
                ),
                exclude_delegation_id=completion_id,
            ):
                if callable(original_start):
                    await original_start(event)
                return
            await original_complete(event, outcome)

        adapter.on_processing_complete = _gated_processing_complete
        adapter._hermes_background_worker_reaction_gate = True

    @staticmethod
    def _load_provider_routing() -> dict:
        """Load OpenRouter provider routing preferences from config.yaml."""
        try:
            import yaml as _y
            cfg_path = _hermes_home / "config.yaml"
            if cfg_path.exists():
                with open(cfg_path, encoding="utf-8") as _f:
                    cfg = _y.safe_load(_f) or {}
                return cfg.get("provider_routing", {}) or {}
        except Exception:
            pass
        return {}

    @staticmethod
    def _load_fallback_model() -> list | None:
        """Load fallback provider chain from config.yaml.

        Returns the merged effective chain from ``fallback_providers`` plus any
        legacy ``fallback_model`` entries. ``fallback_providers`` stays first
        when both keys are present.
        """
        try:
            import yaml as _y
            cfg_path = _hermes_home / "config.yaml"
            if cfg_path.exists():
                with open(cfg_path, encoding="utf-8") as _f:
                    cfg = _y.safe_load(_f) or {}
                fb = get_fallback_chain(cfg)
                if fb:
                    return fb
        except Exception:
            pass
        return None

    def _snapshot_running_agents(self) -> Dict[str, Any]:
        return {
            session_key: agent
            for session_key, agent in self._running_agents.items()
            if agent is not _AGENT_PENDING_SENTINEL
        }

    def _registered_adapters_for_shutdown(self) -> list[BasePlatformAdapter]:
        """Return every primary/profile adapter once for drain accounting."""

        adapters: list[BasePlatformAdapter] = []
        seen: set[int] = set()
        registries = [getattr(self, "adapters", {})]
        registries.extend(
            profile_adapters
            for profile_adapters in getattr(self, "_profile_adapters", {}).values()
            if isinstance(profile_adapters, dict)
        )
        for registry in registries:
            if not isinstance(registry, dict):
                continue
            for adapter in registry.values():
                if adapter is None or id(adapter) in seen:
                    continue
                seen.add(id(adapter))
                adapters.append(adapter)
        return adapters

    def _snapshot_adapter_processing_tasks(
        self,
    ) -> list[tuple[BasePlatformAdapter, str, asyncio.Task]]:
        """Snapshot live adapter-owned message processing/delivery tasks."""

        snapshot: list[tuple[BasePlatformAdapter, str, asyncio.Task]] = []
        for adapter in self._registered_adapters_for_shutdown():
            get_active = getattr(adapter, "active_processing_tasks", None)
            if not callable(get_active):
                continue
            try:
                active = get_active()
            except Exception:
                logger.debug(
                    "Failed to inspect %s adapter processing tasks during shutdown",
                    getattr(adapter, "name", type(adapter).__name__),
                    exc_info=True,
                )
                continue
            for session_key, task in active.items():
                snapshot.append((adapter, session_key, task))
        return snapshot

    @staticmethod
    def _agent_has_active_subagents(running_agent: Any) -> bool:
        """Return True when *running_agent* is currently driving subagents
        via the ``delegate_task`` tool.

        Background (#30170): ``AIAgent.interrupt()`` cascades through the
        parent's ``_active_children`` list and calls ``interrupt()`` on
        every child synchronously, which aborts in-flight subagent work
        and produces a fallback cascade with no actionable signal.
        Demoting ``busy_input_mode='interrupt'`` to ``queue`` semantics
        whenever this helper returns True protects subagent work from
        conversational follow-ups while leaving the explicit ``/stop``
        path (which goes through ``_interrupt_and_clear_session``)
        untouched. Safe-by-default: returns False on any attribute or
        lock error so a missing/broken parent never blocks the existing
        interrupt path.
        """
        if running_agent is None or running_agent is _AGENT_PENDING_SENTINEL:
            return False
        children = getattr(running_agent, "_active_children", None)
        # AIAgent always initialises this as a concrete list (see
        # agent/agent_init.py). Reject anything that isn't a real
        # collection — this guards against ``MagicMock()._active_children``
        # auto-creating a truthy stub in tests and triggering the demotion
        # against an agent that doesn't actually have subagents.
        if not isinstance(children, (list, tuple, set)):
            return False
        if not children:
            return False
        lock = getattr(running_agent, "_active_children_lock", None)
        try:
            if lock is not None:
                with lock:
                    return bool(children)
            return bool(children)
        except Exception:
            return False

    def _queue_or_replace_pending_event(self, session_key: str, event: MessageEvent) -> bool:
        adapter = self._adapter_for_source(event.source)
        if not adapter:
            return False
        if self._queued_event_already_present(session_key, event, adapter):
            logger.info(
                "Suppressing duplicate queued replay for session %s identity=%s",
                session_key,
                self._queued_event_identity(event),
            )
            return False
        # Text follow-ups are distinct user turns. Keep photo/media bursts
        # mergeable, but otherwise append through the bounded FIFO used by
        # /queue so rapid messages cannot overwrite the single adapter slot.
        pending_slot = getattr(adapter, "_pending_messages", None)
        existing = pending_slot.get(session_key) if isinstance(pending_slot, dict) else None
        if existing is not None and (
            getattr(existing, "message_type", None) == MessageType.PHOTO
            or event.message_type == MessageType.PHOTO
            or bool(getattr(existing, "media_urls", None))
            or bool(getattr(event, "media_urls", None))
        ):
            merge_pending_message_event(
                adapter._pending_messages,
                session_key,
                event,
                merge_text=event.message_type == MessageType.TEXT,
            )
            return True

        if self._queue_depth(session_key, adapter=adapter) >= self._BUSY_QUEUE_MAX_PENDING:
            logger.warning(
                "Dropping busy-mode follow-up for session %s — pending queue at cap (%d).",
                session_key,
                self._BUSY_QUEUE_MAX_PENDING,
            )
            return False

        self._enqueue_fifo(session_key, event, adapter)
        return True

    def _start_user_followup_lock(self):
        """Return the lazy lock used by bare-runner-safe startup guidance."""
        lock = self.__dict__.get("_pending_start_user_followups_lock")
        if lock is None:
            lock = threading.Lock()
            self._pending_start_user_followups_lock = lock
        return lock

    def _open_start_user_followups(self, session_key: str, run_generation: int) -> None:
        """Open the same-turn follow-up window for one claimed run."""
        if not session_key:
            return
        with self._start_user_followup_lock():
            pending = self.__dict__.setdefault("_pending_start_user_followups", {})
            by_generation = pending.setdefault(session_key, {})
            by_generation[run_generation] = []

    def _discord_action_pr_generation(self, event: MessageEvent) -> Optional[int]:
        """Return an action event's durable PR generation, if applicable."""

        source = getattr(event, "source", None)
        if getattr(source, "platform", None) != Platform.DISCORD:
            return None
        if _discord_runtime_mode_for(event) is not RuntimeMode.ACTION:
            return None
        if getattr(event, "participates_in_work_lifecycle", True) is False:
            return None
        return self._ledger().normalize_discord_pr_generation(
            getattr(event, "discord_pr_generation", 1)
        )

    def _crosses_running_discord_pr_generation(
        self,
        session_key: str,
        event: MessageEvent,
    ) -> bool:
        """Return whether an action belongs to a different PR than the live turn."""

        event_generation = self._discord_action_pr_generation(event)
        active_runtime_mode = (
            self.__dict__.get("_running_discord_runtime_modes", {}) or {}
        ).get(session_key)
        active_generation = (
            self.__dict__.get("_running_discord_pr_generations", {}) or {}
        ).get(session_key)
        return (
            event_generation is not None
            and (
                (
                    active_runtime_mode is not None
                    and active_runtime_mode != RuntimeMode.ACTION.value
                )
                or (
                    active_generation is not None
                    and event_generation != active_generation
                )
            )
        )

    def _stage_start_user_followup(
        self,
        session_key: str,
        event: MessageEvent,
    ) -> bool:
        """Stage text for the claimed turn while it still has only a sentinel.

        Returning ``False`` means the same-turn window is closed or the payload
        needs the normal media/queue pipeline. Callers must then preserve the
        event through their existing fallback path rather than dropping it.
        """
        if (
            not session_key
            or event.message_type != MessageType.TEXT
            or bool(getattr(event, "media_urls", None))
            or self._crosses_running_discord_pr_generation(session_key, event)
        ):
            return False
        text = (event.text or "").strip()
        if not text:
            return False
        generation = int(
            (getattr(self, "_session_run_generation", None) or {}).get(
                session_key,
                0,
            )
        )
        if generation <= 0:
            return False
        with self._start_user_followup_lock():
            pending = self.__dict__.setdefault("_pending_start_user_followups", {})
            by_generation = pending.get(session_key)
            staged = by_generation.get(generation) if isinstance(by_generation, dict) else None
            if staged is None:
                return False
            if len(staged) >= self._BUSY_QUEUE_MAX_PENDING:
                return False
            if sum(len(item) for item in staged) + len(text) > 32_000:
                return False
            staged.append(text)
        logger.debug(
            "Folded busy follow-up into starting turn for session %s generation %s",
            session_key,
            generation,
        )
        return True

    def _consume_start_user_followups(
        self,
        session_key: str,
        run_generation: int,
    ) -> List[str]:
        """Atomically close and consume startup guidance for one run."""
        if not session_key:
            return []
        with self._start_user_followup_lock():
            pending = self.__dict__.setdefault("_pending_start_user_followups", {})
            by_generation = pending.get(session_key)
            if not isinstance(by_generation, dict):
                return []
            staged = by_generation.pop(run_generation, [])
            if not by_generation:
                pending.pop(session_key, None)
        return list(staged) if isinstance(staged, list) else []

    def _discard_start_user_followups(
        self,
        session_key: str,
        run_generation: Optional[int] = None,
    ) -> None:
        """Discard unconsumed startup guidance during turn teardown."""
        if not session_key:
            return
        with self._start_user_followup_lock():
            pending = self.__dict__.setdefault("_pending_start_user_followups", {})
            if run_generation is None:
                pending.pop(session_key, None)
                return
            by_generation = pending.get(session_key)
            if not isinstance(by_generation, dict):
                return
            by_generation.pop(run_generation, None)
            if not by_generation:
                pending.pop(session_key, None)

    @staticmethod
    def _fold_start_user_followups(message: str, followups: List[str]) -> str:
        """Keep startup follow-ups in the same user-role turn without uplift."""
        result = str(message or "").strip()
        for text in followups:
            block = (
                "[Additional message from the same user while this turn was starting]\n"
                f"{text}"
            )
            result = f"{result}\n\n{block}" if result else block
        return result

    def _ledger(self):
        ledger = getattr(self, "work_ledger", None)
        if ledger is None:
            from gateway.work_ledger import GatewayWorkLedger

            ledger = GatewayWorkLedger()
            self.work_ledger = ledger
        return ledger

    def _work_item_agent_run_active(self, item: Dict[str, Any]) -> bool:
        """Return whether the exact persisted turn still owns a live registry slot."""

        session_key = str(item.get("session_key") or "")
        active_run = item.get("active_run") if isinstance(item.get("active_run"), dict) else {}
        try:
            generation = int(active_run.get("generation") or 0)
        except (TypeError, ValueError):
            return False
        registry_active = bool(session_key and session_key in getattr(self, "_running_agents", {}))
        if not registry_active or not self._is_session_run_current(session_key, generation):
            return False
        return self._ledger().agent_run_active(
            item,
            session_key=session_key,
            run_generation=generation,
            process_epoch=str(getattr(self, "_process_epoch", "") or ""),
            registry_active=True,
        )

    def _persist_action_closeout_workspace(
        self,
        event: MessageEvent,
        *,
        mutable_path: str,
        canonical_path: str,
        config: dict[str, Any],
        source: str = "direct",
        mode: str = "off",
        policy: Optional[dict[str, Any]] = None,
    ) -> Optional[dict[str, Any]]:
        """Persist resolved mutable/canonical identity before model work starts."""

        work_id = str(getattr(event, "work_item_id", "") or "").strip()
        root_text = str(mutable_path or "").strip()
        if not work_id or not root_text:
            return None
        root = Path(root_text).expanduser().resolve(strict=False)
        feature_summary = getattr(event, "feature_summary", None)
        project_context = (
            feature_summary.get("project_context")
            if isinstance(feature_summary, dict)
            and isinstance(feature_summary.get("project_context"), dict)
            else {}
        )
        canonical_path = str(project_context.get("project_path") or canonical_path or "")
        repository = ""
        branch = ""
        try:
            from hermes_cli.github_remote import github_origin_repo

            repository = str(github_origin_repo(root) or "")
        except Exception:
            repository = ""
        try:
            import subprocess

            branch_result = subprocess.run(
                ["git", "branch", "--show-current"],
                cwd=root,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=10,
                check=False,
            )
            if branch_result.returncode == 0:
                branch = str(branch_result.stdout or "").strip()[:240]
        except Exception:
            branch = ""
        closeout_config = _closeout_mapping(config.get("closeout"))
        repo_config = _closeout_repository_config(closeout_config, repository)
        base_branch = str(repo_config.get("base_branch") or "main").strip() or "main"
        ledger = self._ledger()
        existing_item = ledger.get(work_id) or {}
        existing_state = existing_item.get("closeout") if isinstance(existing_item.get("closeout"), dict) else {}
        effective_mode = str(mode or "off").strip().lower()
        if str(existing_state.get("mode") or "off") != "off" and effective_mode == "off":
            effective_mode = str(existing_state.get("mode"))
        state = ledger.attach_closeout_workspace(
            work_id,
            workspace_path=str(root),
            canonical_path=str(canonical_path or ""),
            repository=repository,
            branch=branch,
            base_branch=base_branch,
            source=source,
            mode=effective_mode,
            policy=policy,
        )
        # Workspace attachment is not a lifecycle handoff. The watcher is
        # notified only after a trusted checkpoint atomically activates the
        # complete closeout state.
        return state

    def _activate_direct_closeout_after_checkpoint(
        self,
        work_item_id: str,
        agent_result: Dict[str, Any],
        *,
        visual_pending: bool = False,
    ) -> dict[str, Any] | None:
        """Extract genuine runtime evidence and activate its exact Git head."""

        if not work_item_id or not isinstance(agent_result, dict) or agent_result.get("failed"):
            return None

        runtime_breakdown = (
            agent_result.get("runtime_breakdown")
            if isinstance(agent_result.get("runtime_breakdown"), dict)
            else {}
        )
        trusted_evidence: dict[str, Any] | None = None
        try:
            from agent.verification_evidence import (
                evidence_from_runtime_breakdown,
                latest_evidence_by_surface,
            )

            latest = latest_evidence_by_surface(
                evidence_from_runtime_breakdown(runtime_breakdown)
            )
            final_mutation_generation = int(runtime_breakdown.get("mutation_generation") or 0)
            final_mutation_boundary = int(runtime_breakdown.get("mutation_boundary") or 0)
            for surface in ("verification", "ci"):
                candidate = latest.get(surface)
                if not isinstance(candidate, dict) or str(candidate.get("status") or "") != "success":
                    continue
                canonical_command = str(candidate.get("canonical_command") or "").strip()
                scope = str(candidate.get("scope") or "").strip()
                repository_root = str(candidate.get("repository_root") or "").strip()
                verified_head_sha = str(candidate.get("verified_head_sha") or "").strip().lower()
                if (
                    canonical_command
                    and scope in {"full", "targeted"}
                    and repository_root
                    and "mutation_generation" in runtime_breakdown
                    and "mutation_boundary" in runtime_breakdown
                    and "mutation_generation" in candidate
                    and "mutation_boundary" in candidate
                    and int(candidate.get("mutation_generation") or 0) == final_mutation_generation
                    and int(candidate.get("mutation_boundary") or 0) == final_mutation_boundary
                    and re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", verified_head_sha)
                ):
                    trusted_evidence = candidate
                    break
        except Exception:
            trusted_evidence = None
        if trusted_evidence is None:
            return None
        return self._activate_closeout_at_verified_head(
            work_item_id,
            repository_root=str(trusted_evidence.get("repository_root") or ""),
            verified_head_sha=str(
                trusted_evidence.get("verified_head_sha") or ""
            ),
            visual_result=(
                agent_result.get("visual_qa")
                if isinstance(agent_result.get("visual_qa"), dict)
                else None
            ),
            visual_pending=visual_pending,
        )

    def _activate_closeout_at_verified_head(
        self,
        work_item_id: str,
        *,
        repository_root: str,
        verified_head_sha: str,
        visual_result: Optional[dict[str, Any]] = None,
        visual_pending: bool = False,
    ) -> dict[str, Any] | None:
        """Activate or advance closeout at one clean exact host checkpoint."""

        repository_root = str(repository_root or "").strip()
        verified_head_sha = str(verified_head_sha or "").strip().lower()
        if (
            not work_item_id
            or not repository_root
            or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", verified_head_sha)
        ):
            return None
        ledger = self._ledger()
        item = ledger.get(work_item_id)
        if (
            not isinstance(item, dict)
            or not isinstance(item.get("closeout"), dict)
        ):
            return None
        required_reader = getattr(ledger, "required_async_completion_state", None)
        required_state = (
            required_reader(work_item_id) if callable(required_reader) else None
        )
        if (
            isinstance(required_state, dict)
            and required_state.get("attempt_cancelled") is True
        ):
            return None
        from hermes_cli.trusted_closeout import normalize_closeout_state

        state = normalize_closeout_state(item["closeout"])
        if state["mode"] == "off" or state["source"] not in {"direct", "fable", "opus"}:
            return None

        def notify_closeout() -> None:
            try:
                from gateway.trusted_closeout_watcher import mark_closeout_dirty

                mark_closeout_dirty(work_item_id)
            except Exception:
                pass
            watcher = getattr(self, "trusted_closeout_watcher", None)
            if watcher is not None:
                watcher.notify(work_item_id)

        already_activated = bool(
            item.get("closeout_authoritative") is True
            or item.get("closeout_activated_at") is not None
        )

        root_text = str(state["workspace"].get("path") or "").strip()
        root = Path(root_text).expanduser().resolve(strict=False) if root_text else Path()
        if not root_text or not root.is_dir():
            return None
        evidence_root = Path(repository_root).expanduser().resolve(strict=False)
        try:
            root.relative_to(evidence_root)
        except ValueError:
            return None
        try:
            import subprocess

            toplevel_result = subprocess.run(
                ["git", "rev-parse", "--show-toplevel"],
                cwd=root,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            checked = subprocess.run(
                ["git", "diff", "--check"],
                cwd=root,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            status = subprocess.run(
                ["git", "status", "--porcelain"],
                cwd=root,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            head_result = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                cwd=root,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
        except Exception:
            return None
        current_head_sha = str(head_result.stdout or "").strip().lower()
        git_toplevel = (
            Path(str(toplevel_result.stdout or "").strip())
            .expanduser()
            .resolve(strict=False)
        )
        if (
            toplevel_result.returncode != 0
            or evidence_root != git_toplevel
            or checked.returncode != 0
            or status.returncode != 0
            or bool(str(status.stdout or "").strip())
            or head_result.returncode != 0
            or current_head_sha != verified_head_sha
        ):
            return None

        if already_activated:
            active_head_sha = str(state["pr"].get("head_sha") or "").strip().lower()
            if active_head_sha != verified_head_sha:
                advanced = ledger.publish_closeout_verified_head(
                    work_item_id,
                    expected_head_sha=active_head_sha,
                    verified_head_sha=verified_head_sha,
                )
                if advanced is None:
                    return None
                state = advanced
                notify_closeout()
            if not state["policy"]["require_visual_qa"] or visual_pending:
                return state
            visual_result = visual_result if isinstance(visual_result, dict) else {}
            applied = ledger.apply_closeout_visual_completion(
                work_item_id,
                expected_head_sha=verified_head_sha,
                receipts=visual_result.get("receipts"),
                min_receipt_order=int(visual_result.get("min_receipt_order") or 0),
            )
            if applied is not None:
                notify_closeout()
            return applied

        state["status"] = "pending"
        state["local_verification"] = {"status": "passed", "head_sha": verified_head_sha}
        state["pr"]["head_sha"] = verified_head_sha
        state["ci"]["head_sha"] = verified_head_sha
        if state["policy"]["require_visual_qa"]:
            completion = {"status": "pending"}
            if not visual_pending:
                try:
                    from agent.visual_qa import visual_receipt_completion

                    visual_result = (
                        visual_result if isinstance(visual_result, dict) else {}
                    )
                    completion = visual_receipt_completion(
                        item.get("visual_qa_requirement"),
                        visual_result.get("receipts"),
                        min_order=int(visual_result.get("min_receipt_order") or 0),
                    )
                except Exception:
                    completion = {"status": "missing"}
            state["visual_qa"] = {
                "status": str(completion.get("status") or "missing"),
                "head_sha": verified_head_sha,
            }
        activated = ledger.activate_closeout(
            work_item_id,
            state,
            expected_revision=int(state.get("revision") or 0),
        )
        if activated is None:
            latest = ledger.get(work_item_id)
            if not isinstance(latest, dict) or not isinstance(latest.get("closeout"), dict):
                return None
            latest_state = normalize_closeout_state(latest["closeout"])
            if (
                latest.get("closeout_authoritative") is not True
                and latest.get("closeout_activated_at") is None
            ):
                return None
            if visual_pending or not latest_state["policy"]["require_visual_qa"]:
                return latest_state
            visual_result = visual_result if isinstance(visual_result, dict) else {}
            activated = ledger.apply_closeout_visual_completion(
                work_item_id,
                expected_head_sha=verified_head_sha,
                receipts=visual_result.get("receipts"),
                min_receipt_order=int(visual_result.get("min_receipt_order") or 0),
            )
            if activated is None:
                return None
        notify_closeout()
        return activated

    def _accept_discord_work_item(
        self,
        event: MessageEvent,
        session_key: str,
        *,
        defer_completion: bool = False,
    ) -> Optional[dict]:
        if getattr(event, "internal", False):
            return None
        if getattr(event.source, "platform", None) != Platform.DISCORD:
            return None
        # A slash command that arrives while this session is already running
        # is handled immediately by the busy-command path (usually with a
        # "wait or /stop" response). It never launches an agent turn, so
        # accepting it into the durable work ledger would leave an orphaned
        # claimed item that startup recovery later replays as duplicate work.
        if (
            getattr(event, "message_type", None) is MessageType.COMMAND
            and session_key in getattr(self, "_running_agents", {})
        ):
            return None
        if _discord_runtime_mode_for(event) is not RuntimeMode.ACTION:
            return None
        if not getattr(event, "participates_in_work_lifecycle", True):
            return None
        ledger = self._ledger()
        gateway_config = _load_gateway_config()
        repository = _gateway_repository_for_source(getattr(event, "source", None))
        _, visual_qa_config = _normalize_gateway_visual_qa_contract(
            None,
            _repository_visual_qa_config(gateway_config, repository),
        )
        item = ledger.accept_event(
            event,
            session_key=session_key,
            freshness_seconds=_auto_continue_freshness_window(),
            visual_qa_config=visual_qa_config,
        )
        if not item:
            return None
        promoted = ledger.promote_visual_qa_config(
            str(item.get("id") or ""),
            visual_qa_config,
            expected_run_state=item,
        )
        if promoted is not None:
            item = promoted
        event.work_item_id = item.get("id")
        event.defer_work_completion = defer_completion
        event.discord_pr_generation = ledger.normalize_discord_pr_generation(
            item.get("discord_pr_generation")
        )
        event.discord_pr_rollover = bool(item.get("discord_pr_rollover", False))
        event.visual_qa_requirement, event.visual_qa_config = _normalize_gateway_visual_qa_contract(
            item.get("visual_qa_requirement"),
            item.get("visual_qa_config"),
        )
        status = str(item.get("status") or "")
        if status in {"completed", "blocked", "cancelled", "expired"}:
            return item
        if not getattr(event, "work_replay", False):
            ledger.claim(str(item["id"]))
        return item

    def _record_discord_work_for_drain(
        self,
        event: MessageEvent,
        session_key: str,
    ) -> Optional[dict]:
        if getattr(event, "internal", False):
            return None
        if getattr(getattr(event, "source", None), "platform", None) != Platform.DISCORD:
            return None
        runtime_mode = _discord_runtime_mode_for(event)
        event.discord_runtime_mode = runtime_mode.value
        if runtime_mode is RuntimeMode.READ_ONLY:
            event.participates_in_work_lifecycle = False
        ledger = self._ledger()
        item = ledger.accept_event(
            event,
            session_key=session_key,
            freshness_seconds=_auto_continue_freshness_window(),
            drain_recovery=True,
        )
        if item and item.get("id"):
            event.work_item_id = item.get("id")
            event.defer_work_completion = True
            event.discord_pr_generation = ledger.normalize_discord_pr_generation(
                item.get("discord_pr_generation")
            )
            event.discord_pr_rollover = bool(item.get("discord_pr_rollover", False))
            ledger.claim(str(item["id"]))
        return item

    def _try_steer_busy_event(
        self,
        event: MessageEvent,
        session_key: str,
        *,
        running_agent=None,
    ) -> str:
        """Try one live steer, otherwise queue the original event once.

        Returns ``accepted`` when the current Hermes turn owns the text,
        ``closed`` when the model turn ended but delivery cleanup still owns
        the session, ``queued`` when a live agent otherwise rejected/failed the
        steer, and ``unsupported`` when no steer-capable agent exists yet. All
        fallback outcomes have already queued ``event`` unchanged for the next
        turn.
        """
        if running_agent is None:
            running_agent = self._running_agents.get(session_key)
        text = (event.text or "").strip()
        if self._crosses_running_discord_pr_generation(session_key, event):
            self._queue_or_replace_pending_event(session_key, event)
            return "unsupported"
        if running_agent is _AGENT_PENDING_SENTINEL:
            if self._stage_start_user_followup(session_key, event):
                return "accepted"
            self._queue_or_replace_pending_event(session_key, event)
            return "unsupported"
        if running_agent is None or not hasattr(running_agent, "steer") or not text:
            self._queue_or_replace_pending_event(session_key, event)
            return "unsupported"
        try:
            accepted = bool(running_agent.steer(text))
        except Exception as exc:
            logger.warning("Gateway steer failed for session %s: %s", session_key, exc)
            accepted = False
        if accepted:
            return "accepted"
        steer_state = getattr(running_agent, "steer_state", None)
        if callable(steer_state):
            try:
                rejection = str(steer_state() or "").strip().lower()
            except Exception:
                rejection = ""
            if rejection in {"closed", "unsupported"}:
                self._queue_or_replace_pending_event(session_key, event)
                return rejection
        self._queue_or_replace_pending_event(session_key, event)
        return "queued"

    def _busy_steer_ack_enabled_for_event(self, event: MessageEvent) -> bool:
        from gateway.display_config import resolve_display_setting

        override = os.environ.get("HERMES_GATEWAY_BUSY_STEER_ACK_ENABLED")
        if override is not None:
            return override.strip().lower() in {"1", "true", "yes", "on"}
        return bool(
            resolve_display_setting(
                _load_gateway_config(),
                _platform_config_key(event.source.platform),
                "busy_steer_ack_enabled",
                True,
            )
        )

    def _should_send_busy_steer_ack(self, session_key: str) -> bool:
        """Show the first accepted steer per run, then rate-limit repeats."""
        now = time.time()
        generations = self.__dict__.get("_session_run_generation") or {}
        generation = int(generations.get(session_key, 0))
        seen = self.__dict__.setdefault("_busy_steer_ack_generation", {})
        ack_ts = self.__dict__.setdefault("_busy_steer_ack_ts", {})
        if seen.get(session_key) != generation:
            seen[session_key] = generation
            ack_ts[session_key] = now
            return True
        if now - float(ack_ts.get(session_key, 0)) < 30:
            return False
        ack_ts[session_key] = now
        return True

    async def _rollback_unused_discord_feature_summary(self, event: MessageEvent) -> None:
        """Remove a summary created for input consumed by the active turn."""
        if not getattr(event, "_discord_promotion_created_feature_summary", False):
            return
        adapter = self._adapter_for_source(event.source)
        rollback = getattr(adapter, "rollback_promoted_action_request", None)
        if not callable(rollback):
            return
        try:
            result = rollback(event)
            if inspect.isawaitable(result):
                await result
        except Exception:
            logger.debug(
                "Failed to roll back unused Discord feature summary",
                exc_info=True,
            )

    def _mark_discord_work_consumed(self, event: MessageEvent, *, reason: str) -> None:
        """Prevent active-turn input from replaying as independent work."""
        work_item_id = str(getattr(event, "work_item_id", None) or "").strip()
        if not work_item_id:
            return
        try:
            self._ledger().mark_consumed(work_item_id, reason=reason)
        except Exception:
            logger.debug(
                "Failed to terminalize consumed Discord work item %s",
                work_item_id,
                exc_info=True,
            )

    async def _handle_active_session_busy_message(self, event: MessageEvent, session_key: str) -> bool:
        # --- Authorization gate (#17775) ---
        # The cold path (_handle_message) checks _is_user_authorized before
        # creating a session.  The busy path must enforce the same check;
        # otherwise unauthorized users in shared threads (Slack/Telegram/Discord)
        # can inject messages into an active session they don't own.
        if not self._is_user_authorized(event.source):
            logger.warning(
                "Dropping message from unauthorized user in active session: "
                "user=%s (%s), platform=%s, session=%s",
                event.source.user_id,
                event.source.user_name,
                event.source.platform.value if event.source.platform else "unknown",
                session_key,
            )
            return True  # handled (silently dropped); do not fall through

        # Completion events are fresh internal turns, never steering input.
        # Keep them in the FIFO overflow instead of the adapter's mergeable
        # pending slot so a simultaneously queued user message cannot be folded
        # into the trusted completion prompt.
        if getattr(event, "internal", False):
            self._enqueue_internal_completion(session_key, event)
            return True

        # --- Draining case (gateway restarting/stopping) ---
        if self._draining:
            adapter = self._adapter_for_source(event.source)
            if not adapter:
                return True

            reply_anchor = self._reply_anchor_for_event(event)
            thread_meta = self._thread_metadata_for_source(event.source, reply_anchor)
            if self._queue_during_drain_enabled():
                self._record_discord_work_for_drain(event, session_key)
                self._queue_or_replace_pending_event(session_key, event)
                message = f"⏳ Gateway {self._status_action_gerund()} — queued for the next turn after it comes back."
            else:
                message = f"⏳ Gateway is {self._status_action_gerund()} and is not accepting another turn right now."

            if getattr(event, "work_replay", False):
                logger.info(
                    "Suppressing busy acknowledgement for Discord work replay %s during drain",
                    getattr(event, "work_item_id", "") or getattr(event, "message_id", ""),
                )
                return True

            await adapter._send_with_retry(
                chat_id=event.source.chat_id,
                content=message,
                reply_to=(
                    reply_anchor
                    if event.source.platform == Platform.TELEGRAM
                    and event.source.chat_type == "dm"
                    and event.source.thread_id
                    else (None if event.source.platform == Platform.TELEGRAM and event.source.thread_id else event.message_id)
                ),
                metadata=thread_meta,
            )
            return True

        # A bare approval answer must resolve the blocked command immediately,
        # not enter the normal steer/queue/interrupt path (which deadlocks
        # behind the approval wait). Slash forms are already routed through
        # the canonical command path; this bridge is only active while an
        # approval is actually pending for this exact session.
        original_text = event.text
        try:
            from tools.approval import has_blocking_approval

            if has_blocking_approval(session_key):
                raw_text = (event.text or "").strip().lower()
                approve_words = {"approve", "yes", "ok", "okay", "confirm", "y", "👍"}
                deny_words = {"deny", "no", "reject", "cancel", "n", "👎"}
                approval_verb = None
                normalized_args = ""
                if raw_text in approve_words:
                    approval_verb = "approve"
                elif raw_text in deny_words:
                    approval_verb = "deny"
                elif raw_text in {"always", "approve always", "always approve"}:
                    approval_verb = "approve"
                    normalized_args = "always"
                elif raw_text in {"session", "approve session", "session approve"}:
                    approval_verb = "approve"
                    normalized_args = "session"

                if approval_verb is not None:
                    event.text = f"/{approval_verb}"
                    if normalized_args:
                        event.text = f"{event.text} {normalized_args}"
                    handler = (
                        self._handle_approve_command
                        if approval_verb == "approve"
                        else self._handle_deny_command
                    )
                    reply = await handler(event)
                    logger.info(
                        "Approval response via plain text: session=%s verb=%s args=%r",
                        session_key,
                        approval_verb,
                        normalized_args,
                    )
                    approval_adapter = self._adapter_for_source(event.source)
                    if approval_adapter and reply:
                        text, ephemeral_ttl = approval_adapter._unwrap_ephemeral(reply)
                        if text:
                            anchor = self._reply_anchor_for_event(event)
                            result = await approval_adapter._send_with_retry(
                                chat_id=event.source.chat_id,
                                content=text,
                                reply_to=anchor,
                                metadata=self._thread_metadata_for_source(event.source, anchor),
                            )
                            if (
                                ephemeral_ttl > 0
                                and getattr(result, "success", False)
                                and getattr(result, "message_id", None)
                            ):
                                self._schedule_ephemeral_delete(
                                    chat_id=event.source.chat_id,
                                    message_id=result.message_id,
                                    ttl_seconds=ephemeral_ttl,
                                )
                    return True
        except Exception:
            event.text = original_text
            logger.warning(
                "Plain-text approval routing failed for session %s; "
                "falling through to busy handling",
                session_key,
                exc_info=True,
            )

        # Normal busy case (agent actively running a task)
        adapter = self._adapter_for_source(event.source)
        if not adapter:
            return False  # let default path handle it

        running_agent = self._running_agents.get(session_key)

        if self._crosses_running_discord_pr_generation(session_key, event):
            self._queue_or_replace_pending_event(session_key, event)
            logger.info(
                "Queued Discord PR-generation rollover for session %s until the active PR turn finishes",
                session_key,
            )
            return True

        effective_mode = self._busy_input_mode
        busy_text_mode = getattr(self, "_busy_text_mode", "interrupt")
        if (
            event.message_type == MessageType.TEXT
            and busy_text_mode == "queue"
            and effective_mode == "interrupt"
        ):
            return False

        # Steer mode: inject mid-run via running_agent.steer() instead of
        # queueing + interrupting. While the claimed turn still owns only the
        # startup sentinel, stage plain text for that same turn; unsupported,
        # closed, empty, and media payloads retain the queue fallback.
        # #30170 — Subagent protection. ``AIAgent.interrupt()`` cascades
        # to every entry in the parent's ``_active_children`` list and
        # aborts in-flight ``delegate_task`` work. Demote ``interrupt``
        # to ``queue`` when the parent is currently driving subagents so
        # a conversational follow-up doesn't destroy minutes of subagent
        # work. Explicit ``/stop`` and ``/new`` slash commands go through
        # ``_interrupt_and_clear_session`` and are unaffected — the
        # operator still has a way to force-cancel everything.
        demoted_for_subagents = (
            effective_mode == "interrupt"
            and self._agent_has_active_subagents(running_agent)
        )
        if demoted_for_subagents:
            logger.info(
                "Demoting busy_input_mode 'interrupt' to 'queue' for session %s "
                "because the running agent has active subagents (#30170)",
                session_key,
            )
            effective_mode = "queue"
        demoted_for_compression = (
            effective_mode == "interrupt"
            and running_agent is not _AGENT_PENDING_SENTINEL
            and await self._session_has_compression_in_flight(session_key)
        )
        if demoted_for_compression:
            logger.info(
                "Demoting busy_input_mode 'interrupt' to 'queue' for session %s "
                "because context compression is in flight (#56391)",
                session_key,
            )
            effective_mode = "queue"
        steer_outcome = None
        start_followup_accepted = False
        if (
            effective_mode == "interrupt"
            and running_agent is _AGENT_PENDING_SENTINEL
        ):
            start_followup_accepted = self._stage_start_user_followup(
                session_key,
                event,
            )
            if start_followup_accepted:
                self._mark_discord_work_consumed(
                    event,
                    reason="startup_followup",
                )
                await self._rollback_unused_discord_feature_summary(event)
        if effective_mode == "steer":
            steer_outcome = self._try_steer_busy_event(
                event,
                session_key,
                running_agent=running_agent,
            )
            if steer_outcome != "accepted":
                effective_mode = "queue"
            else:
                self._mark_discord_work_consumed(event, reason="accepted_steer")
                await self._rollback_unused_discord_feature_summary(event)

        # Store the message so it's processed as the next turn after the
        # current run finishes (or is interrupted).  Skip this for a
        # successful steer — the text already landed inside the run and
        # must NOT also be replayed as a next-turn user message.
        if steer_outcome is None and not start_followup_accepted:
            self._queue_or_replace_pending_event(session_key, event)

        is_queue_mode = effective_mode == "queue"
        is_steer_mode = effective_mode == "steer"
        is_closed_steer_fallback = steer_outcome == "closed"
        is_steer_fallback = steer_outcome in {"queued", "unsupported"}

        # If not in queue/steer mode, interrupt the running agent immediately.
        # This aborts in-flight tool calls and causes the agent loop to exit
        # at the next check point.
        if effective_mode == "interrupt" and running_agent and running_agent is not _AGENT_PENDING_SENTINEL:
            try:
                interrupt_text = event.text
                media_urls = getattr(event, "media_urls", None) or []
                if self._pending_event_audio_paths(event):
                    interrupt_text, _ = await self._transcribe_and_echo_pending_voice(
                        event,
                        adapter,
                        event.source,
                        event.text or "",
                        log_context="Voice-busy-interrupt",
                    )
                elif not interrupt_text and media_urls:
                    interrupt_text = _build_media_placeholder(event)
                running_agent.interrupt(interrupt_text)
            except Exception:
                pass  # don't let interrupt failure block input handling

        # Interrupt-mode follow-ups either joined the startup turn or were
        # queued above as replacement input. A separate confirmation bubble
        # adds noise, so keep this mode silent. Queue and steer retain their
        # configurable status acknowledgements.
        if effective_mode == "interrupt":
            logger.debug("Busy interrupt ack suppressed for session %s", session_key)
            return True

        if getattr(event, "work_replay", False):
            logger.info(
                "Suppressing busy acknowledgement for Discord work replay %s",
                getattr(event, "work_item_id", "") or getattr(event, "message_id", ""),
            )
            return True

        # Check if busy ack is disabled — skip sending but still process the input.
        # Placed before debounce so we don't stamp a "last ack" timestamp that was
        # never actually delivered.
        busy_ack_enabled = os.environ.get("HERMES_GATEWAY_BUSY_ACK_ENABLED", "true").lower() == "true"
        if not busy_ack_enabled:
            logger.debug("Busy ack suppressed for session %s", session_key)
            return True  # input still processed, just no ack sent

        # Debounce generic busy acknowledgements once every 30 seconds.  Steer
        # acknowledgements use a separate per-run limiter below so the first
        # accepted steer is never hidden by an earlier queue/interrupt ack.
        _BUSY_ACK_COOLDOWN = 30
        now = time.time()

        from gateway.display_config import resolve_display_setting
        platform_key = _platform_config_key(event.source.platform)

        # Steering already changed the live run. Allow operators to suppress
        # only the confirmation bubble without disabling steer itself.
        if is_steer_mode:
            if not self._should_send_busy_steer_ack(session_key):
                return True
            if not self._busy_steer_ack_enabled_for_event(event):
                logger.debug("Busy steer ack suppressed for session %s", session_key)
                return True
        else:
            last_ack = self._busy_ack_ts.get(session_key, 0)
            if now - last_ack < _BUSY_ACK_COOLDOWN:
                return True

        self._busy_ack_ts[session_key] = now

        # Build a status-rich acknowledgment. Mobile chat defaults keep this
        # terse; detailed iteration/tool state is still available in logs and
        # can be opted in per platform via display.platforms.<platform>.busy_ack_detail.
        status_parts = []
        busy_ack_detail_enabled = bool(
            resolve_display_setting(
                _load_gateway_config(),
                platform_key,
                "busy_ack_detail",
                True,
            )
        )

        if busy_ack_detail_enabled and running_agent and running_agent is not _AGENT_PENDING_SENTINEL:
            try:
                summary = running_agent.get_activity_summary()
                iteration = summary.get("api_call_count", 0)
                max_iter = summary.get("max_iterations", 0)
                current_tool = summary.get("current_tool")
                start_ts = self._running_agents_ts.get(session_key, 0)
                if start_ts:
                    elapsed_min = int((now - start_ts) / 60)
                    if elapsed_min > 0:
                        status_parts.append(f"{elapsed_min} min elapsed")
                if max_iter:
                    status_parts.append(f"iteration {iteration}/{max_iter}")
                if current_tool:
                    status_parts.append(f"running: {current_tool}")
            except Exception:
                pass

        status_detail = f" ({', '.join(status_parts)})" if status_parts else ""
        if is_steer_mode:
            message = (
                f"⏩ Steered into current run{status_detail}. "
                f"It will apply at the next safe boundary."
            )
        elif is_queue_mode and demoted_for_subagents:
            # #30170 — explain the demotion so the user knows their
            # follow-up didn't accidentally kill the subagent and
            # discovers `/stop` as the explicit escape hatch.
            message = (
                f"⏳ Subagent working{status_detail} — your message is queued for "
                f"when it finishes (use /stop to cancel everything)."
            )
        elif is_queue_mode and demoted_for_compression:
            message = (
                f"⏳ Compressing context{status_detail} — your message is queued for "
                f"when it finishes (use /stop to cancel everything)."
            )
        elif is_closed_steer_fallback:
            message = (
                "⏳ Finishing delivery of the previous response — "
                "starting this as the next turn."
            )
        elif is_steer_fallback:
            message = (
                f"⏳ Queued for the immediate next turn{status_detail}. "
                f"The current run could not accept live steering."
            )
        elif is_queue_mode:
            message = (
                f"⏳ Queued for the next turn{status_detail}. "
                f"I'll respond once the current task finishes."
            )
        else:
            message = (
                f"⚡ Interrupting current task{status_detail}. "
                f"I'll respond to your message shortly."
            )

        # First-touch onboarding: the very first time a user sends a message
        # while the agent is busy, append a one-time hint explaining the
        # queue/interrupt knob.  Flag is persisted to config.yaml so it never
        # fires again on this install.
        try:
            from agent.onboarding import (
                BUSY_INPUT_FLAG,
                busy_input_hint_gateway,
                is_seen,
                mark_seen,
            )
            _user_cfg = _load_gateway_config()
            if not is_seen(_user_cfg, BUSY_INPUT_FLAG):
                if is_steer_mode:
                    _hint_mode = "steer"
                elif is_queue_mode:
                    _hint_mode = "queue"
                else:
                    _hint_mode = "interrupt"
                message = (
                    f"{message}\n\n"
                    f"{busy_input_hint_gateway(_hint_mode)}"
                )
                mark_seen(_hermes_home / "config.yaml", BUSY_INPUT_FLAG)
        except Exception as _onb_err:
            logger.debug("Failed to apply busy-input onboarding hint: %s", _onb_err)

        reply_anchor = self._reply_anchor_for_event(event)
        thread_meta = self._thread_metadata_for_source(event.source, reply_anchor)
        try:
            await adapter._send_with_retry(
                chat_id=event.source.chat_id,
                content=message,
                reply_to=(
                    reply_anchor
                    if event.source.platform == Platform.TELEGRAM
                    and event.source.chat_type == "dm"
                    and event.source.thread_id
                    else (None if event.source.platform == Platform.TELEGRAM and event.source.thread_id else event.message_id)
                ),
                metadata=thread_meta,
            )
        except Exception as e:
            logger.debug("Failed to send busy-ack: %s", e)

        return True

    async def _drain_active_agents(self, timeout: float) -> tuple[Dict[str, Any], bool]:
        snapshot = self._snapshot_running_agents()
        last_active_count = self._running_agent_count()
        last_cron_count = self._active_cron_job_count()
        last_api_count = self._active_api_run_count()
        last_coding_worker_count = self._active_coding_worker_count()
        last_adapter_count = len(self._snapshot_adapter_processing_tasks())
        last_status_at = 0.0

        def _maybe_update_status(force: bool = False) -> None:
            nonlocal last_active_count, last_cron_count, last_api_count, last_coding_worker_count, last_adapter_count, last_status_at
            now = asyncio.get_running_loop().time()
            active_count = self._running_agent_count()
            cron_count = self._active_cron_job_count()
            api_count = self._active_api_run_count()
            coding_worker_count = self._active_coding_worker_count()
            adapter_count = len(self._snapshot_adapter_processing_tasks())
            if (
                force
                or active_count != last_active_count
                or cron_count != last_cron_count
                or api_count != last_api_count
                or coding_worker_count != last_coding_worker_count
                or adapter_count != last_adapter_count
                or (now - last_status_at) >= 1.0
            ):
                self._update_runtime_status("draining")
                last_active_count = active_count
                last_cron_count = cron_count
                last_api_count = api_count
                last_coding_worker_count = coding_worker_count
                last_adapter_count = adapter_count
                last_status_at = now

        if (
            not self._running_agents
            and last_cron_count == 0
            and last_api_count == 0
            and last_coding_worker_count == 0
            and last_adapter_count == 0
        ):
            _maybe_update_status(force=True)
            return snapshot, False

        _maybe_update_status(force=True)
        loop = asyncio.get_running_loop()
        primary_deadline = loop.time() + max(float(timeout), 0.0)
        delivery_deadline: Optional[float] = None
        timed_out = False

        while True:
            non_delivery_active = bool(
                self._running_agents
                or self._active_cron_job_count()
                or self._active_api_run_count()
                or self._active_coding_worker_count()
            )
            adapter_count = len(self._snapshot_adapter_processing_tasks())
            if not non_delivery_active and adapter_count == 0:
                break

            now = loop.time()
            if non_delivery_active:
                if now >= primary_deadline:
                    timed_out = True
                    break
                current_deadline = primary_deadline
            else:
                if delivery_deadline is None:
                    try:
                        grace = max(float(self._shutdown_delivery_grace_seconds), 0.0)
                    except (TypeError, ValueError):
                        grace = _SHUTDOWN_DELIVERY_GRACE_SECS_DEFAULT
                    delivery_deadline = now + grace
                    logger.info(
                        "Gateway model work drained; waiting up to %.1fs for %d "
                        "adapter delivery task(s)",
                        grace,
                        adapter_count,
                    )
                if now >= delivery_deadline:
                    timed_out = True
                    break
                current_deadline = delivery_deadline

            _maybe_update_status()
            await asyncio.sleep(min(0.1, max(current_deadline - now, 0.0)))
        _maybe_update_status(force=True)
        return snapshot, timed_out

    def _interrupt_running_agents(self, reason: str) -> None:
        for session_key, agent in list(self._running_agents.items()):
            if agent is _AGENT_PENDING_SENTINEL:
                continue
            try:
                agent.interrupt(reason)
                logger.debug("Interrupted running agent for session %s during shutdown", session_key)
            except Exception as e:
                logger.debug("Failed interrupting agent during shutdown: %s", e)

    async def _notify_active_sessions_of_shutdown(self) -> None:
        """Send shutdown/restart notifications to active chats and home channels.

        Called at the very start of stop() — adapters are still connected so
        messages can be delivered. Best-effort: individual send failures are
        logged and swallowed so they never block the shutdown sequence.
        """
        active = self._snapshot_running_agents()
        restart_source = (
            self._restart_command_source if self._restart_requested else None
        )

        action = "restarting" if self._restart_requested else "shutting down"
        hint = (
            "Your current task will be interrupted. "
            "Hermes will automatically resume it after restart. If automatic "
            "recovery does not proceed, send a message to continue."
            if self._restart_requested
            else "Your current task will be interrupted."
        )
        msg = f"⚠️ Gateway {action} — {hint}"

        notified: set[tuple[str, str, Optional[str]]] = set()
        for session_key in active:
            source = None
            try:
                if getattr(self, "session_store", None) is not None:
                    await self.async_session_store._ensure_loaded()
                    entry = self.session_store._entries.get(session_key)
                    source = getattr(entry, "origin", None) if entry else None
            except Exception as e:
                logger.debug(
                    "Failed to load session origin for shutdown notification %s: %s",
                    session_key,
                    e,
                )

            if source is None:
                source = self._get_cached_session_source(session_key)

            if source is not None:
                platform_str = source.platform.value
                chat_id = str(source.chat_id)
                thread_id = source.thread_id
            else:
                parsed = _parse_session_key(session_key)
                if not parsed:
                    continue
                platform_str = parsed["platform"]
                chat_id = parsed["chat_id"]
                thread_id = parsed.get("thread_id")

            dedup_key = (
                platform_str,
                chat_id,
                str(thread_id) if thread_id else None,
            )
            if dedup_key in notified:
                continue

            try:
                platform = Platform(platform_str)
                adapter = (
                    self._adapter_for_source(source)
                    if source is not None
                    else self.adapters.get(platform)
                )
                if not adapter:
                    continue

                platform_cfg = self.config.platforms.get(platform)
                if (
                    platform_cfg is not None
                    and not platform_cfg.gateway_restart_notification
                ):
                    logger.info(
                        "Shutdown notification suppressed for active session: "
                        "%s has gateway_restart_notification=false",
                        platform_str,
                    )
                    continue

                reply_to_message_id = (
                    getattr(source, "message_id", None)
                    if source is not None
                    else None
                )
                if reply_to_message_id is None and restart_source is not None:
                    try:
                        restart_target = (
                            restart_source.platform.value,
                            str(restart_source.chat_id),
                            str(restart_source.thread_id)
                            if restart_source.thread_id
                            else None,
                        )
                        if restart_target == dedup_key:
                            reply_to_message_id = getattr(
                                restart_source, "message_id", None
                            )
                    except Exception:
                        pass

                metadata = self._thread_metadata_for_target(
                    platform,
                    chat_id,
                    thread_id,
                    chat_type=(
                        getattr(source, "chat_type", None)
                        if source is not None
                        else None
                    ),
                    reply_to_message_id=reply_to_message_id,
                    adapter=adapter,
                )
                result = await adapter.send(chat_id, msg, metadata=metadata)
                if result is not None and getattr(result, "success", True) is False:
                    logger.debug(
                        "Failed to send shutdown notification to %s:%s: %s",
                        platform_str,
                        chat_id,
                        getattr(result, "error", "send returned success=False"),
                    )
                    continue

                notified.add(dedup_key)
                logger.info(
                    "Sent shutdown notification to active chat %s:%s",
                    platform_str,
                    chat_id,
                )
            except Exception as e:
                logger.debug(
                    "Failed to send shutdown notification to %s:%s: %s",
                    platform_str,
                    chat_id,
                    e,
                )

        if self._restart_requested and restart_source is not None:
            logger.debug(
                "Skipping home-channel shutdown notifications for in-chat restart"
            )
            return

        try:
            from gateway.drain_control import drain_notification_suppressed

            if drain_notification_suppressed():
                logger.info(
                    "Home-channel shutdown broadcast suppressed by drain marker "
                    "(suppress_notification=true)"
                )
                return
        except Exception as e:
            logger.debug("drain_notification_suppressed check failed: %s", e)

        # Snapshot adapters up front: adapter.send() can hit a fatal error
        # path that pops the adapter from self.adapters (see _handle_fatal
        # elsewhere), which would otherwise trigger
        # ``RuntimeError: dictionary changed size during iteration`` —
        # observed in a user report during gateway shutdown.
        for platform, adapter in list(self.adapters.items()):
            home = self.config.get_home_channel(platform)
            if not home or not home.chat_id:
                continue

            platform_cfg = self.config.platforms.get(platform)
            if platform_cfg is not None and not platform_cfg.gateway_restart_notification:
                logger.info(
                    "Shutdown notification suppressed for home channel: %s has gateway_restart_notification=false",
                    platform.value,
                )
                continue

            dedup_key = (
                platform.value,
                str(home.chat_id),
                str(home.thread_id) if home.thread_id else None,
            )
            if dedup_key in notified:
                continue

            try:
                metadata = self._thread_metadata_for_target(
                    platform,
                    home.chat_id,
                    home.thread_id,
                    adapter=adapter,
                )
                if metadata:
                    result = await adapter.send(
                        str(home.chat_id), msg, metadata=metadata
                    )
                else:
                    result = await adapter.send(str(home.chat_id), msg)
                if result is not None and getattr(result, "success", True) is False:
                    logger.debug(
                        "Failed to send shutdown notification to home channel %s:%s: %s",
                        platform.value,
                        home.chat_id,
                        getattr(result, "error", "send returned success=False"),
                    )
                    continue

                notified.add(dedup_key)
                logger.info(
                    "Sent shutdown notification to home channel %s:%s",
                    platform.value,
                    home.chat_id,
                )
            except Exception as e:
                logger.debug(
                    "Failed to send shutdown notification to home channel %s:%s: %s",
                    platform.value,
                    home.chat_id,
                    e,
                )

    async def _finalize_shutdown_agents(
        self, active_agents: Dict[str, Any]
    ) -> None:
        for agent in active_agents.values():
            try:
                flush = getattr(agent, "_flush_messages_to_session_db", None)
                session_messages = getattr(agent, "_session_messages", None)
                if (
                    callable(flush)
                    and isinstance(session_messages, list)
                    and session_messages
                ):
                    strip_scaffolding = getattr(
                        agent, "_drop_trailing_empty_response_scaffolding", None
                    )
                    if callable(strip_scaffolding):
                        try:
                            strip_scaffolding(session_messages)
                        except Exception:
                            pass
                    flush(session_messages)
            except Exception as exc:
                logger.debug("Shutdown transcript flush failed: %s", exc)
            try:
                from hermes_cli.plugins import invoke_hook as _invoke_hook
                _invoke_hook(
                    "on_session_finalize",
                    session_id=getattr(agent, "session_id", None),
                    platform="gateway",
                    reason="shutdown",
                )
            except Exception:
                pass
            await self._cleanup_agent_resources_off_loop(
                agent, context="shutdown finalize"
            )

    def _cleanup_agent_resources(self, agent: Any) -> None:
        """Best-effort cleanup for temporary or cached agent instances."""
        if agent is None:
            return
        try:
            if hasattr(agent, "shutdown_memory_provider"):
                # Pass the agent's own conversation transcript so memory
                # providers' ``on_session_end`` hooks see the real messages
                # instead of the empty default (#15165). ``_session_messages``
                # is set on ``AIAgent`` (run_agent.py:1518) and refreshed at
                # the end of every ``run_conversation`` turn via
                # ``_persist_session``; on an agent built through
                # ``object.__new__`` (test stubs) the attribute may be
                # absent, so ``getattr`` with a ``None`` default keeps the
                # call signature-compatible with the pre-fix behaviour
                # (``shutdown_memory_provider(messages=None)``).
                session_messages = getattr(agent, "_session_messages", None)
                if isinstance(session_messages, list):
                    agent.shutdown_memory_provider(session_messages)
                else:
                    agent.shutdown_memory_provider()
        except Exception:
            pass
        # Close tool resources (terminal sandboxes, browser daemons,
        # background processes, httpx clients) to prevent zombie
        # process accumulation.
        try:
            if hasattr(agent, "close"):
                agent.close()
        except Exception:
            pass
        # Auxiliary async clients (session_search/web/vision/etc.) live in a
        # process-global cache and are created inside worker threads. Clean up
        # any entries whose event loop is now dead so their httpx transports do
        # not accumulate across gateway turns.
        try:
            from agent.auxiliary_client import cleanup_stale_async_clients
            cleanup_stale_async_clients()
        except Exception:
            pass

    _STUCK_LOOP_THRESHOLD = 3  # restarts while active before auto-suspend
    _STUCK_LOOP_FILE = ".restart_failure_counts"

    def _increment_restart_failure_counts(self, active_session_keys: set) -> None:
        """Increment restart-failure counters for sessions active at shutdown.

        Persists to a JSON file so counters survive across restarts.
        Sessions NOT in active_session_keys are removed (they completed
        successfully, so the loop is broken).
        """
        import json

        path = _hermes_home / self._STUCK_LOOP_FILE
        try:
            counts = json.loads(path.read_text()) if path.exists() else {}
        except Exception:
            counts = {}

        # Increment active sessions, remove inactive ones (loop broken)
        new_counts = {}
        for key in active_session_keys:
            new_counts[key] = counts.get(key, 0) + 1
        # Keep any entries that are still above 0 even if not active now
        # (they might become active again next restart)

        try:
            atomic_json_write(path, new_counts, indent=None)
        except Exception:
            pass

    def _suspend_stuck_loop_sessions(self) -> int:
        """Suspend sessions that have been active across too many restarts.

        Returns the number of sessions suspended.  Called on gateway startup
        AFTER suspend_recently_active() to catch the stuck-loop pattern:
        session loads → agent gets stuck → gateway restarts → repeat.
        """
        import json

        path = _hermes_home / self._STUCK_LOOP_FILE
        if not path.exists():
            return 0

        try:
            counts = json.loads(path.read_text())
        except Exception:
            return 0

        suspended = 0
        stuck_keys = [k for k, v in counts.items() if v >= self._STUCK_LOOP_THRESHOLD]

        for session_key in stuck_keys:
            try:
                entry = self.session_store._entries.get(session_key)
                if entry and not entry.suspended:
                    entry.suspended = True
                    suspended += 1
                    logger.warning(
                        "Auto-suspended stuck session %s (active across %d "
                        "consecutive restarts — likely a stuck loop)",
                        session_key, counts[session_key],
                    )
            except Exception:
                pass

        if suspended:
            try:
                self.session_store._save()
            except Exception:
                pass

        # Clear the file — counters start fresh after suspension
        try:
            path.unlink(missing_ok=True)
        except Exception:
            pass

        return suspended

    def _clear_restart_failure_count(self, session_key: str) -> None:
        """Clear the restart-failure counter for a session that completed OK.

        Called after a successful agent turn to signal the loop is broken.
        """
        import json

        path = _hermes_home / self._STUCK_LOOP_FILE
        if not path.exists():
            return
        try:
            counts = json.loads(path.read_text())
            if session_key in counts:
                del counts[session_key]
                if counts:
                    atomic_json_write(path, counts, indent=None)
                else:
                    path.unlink(missing_ok=True)
        except Exception:
            pass

    async def _launch_detached_restart_command(self) -> None:
        import shutil
        import subprocess

        hermes_cmd = _resolve_hermes_bin()
        if not hermes_cmd:
            logger.error("Could not locate hermes binary for detached /restart")
            return
        if self._detached_restart_helper_started:
            return
        self._detached_restart_helper_started = True

        current_pid = os.getpid()
        restart_after_s = max(
            float(getattr(self, "_restart_drain_timeout", 0.0) or 0.0) + 5.0,
            5.0,
        )

        # On Windows there's no bash/setsid chain — spawn a tiny Python
        # watcher directly via sys.executable instead.  The watcher polls
        # current_pid, waits for our exit, then runs `hermes gateway
        # restart` with detach flags so the respawn survives the CLI
        # that triggered the /restart command closing its console.
        if sys.platform == "win32":
            import textwrap
            from hermes_cli._subprocess_compat import windows_detach_popen_kwargs

            cmd_argv = [*hermes_cmd, "gateway", "restart"]
            watcher = textwrap.dedent(
                """
                import os, subprocess, sys, time
                from hermes_cli._subprocess_compat import windows_detach_flags_without_breakaway
                pid = int(sys.argv[1])
                restart_after_s = float(sys.argv[2])
                cmd = sys.argv[3:]
                deadline = time.monotonic() + restart_after_s

                def _alive(p):
                    # On Windows, os.kill(pid, 0) is NOT a no-op — it maps to
                    # GenerateConsoleCtrlEvent(0, pid) (bpo-14484). Use the
                    # Win32 handle-based existence check instead.
                    if os.name == 'nt':
                        import ctypes
                        k32 = ctypes.windll.kernel32
                        k32.OpenProcess.restype = ctypes.c_void_p
                        k32.WaitForSingleObject.restype = ctypes.c_uint
                        k32.GetLastError.restype = ctypes.c_uint
                        h = k32.OpenProcess(0x1000 | 0x100000, False, int(p))
                        if not h:
                            return k32.GetLastError() != 87
                        try:
                            return k32.WaitForSingleObject(h, 0) == 0x102
                        finally:
                            k32.CloseHandle(h)
                    try:
                        os.kill(int(p), 0)
                        return True
                    except ProcessLookupError:
                        return False
                    except PermissionError:
                        return True
                    except OSError:
                        return False

                while time.monotonic() < deadline:
                    if not _alive(pid):
                        break
                    time.sleep(0.2)
                subprocess.Popen(
                    cmd,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    creationflags=windows_detach_flags_without_breakaway(),
                )
                """
            ).strip()
            watcher_env = os.environ.copy()
            watcher_env.pop("_HERMES_GATEWAY", None)
            project_root = Path(__file__).resolve().parent.parent
            watcher_python = sys.executable
            try:
                from hermes_cli.gateway_windows import _resolve_detached_python

                watcher_python, _watcher_venv_dir, _watcher_site_packages = (
                    _resolve_detached_python(sys.executable)
                )
            except Exception:
                watcher_python = sys.executable
            venv_dir = Path(
                watcher_env.get("VIRTUAL_ENV") or project_root / "venv"
            )
            site_packages = venv_dir / "Lib" / "site-packages"
            if site_packages.exists():
                watcher_env["VIRTUAL_ENV"] = str(venv_dir)
                pythonpath = [str(project_root), str(site_packages)]
                if watcher_env.get("PYTHONPATH"):
                    pythonpath.append(watcher_env["PYTHONPATH"])
                watcher_env["PYTHONPATH"] = os.pathsep.join(
                    dict.fromkeys(pythonpath)
                )
            subprocess.Popen(
                [
                    watcher_python,
                    "-c",
                    watcher,
                    str(current_pid),
                    str(restart_after_s),
                    *cmd_argv,
                ],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                env=watcher_env,
                **windows_detach_popen_kwargs(),
            )
            return

        cmd = " ".join(shlex.quote(part) for part in hermes_cmd)
        shell_cmd = (
            f"deadline=$(( $(date +%s) + {int(restart_after_s)} )); "
            f"while kill -0 {current_pid} 2>/dev/null "
            f"&& [ $(date +%s) -lt $deadline ]; do sleep 0.2; done; "
            f"{cmd} gateway restart"
        )
        watcher_env = os.environ.copy()
        watcher_env.pop("_HERMES_GATEWAY", None)
        setsid_bin = shutil.which("setsid")
        if setsid_bin:
            subprocess.Popen(
                [setsid_bin, "bash", "-lc", shell_cmd],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                env=watcher_env,
                start_new_session=True,
            )
        else:
            subprocess.Popen(
                ["bash", "-lc", shell_cmd],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                env=watcher_env,
                start_new_session=True,
            )

    def request_restart(self, *, detached: bool = False, via_service: bool = False) -> bool:
        if self._restart_task_started:
            return False
        self._restart_requested = True
        self._restart_detached = detached
        self._restart_via_service = via_service
        self._restart_task_started = True

        async def _run_restart() -> None:
            await asyncio.sleep(0.05)
            await self.stop(restart=True, detached_restart=detached, service_restart=via_service)

        task = asyncio.create_task(_run_restart())
        self._background_tasks.add(task)
        task.add_done_callback(self._background_tasks.discard)
        return True

    def _start_owned_runner(
        self,
        name: str,
        runner_factory: Any,
        *,
        restart_on_exit: bool = False,
    ) -> Optional[asyncio.Task]:
        """Start one strongly-owned long-lived runner under a stable name.

        Critical runners are supervised in-place: an unexpected return or
        exception is logged and restarted with capped backoff while the gateway
        still owns the process.  Shutdown flips ``_running`` before cancelling
        these tasks, so a cancelled runner can never respawn behind teardown.
        """

        if not name or self.__dict__.get("_running") is False:
            return None
        shutdown_event = getattr(self, "_shutdown_event", None)
        if shutdown_event is not None and shutdown_event.is_set():
            return None
        owned = self.__dict__.setdefault("_owned_runner_tasks", {})
        existing = owned.get(name)
        if existing is not None and not existing.done():
            return existing

        async def _supervise() -> None:
            backoff = 0.1
            while self.__dict__.get("_running") is not False:
                if shutdown_event is not None and shutdown_event.is_set():
                    return
                try:
                    await runner_factory()
                    failure: Optional[BaseException] = None
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    failure = exc
                    logger.exception("Gateway runner %s failed", name)
                if not restart_on_exit:
                    return
                if self.__dict__.get("_running") is False:
                    return
                if shutdown_event is not None and shutdown_event.is_set():
                    return
                if failure is None:
                    logger.warning(
                        "Critical gateway runner %s exited unexpectedly; restarting",
                        name,
                    )
                try:
                    if shutdown_event is None:
                        await asyncio.sleep(backoff)
                    else:
                        await asyncio.wait_for(shutdown_event.wait(), timeout=backoff)
                        return
                except TimeoutError:
                    pass
                backoff = min(
                    _REQUIRED_ASYNC_RESTART_BACKOFF_MAX_SECONDS,
                    backoff * 2.0,
                )

        task = asyncio.create_task(
            _supervise(),
            name=f"gateway:{name}",
        )
        owned[name] = task
        background_tasks = self.__dict__.setdefault("_background_tasks", set())
        background_tasks.add(task)

        def _finished(done: asyncio.Task) -> None:
            background_tasks.discard(done)
            if owned.get(name) is done:
                owned.pop(name, None)
            if done.cancelled():
                return
            try:
                exc = done.exception()
            except asyncio.CancelledError:
                return
            if exc is not None:
                logger.error(
                    "Owned gateway runner %s terminated outside supervision",
                    name,
                    exc_info=(type(exc), exc, exc.__traceback__),
                )

        task.add_done_callback(_finished)
        return task

    async def _cancel_owned_runners(self) -> None:
        """Cancel and bounded-await all long-lived runner supervisors."""

        owned = self.__dict__.setdefault("_owned_runner_tasks", {})
        item_tasks = self.__dict__.setdefault("_required_async_item_tasks", {})
        current = asyncio.current_task()
        tasks = list(dict.fromkeys(
            task
            for task in [*owned.values(), *item_tasks.values()]
            if task is not current and not task.done()
        ))
        for task in tasks:
            task.cancel()
        if tasks:
            try:
                await asyncio.wait_for(
                    asyncio.gather(*tasks, return_exceptions=True),
                    timeout=_OWNED_RUNNER_SHUTDOWN_TIMEOUT_SECONDS,
                )
            except TimeoutError:
                pending_names = [task.get_name() for task in tasks if not task.done()]
                logger.warning(
                    "Timed out awaiting owned gateway runners during shutdown: %s",
                    ", ".join(pending_names) or "unknown",
                )
        for name, task in list(owned.items()):
            if task.done() or task in tasks:
                owned.pop(name, None)
        for work_id, task in list(item_tasks.items()):
            if task.done() or task in tasks:
                item_tasks.pop(work_id, None)

    # Drain-timeout reasons set by _stop_impl() when a still-running turn is
    # force-interrupted; "restart_interrupted" is set by
    # SessionStore.suspend_recently_active() on crash recovery (no
    # .clean_shutdown marker).  All three mean "the agent was mid-turn and
    # we killed it" — eligible for startup auto-resume.
    _AUTO_RESUME_REASONS = frozenset(
        {"restart_timeout", "shutdown_timeout", "restart_interrupted"}
    )

    def _resume_pending_entry_is_fresh(self, entry: Any, *, now: Optional[datetime] = None) -> bool:
        if entry is None:
            return False
        if not getattr(entry, "resume_pending", False):
            return False
        if getattr(entry, "suspended", False):
            return False
        if getattr(entry, "resume_reason", None) not in self._AUTO_RESUME_REASONS:
            return False
        marker = getattr(entry, "last_resume_marked_at", None) or getattr(entry, "updated_at", None)
        if marker is None:
            return True
        try:
            age = ((now or datetime.now()) - marker).total_seconds()
            return age <= _auto_continue_freshness_window()
        except Exception:
            return True

    def _resume_pending_entry_for_session(self, session_key: str) -> Any | None:
        if not session_key:
            return None
        store = getattr(self, "session_store", None)
        if store is None:
            return None
        try:
            entry = getattr(store, "_entries", {}).get(session_key)
        except Exception:
            return None
        return entry if self._resume_pending_entry_is_fresh(entry) else None

    def _authoritative_closeout_item_for_session(self, session_key: str) -> Optional[Dict[str, Any]]:
        """Return the durable lifecycle handoff that owns recovery, if any."""

        if not session_key:
            return None
        try:
            from hermes_cli.trusted_closeout import normalize_closeout_state

            for item in self._ledger().incomplete_items():
                if (
                    str(item.get("session_key") or "") != session_key
                    or item.get("closeout_authoritative") is not True
                    or not isinstance(item.get("closeout"), dict)
                ):
                    continue
                if normalize_closeout_state(item["closeout"])["mode"] == "enforce":
                    return item
        except Exception:
            return None
        return None

    def _required_async_recovery_item_for_session(
        self,
        session_key: str,
    ) -> Optional[Dict[str, Any]]:
        """Return the required coding attempt that owns restart recovery."""

        if not session_key:
            return None
        try:
            ledger = self._ledger()
            for item in ledger.incomplete_items():
                if (
                    str(item.get("session_key") or "") != session_key
                    or item.get("platform") != "discord"
                ):
                    continue
                state = ledger.required_async_completion_state(
                    str(item.get("id") or "")
                )
                if isinstance(state, dict) and state.get("owns_recovery") is True:
                    return item
        except Exception:
            logger.debug(
                "Required async recovery ownership lookup failed for %s",
                session_key,
                exc_info=True,
            )
        return None

    def _discord_resume_work_item_for_session(self, session_key: str) -> Optional[Dict[str, Any]]:
        if not session_key:
            return None
        try:
            items = [
                item for item in self._ledger().incomplete_items()
                if item.get("platform") == "discord"
                and str(item.get("session_key") or "") == session_key
            ]
        except Exception:
            return None
        if not items:
            return None

        def _rank(item: Dict[str, Any]) -> tuple[int, int, float, float]:
            status = str(item.get("status") or "")
            final_response = str(item.get("final_response") or "")
            return (
                1 if status == "agent_done" and not final_response else 0,
                1 if status in {"accepted", "claimed", "agent_running", "agent_done"} else 0,
                float(item.get("updated_at") or 0),
                float(item.get("created_at") or 0),
            )

        return max(items, key=_rank)

    @staticmethod
    def _hydrate_discord_resume_event_from_work_item(
        event: MessageEvent,
        item: Optional[Dict[str, Any]],
        *,
        preserve_message_id: bool = False,
        preserve_event_context: bool = False,
    ) -> None:
        if not item:
            return
        work_id = str(item.get("id") or "")
        if work_id:
            event.work_item_id = work_id
            event.work_replay = True
        event.discord_runtime_mode = _discord_runtime_mode_for(
            item.get("discord_runtime_mode"),
            default=RuntimeMode.ACTION,
        ).value
        event.discord_action_request_intent = None
        event.discord_runtime_reason = item.get("discord_runtime_reason")
        event.discord_action_escalation_allowed = bool(
            item.get("discord_action_escalation_allowed", False)
        )
        event.discord_explicit_no_action_denial = bool(
            item.get("discord_explicit_no_action_denial", False)
        )
        event.participates_in_work_lifecycle = (
            bool(item.get("participates_in_work_lifecycle"))
            if "participates_in_work_lifecycle" in item
            else True
        )
        event.discord_drain_recovery = bool(item.get("drain_recovery", False))
        try:
            event.discord_pr_generation = max(
                1,
                int(item.get("discord_pr_generation") or 1),
            )
        except (TypeError, ValueError, OverflowError):
            event.discord_pr_generation = 1
        event.discord_pr_rollover = bool(item.get("discord_pr_rollover", False))
        session_id = str(item.get("session_id") or "").strip()
        if session_id:
            event.session_id = session_id
        feature_summary = item.get("feature_summary")
        project_summary = item.get("project_summary")
        if not preserve_event_context or not isinstance(
            getattr(event, "feature_summary", None), dict
        ):
            event.feature_summary = (
                feature_summary if isinstance(feature_summary, dict) else None
            )
        if not preserve_event_context or not isinstance(
            getattr(event, "project_summary", None), dict
        ):
            event.project_summary = (
                project_summary if isinstance(project_summary, dict) else None
            )
        for field in (
            "channel_prompt",
            "channel_context",
            "goal_thread_context",
            "reply_to_message_id",
            "reply_to_text",
        ):
            if not preserve_event_context or getattr(event, field, None) is None:
                setattr(event, field, item.get(field))
        event.visual_qa_requirement, event.visual_qa_config = _normalize_gateway_visual_qa_contract(
            item.get("visual_qa_requirement"),
            item.get("visual_qa_config"),
        )
        if item.get("message_id") and not preserve_message_id:
            event.message_id = str(item.get("message_id"))
            if getattr(event.source, "message_id", None) is None:
                event.source.message_id = event.message_id

    def _hydrate_discord_feature_summary_from_adapter(
        self,
        event: MessageEvent,
    ) -> Optional[Dict[str, Any]]:
        """Restore a persisted Discord thread summary onto an event.

        Normal adapter intake attaches the handle directly. This fallback also
        covers synthetic or recovered events that have only a thread identity,
        so the turn-end callback can still finalize the embed and its reaction.
        """
        existing = getattr(event, "feature_summary", None)
        if isinstance(existing, dict):
            return existing
        source = getattr(event, "source", None)
        if getattr(source, "platform", None) != Platform.DISCORD:
            return None
        thread_id = str(getattr(source, "thread_id", "") or "").strip()
        if not thread_id:
            return None
        adapter = self._adapter_for_source(source)
        load_handle = getattr(
            adapter,
            "_load_feature_summary_handle_by_thread_id",
            None,
        )
        if not callable(load_handle):
            return None
        try:
            feature_summary = load_handle(thread_id)
        except Exception:
            logger.debug(
                "Discord feature-summary event hydration failed for thread %s",
                thread_id,
                exc_info=True,
            )
            return None
        if not isinstance(feature_summary, dict):
            return None
        event.feature_summary = feature_summary
        return feature_summary

    async def _promote_discord_action_escalation(
        self,
        *,
        event: MessageEvent,
        source: SessionSource,
        session_key: str,
        run_generation: int,
        agent_result: Dict[str, Any],
    ) -> Optional[str]:
        """Queue a clean action-runtime replay for a successful intake handoff."""
        if (
            source.platform != Platform.DISCORD
            or _discord_runtime_mode_for(event) is not RuntimeMode.READ_ONLY
            or not isinstance(agent_result.get("action_escalation_requested"), dict)
            or not self._is_session_run_current(session_key, run_generation)
        ):
            return None
        payload = agent_result["action_escalation_requested"]
        if not (
            payload.get("success") is True
            and payload.get("action_escalation_requested") is True
        ):
            return None

        adapter = self._adapter_for_source(source)
        promote = getattr(adapter, "promote_event_to_action_request", None)
        if not callable(promote):
            logger.error("Discord action escalation unavailable: adapter lacks promotion support")
            return None
        promoted_event, thread_url = await promote(
            event,
            initial_request=str(getattr(event, "text", "") or "").strip(),
            generation_is_current=lambda: self._is_session_run_current(
                session_key,
                run_generation,
            ),
        )
        if promoted_event is None:
            logger.error("Discord action escalation failed to initialize action state")
            return None

        if not self._is_session_run_current(session_key, run_generation):
            rollback = getattr(adapter, "rollback_promoted_action_request", None)
            if callable(rollback):
                try:
                    result = rollback(promoted_event)
                    if inspect.isawaitable(result):
                        await result
                except Exception:
                    logger.debug("Discord stale action-promotion rollback failed", exc_info=True)
            return None

        promoted_source = getattr(promoted_event, "source", None) or source
        promoted_session_key = self._session_key_for_source(promoted_source)
        promoted_event._discord_promotion_origin_session_key = session_key
        promoted_event._discord_promotion_origin_generation = int(run_generation)
        if promoted_session_key == session_key:
            # The current adapter task still owns this session. Put the action
            # replay at the head so a racing user follow-up remains ordered
            # after the original request instead of merging into it.
            if not self._is_session_run_current(session_key, run_generation):
                rollback = getattr(adapter, "rollback_promoted_action_request", None)
                if callable(rollback):
                    try:
                        result = rollback(promoted_event)
                        if inspect.isawaitable(result):
                            await result
                    except Exception:
                        logger.debug(
                            "Discord stale action-promotion rollback failed",
                            exc_info=True,
                        )
                return None
            self._prepend_fifo(session_key, promoted_event, adapter)
        else:
            if not self._is_session_run_current(session_key, run_generation):
                rollback = getattr(adapter, "rollback_promoted_action_request", None)
                if callable(rollback):
                    try:
                        result = rollback(promoted_event)
                        if inspect.isawaitable(result):
                            await result
                    except Exception:
                        logger.debug(
                            "Discord stale action-promotion rollback failed",
                            exc_info=True,
                        )
                return None
            await adapter.handle_message(promoted_event)

        # The intake agent contains an intentionally unpersisted tool turn.
        # Never reuse it after the route changes, even if a future signature
        # change accidentally makes the two runtimes compare equal.
        self._evict_cached_agent(session_key)
        return str(thread_url or "")

    def _promoted_replay_is_current(self, event: MessageEvent) -> bool:
        origin_key = str(
            getattr(event, "_discord_promotion_origin_session_key", "") or ""
        )
        origin_generation = getattr(
            event,
            "_discord_promotion_origin_generation",
            None,
        )
        if not origin_key and origin_generation is None:
            return True
        try:
            return bool(
                origin_key
                and int(origin_generation) > 0
                and self._is_session_run_current(origin_key, int(origin_generation))
            )
        except (TypeError, ValueError):
            return False

    async def _consume_promoted_replay_fence(
        self,
        event: MessageEvent,
        *,
        consume: bool = True,
    ) -> bool:
        """Validate one promoted replay immediately before gateway dispatch."""
        if not hasattr(event, "_discord_promotion_origin_generation"):
            return True
        if not self._promoted_replay_is_current(event):
            adapter = self._adapter_for_source(getattr(event, "source", None))
            rollback = getattr(adapter, "rollback_promoted_action_request", None)
            if callable(rollback):
                try:
                    result = rollback(event)
                    if inspect.isawaitable(result):
                        await result
                except Exception:
                    logger.debug("Discord stale promoted replay rollback failed", exc_info=True)
            logger.info("Discarding stale promoted Discord action replay before dispatch")
            return False
        if consume:
            delattr(event, "_discord_promotion_origin_session_key")
            delattr(event, "_discord_promotion_origin_generation")
        return True

    @staticmethod
    def _is_promoted_discord_replay(event: Optional[MessageEvent]) -> bool:
        return bool(
            event is not None
            and hasattr(event, "_discord_promotion_origin_generation")
        )

    def _defer_promoted_replay_to_fresh_turn(
        self,
        *,
        event: Optional[MessageEvent],
        session_key: str,
        adapter: Any,
    ) -> bool:
        if not self._is_promoted_discord_replay(event):
            return False
        self._prepend_fifo(session_key, event, adapter)
        return True

    def _discord_work_item_id_for_event(
        self,
        event: MessageEvent,
        session_key: str,
    ) -> Optional[str]:
        if not getattr(event, "participates_in_work_lifecycle", True):
            return None
        if (
            getattr(getattr(event, "source", None), "platform", None) == Platform.DISCORD
            and _discord_runtime_mode_for(
                event,
                default=(
                    RuntimeMode.ACTION
                    if getattr(event, "internal", False)
                    else RuntimeMode.READ_ONLY
                ),
            )
            is not RuntimeMode.ACTION
        ):
            return None
        work_item_id = getattr(event, "work_item_id", None)
        if work_item_id or getattr(event.source, "platform", None) != Platform.DISCORD:
            return str(work_item_id) if work_item_id else None
        try:
            work_id = self._ledger().id_for_event(event, session_key)
            item = self._ledger().get(str(work_id)) if work_id else None
        except Exception:
            return None
        if not isinstance(item, dict):
            return None
        self._hydrate_discord_resume_event_from_work_item(event, item)
        return str(item.get("id") or work_id or "") or None

    def _hydrate_discord_continuation_event_from_work_item(
        self,
        event: MessageEvent,
        session_key: str,
        *,
        allow_session_fallback: bool = False,
    ) -> None:
        """Restore durable metadata before a queued Discord continuation runs.

        Normal Discord messages carry their feature-summary handle from the
        adapter. Synthetic and command-created queued events do not, so they
        would otherwise take the generic gateway route instead of the route
        for the action thread that produced them.
        """
        source = getattr(event, "source", None)
        if getattr(source, "platform", None) != Platform.DISCORD:
            return
        if isinstance(getattr(event, "feature_summary", None), dict):
            return

        item: Optional[Dict[str, Any]] = None
        try:
            work_item_id = self._discord_work_item_id_for_event(event, session_key)
            if work_item_id:
                item = self._ledger().get(str(work_item_id))
        except Exception:
            logger.debug("Discord continuation work-item lookup failed", exc_info=True)

        if not isinstance(item, dict) and allow_session_fallback:
            item = self._discord_resume_work_item_for_session(session_key)
        if isinstance(item, dict):
            self._hydrate_discord_resume_event_from_work_item(
                event,
                item,
                preserve_message_id=bool(getattr(event, "message_id", None)),
                preserve_event_context=True,
            )

    async def _redeliver_pending_obligations(self) -> int:
        """Recover ordinary final responses without replaying their model turn.

        Fork-managed work items are deliberately not producers for this ledger;
        their exact-attempt and uncertain-send recovery remains exclusively in
        ``GatewayWorkLedger``.
        """
        try:
            from gateway.delivery_ledger import (
                RECOVERED_MARKER,
                ledger_enabled,
                mark_delivered,
                mark_failed,
                sweep_recoverable,
            )

            if not ledger_enabled():
                return 0
            deliverable = {getattr(p, "value", str(p)) for p in self.adapters}
            claimed = await asyncio.to_thread(
                sweep_recoverable,
                None,
                deliverable_platforms=deliverable,
            )
        except Exception:
            logger.debug("delivery ledger sweep failed", exc_info=True)
            return 0
        if not claimed:
            return 0

        redelivered = 0
        for row in claimed:
            try:
                platform = Platform(row["platform"])
            except Exception:
                logger.debug(
                    "obligation %s: unknown platform %r",
                    row["obligation_id"],
                    row.get("platform"),
                )
                continue
            adapter = self.adapters.get(platform)
            if adapter is None:
                continue
            content = row["content"]
            if row.get("needs_marker"):
                content = RECOVERED_MARKER + content
            metadata = (
                {"thread_id": row["thread_id"]}
                if row.get("thread_id")
                else None
            )
            try:
                result = await adapter.send(
                    chat_id=row["chat_id"],
                    content=content,
                    metadata=metadata,
                )
            except Exception as send_err:
                logger.warning(
                    "obligation %s: redelivery send raised: %s",
                    row["obligation_id"],
                    send_err,
                )
                result = None
            try:
                if result is not None and getattr(result, "success", False):
                    mark_delivered(row["obligation_id"])
                    redelivered += 1
                else:
                    mark_failed(
                        row["obligation_id"],
                        str(getattr(result, "error", "") or "send failed"),
                    )
            except Exception:
                logger.debug("delivery ledger update failed", exc_info=True)

            session_key = row.get("session_key") or ""
            if session_key:
                try:
                    await self.async_session_store.clear_resume_pending(session_key)
                except Exception:
                    logger.debug(
                        "clear_resume_pending failed for %s",
                        session_key,
                        exc_info=True,
                    )
        return redelivered

    def _schedule_resume_pending_sessions(
        self,
        platform: Optional[Platform] = None,
    ) -> int:
        """Auto-continue fresh restart-interrupted sessions after startup.

        ``resume_pending`` already preserves the transcript AND the existing
        ``_is_resume_pending`` branch in ``_handle_message_with_agent``
        injects a reason-aware recovery system note on the next turn.  This
        method closes the UX gap by synthesizing that next turn once
        adapters are back online. The internal prompt explicitly continues
        interrupted work while the recovery-note path retains reason context.

        Adapters that are not yet ready are skipped silently; their sessions
        stay ``resume_pending`` and will auto-resume on the next real user
        message, or when that platform reconnects. ``platform`` restricts a
        reconnect pass to sessions from that platform only.
        """
        try:
            with self.session_store._lock:  # noqa: SLF001 — snapshot under lock
                self.session_store._ensure_loaded_locked()  # noqa: SLF001
                candidates = [
                    entry for entry in self.session_store._entries.values()  # noqa: SLF001
                    if entry.resume_pending
                    and not entry.suspended
                    and entry.origin is not None
                    and entry.resume_reason in self._AUTO_RESUME_REASONS
                    and (platform is None or entry.origin.platform == platform)
                ]
        except Exception as exc:
            logger.warning("Failed to enumerate resume-pending sessions: %s", exc)
            return 0

        now = datetime.now()
        scheduled = 0
        for entry in candidates:
            if not self._resume_pending_entry_is_fresh(entry, now=now):
                continue
            if entry.session_key in getattr(self, "_running_agents", {}):
                # Startup and reconnect passes may overlap. Never synthesize a
                # second continuation while the first one still owns the slot.
                continue
            if self._required_async_recovery_item_for_session(entry.session_key) is not None:
                # The transcript may still carry a restart marker from the
                # parent turn, but its required coding attempt is durably owned
                # by deterministic reconciliation.  Clear the replay marker so
                # a later startup cannot resurrect the parent model turn.
                try:
                    self.session_store.clear_resume_pending(entry.session_key)
                except Exception:
                    logger.debug(
                        "Failed to clear resume marker owned by required async recovery for %s",
                        entry.session_key,
                        exc_info=True,
                    )
                continue
            if self._authoritative_closeout_item_for_session(entry.session_key) is not None:
                # A completed model/worker turn already handed lifecycle ownership
                # to trusted closeout. Never replay that turn after restart.
                try:
                    self.session_store.clear_resume_pending(entry.session_key)
                except Exception:
                    logger.debug(
                        "Failed to clear resume marker owned by closeout for %s",
                        entry.session_key,
                        exc_info=True,
                    )
                continue

            source = entry.origin
            adapter = self._adapter_for_source(source)
            if adapter is None:
                logger.debug(
                    "Skipping auto-resume for %s: adapter not ready for %s",
                    entry.session_key,
                    getattr(source.platform, "value", source.platform),
                )
                continue

            # Startup auto-resume bypasses the ordinary inbound auth gate, so
            # re-check the current allowlist before creating a full agent turn.
            # Authorization errors fail closed rather than reviving work for a
            # user whose access can no longer be established.
            try:
                if not self._is_user_authorized(source):
                    logger.warning(
                        "Skipping auto-resume for %s: session owner is no "
                        "longer authorized under the current allowlist",
                        entry.session_key,
                    )
                    continue
            except Exception as exc:
                logger.warning(
                    "Skipping auto-resume for %s: authorization check failed: %s",
                    entry.session_key,
                    exc,
                )
                continue

            # Claim before task creation so an inbound message cannot race the
            # synthetic turn and start a second agent for the same session.
            self._running_agents[entry.session_key] = _AGENT_PENDING_SENTINEL
            self._running_agents_ts[entry.session_key] = time.time()
            self._persist_active_agents()

            # Internal auto-resume event.  The _is_resume_pending branch in
            # _handle_message_with_agent prepends the reason-aware system note;
            # this text makes the recovered turn explicitly continue instead of
            # treating the empty restart event as a fresh prompt.
            event = MessageEvent(
                text=(
                    "Continue the turn that was interrupted by the gateway restart. "
                    "Use the existing transcript/tool results and report what was completed."
                ),
                message_type=MessageType.TEXT,
                source=source,
                internal=True,
                metadata={_STARTUP_RESUME_EVENT_METADATA_KEY: True},
            )
            if source.platform == Platform.DISCORD:
                self._hydrate_discord_resume_event_from_work_item(
                    event,
                    self._discord_resume_work_item_for_session(entry.session_key),
                )
            task = asyncio.create_task(
                self._run_startup_resume_event(
                    adapter,
                    event,
                    entry.session_key,
                )
            )
            self._background_tasks.add(task)
            task.add_done_callback(self._background_tasks.discard)
            if getattr(self, "_startup_restore_in_progress", False):
                startup_tasks = getattr(self, "_startup_restore_tasks", None)
                if startup_tasks is None:
                    startup_tasks = []
                    self._startup_restore_tasks = startup_tasks
                startup_tasks.append(task)
            scheduled += 1

        if scheduled:
            logger.info(
                "Scheduled auto-resume for %d restart-interrupted session(s)",
                scheduled,
            )
        return scheduled

    def _schedule_incomplete_discord_work_items(self) -> int:
        """Replay accepted Discord work that never reached completion.

        This is intentionally ledger-driven.  We do not scan historical
        sessions, feature summaries, or Discord thread caches, so old threads
        cannot be resurrected unless a fresh accepted work item exists.
        """
        ledger = self._ledger()
        scheduled = 0
        for item in ledger.incomplete_items():
            work_id = str(item.get("id") or "")
            if not work_id:
                continue
            status = str(item.get("status") or "")
            required_state = ledger.required_async_completion_state(work_id)
            if (
                isinstance(required_state, dict)
                and required_state.get("owns_recovery") is True
            ):
                # The required-completion reconciler owns this exact attempt.
                # Never replay its original Discord request after restart.
                continue
            terminal_delivery = (
                item.get("terminal_delivery")
                if isinstance(item.get("terminal_delivery"), dict)
                else {}
            )
            if status == "blocked" and str(terminal_delivery.get("status") or "") != "completed":
                task = asyncio.create_task(self._resume_finished_discord_work_item(item))
                self._background_tasks.add(task)
                task.add_done_callback(self._background_tasks.discard)
                scheduled += 1
                continue
            closeout_state = item.get("closeout") if isinstance(item.get("closeout"), dict) else None
            normalized_closeout = None
            if closeout_state is not None:
                from hermes_cli.trusted_closeout import TERMINAL_CLOSEOUT_STATUSES, normalize_closeout_state

                normalized_closeout = normalize_closeout_state(closeout_state)
            closeout_authoritative = (
                item.get("closeout_authoritative") is True
                and normalized_closeout is not None
                and normalized_closeout["mode"] == "enforce"
            )
            if (
                closeout_authoritative
                and normalized_closeout is not None
                and status not in {"agent_done", "response_delivered", "summary_updated"}
            ):
                if normalized_closeout["status"] in TERMINAL_CLOSEOUT_STATUSES:
                    if status in {"claimed", "agent_running"} and self._work_item_agent_run_active(item):
                        # A live turn still owns its own completion/delivery path.
                        continue
                    failed_closeout = normalized_closeout["status"] in {"blocked", "repair_required"}
                    summary = (
                        "Trusted closeout blocked: a deterministic lifecycle gate requires repair."
                        if failed_closeout
                        else (
                            "PR preview QA completed; the draft PR remains open and main is untouched."
                        )
                    )
                    ledger.mark_agent_done(
                        work_id,
                        final_response=summary,
                        summary_status="Blocked" if failed_closeout else "Complete",
                        expected_run_state=ledger.run_state_snapshot(item),
                    )
                    item = ledger.get(work_id) or item
                    status = str(item.get("status") or "")
                else:
                    watcher = getattr(self, "trusted_closeout_watcher", None)
                    if watcher is not None:
                        watcher.notify(work_id)
                    # Model work already reached a durable lifecycle handoff.
                    # The closeout watcher, not session replay, owns recovery.
                    continue
            lease_until = float(item.get("lease_until") or 0)
            if (
                status in {"claimed", "agent_running"}
                and lease_until > time.time()
                and self._work_item_agent_run_active(item)
            ):
                continue
            if self._resume_pending_entry_for_session(str(item.get("session_key") or "")):
                logger.debug(
                    "Deferring Discord work item replay for resume-pending session %s",
                    item.get("session_key"),
                )
                continue
            try:
                event = ledger.event_from_item(item)
            except Exception as exc:
                logger.warning("Failed to rebuild Discord work item %s: %s", work_id, exc)
                ledger.mark_expired(work_id)
                continue
            repository = _gateway_repository_for_source(getattr(event, "source", None))
            _, recovered_visual_config = _normalize_gateway_visual_qa_contract(
                None,
                _repository_visual_qa_config(_load_gateway_config(), repository),
            )
            promoted = ledger.promote_visual_qa_config(
                work_id,
                recovered_visual_config,
                expected_run_state=item,
            )
            if promoted is not None:
                item = promoted
                event.visual_qa_requirement, event.visual_qa_config = (
                    _normalize_gateway_visual_qa_contract(
                        item.get("visual_qa_requirement"),
                        item.get("visual_qa_config"),
                    )
                )
            source = event.source
            adapter = self._adapter_for_source(source)
            if adapter is None:
                logger.debug("Skipping Discord work item %s: adapter not ready", work_id)
                continue
            if status in {"agent_done", "response_delivered", "summary_updated"}:
                task = asyncio.create_task(self._resume_finished_discord_work_item(item))
            else:
                ledger.claim(work_id)
                task = asyncio.create_task(adapter.handle_message(event))
            self._background_tasks.add(task)
            task.add_done_callback(self._background_tasks.discard)
            scheduled += 1

        self._schedule_pending_discord_terminal_reactions()

        if scheduled:
            logger.info("Scheduled replay for %d incomplete Discord work item(s)", scheduled)
        return scheduled

    def _schedule_pending_discord_terminal_reactions(
        self,
        *,
        platform: Platform | None = None,
        profile_name: str | None = None,
    ) -> int:
        """Retry durable terminal reactions against the currently connected adapter."""

        ledger = self._ledger()
        scheduled = 0
        for item in ledger.pending_terminal_reaction_items():
            work_id = str(item.get("id") or "")
            item_profile = str(
                (item.get("source") if isinstance(item.get("source"), dict) else {}).get(
                    "profile"
                )
                or "default"
            )
            if profile_name is not None and item_profile != profile_name:
                continue
            try:
                event = ledger.event_from_item(item)
            except Exception as exc:
                logger.warning(
                    "Failed to rebuild Discord reaction reconciliation item %s: %s",
                    work_id,
                    exc,
                )
                continue
            if platform is not None and event.source.platform is not platform:
                continue
            adapter = self._discord_terminal_reaction_adapter(event.source)
            reconcile = getattr(adapter, "reconcile_work_ledger_thread_reaction", None)
            if not callable(reconcile):
                continue
            if self._schedule_discord_terminal_reaction(item):
                scheduled += 1

        return scheduled

    @staticmethod
    def _discord_terminal_reaction_task_key(item: Dict[str, Any]) -> tuple[str, str, str, str]:
        source = item.get("source") if isinstance(item.get("source"), dict) else {}
        return (
            str(source.get("profile") or "default"),
            str(source.get("guild_id") or ""),
            str(source.get("parent_chat_id") or ""),
            str(source.get("thread_id") or source.get("chat_id") or ""),
        )

    def _discord_terminal_reaction_adapter(
        self,
        source: SessionSource,
    ) -> BasePlatformAdapter | None:
        """Return the exact profile adapter without cross-profile fallback."""

        profile = str(getattr(source, "profile", None) or "default")
        if profile != "default":
            return getattr(self, "_profile_adapters", {}).get(profile, {}).get(
                source.platform
            )
        return getattr(self, "adapters", {}).get(source.platform)

    async def _reconcile_discord_terminal_reaction(
        self,
        item: Dict[str, Any],
        state: str | None = None,
    ) -> str | None:
        """Serialize one durable Discord reaction repair across lifecycle paths."""

        task, _created = self._request_discord_terminal_reaction(item, state)
        return await asyncio.shield(task)

    def _request_discord_terminal_reaction(
        self,
        item: Dict[str, Any],
        state: str | None,
    ) -> tuple[asyncio.Task, bool]:
        requests = self.__dict__.setdefault("_discord_terminal_reaction_requests", {})
        key = self._discord_terminal_reaction_task_key(item)
        try:
            event = self._ledger().event_from_item(item)
            adapter = self._discord_terminal_reaction_adapter(event.source)
        except Exception:
            adapter = None
        token = (str(item.get("id") or ""), state, id(adapter))
        existing = requests.get(key)
        if isinstance(existing, dict):
            task = existing.get("task")
            if isinstance(task, asyncio.Task) and not task.done():
                if existing.get("token") != token:
                    existing["item"] = item
                    existing["state"] = state
                    existing["token"] = token
                    existing["version"] = int(existing.get("version") or 0) + 1
                return task, False

        request = {
            "item": item,
            "state": state,
            "token": token,
            "version": 1,
        }
        task = asyncio.create_task(
            self._drain_discord_terminal_reaction(key, request)
        )
        request["task"] = task
        requests[key] = request
        self._background_tasks.add(task)

        def _cleanup(done: asyncio.Task) -> None:
            self._background_tasks.discard(done)

        task.add_done_callback(_cleanup)
        return task, True

    async def _drain_discord_terminal_reaction(
        self,
        key: tuple[str, str, str, str],
        request: Dict[str, Any],
    ) -> str | None:
        requests = self.__dict__.setdefault("_discord_terminal_reaction_requests", {})
        result = None
        try:
            while True:
                version = int(request.get("version") or 0)
                item = request.get("item")
                state = request.get("state")
                result = await self._run_discord_terminal_reaction(item, state)
                if int(request.get("version") or 0) == version:
                    if result is not None:
                        self._ledger().mark_discord_thread_reaction_synced(item)
                    return result
        finally:
            if requests.get(key) is request:
                requests.pop(key, None)

    async def _run_discord_terminal_reaction(
        self,
        item: Dict[str, Any],
        state: str | None,
    ) -> str | None:
        try:
            event = self._ledger().event_from_item(item)
            adapter = self._discord_terminal_reaction_adapter(event.source)
            reconcile = getattr(adapter, "reconcile_work_ledger_thread_reaction", None)
            if not callable(reconcile):
                return None
            return await reconcile(item, state, acknowledge=False)
        except Exception:
            logger.warning(
                "Discord terminal reaction reconciliation failed for %s",
                item.get("id"),
                exc_info=True,
            )
            return None

    def _schedule_discord_terminal_reaction(self, item: Dict[str, Any]) -> bool:
        task, created = self._request_discord_terminal_reaction(item, None)
        return created

    def _schedule_terminal_delivery_retry(self, work_id: str, *, attempt: int) -> bool:
        """Schedule one bounded, deduplicated retry without invoking a model."""

        if not work_id or attempt > _TERMINAL_DELIVERY_RETRY_MAX_ATTEMPTS:
            return False
        if self.__dict__.get("_running") is False:
            return False
        shutdown_event = getattr(self, "_shutdown_event", None)
        if shutdown_event is not None and shutdown_event.is_set():
            return False
        tasks = self.__dict__.setdefault("_terminal_delivery_retry_tasks", {})
        existing = tasks.get(work_id)
        current_task = asyncio.current_task()
        if existing is not None and not existing.done() and existing is not current_task:
            return False

        async def retry() -> None:
            delay = min(
                30.0,
                _TERMINAL_DELIVERY_RETRY_BASE_SECONDS * (2 ** max(0, attempt - 1)),
            )
            try:
                if shutdown_event is None:
                    await asyncio.sleep(delay)
                else:
                    try:
                        await asyncio.wait_for(shutdown_event.wait(), timeout=delay)
                        return
                    except TimeoutError:
                        pass
                if self.__dict__.get("_running") is False:
                    return
                if shutdown_event is not None and shutdown_event.is_set():
                    return
                fresh = self._ledger().get(work_id)
                if not isinstance(fresh, dict):
                    return
                delivery = (
                    fresh.get("terminal_delivery")
                    if isinstance(fresh.get("terminal_delivery"), dict)
                    else {}
                )
                if (
                    fresh.get("status") == "blocked"
                    and str(delivery.get("status") or "") not in {"completed"}
                ):
                    await self._resume_finished_discord_work_item(
                        fresh,
                        _delivery_retry_attempt=attempt,
                    )
            finally:
                if tasks.get(work_id) is asyncio.current_task():
                    tasks.pop(work_id, None)

        task = asyncio.create_task(retry())
        tasks[work_id] = task
        background_tasks = self.__dict__.setdefault("_background_tasks", set())
        background_tasks.add(task)
        task.add_done_callback(background_tasks.discard)
        return True

    async def _resume_finished_discord_work_item(
        self,
        item: Dict[str, Any],
        *,
        _delivery_retry_attempt: int = 0,
    ) -> None:
        """Finish Discord work after the agent result was durably recorded."""
        ledger = self._ledger()
        work_id = str(item.get("id") or "")
        if not work_id:
            return
        if not ledger.preview_delivery_satisfied(work_id):
            return
        expected_run_state = ledger.run_state_snapshot(item)
        try:
            event = ledger.event_from_item(item)
        except Exception as exc:
            logger.warning("Failed to rebuild finished Discord work item %s: %s", work_id, exc)
            ledger.mark_expired(work_id)
            return
        adapter = self._adapter_for_source(event.source)
        if adapter is None:
            logger.debug("Skipping finished Discord work item %s: adapter not ready", work_id)
            return

        status = str(item.get("status") or "")
        delivery_attempt = (
            item.get("delivery_attempt")
            if isinstance(item.get("delivery_attempt"), dict)
            else {}
        )
        if status == "agent_done" and str(delivery_attempt.get("status") or "") == "sending":
            persisted = await asyncio.to_thread(
                ledger.mark_response_delivery_uncertain,
                work_id,
                reason="send_attempt_outcome_unknown",
                expected_run_state=expected_run_state,
            )
            if not persisted:
                return
            item = ledger.get(work_id) or item
            status = str(item.get("status") or "")
            expected_run_state = {
                **expected_run_state,
                "status": "response_delivered",
            }
        if status == "blocked" and isinstance(item.get("terminal_delivery"), dict):
            delivery_owner = f"gateway-delivery:{os.getpid()}:{time.time_ns()}"
            claimed = await asyncio.to_thread(
                ledger.claim_terminal_delivery,
                work_id,
                owner=delivery_owner,
            )
            if claimed is None:
                return
            item = claimed
            delivery = item.get("terminal_delivery") if isinstance(item.get("terminal_delivery"), dict) else {}
            delivery_status = str(delivery.get("status") or "")
            final_response = str(item.get("final_response") or "")
            send_confirmed = bool(
                delivery.get("send_confirmed_at")
                or str(delivery.get("result_message_id") or "").strip()
                or delivery.get("confirmed_message_ids")
            )
            if final_response and delivery_status != "uncertain" and not send_confirmed:
                began = await asyncio.to_thread(
                    ledger.begin_terminal_send_attempt,
                    work_id,
                    owner=delivery_owner,
                )
                if not began:
                    return
                metadata = {"notify": True}
                try:
                    from gateway.platforms.base import _reply_anchor_for_event, _thread_metadata_for_source

                    metadata = _thread_metadata_for_source(
                        event.source,
                        _reply_anchor_for_event(event),
                    ) or {}
                    metadata = dict(metadata)
                    metadata["notify"] = True
                    reply_to = _reply_anchor_for_event(event)
                except Exception:
                    reply_to = item.get("reply_to_message_id") or item.get("message_id")
                try:
                    result = await adapter._send_with_retry(
                        chat_id=event.source.chat_id,
                        content=final_response,
                        reply_to=reply_to,
                        metadata=metadata,
                    )
                except Exception:
                    # Once the side effect was attempted, an exception is
                    # ambiguous. Surface uncertainty rather than risking an
                    # automatic duplicate blocked response.
                    uncertain = await asyncio.to_thread(
                        ledger.mark_terminal_delivery_uncertain,
                        work_id,
                        owner=delivery_owner,
                    )
                    if not uncertain:
                        return
                    item = ledger.get(work_id) or item
                    delivery_status = "uncertain"
                else:
                    if not getattr(result, "success", False):
                        error_text = str(getattr(result, "error", "") or "")
                        error_kind = str(getattr(result, "error_kind", "") or "")
                        if not error_kind:
                            error_kind = classify_send_error(None, error_text=error_text)
                        if (
                            event.source.platform == Platform.DISCORD
                            and getattr(event.source, "thread_id", None)
                            and error_kind == "not_found"
                            and "unknown channel" in error_text.lower()
                        ):
                            retired = await asyncio.to_thread(
                                ledger.mark_terminal_delivery_unreachable,
                                work_id,
                                owner=delivery_owner,
                                reason="discord_unknown_channel",
                            )
                            if retired:
                                logger.info(
                                    "Retired unreachable Discord terminal delivery for %s",
                                    work_id,
                                )
                            return
                        timeout_check = getattr(adapter, "_is_timeout_error", None)
                        timed_out = bool(
                            callable(timeout_check) and timeout_check(error_text)
                        )
                        confirmed_ids = get_confirmed_message_ids(result)
                        unsafe_failure = bool(
                            confirmed_ids
                            or not is_logical_send_retry_safe(result)
                            or timed_out
                        )
                        if unsafe_failure:
                            reason = (
                                "partial_send_confirmed"
                                if confirmed_ids
                                else "send_timeout_outcome_unknown"
                                if timed_out
                                else "send_attempt_outcome_unknown"
                            )
                            uncertain = await asyncio.to_thread(
                                ledger.mark_terminal_delivery_uncertain,
                                work_id,
                                owner=delivery_owner,
                                reason=reason,
                                result_message_id=(
                                    str(getattr(result, "message_id", "") or "") or None
                                ),
                                confirmed_message_ids=confirmed_ids,
                            )
                            if not uncertain:
                                return
                            item = ledger.get(work_id) or item
                            delivery_status = "uncertain"
                        else:
                            await asyncio.to_thread(
                                ledger.release_terminal_delivery,
                                work_id,
                                owner=delivery_owner,
                            )
                            self._schedule_terminal_delivery_retry(
                                work_id,
                                attempt=_delivery_retry_attempt + 1,
                            )
                            return
                    else:
                        try:
                            persisted = await asyncio.to_thread(
                                ledger.mark_terminal_response_delivered,
                                work_id,
                                owner=delivery_owner,
                                result_message_id=(
                                    str(getattr(result, "message_id", "") or "") or None
                                ),
                                confirmed_message_ids=get_confirmed_message_ids(result),
                            )
                        except Exception:
                            # Crash-window injection and real persistence failures
                            # intentionally leave the durable `sending` attempt for
                            # expiry recovery to convert to `uncertain`.
                            logger.warning(
                                "Terminal response sent but receipt persistence failed for %s",
                                work_id,
                            )
                            return
                        if not persisted:
                            return
            try:
                summary_ok = await self._update_discord_summaries(
                    source=event.source,
                    feature_summary=item.get("feature_summary"),
                    project_summary=item.get("project_summary"),
                    final_response=final_response,
                    status=str(item.get("summary_status") or "Blocked"),
                    session_id=item.get("session_id"),
                    title=item.get("title"),
                    runtime_breakdown=(
                        item.get("runtime_breakdown")
                        if isinstance(item.get("runtime_breakdown"), dict)
                        else None
                    ),
                )
            except Exception:
                summary_ok = False
            if summary_ok:
                await asyncio.to_thread(
                    ledger.complete_terminal_delivery,
                    work_id,
                    owner=delivery_owner,
                )
            else:
                await asyncio.to_thread(
                    ledger.release_terminal_delivery,
                    work_id,
                    owner=delivery_owner,
                )
                self._schedule_terminal_delivery_retry(
                    work_id,
                    attempt=_delivery_retry_attempt + 1,
                )
            return

        if status == "agent_done":
            final_response = str(item.get("final_response") or "")
            if not final_response:
                if not item.get("feature_summary") and not item.get("project_summary"):
                    logger.warning("Finished Discord work item %s has no final response", work_id)
                    return
            else:
                try:
                    metadata = {"notify": True}
                    try:
                        from gateway.platforms.base import _reply_anchor_for_event, _thread_metadata_for_source

                        metadata = _thread_metadata_for_source(
                            event.source,
                            _reply_anchor_for_event(event),
                        ) or {}
                        metadata = dict(metadata)
                        metadata["notify"] = True
                        reply_to = _reply_anchor_for_event(event)
                    except Exception:
                        reply_to = item.get("reply_to_message_id") or item.get("message_id")
                    began = await asyncio.to_thread(
                        ledger.mark_response_delivery_started,
                        work_id,
                        expected_run_state=expected_run_state,
                    )
                    if not began:
                        return
                    result = await adapter._send_with_retry(
                        chat_id=event.source.chat_id,
                        content=final_response,
                        reply_to=reply_to,
                        metadata=metadata,
                    )
                except asyncio.CancelledError:
                    await asyncio.to_thread(
                        ledger.mark_response_delivery_uncertain,
                        work_id,
                        reason="send_attempt_outcome_unknown",
                        expected_run_state=expected_run_state,
                    )
                    raise
                except Exception as exc:
                    await asyncio.to_thread(
                        ledger.mark_response_delivery_uncertain,
                        work_id,
                        reason="send_attempt_outcome_unknown",
                        expected_run_state=expected_run_state,
                    )
                    logger.warning("Failed to deliver finished Discord work item %s: %s", work_id, exc)
                    return
                if not getattr(result, "success", False):
                    logger.warning(
                        "Failed to deliver finished Discord work item %s: %s",
                        work_id,
                        getattr(result, "error", None),
                    )
                    error_text = str(getattr(result, "error", "") or "")
                    timeout_check = getattr(adapter, "_is_timeout_error", None)
                    timed_out = bool(callable(timeout_check) and timeout_check(error_text))
                    confirmed_ids = get_confirmed_message_ids(result)
                    if not (
                        confirmed_ids
                        or not is_logical_send_retry_safe(result)
                        or timed_out
                    ):
                        await asyncio.to_thread(
                            ledger.release_response_delivery_attempt,
                            work_id,
                            expected_run_state=expected_run_state,
                        )
                        return
                    reason = (
                        "partial_send_confirmed"
                        if confirmed_ids
                        else "send_timeout_outcome_unknown"
                        if timed_out
                        else "send_attempt_outcome_unknown"
                    )
                    if not ledger.mark_response_delivery_uncertain(
                        work_id,
                        result_message_id=(
                            str(getattr(result, "message_id", "") or "") or None
                        ),
                        confirmed_message_ids=confirmed_ids,
                        reason=reason,
                        expected_run_state=expected_run_state,
                    ):
                        return
                    item = ledger.get(work_id) or item
                    expected_run_state = {
                        **expected_run_state,
                        "status": "response_delivered",
                    }
                elif ledger.mark_response_delivered(
                    work_id,
                    result_message_id=str(getattr(result, "message_id", "") or "") or None,
                    confirmed_message_ids=get_confirmed_message_ids(result),
                    expected_run_state=expected_run_state,
                ):
                    expected_run_state = {
                        **expected_run_state,
                        "status": "response_delivered",
                    }
                else:
                    return

        summary_ok = await self._update_discord_summaries(
            source=event.source,
            feature_summary=item.get("feature_summary"),
            project_summary=item.get("project_summary"),
            final_response=str(item.get("final_response") or ""),
            status=str(item.get("summary_status") or "Complete"),
            session_id=item.get("session_id"),
            title=item.get("title"),
            runtime_breakdown=item.get("runtime_breakdown") if isinstance(item.get("runtime_breakdown"), dict) else None,
        )
        if summary_ok:
            if item.get("feature_summary") or item.get("project_summary"):
                if not ledger.mark_summary_updated(
                    work_id,
                    expected_run_state=expected_run_state,
                ):
                    return
                expected_run_state = {
                    **expected_run_state,
                    "status": "summary_updated",
                }
            gate = item.get("completion_gate") if isinstance(item.get("completion_gate"), dict) else {}
            if gate and not gate.get("allowed_to_complete"):
                ledger.mark_blocked(work_id, reason=str(gate.get("reason") or "completion_gate"))
            else:
                ledger.mark_completed(
                    work_id,
                    expected_run_state=expected_run_state,
                )

    async def start(self) -> bool:
        """
        Start the gateway and all configured platform adapters.

        Returns True if at least one adapter connected successfully.
        """
        logger.info("Starting Hermes Gateway...")
        try:
            self._gateway_loop = asyncio.get_running_loop()
        except RuntimeError:
            self._gateway_loop = None
        # Partial/test construction can bypass __init__. Keep lifecycle-owned
        # recovery identity available before any startup reconciliation runs.
        self._process_epoch = str(
            getattr(self, "_process_epoch", _GATEWAY_PROCESS_EPOCH)
            or _GATEWAY_PROCESS_EPOCH
        )
        if await self._abort_startup_if_shutdown_requested():
            return True
        logger.info("Session storage: %s", self.config.sessions_dir)
        try:
            from hermes_cli.worktree_runtime import maybe_cleanup_terminal_action_worktrees

            cleanup_result = await asyncio.to_thread(
                maybe_cleanup_terminal_action_worktrees,
                self.work_ledger,
                _load_gateway_runtime_config(),
                _DISCORD_ACTION_WORKTREE_ROOT,
            )
            if cleanup_result.get("removed"):
                logger.info(
                    "Action worktree cleanup removed %d old terminal worktree(s)",
                    len(cleanup_result["removed"]),
                )
            if cleanup_result.get("errors"):
                logger.warning(
                    "Action worktree cleanup encountered %d error(s)",
                    len(cleanup_result["errors"]),
                )
        except Exception as exc:
            logger.debug("Action worktree cleanup skipped: %s", exc)

        # Sanity-check that systemd's TimeoutStopSec covers our drain
        # window.  When the user upgraded hermes-agent without re-running
        # ``hermes setup``, their unit file may still encode the old
        # default — in which case SIGKILL hits mid-drain and looks like
        # a phantom kill in the journal.  Best-effort, never raises.
        try:
            from gateway.shutdown_forensics import check_systemd_timing_alignment
            _alignment = check_systemd_timing_alignment(self._restart_drain_timeout)
            if _alignment is not None and _alignment.get("mismatch"):
                logger.warning(
                    "Stale systemd unit detected: %s has TimeoutStopSec=%.0fs but "
                    "drain_timeout=%.0fs (expected >=%.0fs). systemd may SIGKILL the "
                    "gateway mid-drain. Run `hermes gateway service install --replace` "
                    "to regenerate the unit, or shorten agent.restart_drain_timeout.",
                    _alignment.get("unit", "(unknown)"),
                    _alignment["timeout_stop_sec"],
                    _alignment["drain_timeout"],
                    _alignment["expected_min"],
                )
        except Exception as _e:
            logger.debug("check_systemd_timing_alignment failed: %s", _e)
        # Log the resolved max_iterations budget so operators can verify the
        # config.yaml → env bridge did the right thing at a glance (instead
        # of silently running at a stale .env value for weeks).
        try:
            _effective_max_iter, _max_iter_source = _current_max_iterations_with_source()
            logger.info(
                "Agent budget: max_iterations=%d source=%s route=gateway/startup",
                _effective_max_iter,
                _max_iter_source,
            )
        except Exception:
            pass
        # Redaction status: ON by default (#17691). Surface a prominent
        # warning if an operator has explicitly opted out so they don't
        # forget the downgrade is active — the redactor snapshots its
        # state at import time, so this log line is the source of truth
        # for this process's lifetime.
        try:
            _redact_raw = os.getenv("HERMES_REDACT_SECRETS", "true")
            _redact_on = _redact_raw.lower() in {"1", "true", "yes", "on"}
            if _redact_on:
                logger.info(
                    "Secret redaction: ENABLED (tool output, logs, and chat "
                    "responses are scrubbed before delivery)"
                )
            else:
                logger.warning(
                    "Secret redaction: DISABLED (HERMES_REDACT_SECRETS=%s). "
                    "API keys and tokens may appear verbatim in chat output, "
                    "session JSONs, and logs. Set security.redact_secrets: true "
                    "in config.yaml to re-enable.",
                    _redact_raw,
                )
        except Exception:
            pass
        try:
            from hermes_cli.profiles import get_active_profile_name
            _profile = get_active_profile_name()
            if _profile and _profile != "default":
                logger.info("Active profile: %s", _profile)
        except Exception:
            pass
        try:
            from gateway.status import write_runtime_status
            write_runtime_status(gateway_state="starting", exit_reason=None)
        except Exception:
            pass

        # Log any active supply-chain security advisories. Operators see this
        # in gateway.log and `hermes status` surfaces it; we do NOT block
        # startup or surface it inline to user messages, since the gateway
        # operator is the one who can act on it (uninstall the package,
        # rotate credentials).  See hermes_cli/security_advisories.py.
        try:
            from hermes_cli.security_advisories import (
                detect_compromised,
                gateway_log_message,
            )
            _adv_hits = detect_compromised()
            _adv_msg = gateway_log_message(_adv_hits)
            if _adv_msg:
                logger.warning("%s", _adv_msg)
                logger.warning(
                    "Run `hermes doctor` on the gateway host for full "
                    "remediation steps."
                )
        except Exception:
            logger.debug(
                "security advisory check failed at gateway startup",
                exc_info=True,
            )

        # Warn if no user allowlists are configured and open access is not opted in
        _builtin_allowed_vars = (
            "TELEGRAM_ALLOWED_USERS", "DISCORD_ALLOWED_USERS",
            "WHATSAPP_ALLOWED_USERS", "SLACK_ALLOWED_USERS",
            "SIGNAL_ALLOWED_USERS", "SIGNAL_GROUP_ALLOWED_USERS",
            "TELEGRAM_GROUP_ALLOWED_USERS",
            "TELEGRAM_GROUP_ALLOWED_CHATS",
            "EMAIL_ALLOWED_USERS",
            "SMS_ALLOWED_USERS", "MATTERMOST_ALLOWED_USERS",
            "MATRIX_ALLOWED_USERS", "DINGTALK_ALLOWED_USERS",
            "FEISHU_ALLOWED_USERS",
            "WECOM_ALLOWED_USERS",
            "WECOM_CALLBACK_ALLOWED_USERS",
            "WEIXIN_ALLOWED_USERS",
            "BLUEBUBBLES_ALLOWED_USERS",
            "QQ_ALLOWED_USERS",
            "YUANBAO_ALLOWED_USERS",
            "GATEWAY_ALLOWED_USERS",
        )
        _builtin_allow_all_vars = (
            "TELEGRAM_ALLOW_ALL_USERS", "DISCORD_ALLOW_ALL_USERS",
            "WHATSAPP_ALLOW_ALL_USERS", "SLACK_ALLOW_ALL_USERS",
            "SIGNAL_ALLOW_ALL_USERS", "EMAIL_ALLOW_ALL_USERS",
            "SMS_ALLOW_ALL_USERS", "MATTERMOST_ALLOW_ALL_USERS",
            "MATRIX_ALLOW_ALL_USERS", "DINGTALK_ALLOW_ALL_USERS",
            "FEISHU_ALLOW_ALL_USERS",
            "WECOM_ALLOW_ALL_USERS",
            "WECOM_CALLBACK_ALLOW_ALL_USERS",
            "WEIXIN_ALLOW_ALL_USERS",
            "BLUEBUBBLES_ALLOW_ALL_USERS",
            "QQ_ALLOW_ALL_USERS",
            "YUANBAO_ALLOW_ALL_USERS",
        )
        # Also pick up plugin-registered platforms — each entry can declare
        # its own allowed_users_env / allow_all_env, so the warning stays
        # accurate as plugins like IRC come online.
        _plugin_allowed_vars: tuple = ()
        _plugin_allow_all_vars: tuple = ()
        try:
            from gateway.platform_registry import platform_registry
            _plugin_allowed_vars = tuple(
                e.allowed_users_env for e in platform_registry.plugin_entries()
                if e.allowed_users_env
            )
            _plugin_allow_all_vars = tuple(
                e.allow_all_env for e in platform_registry.plugin_entries()
                if e.allow_all_env
            )
        except Exception:
            pass
        _any_allowlist = any(
            os.getenv(v) for v in _builtin_allowed_vars + _plugin_allowed_vars
        )
        _allow_all = os.getenv("GATEWAY_ALLOW_ALL_USERS", "").lower() in {"true", "1", "yes"} or any(
            os.getenv(v, "").lower() in {"true", "1", "yes"}
            for v in _builtin_allow_all_vars + _plugin_allow_all_vars
        )
        if not _any_allowlist and not _allow_all:
            logger.warning(
                "No user allowlists configured. All unauthorized users will be denied. "
                "Set GATEWAY_ALLOW_ALL_USERS=true in ~/.hermes/.env to allow open access, "
                "or configure platform allowlists (e.g., TELEGRAM_ALLOWED_USERS=your_id)."
            )

        # Discover Python plugins before shell hooks so plugin block
        # decisions take precedence in tie cases.  The CLI startup path
        # does this via an explicit call in hermes_cli/main.py; the
        # gateway lazily imports run_agent inside per-request handlers,
        # so the discover_plugins() side-effect in model_tools.py is NOT
        # guaranteed to have run by the time we reach this point.
        try:
            from hermes_cli.plugins import discover_plugins
            discover_plugins()
        except Exception:
            logger.warning(
                "plugin discovery failed at gateway startup", exc_info=True,
            )

        # Register declarative shell hooks from cli-config.yaml.  Gateway
        # has no TTY, so consent has to come from one of the three opt-in
        # channels (--accept-hooks on launch, HERMES_ACCEPT_HOOKS env var,
        # or hooks_auto_accept: true in config.yaml).  We pass
        # accept_hooks=False here and let register_from_config resolve
        # the effective value from env + config itself — the CLI-side
        # registration already honored --accept-hooks, and re-reading
        # hooks_auto_accept here would just duplicate that lookup.
        # Failures are logged but must never block gateway startup.
        try:
            from hermes_cli.config import load_config
            from agent.shell_hooks import register_from_config
            register_from_config(load_config(), accept_hooks=False)
        except Exception:
            logger.debug(
                "shell-hook registration failed at gateway startup",
                exc_info=True,
            )

        # Discover and load event hooks
        self.hooks.discover_and_load()


        # Recover background processes from checkpoint (crash recovery)
        try:
            from tools.process_registry import process_registry
            recovered = process_registry.recover_from_checkpoint()
            if recovered:
                logger.info("Recovered %s background process(es) from previous run", recovered)
        except Exception as e:
            logger.warning("Process checkpoint recovery: %s", e)

        # Mark sessions that were active when the gateway last exited as
        # resume-pending.  Stuck-loop detection below still suspends sessions
        # after repeated restart failures, but the first recovery attempt now
        # preserves the transcript and auto-continues the interrupted turn.
        #
        # SKIP suspension after a clean (graceful) shutdown — the previous
        # process already drained active agents, so sessions aren't stuck.
        # This prevents unwanted auto-resets after `hermes update`,
        # `hermes gateway restart`, or `/restart`.
        _clean_marker = _hermes_home / ".clean_shutdown"
        if _clean_marker.exists():
            logger.info("Previous gateway exited cleanly — skipping restart recovery")
            try:
                _clean_marker.unlink()
            except Exception:
                pass
        else:
            try:
                suspended = await self.async_session_store.suspend_recently_active()
                if suspended:
                    logger.info("Marked %d in-flight session(s) as resumable from previous run", suspended)
            except Exception as e:
                logger.warning("Session restart-recovery marking failed: %s", e)

        # Stuck-loop detection (#7536): if a session has been active across
        # 3+ consecutive restarts, it's probably stuck in a loop (the same
        # history keeps causing the agent to hang).  Auto-suspend it so the
        # user gets a clean slate on the next message.
        try:
            stuck = self._suspend_stuck_loop_sessions()
            if stuck:
                logger.warning("Auto-suspended %d stuck-loop session(s)", stuck)
        except Exception as e:
            logger.debug("Stuck-loop detection failed: %s", e)

        # Platform adapters can receive real inbound messages as soon as they
        # connect. Hold those turns until restart-interrupted sessions have
        # completed their synthetic startup resume pass.
        self._startup_restore_in_progress = True
        self._startup_restore_queue = []
        self._startup_restore_tasks = []
        self._startup_restore_typing_tasks = {}

        connected_count = 0
        enabled_platform_count = 0
        startup_nonretryable_errors: list[str] = []
        startup_retryable_errors: list[str] = []

        # Initialize and connect each configured platform
        for platform, platform_config in self.config.platforms.items():
            if not platform_config.enabled:
                continue
            enabled_platform_count += 1

            adapter = self._create_adapter(platform, platform_config)
            if not adapter:
                # Distinguish between missing builtin deps and missing plugin
                _pval = platform.value
                _builtin_names = {m.value for m in Platform.__members__.values()}
                if _pval not in _builtin_names:
                    logger.warning(
                        "No adapter for '%s' — is the plugin installed? "
                        "(platform is enabled in config.yaml but no plugin registered it)",
                        _pval,
                    )
                else:
                    logger.warning("No adapter available for %s", _pval)
                continue

            # Set up message + fatal error handlers
            adapter.set_message_handler(self._handle_message)
            adapter.set_fatal_error_handler(self._handle_adapter_fatal_error)
            adapter.set_session_store(self.session_store)
            adapter.set_busy_session_handler(self._handle_active_session_busy_message)
            adapter.set_topic_recovery_fn(self._recover_telegram_topic_thread_id)
            adapter._busy_text_mode = self._busy_text_mode

            # Try to connect
            logger.info("Connecting to %s...", platform.value)
            self._update_platform_runtime_status(
                platform.value,
                platform_state="connecting",
                error_code=None,
                error_message=None,
            )
            try:
                success = await self._connect_adapter_with_timeout(adapter, platform)
                if await self._abort_startup_if_shutdown_requested(adapter, platform):
                    return True
                if success:
                    self.adapters[platform] = adapter
                    self._install_background_worker_reaction_gate(adapter)
                    self._sync_voice_mode_state_to_adapter(adapter)
                    connected_count += 1
                    self._update_platform_runtime_status(
                        platform.value,
                        platform_state="connected",
                        error_code=None,
                        error_message=None,
                    )
                    logger.info("✓ %s connected", platform.value)
                else:
                    logger.warning("✗ %s failed to connect", platform.value)
                    # Defensive cleanup: a failed connect() may have
                    # allocated resources (aiohttp.ClientSession, poll
                    # tasks, bridge subprocesses) before giving up.
                    # Without this call, those resources are orphaned
                    # and Python logs "Unclosed client session" at
                    # process exit. Adapter disconnect() implementations
                    # are expected to be idempotent and tolerate
                    # partial-init state.
                    await self._safe_adapter_disconnect(adapter, platform)
                    if adapter.has_fatal_error:
                        self._update_platform_runtime_status(
                            platform.value,
                            platform_state="retrying" if adapter.fatal_error_retryable else "fatal",
                            error_code=adapter.fatal_error_code,
                            error_message=adapter.fatal_error_message,
                        )
                        target = (
                            startup_retryable_errors
                            if adapter.fatal_error_retryable
                            else startup_nonretryable_errors
                        )
                        target.append(
                            f"{platform.value}: {adapter.fatal_error_message}"
                        )
                        # Queue for reconnection if the error is retryable
                        if adapter.fatal_error_retryable:
                            self._failed_platforms[platform] = {
                                "config": platform_config,
                                "attempts": 1,
                                "next_retry": time.monotonic() + 30,
                            }
                    else:
                        self._update_platform_runtime_status(
                            platform.value,
                            platform_state="retrying",
                            error_code=None,
                            error_message="failed to connect",
                        )
                        startup_retryable_errors.append(
                            f"{platform.value}: failed to connect"
                        )
                        # No fatal error info means likely a transient issue — queue for retry
                        self._failed_platforms[platform] = {
                            "config": platform_config,
                            "attempts": 1,
                            "next_retry": time.monotonic() + 30,
                        }
            except Exception as e:
                logger.error("✗ %s error: %s", platform.value, e)
                # Same defensive cleanup path for exceptions — an adapter
                # that raised mid-connect may still have a live
                # aiohttp.ClientSession or child subprocess.
                await self._safe_adapter_disconnect(adapter, platform)
                self._update_platform_runtime_status(
                    platform.value,
                    platform_state="retrying",
                    error_code=None,
                    error_message=str(e),
                )
                startup_retryable_errors.append(f"{platform.value}: {e}")
                # Unexpected exceptions are typically transient — queue for retry
                self._failed_platforms[platform] = {
                    "config": platform_config,
                    "attempts": 1,
                    "next_retry": time.monotonic() + 30,
                }
            if await self._abort_startup_if_shutdown_requested():
                return True

        # Multi-profile multiplexing: bring up non-active profile adapters
        # under their own HERMES_HOME + secret scope. No-op unless configured.
        try:
            connected_count += await self._start_secondary_profile_adapters()
        except MultiplexConfigError as e:
            reason = str(e)
            logger.error("Gateway multiplexer config error: %s", reason)
            try:
                from gateway.status import write_runtime_status
                write_runtime_status(gateway_state="startup_failed", exit_reason=reason)
            except Exception:
                pass
            self._request_clean_exit(reason)
            return True
        except Exception as e:
            logger.error("Secondary-profile adapter startup failed: %s", e, exc_info=True)

        if await self._abort_startup_if_shutdown_requested():
            return True

        if connected_count == 0:
            if startup_nonretryable_errors:
                reason = "; ".join(startup_nonretryable_errors)
                logger.error("Gateway hit a non-retryable startup conflict: %s", reason)
                try:
                    from gateway.status import write_runtime_status
                    write_runtime_status(gateway_state="startup_failed", exit_reason=reason)
                except Exception:
                    pass
                self._exit_code = GATEWAY_FATAL_CONFIG_EXIT_CODE
                self._request_clean_exit(reason)
                return True
            if enabled_platform_count > 0:
                if startup_retryable_errors:
                    # All enabled platforms hit retryable failures (network
                    # blip, bridge not paired, npm install timeout, etc.).
                    # Keep the gateway alive so:
                    #   • cron jobs still run
                    #   • the reconnect watcher gets a chance to recover the
                    #     failing platforms once the underlying problem is
                    #     fixed (e.g. user runs `hermes whatsapp`, fixes
                    #     proxy, etc.)
                    # Exiting here used to convert a single misconfigured
                    # platform into an infinite systemd restart loop.
                    reason = "; ".join(startup_retryable_errors)
                    logger.warning(
                        "Gateway started with no connected platforms — "
                        "%d platform(s) queued for retry: %s",
                        len(self._failed_platforms), reason,
                    )
                    try:
                        from gateway.status import write_runtime_status
                        write_runtime_status(
                            gateway_state="degraded",
                            exit_reason=None,
                        )
                    except Exception:
                        pass
                    # Fall through to the normal "running" state — reconnect
                    # watcher takes it from here.
                # All enabled platforms had no adapter (missing library or credentials).
                # In fleet deployments the same config.yaml is shared across nodes that
                # may only have credentials for a subset of platforms.  Rather than
                # failing hard, degrade gracefully and allow cron jobs to run (#5196).
                logger.warning(
                    "No adapter could be created for any of the %d configured platform(s). "
                    "Check that required dependencies are installed and credentials are set. "
                    "Gateway will continue for cron job execution.",
                    enabled_platform_count,
                )
            else:
                logger.warning("No messaging platforms enabled.")
                logger.info("Gateway will continue running for cron job execution.")

        # Update delivery router with adapters
        if await self._abort_startup_if_shutdown_requested():
            return True
        self.delivery_router.adapters = self.adapters
        self._wire_teams_pipeline_runtime()

        self._running = True
        self._update_runtime_status("running")

        # Emit gateway:startup hook
        hook_count = len(self.hooks.loaded_hooks)
        if hook_count:
            logger.info("%s hook(s) loaded", hook_count)
        await self.hooks.emit("gateway:startup", {
            "platforms": [p.value for p in self.adapters.keys()],
        })

        if connected_count > 0:
            logger.info("Gateway running with %s platform(s)", connected_count)

        # Build initial channel directory for send_message name resolution
        try:
            from gateway.channel_directory import build_channel_directory
            directory = await build_channel_directory(self.adapters)
            ch_count = sum(len(chs) for chs in directory.get("platforms", {}).values())
            logger.info("Channel directory built: %d target(s)", ch_count)
        except Exception as e:
            logger.warning("Channel directory build failed: %s", e)

        # Check if we're restarting after a /update command. If the update is
        # still running, keep watching so we notify once it actually finishes.
        notified = await self._send_update_notification()
        if not notified and any(
            path.exists()
            for path in (
                _hermes_home / ".update_pending.json",
                _hermes_home / ".update_pending.claimed.json",
            )
        ):
            self._schedule_update_notification_watch()

        # Give freshly connected platform adapters a brief moment to settle
        # before sending restart/startup lifecycle messages. In practice this
        # helps Discord thread deliveries right after reconnect.
        if connected_count > 0:
            await asyncio.sleep(1.0)

        # Chat-originated /restart has one precise claimant: the originating
        # chat/topic. Planned terminal/service restarts may use home channels.
        # Never broadcast both lifecycle notices for the same restart.
        chat_restart_notification_pending = _restart_notification_pending()
        planned_restart_notification_pending = (
            _planned_restart_notification_pending()
        )
        if chat_restart_notification_pending:
            self._booted_from_restart = True
        await self._send_restart_notification()
        if planned_restart_notification_pending:
            try:
                await self._send_home_channel_startup_notifications(
                    skip_targets=None,
                )
            finally:
                _clear_planned_restart_notification()

        # Establish durable async/closeout ownership before considering any
        # original-intake or session replay. Required coding Worker Runs are
        # enumerated as a set, then reattached/resumed/relaunched from their
        # stable dispatch records. Unsafe ambiguity is surfaced by the ledger;
        # it must never become an arbitrary tool-capable parent replay.
        try:
            recovered_required = await asyncio.to_thread(
                self._recover_durable_coding_workers,
            )
        except Exception:
            recovered_required = {"failed": 1}
            logger.exception("Durable coding-worker startup recovery failed")
        if any(int(recovered_required.get(key) or 0) for key in (
            "launched", "waiting_alive", "manual_fallback", "failed"
        )):
            logger.warning(
                "Durable coding-worker startup recovery: launched=%d waiting=%d "
                "manual_fallback=%d failed=%d",
                int(recovered_required.get("launched") or 0),
                int(recovered_required.get("waiting_alive") or 0),
                int(recovered_required.get("manual_fallback") or 0),
                int(recovered_required.get("failed") or 0),
            )
        await self._send_durable_coding_worker_recovery_notices(
            recovered_required.get("notices") or []
        )
        if self._durable_coding_worker_recovery_needs_retry(recovered_required):
            self._start_owned_runner(
                "durable-coding-worker-recovery",
                self._durable_coding_worker_reconciler,
            )
        self._start_owned_runner(
            "required-async-reconciler",
            self._required_async_reconciler,
            restart_on_exit=True,
        )

        closeout_watcher = getattr(self, "trusted_closeout_watcher", None)
        if closeout_watcher is not None:
            if self._ledger().pending_closeouts():
                closeout_watcher.notify()
            self._start_owned_runner(
                "trusted-closeout-watcher",
                self._trusted_closeout_watcher,
                restart_on_exit=True,
            )
        self._start_owned_runner(
            "action-worktree-cleanup",
            self._action_worktree_cleanup_watcher,
            restart_on_exit=True,
        )
        self._schedule_incomplete_discord_work_items()

        # Fulfil any ordinary final-response transport obligations before
        # considering model replay. A recovered delivery clears that session's
        # resume marker; fork-managed work items never enter this ledger.
        await self._redeliver_pending_obligations()

        # Automatically continue only genuinely interrupted model work. The
        # helper excludes sessions now owned by authoritative closeout.
        self._schedule_resume_pending_sessions()
        await self._finish_startup_restore()

        # Drain any recovered process watchers (from crash recovery checkpoint)
        try:
            from tools.process_registry import process_registry
            while process_registry.pending_watchers:
                watcher = process_registry.pending_watchers.pop(0)
                asyncio.create_task(self._run_process_watcher(watcher))
                logger.info("Resumed watcher for recovered process %s", watcher.get("session_id"))
        except Exception as e:
            logger.error("Recovered watcher setup error: %s", e)

        # Start background session expiry watcher to finalize expired sessions
        asyncio.create_task(self._session_expiry_watcher())

        # Start background kanban notifier — delivers `completed`, `blocked`,
        # `spawn_auto_blocked`, and `crashed` events to gateway subscribers
        # so human-in-the-loop workflows hear back without polling.
        asyncio.create_task(self._kanban_notifier_watcher())

        # Start background kanban dispatcher — spawns workers for ready
        # tasks. Gated by `kanban.dispatch_in_gateway` (default True).
        # When false, users run `hermes kanban daemon` externally or
        # simply don't use kanban; this loop becomes a no-op.
        asyncio.create_task(self._kanban_dispatcher_watcher())

        # Pulse Discord's native typing indicator while Discord thread-backed
        # Kanban workers are active. This is independent from dispatcher
        # ownership so external dispatchers still surface activity.
        asyncio.create_task(self._discord_kanban_typing_watcher())

        # Optional Discord worker foreman alerts. Disabled by default and
        # gated inside the watcher so non-Discord gateways do no work.
        asyncio.create_task(self._discord_worker_foreman_watcher())

        # Start background reconnection watcher for platforms that failed at startup
        if self._failed_platforms:
            logger.info(
                "Starting reconnection watcher for %d failed platform(s): %s",
                len(self._failed_platforms),
                ", ".join(p.value for p in self._failed_platforms),
            )
        asyncio.create_task(self._platform_reconnect_watcher())

        # Start background handoff watcher — picks up CLI sessions marked
        # handoff_state='pending' in state.db and re-binds them to the
        # destination platform's home channel, then forges a synthetic user
        # turn so the agent kicks off the new chat.
        asyncio.create_task(self._handoff_watcher())

        # Discord work-item completions only wake deterministic attempt-level
        # reconciliation. Legacy non-work-item delegations retain best-effort
        # fresh turns; the ledger scan repairs lost durable queue wakeups.
        self._start_owned_runner(
            "async-delegation-notifications",
            self._async_delegation_watcher,
        )

        logger.info("Press Ctrl+C to stop")

        return True

    async def _action_worktree_cleanup_watcher(self) -> None:
        """Periodically reclaim old terminal Discord action worktrees."""

        from hermes_cli.worktree_runtime import (
            maybe_cleanup_terminal_action_worktrees,
            terminal_action_cleanup_interval_seconds,
        )

        while self._running:
            config = _load_gateway_runtime_config()
            interval = terminal_action_cleanup_interval_seconds(config)
            try:
                await asyncio.wait_for(self._shutdown_event.wait(), timeout=interval)
                return
            except TimeoutError:
                pass
            try:
                result = await asyncio.to_thread(
                    maybe_cleanup_terminal_action_worktrees,
                    self.work_ledger,
                    config,
                    _DISCORD_ACTION_WORKTREE_ROOT,
                )
            except Exception:
                logger.debug("Periodic action worktree cleanup failed", exc_info=True)
                continue
            removed = result.get("removed") if isinstance(result, dict) else None
            errors = result.get("errors") if isinstance(result, dict) else None
            if removed:
                logger.info(
                    "Periodic action worktree cleanup removed %d worktree(s)",
                    len(removed),
                )
            if errors:
                logger.warning(
                    "Periodic action worktree cleanup encountered %d error(s)",
                    len(errors),
                )

    async def _on_trusted_closeout_preview(self, item: Dict[str, Any]) -> None:
        """Deliver the exact-head preview before background visual QA finishes."""

        work_id = str(item.get("id") or "")
        if not work_id:
            return
        owner = f"gateway-preview:{os.getpid()}:{time.time_ns()}"
        claimed = await asyncio.to_thread(
            self._ledger().claim_preview_delivery,
            work_id,
            owner=owner,
        )
        if claimed is None:
            return
        delivery = (
            claimed.get("preview_delivery")
            if isinstance(claimed.get("preview_delivery"), dict)
            else {}
        )
        try:
            event = self._ledger().event_from_item(claimed)
        except Exception:
            await asyncio.to_thread(
                self._ledger().fail_preview_delivery,
                work_id,
                owner=owner,
                uncertain=False,
            )
            return
        adapter = self._adapter_for_source(event.source)
        if adapter is None:
            await asyncio.to_thread(
                self._ledger().fail_preview_delivery,
                work_id,
                owner=owner,
                uncertain=False,
            )
            return
        began = await asyncio.to_thread(
            self._ledger().begin_preview_send_attempt,
            work_id,
            owner=owner,
        )
        if not began:
            return
        content = (
            f"Feature preview is ready for {delivery.get('pr_url')}:\n\n"
            f"{delivery.get('preview_url')}\n\n"
            "Visual QA is running in the background; I’ll post the result here. "
            "If the PR changes, its newer preview will get a separate message."
        )
        try:
            from gateway.platforms.base import _reply_anchor_for_event, _thread_metadata_for_source

            reply_to = _reply_anchor_for_event(event)
            metadata = _thread_metadata_for_source(event.source, reply_to) or {}
            metadata = dict(metadata)
            metadata["notify"] = True
            result = await adapter._send_with_retry(
                chat_id=event.source.chat_id,
                content=content,
                reply_to=reply_to,
                metadata=metadata,
            )
        except Exception:
            await asyncio.to_thread(
                self._ledger().fail_preview_delivery,
                work_id,
                owner=owner,
                uncertain=True,
            )
            return
        if not getattr(result, "success", False):
            await asyncio.to_thread(
                self._ledger().fail_preview_delivery,
                work_id,
                owner=owner,
                uncertain=not is_logical_send_retry_safe(result),
            )
            return
        await asyncio.to_thread(
            self._ledger().complete_preview_delivery,
            work_id,
            owner=owner,
            result_message_id=getattr(result, "message_id", None),
            confirmed_message_ids=get_confirmed_message_ids(result),
        )

    async def _on_trusted_closeout_terminal(self, item: Dict[str, Any]) -> None:
        """Deliver deterministic terminal closeout state through existing paths."""

        work_id = str(item.get("id") or "")
        if work_id and not self._ledger().preview_delivery_satisfied(work_id):
            return
        if str(item.get("status") or "") in {
            "agent_done",
            "response_delivered",
            "summary_updated",
            "blocked",
        }:
            await self._resume_finished_discord_work_item(item)

    async def _trusted_closeout_watcher(self) -> None:
        """Resume persisted lifecycle closeout without replaying model work."""

        watcher = getattr(self, "trusted_closeout_watcher", None)
        if watcher is None:
            return
        try:
            await watcher.run_forever(self._shutdown_event)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Trusted closeout watcher failed")

    @staticmethod
    def _required_async_dispatch_rows(state: Any) -> list[dict[str, Any]]:
        if not isinstance(state, dict):
            return []
        raw = state.get("dispatches")
        if isinstance(raw, dict):
            rows = [
                {"delegation_id": str(delegation_id), **dict(row)}
                for delegation_id, row in raw.items()
                if isinstance(row, dict)
            ]
        elif isinstance(raw, list):
            rows = raw
        else:
            rows = []
        return [dict(row) for row in rows if isinstance(row, dict)]

    @staticmethod
    def _required_async_identity(state: Any) -> dict[str, Any]:
        state = state if isinstance(state, dict) else {}
        return {
            "generation": state.get("generation"),
            "attempt_id": str(state.get("attempt_id") or ""),
            "attempt_order": state.get("attempt_order"),
        }

    def _required_async_turn_identity(
        self,
        run_generation: Any,
    ) -> dict[str, Any]:
        """Return the durable attempt identity shared by parent and workers."""

        try:
            generation = int(run_generation or 0)
        except (TypeError, ValueError, OverflowError):
            generation = 0
        process_epoch = str(getattr(self, "_process_epoch", _GATEWAY_PROCESS_EPOCH))
        self._process_epoch = process_epoch
        try:
            attempt_order = int(process_epoch.split("-", 1)[0]) + max(0, generation)
        except (TypeError, ValueError, OverflowError):
            attempt_order = 0
        return {
            "generation": generation,
            "attempt_id": f"{process_epoch}:{generation}",
            "attempt_order": attempt_order,
        }

    def _seal_required_async_parent_attempt(
        self,
        work_item_id: str,
        *,
        run_generation: Any,
    ) -> Optional[dict[str, Any]]:
        """Close exact dispatch membership after a parent turn exits."""

        if not work_item_id:
            return None
        identity = self._required_async_turn_identity(run_generation)
        try:
            ledger = self._ledger()
            current = ledger.required_async_completion_state(work_item_id)
            if (
                not isinstance(current, dict)
                or str(current.get("attempt_id") or "") != identity["attempt_id"]
                or not current.get("dispatches")
            ):
                return None
            sealed = ledger.seal_required_async_attempt(
                work_item_id,
                **identity,
            )
            if isinstance(sealed, dict):
                self.__dict__.setdefault(
                    "_required_async_reconcile_event",
                    asyncio.Event(),
                ).set()
            return sealed
        except Exception:
            logger.exception(
                "Could not seal required async attempt for %s",
                work_item_id,
            )
            return None

    @staticmethod
    def _required_async_reconciliation_id(
        work_id: str,
        state: Any,
    ) -> str:
        identity = GatewayRunner._required_async_identity(state)
        raw = ":".join(
            (
                str(work_id or ""),
                str(identity.get("generation") or ""),
                str(identity.get("attempt_id") or ""),
                str(identity.get("attempt_order") or ""),
            )
        )
        return "required-async:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]

    @staticmethod
    def _required_async_terminal_summary(
        state: Any,
        *,
        success: bool,
    ) -> str:
        rows = GatewayRunner._required_async_dispatch_rows(state)
        required_summaries: list[str] = []
        required_errors: list[str] = []
        advisory_summaries: list[str] = []
        advisory_errors: list[str] = []
        for row in rows:
            evidence = row.get("evidence") if isinstance(row.get("evidence"), dict) else {}
            if row.get("required") is False or row.get("kind") == "advisory":
                for result in evidence.get("advisory_results") or []:
                    if not isinstance(result, dict):
                        continue
                    summary = str(result.get("summary") or "").strip()
                    error = str(result.get("error") or "").strip()
                    if summary and summary not in advisory_summaries:
                        advisory_summaries.append(summary[:800])
                    if error and error not in advisory_errors:
                        advisory_errors.append(error[:800])
                continue
            summary = str(row.get("summary") or "").strip()
            error = str(row.get("error") or "").strip()
            if summary and summary not in required_summaries:
                required_summaries.append(summary[:800])
            if error and error not in required_errors:
                required_errors.append(error[:800])
        if success:
            sections: list[str] = []
            if isinstance(state, dict) and state.get("has_required"):
                sections.append("Required coding workers completed successfully.")
                if required_summaries:
                    sections.append(
                        "\n".join(f"- {summary}" for summary in required_summaries[:8])
                    )
            else:
                sections.append("Background advisory work completed.")
            if advisory_summaries:
                sections.append(
                    "Advisory results available at completion:\n"
                    + "\n".join(f"- {summary}" for summary in advisory_summaries[:8])
                )
            if advisory_errors:
                sections.append(
                    "Advisory work that did not complete:\n"
                    + "\n".join(f"- {error}" for error in advisory_errors[:8])
                )
            return "\n\n".join(sections)
        if (
            isinstance(state, dict)
            and not state.get("has_required")
            and state.get("advisory_failed")
        ):
            lead = (
                "Background advisory work did not produce a usable result, so the "
                "request was blocked without replaying the task."
            )
        elif isinstance(state, dict) and state.get("required_outcome_unknown"):
            lead = (
                "Required coding work could not be verified after gateway recovery. "
                "At least one worker outcome is unknown, so Hermes did not retry or "
                "replay the work automatically."
            )
        elif isinstance(state, dict) and state.get("required_cancelled"):
            lead = "Required coding work was cancelled and will not be resumed automatically."
        elif isinstance(state, dict) and state.get("malformed"):
            lead = "Required coding work has incomplete durable evidence and was blocked safely."
        else:
            lead = "A required coding worker failed, so the request was blocked safely."
        details = (
            required_errors
            or required_summaries
            or advisory_errors
            or advisory_summaries
        )
        body = "\n".join(f"- {detail}" for detail in details[:8])
        if advisory_summaries and isinstance(state, dict) and state.get("has_required"):
            body += (
                ("\n\n" if body else "")
                + "Advisory results available before the block:\n"
                + "\n".join(f"- {summary}" for summary in advisory_summaries[:8])
            )
        return lead + (f"\n\n{body}" if body else "")

    def _activate_required_async_closeout(
        self,
        work_id: str,
        item: Dict[str, Any],
        required_state: Dict[str, Any],
    ) -> tuple[bool, str]:
        """Activate an existing closeout from bounded worker evidence.

        No model or transcript replay is involved.  Successful worker evidence
        is checked against the fresh, clean exact Git head before the existing
        trusted closeout watcher receives ownership.
        """

        required_reader = getattr(
            self._ledger(),
            "required_async_completion_state",
            None,
        )
        live_state = (
            required_reader(work_id) if callable(required_reader) else required_state
        )
        if (
            not isinstance(live_state, dict)
            or self._required_async_identity(live_state)
            != self._required_async_identity(required_state)
        ):
            return False, "required_async_attempt_changed"
        if live_state.get("attempt_cancelled") is True:
            return False, "required_async_attempt_cancelled"
        required_state = live_state

        closeout_raw = item.get("closeout")
        if not isinstance(closeout_raw, dict):
            return False, "work_item"
        from hermes_cli.trusted_closeout import normalize_closeout_state

        closeout = normalize_closeout_state(closeout_raw)
        if closeout["mode"] != "enforce":
            return False, "work_item"
        if item.get("closeout_authoritative") is True:
            watcher = getattr(self, "trusted_closeout_watcher", None)
            if watcher is not None:
                watcher.notify(work_id)
            return True, "closeout"
        if closeout["source"] not in {"direct", "fable", "opus"}:
            return False, "unsupported_closeout_source"

        rows = sorted(
            [
                row
                for row in self._required_async_dispatch_rows(required_state)
                if row.get("required") is not False
                and row.get("kind") != "advisory"
            ],
            key=lambda row: (
                float(row.get("completed_at") or 0),
                str(row.get("delegation_id") or ""),
            ),
        )
        for row in rows:
            evidence = row.get("evidence") if isinstance(row.get("evidence"), dict) else {}
            scope_check = evidence.get("scope_check")
            if isinstance(scope_check, dict) and (
                scope_check.get("clean") is not True
                or scope_check.get("out_of_scope_files")
                or scope_check.get("inspection_error")
            ):
                return False, "worker_scope_check_failed"
            merge = evidence.get("parallel_merge")
            if isinstance(merge, dict) and (
                merge.get("merged") is not True
                or merge.get("success") is False
                or merge.get("recovery_required") is True
                or merge.get("merge_pending") is True
                or merge.get("error")
            ):
                return False, "parallel_merge_incomplete"
        workspace = str(closeout["workspace"].get("path") or "").strip()
        if not rows or not workspace:
            return False, "missing_dispatch_evidence"
        try:
            import subprocess

            top_level = subprocess.run(
                ["git", "rev-parse", "--show-toplevel"],
                cwd=Path(workspace).expanduser().resolve(strict=False),
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
        except Exception:
            return False, "checkpoint_repository_root_failed"
        repository_root = str(top_level.stdout or "").strip()
        if top_level.returncode != 0 or not repository_root:
            return False, "checkpoint_repository_root_failed"
        verified_head, checkpoint_reason = self._checkpoint_required_async_workspace(
            work_id,
            rows,
            workspace,
            required_state,
        )
        if not verified_head:
            return False, checkpoint_reason
        live_state = (
            required_reader(work_id) if callable(required_reader) else required_state
        )
        if (
            not isinstance(live_state, dict)
            or self._required_async_identity(live_state)
            != self._required_async_identity(required_state)
        ):
            return False, "required_async_attempt_changed"
        if live_state.get("attempt_cancelled") is True:
            return False, "required_async_attempt_cancelled"

        visual_result: dict[str, Any] = {}
        if closeout["policy"]["require_visual_qa"]:
            try:
                from agent.visual_qa import visual_receipt_completion

                completion = visual_receipt_completion(
                    item.get("visual_qa_requirement"),
                    item.get("visual_qa_receipts"),
                    min_order=int(item.get("visual_qa_min_receipt_order") or 0),
                )
            except Exception:
                completion = {"status": "missing"}
            if str(completion.get("status") or "") != "passed":
                return False, "required_visual_qa_missing"
            visual_result = {
                "receipts": item.get("visual_qa_receipts") or [],
                "min_receipt_order": int(item.get("visual_qa_min_receipt_order") or 0),
            }

        activated = self._activate_closeout_at_verified_head(
            work_id,
            repository_root=repository_root,
            verified_head_sha=verified_head,
            visual_result=visual_result,
        )
        return (True, "closeout") if activated is not None else (
            False,
            "workspace_head_not_clean_or_verified",
        )

    def _checkpoint_required_async_workspace(
        self,
        work_id: str,
        rows: list[dict[str, Any]],
        workspace: str,
        required_state: dict[str, Any],
    ) -> tuple[str, str]:
        """Create one trusted local checkpoint for successful async mutation.

        Coding workers are intentionally denied Git lifecycle authority. This
        bridge commits only an exact clean-baseline, scope-checked aggregate in
        the already-resolved action worktree, then hands the resulting head to
        trusted closeout. It never pushes, opens a PR, or invokes a model.
        """

        import subprocess

        workspace_root = Path(str(workspace or "")).expanduser().resolve(strict=False)
        if not workspace_root.is_dir():
            return "", "checkpoint_workspace_missing"

        def run_git(
            args: list[str],
            *,
            cwd: Path | None = None,
            timeout: float = 30.0,
            text: bool = True,
            env: dict[str, str] | None = None,
            input_text: str | None = None,
        ) -> subprocess.CompletedProcess:
            return subprocess.run(
                ["git", *args],
                cwd=cwd or repository_root,
                text=text,
                input=input_text,
                env={**os.environ, **env} if env else None,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=timeout,
                check=False,
            )

        top_level = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=workspace_root,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
            check=False,
        )
        if top_level.returncode != 0:
            return "", "checkpoint_repository_root_failed"
        repository_root = Path(str(top_level.stdout or "").strip()).resolve(strict=False)
        if not repository_root.is_dir():
            return "", "checkpoint_repository_root_failed"
        try:
            workspace_prefix = workspace_root.relative_to(repository_root).as_posix()
        except ValueError:
            return "", "checkpoint_workspace_outside_repository"
        workspace_prefix = "" if workspace_prefix == "." else workspace_prefix.strip("/")

        base_shas: set[str] = set()
        allowed_prefixes: list[str] = []
        for row in rows:
            evidence = row.get("evidence") if isinstance(row.get("evidence"), dict) else {}
            scope_check = evidence.get("scope_check")
            if not isinstance(scope_check, dict) or scope_check.get("clean") is not True:
                return "", "checkpoint_scope_evidence_missing"
            if evidence.get("initial_dirty_paths"):
                return "", "checkpoint_baseline_was_dirty"
            base_sha = str(evidence.get("base_sha") or "").strip().lower()
            if not re.fullmatch(r"[0-9a-f]{40}", base_sha):
                return "", "checkpoint_base_head_missing"
            base_shas.add(base_sha)
            parallel_merge = (
                evidence.get("parallel_merge")
                if isinstance(evidence.get("parallel_merge"), dict)
                else None
            )
            if parallel_merge is not None:
                if parallel_merge.get("merged") is not True:
                    return "", "parallel_merge_incomplete"
                # Isolated workers live in sibling worktrees. Their scope paths
                # are already expressed against the base action workspace that
                # received the trusted merge-back.
                worker_prefix = ""
            else:
                worker_cwd = Path(
                    str(evidence.get("worker_cwd") or workspace_root)
                ).expanduser().resolve(strict=False)
                try:
                    worker_prefix = worker_cwd.relative_to(workspace_root).as_posix()
                    if worker_prefix == ".":
                        worker_prefix = ""
                except ValueError:
                    return "", "checkpoint_worker_outside_workspace"
            scopes = evidence.get("scope_paths") or scope_check.get("scope_paths") or []
            if not scopes:
                return "", "checkpoint_scope_evidence_missing"
            for scope in scopes:
                raw_scope = str(scope or "").replace("\\", "/").strip()
                scope_path = PurePosixPath(raw_scope)
                if (
                    not raw_scope
                    or scope_path.is_absolute()
                    or ".." in scope_path.parts
                ):
                    return "", "checkpoint_scope_evidence_invalid"
                normalized = "" if str(scope_path) == "." else str(scope_path).strip("/")
                prefix = "/".join(
                    part
                    for part in (
                        workspace_prefix,
                        worker_prefix.strip("/"),
                        normalized,
                    )
                    if part
                )
                allowed_prefixes.append(prefix)
        if len(base_shas) != 1:
            return "", "checkpoint_base_head_conflict"
        base_sha = next(iter(base_shas))
        message = f"Hermes async checkpoint {str(work_id or '')}"
        identity = self._required_async_identity(required_state)

        def cancellation_fence() -> str:
            ledger = self._ledger()
            reader = getattr(ledger, "required_async_completion_state", None)
            current = reader(work_id) if callable(reader) else required_state
            if not isinstance(current, dict):
                return "checkpoint_attempt_state_missing"
            if self._required_async_identity(current) != identity:
                return "checkpoint_attempt_changed"
            if current.get("attempt_cancelled") is True:
                return "checkpoint_attempt_cancelled"
            return ""

        cancellation_reason = cancellation_fence()
        if cancellation_reason:
            return "", cancellation_reason
        head = run_git(["rev-parse", "--verify", "HEAD"])
        current_head = str(head.stdout or "").strip().lower()
        if head.returncode != 0 or not re.fullmatch(r"[0-9a-f]{40}", current_head):
            return "", "checkpoint_head_failed"

        def status_snapshot() -> tuple[bytes, list[tuple[str, tuple[str, ...]]]] | None:
            result = run_git(
                ["status", "--porcelain=v1", "-z", "--untracked-files=all"],
                text=False,
            )
            if result.returncode != 0:
                return None
            raw = bytes(result.stdout or b"")
            parts = raw.split(b"\0")
            entries: list[tuple[str, tuple[str, ...]]] = []
            index = 0
            while index < len(parts):
                record = parts[index]
                index += 1
                if not record:
                    continue
                if len(record) < 4:
                    return None
                status_code = record[:2].decode("ascii", "replace")
                first = record[3:].decode("utf-8", "surrogateescape").replace("\\", "/")
                paths = [first.strip("/")]
                if "R" in status_code or "C" in status_code:
                    if index >= len(parts) or not parts[index]:
                        return None
                    paths.append(
                        parts[index]
                        .decode("utf-8", "surrogateescape")
                        .replace("\\", "/")
                        .strip("/")
                    )
                    index += 1
                if not all(paths):
                    return None
                entries.append((status_code, tuple(paths)))
            return raw, entries

        initial_status = status_snapshot()
        if initial_status is None:
            return "", "checkpoint_status_failed"
        _initial_raw, initial_entries = initial_status
        changed_paths = sorted(
            {path for _status_code, paths in initial_entries for path in paths}
        )

        checkpoint = (
            required_state.get("checkpoint")
            if isinstance(required_state.get("checkpoint"), dict)
            else None
        )
        if current_head != base_sha:
            if not isinstance(checkpoint, dict):
                return "", "checkpoint_base_head_moved"
            if (
                str(checkpoint.get("parent_sha") or "") != base_sha
                or str(checkpoint.get("message") or "") != message
                or Path(str(checkpoint.get("repository_root") or "")).resolve(strict=False)
                != repository_root
                or Path(str(checkpoint.get("workspace_path") or "")).resolve(strict=False)
                != workspace_root
                or (
                    checkpoint.get("committed_head_sha")
                    and str(checkpoint.get("committed_head_sha") or "") != current_head
                )
            ):
                return "", "checkpoint_identity_mismatch"
            commit_identity = run_git(
                ["show", "-s", "--format=%P%x00%T%x00%B", current_head]
            )
            identity_parts = str(commit_identity.stdout or "").split("\0", 2)
            if (
                commit_identity.returncode != 0
                or len(identity_parts) != 3
                or identity_parts[0].strip() != base_sha
                or identity_parts[1].strip() != str(checkpoint.get("tree_sha") or "")
                or identity_parts[2].rstrip("\n") != message
            ):
                return "", "checkpoint_identity_mismatch"
            if not changed_paths:
                return current_head, ""

            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                return "", cancellation_reason
            base_tree = run_git(["rev-parse", f"{base_sha}^{{tree}}"])
            real_index_tree = run_git(["write-tree"])
            if (
                base_tree.returncode != 0
                or real_index_tree.returncode != 0
                or str(real_index_tree.stdout or "").strip().lower()
                != str(base_tree.stdout or "").strip().lower()
            ):
                return "", "checkpoint_replay_index_base_mismatch"

            import tempfile

            git_dir_result = run_git(["rev-parse", "--git-dir"])
            index_path_result = run_git(["rev-parse", "--git-path", "index"])
            if git_dir_result.returncode != 0 or index_path_result.returncode != 0:
                return "", "checkpoint_git_metadata_failed"
            git_dir = Path(str(git_dir_result.stdout or "").strip())
            if not git_dir.is_absolute():
                git_dir = (repository_root / git_dir).resolve(strict=False)
            index_path = Path(str(index_path_result.stdout or "").strip())
            if not index_path.is_absolute():
                index_path = (repository_root / index_path).resolve(strict=False)
            try:
                initial_index_bytes = index_path.read_bytes()
            except FileNotFoundError:
                initial_index_bytes = b""
            except OSError:
                return "", "checkpoint_index_read_failed"
            private_fd, private_name = tempfile.mkstemp(
                prefix="hermes-replay-index-",
                dir=git_dir,
            )
            os.close(private_fd)
            os.unlink(private_name)
            private_index = Path(private_name)
            index_lock = Path(f"{index_path}.lock")
            lock_fd: int | None = None
            try:
                repaired = run_git(
                    ["-c", "core.hooksPath=/dev/null", "read-tree", current_head],
                    env={"GIT_INDEX_FILE": str(private_index)},
                )
                if repaired.returncode != 0:
                    return "", "checkpoint_replay_index_failed"
                replay_env = {"GIT_INDEX_FILE": str(private_index)}
                replay_pathspecs = [f":(literal){path}" for path in changed_paths]
                replay_stage = run_git(
                    [
                        "-c",
                        "core.hooksPath=/dev/null",
                        "add",
                        "-A",
                        "--",
                        *replay_pathspecs,
                    ],
                    env=replay_env,
                )
                replay_tree = run_git(["write-tree"], env=replay_env)
                untracked = run_git(
                    ["ls-files", "--others", "--exclude-standard", "-z"],
                    text=False,
                    env=replay_env,
                )
                if replay_stage.returncode != 0:
                    return "", "checkpoint_replay_stage_failed"
                if (
                    replay_tree.returncode != 0
                    or str(replay_tree.stdout or "").strip().lower()
                    != str(checkpoint.get("tree_sha") or "")
                ):
                    logger.warning(
                        "Checkpoint replay tree mismatch for %s: expected=%s actual=%s paths=%s",
                        work_id,
                        str(checkpoint.get("tree_sha") or ""),
                        str(replay_tree.stdout or "").strip().lower(),
                        changed_paths,
                    )
                    return "", "checkpoint_replay_tree_mismatch"
                if untracked.returncode != 0 or bool(bytes(untracked.stdout or b"")):
                    return "", "checkpoint_replay_untracked_files"
                try:
                    lock_fd = os.open(
                        index_lock,
                        os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                        0o600,
                    )
                except FileExistsError:
                    return "", "checkpoint_index_lock_busy"
                try:
                    live_index_bytes = index_path.read_bytes()
                except FileNotFoundError:
                    live_index_bytes = b""
                if live_index_bytes != initial_index_bytes:
                    return "", "checkpoint_real_index_changed"
                locked_seed = run_git(
                    ["-c", "core.hooksPath=/dev/null", "read-tree", current_head],
                    env=replay_env,
                )
                locked_stage = run_git(
                    [
                        "-c",
                        "core.hooksPath=/dev/null",
                        "add",
                        "-A",
                        "--",
                        *replay_pathspecs,
                    ],
                    env=replay_env,
                )
                locked_tree = run_git(["write-tree"], env=replay_env)
                locked_untracked = run_git(
                    ["ls-files", "--others", "--exclude-standard", "-z"],
                    text=False,
                    env=replay_env,
                )
                if (
                    str(run_git(["rev-parse", "HEAD"]).stdout or "").strip().lower()
                    != current_head
                    or locked_seed.returncode != 0
                    or locked_stage.returncode != 0
                    or locked_tree.returncode != 0
                    or str(locked_tree.stdout or "").strip().lower()
                    != str(checkpoint.get("tree_sha") or "")
                    or locked_untracked.returncode != 0
                    or bool(bytes(locked_untracked.stdout or b""))
                    or cancellation_fence()
                ):
                    return "", "checkpoint_replay_race"
                with os.fdopen(lock_fd, "wb", closefd=True) as lock_handle:
                    lock_fd = None
                    lock_handle.write(private_index.read_bytes())
                    lock_handle.flush()
                    os.fsync(lock_handle.fileno())
                os.replace(index_lock, index_path)
                repaired_status = status_snapshot()
                repaired_tree = run_git(["write-tree"])
                if (
                    repaired_status is None
                    or bool(repaired_status[1])
                    or str(repaired_tree.stdout or "").strip().lower()
                    != str(checkpoint.get("tree_sha") or "")
                ):
                    return "", "checkpoint_replay_verification_failed"
                completed = self._ledger().record_required_async_checkpoint(
                    work_id,
                    **identity,
                    parent_sha=base_sha,
                    tree_sha=str(checkpoint.get("tree_sha") or ""),
                    message=message,
                    repository_root=str(repository_root),
                    workspace_path=str(workspace_root),
                    committed_head_sha=current_head,
                )
                if not isinstance(completed, dict):
                    return "", "checkpoint_replay_persistence_failed"
                return current_head, ""
            finally:
                if lock_fd is not None:
                    os.close(lock_fd)
                try:
                    index_lock.unlink()
                except FileNotFoundError:
                    pass
                try:
                    private_index.unlink()
                except FileNotFoundError:
                    pass

        if not changed_paths:
            if isinstance(checkpoint, dict) and str(checkpoint.get("tree_sha") or ""):
                base_tree = run_git(["rev-parse", f"{base_sha}^{{tree}}"])
                if str(base_tree.stdout or "").strip() != str(checkpoint.get("tree_sha") or ""):
                    return "", "checkpoint_intent_worktree_missing"
            return current_head, ""

        def allowed(path: str) -> bool:
            return any(
                not prefix
                or path == prefix
                or path.startswith(prefix.rstrip("/") + "/")
                for prefix in allowed_prefixes
            )

        if not allowed_prefixes or any(not allowed(path) for path in changed_paths):
            return "", "checkpoint_changed_paths_out_of_scope"
        if run_git(["diff", "--check"]).returncode != 0:
            return "", "checkpoint_diff_check_failed"

        before_stage = status_snapshot()
        head_before_stage = run_git(["rev-parse", "--verify", "HEAD"])
        if (
            before_stage is None
            or before_stage[0] != initial_status[0]
            or str(head_before_stage.stdout or "").strip().lower() != base_sha
        ):
            return "", "checkpoint_workspace_changed_before_stage"

        import tempfile

        git_dir_result = run_git(["rev-parse", "--git-dir"])
        index_path_result = run_git(["rev-parse", "--git-path", "index"])
        if git_dir_result.returncode != 0 or index_path_result.returncode != 0:
            return "", "checkpoint_git_metadata_failed"
        git_dir = Path(str(git_dir_result.stdout or "").strip())
        if not git_dir.is_absolute():
            git_dir = (repository_root / git_dir).resolve(strict=False)
        index_path = Path(str(index_path_result.stdout or "").strip())
        if not index_path.is_absolute():
            index_path = (repository_root / index_path).resolve(strict=False)
        try:
            initial_index_bytes = index_path.read_bytes()
        except FileNotFoundError:
            initial_index_bytes = b""
        except OSError:
            return "", "checkpoint_index_read_failed"
        initial_index_tree_result = run_git(["write-tree"])
        initial_index_tree = str(initial_index_tree_result.stdout or "").strip().lower()
        if (
            initial_index_tree_result.returncode != 0
            or not re.fullmatch(r"[0-9a-f]{40}", initial_index_tree)
        ):
            return "", "checkpoint_index_tree_failed"

        private_fd, private_name = tempfile.mkstemp(
            prefix="hermes-async-index-",
            dir=git_dir,
        )
        os.close(private_fd)
        os.unlink(private_name)
        private_index = Path(private_name)
        private_env = {"GIT_INDEX_FILE": str(private_index)}
        index_lock = Path(f"{index_path}.lock")
        index_lock_fd: int | None = None

        def release_index_lock() -> None:
            nonlocal index_lock_fd
            if index_lock_fd is not None:
                os.close(index_lock_fd)
                index_lock_fd = None
            try:
                index_lock.unlink()
            except FileNotFoundError:
                pass

        def ref_revert(checkpoint_head: str) -> bool:
            reverted = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "update-ref",
                    "-m",
                    "Hermes async checkpoint cancellation",
                    "HEAD",
                    base_sha,
                    checkpoint_head,
                ]
            )
            return reverted.returncode == 0

        try:
            seeded = run_git(
                ["-c", "core.hooksPath=/dev/null", "read-tree", base_sha],
                env=private_env,
            )
            literal_pathspecs = [f":(literal){path}" for path in changed_paths]
            added = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "add",
                    "-A",
                    "--",
                    *literal_pathspecs,
                ],
                env=private_env,
            )
            if seeded.returncode != 0 or added.returncode != 0:
                return "", "checkpoint_stage_failed"
            if run_git(
                ["diff", "--cached", "--check"],
                env=private_env,
            ).returncode != 0:
                return "", "checkpoint_staged_diff_check_failed"
            tree = run_git(["write-tree"], env=private_env)
            expected_tree = str(tree.stdout or "").strip().lower()
            if tree.returncode != 0 or not re.fullmatch(r"[0-9a-f]{40}", expected_tree):
                return "", "checkpoint_tree_failed"

            after_stage = status_snapshot()
            if (
                after_stage is None
                or after_stage[0] != initial_status[0]
                or str(run_git(["rev-parse", "HEAD"]).stdout or "").strip().lower()
                != base_sha
            ):
                return "", "checkpoint_workspace_changed_after_stage"
            restaged_seed = run_git(
                ["-c", "core.hooksPath=/dev/null", "read-tree", base_sha],
                env=private_env,
            )
            restaged = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "add",
                    "-A",
                    "--",
                    *literal_pathspecs,
                ],
                env=private_env,
            )
            restaged_tree = run_git(["write-tree"], env=private_env)
            if (
                restaged_seed.returncode != 0
                or restaged.returncode != 0
                or restaged_tree.returncode != 0
                or str(restaged_tree.stdout or "").strip().lower() != expected_tree
            ):
                return "", "checkpoint_workspace_changed_after_stage"

            persisted = self._ledger().record_required_async_checkpoint(
                work_id,
                **identity,
                parent_sha=base_sha,
                tree_sha=expected_tree,
                message=message,
                repository_root=str(repository_root),
                workspace_path=str(workspace_root),
            )
            persisted_checkpoint = (
                persisted.get("checkpoint") if isinstance(persisted, dict) else None
            )
            expected_checkpoint = {
                "parent_sha": base_sha,
                "tree_sha": expected_tree,
                "message": message,
                "repository_root": str(repository_root),
                "workspace_path": str(workspace_root),
            }
            if (
                not isinstance(persisted_checkpoint, dict)
                or any(
                    persisted_checkpoint.get(key) != value
                    for key, value in expected_checkpoint.items()
                )
            ):
                return "", "checkpoint_intent_persistence_failed"
            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                return "", cancellation_reason

            try:
                index_lock_fd = os.open(
                    index_lock,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                    0o600,
                )
            except FileExistsError:
                return "", "checkpoint_index_lock_busy"
            except OSError:
                return "", "checkpoint_index_lock_failed"
            try:
                current_index_bytes = index_path.read_bytes()
            except FileNotFoundError:
                current_index_bytes = b""
            except OSError:
                return "", "checkpoint_index_read_failed"
            if current_index_bytes != initial_index_bytes:
                return "", "checkpoint_real_index_changed"

            locked_status = status_snapshot()
            if (
                locked_status is None
                or locked_status[0] != initial_status[0]
                or str(run_git(["rev-parse", "HEAD"]).stdout or "").strip().lower()
                != base_sha
            ):
                return "", "checkpoint_workspace_changed_before_commit"
            final_seed = run_git(
                ["-c", "core.hooksPath=/dev/null", "read-tree", base_sha],
                env=private_env,
            )
            final_stage = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "add",
                    "-A",
                    "--",
                    *literal_pathspecs,
                ],
                env=private_env,
            )
            final_tree = run_git(["write-tree"], env=private_env)
            if (
                final_seed.returncode != 0
                or final_stage.returncode != 0
                or final_tree.returncode != 0
                or str(final_tree.stdout or "").strip().lower() != expected_tree
            ):
                return "", "checkpoint_workspace_changed_before_commit"
            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                return "", cancellation_reason

            committed = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "-c",
                    "commit.gpgSign=false",
                    "commit-tree",
                    expected_tree,
                    "-p",
                    base_sha,
                ],
                timeout=60.0,
                input_text=f"{message}\n",
            )
            checkpoint_head = str(committed.stdout or "").strip().lower()
            if (
                committed.returncode != 0
                or not re.fullmatch(r"[0-9a-f]{40}", checkpoint_head)
            ):
                logger.warning(
                    "Trusted async checkpoint commit-tree failed for %s: %s",
                    work_id,
                    str(committed.stderr or committed.stdout or "")[:500],
                )
                return "", "checkpoint_commit_failed"
            commit_identity = run_git(
                ["show", "-s", "--format=%P%x00%T%x00%B", checkpoint_head]
            )
            identity_parts = str(commit_identity.stdout or "").split("\0", 2)
            if (
                commit_identity.returncode != 0
                or len(identity_parts) != 3
                or identity_parts[0].strip() != base_sha
                or identity_parts[1].strip() != expected_tree
                or identity_parts[2].rstrip("\n") != message
            ):
                return "", "checkpoint_commit_identity_failed"
            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                return "", cancellation_reason

            updated = run_git(
                [
                    "-c",
                    "core.hooksPath=/dev/null",
                    "update-ref",
                    "-m",
                    message,
                    "HEAD",
                    checkpoint_head,
                    base_sha,
                ]
            )
            if updated.returncode != 0:
                return "", "checkpoint_ref_cas_lost"
            try:
                current_index_bytes = index_path.read_bytes()
            except FileNotFoundError:
                current_index_bytes = b""
            except OSError:
                current_index_bytes = b"index-read-failed"
            if current_index_bytes != initial_index_bytes:
                if not ref_revert(checkpoint_head):
                    return "", "checkpoint_ref_revert_failed"
                return "", "checkpoint_real_index_changed"
            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                if not ref_revert(checkpoint_head):
                    return "", "checkpoint_cancel_revert_failed"
                return "", cancellation_reason

            private_index_bytes = private_index.read_bytes()
            if index_lock_fd is None:
                ref_revert(checkpoint_head)
                return "", "checkpoint_index_lock_lost"
            with os.fdopen(index_lock_fd, "wb", closefd=True) as lock_handle:
                index_lock_fd = None
                lock_handle.write(private_index_bytes)
                lock_handle.flush()
                os.fsync(lock_handle.fileno())
            os.replace(index_lock, index_path)

            cancellation_reason = cancellation_fence()
            if cancellation_reason:
                reverted = ref_revert(checkpoint_head)
                try:
                    live_index_bytes = index_path.read_bytes()
                except OSError:
                    live_index_bytes = b"index-read-failed"
                if live_index_bytes != private_index_bytes:
                    return "", "checkpoint_cancel_restore_failed"
                try:
                    restore_fd = os.open(
                        index_lock,
                        os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                        0o600,
                    )
                    try:
                        locked_index_bytes = index_path.read_bytes()
                    except OSError:
                        locked_index_bytes = b"index-read-failed"
                    if locked_index_bytes != private_index_bytes:
                        os.close(restore_fd)
                        index_lock.unlink(missing_ok=True)
                        return "", "checkpoint_cancel_restore_failed"
                    with os.fdopen(restore_fd, "wb", closefd=True) as restore_handle:
                        restore_handle.write(initial_index_bytes)
                        restore_handle.flush()
                        os.fsync(restore_handle.fileno())
                    os.replace(index_lock, index_path)
                except OSError:
                    return "", "checkpoint_cancel_restore_failed"
                if not reverted:
                    return "", "checkpoint_cancel_revert_failed"
                return "", cancellation_reason

            checked = run_git(["diff", "--check"])
            clean = status_snapshot()
            final_head = run_git(["rev-parse", "--verify", "HEAD"])
            verified_head = str(final_head.stdout or "").strip().lower()
            final_index_tree = run_git(["write-tree"])
            if (
                checked.returncode != 0
                or clean is None
                or bool(clean[1])
                or final_head.returncode != 0
                or verified_head != checkpoint_head
                or str(final_index_tree.stdout or "").strip().lower() != expected_tree
            ):
                return "", "checkpoint_post_commit_verification_failed"
            completed_checkpoint = self._ledger().record_required_async_checkpoint(
                work_id,
                **identity,
                parent_sha=base_sha,
                tree_sha=expected_tree,
                message=message,
                repository_root=str(repository_root),
                workspace_path=str(workspace_root),
                committed_head_sha=verified_head,
            )
            if not isinstance(completed_checkpoint, dict):
                cancellation_reason = cancellation_fence()
                if cancellation_reason:
                    reverted = ref_revert(checkpoint_head)
                    try:
                        live_index_bytes = index_path.read_bytes()
                    except OSError:
                        live_index_bytes = b"index-read-failed"
                    if live_index_bytes != private_index_bytes:
                        return "", "checkpoint_cancel_restore_failed"
                    try:
                        restore_fd = os.open(
                            index_lock,
                            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                            0o600,
                        )
                        try:
                            locked_index_bytes = index_path.read_bytes()
                        except OSError:
                            locked_index_bytes = b"index-read-failed"
                        if locked_index_bytes != private_index_bytes:
                            os.close(restore_fd)
                            index_lock.unlink(missing_ok=True)
                            return "", "checkpoint_cancel_restore_failed"
                        with os.fdopen(
                            restore_fd,
                            "wb",
                            closefd=True,
                        ) as restore_handle:
                            restore_handle.write(initial_index_bytes)
                            restore_handle.flush()
                            os.fsync(restore_handle.fileno())
                        os.replace(index_lock, index_path)
                    except OSError:
                        return "", "checkpoint_cancel_restore_failed"
                    if not reverted:
                        return "", "checkpoint_cancel_revert_failed"
                    return "", cancellation_reason
                return "", "checkpoint_completion_persistence_failed"
            return verified_head, ""
        finally:
            release_index_lock()
            try:
                private_index.unlink()
            except FileNotFoundError:
                pass

    async def _reconcile_required_async_item(
        self,
        work_id: str,
        expected_state: Dict[str, Any],
    ) -> None:
        """Advance one sealed terminal attempt without invoking a model."""

        ledger = self._ledger()
        current = ledger.required_async_completion_state(work_id)
        expected_identity = self._required_async_identity(expected_state)
        if (
            not isinstance(current, dict)
            or self._required_async_identity(current) != expected_identity
            or current.get("ready_to_reconcile") is not True
            or current.get("owns_recovery") is not True
        ):
            return
        item = ledger.get(work_id)
        if not isinstance(item, dict):
            return
        reconciliation_id = self._required_async_reconciliation_id(work_id, current)
        failure = bool(
            current.get("failed")
            or current.get("sticky_failure")
            or current.get("malformed")
            or (
                not current.get("has_required")
                and int(current.get("advisory_succeeded") or 0) == 0
                and int(current.get("advisory_failed") or 0) > 0
            )
        )
        identity = self._required_async_identity(current)

        async def finalize_cancelled(state: Dict[str, Any]) -> None:
            cancelled_identity = self._required_async_identity(state)
            cancelled_reconciliation_id = self._required_async_reconciliation_id(
                work_id,
                state,
            )
            finalized = await asyncio.to_thread(
                ledger.finalize_required_async_failure,
                work_id,
                **cancelled_identity,
                final_response=(
                    "Background attempt work was explicitly stopped before "
                    "reconciliation completed and will not be resumed automatically."
                ),
                reason="required_async_attempt_cancelled",
                reconciliation_id=cancelled_reconciliation_id,
            )
            if isinstance(finalized, dict):
                await self._resume_finished_discord_work_item(finalized)

        if failure:
            reason = (
                "required_async_attempt_cancelled"
                if current.get("attempt_cancelled")
                else "required_async_outcome_unknown"
                if current.get("required_outcome_unknown")
                else "required_async_cancelled"
                if current.get("required_cancelled")
                else "required_async_malformed"
                if current.get("malformed")
                else "advisory_async_completion_failed"
                if not current.get("has_required")
                else "required_async_completion_failed"
            )
            finalized = await asyncio.to_thread(
                ledger.finalize_required_async_failure,
                work_id,
                **identity,
                final_response=self._required_async_terminal_summary(
                    current,
                    success=False,
                ),
                reason=reason,
                reconciliation_id=reconciliation_id,
            )
            if isinstance(finalized, dict):
                await self._resume_finished_discord_work_item(finalized)
            return

        if current.get("has_required"):
            activated, route = await asyncio.to_thread(
                self._activate_required_async_closeout,
                work_id,
                item,
                current,
            )
        else:
            activated, route = False, "work_item"
        latest = ledger.required_async_completion_state(work_id)
        if (
            isinstance(latest, dict)
            and self._required_async_identity(latest) == identity
            and latest.get("attempt_cancelled") is True
        ):
            await finalize_cancelled(latest)
            return
        if route not in {"closeout", "work_item"}:
            finalized = await asyncio.to_thread(
                ledger.finalize_required_async_failure,
                work_id,
                **identity,
                final_response=(
                    "Required coding workers completed, but Hermes could not "
                    "safely reconcile their result into trusted closeout "
                    f"({route}). The request was blocked without replaying or retrying work."
                ),
                reason="required_async_reconciliation_failed",
                reconciliation_id=reconciliation_id,
            )
            if isinstance(finalized, dict):
                await self._resume_finished_discord_work_item(finalized)
            return

        if route == "work_item":
            expected_run_state = ledger.run_state_snapshot(item)
            accepted = await asyncio.to_thread(
                ledger.mark_agent_done,
                work_id,
                final_response=self._required_async_terminal_summary(
                    current,
                    success=True,
                ),
                session_id=item.get("session_id"),
                summary_status="Complete",
                feature_summary=item.get("feature_summary"),
                project_summary=item.get("project_summary"),
                expected_run_state=expected_run_state,
            )
            if not accepted:
                return
        latest = ledger.required_async_completion_state(work_id)
        if (
            isinstance(latest, dict)
            and self._required_async_identity(latest) == identity
            and latest.get("attempt_cancelled") is True
        ):
            await finalize_cancelled(latest)
            return
        reconciled = await asyncio.to_thread(
            ledger.mark_required_async_reconciled,
            work_id,
            **identity,
            reconciliation_id=reconciliation_id,
        )
        if not isinstance(reconciled, dict):
            return
        if route == "work_item":
            fresh = ledger.get(work_id)
            if isinstance(fresh, dict):
                await self._resume_finished_discord_work_item(fresh)

    def _schedule_required_async_reconciliation(
        self,
        work_id: str,
        state: Dict[str, Any],
    ) -> bool:
        if not work_id or self.__dict__.get("_running") is False:
            return False
        tasks = self.__dict__.setdefault("_required_async_item_tasks", {})
        existing = tasks.get(work_id)
        if existing is not None and not existing.done():
            return False

        async def _run() -> None:
            try:
                await self._reconcile_required_async_item(work_id, dict(state))
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception(
                    "Required async reconciliation failed for %s",
                    work_id,
                )
            finally:
                if tasks.get(work_id) is asyncio.current_task():
                    tasks.pop(work_id, None)

        task = asyncio.create_task(
            _run(),
            name=f"gateway:required-async-item:{work_id[:32]}",
        )
        tasks[work_id] = task
        background = self.__dict__.setdefault("_background_tasks", set())
        background.add(task)
        task.add_done_callback(background.discard)
        return True

    def _scan_required_async_reconciliation(self) -> int:
        ledger = self._ledger()
        scheduled = 0
        for item in ledger.incomplete_items():
            work_id = str(item.get("id") or "")
            if not work_id:
                continue
            state = ledger.required_async_completion_state(work_id)
            if (
                isinstance(state, dict)
                and state.get("owns_recovery") is True
                and state.get("ready_to_reconcile") is True
                and self._schedule_required_async_reconciliation(work_id, state)
            ):
                scheduled += 1
        return scheduled

    def _recover_durable_coding_workers(self) -> dict[str, Any]:
        """Recover all registered Discord coding children for this process."""

        from tools.coding_worker_tool import recover_durable_coding_workers

        report = recover_durable_coding_workers(
            ledger=self._ledger(),
            process_epoch=str(self._process_epoch),
            owner_pid=os.getpid(),
        )
        if report.get("work_item_ids"):
            event = self.__dict__.setdefault(
                "_required_async_reconcile_event",
                asyncio.Event(),
            )
            event.set()
        return report

    @staticmethod
    def _durable_coding_worker_recovery_needs_retry(report: Any) -> bool:
        """Return whether startup recovery has deferred work to revisit."""

        if not isinstance(report, dict):
            return True
        return any(
            int(report.get(key) or 0) > 0
            for key in ("waiting_alive", "deferred", "failed")
        )

    async def _send_durable_coding_worker_recovery_notices(
        self,
        notices: Any,
    ) -> int:
        """Keep Discord parents informed when automatic recovery must wait/fail."""

        sent = 0
        seen: set[tuple[str, str]] = set()
        delivered = self.__dict__.setdefault(
            "_durable_coding_worker_notice_keys",
            set(),
        )
        for raw in list(notices or [])[:32]:
            if not isinstance(raw, dict):
                continue
            delegation_id = str(raw.get("delegation_id") or "")
            kind = str(raw.get("kind") or "waiting")
            dedupe_key = (delegation_id, kind)
            if not delegation_id or dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            source_data = raw.get("source")
            if not isinstance(source_data, dict):
                continue
            try:
                source = SessionSource.from_dict(source_data)
            except Exception:
                continue
            if source.platform != Platform.DISCORD:
                continue
            adapter = self._adapter_for_source(source)
            if adapter is None:
                continue
            detail = str(raw.get("message") or "").strip()
            persistent_key = (delegation_id, kind, detail)
            if persistent_key in delivered:
                continue
            if kind == "manual_fallback":
                content = (
                    "⚠️ Coding-worker recovery needs attention — Hermes could not "
                    "safely resume this worker and will block the parent request "
                    "without replaying it. " + detail
                )
            else:
                content = (
                    "🔄 Recovering coding work after restart — " + detail
                )
            metadata = {"thread_id": source.thread_id} if source.thread_id else None
            try:
                result = await adapter.send(
                    chat_id=str(source.chat_id),
                    content=content,
                    metadata=metadata,
                )
            except Exception:
                logger.debug(
                    "Durable coding-worker recovery notice failed for %s",
                    delegation_id,
                    exc_info=True,
                )
                continue
            if getattr(result, "success", False):
                sent += 1
                delivered.add(persistent_key)
                if len(delivered) > 256:
                    delivered.clear()
                    delivered.add(persistent_key)
        return sent

    async def _durable_coding_worker_reconciler(self, interval: float = 2.0) -> None:
        """Retry deferred alive/capacity recovery without replaying the parent."""

        while self._running:
            await asyncio.sleep(max(0.25, interval))
            try:
                report = await asyncio.to_thread(self._recover_durable_coding_workers)
                await self._send_durable_coding_worker_recovery_notices(
                    report.get("notices") or []
                )
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception("Durable coding-worker reconciliation failed")
                continue
            if not self._durable_coding_worker_recovery_needs_retry(report):
                return

    async def _required_async_reconciler(
        self,
        interval: float = _REQUIRED_ASYNC_RECONCILE_INTERVAL_SECONDS,
    ) -> None:
        """Periodically repair lost required-completion queue wakeups."""

        wake = self.__dict__.setdefault(
            "_required_async_reconcile_event",
            asyncio.Event(),
        )
        while self._running:
            wake.clear()
            self._scan_required_async_reconciliation()
            try:
                await asyncio.wait_for(wake.wait(), timeout=max(0.05, interval))
            except TimeoutError:
                pass

    async def _handoff_watcher(self, interval: float = 2.0) -> None:
        """Background task that processes pending CLI→gateway session handoffs.

        Polls ``state.db`` for sessions in ``handoff_state='pending'`` and,
        for each one:

        1. Atomically claims it (pending → running).
        2. Resolves the destination platform's configured home channel.
        3. Re-binds the gateway's session_key for that home channel to the
           CLI's existing session_id via ``session_store.switch_session`` so
           the full role-aware transcript replays on the next agent turn.
        4. Forges a synthetic ``MessageEvent`` (``internal=True``) with a
           handoff-notice text and dispatches through the normal gateway
           message pipeline so the agent runs and replies on the platform.
        5. Marks the row ``completed`` (or ``failed`` with ``handoff_error``).

        The CLI process is poll-blocked on the row's terminal state and
        prints the result to the user.
        """
        # Initial delay so the gateway is fully connected to its platforms
        # before we try to dispatch handoffs through them.
        await asyncio.sleep(5)
        while self._running:
            try:
                if self._session_db is None:
                    await asyncio.sleep(interval)
                    continue
                pending = await self._session_db.list_pending_handoffs()
                for row in pending:
                    session_id = row.get("id")
                    if not session_id:
                        continue
                    if not await self._session_db.claim_handoff(session_id):
                        # Another tick or another gateway already claimed it.
                        continue
                    try:
                        await self._process_handoff(row)
                        await self._session_db.complete_handoff(session_id)
                    except Exception as exc:
                        logger.warning(
                            "Handoff for session %s failed: %s",
                            session_id, exc, exc_info=True,
                        )
                        await self._session_db.fail_handoff(session_id, str(exc))
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                logger.debug("Handoff watcher tick error: %s", exc, exc_info=True)
            await asyncio.sleep(interval)

    async def _process_handoff(self, row: Dict[str, Any]) -> None:
        """Execute one handoff row. Raises on failure (caller marks failed)."""
        from gateway.config import Platform
        from gateway.session import SessionSource, build_session_key
        from gateway.platforms.base import MessageEvent

        cli_session_id = row["id"]
        platform_name = (row.get("handoff_platform") or "").strip().lower()
        if not platform_name:
            raise RuntimeError("handoff_platform is empty")

        # Resolve platform enum
        try:
            platform = Platform(platform_name)
        except (ValueError, KeyError):
            raise RuntimeError(f"unknown platform '{platform_name}'")

        # Adapter must be live
        adapter = self.adapters.get(platform)
        if not adapter:
            raise RuntimeError(
                f"platform '{platform_name}' is not active in this gateway"
            )

        # Home channel must be configured
        home = self.config.get_home_channel(platform)
        if not home or not home.chat_id:
            raise RuntimeError(
                f"no home channel configured for {platform_name}; "
                f"run /sethome on the desired chat first"
            )

        cli_title = row.get("title") or cli_session_id[:8]

        # Try to create a fresh thread on the destination so the handoff
        # has its own scrollback. Adapter returns None if threading isn't
        # supported (Matrix/WhatsApp/Signal/SMS) or if creation failed
        # (no permission, topics-mode off, parent is a DM, etc.). When
        # None we fall through to using the home channel directly — the
        # synthetic turn still lands; just without thread isolation.
        thread_name = f"Hermes — {cli_title}"
        try:
            new_thread_id = await adapter.create_handoff_thread(
                str(home.chat_id), thread_name,
            )
        except Exception as exc:
            logger.debug(
                "Handoff: create_handoff_thread raised on %s: %s",
                platform_name, exc, exc_info=True,
            )
            new_thread_id = None

        # Use the new thread if the adapter created one; otherwise fall
        # back to whatever thread (if any) the home channel was configured
        # with.
        effective_thread_id = new_thread_id or (
            str(home.thread_id) if home.thread_id else None
        )

        # Telegram private-chat topics use the DM lane and real user id. A
        # generic ``thread`` source would bind a different session key from the
        # user's next inbound DM-topic reply and lose the handoff.
        home_chat_id = str(home.chat_id)
        is_telegram_private_chat = (
            platform == Platform.TELEGRAM
            and looks_like_telegram_private_chat_id(home_chat_id)
        )
        if new_thread_id and not is_telegram_private_chat:
            dest_chat_type = "thread"
            dest_user_id = "system:handoff"
        else:
            dest_chat_type = "dm"
            dest_user_id = (
                home_chat_id if is_telegram_private_chat else "system:handoff"
            )

        dest_source = SessionSource(
            platform=platform,
            chat_id=home_chat_id,
            chat_name=home.name,
            chat_type=dest_chat_type,
            user_id=dest_user_id,
            user_name="Handoff",
            thread_id=effective_thread_id,
        )

        # Compute the gateway's session_key for that destination using the
        # same rules its adapters use, so switch_session targets the right
        # entry. For thread destinations build_session_key keys without
        # user_id (thread_sessions_per_user defaults to False) — so the
        # next real user message in the thread shares this same session.
        platform_cfg = self.config.platforms.get(platform)
        extra = platform_cfg.extra if platform_cfg else {}
        session_key = build_session_key(
            dest_source,
            group_sessions_per_user=extra.get("group_sessions_per_user", True),
            thread_sessions_per_user=extra.get("thread_sessions_per_user", False),
        )

        # Make sure there's an entry in the session_store for this key. If
        # the home channel has never been used, get_or_create_session
        # creates one; switch_session then re-points it.
        await self.async_session_store.get_or_create_session(dest_source)

        # Re-bind the destination key to the CLI session_id. switch_session
        # ends the prior session in SQLite and reopens the CLI session under
        # the new key. The CLI's transcript becomes the active one for the
        # gateway from this moment on.
        switched = await self.async_session_store.switch_session(session_key, cli_session_id)
        if switched is None:
            raise RuntimeError(
                f"could not switch session key {session_key} → {cli_session_id}"
            )

        # Evict any cached AIAgent for this session_key so the next dispatch
        # rebuilds it against the CLI session_id (mirrors /resume / /branch).
        self._evict_cached_agent(session_key)

        # Cancel any in-flight running-agent state for the destination key
        # so the synthetic turn isn't queued behind a stale running flag.
        self._release_running_agent_state(session_key)

        synthetic_text = (
            f"[Session was just handed off from CLI (\"{cli_title}\") to this "
            f"channel. The full prior conversation history is loaded above. "
            f"Briefly confirm you're working here and summarize what we were "
            f"working on, so the user can continue from this device.]"
        )

        synthetic_event = MessageEvent(
            text=synthetic_text,
            source=dest_source,
            internal=True,
        )

        logger.info(
            "Handoff: dispatching synthetic turn for CLI session %s → %s "
            "(home=%s, thread=%s, session_key=%s)",
            cli_session_id, platform_name, home.chat_id, effective_thread_id,
            session_key,
        )

        # Dispatch through the runner directly. Going through
        # adapter.handle_message would spawn a background task and we'd
        # lose synchronous error visibility; calling _handle_message inline
        # keeps the success/failure path observable for the watcher.
        response_text = await self._handle_message(synthetic_event)
        if not response_text:
            # Streaming may have already delivered the response inline.
            # Either way, agent ran without raising — count as success.
            return

        # Send the agent's reply to the destination. Route to the new
        # thread if we created one; otherwise the configured home channel
        # (which may itself carry a thread_id).
        send_metadata: Dict[str, Any] = {}
        if effective_thread_id:
            send_metadata["thread_id"] = effective_thread_id
        try:
            result = await adapter.send(
                chat_id=str(home.chat_id),
                content=response_text,
                metadata=send_metadata or None,
            )
        except Exception as exc:
            raise RuntimeError(f"adapter.send failed: {exc}") from exc

        if not getattr(result, "success", True):
            err = getattr(result, "error", "send returned success=False")
            raise RuntimeError(f"adapter.send failed: {err}")

    async def _session_expiry_watcher(self, interval: int = 300):
        """Background task that finalizes expired sessions.

        Runs every ``interval`` seconds (default 5 min).  For each session
        whose reset policy has expired, invokes ``on_session_finalize``
        hooks, cleans up the cached AIAgent's tool resources, evicts the
        cache entry so it can be garbage-collected, and marks the session
        so it won't be finalized again.
        """
        await asyncio.sleep(60)  # initial delay — let the gateway fully start
        _finalize_failures: dict[str, int] = {}  # session_id -> consecutive failure count
        _MAX_FINALIZE_RETRIES = 3
        while self._running:
            try:
                await self.async_session_store._ensure_loaded()
                # Collect expired sessions first, then log a single summary.
                _expired_entries = []
                for key, entry in list(self.session_store._entries.items()):
                    if entry.expiry_finalized:
                        continue
                    if not await self.async_session_store._is_session_expired(entry):
                        continue
                    _expired_entries.append((key, entry))

                if _expired_entries:
                    # Extract platform names from session keys for a compact summary.
                    # Keys look like "agent:main:telegram:dm:12345" — platform is field [2].
                    _platforms: dict[str, int] = {}
                    for _k, _e in _expired_entries:
                        _parts = _k.split(":")
                        _plat = _parts[2] if len(_parts) > 2 else "unknown"
                        _platforms[_plat] = _platforms.get(_plat, 0) + 1
                    _plat_summary = ", ".join(
                        f"{p}:{c}" for p, c in sorted(_platforms.items())
                    )
                    logger.info(
                        "Session expiry: %d sessions to finalize (%s)",
                        len(_expired_entries), _plat_summary,
                    )

                for key, entry in _expired_entries:
                    try:
                        try:
                            from hermes_cli.plugins import invoke_hook as _invoke_hook
                            _parts = key.split(":")
                            _platform = _parts[2] if len(_parts) > 2 else ""
                            _invoke_hook(
                                "on_session_finalize",
                                session_id=entry.session_id,
                                platform=_platform,
                            )
                        except Exception:
                            pass
                        # Shut down memory provider and close tool resources
                        # on the cached agent.  Idle agents live in
                        # _agent_cache (not _running_agents), so look there.
                        _cached_agent = None
                        _cache_lock = getattr(self, "_agent_cache_lock", None)
                        if _cache_lock is not None:
                            with _cache_lock:
                                _cached = self._agent_cache.get(key)
                                _cached_agent = _cached[0] if isinstance(_cached, tuple) else _cached if _cached else None
                        # Fall back to _running_agents in case the agent is
                        # still mid-turn when the expiry fires.
                        if _cached_agent is None:
                            _cached_agent = self._running_agents.get(key)
                        if _cached_agent and _cached_agent is not _AGENT_PENDING_SENTINEL:
                            self._cleanup_agent_resources(_cached_agent)
                        # Drop the cache entry so the AIAgent (and its LLM
                        # clients, tool schemas, memory provider refs) can
                        # be garbage-collected.  Otherwise the cache grows
                        # unbounded across the gateway's lifetime.
                        self._evict_cached_agent(key)
                        # Expiry finalization is a conversation boundary. Use
                        # the shared funnel so resolved models, overrides,
                        # queued events, and boundary security state cannot
                        # survive into a later resumed conversation.
                        self._clear_conversation_scope(
                            key, reason="expiry_finalized"
                        )
                        # Mark as finalized and persist to disk so the flag
                        # survives gateway restarts.
                        with self.session_store._lock:
                            entry.expiry_finalized = True
                            await self.async_session_store._save()
                        logger.debug(
                            "Session expiry finalized for %s",
                            entry.session_id,
                        )
                        _finalize_failures.pop(entry.session_id, None)
                    except Exception as e:
                        failures = _finalize_failures.get(entry.session_id, 0) + 1
                        _finalize_failures[entry.session_id] = failures
                        if failures >= _MAX_FINALIZE_RETRIES:
                            logger.warning(
                                "Session finalize gave up after %d attempts for %s: %s. "
                                "Marking as finalized to prevent infinite retry loop.",
                                failures, entry.session_id, e,
                            )
                            with self.session_store._lock:
                                entry.expiry_finalized = True
                                await self.async_session_store._save()
                            _finalize_failures.pop(entry.session_id, None)
                        else:
                            logger.debug(
                                "Session finalize failed (%d/%d) for %s: %s",
                                failures, _MAX_FINALIZE_RETRIES, entry.session_id, e,
                            )

                if _expired_entries:
                    _done = sum(
                        1 for _, e in _expired_entries if e.expiry_finalized
                    )
                    _failed = len(_expired_entries) - _done
                    if _failed:
                        logger.info(
                            "Session expiry done: %d finalized, %d pending retry",
                            _done, _failed,
                        )
                    else:
                        logger.info(
                            "Session expiry done: %d finalized", _done,
                        )

                # Sweep agents that have been idle beyond the TTL regardless
                # of session reset policy.  This catches sessions with very
                # long / "never" reset windows, whose cached AIAgents would
                # otherwise pin memory for the gateway's entire lifetime.
                try:
                    _idle_evicted = self._sweep_idle_cached_agents()
                    if _idle_evicted:
                        logger.info(
                            "Agent cache idle sweep: evicted %d agent(s)",
                            _idle_evicted,
                        )
                except Exception as _e:
                    logger.debug("Idle agent sweep failed: %s", _e)

                # Periodically prune stale SessionStore entries.  The
                # in-memory dict (and sessions.json) would otherwise grow
                # unbounded in gateways serving many rotating chats /
                # threads / users over long time windows.  Pruning is
                # invisible to users — a resumed session just gets a
                # fresh session_id, exactly as if the reset policy fired.
                _last_prune_ts = getattr(self, "_last_session_store_prune_ts", 0.0)
                _prune_interval = 3600.0  # once per hour
                if time.time() - _last_prune_ts > _prune_interval:
                    try:
                        _max_age = int(
                            getattr(self.config, "session_store_max_age_days", 0) or 0
                        )
                        if _max_age > 0:
                            _pruned = await self.async_session_store.prune_old_entries(_max_age)
                            if _pruned:
                                logger.info(
                                    "SessionStore prune: dropped %d stale entries",
                                    _pruned,
                                )
                    except Exception as _e:
                        logger.debug("SessionStore prune failed: %s", _e)
                    self._last_session_store_prune_ts = time.time()
            except Exception as e:
                logger.debug("Session expiry watcher error: %s", e)
            # Sleep in small increments so we can stop quickly
            for _ in range(interval):
                if not self._running:
                    break
                await asyncio.sleep(1)

    def _active_profile_name(self) -> str:
        """Return the profile name this gateway represents."""
        try:
            from hermes_cli.profiles import get_active_profile_name
            return get_active_profile_name() or "default"
        except Exception:
            return "default"

    async def _kanban_notifier_watcher(self, interval: float = 5.0) -> None:
        """Poll ``kanban_notify_subs`` and deliver terminal events to users.

        For each subscription row, fetches ``task_events`` newer than the
        stored cursor with kind in the terminal set (``completed``,
        ``blocked``, ``gave_up``, ``crashed``, ``timed_out``). Sends one
        message per new event to ``(platform, chat_id, thread_id)``,
        then advances the cursor. When a task reaches a terminal state
        (``completed`` / ``archived``), the subscription is removed.

        Runs in the gateway event loop; all SQLite work is pushed to a
        thread via ``asyncio.to_thread`` so the loop never blocks on the
        WAL lock. Failures in one tick don't stop subsequent ticks.

        **Multi-board:** iterates every board discovered on disk per
        tick. Subscriptions live inside each board's own DB and cannot
        cross boards, so delivery semantics are unchanged — this is
        purely a fan-out of the single-DB poll.
        """
        from gateway.config import Platform as _Platform
        try:
            from hermes_cli import kanban_db as _kb
        except Exception:
            logger.warning("kanban notifier: kanban_db not importable; notifier disabled")
            return

        TERMINAL_KINDS = ("completed", "blocked", "gave_up", "crashed", "timed_out")
        # Subscriptions are removed only when the task reaches a truly final
        # status (done / archived). We used to also unsub on any terminal
        # event kind (gave_up / crashed / timed_out / blocked), but that
        # silently dropped the user out of the loop whenever the dispatcher
        # respawned the task: a worker that crashes, gets reclaimed, runs
        # again, and crashes a second time would only notify on the first
        # crash because the subscription was deleted after the first event.
        # Same shape as the reblock-after-unblock cycle that PR #22941
        # fixed for `blocked`. Keeping the subscription alive until the
        # task is genuinely done lets the cursor (advanced atomically by
        # claim_unseen_events_for_sub) handle dedup, and any retry-loop
        # event reaches the user.
        # Per-subscription send-failure counter. Adapter.send raising
        # means the chat is dead (deleted, bot kicked, etc.) — after N
        # consecutive send failures the sub is dropped so we don't spin
        # against a dead chat every 5 seconds forever.
        MAX_SEND_FAILURES = 3
        sub_fail_counts: dict[tuple, int] = getattr(
            self, "_kanban_sub_fail_counts", {}
        )
        self._kanban_sub_fail_counts = sub_fail_counts
        notifier_profile = getattr(self, "_kanban_notifier_profile", None)
        if not notifier_profile:
            notifier_profile = self._active_profile_name()
            self._kanban_notifier_profile = notifier_profile

        # Initial delay so the gateway can finish wiring adapters.
        await asyncio.sleep(5)

        while self._running:
            try:
                def _collect():
                    deliveries: list[dict] = []
                    profile_adapters = getattr(self, "_profile_adapters", {}) or {}
                    if not self.adapters and not any(profile_adapters.values()):
                        logger.debug("kanban notifier: no connected adapters; skipping tick")
                        return deliveries

                    # Enumerate every board on disk, but poll each resolved DB
                    # path once. Multiple slugs can point at the same DB when
                    # HERMES_KANBAN_DB pins the board path; without this guard
                    # one gateway could collect the same subscription/event
                    # more than once before advancing the cursor.
                    try:
                        boards = _kb.list_boards(include_archived=False)
                    except Exception:
                        boards = [_kb.read_board_metadata(_kb.DEFAULT_BOARD)]
                    seen_db_paths: set[str] = set()
                    def _board_db_path(slug: str) -> Path:
                        return Path(str(_kb.kanban_db_path(slug))).expanduser().resolve()

                    def _corrupt_quarantine_state(slug: str) -> dict:
                        try:
                            return _kb.corrupt_board_quarantine_state(slug)
                        except Exception:
                            return {"open_allowed": True, "skipped": False}

                    def _record_corrupt_board(slug: str, exc: Exception) -> Optional[dict]:
                        incident = getattr(exc, "incident", None)
                        if isinstance(incident, dict):
                            return incident
                        try:
                            db_path = _board_db_path(slug)
                            fingerprint = _kb._db_content_fingerprint(db_path)
                        except Exception:
                            db_path = Path(str(_kb.kanban_db_path(slug)))
                            fingerprint = None
                        return _kb.record_corrupt_board_incident(
                            slug,
                            db_path,
                            str(getattr(exc, "reason", None) or exc),
                            backup_path=getattr(exc, "backup_path", None),
                            fingerprint=fingerprint,
                            error_class=exc.__class__.__name__,
                        )

                    def _log_corrupt_board_incident(slug: str, incident: Optional[dict], exc: Exception) -> None:
                        if not _kb.should_log_corrupt_board_incident(incident):
                            return
                        incident = incident or {}
                        logger.error(
                            "kanban notifier: board %s database corruption incident; "
                            "db_path=%s quarantine_path=%s reason=%s. Notification "
                            "polling is paused for this board while the DB fingerprint "
                            "is unchanged. Repair guidance: restore a known-good backup "
                            "or run `hermes kanban repair --board %s`, then retry after "
                            "integrity checks pass.",
                            slug,
                            incident.get("db_path") or str(_kb.kanban_db_path(slug)),
                            incident.get("quarantine_path") or getattr(exc, "backup_path", None) or "<unavailable>",
                            incident.get("reason") or getattr(exc, "reason", None) or str(exc),
                            slug,
                        )

                    for board_meta in boards:
                        slug = board_meta.get("slug") or _kb.DEFAULT_BOARD
                        db_path = board_meta.get("db_path")
                        try:
                            resolved_db_path = str(Path(db_path).expanduser().resolve()) if db_path else str(_kb.kanban_db_path(slug).resolve())
                        except Exception:
                            resolved_db_path = f"slug:{slug}"
                        if resolved_db_path in seen_db_paths:
                            logger.debug(
                                "kanban notifier: skipping duplicate board slug %s for DB %s",
                                slug, resolved_db_path,
                            )
                            continue
                        seen_db_paths.add(resolved_db_path)
                        state = _corrupt_quarantine_state(slug)
                        if state.get("skipped"):
                            logger.debug(
                                "kanban notifier: board %s paused for unchanged DB corruption; "
                                "skipping poll db_path=%s next_retry=%s reason=%s",
                                slug,
                                state.get("db_path"),
                                state.get("next_retry"),
                                state.get("reason"),
                            )
                            continue
                        try:
                            conn = _kb.connect(board=slug)
                        except Exception as exc:
                            if _kb.is_corrupt_board_db_error(exc):
                                _log_corrupt_board_incident(slug, _record_corrupt_board(slug, exc), exc)
                                continue
                            logger.debug("kanban notifier: cannot open board %s: %s", slug, exc)
                            continue
                        try:
                            # `connect()` runs the schema + idempotent migration
                            # on first open per process, so an explicit
                            # `init_db()` here would be redundant. Worse:
                            # `init_db()` deliberately busts the per-process
                            # cache and re-runs the migration on a *second*
                            # connection, which races the first and used to
                            # log a benign but noisy `duplicate column name`
                            # traceback (and intermittent "database is locked"
                            # — issue #21378) on every gateway start against
                            # a legacy DB. `_add_column_if_missing` now
                            # tolerates that race, but we still skip the
                            # redundant call to avoid the wasted work.
                            ready, incident = _kb.board_schema_ready(
                                conn,
                                board=slug,
                                operation="notifier",
                                required_tables=("kanban_notify_subs", "task_events", "tasks"),
                            )
                            if not ready:
                                _log_corrupt_board_incident(slug, incident, RuntimeError(
                                    (incident or {}).get("reason") or "kanban board schema not ready"
                                ))
                                continue
                            subs = _kb.list_notify_subs(conn)
                            if not subs:
                                logger.debug("kanban notifier: board %s has no subscriptions", slug)
                            for sub in subs:
                                owner_profile = sub.get("notifier_profile") or None
                                adapter_profile = (
                                    owner_profile
                                    if owner_profile and owner_profile != notifier_profile
                                    else None
                                )
                                platform = (sub.get("platform") or "").lower()
                                try:
                                    plat = _Platform(platform)
                                except ValueError:
                                    logger.debug(
                                        "kanban notifier: subscription for %s has unknown platform %s; skipping",
                                        sub.get("task_id"), platform or "<missing>",
                                    )
                                    continue
                                if self._authorization_adapter(plat, adapter_profile) is None:
                                    logger.debug(
                                        "kanban notifier: subscription for %s on %s owned by profile %s skipped; adapter not connected",
                                        sub.get("task_id"), platform or "<missing>",
                                        owner_profile or notifier_profile,
                                    )
                                    continue
                                old_cursor, cursor, events = _kb.claim_unseen_events_for_sub(
                                    conn,
                                    task_id=sub["task_id"],
                                    platform=sub["platform"],
                                    chat_id=sub["chat_id"],
                                    thread_id=sub.get("thread_id") or "",
                                    kinds=TERMINAL_KINDS,
                                )
                                if not events:
                                    continue
                                task = _kb.get_task(conn, sub["task_id"])
                                logger.debug(
                                    "kanban notifier: claimed %d event(s) for %s on board %s cursor %s→%s",
                                    len(events), sub["task_id"], slug, old_cursor, cursor,
                                )
                                deliveries.append({
                                    "sub": sub,
                                    "old_cursor": old_cursor,
                                    "cursor": cursor,
                                    "events": events,
                                    "task": task,
                                    "board": slug,
                                })
                        finally:
                            conn.close()
                    return deliveries

                deliveries = await asyncio.to_thread(_collect)
                for d in deliveries:
                    sub = d["sub"]
                    task = d["task"]
                    board_slug = d.get("board")
                    platform_str = (sub["platform"] or "").lower()
                    try:
                        plat = _Platform(platform_str)
                    except ValueError:
                        # Unknown platform string; skip and advance cursor so
                        # we don't replay forever.
                        await asyncio.to_thread(
                            self._kanban_advance, sub, d["cursor"], board_slug,
                        )
                        continue
                    owner_profile = sub.get("notifier_profile") or None
                    adapter_profile = (
                        owner_profile
                        if owner_profile and owner_profile != notifier_profile
                        else None
                    )
                    adapter = self._authorization_adapter(plat, adapter_profile)
                    if adapter is None:
                        logger.debug(
                            "kanban notifier: adapter %s disconnected before delivery for %s; rewinding claim",
                            platform_str, sub["task_id"],
                        )
                        await asyncio.to_thread(
                            self._kanban_rewind,
                            sub,
                            d["cursor"],
                            d.get("old_cursor", 0),
                            board_slug,
                        )
                        continue
                    title = (task.title if task else sub["task_id"])[:120]
                    for ev in d["events"]:
                        kind = ev.kind
                        # Identity prefix: attribute terminal pings to the
                        # worker that did the work. Makes fleets (where one
                        # chat subscribes to many tasks) legible at a glance.
                        who = (task.assignee if task and task.assignee else None)
                        tag = f"@{who} " if who else ""
                        if kind == "completed":
                            # Prefer the run's summary (the worker's
                            # intentional human-facing handoff, carried
                            # in the event payload), then fall back to
                            # task.result for legacy rows written before
                            # runs shipped.
                            handoff = ""
                            payload_summary = None
                            if ev.payload and ev.payload.get("summary"):
                                payload_summary = str(ev.payload["summary"])
                            if payload_summary:
                                h = payload_summary.strip().splitlines()[0][:200]
                                handoff = f"\n{h}"
                            elif task and task.result:
                                r = task.result.strip().splitlines()[0][:160]
                                handoff = f"\n{r}"
                            msg = (
                                f"✔ {tag}Kanban {sub['task_id']} done"
                                f" — {title}{handoff}"
                            )
                        elif kind == "blocked":
                            reason = ""
                            if ev.payload and ev.payload.get("reason"):
                                reason = f": {str(ev.payload['reason'])[:160]}"
                            msg = f"⏸ {tag}Kanban {sub['task_id']} blocked{reason}"
                        elif kind == "gave_up":
                            err = ""
                            if ev.payload and ev.payload.get("error"):
                                err = f"\n{str(ev.payload['error'])[:200]}"
                            msg = (
                                f"✖ {tag}Kanban {sub['task_id']} gave up "
                                f"after repeated spawn failures{err}"
                            )
                        elif kind == "crashed":
                            msg = (
                                f"✖ {tag}Kanban {sub['task_id']} worker crashed "
                                f"(pid gone); dispatcher will retry"
                            )
                        elif kind == "timed_out":
                            limit = 0
                            if ev.payload and ev.payload.get("limit_seconds"):
                                limit = int(ev.payload["limit_seconds"])
                            msg = (
                                f"⏱ {tag}Kanban {sub['task_id']} timed out "
                                f"(max_runtime={limit}s); will retry"
                            )
                        else:
                            continue
                        metadata: dict[str, Any] = {}
                        if sub.get("thread_id"):
                            metadata["thread_id"] = sub["thread_id"]
                        sub_key = (
                            sub["task_id"], sub["platform"],
                            sub["chat_id"], sub.get("thread_id") or "",
                        )
                        try:
                            await adapter.send(
                                sub["chat_id"], msg, metadata=metadata,
                            )
                            logger.debug(
                                "kanban notifier: delivered %s event for %s to %s/%s on board %s",
                                kind, sub["task_id"], platform_str, sub["chat_id"], board_slug,
                            )
                            # After delivering the text notification, surface
                            # any artifact paths the worker referenced in
                            # ``kanban_complete(summary=..., artifacts=[...])``
                            # (or the legacy ``result`` field) as native
                            # uploads. ``extract_local_files`` finds bare
                            # absolute paths in the summary;
                            # ``send_document`` / ``send_image_file`` uploads
                            # them. Only fires on the ``completed`` event so
                            # we never spam attachments on retries.
                            if kind == "completed":
                                try:
                                    await self._deliver_kanban_artifacts(
                                        adapter=adapter,
                                        chat_id=sub["chat_id"],
                                        metadata=metadata,
                                        event_payload=getattr(ev, "payload", None),
                                        task=task,
                                    )
                                except Exception as art_exc:
                                    logger.debug(
                                        "kanban notifier: artifact delivery for %s failed: %s",
                                        sub["task_id"], art_exc,
                                    )
                            # Reset the failure counter on success.
                            sub_fail_counts.pop(sub_key, None)
                        except Exception as exc:
                            fails = sub_fail_counts.get(sub_key, 0) + 1
                            sub_fail_counts[sub_key] = fails
                            logger.warning(
                                "kanban notifier: send failed for %s on %s "
                                "(attempt %d/%d): %s",
                                sub["task_id"], platform_str, fails,
                                MAX_SEND_FAILURES, exc,
                            )
                            if fails >= MAX_SEND_FAILURES:
                                logger.warning(
                                    "kanban notifier: dropping subscription "
                                    "%s on %s after %d consecutive send failures",
                                    sub["task_id"], platform_str, fails,
                                )
                                await asyncio.to_thread(self._kanban_unsub, sub, board_slug)
                                sub_fail_counts.pop(sub_key, None)
                            else:
                                await asyncio.to_thread(
                                    self._kanban_rewind,
                                    sub,
                                    d["cursor"],
                                    d.get("old_cursor", 0),
                                    board_slug,
                                )
                            # Rewind the pre-send claim on transient failure so
                            # a later tick can retry. After too many failures,
                            # dropping the subscription is the terminal action.
                            break
                    else:
                        # All events delivered; advance cursor. The cursor
                        # is the dedup mechanism — it prevents re-delivery
                        # of the same event on subsequent ticks.
                        await asyncio.to_thread(
                            self._kanban_advance, sub, d["cursor"], board_slug,
                        )
                        # Unsubscribe only when the task has reached a truly
                        # final status (done / archived). For blocked /
                        # gave_up / crashed / timed_out the subscription is
                        # kept alive so the user gets notified again if the
                        # dispatcher respawns the task and it cycles into the
                        # same state. See the longer comment on TERMINAL_KINDS
                        # above for the failure mode this prevents.
                        task_terminal = task and task.status in {"done", "archived"}
                        if task_terminal:
                            await asyncio.to_thread(
                                self._kanban_unsub, sub, board_slug,
                            )
            except Exception as exc:
                logger.warning("kanban notifier tick failed: %s", exc)
            # Sleep with cancellation checks.
            for _ in range(int(max(1, interval))):
                if not self._running:
                    return
                await asyncio.sleep(1)

    def _kanban_advance(
        self, sub: dict, cursor: int, board: Optional[str] = None,
    ) -> None:
        """Sync helper: advance a subscription's cursor. Runs in to_thread.

        ``board`` scopes the DB connection to the board that owns this
        subscription. Unsub cursors in one board can't touch another's.
        """
        from hermes_cli import kanban_db as _kb
        conn = _kb.connect(board=board)
        try:
            _kb.advance_notify_cursor(
                conn,
                task_id=sub["task_id"],
                platform=sub["platform"],
                chat_id=sub["chat_id"],
                thread_id=sub.get("thread_id") or "",
                new_cursor=cursor,
            )
        finally:
            conn.close()

    def _kanban_unsub(self, sub: dict, board: Optional[str] = None) -> None:
        from hermes_cli import kanban_db as _kb
        conn = _kb.connect(board=board)
        try:
            _kb.remove_notify_sub(
                conn,
                task_id=sub["task_id"],
                platform=sub["platform"],
                chat_id=sub["chat_id"],
                thread_id=sub.get("thread_id") or "",
            )
        finally:
            conn.close()

    def _kanban_rewind(
        self,
        sub: dict,
        claimed_cursor: int,
        old_cursor: int,
        board: Optional[str] = None,
    ) -> None:
        """Sync helper: undo a claimed notification cursor after send failure."""
        from hermes_cli import kanban_db as _kb
        conn = _kb.connect(board=board)
        try:
            _kb.rewind_notify_cursor(
                conn,
                task_id=sub["task_id"],
                platform=sub["platform"],
                chat_id=sub["chat_id"],
                thread_id=sub.get("thread_id") or "",
                claimed_cursor=claimed_cursor,
                old_cursor=old_cursor,
            )
        finally:
            conn.close()

    async def _deliver_kanban_artifacts(
        self,
        *,
        adapter,
        chat_id: str,
        metadata: dict,
        event_payload: Optional[dict],
        task,
    ) -> None:
        """Upload artifact files referenced by a completed kanban task.

        Workers passing ``kanban_complete(artifacts=[...])`` ship absolute
        file paths through the completion event so downstream humans get
        the deliverable as a native upload instead of a path printed in
        chat.

        Sources scanned, in priority order:
          1. ``event_payload['artifacts']`` (explicit list — preferred)
          2. ``event_payload['summary']`` (truncated first line)
          3. ``task.result`` (legacy fallback)

        Files are deduplicated, missing files are silently skipped (the
        path may have been mentioned for reference only), and delivery
        errors are logged but do not break the notifier loop.
        """
        from pathlib import Path as _Path

        candidates: list[str] = []
        seen: set[str] = set()

        def _add(path: str) -> None:
            if not path:
                return
            expanded = os.path.expanduser(path)
            if expanded in seen:
                return
            if not os.path.isfile(expanded):
                return
            seen.add(expanded)
            candidates.append(expanded)

        # 1. Explicit artifacts list in payload.
        if isinstance(event_payload, dict):
            raw = event_payload.get("artifacts")
            if isinstance(raw, (list, tuple)):
                for item in raw:
                    if isinstance(item, str):
                        _add(item)

            # 2. Paths embedded in the payload summary.
            summary = event_payload.get("summary")
            if isinstance(summary, str) and summary:
                paths, _ = adapter.extract_local_files(summary)
                for p in paths:
                    _add(p)

        # 3. Legacy: paths embedded in task.result.
        if task is not None and getattr(task, "result", None):
            result_text = str(task.result)
            paths, _ = adapter.extract_local_files(result_text)
            for p in paths:
                _add(p)

        if not candidates:
            return

        from gateway.platforms.base import BasePlatformAdapter
        candidates = BasePlatformAdapter.filter_local_delivery_paths(candidates)
        if not candidates:
            return

        _IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".gif", ".webp"}
        _VIDEO_EXTS = {".mp4", ".mov", ".avi", ".mkv", ".webm", ".3gp"}

        from urllib.parse import quote as _quote

        # Partition images so they ride a single send_multiple_images call
        # on platforms that support batch image uploads (Signal/Slack RPCs).
        image_paths = [p for p in candidates if _Path(p).suffix.lower() in _IMAGE_EXTS]
        other_paths = [p for p in candidates if _Path(p).suffix.lower() not in _IMAGE_EXTS]

        if image_paths:
            try:
                batch = [(f"file://{_quote(p)}", "") for p in image_paths]
                await adapter.send_multiple_images(
                    chat_id=chat_id, images=batch, metadata=metadata,
                )
            except Exception as exc:
                logger.warning(
                    "kanban notifier: image batch upload failed: %s", exc,
                )

        for path in other_paths:
            ext = _Path(path).suffix.lower()
            try:
                if ext in _VIDEO_EXTS:
                    await adapter.send_video(
                        chat_id=chat_id, video_path=path, metadata=metadata,
                    )
                else:
                    await adapter.send_document(
                        chat_id=chat_id, file_path=path, metadata=metadata,
                    )
            except Exception as exc:
                logger.warning(
                    "kanban notifier: artifact upload (%s) failed: %s",
                    path, exc,
                )

    def _ensure_kanban_dispatch_dirty_event(self) -> asyncio.Event:
        event = getattr(self, "_kanban_dispatch_dirty_event", None)
        if event is None:
            event = asyncio.Event()
            self._kanban_dispatch_dirty_event = event
        return event

    def _signal_kanban_dispatcher_dirty(self) -> bool:
        """Wake the embedded kanban dispatcher after new gateway-created work."""
        try:
            self._ensure_kanban_dispatch_dirty_event().set()
            return True
        except Exception:
            logger.debug("kanban dispatcher: dirty signal failed", exc_info=True)
            return False

    def _discord_worker_dirty_marker_changed(self, marker_state_attr: str) -> bool:
        """Return True when a Discord worker subprocess updated the dirty marker."""
        try:
            from hermes_cli import discord_worker_boards as _dwb

            marker = _dwb.dispatch_dirty_marker_mtime_ns()
        except Exception:
            return False
        last = int(getattr(self, marker_state_attr, 0) or 0)
        if marker <= 0 or marker <= last:
            return False
        setattr(self, marker_state_attr, marker)
        return True

    def _discord_worker_dispatch_marker_changed(self) -> bool:
        """Return True when a Discord role subprocess requested dispatch."""
        return self._discord_worker_dirty_marker_changed("_kanban_dispatch_dirty_marker_ns")

    async def _sleep_until_discord_worker_dirty_or_timeout(
        self,
        interval: float,
        *,
        marker_state_attr: str,
        event: Optional[asyncio.Event] = None,
    ) -> bool:
        """Sleep until a dirty marker/event wakes this watcher or timeout expires."""
        remaining = max(float(interval or 0), 0.0)
        while getattr(self, "_running", True) and remaining > 0:
            if self._discord_worker_dirty_marker_changed(marker_state_attr):
                return True
            step = min(_DISCORD_WORKER_DIRTY_MARKER_POLL_SECS, remaining)
            if event is None:
                await asyncio.sleep(step)
            else:
                try:
                    await asyncio.wait_for(event.wait(), timeout=step)
                except asyncio.TimeoutError:
                    remaining -= step
                    continue
                event.clear()
                return True
            remaining -= step
        if self._discord_worker_dirty_marker_changed(marker_state_attr):
            return True
        return False

    async def _sleep_until_kanban_dispatch_due(self, interval: float) -> bool:
        """Sleep until the next dispatcher tick or an explicit dirty signal.

        Returns True when a dirty signal woke the sleep early, False on timeout.
        """
        event = self._ensure_kanban_dispatch_dirty_event()
        return await self._sleep_until_discord_worker_dirty_or_timeout(
            interval,
            marker_state_attr="_kanban_dispatch_dirty_marker_ns",
            event=event,
        )

    def _log_gateway_flow_telemetry(
        self,
        *,
        route_type: str,
        source: Any = None,
        session_id: Optional[str] = None,
        admission_ts: Optional[float] = None,
        dispatch_start_ts: Optional[float] = None,
        finished_ts: Optional[float] = None,
        phase_timestamps: Optional[dict[str, Any]] = None,
        phase_durations: Optional[dict[str, Any]] = None,
    ) -> None:
        fields = _gateway_flow_telemetry_fields(
            route_type=route_type,
            source=source,
            session_id=session_id,
            admission_ts=admission_ts,
            dispatch_start_ts=dispatch_start_ts,
            finished_ts=finished_ts,
            phase_timestamps=phase_timestamps,
            phase_durations=phase_durations,
        )
        logger.info(_format_gateway_flow_telemetry(fields))

    async def _kanban_dispatcher_watcher(self) -> None:
        """Embedded kanban dispatcher — one tick every `dispatch_interval_seconds`.

        Gated by `kanban.dispatch_in_gateway` in config.yaml (default True).
        When true, the gateway hosts the single dispatcher for this profile:
        no separate `hermes kanban daemon` process needed. When false, the
        loop exits immediately and an external daemon is expected.

        Each tick calls :func:`kanban_db.dispatch_once` inside
        ``asyncio.to_thread`` so the SQLite WAL lock never blocks the
        event loop. Failures in one tick don't stop subsequent ticks —
        same pattern as `_kanban_notifier_watcher`.

        Shutdown: the loop checks ``self._running`` between ticks; gateway
        stop() flips it to False and cancels pending tasks, and the
        in-flight ``to_thread`` returns on its own after the current
        ``dispatch_once`` call finishes (typically <1ms on an idle board).
        """
        # Read config once at boot. If the user flips the flag later, they
        # restart the gateway; same pattern as every other background
        # watcher here. Honours HERMES_KANBAN_DISPATCH_IN_GATEWAY env var
        # as an escape hatch (false-y value disables without editing YAML).
        try:
            from hermes_cli.config import load_config as _load_config
        except Exception:
            logger.warning("kanban dispatcher: config loader unavailable; disabled")
            return
        env_override = os.environ.get("HERMES_KANBAN_DISPATCH_IN_GATEWAY", "").strip().lower()
        if env_override in {"0", "false", "no", "off"}:
            logger.info("kanban dispatcher: disabled via HERMES_KANBAN_DISPATCH_IN_GATEWAY env")
            return

        try:
            cfg = _load_config()
        except Exception as exc:
            logger.warning("kanban dispatcher: cannot load config (%s); disabled", exc)
            return
        kanban_cfg = cfg.get("kanban", {}) if isinstance(cfg, dict) else {}
        if not kanban_cfg.get("dispatch_in_gateway", True):
            logger.info(
                "kanban dispatcher: disabled via config kanban.dispatch_in_gateway=false"
            )
            return

        try:
            from hermes_cli import kanban_db as _kb
        except Exception:
            logger.warning("kanban dispatcher: kanban_db not importable; dispatcher disabled")
            return

        interval = float(kanban_cfg.get("dispatch_interval_seconds", 5) or 5)
        interval = max(interval, 1.0)  # sanity floor — tighter than this is a footgun

        # Read max_spawn config to limit concurrent kanban tasks
        max_spawn = kanban_cfg.get("max_spawn", None)
        if max_spawn is not None:
            logger.info(f"kanban dispatcher: max_spawn={max_spawn}")

        discord_worker_cfg = (
            kanban_cfg.get("discord_worker", {})
            if isinstance(kanban_cfg.get("discord_worker", {}), dict)
            else {}
        )

        def _positive_int_config(value, default: int) -> int:
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                return default
            return parsed if parsed > 0 else default

        discord_max_global_workers = _positive_int_config(
            discord_worker_cfg.get("max_global_workers"),
            8,
        )
        discord_max_workers_per_board = _positive_int_config(
            discord_worker_cfg.get("max_workers_per_board"),
            2,
        )
        logger.info(
            "kanban dispatcher: Discord worker pool max_global_workers=%d max_workers_per_board=%d",
            discord_max_global_workers,
            discord_max_workers_per_board,
        )

        # Cap the number of simultaneously running tasks so slow workers
        # (local LLMs, resource-constrained hosts) don't pile up and time
        # out. When set, the dispatcher skips spawning when the board
        # already has this many tasks in 'running' status.
        raw_max_in_progress = kanban_cfg.get("max_in_progress", None)
        max_in_progress = None
        if raw_max_in_progress is not None:
            try:
                max_in_progress = int(raw_max_in_progress)
            except (TypeError, ValueError):
                logger.warning(
                    "kanban dispatcher: invalid kanban.max_in_progress=%r; ignoring",
                    raw_max_in_progress,
                )
                max_in_progress = None
            else:
                if max_in_progress < 1:
                    logger.warning(
                        "kanban dispatcher: kanban.max_in_progress=%r is below 1; ignoring",
                        raw_max_in_progress,
                    )
                    max_in_progress = None
                else:
                    logger.info(f"kanban dispatcher: max_in_progress={max_in_progress}")

        raw_failure_limit = kanban_cfg.get("failure_limit", _kb.DEFAULT_FAILURE_LIMIT)
        try:
            failure_limit = int(raw_failure_limit)
        except (TypeError, ValueError):
            logger.warning(
                "kanban dispatcher: invalid kanban.failure_limit=%r; using default %d",
                raw_failure_limit,
                _kb.DEFAULT_FAILURE_LIMIT,
            )
            failure_limit = _kb.DEFAULT_FAILURE_LIMIT
        if failure_limit < 1:
            logger.warning(
                "kanban dispatcher: kanban.failure_limit=%r is below 1; using default %d",
                raw_failure_limit,
                _kb.DEFAULT_FAILURE_LIMIT,
            )
            failure_limit = _kb.DEFAULT_FAILURE_LIMIT

        # Read stale_timeout_seconds — 0 disables stale detection.
        raw_stale = kanban_cfg.get("dispatch_stale_timeout_seconds", 0)
        try:
            stale_timeout_seconds = int(raw_stale or 0)
        except (TypeError, ValueError):
            logger.warning(
                "kanban dispatcher: invalid kanban.dispatch_stale_timeout_seconds=%r; "
                "disabling stale detection",
                raw_stale,
            )
            stale_timeout_seconds = 0

        # Read kanban.default_assignee — fallback profile for tasks
        # created without an explicit assignee (e.g. via the dashboard).
        # When set, the dispatcher applies it to unassigned ready tasks
        # instead of skipping them indefinitely (#27145). Empty string
        # (the schema default) means "no fallback, keep skipping" —
        # backward-compatible with existing installs.
        default_assignee = (kanban_cfg.get("default_assignee") or "").strip() or None
        if default_assignee:
            logger.info(
                "kanban dispatcher: default_assignee=%r (unassigned ready tasks "
                "will route to this profile)",
                default_assignee,
            )

        # Read kanban.max_in_progress_per_profile — per-profile concurrency
        # cap (#21582). When set, no single profile gets more than N
        # workers running at once, even if the global max_in_progress
        # would allow it. Prevents one profile's local model / API quota
        # / browser pool from being overwhelmed by a fan-out.
        raw_per_profile = kanban_cfg.get("max_in_progress_per_profile", None)
        max_in_progress_per_profile = None
        if raw_per_profile is not None:
            try:
                max_in_progress_per_profile = int(raw_per_profile)
            except (TypeError, ValueError):
                logger.warning(
                    "kanban dispatcher: invalid kanban.max_in_progress_per_profile=%r; ignoring",
                    raw_per_profile,
                )
                max_in_progress_per_profile = None
            else:
                if max_in_progress_per_profile < 1:
                    logger.warning(
                        "kanban dispatcher: kanban.max_in_progress_per_profile=%r is below 1; ignoring",
                        raw_per_profile,
                    )
                    max_in_progress_per_profile = None
                else:
                    logger.info(
                        "kanban dispatcher: max_in_progress_per_profile=%d",
                        max_in_progress_per_profile,
                    )

        # Initial delay so the gateway finishes wiring adapters before the
        # dispatcher spawns workers (those workers may hit gateway notify
        # subscriptions etc.). Matches the notifier watcher's delay.
        await asyncio.sleep(5)

        # Health telemetry mirrored from `_cmd_daemon`: warn when ready
        # queue is non-empty but spawns are 0 for N consecutive ticks —
        # usually means broken PATH, missing venv, or credential loss.
        HEALTH_WINDOW = 6
        bad_ticks = 0
        last_warn_at = 0
        def _board_db_identity(slug: str) -> tuple[str, int | None, int | None]:
            path = _kb.kanban_db_path(slug)
            try:
                resolved = str(path.expanduser().resolve())
            except Exception:
                resolved = str(path)
            try:
                stat = path.stat()
            except OSError:
                return (resolved, None, None)
            return (resolved, stat.st_mtime_ns, stat.st_size)

        def _board_db_fingerprint(slug: str) -> tuple[str, str | None]:
            identity = _board_db_identity(slug)
            try:
                fingerprint = _kb._db_content_fingerprint(Path(identity[0]))
            except Exception:
                fingerprint = None
            return (identity[0], fingerprint)

        def _corrupt_quarantine_state(slug: str) -> dict:
            try:
                state = _kb.corrupt_board_quarantine_state(slug)
            except Exception:
                return {"open_allowed": True, "skipped": False}
            if state.get("changed_fingerprint"):
                logger.info(
                    "kanban dispatcher: board %s database changed since corruption incident; retrying health checks",
                    slug,
                )
            return state

        def _paused_corrupt_incident(slug: str) -> Optional[dict]:
            state = _corrupt_quarantine_state(slug)
            return state.get("incident") if state.get("skipped") else None

        def _record_corrupt_board(slug: str, exc: Exception) -> Optional[dict]:
            fingerprint = _board_db_fingerprint(slug)
            incident = getattr(exc, "incident", None)
            if not isinstance(incident, dict):
                backup_path = getattr(exc, "backup_path", None)
                reason = getattr(exc, "reason", None) or str(exc)
                incident = _kb.record_corrupt_board_incident(
                    slug,
                    Path(fingerprint[0]),
                    str(reason),
                    backup_path=backup_path,
                    fingerprint=fingerprint[1],
                    error_class=exc.__class__.__name__,
                )
            return incident

        def _log_corrupt_board_incident(slug: str, incident: Optional[dict], exc: Exception) -> None:
            if not _kb.should_log_corrupt_board_incident(incident):
                return
            incident = incident or {}
            logger.error(
                "kanban dispatcher: board %s database corruption incident; "
                "db_path=%s quarantine_path=%s reason=%s. Dispatch and notifier "
                "polling are paused for this board while the DB fingerprint is "
                "unchanged. Repair guidance: restore a known-good backup or run "
                "`hermes kanban repair --board %s`, then retry after integrity "
                "checks pass.",
                slug,
                incident.get("db_path") or _board_db_fingerprint(slug)[0],
                incident.get("quarantine_path") or getattr(exc, "backup_path", None) or "<unavailable>",
                incident.get("reason") or getattr(exc, "reason", None) or str(exc),
                slug,
            )

        def _tick_once_for_board(slug: str) -> "Optional[object]":
            """Run one dispatch_once for a specific board.

            Runs in a worker thread via `asyncio.to_thread`. `board=slug`
            is passed through `dispatch_once` so `resolve_workspace` and
            `_default_spawn` see the right paths. The per-board DB is
            opened explicitly so concurrent boards never share a
            connection handle or accidentally claim across each other.
            """
            conn = None
            state = _corrupt_quarantine_state(slug)
            if state.get("skipped"):
                logger.debug(
                    "kanban dispatcher: board %s paused for unchanged DB corruption; "
                    "skipping dispatch db_path=%s next_retry=%s reason=%s",
                    slug,
                    state.get("db_path"),
                    state.get("next_retry"),
                    state.get("reason"),
                )
                return None
            try:
                conn = _kb.connect(board=slug)
                # `connect()` runs the schema + idempotent migration on
                # first open per process; the previous explicit
                # `init_db()` call here busted the per-process cache and
                # re-ran the migration on a second connection, racing
                # the first. See the matching comment in
                # `_kanban_notifier_watcher` and issue #21378.
                ready, incident = _kb.board_schema_ready(
                    conn,
                    board=slug,
                    operation="dispatcher",
                    required_tables=("tasks",),
                )
                if not ready:
                    _log_corrupt_board_incident(slug, incident, RuntimeError(
                        (incident or {}).get("reason") or "kanban board schema not ready"
                    ))
                    return None
                # Legacy Discord default-board intake rows were created as
                # blocked+unassigned; if an operator unblocks one, route only
                # that intake tenant instead of generic unassigned work.
                if slug == _kb.DEFAULT_BOARD:
                    intake_assignee = _resolve_default_board_intake_assignee(cfg)
                    assigned_intake = _assign_default_board_intake_ready_tasks(
                        conn,
                        intake_assignee,
                    )
                    if assigned_intake:
                        logger.info(
                            "kanban dispatcher [%s]: assigned %d default-board "
                            "intake task(s) to %s: %s",
                            slug,
                            len(assigned_intake),
                            intake_assignee,
                            ", ".join(assigned_intake[:8]),
                        )
                return _kb.dispatch_once(
                    conn,
                    board=slug,
                    max_spawn=max_spawn,
                    max_in_progress=max_in_progress,
                    failure_limit=failure_limit,
                    stale_timeout_seconds=stale_timeout_seconds,
                    default_assignee=default_assignee,
                    max_in_progress_per_profile=max_in_progress_per_profile,
                )
            except sqlite3.DatabaseError as exc:
                if _kb.is_corrupt_board_db_error(exc):
                    _log_corrupt_board_incident(slug, _record_corrupt_board(slug, exc), exc)
                    return None
                logger.exception("kanban dispatcher: tick failed on board %s", slug)
                return None
            except Exception as exc:
                if _kb.is_corrupt_board_db_error(exc):
                    _log_corrupt_board_incident(slug, _record_corrupt_board(slug, exc), exc)
                    return None
                logger.exception("kanban dispatcher: tick failed on board %s", slug)
                return None
            finally:
                if conn is not None:
                    try:
                        conn.close()
                    except Exception:
                        pass

        def _tick_once() -> "list[tuple[str, Optional[object]]]":
            """Run one dispatch_once per board. Returns (slug, result) pairs.

            Enumerating boards on every tick keeps the dispatcher honest
            when users create a new board mid-run: no restart required,
            the next tick picks it up automatically.
            """
            try:
                boards = _kb.list_boards(include_archived=False)
            except Exception:
                boards = [_kb.read_board_metadata(_kb.DEFAULT_BOARD)]
            out: list[tuple[str, "Optional[object]"]] = []
            discord_slugs: list[str] = []
            try:
                from hermes_cli import discord_worker_boards as _dwb

                for b in boards:
                    slug = b.get("slug") or _kb.DEFAULT_BOARD
                    if _dwb.is_discord_worker_board(slug) and not _paused_corrupt_incident(slug):
                        discord_slugs.append(slug)
            except Exception:
                logger.debug("kanban dispatcher: Discord board detection failed", exc_info=True)
                discord_slugs = []

            discord_slug_set = set(discord_slugs)
            if discord_slugs:
                cursor = int(getattr(self, "_discord_worker_dispatch_cursor", 0) or 0)
                offset = cursor % len(discord_slugs)
                ordered_discord_slugs = discord_slugs[offset:] + discord_slugs[:offset]
                self._discord_worker_dispatch_cursor = (cursor + 1) % len(discord_slugs)
                try:
                    from hermes_cli.discord_worker_dispatch import dispatch_discord_worker_boards

                    out.extend(
                        dispatch_discord_worker_boards(
                            ordered_discord_slugs,
                            max_global_workers=discord_max_global_workers,
                            max_workers_per_board=discord_max_workers_per_board,
                            failure_limit=failure_limit,
                            stale_timeout_seconds=stale_timeout_seconds,
                        )
                    )
                except Exception:
                    logger.exception("kanban dispatcher: Discord worker dispatch failed")
            for b in boards:
                slug = b.get("slug") or _kb.DEFAULT_BOARD
                if slug in discord_slug_set:
                    continue
                out.append((slug, _tick_once_for_board(slug)))
            return out

        def _ready_nonempty() -> bool:
            """Cheap probe: is there ready work the dispatcher must explain?

            Counts ready+assigned+unclaimed tasks whose assignee maps to a
            real Hermes profile (i.e. work the dispatcher would actually
            spawn for). On the top-level default board, also counts
            READY+unassigned tasks as operator-actionable routing blockers.

            Tasks assigned to control-plane lanes (e.g. ``orion-cc``,
            ``orion-research``) are pulled by terminals via
            ``claim_task`` directly and never spawnable, so a queue full
            of those is "correctly idle", not "stuck". Filtering them out
            here keeps the stuck-warn fire only on real failures (broken
            PATH, missing venv, credential loss for a real Hermes profile).
            """
            try:
                boards = _kb.list_boards(include_archived=False)
            except Exception:
                boards = [_kb.read_board_metadata(_kb.DEFAULT_BOARD)]
            discord_running_total = 0
            discord_running_by_board: dict[str, int] = {}
            try:
                from hermes_cli import discord_worker_boards as _dwb
                from hermes_cli.discord_worker_dispatch import running_role_count

                for b in boards:
                    slug = b.get("slug") or _kb.DEFAULT_BOARD
                    if (
                        _dwb.is_discord_worker_board(slug)
                        and _kanban_dispatch_health_candidate(slug, _dwb)
                    ):
                        running = running_role_count(slug)
                        discord_running_by_board[slug] = running
                        discord_running_total += running
            except Exception:
                discord_running_by_board = {}
                discord_running_total = 0
            for b in boards:
                slug = b.get("slug") or _kb.DEFAULT_BOARD
                if _paused_corrupt_incident(slug):
                    continue
                conn = None
                try:
                    conn = _kb.connect(board=slug)
                    try:
                        from hermes_cli import discord_worker_boards as _dwb

                        if _dwb.is_discord_worker_board(slug):
                            if not _kanban_dispatch_health_candidate(slug, _dwb):
                                continue
                            board_running = discord_running_by_board.get(slug, 0)
                            if (
                                discord_running_total >= discord_max_global_workers
                                or board_running >= discord_max_workers_per_board
                            ):
                                continue
                        ready = _kb.has_spawnable_ready(
                            conn,
                            include_unassigned=(slug == _kb.DEFAULT_BOARD),
                            additional_spawnable_assignees=(
                                _dwb.ROLE_ASSIGNEES if _dwb.is_discord_worker_board(slug) else None
                            ),
                        )
                        if ready or _kb.has_spawnable_review(conn):
                            return True
                    except Exception:
                        ready = _kb.has_spawnable_ready(
                            conn,
                            include_unassigned=(slug == _kb.DEFAULT_BOARD),
                        )
                        if ready or _kb.has_spawnable_review(conn):
                            return True
                except Exception:
                    continue
                finally:
                    if conn is not None:
                        try:
                            conn.close()
                        except Exception:
                            pass
            return False

        def _dispatcher_blocker_detail() -> str:
            """Summarize why ready work did not produce worker spawns."""
            try:
                boards = _kb.list_boards(include_archived=False)
            except Exception:
                boards = [_kb.read_board_metadata(_kb.DEFAULT_BOARD)]
            try:
                from hermes_cli.profiles import profile_exists
            except Exception:
                profile_exists = None  # type: ignore[assignment]
            try:
                from hermes_cli import discord_worker_boards as _dwb
                from hermes_cli.discord_worker_dispatch import running_role_count
            except Exception:
                _dwb = None  # type: ignore[assignment]
                running_role_count = None  # type: ignore[assignment]
            details: list[str] = []
            for b in boards:
                slug = str(b.get("slug") or _kb.DEFAULT_BOARD)
                if _paused_corrupt_incident(slug):
                    continue
                conn = None
                try:
                    conn = _kb.connect(board=slug)
                    rows = conn.execute(
                        "SELECT id, status, assignee, last_failure_error "
                        "FROM tasks WHERE status IN ('ready', 'review') "
                        "AND claim_lock IS NULL ORDER BY priority DESC, created_at ASC LIMIT 20"
                    ).fetchall()
                    if not rows:
                        continue
                    is_discord = bool(_dwb and _dwb.is_discord_worker_board(slug))
                    if is_discord and not _kanban_dispatch_health_candidate(slug, _dwb):
                        continue
                    extra = set(_dwb.ROLE_ASSIGNEES) if is_discord and _dwb else set()
                    unassigned = 0
                    nonspawnable: set[str] = set()
                    guarded: dict[str, int] = {}
                    spawnable: set[str] = set()
                    for row in rows:
                        assignee = str(row["assignee"] or "").strip()
                        if not assignee:
                            unassigned += 1
                            continue
                        assignee_key = assignee.lower()
                        if (
                            profile_exists is not None
                            and assignee_key not in extra
                            and not profile_exists(assignee)
                        ):
                            nonspawnable.add(assignee)
                            continue
                        reason = _kb.check_respawn_guard(conn, row["id"])
                        if reason:
                            guarded[reason] = guarded.get(reason, 0) + 1
                            continue
                        spawnable.add(assignee)
                    parts = []
                    if spawnable:
                        parts.append("spawnable=" + ",".join(sorted(spawnable)[:4]))
                    if unassigned:
                        parts.append(f"unassigned={unassigned}")
                    if nonspawnable:
                        parts.append("nonprofile=" + ",".join(sorted(nonspawnable)[:4]))
                    if guarded:
                        parts.append(
                            "guarded="
                            + ",".join(f"{key}:{value}" for key, value in sorted(guarded.items()))
                        )
                    if is_discord and running_role_count is not None:
                        try:
                            board_running = int(running_role_count(slug) or 0)
                        except Exception:
                            board_running = 0
                        if board_running >= discord_max_workers_per_board:
                            parts.append(
                                f"board_worker_cap={board_running}/{discord_max_workers_per_board}"
                            )
                    if parts:
                        details.append(f"{slug}: " + "; ".join(parts))
                except Exception:
                    continue
                finally:
                    if conn is not None:
                        try:
                            conn.close()
                        except Exception:
                            pass
                if len(details) >= 3:
                    break
            return " | ".join(details)

        # Auto-decompose: turn fresh triage tasks into ready workgraphs
        # before the dispatcher fans out workers. Gated by
        # ``kanban.auto_decompose`` (default True). Capped by
        # ``kanban.auto_decompose_per_tick`` (default 3) so a bulk-load
        # of triage tasks doesn't burst-spend the aux LLM in one tick;
        # remainder defers to subsequent ticks.
        auto_decompose_enabled = bool(kanban_cfg.get("auto_decompose", True))
        try:
            auto_decompose_per_tick = int(
                kanban_cfg.get("auto_decompose_per_tick", 3) or 3
            )
        except (TypeError, ValueError):
            auto_decompose_per_tick = 3
        if auto_decompose_per_tick < 1:
            auto_decompose_per_tick = 1

        def _auto_decompose_tick() -> int:
            """Run the auto-decomposer for up to N triage tasks across all
            boards. Returns the number of triage tasks that were
            successfully decomposed or specified this tick.
            """
            try:
                from hermes_cli import kanban_decompose as _decomp
            except Exception as exc:  # pragma: no cover
                logger.warning(
                    "kanban auto-decompose: import failed (%s); skipping", exc,
                )
                return 0
            try:
                boards = _kb.list_boards(include_archived=False)
            except Exception:
                boards = [_kb.read_board_metadata(_kb.DEFAULT_BOARD)]
            attempted = 0
            successes = 0
            for b in boards:
                slug = b.get("slug") or _kb.DEFAULT_BOARD
                if attempted >= auto_decompose_per_tick:
                    break
                if _paused_corrupt_incident(slug):
                    continue
                try:
                    from hermes_cli import discord_worker_boards as _dwb
                    if _dwb.is_discord_worker_board(slug):
                        continue
                except Exception:
                    pass
                try:
                    try:
                        triage_ids = _decomp.list_triage_ids(board=slug)
                    except Exception as exc:
                        logger.debug(
                            "kanban auto-decompose: list_triage_ids failed on board %s (%s)",
                            slug, exc,
                        )
                        triage_ids = []
                    for tid in triage_ids:
                        if attempted >= auto_decompose_per_tick:
                            break
                        attempted += 1
                        try:
                            outcome = _decomp.decompose_task(
                                tid, author="auto-decomposer", board=slug,
                            )
                        except Exception:
                            logger.exception(
                                "kanban auto-decompose: decompose_task crashed on %s",
                                tid,
                            )
                            continue
                        if outcome.ok:
                            successes += 1
                            if outcome.fanout and outcome.child_ids:
                                logger.info(
                                    "kanban auto-decompose [%s]: %s → %d children",
                                    slug, tid, len(outcome.child_ids),
                                )
                            else:
                                logger.info(
                                    "kanban auto-decompose [%s]: %s → single task (no fanout)",
                                    slug, tid,
                                )
                        else:
                            # Common no-op reasons (no aux client configured) shouldn't
                            # spam logs every tick. Log at debug.
                            logger.debug(
                                "kanban auto-decompose [%s]: %s skipped: %s",
                                slug, tid, outcome.reason,
                            )
                except Exception:
                    logger.exception("kanban auto-decompose: tick failed on board %s", slug)
            return successes

        logger.info(
            "kanban dispatcher: embedded in gateway (interval=%.1fs)", interval
        )
        while self._running:
            try:
                self._ensure_kanban_dispatch_dirty_event().clear()
                # Reap zombie children before per-board work so a board DB
                # failure cannot block cleanup of unrelated workers.
                pids = await asyncio.to_thread(_kb.reap_worker_zombies)
                if pids:
                    logger.info(
                        "kanban dispatcher: reaped %d zombie worker(s), pids=%s",
                        len(pids),
                        pids,
                    )
            except Exception:
                logger.exception("kanban dispatcher: zombie reaper failed")

            try:
                if auto_decompose_enabled:
                    await asyncio.to_thread(_auto_decompose_tick)
                results = await asyncio.to_thread(_tick_once)
                any_spawned = False
                for slug, res in (results or []):
                    if res is not None and getattr(res, "spawned", None):
                        any_spawned = True
                        # Quiet by default — only log when something actually
                        # happened, so an idle gateway stays silent.
                        logger.info(
                            "kanban dispatcher [%s]: spawned=%d reclaimed=%d "
                            "crashed=%d timed_out=%d promoted=%d auto_blocked=%d",
                            slug,
                            len(res.spawned),
                            res.reclaimed,
                            len(res.crashed) if hasattr(res.crashed, "__len__") else 0,
                            len(res.timed_out) if hasattr(res.timed_out, "__len__") else 0,
                            res.promoted,
                            len(res.auto_blocked) if hasattr(res.auto_blocked, "__len__") else 0,
                        )
                if any_spawned:
                    await self._discord_worker_announce_spawned_tasks(results)
                # Health telemetry (aggregate across boards)
                ready_pending = await asyncio.to_thread(_ready_nonempty)
                if ready_pending and not any_spawned:
                    bad_ticks += 1
                else:
                    bad_ticks = 0
                if bad_ticks >= HEALTH_WINDOW:
                    now = int(time.time())
                    if now - last_warn_at >= 300:
                        detail = await asyncio.to_thread(_dispatcher_blocker_detail)
                        logger.warning(
                            "kanban dispatcher stuck: ready queue non-empty for "
                            "%d consecutive ticks but 0 workers spawned. Check "
                            "profile health (venv, PATH, credentials) and "
                            "`hermes kanban list --status ready`. %s",
                            bad_ticks,
                            f"Observed: {detail}" if detail else "No blocker detail available.",
                        )
                        last_warn_at = now
            except asyncio.CancelledError:
                logger.debug("kanban dispatcher: cancelled")
                raise
            except Exception:
                logger.exception("kanban dispatcher: unexpected watcher error")

            if self._running:
                await self._sleep_until_kanban_dispatch_due(interval)

    def _runtime_config_dict(self) -> dict:
        config = getattr(self, "config", None)
        if isinstance(config, dict):
            return config
        try:
            return _load_gateway_runtime_config()
        except Exception:
            logger.debug("Failed to load gateway runtime config", exc_info=True)
            return {}

    def _is_discord_default_kanban_intake_event(
        self,
        event: MessageEvent,
        config: Optional[dict] = None,
    ) -> bool:
        """Return true when a Discord message is in a default-board intake channel."""
        source = getattr(event, "source", None)
        if getattr(source, "platform", None) != Platform.DISCORD:
            return False
        if getattr(event, "internal", False) or getattr(source, "is_bot", False):
            return False
        if event.is_command():
            return False
        cfg = config if isinstance(config, dict) else self._runtime_config_dict()
        intake_channels = _discord_default_kanban_intake_channels(cfg)
        if not intake_channels:
            return False
        source_channel_ids = _discord_source_channel_ids(source)
        if not any(channel_id in intake_channels for channel_id in source_channel_ids):
            return False
        raw_text = str(getattr(event, "text", "") or "").strip()
        if not raw_text and getattr(event, "media_urls", None):
            raw_text = "[media attachment]"
        return bool(raw_text)

    def _mark_discord_default_kanban_intake_context(
        self,
        event: MessageEvent,
        source: SessionSource,
        config: Optional[dict] = None,
    ) -> bool:
        """Attach per-turn default-board intake metadata to the source."""
        cfg = config if isinstance(config, dict) else self._runtime_config_dict()
        if not self._is_discord_default_kanban_intake_event(event, cfg):
            return False
        setattr(source, "default_kanban_intake", True)
        if not getattr(source, "message_id", None) and getattr(event, "message_id", None):
            setattr(source, "message_id", str(getattr(event, "message_id")))
        setattr(source, "default_kanban_intake_assignee", _resolve_default_board_intake_assignee(cfg))
        notifier_profile = getattr(self, "_kanban_notifier_profile", None)
        if not notifier_profile:
            try:
                notifier_profile = self._active_profile_name()
            except Exception:
                notifier_profile = ""
        setattr(source, "kanban_notifier_profile", notifier_profile or "")
        return True

    def _discord_default_kanban_intake_prompt(self, source: SessionSource) -> str:
        assignee = str(getattr(source, "default_kanban_intake_assignee", "") or "default")
        return (
            "**Discord default-board intake mode:** This Discord channel is configured "
            "as an intake surface for the top-level Kanban board. Answer ordinary "
            "questions and quick conversational requests directly. When the user is "
            "asking Hermes to do coding, research, operations, or other durable work "
            "that should be tracked asynchronously, create a Kanban task with "
            "`kanban_create` instead of doing the long-running work inline. Use "
            "`board=\"default\"`, the default assignee "
            f"`{assignee}`, and include the user's request plus relevant Discord "
            "source context in the task body. If a mapped project path is present, "
            "use `workspace_kind=\"dir\"` and that absolute path. After creating a "
            "task, reply concisely with the task id. Completion and blocker "
            "notifications are subscribed back to this Discord thread automatically. "
            "Do not create a task for normal questions, clarification, status checks, "
            "or messages you can answer directly."
        )

    def _maybe_route_discord_default_kanban_intake(self, event: MessageEvent) -> Optional[str]:
        """Capture configured Discord channel messages as default-board intake.

        This is for control-room channels such as #dev: accepted human input
        becomes a top-level Kanban intake item instead of a per-thread worker
        board or an immediate agent turn. Slash commands and bot/system events
        continue through their existing paths.
        """
        cfg = self._runtime_config_dict()
        if not self._is_discord_default_kanban_intake_event(event, cfg):
            return None
        source = getattr(event, "source", None)
        source_channel_ids = _discord_source_channel_ids(source)

        raw_text = str(getattr(event, "text", "") or "").strip()
        if not raw_text and getattr(event, "media_urls", None):
            raw_text = "[media attachment]"
        if not raw_text:
            return None
        try:
            from agent.redact import redact_sensitive_text

            safe_text = redact_sensitive_text(raw_text)
        except Exception:
            safe_text = raw_text

        title_text = re.sub(r"\s+", " ", safe_text).strip()
        title_text = re.sub(r"^<@!?\d+>\s*", "", title_text).strip()
        if not title_text:
            title_text = "Discord intake"
        if len(title_text) > 96:
            title_text = title_text[:93].rstrip() + "..."
        title = f"#dev intake: {title_text}"

        guild_id = str(getattr(source, "guild_id", "") or "").strip()
        thread_id = str(getattr(source, "thread_id", "") or "").strip()
        chat_id = str(getattr(source, "chat_id", "") or "").strip()
        parent_channel_id = str(getattr(source, "parent_chat_id", "") or "").strip()
        message_id = str(getattr(event, "message_id", "") or getattr(source, "message_id", "") or "").strip()
        url_channel_id = thread_id or chat_id or parent_channel_id
        source_url = ""
        if guild_id and url_channel_id and message_id:
            source_url = f"https://discord.com/channels/{guild_id}/{url_channel_id}/{message_id}"

        project_path = str(getattr(source, "project_path", "") or "").strip()
        body_lines = [
            "Discord default-board intake.",
            "",
            f"Source URL: {source_url or '(unavailable)'}",
            f"Guild ID: {guild_id or '(unknown)'}",
            f"Channel IDs: {', '.join(source_channel_ids) or '(unknown)'}",
            f"Thread ID: {thread_id or '(none)'}",
            f"Message ID: {message_id or '(none)'}",
            f"User: {getattr(source, 'user_name', None) or getattr(source, 'user_id', None) or '(unknown)'}",
        ]
        if project_path:
            body_lines.append(f"Workspace: {project_path}")
        project_github = str(getattr(source, "project_github_url", "") or "").strip()
        if project_github:
            body_lines.append(f"GitHub: {project_github}")
        body_lines.extend(["", "Message:", safe_text])
        body = "\n".join(body_lines)

        id_source = message_id or hashlib.sha256(
            f"{guild_id}:{url_channel_id}:{safe_text}:{getattr(event, 'timestamp', '')}".encode("utf-8")
        ).hexdigest()[:16]
        idempotency_key = f"discord-default-intake:{guild_id}:{url_channel_id}:{id_source}"

        try:
            from hermes_cli import kanban_db as _kb

            assignee = _resolve_default_board_intake_assignee(cfg)
            conn = _kb.connect(board=_kb.DEFAULT_BOARD)
            try:
                task_id = _kb.create_task(
                    conn,
                    title=title,
                    body=body,
                    assignee=assignee,
                    created_by="discord-default-intake",
                    workspace_kind="dir" if project_path else "scratch",
                    workspace_path=project_path or None,
                    tenant="discord-default-intake",
                    idempotency_key=idempotency_key,
                    initial_status="blocked",
                    board=_kb.DEFAULT_BOARD,
                )
                platform = getattr(source, "platform", None)
                platform_str = (
                    platform.value if hasattr(platform, "value") else str(platform or "")
                ).lower()
                notify_chat_id = chat_id or thread_id or parent_channel_id
                user_id = str(getattr(source, "user_id", "") or "") or None
                if platform_str and notify_chat_id:
                    _kb.add_notify_sub(
                        conn,
                        task_id=task_id,
                        platform=platform_str,
                        chat_id=notify_chat_id,
                        thread_id=thread_id or None,
                        user_id=user_id,
                        notifier_profile=(
                            getattr(self, "_kanban_notifier_profile", None)
                            or self._active_profile_name()
                        ),
                    )
            finally:
                conn.close()
        except Exception as exc:
            logger.exception("Discord default Kanban intake failed")
            return f"⚠️ Failed to queue this on the top-level Kanban board: {exc}"

        return f"Queued on top-level Kanban: `{task_id}`."

    def _fallback_discord_kanban_feature_title(self, target: Dict[str, Any]) -> str:
        text = str(target.get("fallback_title") or "").strip()
        text = re.sub(r"^/goal(?:\s+(.*))?$", r"\1", text, flags=re.IGNORECASE | re.DOTALL).strip()
        text = re.sub(r"`([^`]*)`", r"\1", text)
        text = re.sub(r"[*_>#-]+", " ", text)
        text = re.sub(r"\s+", " ", text).strip(" .")
        if not text:
            text = "Discord Worker Feature"
        if len(text) > 80:
            text = text[:77].rstrip() + "..."
        return text

    def _discord_kanban_feature_title(self, target: Dict[str, Any]) -> str:
        existing = str(target.get("title") or "").strip()
        if existing:
            return existing
        board = str(target.get("board") or "").strip()
        title = self._fallback_discord_kanban_feature_title(target)
        if board and title:
            try:
                from hermes_cli.discord_worker_boards import set_feature_summary_title

                return set_feature_summary_title(board, title) or title
            except Exception:
                logger.debug("Discord Kanban feature-title persistence failed", exc_info=True)
        return title

    def _fallback_discord_feature_title(self, feature_summary: Optional[Dict[str, Any]]) -> Optional[str]:
        if not isinstance(feature_summary, dict):
            return None
        initial_request = str(feature_summary.get("initial_request") or "").strip()
        if not initial_request:
            return None
        return self._fallback_discord_kanban_feature_title({"fallback_title": initial_request})

