    def _discord_kanban_reaction_sync_due(
        self,
        cache_entry: Any,
        state: str,
        now: float,
    ) -> bool:
        if not state:
            return False
        if not isinstance(cache_entry, dict):
            return True
        cached_state = str(cache_entry.get("state") or "")
        if cached_state != state:
            return True
        if state in {"done", "blocked", "errored"} and (
            cache_entry.get("terminal_reaction_sync_pending")
            or cache_entry.get("terminal_reaction_sync_needed")
        ):
            return True
        try:
            synced_at = float(cache_entry.get("synced_at") or 0.0)
        except (TypeError, ValueError):
            synced_at = 0.0
        return now - synced_at >= _DISCORD_KANBAN_REACTION_RESYNC_SECS

    @staticmethod
    def _discord_kanban_completion_notice_only(target: Dict[str, Any]) -> bool:
        if not target.get("terminal_completion_message_pending"):
            return False
        state = str(target.get("state") or "").strip()
        if state not in {"done", "blocked", "errored"}:
            return False
        if str(target.get("source_state") or "").strip():
            return False
        if str(target.get("reaction_state") or "").strip() == "foreman":
            return False
        return not bool(
            target.get("terminal_reaction_sync_pending")
            or target.get("terminal_summary_sync_pending")
            or target.get("terminal_reaction_sync_needed")
        )

    @staticmethod
    def _discord_kanban_completion_notice_ready(target: Dict[str, Any]) -> bool:
        if not target.get("terminal_completion_message_pending"):
            return False
        if target.get("foreman_generated"):
            return True
        try:
            from hermes_cli.discord_time import discord_message_exceeds_age_limit

            if discord_message_exceeds_age_limit(target.get("source_message_id") or target.get("thread_id")):
                return True
        except Exception:
            pass
        board_summary = target.get("board_summary") if isinstance(target.get("board_summary"), dict) else {}
        final_response = board_summary.get("final_response") if isinstance(board_summary.get("final_response"), dict) else {}
        if str(final_response.get("text") or "").strip():
            return True
        # Role-worker / cron-origin boards can finish without a final agent
        # message recorded on the board. The Discord adapter already renders a
        # useful fallback from the deterministic board summary; do not leave the
        # visible thread pending forever just because final_response is empty.
        if str(target.get("outcome") or "").strip():
            return True
        if not board_summary:
            return False
        if str(board_summary.get("outcome") or "").strip():
            return True
        task_counts = board_summary.get("task_counts") if isinstance(board_summary.get("task_counts"), dict) else {}
        try:
            if int(task_counts.get("total") or 0) > 0:
                return True
        except (TypeError, ValueError):
            pass
        pr = board_summary.get("pr") if isinstance(board_summary.get("pr"), dict) else {}
        if str(pr.get("url") or "").strip():
            return True
        latest_tasks = board_summary.get("latest_tasks")
        if isinstance(latest_tasks, list) and latest_tasks:
            return True
        return False

    @staticmethod
    def _discord_foreman_clamped_int(
        value: Any,
        default: int,
        minimum: int,
        maximum: int,
        *,
        allow_zero: bool = False,
    ) -> int:
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            parsed = default
        if allow_zero and parsed <= 0:
            return 0
        return min(max(parsed, minimum), maximum)

    def _discord_foreman_watcher_config(self, config: dict) -> dict[str, Any]:
        raw = cfg_get(config, "kanban", "discord_worker", "foreman", default={})
        if not isinstance(raw, dict):
            raw = {}
        max_alerts_per_board = raw.get(
            "max_alerts_per_board_per_day",
            raw.get("daily_cap_per_board", 20),
        )
        return {
            "enabled": is_truthy_value(raw.get("enabled"), default=False),
            "channel_id": _DISCORD_FOREMAN_DEFAULT_CHANNEL_ID,
            "mention": _DISCORD_FOREMAN_DEFAULT_MENTION,
            "master_board": str(raw.get("master_board") or "default").strip() or "default",
            "scan_interval_seconds": self._discord_foreman_clamped_int(
                raw.get("scan_interval_seconds"), 30, 10, 3600,
            ),
            "blocked_board_min_age_seconds": self._discord_foreman_clamped_int(
                raw.get("blocked_board_min_age_seconds"),
                600,
                60,
                7 * 24 * 3600,
                allow_zero=True,
            ),
            "terminal_suppression_age_seconds": self._discord_foreman_clamped_int(
                raw.get("terminal_suppression_age_seconds"),
                7 * 24 * 3600,
                3600,
                30 * 24 * 3600,
                allow_zero=True,
            ),
            "alert_config": {
                "cooldown_seconds": self._discord_foreman_clamped_int(
                    raw.get("cooldown_seconds"), 3600, 60, 7 * 24 * 3600,
                ),
                "retry_backoff_seconds": self._discord_foreman_clamped_int(
                    raw.get("retry_backoff_seconds"), 300, 30, 3600,
                ),
                "max_retry_backoff_seconds": self._discord_foreman_clamped_int(
                    raw.get("max_retry_backoff_seconds"), 3600, 60, 24 * 3600,
                ),
                "retention_seconds": self._discord_foreman_clamped_int(
                    raw.get("retention_seconds"), 30 * 24 * 3600, 3600, 90 * 24 * 3600,
                ),
                "max_alerts_per_tick": self._discord_foreman_clamped_int(
                    raw.get("max_alerts_per_tick"), 10, 1, 50,
                ),
                "daily_cap_per_board": self._discord_foreman_clamped_int(
                    max_alerts_per_board, 20, 1, 200,
                ),
                "min_board_created_at": self._discord_foreman_clamped_int(
                    raw.get("min_board_created_at"), 0, 0, 4102444800, allow_zero=True,
                ),
            },
        }

    def _discord_worker_task_thread_info(
        self,
        board: str,
        task_id: str,
        workspace_path: str = "",
    ) -> Optional[Dict[str, Any]]:
        from urllib.parse import quote as _quote

        from hermes_cli import discord_worker_boards as _dwb
        from hermes_cli import kanban_db as _kb
        from hermes_cli.discord_worker_roles import DISCORD_WORKER_META_KEY
        from hermes_cli.discord_worker_state import read_codex_worker_state

        if not _dwb.is_discord_worker_board(board):
            return None

        state = read_codex_worker_state(task_id, board=board)
        existing = state.get(_DISCORD_WORKER_TASK_THREAD_STATE_KEY)
        if not isinstance(existing, dict) or not str(existing.get("thread_id") or "").strip():
            existing = state.get(_DISCORD_LEGACY_FOREMAN_THREAD_STATE_KEY)
        if isinstance(existing, dict) and str(existing.get("thread_id") or "").strip():
            return {"existing_thread": dict(existing)}

        conn = _kb.connect(board=board)
        try:
            task = _kb.get_task(conn, task_id)
        finally:
            conn.close()
        if task is None:
            return None

        metadata = _kb.read_board_metadata(board)
        worker = metadata.get(DISCORD_WORKER_META_KEY)
        worker = dict(worker) if isinstance(worker, dict) else {}
        project_context = worker.get("project_context")
        if not isinstance(project_context, dict):
            project_context = {}
        board_url = str(worker.get("public_url") or "").strip()
        if not board_url:
            board_url = _dwb.public_session_board_url(str(worker.get("thread_id") or ""))
        ticket_url = f"{board_url.rstrip('/')}/tickets/{_quote(str(task_id), safe='')}" if board_url else ""
        discord_thread_url = self._discord_foreman_board_thread_url(worker)
        body = str(task.body or "").strip()
        request_parts = [str(task.title or task_id).strip()]
        if body:
            request_parts.append(body)
        if workspace_path:
            request_parts.append(f"Workspace: {workspace_path}")

        return {
            "task_id": task_id,
            "board": board,
            "title": str(task.title or task_id).strip() or task_id,
            "assignee": str(task.assignee or "").strip(),
            "initial_request": "\n\n".join(part for part in request_parts if part),
            "project_context": project_context,
            "thread_id": str(worker.get("thread_id") or "").strip(),
            "chat_id": str(worker.get("chat_id") or worker.get("thread_id") or "").strip(),
            "guild_id": str(worker.get("guild_id") or "").strip(),
            "parent_channel_id": str(worker.get("parent_channel_id") or "").strip(),
            "source_message_id": str(worker.get("source_message_id") or worker.get("request_id") or "").strip(),
            "kanban_url": ticket_url or board_url,
            "board_url": board_url,
            "ticket_url": ticket_url,
            "discord_thread_url": discord_thread_url,
        }

    @staticmethod
    def _discord_worker_task_thread_config(config: dict[str, Any]) -> dict[str, Any]:
        kanban_cfg = config.get("kanban") if isinstance(config, dict) else {}
        kanban_cfg = kanban_cfg if isinstance(kanban_cfg, dict) else {}
        worker_cfg = kanban_cfg.get("discord_worker") if isinstance(kanban_cfg, dict) else {}
        worker_cfg = worker_cfg if isinstance(worker_cfg, dict) else {}
        task_thread_cfg = worker_cfg.get("task_threads")
        task_thread_cfg = task_thread_cfg if isinstance(task_thread_cfg, dict) else {}
        legacy_foreman_cfg = worker_cfg.get("foreman")
        legacy_foreman_cfg = legacy_foreman_cfg if isinstance(legacy_foreman_cfg, dict) else {}
        return {
            "enabled": is_truthy_value(
                task_thread_cfg.get("enabled", legacy_foreman_cfg.get("enabled")),
                default=False,
            )
        }

    @staticmethod
    def _discord_foreman_board_thread_url(worker: Dict[str, Any]) -> str:
        from urllib.parse import quote as _quote

        guild_id = str(worker.get("guild_id") or "").strip()
        thread_id = str(worker.get("thread_id") or "").strip()
        if not guild_id or not thread_id:
            return ""
        message_id = str(worker.get("source_message_id") or worker.get("request_id") or "").strip()
        base = f"https://discord.com/channels/{_quote(guild_id, safe='')}/{_quote(thread_id, safe='')}"
        if message_id:
            return f"{base}/{_quote(message_id, safe='')}"
        return base

    @staticmethod
    def _discord_foreman_issue_with_source_thread_url(issue: Any, source_context: Dict[str, Any]) -> Any:
        evidence = getattr(issue, "evidence", None)
        evidence = dict(evidence) if isinstance(evidence, dict) else {}
        source_url = GatewayRunner._discord_foreman_board_thread_url(source_context)
        if source_url:
            evidence["source_discord_thread_url"] = source_url
        try:
            from dataclasses import replace as _replace

            return _replace(issue, evidence=evidence)
        except Exception:
            from types import SimpleNamespace

            return SimpleNamespace(
                kind=str(getattr(issue, "kind", "") or ""),
                board=str(getattr(issue, "board", "") or ""),
                task_id=str(getattr(issue, "task_id", "") or ""),
                severity=str(getattr(issue, "severity", "") or ""),
                title=str(getattr(issue, "title", "") or ""),
                evidence=evidence,
            )

    def _discord_foreman_issue_embed_context(self, issue: Any) -> Dict[str, str]:
        from urllib.parse import quote as _quote

        evidence = getattr(issue, "evidence", None)
        evidence = evidence if isinstance(evidence, dict) else {}
        source_board = str(evidence.get("source_board") or getattr(issue, "board", "") or "").strip()
        source_task_id = str(evidence.get("source_task_id") or getattr(issue, "task_id", "") or "").strip()
        source_kanban_url = str(evidence.get("source_kanban_url") or evidence.get("session_url") or "").strip()
        source_discord_thread_url = str(evidence.get("source_discord_thread_url") or "").strip()
        if source_board:
            try:
                from hermes_cli import kanban_db as _kb
                from hermes_cli.discord_worker_roles import DISCORD_WORKER_META_KEY

                metadata = _kb.read_board_metadata(source_board)
                worker = metadata.get(DISCORD_WORKER_META_KEY)
                worker = dict(worker) if isinstance(worker, dict) else {}
                source_discord_thread_url = source_discord_thread_url or self._discord_foreman_board_thread_url(worker)
                source_kanban_url = source_kanban_url or str(worker.get("public_url") or "").strip()
            except Exception:
                logger.debug("discord foreman: source board metadata unavailable for %s", source_board, exc_info=True)
        source_task_url = ""
        if source_kanban_url and source_task_id and source_task_id != "__board__":
            source_task_url = f"{source_kanban_url.rstrip('/')}/tickets/{_quote(source_task_id, safe='')}"
        return {
            "source_board": source_board,
            "source_task_id": source_task_id,
            "source_task_url": source_task_url,
            "source_kanban_url": source_kanban_url,
            "source_discord_thread_url": source_discord_thread_url,
        }

    def _discord_foreman_issue_source_context(self, issue: Any) -> Dict[str, Any]:
        evidence = getattr(issue, "evidence", None)
        evidence = evidence if isinstance(evidence, dict) else {}
        source_board = str(evidence.get("source_board") or getattr(issue, "board", "") or "").strip()
        source_task_id = str(evidence.get("source_task_id") or getattr(issue, "task_id", "") or "").strip()
        context: Dict[str, Any] = {
            "source_board": source_board,
            "source_task_id": source_task_id,
            "thread_id": str(evidence.get("thread_id") or "").strip(),
            "chat_id": str(evidence.get("chat_id") or "").strip(),
            "guild_id": str(evidence.get("guild_id") or "").strip(),
            "parent_channel_id": str(evidence.get("parent_channel_id") or "").strip(),
            "source_message_id": str(evidence.get("source_message_id") or "").strip(),
            "project_context": None,
            "public_url": "",
        }
        if source_board:
            try:
                from hermes_cli import kanban_db as _kb
                from hermes_cli.discord_worker_roles import DISCORD_WORKER_META_KEY

                metadata = _kb.read_board_metadata(source_board)
                worker = metadata.get(DISCORD_WORKER_META_KEY)
                worker = dict(worker) if isinstance(worker, dict) else {}
                context["thread_id"] = str(worker.get("thread_id") or context["thread_id"] or "").strip()
                context["chat_id"] = str(worker.get("chat_id") or context["chat_id"] or context["thread_id"] or "").strip()
                context["guild_id"] = str(worker.get("guild_id") or context["guild_id"] or "").strip()
                context["parent_channel_id"] = str(
                    worker.get("parent_channel_id") or context["parent_channel_id"] or ""
                ).strip()
                context["source_message_id"] = str(
                    worker.get("source_message_id")
                    or worker.get("request_id")
                    or context["source_message_id"]
                    or ""
                ).strip()
                project_context = worker.get("project_context")
                if isinstance(project_context, dict):
                    context["project_context"] = dict(project_context)
                context["public_url"] = str(worker.get("public_url") or "").strip()
            except Exception:
                logger.debug("discord foreman: source context unavailable for %s", source_board, exc_info=True)
        if not context["chat_id"] and context["thread_id"]:
            context["chat_id"] = context["thread_id"]
        return context

    @staticmethod
    def _discord_foreman_goal_board_slug(issue: Any) -> str:
        evidence = getattr(issue, "evidence", None)
        evidence = evidence if isinstance(evidence, dict) else {}
        payload = {
            "kind": str(getattr(issue, "kind", "") or ""),
            "board": str(evidence.get("source_board") or getattr(issue, "board", "") or ""),
            "task_id": str(evidence.get("source_task_id") or getattr(issue, "task_id", "") or ""),
            "title": str(getattr(issue, "title", "") or ""),
        }
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return "foreman-" + hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16]

    async def _discord_foreman_sync_source_reaction(
        self,
        adapter: Any,
        source_context: Dict[str, Any],
    ) -> None:
        reaction_sync = getattr(adapter, "sync_kanban_thread_reaction", None) if adapter else None
        if not callable(reaction_sync):
            return
        thread_id = str(source_context.get("thread_id") or "").strip()
        if not thread_id:
            return
        await reaction_sync(
            {
                "board": str(source_context.get("source_board") or ""),
                "thread_id": thread_id,
                "chat_id": str(source_context.get("chat_id") or thread_id),
                "message_id": "",
                "source_message_id": str(source_context.get("source_message_id") or ""),
                "state": "active",
                "reaction_state": "foreman",
            }
        )

    def _discord_worker_record_task_thread(
        self,
        *,
        board: str,
        task_id: str,
        channel_id: str,
        thread_handle: Dict[str, Any],
    ) -> None:
        from hermes_cli.discord_worker_state import (
            codex_worker_state_path,
            read_codex_worker_state,
            write_codex_worker_state,
        )
        from utils import atomic_json_write

        thread_id = str(thread_handle.get("thread_id") or "").strip()
        if not thread_id:
            return

        update = {
            _DISCORD_WORKER_TASK_THREAD_STATE_KEY: {
                "thread_id": thread_id,
                "parent_channel_id": str(channel_id),
                "message_id": str(thread_handle.get("message_id") or ""),
                "thread_name": str(thread_handle.get("thread_name") or ""),
                "created_at": int(thread_handle.get("created_at") or time.time()),
            }
        }
        remove_legacy = False
        try:
            current = read_codex_worker_state(task_id, board=board)
            remove_legacy = _DISCORD_LEGACY_FOREMAN_THREAD_STATE_KEY in current
        except Exception:
            pass

        new_state = write_codex_worker_state(
            task_id,
            board=board,
            update=update,
        )
        if remove_legacy:
            new_state.pop(_DISCORD_LEGACY_FOREMAN_THREAD_STATE_KEY, None)
            atomic_json_write(codex_worker_state_path(task_id, board=board), new_state, indent=2)

    async def _discord_worker_announce_spawned_tasks(self, results: Any) -> None:
        if not results:
            return
        try:
            from hermes_cli.config import load_config as _load_config

            task_thread_cfg = self._discord_worker_task_thread_config(_load_config())
        except Exception as exc:
            logger.debug("discord worker: task-thread config unavailable: %s", exc)
            return
        if not task_thread_cfg.get("enabled"):
            return

        for board, res in results:
            spawned = getattr(res, "spawned", None) if res is not None else None
            if not spawned:
                continue
            for task_id, assignee, workspace_path in spawned:
                try:
                    info = await asyncio.to_thread(
                        self._discord_worker_task_thread_info,
                        str(board),
                        str(task_id),
                        str(workspace_path or ""),
                    )
                    if not info:
                        continue
                    existing_thread = info.get("existing_thread")
                    if isinstance(existing_thread, dict) and str(existing_thread.get("thread_id") or "").strip():
                        await asyncio.to_thread(
                            self._discord_worker_record_task_thread,
                            board=str(board),
                            task_id=str(task_id),
                            channel_id=str(
                                existing_thread.get("parent_channel_id")
                                or existing_thread.get("thread_id")
                                or ""
                            ),
                            thread_handle=existing_thread,
                        )
                        continue
                    thread_id = str(info.get("thread_id") or "").strip()
                    if not thread_id:
                        continue
                    await asyncio.to_thread(
                        self._discord_worker_record_task_thread,
                        board=str(board),
                        task_id=str(task_id),
                        channel_id=str(info.get("chat_id") or thread_id),
                        thread_handle={
                            "thread_id": thread_id,
                            "thread_name": str(info.get("thread_name") or info.get("title") or task_id),
                            "message_id": "",
                        },
                    )
                except Exception:
                    logger.debug(
                        "discord worker: task-thread create failed for %s/%s",
                        board,
                        task_id,
                        exc_info=True,
                    )

    @staticmethod
    def _discord_foreman_safe_log_text(value: Any) -> str:
        try:
            from hermes_cli.discord_worker_foreman import sanitize_foreman_text
        except Exception:
            text = str(value or "")[:300]
            text = re.sub(
                r"(?i)(token|secret|api[_-]?key|authorization|password)\s*[:=]\s*[^\s,;]+",
                "[redacted]",
                text,
            )
            return re.sub(
                r"(?<![\w:/.-])(?:~[\w.-]*(?:/[^\s\"'<>),;{}\[\]]*)?|/(?:home|Users|tmp|var|etc|opt|private|workspace|workspaces|mnt|srv|repo|root)(?:/[^\s\"'<>),;{}\[\]]*)?|[A-Za-z]:\\[^\s\"'<>),;{}\[\]]+)",
                "[path]",
                text,
            )
        return sanitize_foreman_text(value, limit=300)

    async def _discord_foreman_start_goal(
        self,
        adapter: Any,
        *,
        channel_id: str,
        issue: Any,
        prompt: str,
        title: str,
    ) -> None:
        creator = getattr(adapter, "create_foreman_goal_thread", None) if adapter else None
        if not callable(creator):
            raise RuntimeError("Discord adapter cannot create foreman goal threads")

        source_context = self._discord_foreman_issue_source_context(issue)
        source_thread_id = str(source_context.get("thread_id") or "").strip()
        if not source_thread_id:
            raise RuntimeError("Discord foreman issue has no source thread")

        try:
            from hermes_cli import discord_worker_boards as _dwb

            foreman_board_slug = self._discord_foreman_goal_board_slug(issue)
            foreman_board_url = _dwb.public_session_board_url(foreman_board_slug)
        except Exception:
            foreman_board_slug = self._discord_foreman_goal_board_slug(issue)
            foreman_board_url = ""

        embed_context = self._discord_foreman_issue_embed_context(issue)
        handle = await creator(
            source_thread_id,
            name=title,
            initial_request=prompt,
            project_context=source_context.get("project_context"),
            kanban_board={"slug": foreman_board_slug, "public_url": foreman_board_url},
            hide_source_links=True,
            **embed_context,
        )
        if not isinstance(handle, dict) or not str(handle.get("thread_id") or "").strip():
            raise RuntimeError("Discord adapter did not return a foreman goal embed")
        await self._discord_foreman_sync_source_reaction(adapter, source_context)

        thread_id = str(handle.get("thread_id") or "").strip()
        thread_name = str(handle.get("thread_name") or title or thread_id).strip()
        project_context = handle.get("project_context") if isinstance(handle.get("project_context"), dict) else {}
        source = SessionSource(
            platform=Platform.DISCORD,
            chat_id=thread_id,
            chat_name=thread_name or "Discord foreman",
            chat_type="thread",
            user_id="system:foreman",
            user_name="Hermes Foreman",
            thread_id=thread_id,
            guild_id=str(handle.get("guild_id") or source_context.get("guild_id") or "") or None,
            parent_chat_id=str(
                handle.get("parent_channel_id")
                or source_context.get("parent_channel_id")
                or channel_id
                or ""
            ) or None,
            project_name=str(project_context.get("project_name") or "") or None,
            project_path=str(project_context.get("project_path") or "") or None,
            project_github_url=str(project_context.get("project_github_url") or "") or None,
            project_channel_id=str(project_context.get("project_channel_id") or "") or None,
            project_mapping_source=str(project_context.get("project_mapping_source") or "") or None,
            project_mapping_resolved=(
                bool(project_context.get("project_mapping_resolved"))
                if project_context.get("project_mapping_resolved") is not None
                else None
            ),
        )
        event = MessageEvent(
            text=prompt,
            message_type=MessageType.COMMAND,
            source=source,
            message_id=str(handle.get("message_id") or "") or None,
            feature_summary=handle,
            internal=True,
        )
        await self._handle_goal_command(event)

    async def _discord_foreman_enqueue_master_task(
        self,
        adapter: Any,
        *,
        issue: Any,
        master_board: str,
    ) -> None:
        source_context = self._discord_foreman_issue_source_context(issue)
        if not str(source_context.get("thread_id") or "").strip():
            raise RuntimeError("Discord foreman issue has no source thread")
        from hermes_cli import discord_worker_foreman as _foreman

        enriched_issue = self._discord_foreman_issue_with_source_thread_url(
            issue,
            source_context,
        )
        await asyncio.to_thread(
            _foreman.create_foreman_master_task,
            enriched_issue,
            master_board=master_board,
        )
        await self._discord_foreman_sync_source_reaction(adapter, source_context)

    async def _discord_worker_foreman_watcher(self) -> None:
        """Optionally scan Discord worker boards and send foreman alerts."""
        if getattr(self, "_discord_worker_foreman_watcher_active", False):
            logger.debug("discord foreman: watcher already active for this gateway")
            return

        try:
            from hermes_cli.config import load_config as _load_config
        except Exception:
            logger.warning("discord foreman: config loader unavailable; disabled")
            return

        try:
            watcher_cfg = self._discord_foreman_watcher_config(_load_config())
        except Exception as exc:
            logger.warning("discord foreman: cannot load config (%s); disabled", exc)
            return
        if not watcher_cfg["enabled"]:
            logger.info(
                "discord foreman: disabled via config kanban.discord_worker.foreman.enabled=false"
            )
            return
        profile = self._active_profile_name()
        lock_identity = f"{profile}:{_hermes_home}"
        lock_acquired = False
        try:
            from gateway.status import acquire_scoped_lock, release_scoped_lock

            lock_acquired, existing = acquire_scoped_lock(
                "discord-worker-foreman",
                lock_identity,
                metadata={"profile": profile, "hermes_home": str(_hermes_home)},
            )
            if not lock_acquired:
                logger.info(
                    "discord foreman: another watcher owns profile %s (pid=%s); disabled here",
                    profile,
                    (existing or {}).get("pid"),
                )
                return

            self._discord_worker_foreman_watcher_active = True
            interval = float(watcher_cfg["scan_interval_seconds"])
            alert_config = dict(watcher_cfg["alert_config"])
            terminal_age = int(watcher_cfg["terminal_suppression_age_seconds"])
            alert_config["terminal_suppression_age_seconds"] = terminal_age
            startup_baseline_checked = False
            logger.info(
                "discord foreman: enabled (interval=%.1fs)",
                interval,
            )

            await asyncio.sleep(5)
            while self._running:
                try:
                    adapter = self.adapters.get(Platform.DISCORD)
                    if adapter is None:
                        logger.debug("discord foreman: Discord adapter not connected; skipping tick")
                    elif getattr(adapter, "is_connected", True) is False:
                        logger.debug("discord foreman: Discord adapter disconnected; skipping tick")
                    else:
                        try:
                            from hermes_cli import discord_worker_foreman as _foreman
                        except Exception:
                            logger.debug("discord foreman: helper unavailable", exc_info=True)
                        else:
                            def _collect_due_alerts() -> list[Any]:
                                nonlocal startup_baseline_checked
                                now = int(time.time())
                                _foreman.auto_close_completed_foreman_boards(now=now)
                                issues = _foreman.collect_foreman_issues(
                                    now=now,
                                    blocked_board_min_age_seconds=int(
                                        watcher_cfg["blocked_board_min_age_seconds"]
                                    ),
                                )
                                issues.extend(
                                    _foreman.collect_human_intervention_issues(
                                        now=now,
                                        blocked_board_min_age_seconds=int(
                                            watcher_cfg["blocked_board_min_age_seconds"]
                                        ),
                                        master_board=watcher_cfg["master_board"],
                                    )
                                )
                                if not startup_baseline_checked:
                                    startup_baseline_checked = True
                                    if _foreman.startup_baseline_needed():
                                        suppressed = _foreman.record_startup_baseline(
                                            issues,
                                            config=alert_config,
                                            now=now,
                                        )
                                        if suppressed:
                                            logger.info(
                                                "discord foreman: baselined %d existing startup issue(s)",
                                                suppressed,
                                            )
                                        return []
                                due = _foreman.alerts_due(issues, config=alert_config, now=now)
                                return _foreman.coalesce_foreman_issues(
                                    due,
                                    master_board=watcher_cfg["master_board"],
                                )

                            due = await asyncio.to_thread(_collect_due_alerts)
                            for issue in due:
                                try:
                                    if getattr(issue, "kind", "") == "human_intervention_required":
                                        sender = getattr(adapter, "send", None)
                                        if not callable(sender):
                                            raise RuntimeError("Discord adapter cannot send foreman human alerts")
                                        source_context = self._discord_foreman_issue_source_context(issue)
                                        source_thread_id = str(source_context.get("thread_id") or "").strip()
                                        if not source_thread_id:
                                            raise RuntimeError("Discord foreman human alert has no source thread")
                                        alert_issue = self._discord_foreman_issue_with_source_thread_url(
                                            issue,
                                            source_context,
                                        )
                                        rendered_alert = _foreman.render_foreman_alert(
                                            alert_issue,
                                            mention=watcher_cfg["mention"],
                                        )
                                        metadata = {
                                            "foreman_alert_kind": getattr(issue, "kind", ""),
                                            "allowed_role_mentions": ["1503914570077442058"],
                                        }
                                        embed_payload = _foreman.render_foreman_human_intervention_embed(alert_issue)
                                        if embed_payload and getattr(adapter, "supports_metadata_embeds", False):
                                            metadata["_discord_embed"] = embed_payload
                                            rendered_alert = (rendered_alert.splitlines() or [watcher_cfg["mention"]])[0]
                                        result = await sender(
                                            source_thread_id,
                                            rendered_alert,
                                            metadata=metadata,
                                        )
                                        await self._discord_foreman_sync_source_reaction(adapter, source_context)
                                        if getattr(result, "success", True) is False:
                                            raise RuntimeError(
                                                getattr(result, "error", "foreman human alert send failed")
                                            )
                                    else:
                                        await self._discord_foreman_enqueue_master_task(
                                            adapter,
                                            issue=issue,
                                            master_board=watcher_cfg["master_board"],
                                        )
                                except Exception as exc:
                                    safe_error = self._discord_foreman_safe_log_text(exc)
                                    logger.warning(
                                        "discord foreman: alert handling failed for %s/%s: %s",
                                        getattr(issue, "board", "<unknown>"),
                                        getattr(issue, "task_id", "<unknown>"),
                                        safe_error,
                                    )
                                    await asyncio.to_thread(
                                        _foreman.record_alert_failed,
                                        issue,
                                        safe_error,
                                    )
                                else:
                                    await asyncio.to_thread(_foreman.record_alert_sent, issue)
                except asyncio.CancelledError:
                    logger.debug("discord foreman: cancelled")
                    raise
                except Exception:
                    logger.exception("discord foreman: unexpected watcher error")

                if self._running:
                    await self._sleep_until_discord_worker_dirty_or_timeout(
                        interval,
                        marker_state_attr="_kanban_foreman_dirty_marker_ns",
                    )
        finally:
            self._discord_worker_foreman_watcher_active = False
            if lock_acquired:
                try:
                    release_scoped_lock("discord-worker-foreman", lock_identity)
                except Exception:
                    logger.debug("discord foreman: failed to release watcher lock", exc_info=True)

    async def _discord_kanban_typing_watcher(self, interval: float = 5.0) -> None:
        """Keep Discord thread typing visible while thread workers are running."""
        interval = max(float(interval or 5.0), 1.0)
        error_backoff: dict[tuple[str, str, str], dict[str, float | int]] = {}
        error_backoff_window = 60.0

        def log_watcher_exception(scope: str, message: str, exc: Exception, *args: object) -> None:
            key = (scope, type(exc).__name__, str(exc))
            now = time.monotonic()
            state = error_backoff.get(key)
            if state is None or now - float(state.get("last_logged", 0.0)) >= error_backoff_window:
                error_backoff[key] = {"last_logged": now, "suppressed": 0}
                logger.exception(message, *args, exc_info=(type(exc), exc, exc.__traceback__))
                return
            state["suppressed"] = int(state.get("suppressed", 0)) + 1
            logger.debug(
                "%s: suppressed repeated %s after %d occurrences",
                scope,
                type(exc).__name__,
                int(state["suppressed"]),
            )

        def reset_watcher_errors(scope: str) -> None:
            for key in list(error_backoff):
                if key[0] == scope:
                    error_backoff.pop(key, None)

        while self._running:
            try:
                adapter = self.adapters.get(Platform.DISCORD)
                sender = getattr(adapter, "send_typing_once", None) if adapter else None
                reaction_sync = getattr(adapter, "sync_kanban_thread_reaction", None) if adapter else None
                summary_sync = getattr(adapter, "sync_kanban_feature_summary", None) if adapter else None
                completion_notice = getattr(adapter, "send_kanban_completion_notice", None) if adapter else None
                if adapter is not None and (
                    callable(sender)
                    or callable(reaction_sync)
                    or callable(summary_sync)
                    or callable(completion_notice)
                ):
                    targets = []
                    reaction_targets = []
                    try:
                        from hermes_cli.discord_worker_boards import (
                            running_discord_thread_typing_targets,
                            thread_status_targets,
                        )
                    except Exception:
                        logger.debug(
                            "discord kanban typing: worker board helper unavailable",
                            exc_info=True,
                        )
                    else:
                        try:
                            targets = await asyncio.to_thread(running_discord_thread_typing_targets)
                        except Exception as exc:
                            log_watcher_exception(
                                "discord kanban typing target collection",
                                "discord kanban typing: target collection failed",
                                exc,
                            )
                        else:
                            reset_watcher_errors("discord kanban typing target collection")
                        try:
                            reaction_targets = await asyncio.to_thread(thread_status_targets)
                        except Exception as exc:
                            log_watcher_exception(
                                "discord kanban status target collection",
                                "discord kanban status: target collection failed",
                                exc,
                            )
                        else:
                            reset_watcher_errors("discord kanban status target collection")
                    if callable(sender):
                        for target in targets:
                            thread_id = str(target.get("thread_id") or "").strip()
                            if not thread_id:
                                continue
                            chat_id = str(target.get("chat_id") or thread_id)
                            try:
                                await sender(chat_id, metadata={"thread_id": thread_id})
                            except Exception as exc:
                                logger.debug(
                                    "discord kanban typing: heartbeat failed for thread %s: %s",
                                    thread_id,
                                    exc,
                                )
                    if callable(reaction_sync):
                        reaction_cache = getattr(self, "_discord_kanban_reaction_states", None)
                        if not isinstance(reaction_cache, dict):
                            reaction_cache = {}
                            self._discord_kanban_reaction_states = reaction_cache
                        now = time.monotonic()
                        for target in reaction_targets:
                            if self._discord_kanban_completion_notice_only(target):
                                continue
                            board = str(target.get("board") or "")
                            state = str(target.get("reaction_state") or target.get("state") or "")
                            cache_key = self._discord_kanban_target_cache_key(target)
                            cache_entry = reaction_cache.get(cache_key)
                            if target.get("terminal_reaction_sync_pending") or target.get("terminal_reaction_sync_needed"):
                                cache_entry = dict(cache_entry) if isinstance(cache_entry, dict) else {}
                                cache_entry["terminal_reaction_sync_pending"] = bool(
                                    target.get("terminal_reaction_sync_pending")
                                )
                                cache_entry["terminal_reaction_sync_needed"] = bool(
                                    target.get("terminal_reaction_sync_needed")
                                )
                            has_message_identity = bool(
                                str(target.get("source_message_id") or target.get("message_id") or "").strip()
                            )
                            if cache_entry is None and board in reaction_cache:
                                if has_message_identity:
                                    reaction_cache.pop(board, None)
                                else:
                                    cache_entry = reaction_cache.pop(board)
                                    reaction_cache[cache_key] = cache_entry
                            if (
                                not board
                                or not self._discord_kanban_reaction_sync_due(
                                    cache_entry,
                                    state,
                                    now,
                                )
                            ):
                                continue
                            try:
                                synced_state = await reaction_sync(target)
                            except Exception as exc:
                                logger.debug(
                                    "discord kanban reaction: sync failed for board %s: %s",
                                    board,
                                    exc,
                                )
                                continue
                            if synced_state:
                                reaction_cache[cache_key] = {
                                    "state": str(synced_state),
                                    "synced_at": now,
                                }
                    if callable(summary_sync):
                        summary_cache = getattr(self, "_discord_kanban_summary_states", None)
                        if not isinstance(summary_cache, dict):
                            summary_cache = {}
                            self._discord_kanban_summary_states = summary_cache
                        for target in reaction_targets:
                            if self._discord_kanban_completion_notice_only(target):
                                continue
                            board = str(target.get("board") or "")
                            if not board:
                                continue
                            target_for_sync = dict(target)
                            if not str(target_for_sync.get("title") or "").strip():
                                title = self._discord_kanban_feature_title(target_for_sync)
                                if title:
                                    target_for_sync["title"] = title
                            sync_key = self._discord_kanban_summary_sync_key(target_for_sync)
                            cache_key = self._discord_kanban_target_cache_key(target_for_sync)
                            cached_sync_key = summary_cache.get(cache_key)
                            has_message_identity = bool(
                                str(
                                    target_for_sync.get("source_message_id")
                                    or target_for_sync.get("message_id")
                                    or ""
                                ).strip()
                            )
                            if cached_sync_key is None and board in summary_cache:
                                if has_message_identity:
                                    summary_cache.pop(board, None)
                                else:
                                    cached_sync_key = summary_cache.pop(board)
                                    summary_cache[cache_key] = cached_sync_key
                            force_summary_sync = bool(target_for_sync.get("terminal_summary_sync_pending"))
                            if cached_sync_key == sync_key and not force_summary_sync:
                                continue
                            try:
                                synced_key = await summary_sync(target_for_sync)
                            except Exception as exc:
                                logger.debug(
                                    "discord kanban summary: sync failed for board %s: %s",
                                    board,
                                    exc,
                                )
                                continue
                            if synced_key:
                                summary_cache[cache_key] = sync_key
                    for target in reaction_targets:
                        board = str(target.get("board") or "")
                        if not board or not target.get("terminal_completion_message_pending"):
                            continue
                        if not self._discord_kanban_completion_notice_ready(target):
                            continue
                        if callable(completion_notice):
                            try:
                                sent = await completion_notice(target)
                            except Exception as exc:
                                logger.debug(
                                    "discord kanban completion notice: send failed for board %s: %s",
                                    board,
                                    exc,
                                )
                                continue
                            if sent:
                                continue
                            continue
                        logger.debug(
                            "discord kanban completion notice: adapter lacks sender; keeping pending flag for board %s",
                            board,
                        )
                await asyncio.sleep(interval)
            except asyncio.CancelledError:
                logger.debug("discord kanban typing: cancelled")
                raise
            except Exception as exc:
                log_watcher_exception(
                    "discord kanban typing watcher",
                    "discord kanban typing: unexpected watcher error",
                    exc,
                )
                await asyncio.sleep(interval)

    async def _platform_reconnect_watcher(self) -> None:
        """Background task that periodically retries connecting failed platforms.

        Uses exponential backoff: 30s → 60s → 120s → 240s → 300s (cap).
        Retryable failures (network/DNS blips) keep retrying at the backoff
        cap indefinitely — they self-heal once connectivity returns, so a
        transient outage never requires manual intervention. Non-retryable
        failures (bad auth, etc.) drop out of the queue immediately. The
        circuit breaker (``_pause_failed_platform`` / ``/platform pause``)
        remains available for manual operator control via ``/platform list``
        and ``/platform resume <name>``, but is no longer triggered
        automatically — auto-pausing a recovered platform was the cause of
        bots silently staying dead after a transient DNS failure.
        """
        await asyncio.sleep(10)  # initial delay — let startup finish
        while self._running:
            if not self._failed_platforms:
                # Nothing to reconnect — sleep and check again
                for _ in range(30):
                    if not self._running:
                        return
                    await asyncio.sleep(1)
                continue

            now = time.monotonic()
            for platform in list(self._failed_platforms.keys()):
                if not self._running:
                    return
                info = self._failed_platforms[platform]
                # Skip paused platforms entirely — they need explicit
                # /platform resume to come back.
                if info.get("paused"):
                    continue
                if now < info["next_retry"]:
                    continue  # not time yet

                platform_config = info["config"]
                attempt = info["attempts"] + 1
                # Empty-token primary configs can never reconnect; drop them so
                # multiplex setups where a secondary profile owns the bot do
                # not spin forever (#64674).
                if not _platform_has_bot_credential(platform, platform_config):
                    logger.warning(
                        "Reconnect %s: no bot credential on queued config, "
                        "removing from retry queue",
                        platform.value,
                    )
                    del self._failed_platforms[platform]
                    continue
                logger.info(
                    "Reconnecting %s (attempt %d)...",
                    platform.value, attempt,
                )

                adapter = None
                try:
                    adapter = self._create_adapter(platform, platform_config)
                    if not adapter:
                        logger.warning(
                            "Reconnect %s: adapter creation returned None, removing from retry queue",
                            platform.value,
                        )
                        del self._failed_platforms[platform]
                        continue

                    adapter.set_message_handler(self._handle_message)
                    adapter.set_fatal_error_handler(self._handle_adapter_fatal_error)
                    adapter.set_session_store(self.session_store)
                    adapter.set_busy_session_handler(self._handle_active_session_busy_message)
                    adapter.set_topic_recovery_fn(self._recover_telegram_topic_thread_id)
                    adapter.set_authorization_check(
                        self._make_adapter_auth_check(platform)
                    )
                    adapter._busy_text_mode = self._busy_text_mode

                    success = await self._connect_adapter_with_timeout(
                        adapter,
                        platform,
                        is_reconnect=True,
                    )
                    if success:
                        self.adapters[platform] = adapter
                        self._install_background_worker_reaction_gate(adapter)
                        self._sync_voice_mode_state_to_adapter(adapter)
                        self.delivery_router.adapters = self.adapters
                        del self._failed_platforms[platform]
                        self._update_platform_runtime_status(
                            platform.value,
                            platform_state="connected",
                            error_code=None,
                            error_message=None,
                        )
                        logger.info("✓ %s reconnected successfully", platform.value)

                        # Rebuild channel directory with the new adapter
                        try:
                            from gateway.channel_directory import build_channel_directory
                            await build_channel_directory(self.adapters)
                        except Exception:
                            pass

                        # Sessions skipped while this adapter was offline at
                        # startup should resume as soon as their own platform
                        # reconnects, without re-touching other platforms.
                        try:
                            self._schedule_resume_pending_sessions(platform=platform)
                        except Exception:
                            logger.debug(
                                "resume-pending reschedule after %s reconnect failed",
                                platform.value,
                                exc_info=True,
                            )
                        if platform is Platform.DISCORD:
                            try:
                                self._schedule_pending_discord_terminal_reactions(
                                    platform=platform,
                                    profile_name="default",
                                )
                            except Exception:
                                logger.debug(
                                    "terminal reaction reschedule after Discord reconnect failed",
                                    exc_info=True,
                                )
                    # Check if the failure is non-retryable
                    elif adapter.has_fatal_error and not adapter.fatal_error_retryable:
                        self._update_platform_runtime_status(
                            platform.value,
                            platform_state="fatal",
                            error_code=adapter.fatal_error_code,
                            error_message=adapter.fatal_error_message,
                        )
                        logger.warning(
                            "Reconnect %s: non-retryable error (%s), removing from retry queue",
                            platform.value, adapter.fatal_error_message,
                        )
                        await _dispose_unused_adapter(adapter)
                        del self._failed_platforms[platform]
                    else:
                        self._update_platform_runtime_status(
                            platform.value,
                            platform_state="retrying",
                            error_code=adapter.fatal_error_code,
                            error_message=adapter.fatal_error_message or "failed to reconnect",
                        )
                        backoff = _reconnect_backoff(attempt)
                        info["attempts"] = attempt
                        info["next_retry"] = time.monotonic() + backoff
                        logger.info(
                            "Reconnect %s failed, next retry in %ds",
                            platform.value, backoff,
                        )
                        await _dispose_unused_adapter(adapter)
                        # Retryable failures (network/DNS blips) keep retrying
                        # at the backoff cap indefinitely — they self-heal once
                        # connectivity returns. We do NOT auto-pause them: a
                        # transient outage must never require manual `/platform
                        # resume` to recover. Non-retryable failures (bad auth,
                        # etc.) already drop out of the queue via the
                        # `not fatal_error_retryable` branch above, so anything
                        # reaching here is by definition retryable.
                except Exception as e:
                    if adapter is not None:
                        await _dispose_unused_adapter(adapter)
                    self._update_platform_runtime_status(
                        platform.value,
                        platform_state="retrying",
                        error_code=None,
                        error_message=str(e),
                    )
                    backoff = _reconnect_backoff(attempt)
                    info["attempts"] = attempt
                    info["next_retry"] = time.monotonic() + backoff
                    logger.warning(
                        "Reconnect %s error: %s, next retry in %ds",
                        platform.value, e, backoff,
                    )
                    # A raised exception during reconnect (connect timeout, DNS
                    # resolution failure, etc.) is inherently transient — keep
                    # retrying at the backoff cap rather than auto-pausing.

            # Check every 10 seconds for platforms that need reconnection
            for _ in range(10):
                if not self._running:
                    return
                await asyncio.sleep(1)

    async def _cancel_secondary_profile_reconnect_tasks(self) -> None:
        """Cancel profile-scoped reconnects before tearing down their registry.

        A reconnect can be waiting in adapter setup while shutdown begins. It
        must not republish an adapter after the secondary registry is drained.
        Waiting is bounded by the same adapter-cleanup budget; if a task does
        not finish in time, the stopped runner state still prevents it from
        installing an adapter when it eventually resumes.
        """
        pending = self._profile_failed_platforms
        if not isinstance(pending, dict):
            return
        current = asyncio.current_task()
        tasks: list[asyncio.Task] = []
        for profile_pending in pending.values():
            if not isinstance(profile_pending, dict):
                continue
            for task in profile_pending.values():
                if isinstance(task, asyncio.Task) and task is not current and not task.done():
                    tasks.append(task)
        for task in tasks:
            task.cancel()
        timeout = self._adapter_disconnect_timeout_secs()
        if tasks and timeout > 0:
            _done, unfinished = await asyncio.wait(tasks, timeout=timeout)
            if unfinished:
                logger.warning(
                    "Timed out waiting for %d secondary profile reconnect task(s) during shutdown",
                    len(unfinished),
                )
        pending.clear()

    def _start_systemd_watchdog(self) -> bool:
        """Start sd_notify only after a configured gateway is truly running."""
        if not self._running or self.config.systemd_watchdog_seconds <= 0:
            return False
        if self._systemd_watchdog is not None:
            return True

        from gateway.systemd_notify import SystemdWatchdog

        watchdog = SystemdWatchdog(config_enabled=True)
        if not watchdog.start():
            return False
        self._systemd_watchdog = watchdog
        watchdog.ready("Hermes Gateway running")
        return True

    async def _stop_systemd_watchdog(self) -> None:
        """Stop heartbeats before any potentially long shutdown drain."""
        watchdog = self._systemd_watchdog
        if watchdog is None:
            return
        self._systemd_watchdog = None
        await watchdog.stop()

    async def stop(
        self,
        *,
        restart: bool = False,
        detached_restart: bool = False,
        service_restart: bool = False,
    ) -> None:
        """Stop the gateway and disconnect all adapters."""
        if restart:
            self._restart_requested = True
            self._restart_detached = detached_restart
            self._restart_via_service = service_restart
        if self._stop_task is not None:
            await self._stop_task
            return

        async def _stop_impl() -> None:
            def _kill_tool_subprocesses(phase: str) -> None:
                """Kill tool subprocesses + tear down terminal envs + browsers.

                Called twice in the shutdown path: once eagerly after a
                drain timeout forces agent interrupt (so we reclaim bash/
                sleep children before systemd TimeoutStopSec escalates to
                SIGKILL on the cgroup — #8202), and once as a final
                catch-all at the end of _stop_impl() for the graceful
                path or anything respawned mid-teardown.

                All steps are best-effort; exceptions are swallowed so
                one subsystem's failure doesn't block the rest.
                """
                try:
                    from tools.process_registry import process_registry
                    _killed = process_registry.kill_all()
                    if _killed:
                        logger.info(
                            "Shutdown (%s): killed %d tool subprocess(es)",
                            phase, _killed,
                        )
                except Exception as _e:
                    logger.debug("process_registry.kill_all (%s) error: %s", phase, _e)
                try:
                    from cron.scheduler import mark_running_jobs_interrupted
                    interrupted = mark_running_jobs_interrupted(
                        f"Gateway shutdown ({phase}) killed the job's tool "
                        "subprocess before the run finished."
                    )
                    if interrupted:
                        logger.warning(
                            "Shutdown (%s): marked %d in-flight cron job(s) interrupted: %s",
                            phase,
                            len(interrupted),
                            ", ".join(interrupted),
                        )
                except Exception as _e:
                    logger.debug(
                        "mark_running_jobs_interrupted (%s) error: %s",
                        phase,
                        _e,
                    )
                try:
                    from tools.terminal_tool import cleanup_all_environments
                    cleanup_all_environments()
                except Exception as _e:
                    logger.debug("cleanup_all_environments (%s) error: %s", phase, _e)
                try:
                    from tools.browser_tool import cleanup_all_browsers
                    cleanup_all_browsers()
                except Exception as _e:
                    logger.debug("cleanup_all_browsers (%s) error: %s", phase, _e)

            # Thread-based shutdown watchdog (#66892): asyncio timeouts cannot
            # recover a frozen loop. Arm a plain OS thread at the start of
            # stop(); if teardown never finishes within drain+grace it dumps
            # faulthandler stacks and os._exit so KeepAlive/systemd can revive.
            # Skip under pytest so stop()-driving unit tests don't get a
            # delayed hard-exit in the worker.
            _watchdog_done = threading.Event()
            self._shutdown_watchdog_done = _watchdog_done
            _stop_started_at_box: dict[str, float] = {}

            def _shutdown_watchdog_snapshot() -> dict:
                started = _stop_started_at_box.get("t")
                return {
                    "restart_requested": bool(self._restart_requested),
                    "draining": bool(self._draining),
                    "running": bool(self._running),
                    "active_agents": self._running_agent_count(),
                    "active_cron_jobs": self._active_cron_job_count(),
                    "active_api_runs": self._active_api_run_count(),
                    "restart_drain_timeout": self._restart_drain_timeout,
                    "watchdog_delay_s": resolve_shutdown_watchdog_delay(
                        self._restart_drain_timeout
                    ),
                    "phase_elapsed_s": (
                        time.monotonic() - started if started is not None else None
                    ),
                }

            if not os.environ.get("PYTEST_CURRENT_TEST"):
                arm_shutdown_watchdog(
                    resolve_shutdown_watchdog_delay(self._restart_drain_timeout),
                    done_event=_watchdog_done,
                    snapshot_fn=_shutdown_watchdog_snapshot,
                    exit_code=1,
                )

            try:
                await _stop_impl_body(
                    _kill_tool_subprocesses,
                    _stop_started_at_box,
                )
            finally:
                _watchdog_done.set()

        async def _stop_impl_body(_kill_tool_subprocesses, _stop_started_at_box) -> None:
            logger.info(
                "Stopping gateway%s...",
                " for restart" if self._restart_requested else "",
            )
            _stop_started_at = time.monotonic()
            _stop_started_at_box["t"] = _stop_started_at

            def _phase_elapsed() -> float:
                return time.monotonic() - _stop_started_at

            self._running = False
            self._draining = True

            stop_watchdog = getattr(self, "_stop_systemd_watchdog", None)
            if callable(stop_watchdog):
                await stop_watchdog()

            # Reconnect tasks can mutate profile adapter maps, so cancel them
            # before taking notification/drain snapshots.
            await self._cancel_secondary_profile_reconnect_tasks()

            # Notify active chats and operator home channels BEFORE draining.
            # Adapters are still connected here, so messages can be sent.
            await self._notify_active_sessions_of_shutdown()
            logger.info(
                "Shutdown phase: notify_active_sessions done at +%.2fs",
                _phase_elapsed(),
            )

            timeout = self._restart_drain_timeout

            def _cron_tick_active() -> bool:
                try:
                    from cron.scheduler import is_tick_running
                    return bool(is_tick_running())
                except Exception as _e:
                    logger.debug("Cron tick running check failed during shutdown: %s", _e)
                    return False

            if self._restart_requested and _cron_tick_active():
                _cron_wait_started_at = time.monotonic()
                logger.info(
                    "Gateway restart requested while a cron tick is active; waiting up to %.1fs for cron to finish.",
                    timeout,
                )
                while _cron_tick_active() and (time.monotonic() - _cron_wait_started_at) < timeout:
                    self._update_runtime_status("draining")
                    await asyncio.sleep(1.0)
                if _cron_tick_active():
                    logger.warning(
                        "Gateway restart proceeding after %.1fs with cron tick still active.",
                        time.monotonic() - _cron_wait_started_at,
                    )
                else:
                    logger.info(
                        "Gateway restart cron wait completed at +%.2fs.",
                        _phase_elapsed(),
                    )

            _cron_at_start = self._active_cron_job_count()
            _api_at_start = self._active_api_run_count()
            _drain_started_at = time.monotonic()
            active_agents, timed_out = await self._drain_active_agents(timeout)
            _adapter_processing_at_timeout = (
                self._snapshot_adapter_processing_tasks() if timed_out else []
            )
            logger.info(
                "Shutdown phase: drain done at +%.2fs (drain took %.2fs, "
                "timed_out=%s, active_at_start=%d, active_now=%d, "
                "cron_at_start=%d, cron_now=%d, "
                "api_at_start=%d, api_now=%d, adapter_now=%d)",
                _phase_elapsed(),
                time.monotonic() - _drain_started_at,
                timed_out,
                len(active_agents),
                self._running_agent_count(),
                _cron_at_start,
                self._active_cron_job_count(),
                _api_at_start,
                self._active_api_run_count(),
                len(_adapter_processing_at_timeout),
            )

            if timed_out:
                try:
                    _delivery_grace = max(
                        float(self._shutdown_delivery_grace_seconds), 0.0
                    )
                except (TypeError, ValueError):
                    _delivery_grace = _SHUTDOWN_DELIVERY_GRACE_SECS_DEFAULT
                logger.warning(
                    "Gateway drain timed out (agent budget %.1fs, delivery grace %.1fs) "
                    "with %d active agent(s), "
                    "%d in-flight cron job(s), %d api_server run(s), and %d "
                    "adapter delivery task(s); "
                    "interrupting remaining work.",
                    timeout,
                    _delivery_grace,
                    self._running_agent_count(),
                    self._active_cron_job_count(),
                    self._active_api_run_count(),
                    len(_adapter_processing_at_timeout),
                )
                # Mark forcibly-interrupted sessions as resume_pending BEFORE
                # interrupting the agents.  This preserves each session's
                # session_id + transcript so the next message on the same
                # session_key auto-resumes from the existing conversation
                # instead of getting routed through suspend_recently_active()
                # and converted into a fresh session.  Terminal escalation
                # for genuinely stuck sessions still flows through the
                # existing ``.restart_failure_counts`` stuck-loop counter
                # (incremented below, threshold 3), which sets
                # ``suspended=True`` and overrides resume_pending.
                #
                # Iterate self._running_agents (current) rather than the
                # drain-start ``active_agents`` snapshot — the snapshot
                # may include sessions that finished gracefully during
                # the drain window, and marking those falsely would give
                # them a stray restart-interruption system note on their
                # next turn even though their previous turn completed
                # cleanly.  Skip pending sentinels for the same reason
                # _interrupt_running_agents() does: their agent hasn't
                # started yet, there's nothing to interrupt, and the
                # session shouldn't carry a misleading resume flag.
                _resume_reason = (
                    "restart_timeout" if self._restart_requested else "shutdown_timeout"
                )
                _marked_resume = 0
                for _sk, _agent in list(self._running_agents.items()):
                    if _agent is _AGENT_PENDING_SENTINEL:
                        continue
                    try:
                        if await self.async_session_store.mark_resume_pending(_sk, _resume_reason):
                            _marked_resume += 1
                    except Exception as _e:
                        logger.debug(
                            "mark_resume_pending failed for %s: %s",
                            _sk, _e,
                        )
                logger.info(
                    "Marked %d interrupted session(s) resume-pending before gateway %s",
                    _marked_resume,
                    "restart" if self._restart_requested else "shutdown",
                )

                # A model turn can finish and clear ``_running_agents`` before
                # BasePlatformAdapter resumes from its handler await to record
                # the final delivery obligation.  Those adapter-only tasks are
                # not agent interruptions, but aborting them would still lose a
                # generated response.  Arm cancellation-time resume persistence
                # on every primary/profile adapter before requesting cancel.
                _adapter_only_sessions: dict[BasePlatformAdapter, set[str]] = {}
                _running_session_keys = set(self._running_agents)
                for _adapter, _session_key, _task in _adapter_processing_at_timeout:
                    if _session_key in _running_session_keys:
                        continue
                    _adapter_only_sessions.setdefault(_adapter, set()).add(_session_key)
                _adapter_cancelled = 0
                for _adapter, _session_keys in _adapter_only_sessions.items():
                    try:
                        if getattr(_adapter, "_session_store", None) is None:
                            _adapter.set_session_store(self.session_store)
                        _cancelled_sessions = _adapter.cancel_processing_sessions_for_shutdown(
                            _session_keys,
                            reason=_resume_reason,
                        )
                        _adapter_cancelled += len(_cancelled_sessions)
                    except Exception as _e:
                        logger.warning(
                            "Failed to arm adapter delivery recovery for %s: %s",
                            getattr(_adapter, "name", type(_adapter).__name__),
                            _e,
                        )
                if _adapter_cancelled:
                    logger.info(
                        "Cancelled %d adapter delivery task(s) with resume-pending recovery armed",
                        _adapter_cancelled,
                    )
                self._interrupt_running_agents(
                    _INTERRUPT_REASON_GATEWAY_RESTART if self._restart_requested else _INTERRUPT_REASON_GATEWAY_SHUTDOWN
                )
                interrupt_deadline = asyncio.get_running_loop().time() + 5.0
                while self._running_agents and asyncio.get_running_loop().time() < interrupt_deadline:
                    self._update_runtime_status("draining")
                    await asyncio.sleep(0.1)

                # Kill lingering tool subprocesses NOW, before we spend more
                # budget on adapter disconnect / session DB close.  Under
                # systemd (TimeoutStopSec bounded by drain_timeout+headroom),
                # deferring this to the end of stop() risks systemd escalating
                # to SIGKILL on the cgroup first — at which point bash/sleep
                # children left behind by an interrupted terminal tool get
                # killed by systemd instead of us (issue #8202).  The final
                # catch-all cleanup below still runs for the graceful path.
                _kill_tool_subprocesses("post-interrupt")
                logger.info(
                    "Shutdown phase: post-interrupt tool kill done at +%.2fs",
                    _phase_elapsed(),
                )

            if self._restart_requested and self._restart_detached:
                try:
                    await self._launch_detached_restart_command()
                except Exception as e:
                    logger.error("Failed to launch detached gateway restart: %s", e)

            await self._finalize_shutdown_agents(active_agents)

            # Also shut down memory providers on idle cached agents.
            # _finalize_shutdown_agents only handles agents that were
            # mid-turn at drain time; the _agent_cache may still hold
            # idle agents whose MemoryProviders never received
            # on_session_end().
            _cache_lock = getattr(self, "_agent_cache_lock", None)
            _cache = getattr(self, "_agent_cache", None)
            if _cache_lock is not None and _cache is not None:
                with _cache_lock:
                    _idle_agents = list(_cache.values())
                    _cache.clear()
                for _entry in _idle_agents:
                    _agent = (
                        _entry[0] if isinstance(_entry, tuple) else _entry
                    )
                    self._cleanup_agent_resources(_agent)

            await self._cancel_owned_runners()
            for platform, adapter in list(self.adapters.items()):
                _adapter_started_at = time.monotonic()
                try:
                    await adapter.cancel_background_tasks()
                except Exception as e:
                    logger.debug("✗ %s background-task cancel error: %s", platform.value, e)
                try:
                    await adapter.disconnect()
                    logger.info(
                        "✓ %s disconnected (%.2fs)",
                        platform.value,
                        time.monotonic() - _adapter_started_at,
                    )
                except Exception as e:
                    logger.error(
                        "✗ %s disconnect error after %.2fs: %s",
                        platform.value,
                        time.monotonic() - _adapter_started_at,
                        e,
                    )
            for _profile, _adapters in list(getattr(self, "_profile_adapters", {}).items()):
                for platform, adapter in list(_adapters.items()):
                    _adapter_started_at = time.monotonic()
                    try:
                        await adapter.cancel_background_tasks()
                    except Exception as e:
                        logger.debug(
                            "✗ %s background-task cancel error (profile %s): %s",
                            platform.value,
                            _profile,
                            e,
                        )
                    try:
                        await adapter.disconnect()
                        logger.info(
                            "✓ %s disconnected (profile %s, %.2fs)",
                            platform.value,
                            _profile,
                            time.monotonic() - _adapter_started_at,
                        )
                    except Exception as e:
                        logger.error(
                            "✗ %s disconnect error (profile %s) after %.2fs: %s",
                            platform.value,
                            _profile,
                            time.monotonic() - _adapter_started_at,
                            e,
                        )
            logger.info(
                "Shutdown phase: all adapters disconnected at +%.2fs",
                _phase_elapsed(),
            )

            for _task in list(self._background_tasks):
                if _task is self._stop_task:
                    continue
                _task.cancel()
            self._background_tasks.clear()
            retry_tasks = getattr(self, "_terminal_delivery_retry_tasks", None)
            if isinstance(retry_tasks, dict):
                retry_tasks.clear()

            self.adapters.clear()
            if hasattr(self, '_profile_adapters'):
                self._profile_adapters.clear()
            self._running_agents.clear()
            self._running_agents_ts.clear()
            self._pending_messages.clear()
            self._pending_approvals.clear()
            self._shutdown_executor()
            if hasattr(self, '_busy_ack_ts'):
                self._busy_ack_ts.clear()
            self._shutdown_event.set()

            # Global cleanup: kill any remaining tool subprocesses not tied
            # to a specific agent (catch-all for zombie prevention). On the
            # drain-timeout path we already did this earlier after agent
            # interrupt — this second call catches (a) the graceful path
            # where drain succeeded without interrupt, and (b) anything
            # that got respawned between the earlier call and adapter
            # disconnect (defense in depth; safe to call repeatedly).
            _kill_tool_subprocesses("final-cleanup")
            logger.info(
                "Shutdown phase: final-cleanup tool kill done at +%.2fs",
                _phase_elapsed(),
            )

            # Reap the process-global auxiliary-client cache once at the very
            # end of teardown.  Per-turn cleanup runs in _cleanup_agent_resources
            # for each active agent, but clients bound to worker-thread loops
            # that died with their ThreadPoolExecutor (notably cron ticks) only
            # get swept here.  Without this, long-running gateways accumulate
            # async httpx transports until they hit EMFILE on macOS's default
            # RLIMIT_NOFILE=256.  See #14210.
            try:
                from agent.auxiliary_client import shutdown_cached_clients
                shutdown_cached_clients()
            except Exception as _e:
                logger.debug("shutdown_cached_clients error: %s", _e)

            # Close SQLite session DBs so the WAL write lock is released.
            # Without this, --replace and similar restart flows leave the
            # old gateway's connection holding the WAL lock until Python
            # actually exits — causing 'database is locked' errors when
            # the new gateway tries to open the same file.
            for _db_holder in (self, getattr(self, "session_store", None)):
                _db = getattr(_db_holder, "_db", None) if _db_holder else None
                if _db is None or not hasattr(_db, "close"):
                    continue
                try:
                    _db.close()
                except Exception as _e:
                    logger.debug("SessionDB close error: %s", _e)
            logger.info(
                "Shutdown phase: SessionDB close done at +%.2fs",
                _phase_elapsed(),
            )

            from gateway.status import remove_pid_file, release_gateway_runtime_lock
            remove_pid_file()
            release_gateway_runtime_lock()

            # Write a clean-shutdown marker so the next startup knows this
            # wasn't a crash.  suspend_recently_active() only needs to run
            # after unexpected exits.  However, if the drain timed out and
            # agents were force-interrupted, their sessions may be in an
            # incomplete state (trailing tool response, no final assistant
            # message).  Skip the marker in that case so the next startup
            # suspends those sessions — giving users a clean slate instead
            # of resuming a half-finished tool loop.
            if not timed_out:
                try:
                    (_hermes_home / ".clean_shutdown").touch()
                except Exception:
                    pass
            else:
                logger.info(
                    "Skipping .clean_shutdown marker — drain timed out with "
                    "interrupted agents; next startup will auto-resume recent "
                    "resume-pending sessions."
                )

            # Track sessions that were active at shutdown for stuck-loop
            # detection (#7536).  On each restart, the counter increments
            # for sessions that were running.  If a session hits the
            # threshold (3 consecutive restarts while active), the next
            # startup auto-suspends it — breaking the loop.
            if active_agents:
                self._increment_restart_failure_counts(set(active_agents.keys()))

            # A direct ``systemctl restart`` sends SIGTERM without going
            # through Hermes' /restart path.  Preserve the same home-channel
            # notification contract as a planned terminal/service restart so
            # operators can distinguish a healthy reconnect from silence.
            systemd_signal_restart = (
                bool(os.environ.get("INVOCATION_ID"))
                and bool(getattr(self, "_signal_initiated_shutdown", False))
                and not self._restart_requested
            )
            if (
                (self._restart_requested and self._restart_command_source is None)
                or systemd_signal_restart
            ):
                try:
                    atomic_json_write(
                        _planned_restart_notification_path(),
                        {
                            "requested_at": time.time(),
                            "via_service": bool(self._restart_via_service),
                            "detached": bool(self._restart_detached),
                            "systemd_signal_restart": systemd_signal_restart,
                        },
                        indent=None,
                    )
                except Exception as e:
                    logger.debug(
                        "Failed to write planned restart notification marker: %s",
                        e,
                    )

            if self._restart_requested and self._restart_via_service:
                self._launch_systemd_restart_shortcut()
                self._exit_code = GATEWAY_SERVICE_RESTART_EXIT_CODE
                self._exit_reason = self._exit_reason or "Gateway restart requested"

            self._draining = False
            if (
                getattr(self, "_signal_initiated_shutdown", False)
                and not self._restart_requested
            ):
                logger.info(
                    "Gateway stopped by an unexpected signal — persisting "
                    "gateway_state=running so container_boot auto-starts on "
                    "the next boot"
                )
                self._update_runtime_status("running", self._exit_reason)
            else:
                self._update_runtime_status("stopped", self._exit_reason)
            logger.info("Gateway stopped (total teardown %.2fs)", _phase_elapsed())

        self._stop_task = asyncio.create_task(_stop_impl())
        await self._stop_task

    async def wait_for_shutdown(self) -> None:
        """Wait for shutdown signal."""
        await self._shutdown_event.wait()

    async def _start_secondary_profile_adapters(self) -> int:
        """Bring up adapters for every non-active profile this gateway serves."""
        if not getattr(self.config, "multiplex_profiles", False):
            return 0
        try:
            from hermes_cli.profiles import profiles_to_serve, get_active_profile_name
        except Exception:
            logger.debug("profile enumeration unavailable for multiplex gateway", exc_info=True)
            return 0

        active = get_active_profile_name() or "default"
        connected = 0
        claimed: Dict[tuple, str] = {}
        for platform, adapter in getattr(self, "adapters", {}).items():
            fp = self._adapter_credential_fingerprint(adapter)
            if fp is not None:
                claimed[(platform, fp)] = active

        for profile_name, profile_home in profiles_to_serve(multiplex=True):
            if profile_name == active:
                continue
            try:
                connected += await self._start_one_profile_adapters(
                    profile_name, profile_home, claimed
                )
            except SecondaryPortBindingConfigError as exc:
                logger.warning(
                    "Skipping secondary profile '%s' due to port-binding config error: %s",
                    profile_name,
                    exc,
                )
            except MultiplexConfigError:
                # Security-policy violations are process-fatal: silently
                # skipping an unsafe profile would hide operator intent.
                raise
            except Exception as exc:
                logger.error(
                    "Failed to start adapters for profile '%s': %s",
                    profile_name,
                    exc,
                    exc_info=True,
                )

        try:
            from gateway.status import write_runtime_status
            from gateway.pairing import PairingStore

            served = [active] + sorted(
                getattr(self, "_profile_adapters", {}).keys()
            )
            for name in served:
                if name and name not in self.pairing_stores:
                    self.pairing_stores[name] = PairingStore(profile=name)
            write_runtime_status(served_profiles=served)
        except Exception:
            logger.debug("could not record served_profiles", exc_info=True)
        return connected

    async def _start_one_profile_adapters(
        self, profile_name: str, profile_home: "Path", claimed: Dict[tuple, str]
    ) -> int:
        """Create and connect one profile's adapters under its runtime scope."""
        from gateway.config import load_gateway_config

        with _profile_runtime_scope(profile_home):
            profile_cfg = load_gateway_config()
            violation = _own_policy_open_startup_violation(profile_cfg)
        if violation:
            raise MultiplexConfigError(
                f"Profile '{profile_name}' enables {violation}. "
                "Enable GATEWAY_ALLOW_ALL_USERS or the platform allow-all flag "
                "for that profile, or change dm_policy/group_policy away from "
                "'open'."
            )

        port_binding_platforms = sorted(
            platform.value
            for platform, platform_config in profile_cfg.platforms.items()
            if platform_config.enabled
            and _platform_binds_port(platform.value, platform_config.extra)
        )
        if port_binding_platforms:
            joined = ", ".join(port_binding_platforms)
            raise SecondaryPortBindingConfigError(
                f"Profile '{profile_name}' enables port-binding platform(s) "
                f"{joined}, but gateway.multiplex_profiles is on. The default "
                f"profile owns the single shared HTTP listener and serves every "
                f"profile through the /p/{profile_name}/ URL prefix. Remove "
                f"these platform entries from profile '{profile_name}'s config.yaml "
                f"or configure them only on the default profile."
            )

        profile_map = self._profile_adapters.setdefault(profile_name, {})
        connected = 0
        for platform, platform_config in profile_cfg.platforms.items():
            if not platform_config.enabled:
                continue
            # Relay is the process-shared multiplex ingress. The primary
            # profile owns its one connection; connector-stamped
            # ``source.profile`` routes turns to secondary profiles.
            if (
                getattr(self.config, "multiplex_profiles", False)
                and platform is Platform.RELAY
            ):
                continue

            with _profile_runtime_scope(profile_home):
                adapter = self._create_adapter(platform, platform_config)
            if not adapter:
                logger.warning(
                    "[MULTIPLEX] Profile '%s': skipping platform '%s' - adapter creation returned None",
                    profile_name,
                    platform.value,
                )
                continue

            fp = self._adapter_credential_fingerprint(adapter)
            if fp is not None:
                owner = claimed.get((platform, fp))
                if owner is not None:
                    logger.error(
                        "Profile '%s' and '%s' both configure %s with the same credential; "
                        "refusing to start the duplicate.",
                        owner,
                        profile_name,
                        platform.value,
                    )
                    await self._safe_adapter_disconnect(adapter, platform)
                    continue
                claimed[(platform, fp)] = profile_name

            self._configure_profile_adapter(adapter, profile_name, platform)

            try:
                with _profile_runtime_scope(profile_home):
                    success = await self._connect_adapter_with_timeout(adapter, platform)
                if success:
                    profile_map[platform] = adapter
                    self._install_background_worker_reaction_gate(adapter)
                    connected += 1
                    logger.info("✓ %s connected (profile: %s)", platform.value, profile_name)
                else:
                    logger.warning("✗ %s failed to connect (profile: %s)", platform.value, profile_name)
                    await self._safe_adapter_disconnect(adapter, platform)
            except Exception as e:
                logger.error("✗ %s error (profile: %s): %s", platform.value, profile_name, e)
                await self._safe_adapter_disconnect(adapter, platform)
        return connected

    def _configure_profile_adapter(
        self,
        adapter: BasePlatformAdapter,
        profile_name: str,
        platform: Platform,
    ) -> None:
        """Install the profile-scoped handlers shared by startup and reconnect."""
        adapter.set_message_handler(self._make_profile_message_handler(profile_name))
        adapter.set_fatal_error_handler(
            self._make_profile_fatal_error_handler(profile_name, platform)
        )
        adapter.set_session_store(self.session_store)
        adapter.set_busy_session_handler(self._handle_active_session_busy_message)
        adapter.set_topic_recovery_fn(self._recover_telegram_topic_thread_id)
        adapter.set_authorization_check(
            self._make_adapter_auth_check(platform, profile_name=profile_name)
        )
        adapter._busy_text_mode = self._busy_text_mode

    async def _run_secondary_profile_reconnect(
        self, profile_name: str, platform: Platform
    ) -> None:
        """Reconnect a retryable secondary adapter under its own profile scope."""
        attempts = 0
        current_task = asyncio.current_task()
        try:
            while self._running:
                adapter = None
                try:
                    from hermes_cli.profiles import get_profile_dir
                    from gateway.config import load_gateway_config

                    profile_home = get_profile_dir(profile_name)
                    with _profile_runtime_scope(profile_home):
                        profile_config = load_gateway_config().platforms.get(platform)
                        if profile_config is None or not profile_config.enabled:
                            return
                        adapter = self._create_adapter(platform, profile_config)
                        if adapter is None:
                            logger.warning(
                                "Secondary %s reconnect skipped: adapter unavailable (profile: %s)",
                                platform.value,
                                profile_name,
                            )
                            return
                        self._configure_profile_adapter(
                            adapter, profile_name, platform
                        )
                        success = await self._connect_adapter_with_timeout(
                            adapter, platform, is_reconnect=True
                        )

                    if success and self._running:
                        profile_map = self._profile_adapters.setdefault(profile_name, {})
                        if platform not in profile_map:
                            profile_map[platform] = adapter
                            self._install_background_worker_reaction_gate(adapter)
                            self._sync_voice_mode_state_to_adapter(adapter)
                            if platform is Platform.DISCORD:
                                self._schedule_pending_discord_terminal_reactions(
                                    platform=platform,
                                    profile_name=profile_name,
                                )
                            logger.info(
                                "✓ %s reconnected (profile: %s)",
                                platform.value,
                                profile_name,
                            )
                            return
                        # A newer reconnect already won the slot while this
                        # attempt was awaiting connect; do not replace it.
                        await self._safe_adapter_disconnect(adapter, platform)
                        return

                    # Shutdown can begin while connect() is in flight. Do not
                    # republish a newly connected adapter after the registry has
                    # been drained; release its partial resources instead.
                    if success:
                        await self._safe_adapter_disconnect(adapter, platform)
                        return

                    await self._safe_adapter_disconnect(adapter, platform)
                    if (
                        getattr(adapter, "has_fatal_error", False)
                        and not getattr(adapter, "fatal_error_retryable", True)
                    ):
                        return
                except asyncio.CancelledError:
                    if adapter is not None:
                        await self._safe_adapter_disconnect(adapter, platform)
                    raise
                except Exception:
                    if adapter is not None:
                        await self._safe_adapter_disconnect(adapter, platform)
                    logger.debug(
                        "Secondary %s reconnect attempt failed (profile: %s)",
                        platform.value,
                        profile_name,
                        exc_info=True,
                    )

                if not self._running:
                    return
                attempts += 1
                backoff = _reconnect_backoff(attempts)
                logger.info(
                    "Secondary %s reconnect retry in %ds (profile: %s)",
                    platform.value,
                    backoff,
                    profile_name,
                )
                await asyncio.sleep(backoff)
        finally:
            pending = self._profile_failed_platforms
            if isinstance(pending, dict):
                profile_pending = pending.get(profile_name)
                task = profile_pending.get(platform) if isinstance(profile_pending, dict) else None
                if not isinstance(task, asyncio.Task) or task is current_task:
                    if isinstance(profile_pending, dict):
                        profile_pending.pop(platform, None)
                        if not profile_pending:
                            pending.pop(profile_name, None)

    def _schedule_secondary_profile_reconnect(
        self, profile_name: str, platform: Platform, adapter: BasePlatformAdapter
    ) -> None:
        """Schedule one runner-owned reconnect without sharing primary secrets."""
        if not self._running or not adapter.fatal_error_retryable:
            return
        pending = self._profile_failed_platforms
        if not isinstance(pending, dict):
            pending = {}
            self._profile_failed_platforms = pending
        profile_pending = pending.setdefault(profile_name, {})
        if platform in profile_pending:
            return
        task = asyncio.create_task(
            self._run_secondary_profile_reconnect(profile_name, platform),
            name=f"secondary-reconnect:{profile_name}:{platform.value}",
        )
        profile_pending[platform] = task
        background_tasks = getattr(self, "_background_tasks", None)
        if not isinstance(background_tasks, set):
            background_tasks = set()
            self._background_tasks = background_tasks
        background_tasks.add(task)
        task.add_done_callback(background_tasks.discard)

    def _make_profile_fatal_error_handler(
        self, profile_name: str, platform: Platform
    ) -> Callable[[BasePlatformAdapter], Awaitable[None]]:
        """Route a secondary-profile fatal error to that profile's reconnect slot."""
        async def _handler(adapter: BasePlatformAdapter) -> None:
            await self._handle_profile_adapter_fatal_error(profile_name, platform, adapter)

        return _handler

    async def _handle_profile_adapter_fatal_error(
        self,
        profile_name: str,
        platform: Platform,
        adapter: BasePlatformAdapter,
    ) -> None:
        """Remove a failed multiplexed adapter without touching the primary slot.

        Secondary adapters are owned by ``_profile_adapters`` rather than
        ``self.adapters``. The primary-only fatal handler intentionally ignores
        them; without this route, a fatal secondary Discord client stayed live
        forever after its liveness sampler stopped.
        """
        profile_map = getattr(self, "_profile_adapters", {}).get(profile_name)
        if not isinstance(profile_map, dict) or profile_map.get(platform) is not adapter:
            logger.debug(
                "Ignoring stale fatal error from secondary %s adapter (profile: %s)",
                platform.value,
                profile_name,
            )
            return
        profile_map.pop(platform, None)
        await self._safe_adapter_disconnect(adapter, platform)
        if not self._running:
            return
        self._schedule_secondary_profile_reconnect(profile_name, platform, adapter)
        logger.error(
            "Fatal %s adapter error for multiplexed profile %s (%s)",
            platform.value,
            profile_name,
            adapter.fatal_error_code or "unknown",
        )
        # Reconnect is scoped to the profile's own config and secret mapping;
        # never rebuild a secondary adapter with the default profile's credentials.

    def _make_profile_message_handler(self, profile_name: str):
        """Return a message handler that stamps source.profile then delegates.

        Auth runs inside ``_handle_message`` *before* the agent-turn scope is
        installed. For secondary profiles under multiplex, wrap the whole
        handler in ``_profile_runtime_scope`` so allowlists/tokens from that
        profile's ``.env`` are visible to ``get_secret`` / authz.
        """
        from hermes_cli.profiles import get_profile_dir

        try:
            profile_home = get_profile_dir(profile_name)
        except Exception:
            profile_home = None

        async def _handler(event):
            try:
                if getattr(event, "source", None) is not None and not event.source.profile:
                    event.source.profile = profile_name
            except Exception:
                pass
            if profile_home is not None:
                with _profile_runtime_scope(profile_home):
                    return await self._handle_message(event)
            return await self._handle_message(event)

        return _handler

    @staticmethod
    def _adapter_credential_fingerprint(adapter: Any) -> Optional[str]:
        """Return a stable, log-safe fingerprint for adapter credentials."""
        token = None
        for attr in ("token", "bot_token", "_token", "api_token", "_bot_token"):
            val = getattr(adapter, attr, None)
            if isinstance(val, str) and val.strip():
                token = val.strip()
                break
        # Many adapters (e.g. Discord) store the token on their `config`
        # sub-object rather than directly on the adapter. Without this lookup
        # those adapters all return None here, the same-token conflict check
        # is silently skipped, and every profile's adapter for that platform
        # starts polling the same bot token — producing a per-message race
        # for which adapter answers. See test_reads_config_token.
        if not token:
            cfg = getattr(adapter, "config", None)
            if cfg is not None:
                for attr in ("token", "bot_token"):
                    val = getattr(cfg, attr, None)
                    if isinstance(val, str) and val.strip():
                        token = val.strip()
                        break
        if not token:
            config = getattr(adapter, "config", None)
            val = getattr(config, "token", None)
            if isinstance(val, str) and val.strip():
                token = val.strip()
        if not token:
            return None
        import hashlib
        return hashlib.sha256(("hermes-mux:" + token).encode("utf-8")).hexdigest()[:16]

    def _create_adapter(
        self,
        platform: Platform,
        config: Any
    ) -> Optional[BasePlatformAdapter]:
        """Create the appropriate adapter for a platform.

        Checks the platform_registry first (plugin adapters), then falls
        through to the built-in if/elif chain for core platforms.
        """
        if hasattr(config, "extra") and isinstance(config.extra, dict):
            config.extra.setdefault(
                "group_sessions_per_user",
                self.config.group_sessions_per_user,
            )
            config.extra.setdefault(
                "thread_sessions_per_user",
                getattr(self.config, "thread_sessions_per_user", False),
            )

        # ── Plugin-registered platforms (checked first) ───────────────────
        try:
            from gateway.platform_registry import platform_registry
            if platform_registry.is_registered(platform.value):
                adapter = platform_registry.create_adapter(platform.value, config)
                if adapter is not None:
                    # Inject a back-reference to the gateway runner so every
                    # adapter can (a) deliver cross-platform admin alerts and
                    # (b) resolve inbound profile routing through
                    # ``runner._profile_name_for_source``. Unconditional:
                    # ``BasePlatformAdapter`` declares ``gateway_runner``, so
                    # this reaches ALL platforms (not just the ones that
                    # pre-declared it), making profile routing platform-generic.
                    adapter.gateway_runner = self
                    return adapter
                # Registered but failed to instantiate — don't silently fall
                # through to built-ins (there are none for plugin platforms).
                logger.error(
                    "Platform '%s' is registered but adapter creation failed "
                    "(check dependencies and config)",
                    platform.value,
                )
                return None
        except Exception as e:
            logger.debug("Platform registry lookup for '%s' failed: %s", platform.value, e)
        # Fall through to built-in adapters below

        if platform == Platform.TELEGRAM:
            from gateway.platforms.telegram import TelegramAdapter, check_telegram_requirements
            if not check_telegram_requirements():
                logger.warning("Telegram: python-telegram-bot not installed")
                return None
            adapter = TelegramAdapter(config)
            # Apply Telegram notification mode from config.  Controls whether
            # intermediate messages (tool progress, streaming, status) trigger
            # push notifications.  Supports ENV override for quick testing.
            _notify_mode = os.getenv("HERMES_TELEGRAM_NOTIFICATIONS", "")
            if not _notify_mode:
                try:
                    _gw_cfg = _load_gateway_config()
                    _raw = cfg_get(_gw_cfg, "display", "platforms", "telegram", "notifications")
                    if _raw not in {None, ""}:
                        _notify_mode = str(_raw).strip().lower()
                except Exception:
                    pass
            _notify_mode = _notify_mode or "important"
            if _notify_mode not in {"all", "important"}:
                logger.warning(
                    "Unknown telegram notifications mode '%s', "
                    "defaulting to 'important' (valid: all, important)",
                    _notify_mode,
                )
                _notify_mode = "important"
            adapter._notifications_mode = _notify_mode
            return adapter

        elif platform == Platform.WHATSAPP:
            from gateway.platforms.whatsapp import WhatsAppAdapter, check_whatsapp_requirements
            if not check_whatsapp_requirements():
                logger.warning("WhatsApp: Node.js not installed or bridge not configured")
                return None
            return WhatsAppAdapter(config)

        elif platform == Platform.SLACK:
            from gateway.platforms.slack import SlackAdapter, check_slack_requirements
            if not check_slack_requirements():
                logger.warning("Slack: slack-bolt not installed. Run: pip install 'hermes-agent[slack]'")
                return None
            return SlackAdapter(config)

        elif platform == Platform.SIGNAL:
            from gateway.platforms.signal import (
                SignalAdapter,
                check_signal_requirements,
                validate_signal_config,
            )
            if not check_signal_requirements():
                logger.warning("Signal: runtime requirements not met")
                return None
            if not validate_signal_config(config):
                logger.warning("Signal: SIGNAL_HTTP_URL or SIGNAL_ACCOUNT not configured")
                return None
            return SignalAdapter(config)

        elif platform == Platform.HOMEASSISTANT:
            from gateway.platforms.homeassistant import HomeAssistantAdapter, check_ha_requirements
            if not check_ha_requirements():
                logger.warning("HomeAssistant: aiohttp not installed or HASS_TOKEN not set")
                return None
            return HomeAssistantAdapter(config)

        elif platform == Platform.EMAIL:
            from gateway.platforms.email import EmailAdapter, check_email_requirements
            if not check_email_requirements():
                logger.warning("Email: EMAIL_ADDRESS, EMAIL_PASSWORD, EMAIL_IMAP_HOST, or EMAIL_SMTP_HOST not set")
                return None
            return EmailAdapter(config)

        elif platform == Platform.SMS:
            from gateway.platforms.sms import SmsAdapter, check_sms_requirements
            if not check_sms_requirements():
                logger.warning("SMS: aiohttp not installed or TWILIO_ACCOUNT_SID/TWILIO_AUTH_TOKEN not set")
                return None
            return SmsAdapter(config)

        elif platform == Platform.DINGTALK:
            from gateway.platforms.dingtalk import DingTalkAdapter, check_dingtalk_requirements
            if not check_dingtalk_requirements():
                logger.warning("DingTalk: dingtalk-stream not installed or DINGTALK_CLIENT_ID/SECRET not set")
                return None
            return DingTalkAdapter(config)

        elif platform == Platform.FEISHU:
            from gateway.platforms.feishu import FeishuAdapter, check_feishu_requirements
            if not check_feishu_requirements():
                logger.warning("Feishu: lark-oapi not installed or FEISHU_APP_ID/SECRET not set")
                return None
            return FeishuAdapter(config)

        elif platform == Platform.WECOM_CALLBACK:
            from gateway.platforms.wecom_callback import (
                WecomCallbackAdapter,
                check_wecom_callback_requirements,
            )
            if not check_wecom_callback_requirements():
                logger.warning("WeComCallback: aiohttp/httpx/defusedxml not installed")
                return None
            return WecomCallbackAdapter(config)

        elif platform == Platform.WECOM:
            from gateway.platforms.wecom import WeComAdapter, check_wecom_requirements
            if not check_wecom_requirements():
                logger.warning("WeCom: aiohttp not installed or WECOM_BOT_ID/SECRET not set")
                return None
            return WeComAdapter(config)

        elif platform == Platform.WEIXIN:
            from gateway.platforms.weixin import WeixinAdapter, check_weixin_requirements
            if not check_weixin_requirements():
                logger.warning("Weixin: aiohttp/cryptography not installed")
                return None
            return WeixinAdapter(config)

        elif platform == Platform.MATRIX:
            from gateway.platforms.matrix import MatrixAdapter, check_matrix_requirements
            if not check_matrix_requirements():
                logger.warning("Matrix: mautrix not installed or credentials not set. Run: pip install 'mautrix[encryption]'")
                return None
            return MatrixAdapter(config)

        elif platform == Platform.API_SERVER:
            from gateway.platforms.api_server import APIServerAdapter, check_api_server_requirements
            if not check_api_server_requirements():
                logger.warning("API Server: aiohttp not installed")
                return None
            adapter = APIServerAdapter(config)
            adapter.gateway_runner = self
            return adapter

        elif platform == Platform.WEBHOOK:
            from gateway.platforms.webhook import WebhookAdapter, check_webhook_requirements
            if not check_webhook_requirements():
                logger.warning("Webhook: aiohttp not installed")
                return None
            adapter = WebhookAdapter(config)
            adapter.gateway_runner = self  # For cross-platform delivery
            return adapter

        elif platform == Platform.MSGRAPH_WEBHOOK:
            from gateway.platforms.msgraph_webhook import (
                MSGraphWebhookAdapter,
                check_msgraph_webhook_requirements,
            )
            if not check_msgraph_webhook_requirements():
                logger.warning("MSGraph webhook: aiohttp not installed")
                return None
            return MSGraphWebhookAdapter(config)

        elif platform == Platform.BLUEBUBBLES:
            from gateway.platforms.bluebubbles import BlueBubblesAdapter, check_bluebubbles_requirements
            if not check_bluebubbles_requirements():
                logger.warning("BlueBubbles: aiohttp/httpx missing or BLUEBUBBLES_SERVER_URL/BLUEBUBBLES_PASSWORD not configured")
                return None
            return BlueBubblesAdapter(config)

        elif platform == Platform.QQBOT:
            from gateway.platforms.qqbot import QQAdapter, check_qq_requirements
            if not check_qq_requirements():
                logger.warning("QQBot: aiohttp/httpx missing or QQ_APP_ID/QQ_CLIENT_SECRET not configured")
                return None
            return QQAdapter(config)

        elif platform == Platform.YUANBAO:
            from gateway.platforms.yuanbao import YuanbaoAdapter, WEBSOCKETS_AVAILABLE
            if not WEBSOCKETS_AVAILABLE:
                logger.warning("Yuanbao: websockets not installed. Run: pip install websockets")
                return None
            return YuanbaoAdapter(config)

        return None

    def _adapter_enforces_own_access_policy(
        self,
        platform: Optional[Platform],
        *,
        profile: Optional[str] = None,
    ) -> bool:
        return GatewayAuthorizationMixin._adapter_enforces_own_access_policy(
            self,
            platform,
            profile=profile,
        )

    def _is_user_authorized(self, source: SessionSource) -> bool:
        return GatewayAuthorizationMixin._is_user_authorized(self, source)

    def _get_unauthorized_dm_behavior(self, platform: Optional[Platform]) -> str:
        """Return how unauthorized DMs should be handled for a platform.

        Resolution order:
        1. Explicit per-platform ``unauthorized_dm_behavior`` in config — always wins.
        2. Explicit global ``unauthorized_dm_behavior`` in config — wins when no per-platform.
        3. When an allowlist (``PLATFORM_ALLOWED_USERS``,
           ``PLATFORM_GROUP_ALLOWED_USERS`` / ``PLATFORM_GROUP_ALLOWED_CHATS``,
           or ``GATEWAY_ALLOWED_USERS``) is configured, default to ``"ignore"`` —
           the allowlist signals that the owner has deliberately restricted
           access; spamming unknown contacts with pairing codes is both noisy
           and a potential info-leak. (#9337)
        4. No allowlist and no explicit config → ``"pair"`` (open-gateway default).
        """
        config = getattr(self, "config", None)

        # Check for an explicit per-platform override first.
        if config and hasattr(config, "get_unauthorized_dm_behavior") and platform:
            platform_cfg = config.platforms.get(platform) if hasattr(config, "platforms") else None
            if platform_cfg and "unauthorized_dm_behavior" in getattr(platform_cfg, "extra", {}):
                # Operator explicitly configured behavior for this platform — respect it.
                return config.get_unauthorized_dm_behavior(platform)

        # Check for an explicit global config override.
        if config and hasattr(config, "unauthorized_dm_behavior"):
            if config.unauthorized_dm_behavior != "pair":  # non-default → explicit override
                return config.unauthorized_dm_behavior

        # Config-driven dm_policy (WeCom / Weixin / Yuanbao / QQBot). An
        # allowlist or disabled DM policy means the operator restricted access,
        # so unauthorized DMs should be dropped silently rather than answered
        # with a pairing code. An explicit pairing policy opts back into codes.
        if platform and config and hasattr(config, "platforms"):
            platform_cfg = config.platforms.get(platform)
            extra = getattr(platform_cfg, "extra", None) if platform_cfg else None
            if isinstance(extra, dict):
                dm_policy = str(extra.get("dm_policy") or "").strip().lower()
                if dm_policy == "pairing":
                    return "pair"
                if dm_policy in {"allowlist", "disabled"}:
                    return "ignore"

        # No explicit override.  Fall back to allowlist-aware default:
        # if any allowlist is configured for this platform, silently drop
        # unauthorized messages instead of sending pairing codes.
        if platform:
            platform_env_map = {
                Platform.TELEGRAM: "TELEGRAM_ALLOWED_USERS",
                Platform.DISCORD:  "DISCORD_ALLOWED_USERS",
                Platform.WHATSAPP: "WHATSAPP_ALLOWED_USERS",
                Platform.SLACK:    "SLACK_ALLOWED_USERS",
                Platform.SIGNAL:   "SIGNAL_ALLOWED_USERS",
                Platform.EMAIL:    "EMAIL_ALLOWED_USERS",
                Platform.SMS:      "SMS_ALLOWED_USERS",
                Platform.MATTERMOST: "MATTERMOST_ALLOWED_USERS",
                Platform.MATRIX:   "MATRIX_ALLOWED_USERS",
                Platform.DINGTALK: "DINGTALK_ALLOWED_USERS",
                Platform.FEISHU:   "FEISHU_ALLOWED_USERS",
                Platform.WECOM:    "WECOM_ALLOWED_USERS",
                Platform.WECOM_CALLBACK: "WECOM_CALLBACK_ALLOWED_USERS",
                Platform.WEIXIN:   "WEIXIN_ALLOWED_USERS",
                Platform.BLUEBUBBLES: "BLUEBUBBLES_ALLOWED_USERS",
                Platform.QQBOT:    "QQ_ALLOWED_USERS",
            }
            platform_group_env_map = {
                Platform.TELEGRAM: (
                    "TELEGRAM_GROUP_ALLOWED_USERS",
                    "TELEGRAM_GROUP_ALLOWED_CHATS",
                ),
                Platform.QQBOT: ("QQ_GROUP_ALLOWED_USERS",),
            }
            if os.getenv(platform_env_map.get(platform, ""), "").strip():
                return "ignore"
            for env_key in platform_group_env_map.get(platform, ()):
                if os.getenv(env_key, "").strip():
                    return "ignore"

        if os.getenv("GATEWAY_ALLOWED_USERS", "").strip():
            return "ignore"

        return "pair"

    async def _deliver_platform_notice(self, source, content: str) -> None:
        """Deliver a setup/operational notice using platform-specific privacy rules."""
        adapter = self._adapter_for_source(source)
        if not adapter:
            return

        config = getattr(self, "config", None)
        notice_delivery = "public"
        if config and hasattr(config, "get_notice_delivery"):
            notice_delivery = config.get_notice_delivery(source.platform)

        metadata = self._thread_metadata_for_source(source)
        if notice_delivery == "private" and getattr(source, "user_id", None):
            try:
                result = await adapter.send_private_notice(
                    source.chat_id,
                    source.user_id,
                    content,
                    metadata=metadata,
                )
                if getattr(result, "success", False):
                    return
            except Exception:
                logger.debug(
                    "[%s] send_private_notice failed, falling back to public",
                    getattr(source, "platform", "?"),
                    exc_info=True,
                )

        await adapter.send(source.chat_id, content, metadata=metadata)

    async def _handle_dev_merge_reaction(self, event: MessageEvent) -> Optional[str]:
        """Merge the PR attached to one delivered terminal Discord response."""

        source = event.source
        claim = await asyncio.to_thread(
            self._ledger().claim_dev_merge_for_message,
            chat_id=str(source.chat_id or ""),
            message_id=str(event.message_id or source.message_id or ""),
            actor_id=str(source.user_id or ""),
        )
        if not isinstance(claim, dict):
            return None
        closeout = claim.get("closeout") if isinstance(claim.get("closeout"), dict) else {}
        pr = closeout.get("pr") if isinstance(closeout.get("pr"), dict) else {}
        pr_url = str(pr.get("url") or "").strip()
        claim_state = str(claim.get("_dev_merge_claim") or "")
        if claim_state == "already_merged":
            return f"Merged: {pr_url}" if pr_url else "This PR is already merged."
        if claim_state == "in_progress":
            return f"Merge is already in progress: {pr_url}" if pr_url else "Merge is already in progress."
        if claim_state != "claimed":
            return None

        from hermes_cli.dev_pr_merge import DevMergeResult, merge_published_pr

        try:
            result = await asyncio.to_thread(merge_published_pr, closeout)
        except Exception:
            logger.exception(
                "Discord Dev merge execution failed for work item %s",
                claim.get("id"),
            )
            result = DevMergeResult(
                outcome="blocked",
                pr_url=pr_url,
                message=(
                    f"GitHub did not confirm the merge. Check the PR before retrying: {pr_url}"
                    if pr_url
                    else "GitHub did not confirm the merge. Check the PR before retrying."
                ),
            )
        attempt_id = str(claim.get("_dev_merge_attempt_id") or "")
        persisted = await asyncio.to_thread(
            self._ledger().finish_dev_merge,
            str(claim.get("id") or ""),
            attempt_id=attempt_id,
            outcome=result.outcome,
            message=result.message,
            pr_url=result.pr_url,
        )
        if not persisted:
            logger.error(
                "Discord Dev merge result could not be persisted for work item %s",
                claim.get("id"),
            )
        return result.message

    async def _dispatch_plugin_command(
        self, event: MessageEvent, command: str
    ) -> tuple[bool, Optional[str]]:
        """Invoke one plugin command with a trusted post-auth task context."""
        try:
            from hermes_cli.plugin_command_context import bind_plugin_command_context
            from hermes_cli.plugins import get_plugin_command_handler

            canonical = str(command or "").replace("_", "-")
            handler = get_plugin_command_handler(canonical)
            if handler is None:
                return False, None
            raw_args = event.get_command_args().strip()
            with bind_plugin_command_context(
                event=event, canonical_command=canonical, raw_args=raw_args
            ):
                result = handler(raw_args)
                if asyncio.iscoroutine(result):
                    result = await result
            return True, str(result) if result else None
        except Exception as exc:
            logger.exception("Plugin command dispatch failed: /%s", command)
            return True, "Plugin command failed. Check gateway logs for details."

    async def _handle_gateway_platform_event(self, event: dict, source) -> None:
        """Authorize and publish one normalized adapter event to plugin hooks."""
        try:
            from hermes_cli.lifecycle import has_hook, invoke_hook

            if not has_hook("gateway_platform_event"):
                return
            if not self._is_user_authorized(source):
                return
            invoke_hook("gateway_platform_event", **event)
        except Exception:
            logger.debug("gateway_platform_event hook dispatch failed", exc_info=True)

    async def _handle_message(self, event: MessageEvent) -> Optional[str]:
        """
        Handle an incoming message from any platform.

        This is the core message processing pipeline:
        1. Check user authorization
        2. Check for commands (/new, /reset, etc.)
        3. Check for running agent and interrupt if needed
        4. Get or create session
        5. Build context for agent
        6. Run agent conversation
        7. Return response
        """
        source = event.source
        if not await self._consume_promoted_replay_fence(event):
            return None

        if (
            getattr(self, "_startup_restore_in_progress", False)
            and not getattr(event, "internal", False)
            and not getattr(event, "_hermes_startup_restore_replay", False)
        ):
            self._queue_startup_restore_event(event)
            return None

        # Internal events (e.g. background-process completion notifications)
        # are system-generated and must skip user authorization.
        is_internal = bool(getattr(event, "internal", False))

        # Fire pre_gateway_dispatch plugin hook for user-originated messages.
        # Plugins receive the MessageEvent and may return a dict influencing flow:
        #   {"action": "skip",    "reason": ...}    -> drop (no reply, plugin handled)
        #   {"action": "rewrite", "text":  ...}     -> replace event.text, continue
        #   {"action": "allow"}   /   None          -> normal dispatch
        # Hook runs BEFORE auth so plugins can handle unauthorized senders
        # (e.g. customer handover ingest) without triggering the pairing flow.
        if not is_internal:
            try:
                from hermes_cli.plugins import invoke_hook_async as _invoke_hook_async
                _hook_results = await _invoke_hook_async(
                    "pre_gateway_dispatch",
                    event=event,
                    gateway=self,
                    session_store=self.session_store,
                )
            except Exception as _hook_exc:
                logger.warning("pre_gateway_dispatch invocation failed: %s", _hook_exc)
                _hook_results = []

            for _result in _hook_results:
                if not isinstance(_result, dict):
                    continue
                _action = _result.get("action")
                if _action == "skip":
                    logger.info(
                        "pre_gateway_dispatch skip: reason=%s platform=%s chat=%s",
                        _result.get("reason"),
                        source.platform.value if source.platform else "unknown",
                        source.chat_id or "unknown",
                    )
                    return None
                if _action == "rewrite":
                    _new_text = _result.get("text")
                    if isinstance(_new_text, str):
                        event = dataclasses.replace(event, text=_new_text)
                        source = event.source
                    break
                if _action == "allow":
                    break

        if is_internal:
            pass
        elif source.user_id is None:
            # Messages with no user identity (Telegram service messages,
            # channel forwards, anonymous admin posts, sender_chat) can't
            # be paired, but they can still be authorized via a
            # chat-scoped allowlist (e.g. TELEGRAM_GROUP_ALLOWED_CHATS
            # authorizes every member of the listed chat regardless of
            # sender). Defer to _is_user_authorized so that path runs.
            if not self._is_user_authorized(source):
                logger.debug("Ignoring message with no user_id from %s", source.platform.value)
                return None
        elif not self._is_user_authorized(source):
            logger.warning("Unauthorized user: %s (%s) on %s", source.user_id, source.user_name, source.platform.value)
            # In DMs: offer pairing code. In groups: silently ignore.
            if source.chat_type == "dm" and self._get_unauthorized_dm_behavior(
                source.platform,
                profile=getattr(source, "profile", None),
            ) == "pair":
                platform_name = source.platform.value if source.platform else "unknown"
                # Rate-limit ALL pairing responses (code or rejection) to
                # prevent spamming the user with repeated messages when
                # multiple DMs arrive in quick succession.
                if self.pairing_store._is_rate_limited(platform_name, source.user_id):
                    return None
                code = self.pairing_store.generate_code(
                    platform_name, source.user_id, source.user_name or ""
                )
                if code:
                    adapter = self._adapter_for_source(source)
                    if adapter:
                        await adapter.send(
                            source.chat_id,
                            f"Hi~ I don't recognize you yet!\n\n"
                            f"Here's your pairing code: `{code}`\n\n"
                            f"Ask the bot owner to run:\n"
                            f"`hermes pairing approve {platform_name} {code}`"
                        )
                else:
                    adapter = self._adapter_for_source(source)
                    if adapter:
                        await adapter.send(
                            source.chat_id,
                            "Too many pairing requests right now~ "
                            "Please try again later!"
                        )
                    # Record rate limit so subsequent messages are silently ignored
                    self.pairing_store._record_rate_limit(platform_name, source.user_id)
            return None

        if getattr(event, "discord_runtime_reason", None) == "dev_merge_reaction":
            return await self._handle_dev_merge_reaction(event)

        # Intercept messages that are responses to a pending /update prompt.
        # The update process (detached) wrote .update_prompt.json; the watcher
        # forwarded it to the user; now the user's reply goes back via
        # .update_response so the update process can continue.
        #
        # IMPORTANT: recognized slash commands must bypass this interception.
        # Otherwise control/session commands like /new or /help get silently
        # consumed as update answers instead of being dispatched normally.
        _quick_key = self._session_key_for_source(source)
        self._hydrate_discord_feature_summary_from_adapter(event)
        _work_item = self._accept_discord_work_item(event, _quick_key)
        if source.platform == Platform.DISCORD and not _work_item:
            generation = getattr(self._ledger(), "discord_pr_generation", None)
            event.discord_pr_generation = generation(_quick_key) if generation else 1
            event.discord_pr_rollover = False
        if (
            _work_item
            and _work_item.get("_existing")
            and not getattr(event, "work_replay", False)
        ):
            logger.info(
                "Ignoring duplicate Discord work item %s with status=%s",
                _work_item.get("id"),
                _work_item.get("status"),
            )
            return None
        _update_prompts = getattr(self, "_update_prompt_pending", {})
        if _update_prompts.get(_quick_key):
            raw = (event.text or "").strip()
            # Accept /approve and /deny as shorthand for yes/no
            cmd = event.get_command()
            if cmd in {"approve", "yes"}:
                response_text = "y"
            elif cmd in {"deny", "no"}:
                response_text = "n"
            else:
                _recognized_cmd = None
                if cmd:
                    try:
                        from hermes_cli.commands import resolve_command as _resolve_update_cmd
                    except Exception:
                        _resolve_update_cmd = None
                    if _resolve_update_cmd is not None:
                        try:
                            _cmd_def = _resolve_update_cmd(cmd)
                            _recognized_cmd = _cmd_def.name if _cmd_def else None
                        except Exception:
                            _recognized_cmd = None
                if _recognized_cmd:
                    response_text = ""
                else:
                    response_text = raw
            if response_text:
                response_path = _hermes_home / ".update_response"
                prompt_path = _hermes_home / ".update_prompt.json"
                try:
                    tmp = response_path.with_suffix(".tmp")
                    tmp.write_text(response_text)
                    tmp.replace(response_path)
                    prompt_path.unlink(missing_ok=True)
                except OSError as e:
                    logger.warning("Failed to write update response: %s", e)
                    return f"✗ Failed to send response to update process: {e}"
                _update_prompts.pop(_quick_key, None)
                label = response_text if len(response_text) <= 20 else response_text[:20] + "…"
                return f"✓ Sent `{label}` to the update process."
            # Recognized slash command during a pending update prompt:
            # unblock the detached update subprocess by writing a blank
            # response so ``_gateway_prompt`` returns the prompt's default
            # (typically a safe "n" / skip) and exits cleanly instead of
            # blocking on stdin until the 30-minute watcher timeout.
            # The slash command then falls through to normal dispatch.
            if _recognized_cmd:
                response_path = _hermes_home / ".update_response"
                prompt_path = _hermes_home / ".update_prompt.json"
                try:
                    tmp = response_path.with_suffix(".tmp")
                    tmp.write_text("")
                    tmp.replace(response_path)
                    prompt_path.unlink(missing_ok=True)
                    logger.info(
                        "Recognized /%s during pending update prompt for %s; "
                        "cancelled prompt with default and dispatching command",
                        _recognized_cmd,
                        _quick_key,
                    )
                except OSError as e:
                    logger.warning(
                        "Failed to write cancel response for pending update prompt: %s",
                        e,
                    )
                _update_prompts.pop(_quick_key, None)

        # Intercept typed responses to any pending clarify request. This
        # covers open-ended prompts, "Other" free-form replies, numeric
        # choices, and natural replies such as "option 1". The response
        # resolves the clarify and unblocks the agent thread; it must not
        # also become a new turn or live steer.
        try:
            from tools import clarify_gateway as _clarify_mod
            _pending_clarify = _clarify_mod.get_pending_for_session(
                _quick_key,
                include_choice_prompts=True,
            )
        except Exception:
            _pending_clarify = None
        if _pending_clarify is not None:
            _raw_clarify_reply = (event.text or "").strip()
            # Skip slash commands — the user clearly wanted to issue a
            # command, not answer the clarify.  Leave the clarify pending
            # so the user can retry; if it times out, the agent unblocks
            # with an empty response.
            if _raw_clarify_reply and not _raw_clarify_reply.startswith("/"):
                _resolved = _clarify_mod.resolve_text_response_for_session(
                    _quick_key,
                    _raw_clarify_reply,
                )
                if _resolved:
                    logger.info(
                        "Gateway intercepted clarify text response (session=%s, id=%s)",
                        _quick_key, _pending_clarify.clarify_id,
                    )
                    # The clarify callback pauses the platform typing/status
                    # indicator while waiting so Slack users can type their
                    # answer. The active agent resumes as soon as this reply
                    # resolves the wait, so re-enable its indicator here too.
                    # Without this, Slack stays silent until the independent
                    # long-running heartbeat fires (three minutes by default).
                    _clarify_adapter = self._adapter_for_source(source)
                    self._mark_discord_work_consumed(
                        event,
                        reason="clarify_response",
                    )
                    await self._rollback_unused_discord_feature_summary(event)
                    if _clarify_adapter:
                        try:
                            finalize = getattr(
                                _clarify_adapter,
                                "finalize_clarify_prompt",
                                None,
                            )
                            if callable(finalize):
                                finalized = finalize(_pending_clarify.clarify_id)
                                if inspect.isawaitable(finalized):
                                    await finalized
                        except Exception:
                            logger.debug(
                                "Failed to finalize clarify prompt after text response",
                                exc_info=True,
                            )
                        try:
                            _clarify_adapter.resume_typing_for_chat(source.chat_id)
                        except Exception:
                            logger.debug(
                                "Failed to resume typing after clarify response",
                                exc_info=True,
                            )
                    # Acknowledge with empty string so adapters that emit
                    # the agent's response don't double-post.  The agent
                    # itself will produce the next user-facing message.
                    return ""

        # Intercept messages that are responses to a pending /reload-mcp
        # (or future) slash-confirm prompt.  Recognized confirm replies are
        # /approve, /always, /cancel (plus short aliases).  Anything else
        # falls through to normal dispatch — a stale pending confirm does
        # NOT block other commands.
        #
        # Important: if a dangerous-command approval is ALSO pending (agent
        # blocked inside tools/approval.py), the tool approval takes
        # precedence — /approve there unblocks the waiting tool thread.
        # Slash-confirm only catches /approve when no tool approval is live.
        from tools import slash_confirm as _slash_confirm_mod
        _pending_confirm = _slash_confirm_mod.get_pending(_quick_key)
        _tool_approval_live = False
        try:
            from tools.approval import has_blocking_approval
            _tool_approval_live = has_blocking_approval(_quick_key)
        except Exception:
            _tool_approval_live = False
        if _pending_confirm and not _tool_approval_live:
            _raw_reply = (event.text or "").strip()
            _cmd_reply = event.get_command()
            _confirm_choice = None
            if _cmd_reply in {"approve", "yes", "ok", "confirm"}:
                _confirm_choice = "once"
            elif _cmd_reply in {"always", "remember"}:
                _confirm_choice = "always"
            elif _cmd_reply in {"cancel", "no", "deny", "nevermind"}:
                _confirm_choice = "cancel"
            elif _raw_reply.lower() in {"approve", "approve once", "once"}:
                _confirm_choice = "once"
            elif _raw_reply.lower() in {"always", "always approve"}:
                _confirm_choice = "always"
            elif _raw_reply.lower() in {"cancel", "nevermind", "no"}:
                _confirm_choice = "cancel"
            if _confirm_choice is not None:
                _resolved = await _slash_confirm_mod.resolve(
                    _quick_key, _pending_confirm.get("confirm_id"), _confirm_choice,
                )
                return _resolved or ""
            # Stale pending + unrelated command: drop the pending state so
            # the confirm doesn't block normal usage indefinitely.  The user
            # clearly moved on.
            _slash_confirm_mod.clear_if_stale(_quick_key)

        # PRIORITY handling when an agent is already running for this session.
        # Default behavior is to interrupt immediately so user text/stop messages
        # are handled with minimal latency.
        #
        # Special case: Telegram/photo bursts often arrive as multiple near-
        # simultaneous updates. Do NOT interrupt for photo-only follow-ups here;
        # let the adapter-level batching/queueing logic absorb them.

        # Staleness eviction: detect leaked locks from hung/crashed handlers.
        # With inactivity-based timeout, active tasks can run for hours, so
        # wall-clock age alone isn't sufficient.  Evict only when the agent
        # has been *idle* beyond the inactivity threshold (or when the agent
        # object has no activity tracker and wall-clock age is extreme).
        _raw_stale_timeout = _float_env("HERMES_AGENT_TIMEOUT", 3600)
        _stale_ts = self._running_agents_ts.get(_quick_key, 0)
        if _quick_key in self._running_agents and _stale_ts:
            _stale_age = time.time() - _stale_ts
            _stale_agent = self._running_agents.get(_quick_key)
            # Never evict the pending sentinel — it was just placed moments
            # ago during the async setup phase before the real agent is
            # created.  Sentinels have no get_activity_summary(), so the
            # idle check below would always evaluate to inf >= timeout and
            # immediately evict them, racing with the setup path.
            _stale_idle = float("inf")  # assume idle if we can't check
            _stale_detail = ""
            if _stale_agent and hasattr(_stale_agent, "get_activity_summary"):
                try:
                    _sa = _stale_agent.get_activity_summary()
                    _stale_idle = _sa.get("seconds_since_activity", float("inf"))
                    _stale_detail = (
                        f" | last_activity={_sa.get('last_activity_desc', 'unknown')} "
                        f"({_stale_idle:.0f}s ago) "
                        f"| iteration={_sa.get('api_call_count', 0)}/{_sa.get('max_iterations', 0)}"
                    )
                except Exception:
                    pass
            # Evict if: agent is idle beyond timeout, OR wall-clock age is
            # extreme (10x timeout or 2h, whichever is larger — catches
            # cases where the agent object was garbage-collected).
            _wall_ttl = max(_raw_stale_timeout * 10, 7200) if _raw_stale_timeout > 0 else float("inf")
            _should_evict = (
                _stale_agent is not _AGENT_PENDING_SENTINEL
                and (
                    (_raw_stale_timeout > 0 and _stale_idle >= _raw_stale_timeout)
                    or _stale_age > _wall_ttl
                )
            )
            if _should_evict:
                logger.warning(
                    "Evicting stale _running_agents entry for %s "
                    "(age: %.0fs, idle: %.0fs, timeout: %.0fs)%s",
                    _quick_key, _stale_age, _stale_idle,
                    _raw_stale_timeout, _stale_detail,
                )
                self._invalidate_session_run_generation(
                    _quick_key,
                    reason="stale_running_agent_eviction",
                )
                self._release_running_agent_state(_quick_key)

        if _quick_key in self._running_agents and not (
            self._running_agents.get(_quick_key) is _AGENT_PENDING_SENTINEL
            and _is_startup_resume_event(event)
        ):
            if event.get_command() == "status":
                return await self._handle_status_command(event)

            # Resolve the command once for all early-intercept checks below.
            from hermes_cli.commands import (
                ACTIVE_SESSION_BYPASS_COMMANDS as _DEDICATED_HANDLERS,
                is_gateway_known_command as _is_known_inner,
                resolve_command as _resolve_cmd_inner,
            )
            _evt_cmd = event.get_command()
            _queue_caption_args: Optional[str] = None
            if _evt_cmd is None and getattr(event, "media_urls", None):
                # The fork intentionally limits MessageEvent.is_command() to
                # TEXT/COMMAND events, but Telegram and other adapters carry a
                # photo/document caption as the media event's text. Recognize
                # only /queue here so an attached payload can use the same
                # running-agent request-control path without widening command
                # handling for every media message.
                _caption_parts = (event.text or "").strip().split(maxsplit=1)
                _caption_head = _caption_parts[0] if _caption_parts else ""
                if _caption_head.startswith("/"):
                    _caption_cmd = _caption_head[1:].lower()
                    if "@" in _caption_cmd:
                        _caption_cmd = _caption_cmd.split("@", 1)[0]
                    if "/" not in _caption_cmd and _caption_cmd in {"queue", "q"}:
                        _evt_cmd = _caption_cmd
                        _queue_caption_args = (
                            _caption_parts[1].strip()
                            if len(_caption_parts) > 1
                            else ""
                        )
            _cmd_def_inner = _resolve_cmd_inner(_evt_cmd) if _evt_cmd else None

            # Slash command access control on the running-agent fast-path.
            # Mirrors the cold-path gate further below so non-admin users
            # can't bypass gating just because an agent happens to be busy.
            # /status above is intentionally pre-gate so users always see
            # session state. /help and /whoami fall under the always-allowed
            # floor inside _check_slash_access.
            if _evt_cmd and _cmd_def_inner is not None:
                _denied = self._check_slash_access(source, _cmd_def_inner.name)
                if _denied is not None:
                    return _denied

            # Telegram sends /start for bot launches/deep-links. Treat it as a
            # platform ping, not a user command: no help dump, no agent
            # interrupt, no queued text.
            if _cmd_def_inner and _cmd_def_inner.name == "start":
                logger.info("Ignoring /start platform ping for active session %s", _quick_key)
                return ""

            if _cmd_def_inner and _cmd_def_inner.name == "restart":
                return await self._handle_restart_command(event)

            # /stop must hard-kill the session when an agent is running.
            # A soft interrupt (agent.interrupt()) doesn't help when the agent
            # is truly hung — the executor thread is blocked and never checks
            # _interrupt_requested.  Force-clean _running_agents so the session
            # is unlocked and subsequent messages are processed normally.
            if _cmd_def_inner and _cmd_def_inner.name == "stop":
                report = await self._stop_session_owned_work(
                    event,
                    [_quick_key],
                    invalidation_reason="stop_command",
                )
                if report["active_parent"]["pending"]:
                    return EphemeralReply(t("gateway.stop.stopped_pending"))
                return EphemeralReply(t("gateway.stop.stopped"))

            # /reset and /new must bypass the running-agent guard so they
            # actually dispatch as commands instead of being queued as user
            # text (which would be fed back to the agent with the same
            # broken history — #2170).  Interrupt the agent first, then
            # clear the adapter's pending queue so the stale "/reset" text
            # doesn't get re-processed as a user message after the
            # interrupt completes.
            if _cmd_def_inner and _cmd_def_inner.name == "new":
                # Clear any pending messages so the old text doesn't replay
                await self._interrupt_and_clear_session(
                    _quick_key,
                    source,
                    interrupt_reason=_INTERRUPT_REASON_RESET,
                    invalidation_reason="new_command",
                )
                # Clean up the running agent entry so the reset handler
                # doesn't think an agent is still active.
                return await self._handle_reset_command(event)

            # /queue <prompt> — queue without interrupting.
            # Semantics: each /queue invocation produces its own full agent
            # turn, processed in FIFO order after the current run (and any
            # earlier /queue items) finishes.  Messages are NOT merged.
            if _evt_cmd in {"queue", "q"}:
                queued_text = (
                    _queue_caption_args
                    if _queue_caption_args is not None
                    else event.get_command_args().strip()
                )
                has_media = bool(getattr(event, "media_urls", None))
                if not queued_text and not has_media:
                    return "Usage: /queue <prompt>"
                adapter = self._adapter_for_source(source)
                if adapter:
                    queued_event = dataclasses.replace(
                        event,
                        text=queued_text,
                        message_type=(
                            event.message_type if has_media else MessageType.TEXT
                        ),
                        media_urls=list(getattr(event, "media_urls", []) or []),
                        media_types=list(getattr(event, "media_types", []) or []),
                    )
                    self._enqueue_fifo(_quick_key, queued_event, adapter)
                depth = self._queue_depth(_quick_key, adapter=self._adapter_for_source(source))
                if depth <= 1:
                    return "Queued for the next turn."
                return f"Queued for the next turn. ({depth} queued)"

            # /steer <prompt> — guide the live run at its next safe boundary.
            # Unlike /queue, it stays in the same turn when intake is open;
            # otherwise the stripped prompt is queued immediately.
            if _cmd_def_inner and _cmd_def_inner.name == "steer":
                steer_text = event.get_command_args().strip()
                if not steer_text:
                    return "Usage: /steer <prompt>"
                running_agent = self._running_agents.get(_quick_key)
                if running_agent is _AGENT_PENDING_SENTINEL:
                    staged_event = dataclasses.replace(
                        event,
                        text=steer_text,
                        message_type=MessageType.TEXT,
                    )
                    if self._stage_start_user_followup(_quick_key, staged_event):
                        self._mark_discord_work_consumed(
                            event,
                            reason="startup_followup",
                        )
                        await self._rollback_unused_discord_feature_summary(event)
                        return "⏩ Folded into the turn that is starting."
                    self._queue_or_replace_pending_event(_quick_key, staged_event)
                    return "Agent startup intake closed — queued for the immediate next turn."
                if running_agent and hasattr(running_agent, "steer"):
                    try:
                        accepted = running_agent.steer(steer_text)
                    except Exception as exc:
                        logger.warning("Steer failed for session %s: %s", _quick_key, exc)
                        queued_event = dataclasses.replace(
                            event,
                            text=steer_text,
                            message_type=MessageType.TEXT,
                        )
                        self._queue_or_replace_pending_event(_quick_key, queued_event)
                        return "Live steering failed — queued for the immediate next turn."
                    if accepted:
                        self._mark_discord_work_consumed(
                            event,
                            reason="accepted_steer",
                        )
                        await self._rollback_unused_discord_feature_summary(event)
                        preview = steer_text[:60] + ("..." if len(steer_text) > 60 else "")
                        return (
                            "⏩ Steered into the current run; it will apply at the "
                            f"next safe boundary: '{preview}'"
                        )
                    queued_event = dataclasses.replace(
                        event,
                        text=steer_text,
                        message_type=MessageType.TEXT,
                    )
                    self._queue_or_replace_pending_event(_quick_key, queued_event)
                    steer_state = getattr(running_agent, "steer_state", None)
                    if callable(steer_state):
                        try:
                            if steer_state() == "closed":
                                return (
                                    "Finishing delivery of the previous response — "
                                    "starting this as the next turn."
                                )
                        except Exception:
                            pass
                    return "Live steering closed — queued for the immediate next turn."
                # Running agent is missing or lacks steer() — fall back to queue.
                queued_event = dataclasses.replace(
                    event,
                    text=steer_text,
                    message_type=MessageType.TEXT,
                )
                self._queue_or_replace_pending_event(_quick_key, queued_event)
                return "No live steering support — queued for the immediate next turn."

            # /model must not be used while the agent is running.
            if _cmd_def_inner and _cmd_def_inner.name == "model":
                return "Agent is running — wait or /stop first, then switch models."

            # /codex-runtime must not be used while the agent is running.
            # Switching mid-turn would split a turn across two transports.
            if _cmd_def_inner and _cmd_def_inner.name == "codex-runtime":
                return ("Agent is running — wait or /stop first, then "
                        "change runtime.")

            # /approve and /deny must bypass the running-agent interrupt path.
            # The agent thread is blocked on a threading.Event inside
            # tools/approval.py — sending an interrupt won't unblock it.
            # Route directly to the approval handler so the event is signalled.
            if _cmd_def_inner and _cmd_def_inner.name in {"approve", "deny"}:
                if _cmd_def_inner.name == "approve":
                    return await self._handle_approve_command(event)
                return await self._handle_deny_command(event)

            # /agents (/tasks alias) should be query-only and never interrupt.
            if _cmd_def_inner and _cmd_def_inner.name == "agents":
                return await self._handle_agents_command(event)

            # /background must bypass the running-agent guard — it starts a
            # parallel task and must never interrupt the active conversation.
            # /btw is an alias of /background and resolves to the same canonical
            # name, so this branch handles both commands.
            if _cmd_def_inner and _cmd_def_inner.name == "background":
                return await self._handle_background_command(event)

            # /kanban must bypass the guard. It writes to a profile-agnostic
            # DB (kanban.db), not to the running agent's state. In fact
            # /kanban unblock is often the only way to free a worker that
            # has blocked waiting for a peer — letting that be dispatched
            # mid-run is the whole point of the board.
            if _cmd_def_inner and _cmd_def_inner.name == "kanban":
                return await self._handle_kanban_command(event)

            # /goal is safe mid-run for status/pause/clear (inspection and
            # control-plane only — doesn't interrupt the running turn).
            # Setting a new goal text mid-run is rejected with the same
            # "wait or /stop" message as /model so we don't race a second
            # continuation prompt against the current turn.
            if _cmd_def_inner and _cmd_def_inner.name == "goal":
                _goal_arg = (event.get_command_args() or "").strip().lower()
                from hermes_cli.discord_worker_roles import GOAL_CONTROL_COMMANDS

                if not _goal_arg or _goal_arg in GOAL_CONTROL_COMMANDS:
                    return await self._handle_goal_command(event)
                try:
                    from hermes_cli.discord_worker_boards import board_for_gateway_event

                    if board_for_gateway_event(event, create=True) is not None:
                        return await self._handle_goal_command(event)
                except Exception:
                    pass
                return "Agent is running — use /goal status / pause / clear mid-run, or /stop before setting a new goal."

            # /subgoal is safe mid-run — it only modifies the goal's
            # subgoals list, which the judge reads at the next turn
            # boundary. No race with the running turn.
            if _cmd_def_inner and _cmd_def_inner.name == "subgoal":
                return await self._handle_subgoal_command(event)

            # Session-level toggles that are safe to run mid-agent —
            # /yolo can unblock a pending approval prompt, /verbose cycles
            # the tool-progress display mode for the ongoing stream, and
            # /footer toggles runtime metadata on later final replies.
            # Both modify session state without needing agent interaction
            # and must not be queued (the safety net would discard them).
            # /fast and /reasoning are config-only and take effect next
            # message, so they fall through to the catch-all busy response
            # below — users should wait and set them between turns.
            if _cmd_def_inner and _cmd_def_inner.name in {"yolo", "verbose", "footer"}:
                if _cmd_def_inner.name == "yolo":
                    return await self._handle_yolo_command(event)
                if _cmd_def_inner.name == "verbose":
                    return await self._handle_verbose_command(event)
                if _cmd_def_inner.name == "footer":
                    return await self._handle_footer_command(event)

            # Gateway-handled info/control commands with dedicated
            # running-agent handlers.
            if _cmd_def_inner and _cmd_def_inner.name in _DEDICATED_HANDLERS:
                if _cmd_def_inner.name == "help":
                    return await self._handle_help_command(event)
                if _cmd_def_inner.name == "commands":
                    return await self._handle_commands_command(event)
                if _cmd_def_inner.name == "profile":
                    return await self._handle_profile_command(event)
                if _cmd_def_inner.name == "update":
                    return await self._handle_update_command(event)

            # Catch-all: any other recognized slash command reached the
            # running-agent guard. Reject gracefully rather than falling
            # through to interrupt + discard. Without this, commands
            # like /model, /reasoning, /voice, /insights, /title,
            # /resume, /retry, /undo, /compress, /usage,
            # /reload-mcp, /sethome, /reset (all registered as Discord
            # slash commands) would interrupt the agent AND get
            # silently discarded by the slash-command safety net,
            # producing a zero-char response. See #5057, #6252, #10370.
            if _cmd_def_inner:
                return (
                    f"⏳ Agent is running — `/{_cmd_def_inner.name}` can't run "
                    f"mid-turn. Wait for the current response or `/stop` first."
                )

            if _evt_cmd and _is_known_inner(_evt_cmd):
                _denied = self._check_slash_access(source, _evt_cmd)
                if _denied is not None:
                    return _denied
                handled, response = await self._dispatch_plugin_command(event, _evt_cmd)
                if handled:
                    return response

            if self._crosses_running_discord_pr_generation(_quick_key, event):
                self._queue_or_replace_pending_event(_quick_key, event)
                logger.info(
                    "Queued Discord PR-generation rollover for session %s until the active PR turn finishes",
                    _quick_key,
                )
                return "⏳ Queued for the next PR in this thread after the current turn finishes."

            if event.message_type == MessageType.PHOTO:
                logger.debug("PRIORITY photo follow-up for session %s — queueing without interrupt", _quick_key)
                adapter = self._adapter_for_source(source)
                if adapter:
                    merge_pending_message_event(adapter._pending_messages, _quick_key, event)
                return None

            _telegram_followup_grace = float(
                os.getenv("HERMES_TELEGRAM_FOLLOWUP_GRACE_SECONDS", "3.0")
            )
            _started_at = self._running_agents_ts.get(_quick_key, 0)
            if (
                self._busy_input_mode == "interrupt"
                and source.platform == Platform.TELEGRAM
                and event.message_type == MessageType.TEXT
                and _telegram_followup_grace > 0
                and _started_at
                and (time.time() - _started_at) <= _telegram_followup_grace
            ):
                logger.debug(
                    "Telegram follow-up arrived %.2fs after run start for %s — queueing without interrupt",
                    time.time() - _started_at,
                    _quick_key,
                )
                adapter = self._adapter_for_source(source)
                if adapter:
                    if self._busy_input_mode == "queue":
                        self._enqueue_fifo(_quick_key, event, adapter)
                    else:
                        merge_pending_message_event(
                            adapter._pending_messages,
                            _quick_key,
                            event,
                            merge_text=True,
                        )
                return None

            running_agent = self._running_agents.get(_quick_key)
            if running_agent is _AGENT_PENDING_SENTINEL:
                # Agent is being set up but not ready yet.
                if event.get_command() == "stop":
                    # Force-clean the sentinel so the session is unlocked.
                    self._release_running_agent_state(_quick_key)
                    logger.info("HARD STOP (pending) for session %s — sentinel cleared", _quick_key)
                    return EphemeralReply("⚡ Force-stopped. The agent was still starting — session unlocked.")
                if self._busy_input_mode in {"steer", "interrupt"}:
                    if self._stage_start_user_followup(_quick_key, event):
                        self._mark_discord_work_consumed(
                            event,
                            reason="startup_followup",
                        )
                        await self._rollback_unused_discord_feature_summary(event)
                        return None
                # Queue the message so it will be picked up after the agent starts.
                adapter = self._adapter_for_source(source)
                if adapter:
                    merge_pending_message_event(
                        adapter._pending_messages,
                        _quick_key,
                        event,
                        merge_text=True,
                    )
                return None
            if self._draining:
                if self._queue_during_drain_enabled():
                    self._record_discord_work_for_drain(event, _quick_key)
                    self._queue_or_replace_pending_event(_quick_key, event)
                if getattr(event, "work_replay", False):
                    logger.info(
                        "Suppressing priority busy acknowledgement for Discord work replay %s during drain",
                        getattr(event, "work_item_id", "") or getattr(event, "message_id", ""),
                    )
                    return None
                return (
                    f"⏳ Gateway {self._status_action_gerund()} — queued for the next turn after it comes back."
                    if self._queue_during_drain_enabled()
                    else f"⏳ Gateway is {self._status_action_gerund()} and is not accepting another turn right now."
                )
            if self._busy_input_mode == "queue":
                logger.debug("PRIORITY queue follow-up for session %s", _quick_key)
                self._queue_or_replace_pending_event(_quick_key, event)
                return None
            if self._busy_input_mode == "steer":
                steer_outcome = self._try_steer_busy_event(
                    event,
                    _quick_key,
                    running_agent=running_agent,
                )
                if steer_outcome == "accepted":
                    self._mark_discord_work_consumed(event, reason="accepted_steer")
                    await self._rollback_unused_discord_feature_summary(event)
                    logger.debug("PRIORITY steer for session %s", _quick_key)
                    if (
                        os.environ.get("HERMES_GATEWAY_BUSY_ACK_ENABLED", "true").lower() == "true"
                        and self._should_send_busy_steer_ack(_quick_key)
                        and self._busy_steer_ack_enabled_for_event(event)
                    ):
                        return "⏩ Steered into the current run; it will apply at the next safe boundary."
                    return None
                logger.debug("PRIORITY steer-fallback-to-queue for session %s", _quick_key)
                if getattr(event, "work_replay", False):
                    logger.info(
                        "Suppressing priority busy acknowledgement for Discord work replay %s",
                        getattr(event, "work_item_id", "") or getattr(event, "message_id", ""),
                    )
                    return None
                if steer_outcome == "closed":
                    return (
                        "⏳ Finishing delivery of the previous response — "
                        "starting this as the next turn."
                    )
                return "⏳ Queued for the immediate next turn — live steering was unavailable."
            # #30170 — Subagent protection (PRIORITY path). Same rationale
            # as ``_handle_active_session_busy_message``: an interrupt
            # cascades through ``_active_children`` and aborts in-flight
            # delegate_task work. Demote to queue semantics when the
            # parent is currently driving subagents so a conversational
            # follow-up doesn't destroy minutes of subagent progress.
            # /stop reaches its dedicated handler above, so the operator
            # still has a clean escape hatch.
            if self._agent_has_active_subagents(running_agent):
                logger.info(
                    "PRIORITY interrupt demoted to queue for session %s "
                    "because the running agent has active subagents (#30170)",
                    _quick_key,
                )
                self._queue_or_replace_pending_event(_quick_key, event)
                return None
            # #56391 — Compression protection (PRIORITY path). Same
            # rationale as ``_handle_active_session_busy_message``: context
            # compression is interrupt-protected (#23975), but an interrupt
            # here starts a new turn against the pre-rotation parent
            # session while the still-running compression later rotates
            # the id out from under it, forking orphaned compression
            # siblings. Demote to queue semantics so the follow-up waits
            # for the in-flight compression + rotation to land.
            if await self._session_has_compression_in_flight(_quick_key):
                logger.info(
                    "PRIORITY interrupt demoted to queue for session %s "
                    "because context compression is in flight (#56391)",
                    _quick_key,
                )
                self._queue_or_replace_pending_event(_quick_key, event)
                return None
            logger.debug("PRIORITY interrupt for session %s", _quick_key)
            _interrupt_text = event.text
            _media_urls = getattr(event, "media_urls", None) or []
            if self._pending_event_audio_paths(event):
                _interrupt_text, _ = await self._transcribe_and_echo_pending_voice(
                    event,
                    self._adapter_for_source(source),
                    source,
                    event.text or "",
                    log_context="Voice-priority-interrupt",
                )
            elif not _interrupt_text and _media_urls:
                _interrupt_text = _build_media_placeholder(event)
            running_agent.interrupt(_interrupt_text)
            # NOTE: self._pending_messages was write-only (never consumed).
            # The actual interrupt message is delivered via adapter._pending_messages
            # which is read by _run_agent. Removed to prevent unbounded growth.
            return None

        # Check for commands
        command = event.get_command()

        from hermes_cli.commands import (
            GATEWAY_KNOWN_COMMANDS,
            is_gateway_known_command,
            resolve_command as _resolve_cmd,
        )

        # Resolve aliases to canonical name so dispatch and hook names
        # don't depend on the exact alias the user typed.
        _cmd_def = _resolve_cmd(command) if command else None
        canonical = _cmd_def.name if _cmd_def else command

        # Expand alias quick commands before built-in dispatch so targets like
        # /model openai/gpt-5.5 --provider openrouter reach the /model handler.
        # Preserve built-in precedence; aliases only need early handling when
        # the typed command is not already known.
        if command and _cmd_def is None:
            if isinstance(self.config, dict):
                quick_commands = self.config.get("quick_commands", {}) or {}
            else:
                quick_commands = getattr(self.config, "quick_commands", {}) or {}
            if isinstance(quick_commands, dict) and command in quick_commands:
                qcmd = quick_commands[command]
                if qcmd.get("type") == "alias":
                    target = (qcmd.get("target") or "").strip()
                    if target:
                        target = target if target.startswith("/") else f"/{target}"
                        target_command = target.lstrip("/")
                        user_args = event.get_command_args().strip()
                        event.text = f"{target} {user_args}".strip()
                        command = target_command.split()[0] if target_command else target_command
                        _cmd_def = _resolve_cmd(command) if command else None
                        canonical = _cmd_def.name if _cmd_def else command

        # Per-platform slash command access control. Only kicks in when the
        # operator has set ``allow_admin_from`` for the source's scope (DM
        # vs group). When unset → backward-compat: every allowed user can
        # run every command. When set → non-admins can run only commands in
        # ``user_allowed_commands`` (plus the always-allowed floor: /help,
        # /whoami). Plain chat is unaffected — only slash commands gate.
        if command and canonical and is_gateway_known_command(canonical):
            _denied = self._check_slash_access(source, canonical)
            if _denied is not None:
                return _denied

        # Fire the ``command:<canonical>`` hook for any recognized slash
        # command — built-in OR plugin-registered. Handlers can return a
        # dict with ``{"decision": "deny" | "handled" | "rewrite", ...}``
        # to intercept dispatch before core handling runs. This replaces
        # the previous fire-and-forget emit(): return values are now
        # honored, but handlers that return nothing behave exactly as
        # before (telemetry-style hooks keep working).
        if command and is_gateway_known_command(canonical):
            raw_args = event.get_command_args().strip()
            hook_ctx = {
                "platform": source.platform.value if source.platform else "",
                "user_id": source.user_id,
                "command": canonical,
                "raw_command": command,
                "args": raw_args,
                "raw_args": raw_args,
            }
            try:
                hook_results = await self.hooks.emit_collect(
                    f"command:{canonical}", hook_ctx
                )
            except Exception as _hook_err:
                logger.debug(
                    "command:%s hook dispatch failed (non-fatal): %s",
                    canonical, _hook_err,
                )
                hook_results = []

            for hook_result in hook_results:
                if not isinstance(hook_result, dict):
                    continue
                decision = str(hook_result.get("decision", "")).strip().lower()
                if not decision or decision == "allow":
                    continue
                if decision == "deny":
                    message = hook_result.get("message")
                    if isinstance(message, str) and message:
                        return message
                    return f"Command `/{command}` was blocked by a hook."
                if decision == "handled":
                    message = hook_result.get("message")
                    return message if isinstance(message, str) and message else None
                if decision == "rewrite":
                    new_command = str(
                        hook_result.get("command_name", "")
                    ).strip().lstrip("/")
                    if not new_command:
                        continue
                    new_args = str(hook_result.get("raw_args", "")).strip()
                    event.text = f"/{new_command} {new_args}".strip()
                    command = event.get_command()
                    _cmd_def = _resolve_cmd(command) if command else None
                    canonical = _cmd_def.name if _cmd_def else command
                    break

        if canonical == "new":
            if await asyncio.to_thread(self._is_telegram_topic_root_lobby, source):
                return self._telegram_topic_root_new_message()
            async def _do_reset():
                return await self._handle_reset_command(event)
            return await self._maybe_confirm_destructive_slash(
                event=event,
                command="new",
                title="/new",
                detail=(
                    "This starts a fresh session and discards the current "
                    "conversation history."
                ),
                execute=_do_reset,
            )

        if canonical == "topic":
            return await self._handle_topic_command(event)

        if canonical == "fable":
            fable_result = await self._handle_fable_command(event, _quick_key)
            if fable_result is not None:
                return fable_result
            command = None
            canonical = None

        if canonical == "opus":
            opus_result = await self._handle_opus_command(event, _quick_key)
            if opus_result is not None:
                return opus_result
            command = None
            canonical = None

        if canonical == "help":
            return await self._handle_help_command(event)

        if canonical == "start":
            logger.info("Ignoring /start platform ping for session %s", _quick_key)
            return ""

        if canonical == "commands":
            return await self._handle_commands_command(event)

        if canonical == "profile":
            return await self._handle_profile_command(event)

        if canonical == "whoami":
            return await self._handle_whoami_command(event)

        if canonical == "status":
            return await self._handle_status_command(event)

        if canonical == "agents":
            return await self._handle_agents_command(event)

        if canonical == "platform":
            return await self._handle_platform_command(event)

        if canonical == "restart":
            return await self._handle_restart_command(event)

        if canonical == "stop":
            return await self._handle_stop_command(event)

        if canonical == "reasoning":
            return await self._handle_reasoning_command(event)

        if canonical == "fast":
            return await self._handle_fast_command(event)

        if canonical == "verbose":
            return await self._handle_verbose_command(event)

        if canonical == "footer":
            return await self._handle_footer_command(event)

        if canonical == "yolo":
            return await self._handle_yolo_command(event)

        if canonical == "model":
            return await self._handle_model_command(event)

        if canonical == "codex-runtime":
            return await self._handle_codex_runtime_command(event)

        if canonical == "coding-worker":
            return await self._handle_coding_worker_command(event)

        if canonical == "personality":
            return await self._handle_personality_command(event)

        if canonical == "kanban":
            return await self._handle_kanban_command(event)

        if canonical == "retry":
            return await self._handle_retry_command(event)

        if canonical == "undo":
            async def _do_undo():
                return await self._handle_undo_command(event)
            return await self._maybe_confirm_destructive_slash(
                event=event,
                command="undo",
                title="/undo",
                detail="This removes the last user/assistant exchange from history.",
                execute=_do_undo,
            )

        if canonical == "sethome":
            return await self._handle_set_home_command(event)

        if canonical == "compress":
            return await self._handle_compress_command(event)

        if canonical == "usage":
            return await self._handle_usage_command(event)

        if canonical == "insights":
            return await self._handle_insights_command(event)

        if canonical == "reload-mcp":
            return await self._handle_reload_mcp_command(event)

        if canonical == "reload-skills":
            return await self._handle_reload_skills_command(event)

        if canonical == "bundles":
            return await self._handle_bundles_command(event)

        if canonical == "approve":
            return await self._handle_approve_command(event)

        if canonical == "deny":
            return await self._handle_deny_command(event)

        if canonical == "update":
            return await self._handle_update_command(event)

        if canonical == "debug":
            return await self._handle_debug_command(event)

        if canonical == "title":
            return await self._handle_title_command(event)

        if canonical == "resume":
            return await self._handle_resume_command(event)

        if canonical == "sessions":
            return await self._handle_sessions_command(event)

        if canonical == "branch":
            return await self._handle_branch_command(event)

        if canonical == "rollback":
            return await self._handle_rollback_command(event)

        if canonical == "background":
            return await self._handle_background_command(event)

        if canonical == "queue":
            queue_payload = event.get_command_args().strip()
            if not queue_payload:
                return "Usage: /queue <prompt>"
            try:
                event.text = queue_payload
            except Exception:
                pass

        if canonical == "steer":
            # No active agent — /steer has no tool call to inject into.
            # Strip the prefix so downstream treats it as a normal user
            # message. If the payload is empty, surface the usage hint.
            steer_payload = event.get_command_args().strip()
            if not steer_payload:
                return "Usage: /steer <prompt>  (no agent is running; sending as a normal message)"
            try:
                event.text = steer_payload
            except Exception:
                pass
            # Do NOT return — fall through to _handle_message_with_agent
            # at the end of this function so the rewritten text is sent
            # to the agent as a regular user turn.

        if canonical == "goal":
            return await self._handle_goal_command(event)

        if canonical == "subgoal":
            return await self._handle_subgoal_command(event)

        if canonical == "voice":
            return await self._handle_voice_command(event)

        if self._draining:
            if self._record_discord_work_for_drain(event, _quick_key):
                return f"⏳ Gateway {self._status_action_gerund()} — queued for the next turn after it comes back."
            return f"⏳ Gateway is {self._status_action_gerund()} and is not accepting new work right now."

        # User-defined quick commands (bypass agent loop, no LLM call)
        if command:
            if isinstance(self.config, dict):
                quick_commands = self.config.get("quick_commands", {}) or {}
            else:
                quick_commands = getattr(self.config, "quick_commands", {}) or {}
            if not isinstance(quick_commands, dict):
                quick_commands = {}
            if command in quick_commands:
                # Quick commands are slash capabilities too, and ``type:
                # exec`` entries run a shell command inside the gateway
                # process. They are not registry commands, so the earlier
                # registry-only access gate cannot protect this sink.
                _denied = self._check_slash_access(source, command)
                if _denied is not None:
                    return _denied
                qcmd = quick_commands[command]
                if qcmd.get("type") == "exec":
                    exec_cmd = qcmd.get("command", "")
                    if exec_cmd:
                        try:
                            # Sanitize env to prevent credential leakage —
                            # quick commands run in the gateway process which
                            # has all API keys in os.environ.
                            from tools.environments.local import _sanitize_subprocess_env
                            sanitized_env = _sanitize_subprocess_env(os.environ.copy())
                            proc = await asyncio.create_subprocess_shell(
                                exec_cmd,
                                stdout=asyncio.subprocess.PIPE,
                                stderr=asyncio.subprocess.PIPE,
                                env=sanitized_env,
                            )
                            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
                            output = (stdout or stderr).decode().strip()
                            # Redact any remaining sensitive patterns in output
                            if output:
                                from agent.redact import redact_sensitive_text
                                output = redact_sensitive_text(output)
                            return output if output else "Command returned no output."
                        except asyncio.TimeoutError:
                            return "Quick command timed out (30s)."
                        except Exception as e:
                            return f"Quick command error: {e}"
                    else:
                        return f"Quick command '/{command}' has no command defined."
                elif qcmd.get("type") == "alias":
                    target = (qcmd.get("target") or "").strip()
                    if target:
                        target = target if target.startswith("/") else f"/{target}"
                        target_command = target.lstrip("/")
                        user_args = event.get_command_args().strip()
                        event.text = f"{target} {user_args}".strip()
                        command = target_command.split()[0] if target_command else target_command
                        # Fall through to normal command dispatch below
                    else:
                        return f"Quick command '/{command}' has no target defined."
                else:
                    return f"Quick command '/{command}' has unsupported type (supported: 'exec', 'alias')."

        # Plugin-registered slash commands
        if command:
            handled, result = await self._dispatch_plugin_command(event, command)
            if handled:
                return result

        # Skill slash commands: /skill-name loads the skill and sends to agent.
        # resolve_skill_command_key() handles the Telegram underscore/hyphen
        # round-trip so /claude_code from Telegram autocomplete still resolves
        # to the claude-code skill.
        if command:
            # Skill bundles take precedence over individual skill commands —
            # /<bundle> loads multiple skills at once. Mirrors CLI dispatch.
            _bundle_handled = False
            try:
                from agent.skill_bundles import (
                    build_bundle_invocation_message,
                    resolve_bundle_command_key,
                )
                bundle_key = resolve_bundle_command_key(command)
                if bundle_key is not None:
                    user_instruction = event.get_command_args().strip()
                    # Pass the platform explicitly: bundle skill loading
                    # bypasses get_skill_commands()' scan-time disabled
                    # filter, and the gateway serves multiple platforms in
                    # one process, so env-var platform resolution can't be
                    # trusted here. Mirrors the stacked-skill gate (#58888).
                    _bundle_plat = source.platform.value if source.platform else None
                    bundle_result = build_bundle_invocation_message(
                        bundle_key, user_instruction, task_id=_quick_key,
                        platform=_bundle_plat,
                    )
                    if bundle_result:
                        msg, _loaded, missing = bundle_result
                        event.text = msg
                        _bundle_handled = True
                        if missing:
                            logger.info(
                                "Bundle %s skipped missing skills: %s",
                                bundle_key, ", ".join(missing),
                            )
                        # Fall through to normal message processing with bundle content
            except Exception as exc:
                logger.debug("Bundle dispatch failed (non-fatal): %s", exc)

        if command and not locals().get("_bundle_handled", False):
            try:
                from agent.skill_commands import (
                    get_skill_commands,
                    build_skill_invocation_message,
                    resolve_skill_command_key,
                )
                skill_cmds = get_skill_commands()
                cmd_key = resolve_skill_command_key(command)
                if cmd_key is not None:
                    # Check per-platform disabled status before executing.
                    # get_skill_commands() only applies the *global* disabled
                    # list at scan time; per-platform overrides need checking
                    # here because the cache is process-global across platforms.
                    _skill_name = skill_cmds[cmd_key].get("name", "")
                    try:
                        # Preserve the user-visible skill command that caused
                        # this turn before event.text is replaced by the full
                        # skill payload. Post-turn gateway features (not the
                        # model) use this to apply deterministic follow-up
                        # behavior such as /meeting goal/subgoal creation.
                        event.invoked_skill_name = _skill_name
                        event.invoked_skill_command = command.replace("_", "-")
                    except Exception:
                        pass
                    _plat = source.platform.value if source.platform else None
                    if _plat and _skill_name:
                        from agent.skill_utils import get_disabled_skill_names as _get_plat_disabled
                        if _skill_name in _get_plat_disabled(platform=_plat):
                            return (
                                f"The **{_skill_name}** skill is disabled for {_plat}.\n"
                                f"Enable it with: `hermes skills config`"
                            )
                    user_instruction = event.get_command_args().strip()
                    # Stacked slash-skill invocations: `/skill-a /skill-b do
                    # XYZ` loads every leading skill (up to 5), not just the
                    # first. Inspired by Claude Code v2.1.199. Mirrors CLI.
                    try:
                        from agent.skill_commands import (
                            build_stacked_skill_invocation_message as _build_stacked,
                            split_stacked_skill_commands,
                        )
                        extra_keys, stacked_instruction = (
                            split_stacked_skill_commands(user_instruction)
                        )
                    except Exception:
                        _build_stacked = None
                        extra_keys, stacked_instruction = [], user_instruction
                    if extra_keys and _plat:
                        # split_stacked_skill_commands() only resolves that
                        # each extra token is a KNOWN skill command — like
                        # get_skill_commands() itself, it has no per-platform
                        # view. Re-check every stacked skill (not just the
                        # leading one above) against the same disabled list,
                        # or a skill an operator disabled for this platform
                        # still gets its full content loaded via the stack.
                        from agent.skill_utils import get_disabled_skill_names as _get_plat_disabled
                        _plat_disabled = _get_plat_disabled(platform=_plat)
                        _disabled_extra = [
                            skill_cmds.get(k, {}).get("name", "")
                            for k in extra_keys
                            if skill_cmds.get(k, {}).get("name", "") in _plat_disabled
                        ]
                        if _disabled_extra:
                            return (
                                f"The **{', '.join(_disabled_extra)}** skill(s) in this "
                                f"stacked invocation are disabled for {_plat}.\n"
                                f"Enable them with: `hermes skills config`"
                            )
                    if extra_keys and _build_stacked is not None:
                        stacked_result = _build_stacked(
                            [cmd_key, *extra_keys],
                            stacked_instruction,
                            task_id=_quick_key,
                        )
                        if stacked_result:
                            msg, _loaded, _missing = stacked_result
                            event.text = msg
                            # Fall through to normal message processing
                        else:
                            return f"Failed to load stacked skills for /{command}."
                    else:
                        msg = build_skill_invocation_message(
                            cmd_key, user_instruction, task_id=_quick_key
                        )
                        if msg:
                            event.text = msg
                            # Fall through to normal message processing with skill content
                else:
                    # Not an active skill — check if it's a known-but-disabled or
                    # uninstalled skill and give actionable guidance.
                    _unavail_msg = _check_unavailable_skill(command)
                    if _unavail_msg:
                        return _unavail_msg
                    # Genuinely unrecognized /command: not a built-in, not a
                    # plugin, not a skill, not a known-inactive skill. Warn
                    # the user instead of silently forwarding it to the LLM
                    # as free text (which leads to silent-failure behavior
                    # like the model inventing a delegate_task call).
                    # Normalize to hyphenated form before checking known
                    # built-ins (command may be an alias target set by the
                    # quick-command block above, so _cmd_def can be stale).
                    if command.replace("_", "-") not in GATEWAY_KNOWN_COMMANDS:
                        logger.warning(
                            "Unrecognized slash command /%s from %s — "
                            "replying with unknown-command notice",
                            command,
                            source.platform.value if source.platform else "?",
                        )
                        return (
                            f"Unknown command `/{command}`. "
                            f"Type /commands to see what's available, "
                            f"or resend without the leading slash to send "
                            f"as a regular message."
                        )
            except Exception as e:
                logger.debug("Skill command check failed (non-fatal): %s", e)

        # Pending exec approvals are handled by /approve and /deny commands above.
        # No bare text matching — "yes" in normal conversation must not trigger
        # execution of a dangerous command.

        if not command and detect_grill_me_trigger(event.text or ""):
            event = dataclasses.replace(
                event,
                text=build_grill_me_prompt(
                    event.text or "",
                    runtime_note="Gateway natural-language grill-me trigger detected.",
                ),
            )
            source = event.source

        if await asyncio.to_thread(self._is_telegram_topic_root_lobby, source):
            # Debounce the lobby reminder so a user who forgets about
            # topic mode and fires ten prompts doesn't get ten copies.
            if self._should_send_telegram_lobby_reminder(source):
                return self._telegram_topic_root_lobby_message()
            return None

        # External maintenance drains stop only NEW user work. Internal
        # completion/recovery events are part of draining existing work and
        # must still flow until their exact attempt is closed out.
        if self._external_drain_active and not is_internal:
            logger.info(
                "Refusing new turn for session %s — external drain active.",
                _quick_key,
            )
            return (
                "⏳ This agent is draining for a maintenance action and isn't "
                "accepting new turns right now. It'll be back in a moment — "
                "please resend shortly."
            )

        if self._is_stale_discord_process_completion(event, _quick_key):
            logger.info(
                "Dropping stale terminal-process completion for completed Discord work item: %s",
                getattr(event, "work_item_id", "") or "unknown",
            )
            return None

        _flow_admission_ts = time.time()
        _flow_route_type = _gateway_flow_route_type(event, command)
        _event_metadata = getattr(event, "metadata", None)
        if not isinstance(_event_metadata, dict):
            _event_metadata = {}
            event.metadata = _event_metadata
        _flow_phase_timestamps = {
            "request_ts": _event_metadata.get("discord_request_ts"),
            "adapter_dispatch_ts": _event_metadata.get("discord_adapter_dispatch_ts"),
            "intake_ts": _event_metadata.get("gateway_intake_ts"),
            "admitted_ts": _event_metadata.get("gateway_admitted_ts"),
            "agent_handler_start_ts": _event_metadata.get("gateway_agent_handler_start_ts"),
        }
        _flow_phase_durations: dict[str, Any] = {}
        _event_metadata["gateway_flow_phase_timestamps"] = _flow_phase_timestamps
        _event_metadata["gateway_flow_phase_durations"] = _flow_phase_durations
        # ── Claim this session before any await ───────────────────────
        # Between here and _run_agent registering the real AIAgent, there
        # are numerous await points (hooks, vision enrichment, STT,
        # session hygiene compression).  Without this sentinel a second
        # message arriving during any of those yields would pass the
        # "already running" guard and spin up a duplicate agent for the
        # same session — corrupting the transcript.
        active_session_lease, limit_message = self._claim_active_session_slot(
            _quick_key,
            source,
        )
        if limit_message is not None:
            logger.info(
                "Rejecting new active session %s: max_concurrent_sessions reached",
                _quick_key,
            )
            return limit_message
        if active_session_lease is not None:
            if not hasattr(self, "_active_session_leases"):
                self._active_session_leases = {}
            self._active_session_leases[_quick_key] = active_session_lease
        self._running_agents[_quick_key] = _AGENT_PENDING_SENTINEL
        self._running_agents_ts[_quick_key] = time.time()
        self._refresh_active_agent_runtime_status()
        _run_generation = self._begin_session_run_generation(_quick_key)
        if getattr(source, "platform", None) == Platform.DISCORD:
            _discord_runtime_mode = _discord_runtime_mode_for(event)
            _discord_pr_generation = self._discord_action_pr_generation(event)
            if _discord_pr_generation is None:
                _discord_pr_generation = self._ledger().discord_pr_generation(
                    _quick_key
                )
            self.__dict__.setdefault("_running_discord_pr_generations", {})[
                _quick_key
            ] = _discord_pr_generation
            self.__dict__.setdefault("_running_discord_runtime_modes", {})[
                _quick_key
            ] = _discord_runtime_mode.value
        self._open_start_user_followups(_quick_key, _run_generation)
        _work_item_id = str(getattr(event, "work_item_id", "") or "")
        if _work_item_id and getattr(source, "platform", None) == Platform.DISCORD:
            _ledger_claim_started = time.perf_counter()
            try:
                self._ledger().claim(
                    _work_item_id,
                    session_key=_quick_key,
                    run_generation=_run_generation,
                    process_epoch=self._process_epoch,
                )
            except Exception:
                logger.debug("Discord work ledger run-generation claim failed", exc_info=True)
            finally:
                _flow_phase_durations["ledger_claim_ms"] = int(
                    (time.perf_counter() - _ledger_claim_started) * 1000
                )
                _flow_phase_durations["ledger_claim_calls"] = 1

        try:
            _flow_dispatch_start_ts = time.time()
            _agent_result = await self._handle_message_with_agent(event, source, _quick_key, _run_generation)
            _fable_plan_metadata = getattr(event, "fable_plan_metadata", None)
            _opus_plan_metadata = getattr(event, "opus_plan_metadata", None)
            if (
                _fable_plan_metadata
                and isinstance(_agent_result, str)
                and not _agent_result.startswith("⚠️ /fable is pinned")
            ):
                _agent_result = MetadataReply(_agent_result, _fable_plan_metadata)
            if (
                _opus_plan_metadata
                and isinstance(_agent_result, str)
                and not _agent_result.startswith("⚠️ /opus is pinned")
            ):
                _agent_result = MetadataReply(_agent_result, _opus_plan_metadata)
            self._log_gateway_flow_telemetry(
                route_type=_flow_route_type,
                source=source,
                session_id=_quick_key,
                admission_ts=_flow_admission_ts,
                dispatch_start_ts=_flow_dispatch_start_ts,
                finished_ts=time.time(),
                phase_timestamps=_flow_phase_timestamps,
                phase_durations=_flow_phase_durations,
            )
            # Goal continuation: after the agent returns a final response
            # for this turn, check any standing /goal — the judge will
            # either mark it done, pause it (budget), or enqueue a
            # continuation prompt back through the adapter FIFO so the
            # next turn makes more progress. Wrapped in try/except so a
            # broken judge never breaks normal message handling.
            try:
                _final_text = ""
                if isinstance(_agent_result, dict):
                    _final_text = str(_agent_result.get("final_response") or "")
                elif isinstance(_agent_result, str):
                    _final_text = _agent_result
                # Skip for empty responses (interrupted / errored) — the
                # judge would almost always say "continue" and we'd loop
                # on error. Let the user drive the next turn.
                if _final_text.strip() and not getattr(event, "skip_post_turn_goal_once", False):
                    try:
                        session_entry = await self.async_session_store.get_or_create_session(source)
                    except Exception:
                        session_entry = None
                    if session_entry is not None:
                        await self._post_turn_goal_continuation(
                            session_entry=session_entry,
                            source=source,
                            final_response=_final_text,
                            runtime_breakdown=_agent_result.get("runtime_breakdown") if isinstance(_agent_result, dict) else None,
                        )
            except Exception as _goal_exc:
                logger.debug("goal continuation hook failed: %s", _goal_exc)
            return _agent_result
        finally:
            # The transcript lease is independent from the routing-key busy
            # guard. Always release this turn's exact token, including early
            # failures before _run_agent installs a real agent. Normal
            # _run_agent cleanup also releases it; the helper is idempotent.
            self._release_turn_lease(_quick_key, _run_generation)
            if getattr(event, "fable_plan_metadata", None):
                previous_override = getattr(event, "fable_previous_model_override", None)
                if previous_override is None:
                    self._session_model_overrides.pop(_quick_key, None)
                else:
                    self._session_model_overrides[_quick_key] = previous_override
                try:
                    self._evict_cached_agent(_quick_key)
                except Exception:
                    pass
            if getattr(event, "opus_plan_metadata", None):
                previous_override = getattr(event, "opus_previous_model_override", None)
                if previous_override is None:
                    self._session_model_overrides.pop(_quick_key, None)
                else:
                    self._session_model_overrides[_quick_key] = previous_override
                try:
                    self._evict_cached_agent(_quick_key)
                except Exception:
                    pass
            # If _run_agent replaced the sentinel with a real agent and
            # then cleaned it up, this is a no-op.  If we exited early
            # (exception, command fallthrough, etc.) the sentinel must
            # not linger or the session would be permanently locked out.
            if self._running_agents.get(_quick_key) is _AGENT_PENDING_SENTINEL:
                self._release_running_agent_state(_quick_key)
            elif _quick_key not in self._running_agents:
                # Agent path already cleaned _running_agents; make sure
                # the paired metadata dicts are gone too. A restored older
                # run still owns them and remains steerable.
                self._running_agents_ts.pop(_quick_key, None)
                if hasattr(self, "_busy_ack_ts"):
                    self._busy_ack_ts.pop(_quick_key, None)

    def _restore_pending_one_turn_model_override(self, session_key: str) -> None:
        """Restore a per-session model override after ``/model --once`` runs."""
        if not session_key:
            return
        try:
            snapshot = self._pending_one_turn_model_restores.pop(session_key, None)
            if not snapshot:
                return
            self._restore_session_model_override(session_key, snapshot)
        except Exception:
            logger.debug("Failed to restore one-turn model override", exc_info=True)

    async def _prepare_inbound_message_text(
        self,
        *,
        event: MessageEvent,
        source: SessionSource,
        history: List[Dict[str, Any]],
        session_key: Optional[str] = None,
    ) -> Optional[str]:
        """Prepare inbound event text for the agent.

        Keep the normal inbound path and the queued follow-up path on the same
        preprocessing pipeline so sender attribution, image enrichment, STT,
        document notes, reply context, and @ references all behave the same.

        Side effect: buffers per-session native image paths when the active
        model supports native vision AND the user has images attached. The
        caller consumes and clears that session-scoped buffer at the
        ``run_conversation`` site to build a multimodal user turn. When the
        list is empty, the ``_enrich_message_with_vision`` text path has
        already run and images are represented in-text.
        """
        history = history or []
        _pending_stt_prepared = hasattr(event, "_gateway_pending_stt_text")
        message_text = (
            getattr(event, "_gateway_pending_stt_text", None)
            if _pending_stt_prepared
            else event.text
        ) or ""
        _group_sessions_per_user = getattr(self.config, "group_sessions_per_user", True)
        _thread_sessions_per_user = getattr(self.config, "thread_sessions_per_user", False)
        # Use the same helper every other call site uses so the write key here
        # matches the consume key at the run_conversation site — even if the
        # session store overrides build_session_key's default behavior.
        session_key = session_key or self._session_key_for_source(source)
        # Reset only this session's per-call buffer; other sessions may be
        # concurrently preparing multimodal turns on the same runner.
        self._consume_pending_native_image_paths(session_key)

        _is_shared_multi_user = is_shared_multi_user_session(
            source,
            group_sessions_per_user=_group_sessions_per_user,
            thread_sessions_per_user=_thread_sessions_per_user,
        )
        if _is_shared_multi_user and source.user_name:
            # source.user_name is the platform display name — attacker-
            # influenceable on any platform that lets participants set their
            # own name. Neutralize embedded newlines/control chars before
            # interpolating it into every message in the shared session, or
            # a hostile name can masquerade as a fake markdown section
            # (mirrors the same field's treatment in
            # build_session_context_prompt via _format_untrusted_prompt_value).
            _safe_user_name = neutralize_untrusted_inline_text(source.user_name)
            message_text = f"[{_safe_user_name}] {message_text}"

        # Prepend channel context from history backfill (if any).  This
        # happens after sender-prefix so the prefix only applies to the
        # trigger message, not the backfill block.
        if getattr(event, "channel_context", None):
            message_text = f"{event.channel_context}\n\n[New message]\n{message_text}"

        # Declare at outer scope so the audio-file-paths handling block below
        # remains safe when ``event.media_urls`` is empty (no inner block runs).
        audio_file_paths: list[str] = []
        video_paths: list[str] = []

        if event.media_urls:
            image_paths = []
            audio_paths = []
            for i, path in enumerate(event.media_urls):
                mtype = event.media_types[i] if i < len(event.media_types) else ""
                if _event_media_is_image(event, i):
                    image_paths.append(path)
                # MessageType.AUDIO = audio file attachment (e.g. .mp3, .m4a) — never STT
                # MessageType.VOICE = voice message (Opus/OGG) — always STT
                if event.message_type == MessageType.AUDIO:
                    audio_file_paths.append(path)
                elif not _pending_stt_prepared and _event_media_is_stt_input(event, i):
                    audio_paths.append(path)
                if mtype.startswith("video/") or (
                    not mtype and event.message_type == MessageType.VIDEO
                ):
                    video_paths.append(path)

            if image_paths:
                # Decide routing: native (attach pixels) vs text (vision_analyze
                # pre-run + prepend description).  See agent/image_routing.py.
                _img_mode = await asyncio.to_thread(
                    self._decide_image_input_mode,
                    source=source,
                    session_key=session_key,
                )
                if _img_mode == "native":
                    # Defer attachment to the run_conversation call site.
                    pending_native = getattr(self, "_pending_native_image_paths_by_session", None)
                    if pending_native is None:
                        pending_native = {}
                        self._pending_native_image_paths_by_session = pending_native
                    pending_native[session_key] = list(image_paths)
                    logger.info(
                        "Image routing: native (model supports vision). %d image(s) will be attached inline.",
                        len(image_paths),
                    )
                else:
                    logger.info(
                        "Image routing: text (mode=%s). Pre-analyzing %d image(s) via vision_analyze.",
                        _img_mode, len(image_paths),
                    )
                    # Vision enrichment runs before AIAgent.run_conversation(),
                    # so bind this session's resolved runtime explicitly rather
                    # than consulting process-global compatibility mirrors.
                    vision_runtime = None
                    try:
                        turn_model, runtime_kwargs = self._resolve_session_agent_runtime(
                            source=source,
                            session_key=session_key,
                        )
                        vision_runtime = dict(runtime_kwargs or {})
                        vision_runtime["model"] = turn_model
                    except Exception:
                        logger.debug(
                            "vision enrichment: session runtime resolution failed",
                            exc_info=True,
                        )

                    from agent.auxiliary_client import scoped_runtime_main

                    with scoped_runtime_main(vision_runtime):
                        message_text = await self._enrich_message_with_vision(
                            message_text,
                            image_paths,
                        )

            if audio_paths:
                audio_context_note = None
                if (
                    source.platform == Platform.DISCORD
                    and event.message_type in {MessageType.VOICE, MessageType.AUDIO}
                ):
                    audio_context_note = (
                        "Treat this transcript as a Discord voice note from "
                        "the sender/intermediary, not as a client document."
                    )
                message_text, successful_transcripts = await self._enrich_message_with_transcription(
                    message_text,
                    audio_paths,
                    context_note=audio_context_note,
                )
                if successful_transcripts and self._should_echo_stt_transcripts():
                    echo_adapter = self._adapter_for_source(source)
                    echo_metadata = self._thread_metadata_for_source(
                        source,
                        self._reply_anchor_for_event(event),
                    )
                    if echo_adapter:
                        for transcript in successful_transcripts:
                            try:
                                await echo_adapter.send(
                                    source.chat_id,
                                    f'🎙️ "{transcript}"',
                                    metadata=echo_metadata,
                                )
                            except Exception as exc:
                                logger.debug("Transcript echo failed (non-fatal): %s", exc)
                _stt_fail_markers = (
                    "No STT provider",
                    "STT is disabled",
                    "can't listen",
                    "VOICE_TOOLS_OPENAI_KEY",
                )
                if any(marker in message_text for marker in _stt_fail_markers):
                    _stt_adapter = self._adapter_for_source(source)
                    _stt_meta = self._thread_metadata_for_source(source, self._reply_anchor_for_event(event))
                    if _stt_adapter:
                        try:
                            _stt_msg = (
                                "🎤 I received your voice message but can't transcribe it — "
                                "no speech-to-text provider is configured.\n\n"
                                "To enable voice: install faster-whisper "
                                "(`uv pip install faster-whisper` in the Hermes venv; "
                                "`pip install faster-whisper` also works if pip is on PATH) "
                                "and set `stt.enabled: true` in config.yaml, "
                                "then /restart the gateway."
                            )
                            if self._has_setup_skill():
                                _stt_msg += "\n\nFor full setup instructions, type: `/skill hermes-agent-setup`"
                            await _stt_adapter.send(
                                source.chat_id,
                                _stt_msg,
                                metadata=_stt_meta,
                            )
                        except Exception:
                            pass

        if audio_file_paths:
            from tools.credential_files import to_agent_visible_cache_path as _to_agent_path
            for _apath in audio_file_paths:
                _basename = os.path.basename(_apath)
                _parts = _basename.split("_", 2)
                _display = _parts[2] if len(_parts) >= 3 else _basename
                _display = re.sub(r'[^\w.\- ]', '_', _display)
                _agent_path = _to_agent_path(_apath)
                _note = (
                    f"[The user sent an audio file attachment: '{_display}'. "
                    f"It is saved at: {_agent_path}. "
                    f"Ask the user what they'd like you to do with it, or pass the path to a transcription or media tool.]"
                )
                message_text = f"{_note}\n\n{message_text}"

        if video_paths:
            from tools.credential_files import to_agent_visible_cache_path as _to_agent_path
            for _vpath in video_paths:
                _basename = os.path.basename(_vpath)
                _parts = _basename.split("_", 2)
                _display = _parts[2] if len(_parts) >= 3 else _basename
                _display = re.sub(r'[^\w.\- ]', '_', _display)
                _agent_path = _to_agent_path(_vpath)
                _note = (
                    f"[The user sent a video attachment: '{_display}'. "
                    f"It is saved at: {_agent_path}. "
                    "Its content is not inlined here. If the user's request involves "
                    "what the video contains, inspect or process it yourself — for "
                    "example by passing the path to a video analysis or media tool — "
                    "instead of asking the user to describe it. Only ask what to do "
                    "with it if their intent is genuinely unclear.]"
                )
                message_text = f"{_note}\n\n{message_text}"

        if event.media_urls and event.message_type == MessageType.DOCUMENT:
            import mimetypes as _mimetypes
            from tools.credential_files import to_agent_visible_cache_path

            _TEXT_EXTENSIONS = {".txt", ".md", ".csv", ".log", ".json", ".xml", ".yaml", ".yml", ".toml", ".ini", ".cfg"}
            for i, path in enumerate(event.media_urls):
                mtype = event.media_types[i] if i < len(event.media_types) else ""
                _ext = os.path.splitext(path)[1].lower()
                if mtype in {"", "application/octet-stream"}:
                    if _ext in _TEXT_EXTENSIONS:
                        mtype = "text/plain"
                    else:
                        guessed, _ = _mimetypes.guess_type(path)
                        if guessed:
                            mtype = guessed
                if not mtype.startswith(("application/", "text/")):
                    continue

                if (
                    getattr(event, "text_document_inlined", False)
                    and _ext == ".txt"
                    and mtype.startswith("text/")
                ):
                    # The platform adapter already decoded the .txt body into
                    # event.text in user-message order.  Do not prepend a path
                    # note here; uploaded .txt should be replaceable with the
                    # same text pasted directly by the user.
                    continue

                basename = os.path.basename(path)
                parts = basename.split("_", 2)
                display_name = parts[2] if len(parts) >= 3 else basename
                display_name = re.sub(r'[^\w.\- ]', '_', display_name)

                # Translate host cache path to in-container path if running under Docker backend.
                # This ensures the agent receives a path it can open inside its sandbox, as the
                # cache directories are auto-mounted at /root/.hermes/cache/* by get_cache_directory_mounts().
                agent_path = to_agent_visible_cache_path(path)

                if mtype.startswith("text/"):
                    context_note = (
                        f"[The user sent a text document: '{display_name}'. "
                        f"Its content has been included below. "
                        f"The file is also saved at: {agent_path}]"
                    )
                else:
                    context_note = (
                        f"[The user sent a document: '{display_name}'. "
                        f"The file is saved at: {agent_path}. "
                        f"Ask the user what they'd like you to do with it.]"
                    )
                message_text = f"{context_note}\n\n{message_text}"

        if getattr(event, "reply_to_text", None) and event.reply_to_message_id:
            matched_previous, previous_role = _reply_target_matches_previous_history_message(
                history,
                event.reply_to_text,
            )
            if matched_previous:
                message_text = f"[Replying to previous {previous_role} message]\n\n{message_text}"
            else:
                reply_snippet = event.reply_to_text[:500]
                if getattr(event, "reply_to_is_own_message", False):
                    message_text = (
                        f'[Replying to your previous message: "{reply_snippet}"]\n\n'
                        f"{message_text}"
                    )
                else:
                    message_text = f'[Replying to: "{reply_snippet}"]\n\n{message_text}'

        if "@" in message_text:
            try:
                from agent.context_references import preprocess_context_references_async
                from agent.model_metadata import get_model_context_length_async

                from gateway.session_context import get_session_env

                _msg_cwd = (
                    get_session_env("HERMES_SESSION_CWD", "")
                    or os.environ.get("TERMINAL_CWD", os.path.expanduser("~"))
                )
                _msg_config_ctx = None
                _msg_cfg = None
                _msg_model_cfg = {}
                _msg_custom_providers = []
                try:
                    _msg_cfg = _load_gateway_config()
                    _msg_model_cfg = _msg_cfg.get("model", {})
                    if isinstance(_msg_model_cfg, dict):
                        _msg_raw_ctx = _msg_model_cfg.get("context_length")
                        if _msg_raw_ctx is not None:
                            _msg_config_ctx = int(_msg_raw_ctx)
                    try:
                        from hermes_cli.config import get_compatible_custom_providers

                        _msg_custom_providers = get_compatible_custom_providers(_msg_cfg)
                    except Exception:
                        _msg_custom_providers = _msg_cfg.get("custom_providers") or []
                except Exception:
                    pass
                _msg_model, _msg_runtime = self._resolve_session_agent_runtime(
                    source=source,
                    session_key=session_key,
                    user_config=_msg_cfg,
                )
                _msg_base_url = _msg_runtime.get("base_url") or ""
                if isinstance(_msg_model_cfg, dict):
                    _msg_configured_model = (
                        _msg_model_cfg.get("default") or _msg_model_cfg.get("model")
                    )
                else:
                    _msg_configured_model = _msg_model_cfg
                if _msg_model != _msg_configured_model:
                    _msg_config_ctx = None
                if _msg_custom_providers and _msg_base_url:
                    try:
                        from hermes_cli.config import get_custom_provider_context_length

                        _msg_custom_ctx = get_custom_provider_context_length(
                            model=_msg_model,
                            base_url=_msg_base_url,
                            custom_providers=_msg_custom_providers,
                        )
                        if _msg_custom_ctx:
                            _msg_config_ctx = _msg_custom_ctx
                    except Exception:
                        pass
                _msg_ctx_len = await get_model_context_length_async(
                    _msg_model,
                    base_url=_msg_base_url,
                    api_key=_msg_runtime.get("api_key") or "",
                    config_context_length=_msg_config_ctx,
                    provider=_msg_runtime.get("provider") or "",
                    custom_providers=_msg_custom_providers,
                )
                _ctx_result = await preprocess_context_references_async(
                    message_text,
                    cwd=_msg_cwd,
                    context_length=_msg_ctx_len,
                    allowed_root=_msg_cwd,
                )
                if _ctx_result.blocked:
                    _adapter = self._adapter_for_source(source)
                    if _adapter:
                        await _adapter.send(
                            source.chat_id,
                            "\n".join(_ctx_result.warnings) or "Context injection refused.",
                        )
                    return None
                if _ctx_result.expanded:
                    message_text = _ctx_result.message
            except Exception as exc:
                logger.warning("@ context reference expansion failed: %s", exc)
                logger.debug("@ context reference expansion failure detail", exc_info=True)

        return message_text

    async def _prepare_profile_scoped_inbound_message_text(
        self,
        *,
        event: MessageEvent,
        source: SessionSource,
        history: List[Dict[str, Any]],
        session_key: Optional[str] = None,
    ) -> Optional[str]:
        """Run inbound preprocessing under the routed profile when multiplexed."""
        if getattr(getattr(self, "config", None), "multiplex_profiles", False):
            with _profile_runtime_scope(self._resolve_profile_home_for_source(source)):
                return await self._prepare_inbound_message_text(
                    event=event,
                    source=source,
                    history=history,
                    session_key=session_key,
                )
        return await self._prepare_inbound_message_text(
            event=event,
            source=source,
            history=history,
            session_key=session_key,
        )

    def _consume_pending_native_image_paths(self, session_key: str) -> List[str]:
        pending_native = getattr(self, "_pending_native_image_paths_by_session", None)
        if not pending_native:
            return []
        return list(pending_native.pop(session_key, []) or [])

    def _cache_session_source(self, session_key: str, source) -> None:
        if not session_key or source is None:
            return
        cached_sources = getattr(self, "_session_sources", None)
        if cached_sources is None:
            cached_sources = OrderedDict()
            self._session_sources = cached_sources
        try:
            cached_sources[session_key] = dataclasses.replace(source)
        except Exception:
            logger.debug("Failed to cache live session source for %s", session_key, exc_info=True)
            return
        # LRU: mark as most-recently-used and trim to max size.
        try:
            cached_sources.move_to_end(session_key)
            max_size = getattr(self, "_session_sources_max", 512)
            while len(cached_sources) > max_size:
                cached_sources.popitem(last=False)
        except Exception:
            pass

    @property
    def async_session_store(self) -> AsyncSessionStore:
        """Return the single async facade for this runner's SessionStore."""
        facade = getattr(self, "_async_session_store", None)
        if facade is None or facade._store is not self.session_store:
            facade = AsyncSessionStore(self.session_store)
            self._async_session_store = facade
        return facade

    def _get_cached_session_source(self, session_key: str):
        if not session_key:
            return None
        cached_sources = getattr(self, "_session_sources", None)
        if not cached_sources:
            return None
        source = cached_sources.get(session_key)
        if source is not None:
            try:
                cached_sources.move_to_end(session_key)
            except Exception:
                pass
        return source

    async def _handle_message_with_agent(self, event, source, _quick_key: str, run_generation: int):
        """Inner handler that runs under the _running_agents sentinel guard."""
        _msg_start_time = time.time()
        _platform_name = source.platform.value if hasattr(source.platform, "value") else str(source.platform)
        _msg_preview = (event.text or "")[:80].replace("\n", " ")
        logger.info(
            "inbound message: platform=%s user=%s chat=%s msg=%r",
            _platform_name, source.user_name or source.user_id or "unknown",
            source.chat_id or "unknown", _msg_preview,
        )

        # Get or create session
        # Topic-mode DMs: rewrite a stale/foreign thread_id to the user's
        # last-active topic so a cross-topic Reply or stripped plain reply
        # doesn't fragment the conversation across sessions.
        recovered = await asyncio.to_thread(self._recover_telegram_topic_thread_id, source)
        if recovered is not None:
            logger.info(
                "telegram topic recovery: chat=%s user=%s %r -> %s",
                source.chat_id, source.user_id, source.thread_id, recovered,
            )
            source = dataclasses.replace(source, thread_id=recovered)
            try:
                event.source = source
            except Exception:
                pass

        session_entry = await self.async_session_store.get_or_create_session(source)
        session_key = session_entry.session_key
        turn_sidecar_notes: List[str] = []
        _background_completion_id = str(
            getattr(event, "background_completion_id", "") or ""
        )
        self._cache_session_source(session_key, source)
        if await asyncio.to_thread(self._is_telegram_topic_lane, source):
            try:
                binding = await self._session_db.get_telegram_topic_binding(
                    chat_id=str(source.chat_id),
                    thread_id=str(source.thread_id),
                ) if self._session_db else None
            except Exception:
                logger.debug("Failed to read Telegram topic binding", exc_info=True)
                binding = None
            if binding:
                bound_session_id = str(binding.get("session_id") or "")
                # Heal bindings that point at a pre-compression parent: walk
                # the compression-continuation chain forward to its tip so the
                # next message resumes the compressed child instead of
                # reloading the oversized parent transcript (#20470/#29712/
                # #33414). Returns the input unchanged when the session isn't
                # a compression parent, so this is cheap and safe.
                if bound_session_id and self._session_db is not None:
                    try:
                        canonical_session_id = await self._session_db.get_compression_tip(
                            bound_session_id,
                        )
                    except Exception:
                        logger.debug(
                            "compression-tip lookup failed for %s",
                            bound_session_id, exc_info=True,
                        )
                        canonical_session_id = bound_session_id
                    if (
                        canonical_session_id
                        and canonical_session_id != bound_session_id
                    ):
                        bound_session_id = canonical_session_id
                if bound_session_id and bound_session_id != session_entry.session_id:
                    # Route the override through SessionStore so the session_key
                    # → session_id mapping is persisted to disk and the previous
                    # lane session is ended cleanly. Mutating session_entry in
                    # place here created a split-brain state where the JSON
                    # index pointed at one id but code downstream used another.
                    switched = await self.async_session_store.switch_session(session_key, bound_session_id)
                    if switched is not None:
                        session_entry = switched
                # If the stored binding pointed at a parent, rewrite it to the
                # canonical descendant now that we've followed the chain.
                if (
                    bound_session_id
                    and bound_session_id != str(binding.get("session_id") or "")
                ):
                    await asyncio.to_thread(self._sync_telegram_topic_binding, source, session_entry, reason="compression-tip-walk")
            else:
                try:
                    await asyncio.to_thread(self._record_telegram_topic_binding, source, session_entry)
                except Exception:
                    logger.debug("Failed to record Telegram topic binding", exc_info=True)
        # Capture and immediately consume was_auto_reset so it does not
        # re-fire on subsequent messages and wipe overrides set between turns.
        _was_auto_reset = getattr(session_entry, "was_auto_reset", False)
        if _was_auto_reset:
            # Treat auto-reset as a full conversation boundary. One funnel call
            # clears every conversation-scoped per-session dict, including the
            # resolved-model cache and queued model notes.
            self._clear_conversation_scope(session_key, reason="auto_reset")
            # The agent cache is keyed by the stable session_key, so explicitly
            # evict it to prevent the previous conversation's compression summary
            # from leaking into the fresh session.
            self._evict_cached_agent(session_key)
            session_entry.was_auto_reset = False

        # Emit session:start for new or auto-reset sessions
        _is_new_session = (
            session_entry.created_at == session_entry.updated_at
            or _was_auto_reset
            or getattr(session_entry, "is_fresh_reset", False)
        )
        # Consume the is_fresh_reset flag immediately so it doesn't leak
        # onto subsequent messages in the same session (issue #6508).
        if getattr(session_entry, "is_fresh_reset", False):
            session_entry.is_fresh_reset = False
        if _is_new_session:
            await self.hooks.emit("session:start", {
                "platform": source.platform.value if source.platform else "",
                "user_id": source.user_id,
                "session_id": session_entry.session_id,
                "session_key": session_key,
            })

        await self._refresh_discord_running_summary_artifacts(
            source=source,
            feature_summary=getattr(event, "feature_summary", None),
            session_id=session_entry.session_id,
        )

        _pcfg = {}
        _redact_pii = False
        try:
            _pcfg = _load_gateway_config()
            _redact_pii = bool((_pcfg.get("privacy") or {}).get("redact_pii", False))
        except Exception:
            pass

        default_kanban_intake = self._mark_discord_default_kanban_intake_context(
            event,
            source,
            _pcfg,
        )

        # Plan-only Fable/Opus turns retain the mapped canonical checkout for
        # inspection. Premium implementation turns must receive the same
        # per-thread mutable worktree as ordinary Discord action requests.
        # Normally the command handler has already provisioned it so its
        # prompt names the effective workdir; keep this branch as a robust
        # fallback for callers that inject Fable metadata directly.
        _fable_turn_metadata = getattr(event, "fable_plan_metadata", None)
        _opus_turn_metadata = getattr(event, "opus_plan_metadata", None)
        _fable_implementation_turn = bool(
            isinstance(_fable_turn_metadata, dict)
            and str(_fable_turn_metadata.get("fable_mode") or "").strip().lower()
            == "implementation"
        )
        _opus_implementation_turn = bool(
            isinstance(_opus_turn_metadata, dict)
            and str(_opus_turn_metadata.get("opus_mode") or "").strip().lower()
            == "implementation"
        )
        _premium_implementation_turn = (
            _fable_implementation_turn or _opus_implementation_turn
        )
        _premium_plan_turn = bool(
            (_fable_turn_metadata or _opus_turn_metadata)
            and not _premium_implementation_turn
        )
        _premium_closeout_source = (
            "opus" if _opus_implementation_turn else "fable"
            if _fable_implementation_turn else "direct"
        )
        action_preflight_prompt = ""
        discord_runtime_mode = (
            RuntimeMode.ACTION
            if _premium_implementation_turn
            else _discord_runtime_mode_for(event)
            if source.platform == Platform.DISCORD
            else RuntimeMode.ACTION
        )
        if _premium_plan_turn:
            session_cwd = _resolve_gateway_session_cwd(source, _pcfg)
            session_cwd_error = None
            action_worktree_cwd = None
        else:
            session_cwd, session_cwd_error, action_worktree_cwd = await asyncio.to_thread(
                _resolve_gateway_turn_cwd,
                source,
                getattr(event, "feature_summary", None),
                _pcfg,
                session_key,
                discord_runtime_mode,
                getattr(event, "discord_pr_generation", 1),
            )
        if session_cwd_error:
            logger.error(
                "Discord action-request worktree preparation failed for session %s: %s",
                session_key,
                session_cwd_error,
            )
            return (
                "⚠️ I could not start this Discord action request safely in a mutable "
                f"Git worktree. {session_cwd_error} The protected canonical checkout "
                "was not used as the agent working directory."
            )
        if action_worktree_cwd:
            if discord_runtime_mode is RuntimeMode.ACTION:
                repository = _gateway_repository_for_source(
                    source,
                    workspace_path=action_worktree_cwd,
                )
                if not repository:
                    try:
                        from hermes_cli.github_remote import github_origin_repo

                        repository = str(github_origin_repo(action_worktree_cwd) or "")
                    except Exception:
                        repository = ""
                visual_requirement = getattr(event, "visual_qa_requirement", None)
                direct_mode, direct_policy = _gateway_action_closeout_contract(
                    _pcfg,
                    repository=repository,
                    request=_gateway_action_request_text(event),
                    source=_premium_closeout_source,
                    visual_requirement=visual_requirement,
                    visual_config=getattr(event, "visual_qa_config", None),
                )
                self._persist_action_closeout_workspace(
                    event,
                    mutable_path=action_worktree_cwd,
                    canonical_path=str(source.project_path or ""),
                    config=_pcfg,
                    source=_premium_closeout_source,
                    mode=direct_mode,
                    policy=direct_policy,
                )
            # The Discord mapping remains canonical in its DB/adapter state,
            # but this turn's injected project context must name the worktree.
            # Otherwise the system prompt explicitly tells lower-tier models to
            # cd back to source.project_path, defeating the safe session CWD.
            source = dataclasses.replace(source, project_path=action_worktree_cwd)
            try:
                event.source = source
            except Exception:
                pass
            self._cache_session_source(session_key, source)
            if discord_runtime_mode is RuntimeMode.ACTION:
                action_preflight_prompt = await asyncio.to_thread(
                    _discord_action_worktree_preflight_prompt,
                    action_worktree_cwd,
                )

        # Build session context
        context = build_session_context(source, self.config, session_entry)

        # Set session context variables for tools (task-local, concurrency-safe).
        _set_env = self._set_session_env
        try:
            _set_env_sig = inspect.signature(_set_env)
            _set_env_kwargs = {}
            if "session_cwd" in _set_env_sig.parameters:
                _set_env_kwargs["session_cwd"] = session_cwd
            if "discord_action_escalation_allowed" in _set_env_sig.parameters:
                _set_env_kwargs["discord_action_escalation_allowed"] = bool(
                    source.platform == Platform.DISCORD
                    and discord_runtime_mode is RuntimeMode.READ_ONLY
                )
            if "trusted_discord_work_item_id" in _set_env_sig.parameters:
                _set_env_kwargs["trusted_discord_work_item_id"] = (
                    self._trusted_discord_work_item_id_for_turn(
                        event, source, discord_runtime_mode
                    )
                )
            # Some focused tests replace _set_session_env with a minimal
            # one-arg stub; only pass kwargs its signature accepts.
            _session_env_tokens = _set_env(context, **_set_env_kwargs)
        except (TypeError, ValueError):
            _session_env_tokens = _set_env(context, session_cwd=session_cwd)

        # Build the context prompt to inject. Reuse the pinned bytes while the
        # exact renderer inputs are unchanged so the system-prompt/cache prefix
        # remains stable across turns.
        context_prompt = self._pinned_session_context_prompt(
            context, _redact_pii, session_key
        )
        if action_preflight_prompt:
            context_prompt = f"{context_prompt}\n\n{action_preflight_prompt}".strip()
        if default_kanban_intake:
            context_prompt = (
                context_prompt
                + "\n\n"
                + self._discord_default_kanban_intake_prompt(source)
            ).strip()
        if source.platform == Platform.DISCORD:
            try:
                pr_generation = max(
                    1,
                    int(getattr(event, "discord_pr_generation", 1)),
                )
            except (TypeError, ValueError, OverflowError):
                pr_generation = 1
            if pr_generation > 1:
                rollover_prompt = (
                    f"Discord PR generation: {pr_generation}. Earlier PRs in this "
                    "thread are immutable and already merged. Use only the current "
                    "workspace and branch for this generation. Publish a new PR and "
                    "Vercel preview; never amend, reopen, or push to an earlier PR branch."
                )
                if getattr(event, "discord_pr_rollover", False):
                    rollover_prompt += (
                        " In the first visible progress update, tell the user that this "
                        "follow-up is starting a new PR in the same thread."
                    )
                context_prompt = f"{context_prompt}\n\n{rollover_prompt}".strip()

        # If the previous session expired and was auto-reset, prepend a notice
        # so the agent knows this is a fresh conversation (not an intentional /reset).
        if _was_auto_reset:
            reset_reason = getattr(session_entry, 'auto_reset_reason', None) or 'idle'
            if reset_reason == "suspended":
                context_note = "[System note: The user's previous session was stopped and suspended. This is a fresh conversation with no prior context.]"
            elif reset_reason == "daily":
                context_note = "[System note: The user's session was automatically reset by the daily schedule. This is a fresh conversation with no prior context.]"
            elif reset_reason == "resume_pending_expired":
                context_note = "[System note: The previous gateway session could not be recovered after a restart (API recovery timed out). This is a fresh conversation — use /resume to restore history if needed.]"
            else:
                context_note = "[System note: The user's previous session expired due to inactivity. This is a fresh conversation with no prior context.]"
            turn_sidecar_notes.append(context_note)

            # Send a user-facing notification explaining the reset, unless:
            # - notifications are disabled in config
            # - the platform is excluded (e.g. api_server, webhook)
            # - the expired session had no activity (nothing was cleared)
            try:
                policy = self.session_store.config.get_reset_policy(
                    platform=source.platform,
                    session_type=getattr(source, 'chat_type', 'dm'),
                )
                platform_name = source.platform.value if source.platform else ""
                had_activity = getattr(session_entry, 'reset_had_activity', False)
                # Suspended and restart-recovery-expired sessions always notify
                # regardless of policy.notify — the user had an active session
                # that was silently replaced, so they need to know they can
                # /resume it.  Idle/daily resets respect the policy flag.
                should_notify = reset_reason in {"suspended", "resume_pending_expired"} or (
                    policy.notify
                    and had_activity
                    and platform_name not in policy.notify_exclude_platforms
                )
                if should_notify:
                    adapter = self._adapter_for_source(source)
                    if adapter:
                        if reset_reason == "suspended":
                            reason_text = "previous session was stopped or interrupted"
                        elif reset_reason == "resume_pending_expired":
                            reason_text = "gateway restart recovery timed out"
                        elif reset_reason == "daily":
                            reason_text = f"daily schedule at {policy.at_hour}:00"
                        else:
                            hours = policy.idle_minutes // 60
                            mins = policy.idle_minutes % 60
                            duration = f"{hours}h" if not mins else f"{hours}h {mins}m" if hours else f"{mins}m"
                            reason_text = f"inactive for {duration}"
                        notice = (
                            f"◐ Session automatically reset ({reason_text}). "
                            f"Conversation history cleared.\n"
                            f"Use /resume to browse and restore a previous session.\n"
                            f"Adjust reset timing in config.yaml under session_reset."
                        )
                        try:
                            session_info = await asyncio.to_thread(
                                self._reset_notice_session_info, source
                            )
                            if session_info:
                                notice = f"{notice}\n\n{session_info}"
                        except Exception:
                            pass
                        await adapter.send(
                            source.chat_id, notice,
                            metadata=self._thread_metadata_for_source(source),
                        )
            except Exception as e:
                logger.debug("Auto-reset notification failed (non-fatal): %s", e)

            # was_auto_reset was consumed in the cleanup block above; only the
            # user-facing reason remains to be cleared here.
            session_entry.auto_reset_reason = None

        # Auto-load skill(s) for topic/channel bindings (Telegram DM Topics,
        # Discord channel_skill_bindings).  Supports a single name or ordered list.
        # Only inject on NEW sessions — ongoing conversations already have the
        # skill content in their conversation history from the first message.
        _auto = getattr(event, "auto_skill", None)
        if _is_new_session and _auto:
            _skill_names = [_auto] if isinstance(_auto, str) else list(_auto)
            try:
                from agent.skill_commands import build_automatic_skills_message

                _auto_msg, _loaded_names, _missing_names = build_automatic_skills_message(
                    _skill_names,
                    user_text=event.text,
                    task_id=_quick_key,
                    source_label="gateway channel/topic binding",
                )
                for _sname in _missing_names:
                    logger.warning("[Gateway] Auto-skill '%s' not found", _sname)
                if _auto_msg:
                    event.text = _auto_msg
                    logger.info(
                        "[Gateway] Auto-loaded skill(s) %s for session %s",
                        _loaded_names, session_key,
                    )
            except Exception as e:
                logger.warning("[Gateway] Failed to auto-load skill(s) %s: %s", _skill_names, e)

        # ── Turn lease (#64934) ────────────────────────────────────────
        # Session resolution is FINAL here (get_or_create → async-delegation
        # pinning → topic tip-walk switch_session are all above). Serialize
        # the [load history → run → flush] region per resolved SESSION_ID:
        # when a second routing key is mapped to this same session_id, its
        # turn waits here for the previous turn's flush instead of loading a
        # stale history base and interleaving transcript writes. Same-key
        # messages never reach this point mid-turn (adapter + runner guards
        # hold them), so the lock is uncontended outside the alias-key route.
        # Fail-open: on timeout the token comes back degraded and the turn
        # proceeds unserialized (never a wedged session). Released in
        # _handle_message's finally via _release_turn_lease — granted per
        # (routing key, run generation) so a stale unwind can't release a
        # newer turn's lease.
        _lease_registry = getattr(self, "_turn_leases", None)
        if _lease_registry is not None:
            _lease_token = await _lease_registry.acquire(
                session_entry.session_id,
                owner_key=_quick_key,
                generation=run_generation,
                timeout=_float_env("HERMES_AGENT_TIMEOUT", 3600),
            )
            if _lease_token is not None:
                if not hasattr(self, "_turn_lease_tokens"):
                    self._turn_lease_tokens = {}
                self._turn_lease_tokens[(_quick_key, run_generation)] = _lease_token

        # Load conversation history from transcript
        history = await self.async_session_store.load_transcript(session_entry.session_id)

        # -----------------------------------------------------------------
        # Session hygiene: auto-compress pathologically large transcripts
        #
        # Long-lived gateway sessions can accumulate enough history that
        # every new message rehydrates an oversized transcript, causing
        # repeated truncation/context failures.  Detect this early and
        # compress proactively — before the agent even starts.  (#628)
        #
        # Token source priority:
        # 1. Actual API-reported prompt_tokens from the last turn
        #    (stored in session_entry.last_prompt_tokens)
        # 2. Rough char-based estimate (str(msg)//4). Overestimates
        #    by 30-50% on code/JSON-heavy sessions, but that just
        #    means hygiene fires a bit early — safe and harmless.
        # -----------------------------------------------------------------
        # Read-only Discord turns use a bounded API-only replay below. Running
        # durable session hygiene first would defeat that latency/cost bound and
        # could rewrite or rotate the stored transcript before an observational
        # turn. Action turns and every non-Discord surface retain the existing
        # hygiene behavior.
        _skip_hygiene_for_read_only_discord = bool(
            source.platform == Platform.DISCORD
            and discord_runtime_mode is RuntimeMode.READ_ONLY
        )
        if history and len(history) >= 4 and not _skip_hygiene_for_read_only_discord:
            from agent.model_metadata import (
                estimate_messages_tokens_rough,
                get_model_context_length,
            )

            # Read model + compression config from config.yaml.
            # NOTE: hygiene threshold is intentionally HIGHER than the agent's
            # own compressor (0.85 vs 0.50).  Hygiene is a safety net for
            # sessions that grew too large between turns — it fires pre-agent
            # to prevent API failures.  The agent's own compressor handles
            # normal context management during its tool loop with accurate
            # real token counts.  Having hygiene at 0.50 caused premature
            # compression on every turn in long gateway sessions.
            _hyg_model = "anthropic/claude-sonnet-4.6"
            _hyg_threshold_pct = 0.85
            _hyg_compression_enabled = True
            _hyg_hard_msg_limit = 400
            _hyg_config_context_length = None
            _hyg_provider = None
            _hyg_base_url = None
            _hyg_api_key = None
            _hyg_data = {}
            try:
                _hyg_data = _load_gateway_config()
                if _hyg_data:
                    # Resolve model name (same logic as run_sync)
                    _model_cfg = _hyg_data.get("model", {})
                    if isinstance(_model_cfg, str):
                        _hyg_model = _model_cfg
                    elif isinstance(_model_cfg, dict):
                        _hyg_model = _model_cfg.get("default") or _model_cfg.get("model") or _hyg_model
                        # Read explicit context_length override from model config
                        # (same as run_agent.py lines 995-1005)
                        _raw_ctx = _model_cfg.get("context_length")
                        if _raw_ctx is not None:
                            try:
                                _hyg_config_context_length = int(_raw_ctx)
                            except (TypeError, ValueError):
                                pass
                        # Read provider for accurate context detection
                        _hyg_provider = _model_cfg.get("provider") or None
                        _hyg_base_url = _model_cfg.get("base_url") or None

                    # Read compression settings — only use enabled flag.
                    # The threshold is intentionally separate from the agent's
                    # compression.threshold (hygiene runs higher).
                    _comp_cfg = _hyg_data.get("compression", {})
                    if isinstance(_comp_cfg, dict):
                        _hyg_compression_enabled = str(
                            _comp_cfg.get("enabled", True)
                        ).lower() in {"true", "1", "yes"}
                        _raw_hard_limit = _comp_cfg.get("hygiene_hard_message_limit")
                        if _raw_hard_limit is not None:
                            try:
                                _parsed = int(_raw_hard_limit)
                                if _parsed > 0:
                                    _hyg_hard_msg_limit = _parsed
                            except (TypeError, ValueError):
                                pass

                try:
                    _hyg_model, _hyg_runtime = self._resolve_session_agent_runtime(
                        source=source,
                        session_key=session_key,
                        user_config=_hyg_data if isinstance(_hyg_data, dict) else None,
                    )
                    _hyg_provider = _hyg_runtime.get("provider") or _hyg_provider
                    _hyg_base_url = _hyg_runtime.get("base_url") or _hyg_base_url
                    _hyg_api_key = _hyg_runtime.get("api_key") or _hyg_api_key
                except Exception:
                    pass

                # Check custom_providers per-model context_length
                # (same fallback as run_agent.py lines 1171-1189).
                # Must run after runtime resolution so _hyg_base_url is set.
                if _hyg_config_context_length is None and _hyg_base_url:
                    try:
                        try:
                            from hermes_cli.config import get_compatible_custom_providers as _gw_gcp
                            _hyg_custom_providers = _gw_gcp(_hyg_data)
                        except Exception:
                            _hyg_custom_providers = _hyg_data.get("custom_providers")
                            if not isinstance(_hyg_custom_providers, list):
                                _hyg_custom_providers = []
                        for _cp in _hyg_custom_providers:
                            if not isinstance(_cp, dict):
                                continue
                            _cp_url = (_cp.get("base_url") or "").rstrip("/")
                            if _cp_url and _cp_url == _hyg_base_url.rstrip("/"):
                                _cp_models = _cp.get("models", {})
                                if isinstance(_cp_models, dict):
                                    _cp_model_cfg = _cp_models.get(_hyg_model, {})
                                    if isinstance(_cp_model_cfg, dict):
                                        _cp_ctx = _cp_model_cfg.get("context_length")
                                        if _cp_ctx is not None:
                                            _hyg_config_context_length = int(_cp_ctx)
                                break
                    except (TypeError, ValueError):
                        pass
            except Exception:
                pass

            if _hyg_compression_enabled:
                _hyg_context_length = get_model_context_length(
                    _hyg_model,
                    base_url=_hyg_base_url or "",
                    api_key=_hyg_api_key or "",
                    config_context_length=_hyg_config_context_length,
                    provider=_hyg_provider or "",
                )
                _compress_token_threshold = int(
                    _hyg_context_length * _hyg_threshold_pct
                )
                _warn_token_threshold = int(_hyg_context_length * 0.95)

                _msg_count = len(history)

                # Prefer actual API-reported tokens from the last turn
                # (stored in session entry) over the rough char-based estimate.
                _stored_tokens = session_entry.last_prompt_tokens
                if _stored_tokens > 0:
                    _approx_tokens = _stored_tokens
                    _token_source = "actual"
                else:
                    _approx_tokens = estimate_messages_tokens_rough(history)
                    _token_source = "estimated"
                    # Note: rough estimates overestimate by 30-50% for code/JSON-heavy
                    # sessions, but that just means hygiene fires a bit early — which
                    # is safe and harmless.  The 85% threshold already provides ample
                    # headroom (agent's own compressor runs at 50%).  A previous 1.4x
                    # multiplier tried to compensate by inflating the threshold, but
                    # 85% * 1.4 = 119% of context — which exceeds the model's limit
                    # and prevented hygiene from ever firing for ~200K models (GLM-5).

                # Hard safety valve: force compression if message count is
                # extreme, regardless of token estimates.  This breaks the
                # death spiral where API disconnects prevent token data
                # collection, which prevents compression, which causes more
                # disconnects.  400 messages is well above normal sessions
                # but catches runaway growth before it becomes unrecoverable.
                # Threshold is configurable via
                # compression.hygiene_hard_message_limit.
                # (#2153)
                _HARD_MSG_LIMIT = _hyg_hard_msg_limit
                _needs_compress = (
                    _approx_tokens >= _compress_token_threshold
                    or _msg_count >= _HARD_MSG_LIMIT
                )

                if _needs_compress:
                    logger.info(
                        "Session hygiene: %s messages, ~%s tokens (%s) — auto-compressing "
                        "(threshold: %s%% of %s = %s tokens)",
                        _msg_count, f"{_approx_tokens:,}", _token_source,
                        int(_hyg_threshold_pct * 100),
                        f"{_hyg_context_length:,}",
                        f"{_compress_token_threshold:,}",
                    )

                    _hyg_meta = self._thread_metadata_for_source(source, self._reply_anchor_for_event(event))

                    try:
                        from run_agent import AIAgent

                        _hyg_model, _hyg_runtime = self._resolve_session_agent_runtime(
                            source=source,
                            session_key=session_key,
                            user_config=_hyg_data if isinstance(_hyg_data, dict) else None,
                        )
                        if _hyg_runtime.get("api_key"):
                            # Pass the FULL transcript (tool results included).
                            # Filtering to user/assistant-only starved the
                            # compressor: tool results are usually the bulk of
                            # the context, _prune_old_tool_results never saw
                            # them, and short filtered histories tripped the
                            # protect-first/last early-return so nothing was
                            # compressed at all (#3854). The agent loop passes
                            # its full message list to _compress_context — the
                            # gateway now matches.
                            _hyg_msgs = [
                                m for m in history
                                if m.get("role") in {"user", "assistant", "tool"}
                            ]

                            if len(_hyg_msgs) >= 4:
                                _hyg_session_db = getattr(self._session_db, "_db", self._session_db)
                                _hyg_agent = AIAgent(
                                    **_hyg_runtime,
                                    model=_hyg_model,
                                    max_iterations=4,
                                    quiet_mode=True,
                                    skip_memory=True,
                                    enabled_toolsets=["memory"],
                                    session_id=session_entry.session_id,
                                    session_db=_hyg_session_db,
                                )
                                try:
                                    # Hygiene owns the live session binding. Prefer
                                    # in-place compaction when a SessionDB exists;
                                    # without one, the guards below preserve the
                                    # original transcript rather than overwriting it
                                    # with an uncommitted summary.
                                    _hyg_agent.compression_in_place = True
                                    bind_hyg_state = getattr(
                                        getattr(_hyg_agent, "context_compressor", None),
                                        "bind_session_state",
                                        None,
                                    )
                                    if callable(bind_hyg_state):
                                        bind_hyg_state(
                                            _hyg_session_db,
                                            session_entry.session_id,
                                        )
                                    _hyg_agent._end_session_on_close = False
                                    _hyg_agent._print_fn = lambda *a, **kw: None

                                    loop = asyncio.get_running_loop()
                                    _compressed, _ = await loop.run_in_executor(
                                        None,
                                        lambda: _hyg_agent._compress_context(
                                            _hyg_msgs, "",
                                            approx_tokens=_approx_tokens,
                                        ),
                                    )

                                    # _compress_context ends the old session and creates
                                    # a new session_id.  Write compressed messages into
                                    # the NEW session so the old transcript stays intact
                                    # and searchable via session_search.
                                    _hyg_new_sid = _hyg_agent.session_id
                                    _hyg_rotated = _hyg_new_sid != session_entry.session_id
                                    _hyg_in_place = bool(
                                        getattr(
                                            _hyg_agent,
                                            "_last_compaction_in_place",
                                            False,
                                        )
                                    )
                                    if _hyg_rotated:
                                        session_entry.session_id = _hyg_new_sid
                                        self._rebind_turn_lease(
                                            _quick_key,
                                            run_generation,
                                            _hyg_new_sid,
                                        )
                                        await self.async_session_store._save()
                                        await asyncio.to_thread(
                                            self._sync_telegram_topic_binding,
                                            source,
                                            session_entry,
                                            reason="hygiene-compression",
                                        )

                                    # Rotation requires publishing the new child's
                                    # transcript. In-place compaction already wrote
                                    # the new active set and archived the old rows;
                                    # rewriting there would delete the archive. If
                                    # neither path completed, preserve the original
                                    # transcript instead of destructive summary-only
                                    # replacement (#21301/#61145).
                                    if _hyg_rotated:
                                        await self.async_session_store.rewrite_transcript(
                                            session_entry.session_id,
                                            _compressed,
                                        )
                                        session_entry.last_prompt_tokens = 0
                                        history = _compressed
                                        _new_count = len(_compressed)
                                        _new_tokens = estimate_messages_tokens_rough(
                                            _compressed
                                        )
                                    elif _hyg_in_place:
                                        session_entry.last_prompt_tokens = 0
                                        history = _compressed
                                        _new_count = len(_compressed)
                                        _new_tokens = estimate_messages_tokens_rough(
                                            _compressed
                                        )
                                    else:
                                        _new_count = _msg_count
                                        _new_tokens = _approx_tokens
                                        logger.warning(
                                            "Gateway hygiene compression for session %s "
                                            "did not rotate or compact in place; preserving "
                                            "the original transcript.",
                                            session_entry.session_id,
                                        )

                                    logger.info(
                                        "Session hygiene: compressed %s → %s msgs, "
                                        "~%s → ~%s tokens",
                                        _msg_count, _new_count,
                                        f"{_approx_tokens:,}", f"{_new_tokens:,}",
                                    )

                                    if _new_tokens >= _warn_token_threshold:
                                        logger.warning(
                                            "Session hygiene: still ~%s tokens after "
                                            "compression",
                                            f"{_new_tokens:,}",
                                    )

                                    # If summary generation failed, the
                                    # compressor aborts entirely and returns
                                    # messages unchanged — nothing is dropped.
                                    # Surface a visible warning to the gateway
                                    # user — agent.log alone is invisible on
                                    # TG/Discord/etc. — so they know the chat
                                    # is "frozen" at the current size and can
                                    # /compress to retry or /reset to start
                                    # fresh.
                                    _comp = getattr(_hyg_agent, "context_compressor", None)
                                    if _comp is not None and getattr(_comp, "_last_compress_aborted", False):
                                        _err = getattr(_comp, "_last_summary_error", None) or "unknown error"
                                        # Force-redact: provider exception text
                                        # may contain credentials; this message
                                        # reaches gateway users directly.
                                        from agent.redact import redact_sensitive_text
                                        _err = redact_sensitive_text(_err, force=True)
                                        _warn_msg = (
                                            "⚠️ Context compression aborted "
                                            f"({_err}). No messages were dropped — "
                                            "conversation is unchanged. Run /compress "
                                            "to retry, /reset for a clean session, or "
                                            "check your auxiliary.compression model "
                                            "configuration."
                                        )
                                        try:
                                            _adapter = self._adapter_for_source(source)
                                            if _adapter and source.chat_id:
                                                await _adapter.send(source.chat_id, _warn_msg, metadata=_hyg_meta)
                                        except Exception as _werr:
                                            logger.warning(
                                                "Failed to deliver compression-failure warning to user: %s",
                                                _werr,
                                            )
                                    elif _comp is not None and getattr(_comp, "_last_summary_fallback_used", False):
                                        _err = getattr(_comp, "_last_summary_error", None) or "unknown error"
                                        _dropped = getattr(_comp, "_last_summary_dropped_count", 0) or 0
                                        _warn_msg = (
                                            "⚠️ Context compression summary failed "
                                            f"({_err}). {_dropped} historical message(s) were "
                                            "replaced with a local fallback summary; some earlier "
                                            "details may be missing. Consider checking your "
                                            "auxiliary.compression model configuration."
                                        )
                                        try:
                                            _adapter = self._adapter_for_source(source)
                                            if _adapter and source.chat_id:
                                                await _adapter.send(source.chat_id, _warn_msg, metadata=_hyg_meta)
                                        except Exception as _werr:
                                            logger.warning(
                                                "Failed to deliver compression-failure warning to user: %s",
                                                _werr,
                                            )
                                    # Separately: if the user's CONFIGURED aux
                                    # model failed and we recovered by falling
                                    # back to the main model, tell them — a
                                    # misconfigured auxiliary.compression.model
                                    # is something only they can fix, and
                                    # silent recovery would hide it.
                                    elif _comp is not None and getattr(_comp, "_last_aux_model_failure_model", None):
                                        _aux_model = getattr(_comp, "_last_aux_model_failure_model", "")
                                        _aux_err = getattr(_comp, "_last_aux_model_failure_error", None) or "unknown error"
                                        _aux_msg = (
                                            f"ℹ️ Configured compression model `{_aux_model}` "
                                            f"failed ({_aux_err}). Recovered using your main "
                                            "model — context is intact — but you may want to "
                                            "check `auxiliary.compression.model` in config.yaml."
                                        )
                                        try:
                                            _adapter = self._adapter_for_source(source)
                                            if _adapter and source.chat_id:
                                                await _adapter.send(source.chat_id, _aux_msg, metadata=_hyg_meta)
                                        except Exception as _werr:
                                            logger.warning(
                                                "Failed to deliver aux-model-fallback notice to user: %s",
                                                _werr,
                                            )
                                finally:
                                    # Evict the cached agent so the next turn
                                    # rebuilds its system prompt from current
                                    # SOUL.md, memory, and skills.
                                    self._evict_cached_agent(session_key)
                                    self._cleanup_agent_resources(_hyg_agent)

                    except Exception as e:
                        logger.warning(
                            "Session hygiene auto-compress failed: %s", e
                        )

        # First-message onboarding -- only on the very first interaction ever
        if not history and not await self.async_session_store.has_any_sessions():
            context_prompt += (
                "\n\n[System note: This is the user's very first message ever. "
                "Briefly introduce yourself and mention that /help shows available commands. "
                "Keep the introduction concise -- one or two sentences max.]"
            )

        # One-time prompt if no home channel is set for this platform
        # Skip for webhooks - they deliver directly to configured targets.
        if not history and source.platform and source.platform != Platform.LOCAL and source.platform != Platform.WEBHOOK:
            platform_name = source.platform.value
            env_key = _home_target_env_var(platform_name)
            # Multiplex: home channel may live only in the profile secret
            # scope / PlatformConfig, not process os.environ.
            home_env = ""
            try:
                from agent.secret_scope import get_secret

                home_env = (get_secret(env_key) or "").strip() if env_key else ""
            except Exception:
                home_env = ""
            if not home_env:
                home_env = (os.getenv(env_key) or "").strip() if env_key else ""
            # Also honor in-memory / yaml home_channel on this platform.
            try:
                if not home_env and self.config.get_home_channel(source.platform):
                    home_env = "set"
            except Exception:
                pass
            # Secondary-profile platforms (e.g. Slack on yolo) may only exist
            # under that profile's loaded config — check after scope install.
            if not home_env:
                try:
                    from hermes_cli.profiles import get_profile_dir
                    from gateway.config import load_gateway_config as _lgc
                    prof = (getattr(source, "profile", None) or "").strip()
                    if prof and prof != "default":
                        # Already inside profile scope for secondary handlers;
                        # re-read live config for home_channel.
                        _pcfg = _lgc()
                        if _pcfg.get_home_channel(source.platform):
                            home_env = "set"
                except Exception:
                    pass
            if not home_env:
                # Slack dispatches all Hermes commands through a single
                # parent slash command `/hermes`; bare `/sethome` is not
                # registered and would fail with "app did not respond".
                sethome_cmd = (
                    "/hermes sethome"
                    if source.platform == Platform.SLACK
                    else "/sethome"
                )
                notice = (
                    f"📬 No home channel is set for {platform_name.title()}. "
                    f"A home channel is where Hermes delivers cron job results "
                    f"and cross-platform messages.\n\n"
                    f"Type {sethome_cmd} to make this chat your home channel, "
                    f"or ignore to skip."
                )
                await self._deliver_platform_notice(source, notice)

        # -----------------------------------------------------------------
        # Voice channel awareness — deliver current voice channel state so
        # the agent knows who is in the channel and who is speaking, without
        # needing a separate tool call.  Delivered on the current user
        # message and ONLY when it changed since the previous turn: the
        # member/speaking serialization differs essentially every turn, and
        # appending it to the ephemeral system prompt forced a full agent
        # rebuild + prompt-cache re-key per message.  The system prompt
        # carries a static pointer line instead (gateway/session.py).
        # -----------------------------------------------------------------
        _vc_note = self._voice_channel_sidecar_note(event, source, session_key)
        if _vc_note:
            turn_sidecar_notes.append(_vc_note)

        # -----------------------------------------------------------------
        # Auto-analyze images sent by the user
        #
        # If the user attached image(s), we run the vision tool eagerly so
        # the conversation model always receives a text description.  The
        # local file path is also included so the model can re-examine the
        # image later with a more targeted question via vision_analyze.
        #
        # We filter to image paths only (by media_type) so that non-image
        # attachments (documents, audio, etc.) are not sent to the vision
        # tool even when they appear in the same message.
        # -----------------------------------------------------------------
        _starting_followups = self._consume_start_user_followups(
            _quick_key,
            run_generation,
        )
        if _starting_followups:
            # Mutate only the text on the owned intake event. dataclasses.replace
            # would discard transient attributes attached by Discord/Fable/
            # background-completion paths that are not declared dataclass fields.
            event.text = self._fold_start_user_followups(
                event.text or "",
                _starting_followups,
            )

        message_text = await self._prepare_profile_scoped_inbound_message_text(
            event=event,
            source=source,
            history=history,
        )
        if message_text is None:
            return

        # Bind this gateway run generation to the adapter's active-session
        # event so deferred post-delivery callbacks can be released by the
        # same run that registered them.
        self._bind_adapter_run_generation(
            self._adapter_for_source(source),
            session_key,
            run_generation,
        )

        try:
            # Emit agent:start hook
            hook_ctx = {
                "platform": source.platform.value if source.platform else "",
                "user_id": source.user_id,
                "chat_id": source.chat_id or "",
                "session_id": session_entry.session_id,
                "message": message_text[:500],
            }
            await self.hooks.emit("agent:start", hook_ctx)

            # Run the agent
            work_item_id = self._discord_work_item_id_for_event(event, session_key)
            work_item_expected_run_state = None
            work_item_heartbeat_task = None
            if work_item_id and source.platform == Platform.DISCORD:
                _ledger_running_started = time.perf_counter()
                try:
                    self._ledger().mark_agent_running(
                        str(work_item_id),
                        session_id=session_entry.session_id,
                        session_key=session_key,
                        run_generation=run_generation,
                        process_epoch=self._process_epoch,
                    )
                    work_item_expected_run_state = self._ledger().capture_run_state(
                        str(work_item_id),
                        session_key=session_key,
                        run_generation=run_generation,
                        owner_pid=os.getpid(),
                        process_epoch=self._process_epoch,
                    )
                    if work_item_expected_run_state is not None:
                        async def _renew_work_item_lease() -> None:
                            nonlocal work_item_expected_run_state
                            while True:
                                await asyncio.sleep(30.0)
                                renewed = self._ledger().renew_active_run(
                                    str(work_item_id),
                                    session_key=session_key,
                                    run_generation=run_generation,
                                    owner_pid=os.getpid(),
                                    process_epoch=self._process_epoch,
                                )
                                if renewed is None:
                                    logger.warning(
                                        "Stopped Discord work-item heartbeat after ownership changed for %s",
                                        work_item_id,
                                    )
                                    return
                                work_item_expected_run_state = self._ledger().run_state_snapshot(
                                    renewed
                                )

                        work_item_heartbeat_task = asyncio.create_task(
                            _renew_work_item_lease()
                        )
                    try:
                        from agent.provider_progress import record_provider_progress_signal

                        record_provider_progress_signal(
                            session_key,
                            "gateway_ledger_agent_running",
                            phase="work_ledger",
                            source="gateway",
                            metadata={"work_id": str(work_item_id)},
                        )
                    except Exception:
                        pass
                except Exception as exc:
                    logger.debug("Discord work ledger agent_running update failed: %s", exc)
                finally:
                    _flow_durations = getattr(event, "metadata", {}).get(
                        "gateway_flow_phase_durations"
                    )
                    if isinstance(_flow_durations, dict):
                        _flow_durations["ledger_agent_running_ms"] = int(
                            (time.perf_counter() - _ledger_running_started) * 1000
                        )
                        _flow_durations["ledger_agent_running_calls"] = 1
            detached_accounting = []
            pending_accounting = getattr(
                self,
                "_pending_detached_delegation_accounting",
                None,
            )
            if isinstance(pending_accounting, dict):
                detached_accounting.extend(pending_accounting.pop(session_key, []))
            event_accounting = getattr(
                event,
                "detached_delegation_accounting",
                None,
            )
            if isinstance(event_accounting, dict):
                detached_accounting.append(event_accounting)
            if turn_sidecar_notes and session_key:
                self._set_pending_turn_sidecar_notes(
                    session_key,
                    turn_sidecar_notes,
                )
            sealed_required_state = None
            try:
                agent_result = await self._run_agent(
                    message=message_text,
                    context_prompt=context_prompt,
                    history=history,
                    source=source,
                    session_id=session_entry.session_id,
                    session_key=session_key,
                    run_generation=run_generation,
                    event_message_id=self._reply_anchor_for_event(event),
                    channel_prompt=event.channel_prompt,
                    feature_summary=getattr(event, "feature_summary", None),
                    project_summary=getattr(event, "project_summary", None),
                    discord_runtime_mode=discord_runtime_mode.value,
                    discord_action_request_intent=getattr(
                        event,
                        "discord_action_request_intent",
                        None,
                    ),
                    discord_action_escalation_allowed=bool(
                        source.platform == Platform.DISCORD
                        and discord_runtime_mode is RuntimeMode.READ_ONLY
                    ),
                    fable_plan_metadata=getattr(event, "fable_plan_metadata", None),
                    fable_toolsets=getattr(event, "fable_enabled_toolsets", None),
                    fable_reasoning_config=getattr(event, "fable_reasoning_config", None),
                    fable_transcript_user_message=getattr(event, "fable_transcript_user_message", None),
                    opus_plan_metadata=getattr(event, "opus_plan_metadata", None),
                    opus_toolsets=getattr(event, "opus_enabled_toolsets", None),
                    opus_reasoning_config=getattr(event, "opus_reasoning_config", None),
                    opus_transcript_user_message=getattr(event, "opus_transcript_user_message", None),
                    session_cwd_override=session_cwd,
                    visual_qa_requirement=getattr(event, "visual_qa_requirement", None),
                    visual_qa_config=getattr(event, "visual_qa_config", None),
                    completed_worker_run=getattr(event, "completed_worker_run", None),
                    detached_delegation_accounting=detached_accounting,
                    origin_work_item_id=str(work_item_id or ""),
                    suppress_user_output=bool(
                        getattr(event, "suppress_user_output", False)
                    ),
                    flow_timing=getattr(event, "metadata", {}).get(
                        "gateway_flow_phase_timestamps"
                    ),
                    defer_persistence=bool(
                        source.platform == Platform.DISCORD
                        and discord_runtime_mode is RuntimeMode.READ_ONLY
                    ),
                )
            finally:
                if work_item_id and source.platform == Platform.DISCORD:
                    # Returning or raising from _run_agent closes this parent
                    # turn's dispatch-membership window. Seal in the unwind
                    # path so an unexpected model/runtime error cannot strand
                    # already released required workers in an open attempt.
                    sealed_required_state = self._seal_required_async_parent_attempt(
                        str(work_item_id),
                        run_generation=run_generation,
                    )
                if work_item_heartbeat_task is not None:
                    work_item_heartbeat_task.cancel()
                    try:
                        await work_item_heartbeat_task
                    except asyncio.CancelledError:
                        pass

            _pending_background_workers = bool(
                isinstance(sealed_required_state, dict)
                and sealed_required_state.get("owns_recovery") is True
            ) or self._session_has_pending_background_workers(
                session_key,
                work_item_id=str(work_item_id or "") or None,
                origin_run_generation=getattr(
                    event,
                    "background_completion_generation",
                    None,
                ),
                origin_attempt_id=getattr(
                    event,
                    "background_completion_attempt_id",
                    None,
                ),
                exclude_delegation_id=_background_completion_id or None,
            )
            if _pending_background_workers:
                event.defer_work_completion = True

            # Stop persistent typing indicator now that the agent is done.
            # Slack AI status is scoped to a thread/workspace, so preserve the
            # same routing metadata used by the response delivery path.
            try:
                _typing_adapter = self._adapter_for_source(source)
                if _typing_adapter and hasattr(_typing_adapter, "stop_typing"):
                    await _typing_adapter.stop_typing(source.chat_id)
            except Exception:
                pass

            if not self._is_session_run_current(_quick_key, run_generation):
                logger.info(
                    "Discarding stale agent result for %s — generation %d is no longer current",
                    _quick_key or "?",
                    run_generation,
                )
                _stale_adapter = self._adapter_for_source(source)
                if getattr(type(_stale_adapter), "pop_post_delivery_callback", None) is not None:
                    _stale_adapter.pop_post_delivery_callback(
                        _quick_key,
                        generation=run_generation,
                    )
                elif _stale_adapter and hasattr(_stale_adapter, "_post_delivery_callbacks"):
                    _stale_adapter._post_delivery_callbacks.pop(_quick_key, None)
                return None

            escalation_requested = isinstance(
                agent_result.get("action_escalation_requested"), dict
            )
            if escalation_requested:
                promoted_thread_url = await self._promote_discord_action_escalation(
                    event=event,
                    source=source,
                    session_key=session_key,
                    run_generation=run_generation,
                    agent_result=agent_result,
                )
                if promoted_thread_url is None:
                    return (
                        "⚠️ I recognized this as an action request, but I could not "
                        "initialize its isolated Discord action runtime. Nothing was "
                        "implemented. Please retry or use an action-request channel."
                    )
                # The action replay is the user-visible continuation. A separate
                # acknowledgement in the question thread is redundant (and can
                # look like an extra bot response when the promoted thread is
                # already visible in Discord), so let the action turn speak for
                # itself. Keep the URL available for logging/debugging only.
                logger.info(
                    "Discord action escalation dispatched without acknowledgement: %s",
                    promoted_thread_url or "same-thread",
                )
                return None

            response = agent_result.get("final_response") or ""
            # Hidden-reasoning-only retry exhaustion has no user-visible model
            # answer. Blank the sentinel before empty-response normalization;
            # a genuinely different final_response is preserved by the helper.
            if _is_gateway_hidden_reasoning_incomplete_turn(agent_result):
                response = ""
            try:
                from gateway.response_filters import (
                    is_intentional_silence_agent_result,
                )

                _intentional_silence = is_intentional_silence_agent_result(
                    agent_result,
                    response,
                )
            except Exception:
                _intentional_silence = False
            fable_plan_metadata = getattr(event, "fable_plan_metadata", None)
            if fable_plan_metadata:
                actual_model = str(agent_result.get("model") or "")
                actual_provider = str(agent_result.get("provider") or "")
                if agent_result.get("failed"):
                    detail = str(agent_result.get("error") or response or "Fable route unavailable.")
                    return _fable_fail_closed_error(detail, str(fable_plan_metadata.get("route") or ""))
                if actual_model != "claude-fable-5" or actual_provider != "anthropic":
                    logger.error(
                        "/fable resolved unexpected route provider=%r model=%r; refusing fallback result for session %s",
                        actual_provider,
                        actual_model,
                        session_key,
                    )
                    return _fable_fail_closed_error(
                        "Resolved unexpected route "
                        f"provider={actual_provider!r} model={actual_model!r}; refusing fallback result.",
                        str(fable_plan_metadata.get("route") or ""),
                    )
                transcript_user_message = str(
                    getattr(event, "fable_transcript_user_message", "") or ""
                ).strip()
                if transcript_user_message:
                    original_message_text = message_text
                    message_text = transcript_user_message
                    logger.debug(
                        "Persisting /fable command text for session %s instead of plan-only skill payload (%d chars elided)",
                        session_key,
                        len(original_message_text or ""),
                    )
            opus_plan_metadata = getattr(event, "opus_plan_metadata", None)
            if opus_plan_metadata:
                actual_model = str(agent_result.get("model") or "")
                actual_provider = str(agent_result.get("provider") or "")
                if agent_result.get("failed"):
                    detail = str(agent_result.get("error") or response or "Opus route unavailable.")
                    return _opus_fail_closed_error(detail, str(opus_plan_metadata.get("route") or ""))
                if actual_model != "claude-opus-5" or actual_provider != "anthropic":
                    logger.error(
                        "/opus resolved unexpected route provider=%r model=%r; refusing fallback result for session %s",
                        actual_provider,
                        actual_model,
                        session_key,
                    )
                    return _opus_fail_closed_error(
                        "Resolved unexpected route "
                        f"provider={actual_provider!r} model={actual_model!r}; refusing fallback result.",
                        str(opus_plan_metadata.get("route") or ""),
                    )
                transcript_user_message = str(
                    getattr(event, "opus_transcript_user_message", "") or ""
                ).strip()
                if transcript_user_message:
                    original_message_text = message_text
                    message_text = transcript_user_message
                    logger.debug(
                        "Persisting /opus command text for session %s instead of plan-only skill payload (%d chars elided)",
                        session_key,
                        len(original_message_text or ""),
                    )

            # Convert the agent's internal "(empty)" sentinel into a
            # user-friendly message.  "(empty)" means the model failed to
            # produce visible content after exhausting all retries (nudge,
            # prefill, empty-retry, fallback).  Sending the raw sentinel
            # looks like a bug; a short explanation is more helpful.
            if response == "(empty)" and not _intentional_silence:
                response = (
                    "⚠️ The model returned no response after processing tool "
                    "results. This can happen with some models — try again or "
                    "rephrase your question."
                )
            agent_messages = agent_result.get("messages", [])
            transcript_user_message = str(
                getattr(event, "fable_transcript_user_message", "")
                or getattr(event, "opus_transcript_user_message", "")
                or ""
            ).strip()
            if transcript_user_message:
                try:
                    history_offset = agent_result.get("history_offset", len(history))
                    agent_messages = list(agent_messages or [])
                    if len(agent_messages) > history_offset:
                        first_new = agent_messages[history_offset]
                        if isinstance(first_new, dict) and first_new.get("role") == "user":
                            patched_first_new = dict(first_new)
                            patched_first_new["content"] = transcript_user_message
                            agent_messages[history_offset] = patched_first_new
                except Exception:
                    agent_messages = agent_result.get("messages", [])
            persisted_message_text = transcript_user_message or message_text
            _response_time = time.time() - _msg_start_time
            _api_calls = agent_result.get("api_calls", 0)
            _resp_len = len(response)
            logger.info(
                "response ready: platform=%s chat=%s time=%.1fs api_calls=%d response=%d chars",
                _platform_name, source.chat_id or "unknown",
                _response_time, _api_calls, _resp_len,
            )

            # Successful turn — clear any stuck-loop counter for this session.
            # This ensures the counter only accumulates across CONSECUTIVE
            # restarts where the session was active (never completed).
            #
            # Also clear the resume_pending flag (set by drain-timeout
            # shutdown) — the turn ran to completion, so recovery
            # succeeded and subsequent messages should no longer receive
            # the restart-interruption system note.
            if session_key and _should_clear_resume_pending_after_turn(agent_result):
                self._clear_restart_failure_count(session_key)
                try:
                    await self.async_session_store.clear_resume_pending(session_key)
                except Exception as _e:
                    logger.debug(
                        "clear_resume_pending failed for %s: %s",
                        session_key, _e,
                    )

            # Normalize empty responses: surface errors, partial failures, and
            # the case where agent did work but returned no text. Fix for #18765.
            response = _normalize_empty_agent_response(
                agent_result, response, history_len=len(history),
            )
            response = _sanitize_gateway_final_response(source.platform, response)

            meeting_goal_status = ""
            if response and not _intentional_silence and not agent_result.get("failed"):
                try:
                    meeting_goal_status = await self._apply_meeting_auto_goal_from_response(
                        event,
                        response,
                    )
                    if meeting_goal_status:
                        response = f"{response.rstrip()}\n\n{meeting_goal_status}"
                except Exception as _meeting_goal_exc:
                    logger.debug("meeting auto-goal hook failed: %s", _meeting_goal_exc)

            # If the agent's session_id changed during compression, update
            # session_entry so transcript writes below go to the right session.
            if agent_result.get("session_id") and agent_result["session_id"] != session_entry.session_id:
                session_entry.session_id = agent_result["session_id"]
                await self.async_session_store._save()
                await asyncio.to_thread(self._sync_telegram_topic_binding, source, session_entry, reason="agent-result-compression")

            # Prepend reasoning/thinking if display is enabled (per-platform)
            try:
                from gateway.display_config import resolve_display_setting as _rds
                _show_reasoning_effective = _rds(
                    _load_gateway_config(),
                    _platform_config_key(source.platform),
                    "show_reasoning",
                    getattr(self, "_show_reasoning", False),
                )
            except Exception:
                _show_reasoning_effective = getattr(self, "_show_reasoning", False)
            if _show_reasoning_effective and response and not _intentional_silence:
                last_reasoning = agent_result.get("last_reasoning")
                if last_reasoning:
                    # Collapse long reasoning to keep messages readable
                    lines = last_reasoning.strip().splitlines()
                    if len(lines) > 15:
                        display_reasoning = "\n".join(lines[:15])
                        display_reasoning += f"\n_... ({len(lines) - 15} more lines)_"
                    else:
                        display_reasoning = last_reasoning.strip()
                    response = f"💭 **Reasoning:**\n```\n{display_reasoning}\n```\n\n{response}"

            # Runtime-metadata footer — only on the FINAL message of the turn.
            # Off by default (display.runtime_footer.enabled=false).  When
            # streaming already delivered the body, we can't mutate the sent
            # text, so we fire a separate trailing send below.
            _footer_line = _runtime_footer_line_for_agent_result(
                user_config=_load_gateway_config(),
                source=source,
                agent_result=agent_result,
                cwd=session_cwd,
            )
            if (
                _footer_line
                and response
                and not agent_result.get("already_sent")
                and not _intentional_silence
            ):
                response = _append_runtime_footer(response, _footer_line)

            work_item_id = self._discord_work_item_id_for_event(event, session_key)
            _streaming_gate_notice = ""
            if (
                work_item_id
                and source.platform == Platform.DISCORD
                and not _pending_background_workers
            ):
                try:
                    visual_turn = (
                        agent_result.get("visual_qa")
                        if isinstance(agent_result.get("visual_qa"), dict)
                        else {}
                    )
                    promoted_requirement = visual_turn.get("requirement")
                    if isinstance(promoted_requirement, dict):
                        promoted_item = await asyncio.to_thread(
                            self._ledger().promote_visual_qa_requirement,
                            str(work_item_id),
                            promoted_requirement,
                            expected_run_state=work_item_expected_run_state,
                        )
                        if isinstance(promoted_item, dict):
                            event.visual_qa_requirement = promoted_item.get(
                                "visual_qa_requirement"
                            )
                    await asyncio.to_thread(
                        self._activate_direct_closeout_after_checkpoint,
                        str(work_item_id),
                        agent_result,
                    )
                    title = None
                    if session_entry.session_id and self._session_db and not getattr(event, "feature_summary", None):
                        try:
                            title = await self._session_db.get_session_title(session_entry.session_id)
                        except Exception:
                            title = None
                    agent_done = self._ledger().mark_agent_done(
                        str(work_item_id),
                        final_response=response,
                        session_id=session_entry.session_id,
                        summary_status=self._discord_summary_status(agent_result),
                        title=title,
                        feature_summary=getattr(event, "feature_summary", None),
                        project_summary=getattr(event, "project_summary", None),
                        runtime_breakdown=agent_result.get("runtime_breakdown") if isinstance(agent_result, dict) else None,
                        provider_no_progress=agent_result.get("provider_no_progress") if isinstance(agent_result, dict) else None,
                        visual_qa_requirement=(
                            agent_result.get("visual_qa", {}).get("requirement")
                            if isinstance(agent_result.get("visual_qa"), dict)
                            else None
                        ),
                        visual_qa_receipts=(
                            agent_result.get("visual_qa", {}).get("receipts")
                            if isinstance(agent_result.get("visual_qa"), dict)
                            else None
                        ),
                        visual_qa_code_mutation_observed=(
                            agent_result.get("visual_qa", {}).get("code_mutation_observed")
                            if isinstance(agent_result.get("visual_qa"), dict)
                            else None
                        ),
                        visual_qa_min_receipt_order=(
                            agent_result.get("visual_qa", {}).get("min_receipt_order")
                            if isinstance(agent_result.get("visual_qa"), dict)
                            else None
                        ),
                        already_delivered=bool(agent_result.get("already_sent"))
                        and not agent_result.get("failed"),
                        expected_run_state=work_item_expected_run_state,
                    )
                    if agent_done:
                        event.work_item_run_state = self._ledger().run_state_snapshot(
                            {
                                "status": (
                                    "response_delivered"
                                    if bool(agent_result.get("already_sent"))
                                    and not agent_result.get("failed")
                                    else "agent_done"
                                ),
                                "active_run": None,
                            }
                        )
                    else:
                        logger.info(
                            "Suppressing stale Discord response after agent_done CAS failed for %s",
                            work_item_id,
                        )
                        response = None
                    if agent_done:
                        current_item = self._ledger().get(str(work_item_id)) or {}
                        persisted_response = str(current_item.get("final_response") or "")
                        if persisted_response != response:
                            response = persisted_response
                            if agent_result.get("already_sent") and not agent_result.get("failed"):
                                from gateway.work_ledger import enforced_visual_qa_block_notice

                                _streaming_gate_notice = enforced_visual_qa_block_notice(
                                    current_item
                                )
                        try:
                            from agent.provider_progress import record_provider_progress_signal

                            record_provider_progress_signal(
                                session_key,
                                "gateway_ledger_agent_done",
                                phase="work_ledger",
                                source="gateway",
                                metadata={"work_id": str(work_item_id)},
                            )
                        except Exception:
                            pass
                except Exception as exc:
                    logger.debug("Discord work ledger agent_done update failed: %s", exc)

            # Emit agent:end hook
            await self.hooks.emit("agent:end", {
                **hook_ctx,
                "response": (response or "")[:500],
            })

            # Check for pending process watchers (check_interval on background processes)
            try:
                from tools.process_registry import process_registry
                while process_registry.pending_watchers:
                    watcher = process_registry.pending_watchers.pop(0)
                    asyncio.create_task(self._run_process_watcher(watcher))
            except Exception as e:
                logger.error("Process watcher setup error: %s", e)

            # Drain watch pattern notifications that arrived during the agent run.
            # Watch events and completions share the same queue; completions are
            # already handled by the per-process watcher task above, so we only
            # deliver watch-type status notifications here. These are direct
            # platform notifications, not synthetic user turns: a late server
            # readiness line should not trigger a second "what happened?" agent
            # response after the original turn is already complete.
            try:
                from tools.process_registry import process_registry as _pr
                _watch_events = _drain_gateway_watch_events(_pr.completion_queue)
                for evt in _watch_events:
                    synth_text = _format_gateway_process_notification(evt)
                    if synth_text:
                        try:
                            await self._inject_watch_notification(synth_text, evt)
                        except Exception as e2:
                            logger.error("Watch notification delivery error: %s", e2)
            except Exception as e:
                logger.debug("Watch queue drain error: %s", e)

            # NOTE: Dangerous command approvals are now handled inline by the
            # blocking gateway approval mechanism in tools/approval.py.  The agent
            # thread blocks until the user responds with /approve or /deny, so by
            # the time we reach here the approval has already been resolved.  The
            # old post-loop pop_pending + approval_hint code was removed in favour
            # of the blocking approach that mirrors CLI's synchronous input().

            # Save the full conversation to the transcript, including tool calls.
            # This preserves the complete agent loop (tool_calls, tool results,
            # intermediate reasoning) so sessions can be resumed with full context
            # and transcripts are useful for debugging and training data.
            #
            # IMPORTANT: For context-overflow failures (compression exhausted,
            # generic 400 on large sessions) we must NOT persist the user's
            # message — doing so would grow the session further and cause the
            # same failure on the next attempt, an infinite loop. (#1630, #9893)
            #
            # Transient failures (429, timeout, connection error, provider 5xx)
            # are different: the session is not oversized, and silently dropping
            # the user message causes severe context loss on retry — the agent
            # forgets what was just asked.  Persist the user turn so the
            # conversation is preserved. (#7100)
            agent_failed_early = bool(agent_result.get("failed"))
            hidden_reasoning_incomplete = _is_gateway_hidden_reasoning_incomplete_turn(
                agent_result
            )
            is_context_overflow_failure = _is_context_overflow_failure(agent_result)
            if is_context_overflow_failure:
                logger.info(
                    "Skipping transcript persistence for context-overflow "
                    "failure in session %s to prevent session growth loop.",
                    session_entry.session_id,
                )
            elif agent_failed_early:
                logger.info(
                    "Transient agent failure in session %s — persisting user "
                    "message so conversation context is preserved on retry.",
                    session_entry.session_id,
                )
            elif hidden_reasoning_incomplete:
                logger.warning(
                    "Suppressing hidden-reasoning-only incomplete gateway turn "
                    "for session %s: %s",
                    session_entry.session_id,
                    agent_result.get("error", "processing incomplete"),
                )

            # When compression is exhausted, the session is permanently too
            # large to process.  Auto-reset it so the next message starts
            # fresh instead of replaying the same oversized context in an
            # infinite fail loop.  (#9893)
            if agent_result.get("compression_exhausted") and session_entry and session_key:
                logger.info(
                    "Auto-resetting session %s after compression exhaustion.",
                    session_entry.session_id,
                )
                new_entry = await self.async_session_store.reset_session(session_key)
                self._evict_cached_agent(session_key)
                self._clear_conversation_scope(
                    session_key, reason="compression_exhausted_reset"
                )
                if new_entry is not None:
                    # Compression may have re-bound this topic to the oversized
                    # child session earlier in the turn. Point the binding at the
                    # fresh reset entry so the next message cannot heal back onto
                    # the exhausted transcript.
                    session_entry = new_entry
                    await asyncio.to_thread(
                        self._sync_telegram_topic_binding,
                        source,
                        session_entry,
                        reason="compression-exhausted-reset",
                    )
                response = (response or "") + (
                    "\n\n🔄 Session auto-reset — the conversation exceeded the "
                    "maximum context size and could not be compressed further. "
                    "Your next message will start a fresh session."
                )

            ts = datetime.now().isoformat()

            # If this is a fresh session (no history), write the full tool
            # definitions as the first entry so the transcript is self-describing
            # -- the same list of dicts sent as tools=[...] in the API request.
            if is_context_overflow_failure:
                pass  # Skip all transcript writes — don't grow a broken session
            elif not history:
                tool_defs = agent_result.get("tools", [])
                await self.async_session_store.append_to_transcript(
                    session_entry.session_id,
                    {
                        "role": "session_meta",
                        "tools": tool_defs or [],
                        "model": agent_result.get("model") or _resolve_gateway_model(),
                        "platform": source.platform.value if source.platform else "",
                        "timestamp": ts,
                    }
                )

            # The agent normally persists its own messages to SQLite. Keep the
            # gateway JSONL fallback while skipping duplicate DB writes on every
            # persistence branch; runtimes that do not self-persist can return
            # agent_persisted=False explicitly.
            agent_persisted = agent_result.get(
                "agent_persisted", self._session_db is not None
            )

            # Find only the NEW messages from this turn (skip history we loaded).
            # Use the filtered history length (history_offset) that was actually
            # passed to the agent, not len(history) which includes session_meta
            # entries that were stripped before the agent saw them.
            if is_context_overflow_failure:
                pass  # handled above — skip all transcript writes
            elif agent_failed_early or hidden_reasoning_incomplete:
                # Transient failure (429/timeout/5xx): persist only the user
                # message so the next message can load a transcript that
                # reflects what was said.  Skip the assistant error text since
                # it's a gateway-generated hint, not model output. Hidden-
                # reasoning-only incomplete turns follow the same persistence
                # rule so peer-agent channels don't ingest them as completed
                # assistant turns. (#7100, #51628)
                _user_entry = {
                    "role": "user",
                    "content": persisted_message_text,
                    "timestamp": ts,
                }
                if event.message_id:
                    _user_entry["message_id"] = str(event.message_id)
                await self.async_session_store.append_to_transcript(
                    session_entry.session_id,
                    _user_entry,
                    skip_db=agent_persisted,
                )
            else:
                history_len = agent_result.get("history_offset", len(history))
                new_messages = agent_messages[history_len:] if len(agent_messages) > history_len else []

                # If no new messages found (edge case), fall back to simple user/assistant
                if not new_messages:
                    _user_entry = {
                        "role": "user",
                        "content": persisted_message_text,
                        "timestamp": ts,
                    }
                    if event.message_id:
                        _user_entry["message_id"] = str(event.message_id)
                    await self.async_session_store.append_to_transcript(
                        session_entry.session_id,
                        _user_entry,
                        skip_db=agent_persisted,
                    )
                    if response:
                        await self.async_session_store.append_to_transcript(
                            session_entry.session_id,
                            {"role": "assistant", "content": response, "timestamp": ts},
                            skip_db=agent_persisted,
                        )
                else:
                    # The agent already persisted these messages to SQLite via
                    # _flush_messages_to_session_db(), so skip the DB write here
                    # to prevent the duplicate-write bug (#860).  We still write
                    # to JSONL for backward compatibility and as a backup.
                    # Attach the inbound platform message_id to the first user
                    # entry written this turn so platform-level quote-resolution
                    # (e.g. Yuanbao QuoteContextMiddleware's transcript fallback)
                    # can find earlier @bot messages by their original message_id.
                    _user_msg_id_attached = False
                    for msg in new_messages:
                        # Skip system messages (they're rebuilt each run)
                        if msg.get("role") == "system":
                            continue
                        # Add timestamp to each message for debugging
                        entry = {**msg, "timestamp": ts}
                        if (
                            not _user_msg_id_attached
                            and msg.get("role") == "user"
                            and event.message_id
                            and "message_id" not in entry
                        ):
                            entry["message_id"] = str(event.message_id)
                            _user_msg_id_attached = True
                        await self.async_session_store.append_to_transcript(
                            session_entry.session_id, entry,
                            skip_db=agent_persisted,
                        )

            # Token counts and model are now persisted by the agent directly.
            # Keep only last_prompt_tokens here for context-window tracking and
            # compression decisions.
            await self.async_session_store.update_session(
                session_entry.session_key,
                last_prompt_tokens=agent_result.get("last_prompt_tokens", 0),
            )

            # Re-baseline only after every transcript write, including the
            # first-turn session_meta row. Otherwise this process's own writes
            # look like a cross-process mutation on turn two and evict the live
            # cached agent, destroying prompt-prefix caching.
            await self._refresh_agent_cache_message_count(
                session_key,
                session_entry.session_id,
            )

            # Silence markers remain in the transcript for correct turn
            # alternation, but are never published to the user.
            if _intentional_silence:
                logger.info(
                    "Suppressing intentional silence marker for session %s",
                    session_entry.session_id,
                )
                response = ""

            # Auto voice reply: send TTS audio before the text response
            _already_sent = bool(agent_result.get("already_sent"))
            if (
                not getattr(event, "suppress_user_output", False)
                and self._should_send_voice_reply(
                    event,
                    response,
                    agent_messages,
                    already_sent=_already_sent,
                )
            ):
                await self._send_voice_reply(event, response)

            if _already_sent and not agent_result.get("failed"):
                work_item_id = getattr(event, "work_item_id", None)
                turn_feature_summary = _discord_feature_summary_for_turn(
                    source,
                    getattr(event, "feature_summary", None),
                    getattr(event, "discord_runtime_mode", None),
                    getattr(event, "discord_action_request_intent", None),
                )
                turn_project_summary = (
                    getattr(event, "project_summary", None)
                    if _discord_runtime_mode_for(event) is RuntimeMode.ACTION
                    else None
                )
                summary_status = (
                    "Running"
                    if _pending_background_workers
                    else self._discord_ledger_summary_status(
                        work_item_id,
                        self._discord_summary_status(agent_result),
                    )
                )
                summary_ok = False
                if turn_feature_summary or turn_project_summary or work_item_id:
                    summary_ok = await self._update_discord_summaries(
                        source=source,
                        feature_summary=turn_feature_summary,
                        project_summary=turn_project_summary,
                        final_response=response,
                        status=summary_status,
                        session_id=session_entry.session_id,
                        runtime_breakdown=agent_result.get("runtime_breakdown") if isinstance(agent_result, dict) else None,
                    )
                if (
                    work_item_id
                    and source.platform == Platform.DISCORD
                    and summary_ok
                    and not _pending_background_workers
                ):
                    try:
                        expected_run_state = getattr(event, "work_item_run_state", None)
                        if turn_feature_summary or turn_project_summary:
                            if self._ledger().mark_summary_updated(str(work_item_id)) and isinstance(
                                expected_run_state,
                                dict,
                            ):
                                expected_run_state = {
                                    **expected_run_state,
                                    "status": "summary_updated",
                                }
                                event.work_item_run_state = expected_run_state
                        completion_kwargs = {}
                        if isinstance(expected_run_state, dict):
                            completion_kwargs["expected_run_state"] = expected_run_state
                        self._ledger().mark_completed(
                            str(work_item_id),
                            **completion_kwargs,
                        )
                    except Exception as exc:
                        logger.debug("Discord work ledger summary completion update failed: %s", exc)
            else:
                self._register_discord_summary_post_delivery(
                    event=event,
                    source=source,
                    session_key=session_key,
                    run_generation=run_generation,
                    session_id=session_entry.session_id,
                    final_response=response,
                    agent_result=agent_result,
                )

            # If streaming already delivered the response, extract and
            # deliver any MEDIA: files before returning None.  Streaming
            # sends raw text chunks that include MEDIA: tags — the normal
            # post-processing in _process_message_background is skipped
            # when already_sent is True, so media files would never be
            # delivered without this.
            #
            # Never skip when the agent failed — the error message is new
            # content the user hasn't seen (streaming only sent earlier
            # partial output before the failure).  Without this guard,
            # users see the agent "stop responding without explanation."
            if (
                agent_result.get("already_sent")
                and not agent_result.get("failed")
                and not getattr(event, "suppress_user_output", False)
            ):
                if response:
                    _media_adapter = self._adapter_for_source(source)
                    if _media_adapter:
                        await self._deliver_media_from_response(
                            response,
                            event,
                            _media_adapter,
                            message_id=agent_result.get("streamed_message_id"),
                        )
                if meeting_goal_status:
                    try:
                        _status_adapter = self._adapter_for_source(source)
                        if _status_adapter:
                            await _status_adapter.send(
                                source.chat_id,
                                meeting_goal_status,
                                metadata=self._thread_metadata_for_source(source, self._reply_anchor_for_event(event)),
                            )
                    except Exception as _e:
                        logger.debug("meeting auto-goal status send failed: %s", _e)
                if _streaming_gate_notice:
                    try:
                        _gate_adapter = self._adapter_for_source(source)
                        if _gate_adapter:
                            await _gate_adapter.send(
                                source.chat_id,
                                _streaming_gate_notice,
                                metadata=self._thread_metadata_for_source(
                                    source,
                                    self._reply_anchor_for_event(event),
                                ),
                            )
                    except Exception as _e:
                        logger.warning(
                            "enforced visual-QA blocked notice send failed: %s",
                            _e,
                        )
                # Streaming already delivered the body text, but the footer was
                # intentionally held back (see the `not already_sent` gate above).
                # Send it now as a small trailing message so Telegram/Discord/etc.
                # still surface the runtime metadata on the final reply.
                if _footer_line:
                    try:
                        _foot_adapter = self._adapter_for_source(source)
                        if _foot_adapter:
                            await _foot_adapter.send(
                                source.chat_id,
                                _footer_line,
                                metadata=self._thread_metadata_for_source(source, self._reply_anchor_for_event(event)),
                            )
                    except Exception as _e:
                        logger.debug("trailing footer send failed: %s", _e)
                return None

            fable_plan_metadata = getattr(event, "fable_plan_metadata", None)
            if fable_plan_metadata and response and not agent_result.get("failed"):
                return MetadataReply(response, fable_plan_metadata)
            opus_plan_metadata = getattr(event, "opus_plan_metadata", None)
            if opus_plan_metadata and response and not agent_result.get("failed"):
                return MetadataReply(response, opus_plan_metadata)
            return response

        except Exception as e:
            # Stop typing indicator on error too, retaining Slack thread/workspace
            # routing so a failed turn cannot leave its status visible.
            try:
                _err_adapter = self._adapter_for_source(source)
                if _err_adapter and hasattr(_err_adapter, "stop_typing"):
                    await _err_adapter.stop_typing(source.chat_id)
            except Exception:
                pass
            logger.exception("Agent error in session %s", session_key)
            error_type = type(e).__name__
            error_detail = str(e)[:300] if str(e) else "no details available"
            status_hint = ""
            status_code = getattr(e, "status_code", None)
            _hist_len = len(history) if 'history' in locals() else 0
            if status_code == 401:
                status_hint = " Check your API key or run `claude /login` to refresh OAuth credentials."
            elif status_code == 402:
                status_hint = " Your API balance or quota is exhausted. Check your provider dashboard."
            elif status_code == 429:
                # Check if this is a plan usage limit (resets on a schedule) vs a transient rate limit
                _err_body = getattr(e, "response", None)
                _err_json = {}
                try:
                    if _err_body is not None:
                        _err_json = _err_body.json().get("error", {})
                        if not isinstance(_err_json, dict):
                            _err_json = {}
                except Exception:
                    pass
                if _err_json.get("type") == "usage_limit_reached":
                    _resets_in = _err_json.get("resets_in_seconds")
                    if _resets_in and _resets_in > 0:
                        import math
                        _hours = math.ceil(_resets_in / 3600)
                        status_hint = f" Your plan's usage limit has been reached. It resets in ~{_hours}h."
                    else:
                        status_hint = " Your plan's usage limit has been reached. Please wait until it resets."
                else:
                    status_hint = " You are being rate-limited. Please wait a moment and try again."
            elif status_code == 529:
                status_hint = " The API is temporarily overloaded. Please try again shortly."
            elif status_code in {400, 500}:
                # 400 with a large session is context overflow.
                # 500 with a large session often means the payload is too large
                # for the API to process — treat it the same way.
                if _hist_len > 50:
                    return (
                        "⚠️ Session too large for the model's context window.\n"
                        "Use /compact to compress the conversation, or "
                        "/reset to start fresh."
                    )
                elif status_code == 400:
                    status_hint = " The request was rejected by the API."
            return (
                f"Sorry, I encountered an error ({error_type}).\n"
                f"{error_detail}\n"
                f"{status_hint}"
                "Try again or use /reset to start a fresh session."
            )
        finally:
            # Restore session context variables to their pre-handler state
            self._clear_session_env(_session_env_tokens)

    def _reset_notice_session_info(self, source: SessionSource) -> str:
        """Session-info block for the auto-reset notice, profile-scoped.

        When multiplexing, resolve model/provider/context inside the profile
        serving ``source`` — otherwise the banner advertises the base config's
        model while the session actually runs on the profile's (#59003).
        Mirrors ``_run_agent``'s gating so single-profile gateways never
        enter the scope.

        Call via ``asyncio.to_thread`` from async handlers: under the scope,
        resolution can do blocking work (credential refresh, context-length
        HTTP probes) that must not run on the event loop. The scope is entered
        inside this method, so contextvars behave correctly in the worker
        thread.
        """
        if getattr(getattr(self, "config", None), "multiplex_profiles", False):
            with _profile_runtime_scope(self._resolve_profile_home_for_source(source)):
                return self._format_session_info()
        return self._format_session_info()

    def _format_session_info(self) -> str:
        """Resolve current model config and return a formatted info block.

        Surfaces model, provider, context length, and endpoint so gateway
        users can immediately see if context detection went wrong (e.g.
        local models falling to the 128K default).
        """
        from agent.model_metadata import get_model_context_length, DEFAULT_FALLBACK_CONTEXT

        model = _resolve_gateway_model()
        config_context_length = None
        provider = None
        base_url = None
        api_key = None
        custom_provs = None
        data = None

        try:
            data = _load_gateway_config()
            if data:
                model_cfg = data.get("model", {})
                if isinstance(model_cfg, dict):
                    raw_ctx = model_cfg.get("context_length")
                    if raw_ctx is not None:
                        try:
                            config_context_length = int(raw_ctx)
                        except (TypeError, ValueError):
                            pass
                    provider = model_cfg.get("provider") or None
                    base_url = model_cfg.get("base_url") or None
                try:
                    from hermes_cli.config import get_compatible_custom_providers
                    custom_provs = get_compatible_custom_providers(data)
                except Exception:
                    custom_provs = data.get("custom_providers")
        except Exception:
            pass

        # Also check custom_providers for context_length when top-level model.context_length is not set
        if config_context_length is None and data:
            try:
                custom_providers = data.get("custom_providers", [])
                if custom_providers:
                    for cp in custom_providers:
                        if not isinstance(cp, dict):
                            continue
                        cp_model = cp.get("model") or ""
                        cp_models = cp.get("models") or {}
                        # Match provider model to current model
                        if cp_model and cp_model == model:
                            raw_cp_ctx = cp.get("context_length")
                            if raw_cp_ctx is not None:
                                try:
                                    config_context_length = int(raw_cp_ctx)
                                    break
                                except (TypeError, ValueError):
                                    pass
                        # Also check per-model context_length
                        if isinstance(cp_models, dict):
                            model_entry = cp_models.get(model)
                            if isinstance(model_entry, dict):
                                model_ctx = model_entry.get("context_length")
                            else:
                                model_ctx = model_entry
                            if model_ctx is not None and isinstance(model_ctx, (int, float)):
                                try:
                                    config_context_length = int(model_ctx)
                                    break
                                except (TypeError, ValueError):
                                    pass
            except Exception:
                pass

        # Resolve runtime credentials for probing
        try:
            runtime = _resolve_runtime_agent_kwargs()
            provider = provider or runtime.get("provider")
            base_url = base_url or runtime.get("base_url")
            api_key = runtime.get("api_key")
        except Exception:
            pass

        context_length = get_model_context_length(
            model,
            base_url=base_url or "",
            api_key=api_key or "",
            config_context_length=config_context_length,
            provider=provider or "",
            custom_providers=custom_provs,
        )

        # Format context source hint
        if config_context_length is not None:
            ctx_source = "config"
        elif context_length == DEFAULT_FALLBACK_CONTEXT:
            ctx_source = "default — set model.context_length in config to override"
        else:
            ctx_source = "detected"

        # Format context length for display
        if context_length >= 1_000_000:
            ctx_display = f"{context_length / 1_000_000:.1f}M"
        elif context_length >= 1_000:
            ctx_display = f"{context_length // 1_000}K"
        else:
            ctx_display = str(context_length)

        lines = [
            f"◆ Model: `{model}`",
            f"◆ Provider: {provider or 'openrouter'}",
            f"◆ Context: {ctx_display} tokens ({ctx_source})",
        ]

        # Show endpoint for local/custom setups
        if base_url and ("localhost" in base_url or "127.0.0.1" in base_url or "0.0.0.0" in base_url):
            lines.append(f"◆ Endpoint: {base_url}")

        return "\n".join(lines)

    async def _handle_reset_command(self, event: MessageEvent) -> Union[str, EphemeralReply]:
        """Handle /new or /reset command."""
        source = event.source

        # Get existing session key
        session_key = self._session_key_for_source(source)
        self._invalidate_session_run_generation(session_key, reason="session_reset")

        # Snapshot the old entry so on_session_finalize can report the
        # expiring session id before reset_session() rotates it.
        old_entry = self.session_store._entries.get(session_key)

        # Close tool resources on the old agent (terminal sandboxes, browser
        # daemons, background processes) before evicting from cache.
        # Guard with getattr because test fixtures may skip __init__.
        _cache_lock = getattr(self, "_agent_cache_lock", None)
        if _cache_lock is not None:
            with _cache_lock:
                _cached = self._agent_cache.get(session_key)
                _old_agent = _cached[0] if isinstance(_cached, tuple) else _cached if _cached else None
            if _old_agent is not None:
                self._cleanup_agent_resources(_old_agent)
        self._evict_cached_agent(session_key)

        # Discard any /queue overflow for this session — /new is a
        # conversation-boundary operation, queued follow-ups from the
        # previous conversation must not bleed into the new one.
        _qe = getattr(self, "_queued_events", None)
        if _qe is not None:
            _qe.pop(session_key, None)

        try:
            from tools.env_passthrough import clear_env_passthrough
            clear_env_passthrough()
        except Exception:
            pass

        try:
            from tools.credential_files import clear_credential_files
            clear_credential_files()
        except Exception:
            pass

        # Reset the session
        new_entry = await self.async_session_store.reset_session(session_key)

        # Clear any session-scoped model/reasoning overrides so the next agent
        # picks up configured defaults instead of previous session switches.
        self._session_model_overrides.pop(session_key, None)
        self._set_session_reasoning_override(session_key, None)
        if hasattr(self, "_pending_model_notes"):
            self._pending_model_notes.pop(session_key, None)

        # Clear session-scoped dangerous-command approvals and /yolo state.
        # /new is a conversation-boundary operation — approval state from the
        # previous conversation must not survive the reset.
        self._clear_session_boundary_security_state(session_key)

        # Fire plugin on_session_finalize hook (session boundary)
        try:
            from hermes_cli.plugins import invoke_hook as _invoke_hook
            _old_sid = old_entry.session_id if old_entry else None
            _invoke_hook("on_session_finalize", session_id=_old_sid,
                         platform=source.platform.value if source.platform else "")
        except Exception:
            pass

        # Emit session:end hook (session is ending)
        await self.hooks.emit("session:end", {
            "platform": source.platform.value if source.platform else "",
            "user_id": source.user_id,
            "session_key": session_key,
        })

        # Emit session:reset hook
        await self.hooks.emit("session:reset", {
            "platform": source.platform.value if source.platform else "",
            "user_id": source.user_id,
            "session_key": session_key,
        })

        # Resolve session config info to surface to the user
        try:
            session_info = self._format_session_info()
        except Exception:
            session_info = ""

        if new_entry:
            header = await asyncio.to_thread(self._telegram_topic_new_header, source) or t("gateway.reset.header_default")
        else:
            # No existing session, just create one
            new_entry = await self.async_session_store.get_or_create_session(source, force_new=True)
            header = await asyncio.to_thread(self._telegram_topic_new_header, source) or t("gateway.reset.header_new")

        # Set session title if provided with /new <title>
        _title_arg = event.get_command_args().strip()
        _title_note = ""
        if _title_arg and self._session_db and new_entry:
            from hermes_state import SessionDB
            try:
                sanitized = SessionDB.sanitize_title(_title_arg)
            except ValueError as e:
                sanitized = None
                _title_note = t("gateway.reset.title_rejected", error=str(e))
            if sanitized:
                try:
                    await self._session_db.set_session_title(new_entry.session_id, sanitized)
                    header = t("gateway.reset.header_titled", title=sanitized)
                except ValueError as e:
                    _title_note = t("gateway.reset.title_error_untitled", error=str(e))
                except Exception:
                    pass
            elif not _title_note:
                # sanitize_title returned empty (whitespace-only / unprintable)
                _title_note = t("gateway.reset.title_empty_untitled")
        header = header + _title_note

        # When /new runs inside a Telegram DM topic lane, rewrite the
        # (chat_id, thread_id) → session_id binding so the next message
        # uses the freshly-created session. Without this, the binding
        # still points at the old session and the binding-lookup at the
        # top of _handle_message_with_agent would switch right back.
        if await asyncio.to_thread(self._is_telegram_topic_lane, source) and new_entry is not None:
            try:
                await asyncio.to_thread(self._record_telegram_topic_binding, source, new_entry)
            except Exception:
                logger.debug("Failed to rebind Telegram topic after /new", exc_info=True)

        # Fire plugin on_session_reset hook (new session guaranteed to exist)
        try:
            from hermes_cli.plugins import invoke_hook as _invoke_hook
            _new_sid = new_entry.session_id if new_entry else None
            _invoke_hook("on_session_reset", session_id=_new_sid,
                         platform=source.platform.value if source.platform else "")
        except Exception:
            pass

        # Append a random tip to the reset message
        try:
            from hermes_cli.tips import get_random_tip
            _tip_line = t("gateway.reset.tip", tip=get_random_tip())
        except Exception:
            _tip_line = ""

        if session_info:
            return EphemeralReply(f"{header}\n\n{session_info}{_tip_line}")
        return EphemeralReply(f"{header}{_tip_line}")

    async def _handle_profile_command(self, event: MessageEvent) -> str:
        """Handle /profile — show active profile name and home directory."""
        from hermes_constants import display_hermes_home
        from hermes_cli.profiles import get_active_profile_name

        display = display_hermes_home()
        profile_name = get_active_profile_name()

        lines = [
            t("gateway.profile.header", profile=profile_name),
            t("gateway.profile.home", home=display),
        ]

        return "\n".join(lines)


    def _check_slash_access(
        self, source: SessionSource, canonical_cmd: str
    ) -> Optional[str]:
        """Return a denial message if ``source`` cannot run ``canonical_cmd``,
        else None. Used by both the cold and running-agent dispatch paths
        in ``_handle_message`` so admin/user gating can't be bypassed by
        an in-flight agent.

        Backward-compat semantics live in
        :func:`gateway.slash_access.policy_for_source` — when the operator
        hasn't set ``allow_admin_from`` for the scope, the policy returns
        ``enabled=False`` and this method always returns None.
        """
        from gateway.slash_access import policy_for_source as _policy_for_source

        if not canonical_cmd:
            return None
        policy = _policy_for_source(self.config, source)
        if not policy.enabled or policy.can_run(source.user_id, canonical_cmd):
            return None
        logger.info(
            "Slash command /%s denied for %s:%s (not admin, not in user_allowed_commands)",
            canonical_cmd,
            source.platform.value if source.platform else "?",
            source.user_id,
        )
        allowed_preview = sorted(policy.user_allowed_commands)
        if allowed_preview:
            suffix = (
                "You can run: "
                + ", ".join(f"/{c}" for c in allowed_preview[:12])
                + ("…" if len(allowed_preview) > 12 else "")
                + ". Use /whoami for the full list."
            )
        else:
            suffix = (
                "No slash commands are enabled for non-admins on this "
                "platform. Ask an admin to add you to allow_admin_from "
                "or to set user_allowed_commands."
            )
        return f"⛔ /{canonical_cmd} is admin-only here. {suffix}"


    async def _handle_whoami_command(self, event: MessageEvent) -> str:
        """Handle /whoami — show the user's slash command access on this scope.

        Always works (it's in the always-allowed floor of slash_access).
        Reports: platform, scope (DM vs group), the user's tier
        (admin / user / unrestricted), and the slash commands they can
        actually run on this scope.
        """
        from gateway.slash_access import policy_for_source as _policy_for_source

        source = event.source
        policy = _policy_for_source(self.config, source)
        platform = source.platform.value if source and source.platform else "?"
        chat_type = (source.chat_type if source else "") or "dm"
        scope = "DM" if chat_type.lower() in {"dm", "direct", "private", ""} else "group/channel"
        user_id = (source.user_id if source else None) or "?"

        if not policy.enabled:
            return (
                f"**You** — {platform} ({scope})\n"
                f"User ID: `{user_id}`\n"
                f"Tier: unrestricted (no admin list configured for this scope)\n"
                f"Slash commands: all available"
            )

        if policy.is_admin(user_id):
            return (
                f"**You** — {platform} ({scope})\n"
                f"User ID: `{user_id}`\n"
                f"Tier: **admin**\n"
                f"Slash commands: all available"
            )

        # Non-admin user. Show what's actually reachable.
        floor = ["help", "whoami"]  # mirrors slash_access._ALWAYS_ALLOWED_FOR_USERS
        configured = sorted(policy.user_allowed_commands)
        # Combine + dedupe, preserve order: floor first, then operator additions.
        seen: set[str] = set()
        runnable: list[str] = []
        for c in floor + configured:
            if c not in seen:
                seen.add(c)
                runnable.append(c)
        runnable_str = ", ".join(f"/{c}" for c in runnable) if runnable else "(none)"
        return (
            f"**You** — {platform} ({scope})\n"
            f"User ID: `{user_id}`\n"
            f"Tier: user\n"
            f"Slash commands you can run: {runnable_str}"
        )


    async def _handle_kanban_command(self, event: MessageEvent) -> str:
        """Handle /kanban — delegate to the shared kanban CLI.

        Run the potentially-blocking DB work in a thread pool so the
        gateway event loop stays responsive.  Read operations (list,
        show, context, tail) are permitted while an agent is running;
        mutations are allowed too because the board is profile-agnostic
        and does not touch the running agent's state.

        For ``/kanban create`` invocations we also auto-subscribe the
        originating gateway source (platform + chat + thread) to the new
        task's terminal events, so the user hears back when the worker
        completes / blocks / auto-blocks / crashes without having to poll.
        """
        import asyncio
        import re
        import shlex
        from hermes_cli.kanban import run_slash

        text = (event.text or "").strip()
        # Strip the leading "/kanban" (with or without slash), leaving args.
        if text.startswith("/"):
            text = text.lstrip("/")
        if text.startswith("kanban"):
            text = text[len("kanban"):].lstrip()

        tokens = shlex.split(text) if text else []
        requested_board = None
        action = None
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok == "--board":
                if i + 1 >= len(tokens):
                    break
                requested_board = tokens[i + 1]
                i += 2
                continue
            if tok.startswith("--board="):
                requested_board = tok.split("=", 1)[1]
                i += 1
                continue
            action = tok
            break

        is_create = action == "create"

        try:
            output = await asyncio.to_thread(run_slash, text)
        except Exception as exc:  # pragma: no cover - defensive
            return t("gateway.kanban.error_prefix", error=exc)

        # Auto-subscribe on create. Parse the task id from the CLI's standard
        # success line ("Created t_abcd  (ready, assignee=...)"). If the user
        # passed --json we don't subscribe; they're clearly scripting and
        # can call /kanban notify-subscribe explicitly.
        if is_create and output:
            m = re.search(r"Created\s+(t_[0-9a-f]+)\b", output)
            if m:
                task_id = m.group(1)
                try:
                    source = event.source
                    platform = getattr(source, "platform", None)
                    platform_str = (
                        platform.value if hasattr(platform, "value") else str(platform or "")
                    ).lower()
                    chat_id = str(getattr(source, "chat_id", "") or "")
                    thread_id = str(getattr(source, "thread_id", "") or "")
                    user_id = str(getattr(source, "user_id", "") or "") or None
                    user_id_alt = str(getattr(source, "user_id_alt", "") or "") or None
                    delivery_metadata = self._thread_metadata_for_source(
                        source, str(getattr(event, "message_id", "") or "") or None
                    ) or {}
                    chat_type = str(getattr(source, "chat_type", "") or "") or None
                    if chat_type:
                        delivery_metadata["chat_type"] = chat_type
                    if platform_str and chat_id:
                        def _sub():
                            from hermes_cli import kanban_db as _kb
                            conn = _kb.connect(board=requested_board)
                            try:
                                _kb.add_notify_sub(
                                    conn, task_id=task_id,
                                    platform=platform_str, chat_id=chat_id,
                                    thread_id=thread_id or None,
                                    user_id=user_id,
                                    user_id_alt=user_id_alt,
                                    chat_type=chat_type,
                                    delivery_metadata=delivery_metadata,
                                    notifier_profile=getattr(self, "_kanban_notifier_profile", None) or self._active_profile_name(),
                                )
                            finally:
                                conn.close()
                        await asyncio.to_thread(_sub)
                        output = (
                            output.rstrip()
                            + "\n"
                            + t("gateway.kanban.subscribed_suffix", task_id=task_id)
                        )
                except Exception as exc:
                    logger.warning("kanban create auto-subscribe failed: %s", exc)

        # Gateway messages have practical length caps; truncate long
        # listings to keep the UX reasonable.
        if len(output) > 3800:
            output = output[:3800] + "\n" + t("gateway.kanban.truncated_suffix")
        return output or t("gateway.kanban.no_output")

    async def _handle_status_command(self, event: MessageEvent) -> str:
        """Handle /status command."""
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)

        connected_platforms = [p.value for p in self.adapters.keys()]

        # Check if there's an active agent
        session_key = session_entry.session_key
        is_running = session_key in self._running_agents

        # Count pending /queue follow-ups (slot + overflow).
        adapter = self._adapter_for_source(source) if source else None
        queue_depth = self._queue_depth(session_key, adapter=adapter)

        title = None
        # Pull token totals from the SQLite session DB rather than the
        # in-memory SessionStore.  The agent's per-turn token deltas are
        # persisted into sessions_db (run_agent.py), not into SessionEntry,
        # so session_entry.total_tokens is always 0.  SessionDB is the
        # single source of truth; reading it here keeps /status accurate
        # without duplicating token writes into two stores.
        db_total_tokens = 0
        if self._session_db:
            try:
                title = await self._session_db.get_session_title(session_entry.session_id)
            except Exception:
                title = None
            try:
                row = await self._session_db.get_session(session_entry.session_id)
                if row:
                    db_total_tokens = (
                        (row.get("input_tokens") or 0)
                        + (row.get("output_tokens") or 0)
                        + (row.get("cache_read_tokens") or 0)
                        + (row.get("cache_write_tokens") or 0)
                        + (row.get("reasoning_tokens") or 0)
                    )
            except Exception:
                db_total_tokens = 0

        lines = [
            t("gateway.status.header"),
            "",
            t("gateway.status.session_id", session_id=session_entry.session_id),
        ]
        if title:
            lines.append(t("gateway.status.title", title=title))
        lines.extend([
            t("gateway.status.created", timestamp=session_entry.created_at.strftime('%Y-%m-%d %H:%M')),
            t("gateway.status.last_activity", timestamp=session_entry.updated_at.strftime('%Y-%m-%d %H:%M')),
            t("gateway.status.tokens", tokens=f"{db_total_tokens:,}"),
            t("gateway.status.agent_running", state=t("gateway.status.state_yes") if is_running else t("gateway.status.state_no")),
        ])
        if queue_depth:
            lines.append(t("gateway.status.queued", count=queue_depth))
        lines.extend([
            "",
            t("gateway.status.platforms", platforms=', '.join(connected_platforms)),
        ])

        # Session recap — what was this session ABOUT? Pure local compute,
        # no LLM call, no prompt-cache impact. Useful when juggling multiple
        # gateway sessions and you want a one-glance reminder of where this
        # one left off. Inspired by Claude Code 2.1.114's /recap.
        try:
            from hermes_cli.session_recap import build_recap
            history = await self.async_session_store.load_transcript(session_entry.session_id)
            recap = build_recap(
                history,
                session_title=title,
                session_id=session_entry.session_id,
                platform=source.platform.value if source else None,
            )
            if recap:
                lines.extend(["", recap])
        except Exception as exc:  # pragma: no cover — defensive
            logger.debug("build_recap failed in /status: %s", exc)

        return "\n".join(lines)

    async def _handle_agents_command(self, event: MessageEvent) -> str:
        """Handle /agents command - list active agents and running tasks."""
        from tools.process_registry import format_uptime_short, process_registry

        now = time.time()
        current_session_key = self._session_key_for_source(event.source)

        running_agents: dict = getattr(self, "_running_agents", {}) or {}
        running_started: dict = getattr(self, "_running_agents_ts", {}) or {}

        agent_rows: list[dict] = []
        for session_key, agent in running_agents.items():
            started = float(running_started.get(session_key, now))
            elapsed = max(0, int(now - started))
            is_pending = agent is _AGENT_PENDING_SENTINEL
            agent_rows.append(
                {
                    "session_key": session_key,
                    "elapsed": elapsed,
                    "state": t("gateway.agents.state_starting") if is_pending else t("gateway.agents.state_running"),
                    "session_id": "" if is_pending else str(getattr(agent, "session_id", "") or ""),
                    "model": "" if is_pending else str(getattr(agent, "model", "") or ""),
                }
            )

        agent_rows.sort(key=lambda row: row["elapsed"], reverse=True)

        running_processes: list[dict] = []
        try:
            running_processes = [
                p for p in process_registry.list_sessions()
                if p.get("status") == "running"
            ]
        except Exception:
            running_processes = []

        background_tasks = [
            t for t in (getattr(self, "_background_tasks", set()) or set())
            if hasattr(t, "done") and not t.done()
        ]

        lines = [
            t("gateway.agents.header"),
            "",
            t("gateway.agents.active_agents", count=len(agent_rows)),
        ]

        if agent_rows:
            for idx, row in enumerate(agent_rows[:12], 1):
                current = t("gateway.agents.this_chat") if row["session_key"] == current_session_key else ""
                sid = f" · `{row['session_id']}`" if row["session_id"] else ""
                model = f" · `{row['model']}`" if row["model"] else ""
                lines.append(
                    f"{idx}. `{row['session_key']}` · {row['state']} · "
                    f"{format_uptime_short(row['elapsed'])}{sid}{model}{current}"
                )
            if len(agent_rows) > 12:
                lines.append(t("gateway.agents.more", count=len(agent_rows) - 12))

        lines.extend(
            [
                "",
                t("gateway.agents.running_processes", count=len(running_processes)),
            ]
        )
        if running_processes:
            for proc in running_processes[:12]:
                cmd = " ".join(str(proc.get("command", "")).split())
                if len(cmd) > 90:
                    cmd = cmd[:87] + "..."
                lines.append(
                    f"- `{proc.get('session_id', '?')}` · "
                    f"{format_uptime_short(int(proc.get('uptime_seconds', 0)))} · `{cmd}`"
                )
            if len(running_processes) > 12:
                lines.append(t("gateway.agents.more", count=len(running_processes) - 12))

        lines.extend(
            [
                "",
                t("gateway.agents.async_jobs", count=len(background_tasks)),
            ]
        )

        if not agent_rows and not running_processes and not background_tasks:
            lines.append("")
            lines.append(t("gateway.agents.none"))

        return "\n".join(lines)

    async def _stop_discord_thread_boards_for_event(self, event: MessageEvent) -> list[str]:
        """Best-effort /stop bridge from a Discord thread to worker board halt."""

        def _stop() -> list[str]:
            from hermes_cli import discord_worker_boards as _dwb

            stopped: list[str] = []
            for board in _dwb.stoppable_boards_for_gateway_event(event):
                _dwb.stop_board_execution(board.slug, reason="slash-stop")
                stopped.append(board.slug)
            return stopped

        try:
            stopped = await asyncio.to_thread(_stop)
        except Exception as exc:
            logger.debug("Discord worker board /stop bridge failed: %s", exc, exc_info=True)
            return []
        if stopped:
            self._signal_kanban_dispatcher_dirty()
        return stopped

    async def _handle_stop_command(self, event: MessageEvent) -> Union[str, EphemeralReply]:
        """Handle /stop command - interrupt a running agent.

        When an agent is truly hung (blocked thread that never checks
        _interrupt_requested), the early intercept in _handle_message()
        handles /stop before this method is reached.  This handler fires
        only through normal command dispatch (no running agent) or as a
        fallback.  Force-clean the session lock in all cases for safety.

        The session is preserved so the user can continue the conversation.
        """
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)
        session_key = session_entry.session_key
        stopped_boards = await self._stop_discord_thread_boards_for_event(event)

        agent = self._running_agents.get(session_key)
        if agent is _AGENT_PENDING_SENTINEL:
            # Force-clean the sentinel so the session is unlocked.
            await self._interrupt_and_clear_session(
                session_key,
                source,
                interrupt_reason=_INTERRUPT_REASON_STOP,
                invalidation_reason="stop_command_pending",
                cleanup_background_processes=True,
            )
            logger.info("STOP (pending) for session %s — sentinel cleared", session_key)
            return EphemeralReply(t("gateway.stop.stopped_pending"))
        if agent:
            # Force-clean the session lock so a truly hung agent doesn't
            # keep it locked forever.
            await self._interrupt_and_clear_session(
                session_key,
                source,
                interrupt_reason=_INTERRUPT_REASON_STOP,
                invalidation_reason="stop_command_handler",
                cleanup_background_processes=True,
            )
            return EphemeralReply(t("gateway.stop.stopped"))
        stopped_required = self._stop_required_async_for_session(session_key)
        stopped_processes = self._stop_session_background_processes(session_key)
        if stopped_boards or stopped_processes or stopped_required:
            logger.info(
                "STOP for session %s — Discord worker boards stopped: %s, background_processes_stopped=%d, required_async_stopped=%d",
                session_key,
                ",".join(stopped_boards) if stopped_boards else "-",
                stopped_processes,
                stopped_required,
            )
            return EphemeralReply(t("gateway.stop.stopped"))
        return t("gateway.stop.no_active")

    async def _handle_platform_command(self, event: MessageEvent) -> str:
        """Handle ``/platform list|pause|resume [name]`` — surface and
        manually control failed/paused gateway adapters.

        Examples:
            ``/platform list``           — show connected + failed/paused platforms
            ``/platform pause whatsapp`` — stop the reconnect watcher hammering whatsapp
            ``/platform resume whatsapp`` — re-queue a paused platform for retry
        """
        text = (getattr(event, "content", "") or "").strip()
        # Strip the leading "/platform" (or "/PLATFORM") token if present
        parts = text.split(maxsplit=2)
        if parts and parts[0].lower().lstrip("/").startswith("platform"):
            parts = parts[1:]
        action = (parts[0] if parts else "list").lower()
        target = parts[1].lower() if len(parts) > 1 else ""

        # Resolve platform name (case-insensitive, value match)
        def _resolve_platform(name: str):
            if not name:
                return None
            for p in Platform.__members__.values():
                if p.value.lower() == name:
                    return p
            return None

        if action == "list":
            lines = ["**Gateway platforms**"]
            connected = sorted(p.value for p in self.adapters.keys())
            if connected:
                lines.append("Connected: " + ", ".join(connected))
            else:
                lines.append("Connected: (none)")
            failed = getattr(self, "_failed_platforms", {}) or {}
            if failed:
                for p, info in failed.items():
                    if info.get("paused"):
                        reason = info.get("pause_reason") or "paused"
                        lines.append(
                            f"  · {p.value} — PAUSED ({reason}). "
                            f"Resume with `/platform resume {p.value}`."
                        )
                    else:
                        attempts = info.get("attempts", 0)
                        lines.append(
                            f"  · {p.value} — retrying (attempt {attempts})"
                        )
            else:
                lines.append("Failed/paused: (none)")
            return "\n".join(lines)

        if action in {"pause", "resume"}:
            if not target:
                return f"Usage: /platform {action} <name>"
            platform = _resolve_platform(target)
            if platform is None:
                return f"Unknown platform: {target}"
            failed = getattr(self, "_failed_platforms", {}) or {}
            if action == "pause":
                if platform not in failed:
                    return (
                        f"{platform.value} is not in the retry queue "
                        f"(it's either connected or not enabled)."
                    )
                if failed[platform].get("paused"):
                    return f"{platform.value} is already paused."
                self._pause_failed_platform(platform, reason="paused via /platform pause")
                return (
                    f"✓ {platform.value} paused. "
                    f"Resume with `/platform resume {platform.value}` or "
                    f"`hermes gateway restart` to reset."
                )
            # action == "resume"
            if platform not in failed:
                return (
                    f"{platform.value} is not in the retry queue — "
                    f"nothing to resume."
                )
            if not failed[platform].get("paused"):
                return (
                    f"{platform.value} is already retrying — "
                    f"no resume needed."
                )
            self._resume_paused_platform(platform)
            return f"✓ {platform.value} resumed — retrying on next watcher tick."

        return (
            "Usage: /platform <list|pause|resume> [name]\n"
            "  /platform list — show platform status\n"
            "  /platform pause <name> — stop retrying a failing platform\n"
            "  /platform resume <name> — re-queue a paused platform"
        )

    async def _handle_restart_command(self, event: MessageEvent) -> Union[str, EphemeralReply]:
        """Handle /restart command - drain active work, then restart the gateway."""
        # Defensive idempotency check: if the previous gateway process
        # recorded this same /restart (same platform + update_id) and the new
        # process is seeing it *again*, this is a re-delivery caused by PTB's
        # graceful-shutdown `get_updates` ACK failing on the way out ("Error
        # while calling `get_updates` one more time to mark all fetched
        # updates. Suppressing error to ensure graceful shutdown. When
        # polling for updates is restarted, updates may be received twice."
        # in gateway.log).  Ignoring the stale redelivery prevents a
        # self-perpetuating restart loop where every fresh gateway
        # re-processes the same /restart command and immediately restarts
        # again.
        if self._is_stale_restart_redelivery(event):
            logger.info(
                "Ignoring redelivered /restart (platform=%s, update_id=%s) — "
                "already processed by a previous gateway instance.",
                event.source.platform.value if event.source and event.source.platform else "?",
                event.platform_update_id,
            )
            return ""

        if self._restart_requested or self._draining:
            count = self._running_agent_count()
            if count:
                return t("gateway.draining", count=count)
            return EphemeralReply(t("gateway.restart.in_progress"))

        # Save the requester's routing info so the new gateway process can
        # notify them once it comes back online.
        try:
            notify_data = {
                "platform": event.source.platform.value if event.source.platform else None,
                "chat_id": event.source.chat_id,
            }
            if event.source.thread_id:
                notify_data["thread_id"] = event.source.thread_id
            atomic_json_write(
                _hermes_home / ".restart_notify.json",
                notify_data,
                indent=None,
            )
        except Exception as e:
            logger.debug("Failed to write restart notify file: %s", e)

        # Record the triggering platform + update_id in a dedicated dedup
        # marker.  Unlike .restart_notify.json (which gets unlinked once the
        # new gateway sends the "gateway restarted" notification), this
        # marker persists so the new gateway can still detect a delayed
        # /restart redelivery from Telegram.  Overwritten on every /restart.
        try:
            dedup_data = {
                "platform": event.source.platform.value if event.source.platform else None,
                "requested_at": time.time(),
            }
            if event.platform_update_id is not None:
                dedup_data["update_id"] = event.platform_update_id
            atomic_json_write(
                _hermes_home / ".restart_last_processed.json",
                dedup_data,
                indent=None,
            )
        except Exception as e:
            logger.debug("Failed to write restart dedup marker: %s", e)

        active_agents = self._running_agent_count()
        # When running under a service manager (systemd/launchd) or inside a
        # Docker/Podman container, use the service restart path: exit with
        # code 75 so the service manager / container restart policy restarts
        # us.  The detached subprocess approach (setsid + bash) doesn't work
        # under systemd (KillMode=mixed kills the cgroup) or Docker (tini
        # exits when the gateway dies, taking the detached helper with it).
        _under_service = bool(os.environ.get("INVOCATION_ID"))  # systemd sets this
        _in_container = os.path.exists("/.dockerenv") or os.path.exists("/run/.containerenv")
        if _under_service or _in_container:
            self.request_restart(detached=False, via_service=True)
        else:
            self.request_restart(detached=True, via_service=False)
        if active_agents:
            return t("gateway.draining", count=active_agents)
        return EphemeralReply(t("gateway.restart.restarting"))

    def _is_stale_restart_redelivery(self, event: MessageEvent) -> bool:
        """Return True if this /restart is a Telegram re-delivery we already handled.

        The previous gateway wrote ``.restart_last_processed.json`` with the
        triggering platform + update_id when it processed the /restart.  If
        we now see a /restart on the same platform with an update_id <= that
        recorded value, it is a redelivery when this process booted from that
        restart. Otherwise the marker must still be recent (< 5 minutes).

        Only applies to Telegram today (the only platform that exposes a
        numeric cross-session update ordering); other platforms return False.
        """
        if event is None or event.source is None:
            return False
        if event.platform_update_id is None:
            return False
        if event.source.platform is None:
            return False
        # Only Telegram populates platform_update_id currently; be explicit
        # so future platforms aren't accidentally gated by this check.
        try:
            platform_value = event.source.platform.value
        except Exception:
            return False
        if platform_value != "telegram":
            return False

        try:
            marker_path = _hermes_home / ".restart_last_processed.json"
            if not marker_path.exists():
                # If this process was demonstrably booted by a chat /restart,
                # suppress one same-window redelivery even when the durable
                # update-id marker went missing. A genuine fresh boot leaves the
                # flag false, so its first /restart is never swallowed.
                if (
                    getattr(self, "_booted_from_restart", False)
                    and time.time() - getattr(self, "_startup_time", 0.0) < 60
                ):
                    self._booted_from_restart = False
                    return True
                return False
            data = json.loads(marker_path.read_text())
        except Exception:
            return False

        if data.get("platform") != platform_value:
            return False
        recorded_uid = data.get("update_id")
        if not isinstance(recorded_uid, int):
            return False
        if event.platform_update_id > recorded_uid:
            return False

        # A service-managed restart can legitimately take longer than the
        # marker's normal five-minute trust window while adapters, cron, and
        # in-flight deliveries drain. If this process booted from the recorded
        # chat restart, the first same-or-older update is still that restart's
        # redelivery regardless of elapsed wall time. Consume the boot signal
        # one-shot so a later genuine command is evaluated normally.
        if getattr(self, "_booted_from_restart", False):
            self._booted_from_restart = False
            return True

        # Staleness guard: ignore markers older than 5 minutes.  A legitimately
        # old marker (e.g. crash recovery where notify never fired) should not
        # swallow a fresh /restart from the user.
        requested_at = data.get("requested_at")
        if isinstance(requested_at, (int, float)):
            if time.time() - requested_at > 300:
                return False
        return True


    async def _handle_help_command(self, event: MessageEvent) -> str:
        """Handle /help command - list available commands."""
        from hermes_cli.commands import gateway_help_lines
        platform_name = str(
            getattr(getattr(event, "source", None), "platform", "") or ""
        ).lower()
        if platform_name.startswith("platform."):
            platform_name = platform_name.rsplit(".", 1)[-1]
        lines = [
            t("gateway.help.header"),
            *gateway_help_lines(platform_name),
        ]
        try:
            from agent.skill_commands import get_skill_commands
            skill_cmds = get_skill_commands()
            if skill_cmds:
                lines.append(t("gateway.help.skill_header", count=len(skill_cmds)))
                # Show first 10, then point to /commands for the rest
                sorted_cmds = sorted(skill_cmds)
                for cmd in sorted_cmds[:10]:
                    lines.append(f"`{cmd}` — {skill_cmds[cmd]['description']}")
                if len(sorted_cmds) > 10:
                    lines.append(t("gateway.help.more_use_commands", count=len(sorted_cmds) - 10))
        except Exception:
            pass
        return _telegramize_command_mentions(
            "\n".join(lines),
            getattr(getattr(event, "source", None), "platform", None),
        )

    async def _handle_commands_command(self, event: MessageEvent) -> str:
        from hermes_cli.commands import gateway_help_lines

        raw_args = event.get_command_args().strip()
        if raw_args:
            try:
                requested_page = int(raw_args)
            except ValueError:
                return t("gateway.commands.usage")
        else:
            requested_page = 1

        # Build combined entry list: built-in commands + skill commands
        platform_name = str(getattr(event.source, "platform", "") or "").lower()
        if platform_name.startswith("platform."):
            platform_name = platform_name.rsplit(".", 1)[-1]
        entries = list(gateway_help_lines(platform_name))
        try:
            from agent.skill_commands import get_skill_commands
            skill_cmds = get_skill_commands()
            if skill_cmds:
                entries.append("")
                entries.append(t("gateway.commands.skill_header"))
                for cmd in sorted(skill_cmds):
                    desc = skill_cmds[cmd].get("description", "").strip() or t("gateway.commands.default_desc")
                    entries.append(f"`{cmd}` — {desc}")
        except Exception:
            pass

        if not entries:
            return t("gateway.commands.none")

        from gateway.config import Platform
        page_size = 15 if event.source.platform == Platform.TELEGRAM else 20
        total_pages = max(1, (len(entries) + page_size - 1) // page_size)
        page = max(1, min(requested_page, total_pages))
        start = (page - 1) * page_size
        page_entries = entries[start:start + page_size]

        lines = [
            t("gateway.commands.header", total=len(entries), page=page, total_pages=total_pages),
            "",
            *page_entries,
        ]
        if total_pages > 1:
            nav_parts = []
            if page > 1:
                nav_parts.append(t("gateway.commands.nav_prev", page=page - 1))
            if page < total_pages:
                nav_parts.append(t("gateway.commands.nav_next", page=page + 1))
            lines.extend(["", " | ".join(nav_parts)])
        if page != requested_page:
            lines.append(t("gateway.commands.out_of_range", requested=requested_page, page=page))
        return _telegramize_command_mentions(
            "\n".join(lines),
            getattr(getattr(event, "source", None), "platform", None),
        )

    async def _handle_model_command(self, event: MessageEvent) -> Optional[str]:
        """Handle /model command — switch model for this session.

        Supports:
          /model                              — interactive picker (Telegram/Discord) or text list
          /model <name>                       — switch for this session only
          /model <name> --global              — switch and persist to config.yaml
          /model <name> --provider <provider> — switch provider + model
          /model --provider <provider>        — switch to provider, auto-detect model
        """
        import yaml
        from hermes_cli.model_switch import (
            switch_model as _switch_model, parse_model_flags,
            resolve_persist_behavior,
            list_authenticated_providers,
            list_picker_providers,
        )
        from hermes_cli.providers import get_label

        raw_args = event.get_command_args().strip()

        # Parse --provider, --global, and --refresh flags
        (
            model_input,
            explicit_provider,
            is_global_flag,
            force_refresh,
            is_session,
        ) = parse_model_flags(raw_args)
        persist_global = resolve_persist_behavior(is_global_flag, is_session)

        # --refresh: bust the disk cache so the picker shows live data.
        if force_refresh:
            try:
                from hermes_cli.models import clear_provider_models_cache
                clear_provider_models_cache()
            except Exception:
                pass

        # Read current model/provider from config
        current_model = ""
        current_provider = "openrouter"
        current_base_url = ""
        current_api_key = ""
        user_provs = None
        custom_provs = None
        config_path = _hermes_home / "config.yaml"
        try:
            cfg = _load_gateway_config()
            if cfg:
                model_cfg = cfg.get("model", {})
                if isinstance(model_cfg, dict):
                    current_model = model_cfg.get("default", "")
                    current_provider = model_cfg.get("provider", current_provider)
                    current_base_url = model_cfg.get("base_url", "")
                user_provs = cfg.get("providers")
                try:
                    from hermes_cli.config import get_compatible_custom_providers
                    custom_provs = get_compatible_custom_providers(cfg)
                except Exception:
                    custom_provs = cfg.get("custom_providers")
        except Exception:
            pass

        # Check for session override
        source = event.source
        session_key = self._session_key_for_source(source)
        override = self._session_model_overrides.get(session_key, {})
        if override:
            current_model = override.get("model", current_model)
            current_provider = override.get("provider", current_provider)
            current_base_url = override.get("base_url", current_base_url)
            current_api_key = override.get("api_key", current_api_key)

        # No args: show interactive picker (Telegram/Discord) or text list
        if not model_input and not explicit_provider:
            # Try interactive picker if the platform supports it
            adapter = self._adapter_for_source(source)
            has_picker = (
                adapter is not None
                and getattr(type(adapter), "send_model_picker", None) is not None
            )

            if has_picker:
                try:
                    providers = list_picker_providers(
                        current_provider=current_provider,
                        current_base_url=current_base_url,
                        current_model=current_model,
                        user_providers=user_provs,
                        custom_providers=custom_provs,
                        max_models=50,
                    )
                except Exception:
                    providers = []

                if providers:
                    # Build a callback closure for when the user picks a model.
                    # Captures self + locals needed for the switch logic.
                    _self = self
                    _session_key = session_key
                    _cur_model = current_model
                    _cur_provider = current_provider
                    _cur_base_url = current_base_url
                    _cur_api_key = current_api_key

                    async def _on_model_selected(
                        _chat_id: str, model_id: str, provider_slug: str
                    ) -> str:
                        """Perform the model switch and return confirmation text."""
                        result = _switch_model(
                            raw_input=model_id,
                            current_provider=_cur_provider,
                            current_model=_cur_model,
                            current_base_url=_cur_base_url,
                            current_api_key=_cur_api_key,
                            is_global=False,
                            explicit_provider=provider_slug,
                            user_providers=user_provs,
                            custom_providers=custom_provs,
                        )
                        if not result.success:
                            return t("gateway.model.error_prefix", error=result.error_message)

                        # Update cached agent in-place
                        cached_entry = None
                        _cache_lock = getattr(_self, "_agent_cache_lock", None)
                        _cache = getattr(_self, "_agent_cache", None)
                        if _cache_lock and _cache is not None:
                            with _cache_lock:
                                cached_entry = _cache.get(_session_key)
                        if cached_entry and cached_entry[0] is not None:
                            try:
                                cached_entry[0].switch_model(
                                    new_model=result.new_model,
                                    new_provider=result.target_provider,
                                    api_key=result.api_key,
                                    base_url=result.base_url,
                                    api_mode=result.api_mode,
                                )
                            except Exception as exc:
                                logger.warning("Picker model switch failed for cached agent: %s", exc)

                        # Persist the new model to the session DB so the
                        # dashboard shows the updated model (#34850).
                        _sess_db = getattr(_self, "_session_db", None)
                        if _sess_db is not None:
                            try:
                                _sess_entry = await _self.async_session_store.get_or_create_session(
                                    event.source
                                )
                                await _sess_db.update_session_model(
                                    _sess_entry.session_id, result.new_model
                                )
                            except Exception as exc:
                                logger.debug(
                                    "Failed to persist model switch to DB: %s", exc
                                )

                        # Store model note + session override
                        if not hasattr(_self, "_pending_model_notes"):
                            _self._pending_model_notes = {}
                        _self._pending_model_notes[_session_key] = (
                            f"[Note: model was just switched from {_cur_model} to {result.new_model} "
                            f"via {result.provider_label or result.target_provider}. "
                            f"Adjust your self-identification accordingly.]"
                        )
                        _self._session_model_overrides[_session_key] = {
                            "model": result.new_model,
                            "provider": result.target_provider,
                            "api_key": result.api_key,
                            "base_url": result.base_url,
                            "api_mode": result.api_mode,
                        }

                        # Evict cached agent so the next turn creates a fresh
                        # agent from the override rather than relying on the
                        # stale cache signature to trigger a rebuild.
                        _self._evict_cached_agent(_session_key)

                        # Build confirmation text
                        plabel = result.provider_label or result.target_provider
                        lines = [t("gateway.model.switched", model=result.new_model)]
                        lines.append(t("gateway.model.provider_label", provider=plabel))
                        mi = result.model_info
                        from hermes_cli.model_switch import resolve_display_context_length
                        _sw_config_ctx = None
                        try:
                            _sw_cfg = _load_gateway_config()
                            _sw_model_cfg = _sw_cfg.get("model", {})
                            if isinstance(_sw_model_cfg, dict):
                                _sw_raw = _sw_model_cfg.get("context_length")
                                if _sw_raw is not None:
                                    _sw_config_ctx = int(_sw_raw)
                        except Exception:
                            pass
                        ctx = resolve_display_context_length(
                            result.new_model,
                            result.target_provider,
                            base_url=result.base_url or current_base_url or "",
                            api_key=result.api_key or current_api_key or "",
                            model_info=mi,
                            custom_providers=custom_provs,
                            config_context_length=_sw_config_ctx,
                        )
                        if ctx:
                            lines.append(t("gateway.model.context_label", tokens=f"{ctx:,}"))
                        if mi:
                            if mi.max_output:
                                lines.append(t("gateway.model.max_output_label", tokens=f"{mi.max_output:,}"))
                            if mi.has_cost_data():
                                lines.append(t("gateway.model.cost_label", cost=mi.format_cost()))
                            lines.append(t("gateway.model.capabilities_label", capabilities=mi.format_capabilities()))
                        lines.append(t("gateway.model.session_only_hint"))
                        return "\n".join(lines)

                    metadata = self._thread_metadata_for_source(source, self._reply_anchor_for_event(event))
                    result = await adapter.send_model_picker(
                        chat_id=source.chat_id,
                        providers=providers,
                        current_model=current_model,
                        current_provider=current_provider,
                        session_key=session_key,
                        on_model_selected=_on_model_selected,
                        metadata=metadata,
                    )
                    if result.success:
                        return None  # Picker sent — adapter handles the response

            # Fallback: text list (for platforms without picker or if picker failed)
            provider_label = get_label(current_provider)
            lines = [t("gateway.model.current_label", model=current_model or "unknown", provider=provider_label), ""]

            try:
                providers = list_authenticated_providers(
                    current_provider=current_provider,
                    current_base_url=current_base_url,
                    current_model=current_model,
                    user_providers=user_provs,
                    custom_providers=custom_provs,
                    max_models=5,
                )
                for p in providers:
                    tag = t("gateway.model.current_tag") if p["is_current"] else ""
                    lines.append(f"**{p['name']}** `--provider {p['slug']}`{tag}:")
                    if p["models"]:
                        model_strs = ", ".join(f"`{m}`" for m in p["models"])
                        extra = t("gateway.model.more_models_suffix", count=p["total_models"] - len(p["models"])) if p["total_models"] > len(p["models"]) else ""
                        lines.append(f"  {model_strs}{extra}")
                    elif p.get("api_url"):
                        lines.append(f"  `{p['api_url']}`")
                    lines.append("")
            except Exception:
                pass

            lines.append(t("gateway.model.usage_switch_model"))
            lines.append(t("gateway.model.usage_switch_provider"))
            lines.append(t("gateway.model.usage_persist"))
            return "\n".join(lines)

        # Perform the switch
        result = _switch_model(
            raw_input=model_input,
            current_provider=current_provider,
            current_model=current_model,
            current_base_url=current_base_url,
            current_api_key=current_api_key,
            is_global=persist_global,
            explicit_provider=explicit_provider,
            user_providers=user_provs,
            custom_providers=custom_provs,
        )

        if not result.success:
            return t("gateway.model.error_prefix", error=result.error_message)

        # If there's a cached agent, update it in-place
        cached_entry = None
        _cache_lock = getattr(self, "_agent_cache_lock", None)
        _cache = getattr(self, "_agent_cache", None)
        if _cache_lock and _cache is not None:
            with _cache_lock:
                cached_entry = _cache.get(session_key)

        if cached_entry and cached_entry[0] is not None:
            try:
                cached_entry[0].switch_model(
                    new_model=result.new_model,
                    new_provider=result.target_provider,
                    api_key=result.api_key,
                    base_url=result.base_url,
                    api_mode=result.api_mode,
                )
            except Exception as exc:
                logger.warning("In-place model switch failed for cached agent: %s", exc)

        # Persist the new model to the session DB so the dashboard
        # shows the updated model (#34850).
        _sess_db = getattr(self, "_session_db", None)
        if _sess_db is not None:
            try:
                _sess_entry = await self.async_session_store.get_or_create_session(source)
                await _sess_db.update_session_model(
                    _sess_entry.session_id, result.new_model
                )
            except Exception as exc:
                logger.debug(
                    "Failed to persist model switch to DB: %s", exc
                )

        # Store a note to prepend to the next user message so the model
        # knows about the switch (avoids system messages mid-history).
        if not hasattr(self, "_pending_model_notes"):
            self._pending_model_notes = {}
        self._pending_model_notes[session_key] = (
            f"[Note: model was just switched from {current_model} to {result.new_model} "
            f"via {result.provider_label or result.target_provider}. "
            f"Adjust your self-identification accordingly.]"
        )

        # Store session override so next agent creation uses the new model
        self._session_model_overrides[session_key] = {
            "model": result.new_model,
            "provider": result.target_provider,
            "api_key": result.api_key,
            "base_url": result.base_url,
            "api_mode": result.api_mode,
        }

        # Evict cached agent so the next turn creates a fresh agent from the
        # override rather than relying on cache signature mismatch detection.
        self._evict_cached_agent(session_key)

        # Persist to config if --global
        if persist_global:
            try:
                if config_path.exists():
                    with open(config_path, encoding="utf-8") as f:
                        cfg = yaml.safe_load(f) or {}
                else:
                    cfg = {}
                # Coerce scalar/None ``model:`` into a dict before mutation —
                # otherwise ``cfg.setdefault("model", {})`` returns the existing
                # scalar and the next assignment raises
                # ``TypeError: 'str' object does not support item assignment``.
                # Reproduces when ``config.yaml`` has ``model: <name>`` (flat
                # string) instead of the proper nested ``model: {default: ...}``.
                raw_model = cfg.get("model")
                if isinstance(raw_model, dict):
                    model_cfg = raw_model
                elif isinstance(raw_model, str) and raw_model.strip():
                    model_cfg = {"default": raw_model.strip()}
                    cfg["model"] = model_cfg
                else:
                    model_cfg = {}
                    cfg["model"] = model_cfg
                model_cfg["default"] = result.new_model
                model_cfg["provider"] = result.target_provider
                if result.base_url:
                    model_cfg["base_url"] = result.base_url
                from hermes_cli.config import save_config
                save_config(cfg)
            except Exception as e:
                logger.warning("Failed to persist model switch: %s", e)

        # Build confirmation message with full metadata
        provider_label = result.provider_label or result.target_provider
        lines = [t("gateway.model.switched", model=result.new_model)]
        lines.append(t("gateway.model.provider_label", provider=provider_label))

        # Context: always resolve via the provider-aware chain so Codex OAuth,
        # Copilot, and Nous-enforced caps win over the raw models.dev entry.
        mi = result.model_info
        from hermes_cli.model_switch import resolve_display_context_length
        _sw2_config_ctx = None
        try:
            _sw2_cfg = _load_gateway_config()
            _sw2_model_cfg = _sw2_cfg.get("model", {})
            if isinstance(_sw2_model_cfg, dict):
                _sw2_raw = _sw2_model_cfg.get("context_length")
                if _sw2_raw is not None:
                    _sw2_config_ctx = int(_sw2_raw)
        except Exception:
            pass
        ctx = resolve_display_context_length(
            result.new_model,
            result.target_provider,
            base_url=result.base_url or current_base_url or "",
            api_key=result.api_key or current_api_key or "",
            model_info=mi,
            custom_providers=custom_provs,
            config_context_length=_sw2_config_ctx,
        )
        if ctx:
            lines.append(t("gateway.model.context_label", tokens=f"{ctx:,}"))
        if mi:
            if mi.max_output:
                lines.append(t("gateway.model.max_output_label", tokens=f"{mi.max_output:,}"))
            if mi.has_cost_data():
                lines.append(t("gateway.model.cost_label", cost=mi.format_cost()))
            lines.append(t("gateway.model.capabilities_label", capabilities=mi.format_capabilities()))

        # Cache notice
        cache_enabled = (
            (base_url_host_matches(result.base_url or "", "openrouter.ai") and "claude" in result.new_model.lower())
            or result.api_mode == "anthropic_messages"
        )
        if cache_enabled:
            lines.append(t("gateway.model.prompt_caching_enabled"))

        if result.warning_message:
            lines.append(t("gateway.model.warning_prefix", warning=result.warning_message))

        if persist_global:
            lines.append(t("gateway.model.saved_global"))
        else:
            lines.append(t("gateway.model.session_only_hint"))

        return "\n".join(lines)

    async def _handle_codex_runtime_command(self, event: MessageEvent) -> str:
        """Handle /codex-runtime command in the gateway.

        Same surface as the CLI handler in cli.py:
            /codex-runtime                  — show current state
            /codex-runtime auto             — Hermes default runtime
            /codex-runtime codex_app_server — codex subprocess runtime
            /codex-runtime on / off         — synonyms

        On change, the cached agent for this session is evicted so the next
        message creates a fresh AIAgent with the new api_mode wired in
        (avoids prompt-cache invalidation mid-session)."""
        from hermes_cli import codex_runtime_switch as crs

        raw_args = event.get_command_args().strip() if event else ""
        new_value, errors = crs.parse_args(raw_args)
        if errors:
            return "❌ " + "\n❌ ".join(errors)

        # Load + persist via the same helpers used for /model and /yolo
        try:
            from hermes_cli.config import load_config, save_config
        except Exception as exc:
            return f"❌ Could not load config: {exc}"
        cfg = load_config()

        result = crs.apply(
            cfg,
            new_value,
            persist_callback=(save_config if new_value is not None else None),
        )

        # On a real change, evict the cached agent so the new runtime takes
        # effect on the next message rather than waiting for cache TTL.
        if result.success and new_value is not None and result.requires_new_session:
            try:
                session_key = self._session_key_for_source(event.source)
                self._evict_cached_agent(session_key)
            except Exception:
                logger.debug("could not evict cached agent after codex-runtime change",
                             exc_info=True)

        prefix = "✓" if result.success else "✗"
        return f"{prefix} {result.message}"

    async def _handle_coding_worker_command(self, event: MessageEvent) -> str:
        """Handle /coding-worker command in the gateway."""
        from hermes_cli import coding_worker_switch as cws

        raw_args = event.get_command_args().strip() if event else ""
        new_enabled, errors = cws.parse_args(raw_args)
        if errors:
            return "❌ " + "\n❌ ".join(errors)

        try:
            from hermes_cli.config import load_config, save_config
        except Exception as exc:
            return f"❌ Could not load config: {exc}"
        cfg = load_config()

        result = cws.apply(
            cfg,
            new_enabled,
            persist_callback=(save_config if new_enabled is not None else None),
        )

        if result.success and new_enabled is not None:
            try:
                session_key = self._session_key_for_source(event.source)
                self._evict_cached_agent(session_key)
            except Exception:
                logger.debug("could not evict cached agent after coding-worker change",
                             exc_info=True)

        prefix = "✓" if result.success else "✗"
        return f"{prefix} {result.message}"

    async def _handle_personality_command(self, event: MessageEvent) -> str:
        """Handle /personality command - list or set a personality."""
        from hermes_constants import display_hermes_home

        args = event.get_command_args().strip().lower()
        config_path = _hermes_home / 'config.yaml'

        try:
            config = _load_gateway_config()
            personalities = cfg_get(config, "agent", "personalities", default={})
        except Exception:
            config = {}
            personalities = {}

        if not personalities:
            return t("gateway.personality.none_configured", path=display_hermes_home())

        if not args:
            lines = [t("gateway.personality.header")]
            lines.append(t("gateway.personality.none_option"))
            for name, prompt in personalities.items():
                if isinstance(prompt, dict):
                    preview = prompt.get("description") or prompt.get("system_prompt", "")[:50]
                else:
                    preview = prompt[:50] + "..." if len(prompt) > 50 else prompt
                lines.append(t("gateway.personality.item", name=name, preview=preview))
            lines.append(t("gateway.personality.usage"))
            return "\n".join(lines)

        def _resolve_prompt(value):
            if isinstance(value, dict):
                parts = [value.get("system_prompt", "")]
                if value.get("tone"):
                    parts.append(f'Tone: {value["tone"]}')
                if value.get("style"):
                    parts.append(f'Style: {value["style"]}')
                return "\n".join(p for p in parts if p)
            return str(value)

        if args in {"none", "default", "neutral"}:
            try:
                if "agent" not in config or not isinstance(config.get("agent"), dict):
                    config["agent"] = {}
                config["agent"]["system_prompt"] = ""
                atomic_yaml_write(config_path, config)
            except Exception as e:
                return t("gateway.personality.save_failed", error=str(e))
            self._ephemeral_system_prompt = ""
            return t("gateway.personality.cleared")
        elif args in personalities:
            new_prompt = _resolve_prompt(personalities[args])

            # Write to config.yaml, same pattern as CLI save_config_value.
            try:
                if "agent" not in config or not isinstance(config.get("agent"), dict):
                    config["agent"] = {}
                config["agent"]["system_prompt"] = new_prompt
                atomic_yaml_write(config_path, config)
            except Exception as e:
                return t("gateway.personality.save_failed", error=str(e))

            # Update in-memory so it takes effect on the very next message.
            self._ephemeral_system_prompt = new_prompt

            return t("gateway.personality.set_to", name=args)

        available = "`none`, " + ", ".join(f"`{n}`" for n in personalities)
        return t("gateway.personality.unknown", name=args, available=available)

    async def _handle_retry_command(self, event: MessageEvent) -> str:
        """Handle /retry command - re-send the last user message."""
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)
        history = await self.async_session_store.load_transcript(session_entry.session_id)

        # Find the last user message
        last_user_msg = None
        last_user_idx = None
        for i in range(len(history) - 1, -1, -1):
            if history[i].get("role") == "user":
                last_user_msg = history[i].get("content", "")
                last_user_idx = i
                break

        if not last_user_msg:
            return t("gateway.retry.no_previous")

        # Truncate history to before the last user message and persist
        truncated = history[:last_user_idx]
        await self.async_session_store.rewrite_transcript(session_entry.session_id, truncated)
        # Reset stored token count — transcript was truncated
        session_entry.last_prompt_tokens = 0

        # Re-send by creating a fake text event with the old message
        retry_event = MessageEvent(
            text=last_user_msg,
            message_type=MessageType.TEXT,
            source=source,
            raw_message=event.raw_message,
            channel_prompt=event.channel_prompt,
        )

        # Let the normal message handler process it
        return await self._handle_message(retry_event)

    # ────────────────────────────────────────────────────────────────
    # /meeting — deterministic goal/subgoal creation from meeting summaries
    # ────────────────────────────────────────────────────────────────
    @staticmethod
    def _is_meeting_skill_event(event: "MessageEvent") -> bool:
        """Return true when this turn came from the meeting intake skill."""
        skill_name = str(getattr(event, "invoked_skill_name", "") or "").strip().lower()
        command = str(getattr(event, "invoked_skill_command", "") or "").strip().lower()
        return skill_name in _MEETING_GOAL_SKILL_NAMES or command == "meeting"

    @staticmethod
    def _clean_meeting_todo_line(line: str) -> str:
        """Normalize a single todo bullet/numbered item from a meeting reply."""
        text = (line or "").strip()
        text = re.sub(r"^>\s*", "", text)
        text = re.sub(r"^[-*•]\s+", "", text)
        text = re.sub(r"^\d+[.)]\s+", "", text)
        text = re.sub(r"^\[[ xX]\]\s+", "", text)
        text = text.strip(" -\t")
        if not text:
            return ""
        lowered = text.lower().strip(" .")
        if lowered in {
            "none",
            "n/a",
            "no clear follow-up todos were stated",
            "no clear todos",
            "no follow-up todos",
        }:
            return ""
        if lowered.startswith(("no clear follow-up", "no clear todo", "no follow-up todo")):
            return ""
        return text

    @classmethod
    def _extract_meeting_todos_from_response(cls, response: str) -> list[str]:
        """Extract actionable todo lines from a meeting-intake response.

        The model still summarizes and identifies todos, but the gateway owns
        the /goal and /subgoal state mutation.  Accept both the requested
        `Next todos` section and the older failure mode where the model printed
        `/subgoal ...` commands for the user to copy-paste.
        """
        text = str(response or "")
        todos: list[str] = []

        # Backward-compatible recovery for responses shaped like:
        #   /goal Follow up ... /subgoal Do the thing /subgoal Do another thing
        for match in re.finditer(r"(?is)(?:^|\s)/subgoal\s+(.+?)(?=(?:\s+/subgoal\b)|\s*$)", text):
            candidate = cls._clean_meeting_todo_line(match.group(1))
            if candidate:
                todos.append(candidate)

        in_todos = False
        seen_any = False
        stop_headers = (
            "meeting summary",
            "summary",
            "decisions",
            "decisions / agreements",
            "open questions",
            "open questions / risks",
            "risks",
            "goal tracking",
            "transcript",
            "raw transcript",
        )
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line or line.startswith("```"):
                continue
            header = line.strip("#*: ").lower()
            if "next todos" in header or header in {"todos", "todo", "action items", "next steps"}:
                in_todos = True
                seen_any = False
                continue
            if in_todos and seen_any and any(header.startswith(h) for h in stop_headers):
                break
            if not in_todos:
                continue
            candidate = cls._clean_meeting_todo_line(line)
            if not candidate:
                continue
            # In a todos section, only accept bullet/numbered/checklist-style
            # lines. This avoids swallowing prose after the section.
            if not re.match(r"^\s*(?:[-*•]|\d+[.)]|\[[ xX]\])\s+", raw_line):
                continue
            todos.append(candidate)
            seen_any = True

        deduped: list[str] = []
        seen: set[str] = set()
        for todo in todos:
            key = re.sub(r"\s+", " ", todo).strip().lower()
            if not key or key in seen:
                continue
            seen.add(key)
            deduped.append(todo)
            if len(deduped) >= 20:
                break
        return deduped

    async def _apply_meeting_auto_goal_from_response(
        self,
        event: "MessageEvent",
        response: str,
    ) -> str:
        """Create/update /goal state for a completed /meeting turn.

        This intentionally bypasses the model for the state mutation.  The
        model may summarize and list todos, but the gateway directly calls the
        same GoalManager methods used by /goal and /subgoal instead of sending
        slash-command text back to the user.
        """
        if not self._is_meeting_skill_event(event):
            return ""

        todos = self._extract_meeting_todos_from_response(response)
        if not todos:
            return ""

        async def _defer_discord_goal_embed_after_delivery(project_context: dict[str, Any]) -> bool:
            adapter = getattr(self, "adapters", {}).get(Platform.DISCORD)
            initializer = getattr(adapter, "initialize_goal_feature_summary_for_source", None)
            if not adapter or not callable(initializer):
                logger.debug("meeting auto-goal: Discord feature summary initializer unavailable")
                return False

            source = event.source
            initial_request = f"/goal {_MEETING_AUTO_GOAL_TEXT}"

            async def _deliver() -> bool:
                try:
                    handle = await initializer(
                        source,
                        initial_request=initial_request,
                        project_context=project_context,
                    )
                    return bool(handle)
                except Exception as exc:
                    logger.warning("meeting auto-goal: feature summary embed send failed: %s", exc, exc_info=True)
                    return False

            try:
                session_key = self._session_key_for_source(source)
            except Exception:
                session_key = None

            if session_key and hasattr(adapter, "register_post_delivery_callback"):
                try:
                    generation = None
                    active = getattr(adapter, "_active_sessions", {}).get(session_key)
                    if active is not None:
                        generation = getattr(active, "_hermes_run_generation", None)
                    adapter.register_post_delivery_callback(
                        session_key,
                        _deliver,
                        generation=generation,
                    )
                    return True
                except Exception as exc:
                    logger.debug("meeting auto-goal: post-delivery embed registration failed: %s", exc)

            return await _deliver()

        source = getattr(event, "source", None)
        platform = getattr(source, "platform", None)
        platform_value = platform.value if hasattr(platform, "value") else str(platform or "")
        if platform_value.lower() == "discord":
            thread_id = str(getattr(source, "thread_id", "") or getattr(source, "chat_id", "") or "")
            if thread_id:
                try:
                    from hermes_cli import discord_worker_boards as _dwb

                    admission_ts = time.time()
                    dispatch_start_ts = time.time()
                    board = _dwb.start_direct_goal(
                        thread_id=thread_id,
                        goal=_MEETING_AUTO_GOAL_TEXT,
                        chat_id=str(getattr(source, "chat_id", "") or ""),
                        guild_id=str(getattr(source, "guild_id", "") or ""),
                        parent_channel_id=str(getattr(source, "parent_chat_id", "") or ""),
                        project_context={
                            k: v for k, v in {
                                "project_name": getattr(source, "project_name", None),
                                "project_path": getattr(source, "project_path", None),
                                "project_github_url": getattr(source, "project_github_url", None),
                                "project_channel_id": getattr(source, "project_channel_id", None),
                                "project_mapping_source": getattr(source, "project_mapping_source", None),
                                "project_mapping_resolved": getattr(source, "project_mapping_resolved", None),
                            }.items() if v is not None
                        },
                    )
                    added = 0
                    for todo in todos:
                        try:
                            _dwb.add_subgoal(board.slug, todo)
                            added += 1
                        except Exception as exc:
                            logger.debug("meeting auto-goal: Kanban add_subgoal failed: %s", exc)

                    if added > 0:
                        self._signal_kanban_dispatcher_dirty()
                        self._log_gateway_flow_telemetry(
                            route_type="discord_worker_goal",
                            source=source,
                            session_id=thread_id,
                            admission_ts=admission_ts,
                            dispatch_start_ts=dispatch_start_ts,
                            finished_ts=time.time(),
                        )
                        try:
                            event.skip_post_turn_goal_once = True
                        except Exception:
                            pass
                        await _defer_discord_goal_embed_after_delivery(dict(board.worker.get("project_context") or {}))
                        return ""
                    return ""
                except Exception as exc:
                    logger.debug(
                        "meeting auto-goal: Discord Kanban backend unavailable; falling back to legacy goal loop: %s",
                        exc,
                    )

        mgr, _session_entry = await self._get_goal_manager_for_event(event)
        if mgr is None:
            return (
                f"⚠️ I found {len(todos)} meeting todo(s), but goal tracking "
                "is unavailable in this gateway session."
            )

        created_goal = not mgr.has_goal()
        if created_goal:
            state = mgr.set(_MEETING_AUTO_GOAL_TEXT)
        else:
            state = mgr.state

        added = 0
        for todo in todos:
            try:
                mgr.add_subgoal(todo)
                added += 1
            except Exception as exc:
                logger.debug("meeting auto-goal: add_subgoal failed: %s", exc)

        if added <= 0:
            return ""

        # Avoid judging the meeting summary as if it were work toward the new
        # follow-up goal; enqueue the first real goal-continuation turn instead.
        try:
            event.skip_post_turn_goal_once = True
        except Exception:
            pass

        if created_goal and state is not None:
            try:
                prompt = mgr.next_continuation_prompt() or self._goal_kickoff_prompt(state.goal)
                self._enqueue_goal_work(event, prompt)
            except Exception as exc:
                logger.debug("meeting auto-goal: kickoff enqueue failed: %s", exc)

        if created_goal:
            return f"Goal tracking started with {added} subgoal{'s' if added != 1 else ''}."
        return f"Added {added} meeting subgoal{'s' if added != 1 else ''} to the active goal."

    # ────────────────────────────────────────────────────────────────
    # /goal — persistent cross-turn goals (Ralph-style loop)
    # ────────────────────────────────────────────────────────────────
    def _goal_max_turns_from_config(self) -> int:
        """Resolve the configured /goal turn budget for gateway sessions.

        GatewayRunner.config is a GatewayConfig dataclass, not the full
        user config mapping. Top-level config blocks such as ``goals`` are
        therefore only available through hermes_cli.config.load_config().
        """
        try:
            goals_cfg = (
                (self.config or {}).get("goals", {})
                if isinstance(self.config, dict)
                else getattr(self.config, "goals", {}) or {}
            )
            if not goals_cfg:
                from hermes_cli.config import load_config

                goals_cfg = (load_config() or {}).get("goals") or {}
            return int(goals_cfg.get("max_turns", 20) or 20)
        except Exception:
            return 20

    async def _get_goal_manager_for_event(self, event: "MessageEvent"):
        """Return a GoalManager bound to the session for this gateway event.

        Returns ``(manager, session_entry)`` or ``(None, None)`` if the
        goals module can't be loaded.
        """
        try:
            from hermes_cli.goals import GoalManager
        except Exception as exc:
            logger.debug("goal manager unavailable: %s", exc)
            return None, None
        try:
            session_entry = await self.async_session_store.get_or_create_session(event.source)
        except Exception as exc:
            logger.debug("goal manager: session lookup failed: %s", exc)
            return None, None
        sid = getattr(session_entry, "session_id", None) or ""
        if not sid:
            return None, None
        max_turns = self._goal_max_turns_from_config()
        return GoalManager(session_id=sid, default_max_turns=max_turns), session_entry

    async def _handle_goal_command(self, event: "MessageEvent") -> Optional[str]:
        """Handle /goal for gateway platforms.

        Subcommands: ``/goal`` / ``/goal status`` / ``/goal pause`` /
        ``/goal resume`` / ``/goal clear``. Any other text becomes the
        new goal.

        Setting a new goal queues the goal text as the next turn so the
        agent starts working on it immediately — the post-turn
        continuation hook then takes over from there.

        ``/goal clear`` is intentionally silent on gateway platforms: it is
        a deterministic control-plane mutation, not something that should
        clutter chat or create a response that can be misread as an agent turn.
        """
        admission_ts = time.time()
        args = (event.get_command_args() or "").strip()
        lower = args.lower()

        try:
            from hermes_cli import discord_worker_boards as _dwb
            from hermes_cli.discord_worker_roles import GOAL_CONTROL_COMMANDS

            # The official Discord application command /goal is reserved for
            # the Hermes/Ralph-style goal loop. Only user-typed Discord text
            # commands (and synthetic worker-thread events) should enter the
            # Discord Kanban board backend.
            native_discord_slash_goal = (
                getattr(event, "native_slash_command", False)
                and getattr(getattr(event, "source", None), "platform", None) == Platform.DISCORD
            )
            board = None
            if not native_discord_slash_goal:
                is_set = bool(args and lower not in GOAL_CONTROL_COMMANDS)
                board = _dwb.board_for_gateway_event(event, create=is_set)
            if board is not None:
                if not args or lower == "status":
                    return _dwb.status_line(board.slug)
                if lower == "pause":
                    _dwb.pause_board(board.slug)
                    return "Kanban goal paused."
                if lower == "resume":
                    _dwb.resume_board(board.slug)
                    self._signal_kanban_dispatcher_dirty()
                    return "Kanban goal resumed."
                if lower in {"clear", "stop", "done"}:
                    _dwb.clear_board_goal(board.slug)
                    return None
                source = event.source
                dispatch_start_ts = time.time()
                board = _dwb.set_goal(
                    thread_id=str(getattr(source, "thread_id", "") or getattr(source, "chat_id", "") or ""),
                    goal=args,
                    chat_id=str(getattr(source, "chat_id", "") or ""),
                    guild_id=str(getattr(source, "guild_id", "") or ""),
                    parent_channel_id=str(getattr(source, "parent_chat_id", "") or ""),
                    request_id=str(getattr(event, "message_id", "") or ""),
                    thread_context=str(getattr(event, "goal_thread_context", "") or ""),
                    board_slug=board.slug,
                    project_context={
                        k: v for k, v in {
                            "project_name": getattr(source, "project_name", None),
                            "project_path": getattr(source, "project_path", None),
                            "project_github_url": getattr(source, "project_github_url", None),
                            "project_channel_id": getattr(source, "project_channel_id", None),
                            "project_mapping_source": getattr(source, "project_mapping_source", None),
                            "project_mapping_resolved": getattr(source, "project_mapping_resolved", None),
                        }.items() if v is not None
                    },
                )
                self._signal_kanban_dispatcher_dirty()
                self._log_gateway_flow_telemetry(
                    route_type="discord_worker_goal",
                    source=source,
                    session_id=board.slug,
                    admission_ts=admission_ts,
                    dispatch_start_ts=dispatch_start_ts,
                    finished_ts=time.time(),
                )
                if getattr(event, "feature_summary", None):
                    try:
                        adapter = self._adapter_for_source(source) if source else None
                        summary_sync = getattr(adapter, "sync_kanban_feature_summary", None) if adapter else None
                        if callable(summary_sync):
                            feature_summary = getattr(event, "feature_summary", None)
                            feature_summary = feature_summary if isinstance(feature_summary, dict) else {}
                            try:
                                target = _dwb.feature_summary_snapshot(board.slug)
                            except Exception:
                                logger.debug("Discord Kanban goal summary snapshot failed", exc_info=True)
                                target = {}
                            target.update(
                                {
                                    "board": board.slug,
                                    "thread_id": str(
                                        getattr(source, "thread_id", "")
                                        or getattr(source, "chat_id", "")
                                        or ""
                                    ),
                                    "guild_id": str(getattr(source, "guild_id", "") or ""),
                                    "parent_channel_id": str(getattr(source, "parent_chat_id", "") or ""),
                                    "message_id": str(feature_summary.get("message_id") or ""),
                                    "source_message_id": str(feature_summary.get("source_message_id") or ""),
                                    "state": str(target.get("state") or "active"),
                                    "public_url": str(target.get("public_url") or board.public_url or ""),
                                }
                            )
                            for key in (
                                "source_board",
                                "source_task_id",
                                "source_task_url",
                                "source_kanban_url",
                                "source_discord_thread_url",
                            ):
                                if feature_summary.get(key):
                                    target[key] = str(feature_summary.get(key) or "")
                            if feature_summary.get("hide_source_links") is not None:
                                target["hide_source_links"] = bool(feature_summary.get("hide_source_links"))
                            preferred_title = str(feature_summary.get("title") or "").strip()
                            if preferred_title:
                                target["title"] = preferred_title
                            feature_initial_request = str(feature_summary.get("initial_request") or "").strip()
                            if feature_initial_request and not str(target.get("fallback_title") or "").strip():
                                target["fallback_title"] = feature_initial_request
                            if not preferred_title and str(feature_summary.get("source_message_id") or "").strip() and feature_initial_request:
                                title = self._fallback_discord_feature_title(feature_summary)
                                if title:
                                    target["title"] = title
                            if not str(target.get("title") or "").strip():
                                title = self._discord_kanban_feature_title(target)
                                if title:
                                    target["title"] = title
                            if not str(target.get("sync_key") or "").strip():
                                target["sync_key"] = self._discord_kanban_summary_sync_key(target)
                            await summary_sync(target)
                    except Exception:
                        logger.debug("Discord Kanban goal feature-summary sync failed", exc_info=True)
                    return None
                return f"Kanban goal set. Board: {board.public_url or board.slug}"
        except Exception as exc:
            logger.debug("Discord Kanban goal backend unavailable; falling back to legacy goal loop: %s", exc)

        mgr, session_entry = await self._get_goal_manager_for_event(event)
        if mgr is None:
            return t("gateway.goal.unavailable")

        if not args or lower == "status":
            return mgr.status_line()

        if lower == "pause":
            state = mgr.pause(reason="user-paused")
            if state is None:
                return t("gateway.goal.no_goal_set")
            try:
                adapter = self._adapter_for_source(event.source) if event.source else None
                _quick_key = self._session_key_for_source(event.source) if event.source else None
                if adapter and _quick_key:
                    self._clear_goal_pending_continuations(_quick_key, adapter)
            except Exception as exc:
                logger.debug("goal pause: pending continuation cleanup failed: %s", exc)
            return t("gateway.goal.paused", goal=state.goal)

        if lower == "resume":
            state = mgr.resume()
            if state is None:
                return t("gateway.goal.no_resume")
            try:
                prompt = mgr.next_continuation_prompt() or self._goal_kickoff_prompt(state.goal)
                self._enqueue_goal_work(event, prompt)
            except Exception as exc:
                logger.debug("goal resume enqueue failed: %s", exc)
            return t("gateway.goal.resumed", goal=state.goal)

        if lower in {"clear", "stop", "done"}:
            mgr.clear()
            try:
                adapter = self._adapter_for_source(event.source) if event.source else None
                _quick_key = self._session_key_for_source(event.source) if event.source else None
                if adapter and _quick_key:
                    self._clear_goal_pending_continuations(_quick_key, adapter)
            except Exception as exc:
                logger.debug("goal clear: pending continuation cleanup failed: %s", exc)
            return None

        # Otherwise — treat the remaining text as the new goal.
        try:
            dispatch_start_ts = time.time()
            state = mgr.set(args)
            if isinstance(getattr(event, "feature_summary", None), dict):
                event.feature_summary["title"] = self._fallback_discord_feature_title(event.feature_summary)
        except ValueError as exc:
            return t("gateway.goal.invalid", error=str(exc))

        # Queue a wrapped goal prompt as an immediate first turn so the
        # agent starts making progress. The post-turn hook takes over after.
        try:
            self._enqueue_goal_work(
                event,
                self._goal_initial_work_prompt(
                    mgr,
                    state.goal,
                    str(getattr(event, "goal_thread_context", "") or ""),
                ),
            )
            self._log_gateway_flow_telemetry(
                route_type="slash_goal",
                source=event.source,
                session_id=getattr(session_entry, "session_id", None),
                admission_ts=admission_ts,
                dispatch_start_ts=dispatch_start_ts,
                finished_ts=time.time(),
            )
        except Exception as exc:
            logger.debug("goal kickoff enqueue failed: %s", exc)

        return t("gateway.goal.set", budget=state.max_turns, goal=state.goal)

    @staticmethod
    def _goal_initial_work_prompt(mgr: Any, goal: str, context: str) -> str:
        base = mgr.initial_work_prompt() or GatewayRunner._goal_kickoff_prompt(goal)
        context = str(context or "").strip()
        if not context:
            return base
        return f"{base}\n\n[Discord goal thread context]\n{context}"

    async def _handle_subgoal_command(self, event: "MessageEvent") -> str:
        """Handle /subgoal for gateway platforms (mirror of CLI handler).

        Subgoals are extra criteria appended to the active goal mid-loop.
        They modify state read at the next turn boundary, so this is safe
        to invoke while the agent is running.
        """
        args = (event.get_command_args() or "").strip()
        try:
            from hermes_cli import discord_worker_boards as _dwb

            board = _dwb.board_for_gateway_event(event, create=bool(args))
            if board is not None:
                if not args:
                    return _dwb.status_line(board.slug) + "\n" + _dwb.list_subgoals(board.slug)
                tokens = args.split(None, 1)
                verb = tokens[0].lower()
                rest = tokens[1].strip() if len(tokens) > 1 else ""
                if verb == "remove":
                    if not rest:
                        return "Usage: /subgoal remove <n>"
                    try:
                        removed = _dwb.deactivate_subgoal(board.slug, int(rest.split()[0]))
                    except (ValueError, IndexError) as exc:
                        return f"/subgoal remove: {exc}"
                    return f"Removed subgoal: {removed}"
                if verb == "clear":
                    count = _dwb.clear_subgoals(board.slug)
                    return f"Cleared {count} subgoal{'s' if count != 1 else ''}."
                idx, text = _dwb.add_subgoal(board.slug, args)
                self._signal_kanban_dispatcher_dirty()
                return f"Added subgoal {idx}: {text}"
        except Exception as exc:
            logger.debug("Discord Kanban subgoal backend unavailable; falling back to legacy goal loop: %s", exc)

        mgr, _session_entry = await self._get_goal_manager_for_event(event)
        if mgr is None:
            return t("gateway.goal.unavailable")
        if not mgr.has_goal():
            return "No active goal. Set one with /goal <text>."

        # No args → list current subgoals.
        if not args:
            return f"{mgr.status_line()}\n{mgr.render_subgoals()}"

        tokens = args.split(None, 1)
        verb = tokens[0].lower()
        rest = tokens[1].strip() if len(tokens) > 1 else ""

        if verb == "remove":
            if not rest:
                return "Usage: /subgoal remove <n>"
            try:
                idx = int(rest.split()[0])
            except ValueError:
                return "/subgoal remove: <n> must be an integer (1-based index)."
            try:
                removed = mgr.remove_subgoal(idx)
            except (IndexError, RuntimeError) as exc:
                return f"/subgoal remove: {exc}"
            return f"✓ Removed subgoal {idx}: {removed}"

        if verb == "clear":
            try:
                prev = mgr.clear_subgoals()
            except RuntimeError as exc:
                return f"/subgoal clear: {exc}"
            if prev:
                return f"✓ Cleared {prev} subgoal{'s' if prev != 1 else ''}."
            return "No subgoals to clear."

        try:
            text = mgr.add_subgoal(args)
        except (ValueError, RuntimeError) as exc:
            return f"/subgoal: {exc}"
        idx = len(mgr.state.subgoals) if mgr.state else 0
        return f"✓ Added subgoal {idx}: {text}"

    async def _send_goal_status_notice(self, source: Any, message: str) -> None:
        """Send a /goal judge status line back to the originating chat/thread."""
        adapter = self._adapter_for_source(source)
        if not adapter:
            logger.debug("goal continuation: no adapter for %s", getattr(source, "platform", None))
            return

        try:
            metadata = self._thread_metadata_for_source(source)
        except Exception:
            metadata = None

        result = await adapter.send(source.chat_id, message, metadata=metadata)
        if result is not None and not getattr(result, "success", True):
            logger.warning(
                "goal continuation: status send failed: %s",
                getattr(result, "error", "unknown error"),
            )

    async def _defer_goal_status_notice_after_delivery(self, source: Any, message: str) -> None:
        """Send a /goal status line after the main response is delivered.

        The gateway message handler returns the agent response to the platform
        adapter, which sends it after this method's caller has returned.  For a
        natural Discord/Telegram reading order, goal status belongs after that
        send.  Platform adapters provide a one-shot post-delivery callback for
        exactly this boundary; when unavailable, fall back to direct awaited
        delivery rather than silently dropping the notice.
        """
        adapter = self._adapter_for_source(source)
        if not adapter:
            logger.debug("goal continuation: no adapter for %s", getattr(source, "platform", None))
            return

        async def _deliver() -> None:
            try:
                await self._send_goal_status_notice(source, message)
            except Exception as exc:
                logger.warning("goal continuation: status send failed: %s", exc, exc_info=True)

        try:
            session_key = self._session_key_for_source(source)
        except Exception:
            session_key = None

        if session_key and hasattr(adapter, "register_post_delivery_callback"):
            try:
                generation = None
                active = getattr(adapter, "_active_sessions", {}).get(session_key)
                if active is not None:
                    generation = getattr(active, "_hermes_run_generation", None)
                adapter.register_post_delivery_callback(
                    session_key,
                    _deliver,
                    generation=generation,
                )
                return
            except Exception as exc:
                logger.debug("goal continuation: post-delivery callback registration failed: %s", exc)

        await _deliver()

    def _discord_summary_status(self, agent_result: Optional[Dict[str, Any]]) -> str:
        agent_result = agent_result or {}
        if agent_result.get("provider_no_progress"):
            return "Failed"
        if agent_result.get("interrupted"):
            return "Interrupted"
        if agent_result.get("failed") or agent_result.get("error"):
            return "Failed"
        return "Complete"

    def _discord_ledger_summary_status(self, work_item_id: Optional[Any], fallback: str) -> str:
        if not work_item_id:
            return fallback
        try:
            item = self._ledger().get(str(work_item_id))
        except Exception:
            return fallback
        if not isinstance(item, dict):
            return fallback
        if item.get("closeout_authoritative") is True and isinstance(
            item.get("closeout"),
            dict,
        ):
            try:
                from hermes_cli.trusted_closeout import (
                    closeout_terminal_eligible,
                    normalize_closeout_state,
                )

                closeout = normalize_closeout_state(item["closeout"])
                if not closeout_terminal_eligible(closeout):
                    closeout_status = str(closeout.get("status") or "").lower()
                    if closeout_status in {
                        "failed",
                        "blocked",
                        "error",
                        "errored",
                    }:
                        return "Failed"
                    return "Running"
            except Exception:
                return "Running"
        gate = item.get("completion_gate") if isinstance(item.get("completion_gate"), dict) else None
        if gate and not gate.get("allowed_to_complete"):
            return str(gate.get("summary_status") or item.get("summary_status") or "Blocked")
        return str(item.get("summary_status") or fallback)

    def _fallback_discord_feature_outcome(self, final_response: str, *, limit: int = 420) -> str:
        text = re.sub(r"MEDIA:\s*\S+", "", str(final_response or "")).strip()
        text = text.replace("[[audio_as_voice]]", "").replace("[[as_document]]", "").strip()
        text = re.sub(r"```.*?```", " ", text, flags=re.DOTALL)
        text = re.sub(r"`([^`]*)`", r"\1", text)
        text = re.sub(r"[*_>#-]+", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        if not text:
            return "No visible response was produced."

        sentences = re.split(r"(?<=[.!?])\s+", text)
        concise = " ".join(s.strip() for s in sentences[:3] if s.strip()) or text
        if len(concise) > limit:
            concise = concise[: limit - 3].rstrip() + "..."
        return concise

    def _discord_feature_outcome_needs_summary(self, final_response: str) -> bool:
        text = str(final_response or "")
        if len(text) > 420:
            return True
        if len(re.findall(r"(?<=[.!?])\s+", text)) >= 3:
            return True
        bullet_lines = [
            line for line in text.splitlines()
            if line.lstrip().startswith(("-", "*", "•")) or re.match(r"\s*\d+[.)]\s+", line)
        ]
        return len(bullet_lines) > 3

    def _summarize_discord_feature_outcome(self, final_response: str) -> str:
        fallback = self._fallback_discord_feature_outcome(final_response)
        if not self._discord_feature_outcome_needs_summary(final_response):
            return fallback

        prompt = (
            "Summarize this completed Hermes feature-thread outcome in a few concise sentences. "
            "State only what changed or what result the user got. Do not include logs, "
            "long bullet lists, code, tool chatter, or copied implementation details.\n\n"
            f"Final response:\n{str(final_response or '')[:6000]}"
        )
        try:
            from agent.auxiliary_client import call_llm

            response = call_llm(
                task="feature_summary",
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "You write concise Discord feature-summary outcomes. "
                            "Return 2-3 short sentences, no heading."
                        ),
                    },
                    {"role": "user", "content": prompt},
                ],
                max_tokens=180,
                temperature=0.2,
                timeout=15,
            )
            summary = (response.choices[0].message.content or "").strip()
            if summary:
                return self._fallback_discord_feature_outcome(summary)
        except Exception as exc:
            logger.debug("Discord feature outcome summarization failed: %s", exc)
        return fallback

    async def _update_discord_summaries(
        self,
        *,
        source: SessionSource,
        feature_summary: Optional[Dict[str, Any]] = None,
        project_summary: Optional[Dict[str, Any]] = None,
        final_response: str = "",
        status: str = "Complete",
        session_id: Optional[str] = None,
        title: Optional[str] = None,
        runtime_breakdown: Optional[Dict[str, Any]] = None,
    ) -> bool:
        if source.platform != Platform.DISCORD:
            return True
        if not feature_summary and not project_summary:
            return True
        adapter = self.adapters.get(Platform.DISCORD)
        if not adapter:
            return False
        session_db = getattr(self, "_session_db", None)
        if not title and session_id and session_db and not feature_summary:
            try:
                title = await session_db.get_session_title(session_id)
            except Exception:
                title = None
        has_feature_kanban = isinstance(feature_summary, dict) and isinstance(
            feature_summary.get("kanban_board"),
            dict,
        )
        if feature_summary and not title and not has_feature_kanban:
            title = self._fallback_discord_feature_title(feature_summary)
        if feature_summary and not has_feature_kanban and session_id:
            initial_request = str(feature_summary.get("initial_request") or "").strip()
            if re.match(r"^/goal(?:\s|$)", initial_request, flags=re.IGNORECASE):
                try:
                    from hermes_cli.goals import GoalManager

                    state = GoalManager(session_id=session_id).state
                    accumulated = getattr(state, "runtime_breakdown", None) if state is not None else None
                    if isinstance(accumulated, dict) and accumulated:
                        runtime_breakdown = accumulated
                except Exception:
                    logger.debug("Discord goal runtime summary lookup failed", exc_info=True)
        if feature_summary and hasattr(adapter, "update_feature_summary"):
            try:
                concise_response = await asyncio.to_thread(
                    self._summarize_discord_feature_outcome,
                    final_response,
                )
                update_kwargs = {
                    "final_response": concise_response,
                    "status": status,
                    "title": title,
                }
                if runtime_breakdown is not None:
                    update_kwargs["runtime_breakdown"] = runtime_breakdown
                if session_id:
                    try:
                        from hermes_cli.plugins import collect_session_artifacts

                        artifacts = await asyncio.to_thread(
                            collect_session_artifacts,
                            session_id,
                            surface="discord_feature_summary",
                        )
                        if artifacts:
                            update_kwargs["artifacts"] = artifacts
                    except Exception:
                        logger.debug(
                            "Discord feature summary artifact collection failed",
                            exc_info=True,
                        )
                result = await adapter.update_feature_summary(
                    feature_summary,
                    **update_kwargs,
                )
                return bool(result) if result is not None else True
            except Exception:
                logger.debug("Discord feature summary update failed", exc_info=True)
                return False
        return True

    async def _refresh_discord_running_summary_artifacts(
        self,
        *,
        source: SessionSource,
        feature_summary: Optional[Dict[str, Any]],
        session_id: str,
    ) -> bool:
        """Attach session artifacts after Discord resolves the live session."""
        if source.platform != Platform.DISCORD or not feature_summary or not session_id:
            return True
        adapter = self.adapters.get(Platform.DISCORD)
        if not adapter or not hasattr(adapter, "update_feature_summary"):
            return False
        try:
            from hermes_cli.plugins import collect_session_artifacts

            artifacts = await asyncio.to_thread(
                collect_session_artifacts,
                session_id,
                surface="discord_feature_summary",
            )
            if not artifacts:
                return True
            result = await adapter.update_feature_summary(
                feature_summary,
                status="Running",
                artifacts=artifacts,
            )
            return bool(result) if result is not None else True
        except Exception:
            logger.debug(
                "Discord running feature-summary artifact refresh failed",
                exc_info=True,
            )
            return False

    def _register_discord_summary_post_delivery(
        self,
        *,
        event: MessageEvent,
        source: SessionSource,
        session_key: str,
        run_generation: Optional[int],
        session_id: str,
        final_response: str,
        agent_result: Optional[Dict[str, Any]],
    ) -> None:
        if source.platform != Platform.DISCORD:
            return
        adapter = self.adapters.get(Platform.DISCORD)
        if not adapter or not hasattr(adapter, "register_post_delivery_callback"):
            return
        completion_id = str(
            getattr(event, "background_completion_id", "") or ""
        ) or None
        pending_background = self._session_has_pending_background_workers(
            session_key,
            work_item_id=str(getattr(event, "work_item_id", "") or "") or None,
            origin_run_generation=getattr(
                event,
                "background_completion_generation",
                None,
            ),
            origin_attempt_id=getattr(
                event,
                "background_completion_attempt_id",
                None,
            ),
            exclude_delegation_id=completion_id,
        )
        status = (
            "Running"
            if pending_background
            else self._discord_summary_status(agent_result)
        )
        work_item_id = self._discord_work_item_id_for_event(event, session_key)
        feature_summary = _discord_feature_summary_for_turn(
            source,
            getattr(event, "feature_summary", None),
            getattr(event, "discord_runtime_mode", None),
            getattr(event, "discord_action_request_intent", None),
        )
        project_summary = (
            getattr(event, "project_summary", None)
            if _discord_runtime_mode_for(event) is RuntimeMode.ACTION
            else None
        )
        if not feature_summary and not project_summary and not work_item_id:
            return
        if not pending_background:
            status = self._discord_ledger_summary_status(work_item_id, status)
        summary_response = (
            "Coding workers are still running; completion will arrive in a follow-up turn."
            if pending_background
            else final_response
        )

        async def _deliver():
            summary_ok = await self._update_discord_summaries(
                source=source,
                feature_summary=feature_summary,
                project_summary=project_summary,
                final_response=summary_response,
                status=status,
                session_id=session_id,
                runtime_breakdown=(agent_result or {}).get("runtime_breakdown") if isinstance(agent_result, dict) else None,
            )
            if summary_ok and work_item_id and not pending_background:
                try:
                    expected_run_state = getattr(event, "work_item_run_state", None)
                    if feature_summary or project_summary:
                        if self._ledger().mark_summary_updated(str(work_item_id)) and isinstance(
                            expected_run_state,
                            dict,
                        ):
                            expected_run_state = {
                                **expected_run_state,
                                "status": "summary_updated",
                            }
                            event.work_item_run_state = expected_run_state
                    completion_kwargs = {}
                    if isinstance(expected_run_state, dict):
                        completion_kwargs["expected_run_state"] = expected_run_state
                    self._ledger().mark_completed(
                        str(work_item_id),
                        **completion_kwargs,
                    )
                except Exception as exc:
                    logger.debug("Discord work ledger summary completion update failed: %s", exc)
            return summary_ok

        try:
            adapter.register_post_delivery_callback(
                session_key,
                _deliver,
                generation=run_generation,
            )
        except Exception:
            logger.debug("Discord summary post-delivery registration failed", exc_info=True)

    async def _post_turn_goal_continuation(
        self,
        *,
        session_entry: Any,
        source: Any,
        final_response: str,
        runtime_breakdown: Optional[Dict[str, Any]] = None,
    ) -> None:
        """Run the goal judge after a gateway turn and, if still active,
        enqueue a continuation prompt for the same session.

        Called from ``_handle_message_with_agent`` at turn boundary, AFTER
        the response has been delivered. Safe when no goal is set.

        We use the adapter's pending-message / FIFO machinery so any real
        user message that arrives simultaneously is handled by the same
        queue and takes priority naturally.
        """
        try:
            from gateway.platforms.base import MessageEvent, MessageType
            from hermes_cli.discord_worker_boards import board_for_gateway_event

            probe = MessageEvent(
                text="",
                message_type=MessageType.TEXT,
                source=source,
                internal=True,
            )
            if board_for_gateway_event(probe, create=False) is not None:
                return
        except Exception:
            pass
        try:
            from hermes_cli.goals import GoalManager
        except Exception as exc:
            logger.debug("goal continuation: goals module unavailable: %s", exc)
            return

        sid = getattr(session_entry, "session_id", None) or ""
        if not sid:
            return

        max_turns = self._goal_max_turns_from_config()

        mgr = GoalManager(session_id=sid, default_max_turns=max_turns)
        if not mgr.is_active():
            return

        decision = mgr.evaluate_after_turn(
            final_response or "",
            user_initiated=True,
            runtime_breakdown=runtime_breakdown,
        )
        msg = decision.get("message") or ""

        # Defer the status line until after the adapter has delivered the
        # agent's visible final response. The judge runs after the response is
        # produced but before BasePlatformAdapter sends it, so sending here
        # would show "✓ Goal achieved" before the answer itself. Registering
        # an awaited post-delivery callback preserves delivery reliability
        # without reversing the user-visible ordering.
        if msg and source is not None:
            await self._defer_goal_status_notice_after_delivery(source, msg)

        if not decision.get("should_continue"):
            return

        prompt = decision.get("continuation_prompt") or ""
        if not prompt or source is None:
            return

        # Enqueue via the adapter's FIFO so a user message already in
        # flight preempts the continuation naturally.
        try:
            adapter = self._adapter_for_source(source)
            _quick_key = self._session_key_for_source(source)
            if adapter and _quick_key:
                cont_event = MessageEvent(
                    text=prompt,
                    message_type=MessageType.TEXT,
                    source=source,
                    message_id=None,
                    channel_prompt=None,
                )
                self._enqueue_fifo(_quick_key, cont_event, adapter)
        except Exception as exc:
            logger.debug("goal continuation: enqueue failed: %s", exc)

    async def _handle_undo_command(self, event: MessageEvent) -> str:
        """Handle /undo command - remove the last user/assistant exchange."""
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)
        history = await self.async_session_store.load_transcript(session_entry.session_id)

        # Find the last user message and remove everything from it onward
        last_user_idx = None
        for i in range(len(history) - 1, -1, -1):
            if history[i].get("role") == "user":
                last_user_idx = i
                break

        if last_user_idx is None:
            return t("gateway.undo.nothing")

        removed_msg = history[last_user_idx].get("content", "")
        removed_count = len(history) - last_user_idx
        await self.async_session_store.rewrite_transcript(session_entry.session_id, history[:last_user_idx])
        # Reset stored token count — transcript was truncated
        session_entry.last_prompt_tokens = 0

        preview = removed_msg[:40] + "..." if len(removed_msg) > 40 else removed_msg
        return t("gateway.undo.removed", count=removed_count, preview=preview)

    async def _handle_set_home_command(self, event: MessageEvent) -> str:
        """Handle /sethome command -- set the current chat as the platform's home channel."""
        source = event.source
        platform_name = source.platform.value if source.platform else "unknown"
        chat_id = source.chat_id
        chat_name = source.chat_name or chat_id

        env_key = _home_target_env_var(platform_name)
        thread_env_key = _home_thread_env_var(platform_name)
        thread_id = source.thread_id

        # Save to .env so it persists across restarts
        try:
            from hermes_cli.config import save_env_value
            save_env_value(env_key, str(chat_id))
            # Keep thread/topic routing explicit and clear stale values when
            # /sethome is run from the parent chat instead of a thread.
            save_env_value(thread_env_key, str(thread_id or ""))
        except Exception as e:
            return t("gateway.set_home.save_failed", error=e)

        # Keep the running gateway config in sync too. The pre-restart
        # notification path reads self.config before the process reloads env.
        if source.platform:
            platform_config = self.config.platforms.setdefault(
                source.platform,
                PlatformConfig(enabled=True),
            )
            platform_config.home_channel = HomeChannel(
                platform=source.platform,
                chat_id=str(chat_id),
                name=chat_name,
                thread_id=str(thread_id) if thread_id else None,
            )

        return t("gateway.set_home.success", name=chat_name, chat_id=chat_id)

    @staticmethod
    def _get_guild_id(event: MessageEvent) -> Optional[int]:
        """Extract Discord guild_id from the raw message object."""
        raw = getattr(event, "raw_message", None)
        if raw is None:
            return None
        # Slash command interaction
        if hasattr(raw, "guild_id") and raw.guild_id:
            return int(raw.guild_id)
        # Regular message
        if hasattr(raw, "guild") and raw.guild:
            return raw.guild.id
        return None

    async def _handle_voice_command(self, event: MessageEvent) -> str:
        """Handle /voice [on|off|tts|channel|leave|status] command."""
        args = event.get_command_args().strip().lower()
        chat_id = event.source.chat_id
        platform = event.source.platform
        voice_key = self._voice_key(platform, chat_id)

        adapter = self.adapters.get(platform)

        if args in {"on", "enable"}:
            self._voice_mode[voice_key] = "voice_only"
            self._save_voice_modes()
            if adapter:
                self._set_adapter_auto_tts_enabled(adapter, chat_id, enabled=True)
            return t("gateway.voice.enabled_voice_only")
        elif args in {"off", "disable"}:
            self._voice_mode[voice_key] = "off"
            self._save_voice_modes()
            if adapter:
                self._set_adapter_auto_tts_disabled(adapter, chat_id, disabled=True)
            return t("gateway.voice.disabled_text")
        elif args == "tts":
            self._voice_mode[voice_key] = "all"
            self._save_voice_modes()
            if adapter:
                self._set_adapter_auto_tts_enabled(adapter, chat_id, enabled=True)
            return t("gateway.voice.tts_enabled")
        elif args in {"channel", "join"}:
            if not _discord_live_voice_enabled():
                return (
                    "Live Discord voice-channel listening is disabled. "
                    "Send a recorded Discord voice message or audio attachment instead."
                )
            return await self._handle_voice_channel_join(event)
        elif args == "leave":
            return await self._handle_voice_channel_leave(event)
        elif args == "status":
            mode = self._voice_mode.get(voice_key, "off")
            labels = {
                "off": t("gateway.voice.label_off"),
                "voice_only": t("gateway.voice.label_voice_only"),
                "all": t("gateway.voice.label_all"),
            }
            # Append voice channel info if connected
            adapter = self._adapter_for_source(event.source)
            guild_id = self._get_guild_id(event)
            if guild_id and hasattr(adapter, "get_voice_channel_info"):
                info = adapter.get_voice_channel_info(guild_id)
                if info:
                    lines = [
                        t("gateway.voice.status_mode", label=labels.get(mode, mode)),
                        t("gateway.voice.status_channel", channel=info['channel_name']),
                        t("gateway.voice.status_participants", count=info['member_count']),
                    ]
                    for m in info["members"]:
                        status = t("gateway.voice.speaking") if m.get("is_speaking") else ""
                        lines.append(t("gateway.voice.status_member", name=m['display_name'], status=status))
                    return "\n".join(lines)
            return t("gateway.voice.status_mode", label=labels.get(mode, mode))
        else:
            # Toggle: off → on, on/all → off
            current = self._voice_mode.get(voice_key, "off")
            if current == "off":
                self._voice_mode[voice_key] = "voice_only"
                self._save_voice_modes()
                if adapter:
                    self._set_adapter_auto_tts_enabled(adapter, chat_id, enabled=True)
                return t("gateway.voice.enabled_short")
            else:
                self._voice_mode[voice_key] = "off"
                self._save_voice_modes()
                if adapter:
                    self._set_adapter_auto_tts_disabled(adapter, chat_id, disabled=True)
                return t("gateway.voice.disabled_short")

    async def _handle_voice_channel_join(self, event: MessageEvent) -> str:
        """Join the user's current Discord voice channel."""
        if not _discord_live_voice_enabled():
            return (
                "Live Discord voice-channel listening is disabled. "
                "Send a recorded Discord voice message or audio attachment instead."
            )

        adapter = self._adapter_for_source(event.source)
        if not hasattr(adapter, "join_voice_channel"):
            return "Voice channels are not supported on this platform."

        guild_id = self._get_guild_id(event)
        if not guild_id:
            return "This command only works in a Discord server."

        voice_channel = await adapter.get_user_voice_channel(
            guild_id, event.source.user_id
        )
        if not voice_channel:
            return "You need to be in a voice channel first."

        # Wire callbacks BEFORE join so voice input arriving immediately
        # after connection is not lost.
        if hasattr(adapter, "_voice_input_callback"):
            adapter._voice_input_callback = self._handle_voice_channel_input
        if hasattr(adapter, "_on_voice_disconnect"):
            adapter._on_voice_disconnect = self._handle_voice_timeout_cleanup
        # Let the adapter's inactivity timer see the live voice-reply mode so it
        # doesn't disconnect a deliberately text-only (/voice off) session.
        if hasattr(adapter, "_voice_mode_getter"):
            adapter._voice_mode_getter = lambda chat_id: self._voice_mode.get(
                self._voice_key(Platform.DISCORD, str(chat_id)), "off"
            )

        try:
            success = await adapter.join_voice_channel(voice_channel)
        except Exception as e:
            logger.warning("Failed to join voice channel: %s", e)
            adapter._voice_input_callback = None
            err_lower = str(e).lower()
            if "pynacl" in err_lower or "nacl" in err_lower or "davey" in err_lower:
                return (
                    "Voice dependencies are missing (PyNaCl / davey). "
                    f"Install with: `{sys.executable} -m pip install PyNaCl`"
                )
            return f"Failed to join voice channel: {e}"

        if success:
            adapter._voice_text_channels[guild_id] = int(event.source.chat_id)
            if hasattr(adapter, "_voice_sources"):
                adapter._voice_sources[guild_id] = event.source.to_dict()
            self._voice_mode[self._voice_key(event.source.platform, event.source.chat_id)] = "all"
            self._save_voice_modes()
            self._set_adapter_auto_tts_enabled(adapter, event.source.chat_id, enabled=True)
            return (
                f"Joined voice channel **{voice_channel.name}**.\n"
                f"I'll speak my replies and listen to you. Use /voice leave to disconnect."
            )
        # Join failed — clear callback
        adapter._voice_input_callback = None
        return "Failed to join voice channel. Check bot permissions (Connect + Speak)."

    async def _handle_voice_channel_leave(self, event: MessageEvent) -> str:
        """Leave the Discord voice channel."""
        adapter = self._adapter_for_source(event.source)
        guild_id = self._get_guild_id(event)

        if not guild_id or not hasattr(adapter, "leave_voice_channel"):
            return "Not in a voice channel."

        if not hasattr(adapter, "is_in_voice_channel") or not adapter.is_in_voice_channel(guild_id):
            return "Not in a voice channel."

        try:
            await adapter.leave_voice_channel(guild_id)
        except Exception as e:
            logger.warning("Error leaving voice channel: %s", e)
        # Always clean up state even if leave raised an exception
        self._voice_mode[self._voice_key(event.source.platform, event.source.chat_id)] = "off"
        self._save_voice_modes()
        self._set_adapter_auto_tts_disabled(adapter, event.source.chat_id, disabled=True)
        if hasattr(adapter, "_voice_input_callback"):
            adapter._voice_input_callback = None
        return "Left voice channel."

    def _handle_voice_timeout_cleanup(self, chat_id: str) -> None:
        """Called by the adapter when a voice channel times out.

        Cleans up runner-side voice_mode state that the adapter cannot reach.
        """
        self._voice_mode[self._voice_key(Platform.DISCORD, chat_id)] = "off"
        self._save_voice_modes()
        adapter = self.adapters.get(Platform.DISCORD)
        self._set_adapter_auto_tts_disabled(adapter, chat_id, disabled=True)

    def _is_duplicate_voice_transcript(self, guild_id: int, user_id: int, transcript: str) -> bool:
        """Suppress repeated STT outputs for the same recent utterance.

        Voice capture can occasionally emit the same utterance twice a few
        seconds apart, which creates a second queued agent run and overlapping
        spoken replies. Dedup exact and near-exact repeats per guild/user over a
        short window while allowing genuinely new turns through.
        """
        from difflib import SequenceMatcher

        normalized = re.sub(r"\s+", " ", transcript).strip().lower()
        normalized = re.sub(r"[^\w\s]", "", normalized)
        if not normalized:
            return False

        now = time.monotonic()
        window_seconds = 12.0
        key = (guild_id, user_id)
        recent_store = getattr(self, "_recent_voice_transcripts", None)
        if not isinstance(recent_store, dict):
            recent_store = {}
            self._recent_voice_transcripts = recent_store
        recent = [
            (ts, txt)
            for ts, txt in recent_store.get(key, [])
            if now - ts <= window_seconds
        ]

        for _, prior in recent:
            if prior == normalized:
                recent_store[key] = recent
                return True
            if len(prior) >= 16 and len(normalized) >= 16:
                if SequenceMatcher(None, prior, normalized).ratio() >= 0.95:
                    recent_store[key] = recent
                    return True

        recent.append((now, normalized))
        recent_store[key] = recent[-5:]
        return False

    async def _handle_voice_channel_input(
        self, guild_id: int, user_id: int, transcript: str
    ):
        """Handle transcribed voice from a user in a voice channel.

        Creates a synthetic MessageEvent and processes it through the
        adapter's full message pipeline (session, typing, agent, TTS reply).
        """
        adapter = self.adapters.get(Platform.DISCORD)
        if not adapter:
            return

        text_ch_id = adapter._voice_text_channels.get(guild_id)
        if not text_ch_id:
            return

        # Build source — reuse the linked text channel's metadata when available
        # so voice input shares the same session as the bound text conversation.
        source_data = getattr(adapter, "_voice_sources", {}).get(guild_id)
        if source_data:
            source = SessionSource.from_dict(source_data)
            source.user_id = str(user_id)
            source.user_name = str(user_id)
        else:
            source = SessionSource(
                platform=Platform.DISCORD,
                chat_id=str(text_ch_id),
                user_id=str(user_id),
                user_name=str(user_id),
                chat_type="channel",
            )

        # Check authorization before processing voice input
        if not self._is_user_authorized(source):
            logger.debug("Unauthorized voice input from user %d, ignoring", user_id)
            return

        if self._is_duplicate_voice_transcript(guild_id, user_id, transcript):
            logger.info(
                "Suppressing duplicate voice transcript for guild=%s user=%s: %s",
                guild_id,
                user_id,
                transcript[:100],
            )
            return

        # Show transcript in text channel (after auth, with mention sanitization)
        try:
            channel = adapter._client.get_channel(text_ch_id)
            if channel:
                safe_text = transcript[:2000].replace("@everyone", "@\u200beveryone").replace("@here", "@\u200bhere")
                await channel.send(f"**[Voice]** <@{user_id}>: {safe_text}")
        except Exception:
            pass

        # Build a synthetic MessageEvent and feed through the normal pipeline
        # Use SimpleNamespace as raw_message so _get_guild_id() can extract
        # guild_id and _send_voice_reply() plays audio in the voice channel.
        from types import SimpleNamespace
        event = MessageEvent(
            source=source,
            text=transcript,
            message_type=MessageType.VOICE,
            raw_message=SimpleNamespace(guild_id=guild_id, guild=None),
        )

        await adapter.handle_message(event)

    def _should_send_voice_reply(
        self,
        event: MessageEvent,
        response: str,
        agent_messages: list,
        already_sent: bool = False,
    ) -> bool:
        """Decide whether the runner should send a TTS voice reply.

        Returns False when:
        - voice_mode is off for this chat
        - response is empty or an error
        - agent already called text_to_speech tool (dedup)
        - voice input and base adapter auto-TTS already handled it (skip_double)
          UNLESS streaming already consumed the response (already_sent=True),
          in which case the base adapter won't have text for auto-TTS so the
          runner must handle it.
        """
        if not response or response.startswith("Error:"):
            return False

        chat_id = event.source.chat_id
        voice_mode = self._voice_mode.get(self._voice_key(event.source.platform, chat_id), "off")
        is_voice_input = (event.message_type == MessageType.VOICE)

        should = (
            (voice_mode == "all")
            or (voice_mode == "voice_only" and is_voice_input)
        )
        if not should:
            return False

        # Dedup: agent already called TTS tool
        has_agent_tts = any(
            msg.get("role") == "assistant"
            and any(
                tc.get("function", {}).get("name") == "text_to_speech"
                for tc in (msg.get("tool_calls") or [])
            )
            for msg in agent_messages
        )
        if has_agent_tts:
            return False

        # Dedup: base adapter auto-TTS already handles voice input
        # (play_tts plays in VC when connected, so runner can skip).
        # When streaming already delivered the text (already_sent=True),
        # the base adapter will receive None and can't run auto-TTS,
        # so the runner must take over.
        if is_voice_input and not already_sent:
            return False

        return True

    def _should_echo_stt_transcripts(self) -> bool:
        """Return whether inbound voice/STT transcripts should be echoed to chat."""
        return bool(getattr(self.config, "stt_echo_transcripts", True))

    async def _send_voice_reply(self, event: MessageEvent, text: str) -> None:
        """Generate TTS audio and send as a voice message before the text reply."""
        import uuid as _uuid
        audio_path = None
        actual_path = None
        try:
            from tools.tts_tool import text_to_speech_tool, _strip_markdown_for_tts

            tts_text = _strip_markdown_for_tts(text[:4000])
            if not tts_text:
                return

            # Telegram's adapter only sends native voice bubbles for OGG/Opus.
            # Other platforms keep the existing MP3 default.
            audio_ext = "ogg" if event.source.platform == Platform.TELEGRAM else "mp3"
            audio_path = os.path.join(
                tempfile.gettempdir(), "hermes_voice",
                f"tts_reply_{_uuid.uuid4().hex[:12]}.{audio_ext}",
            )
            os.makedirs(os.path.dirname(audio_path), exist_ok=True)

            result_json = await asyncio.to_thread(
                text_to_speech_tool, text=tts_text, output_path=audio_path
            )
            try:
                result = json.loads(result_json)
            except (json.JSONDecodeError, TypeError):
                logger.warning("Auto voice reply TTS returned invalid JSON: %s", result_json[:200] if result_json else result_json)
                return

            # Use the actual file path from result (may differ after opus conversion)
            actual_path = result.get("file_path", audio_path)
            if not result.get("success") or not os.path.isfile(actual_path):
                logger.warning("Auto voice reply TTS failed: %s", result.get("error"))
                return

            adapter = self._adapter_for_source(event.source)

            # If connected to a voice channel, play there instead of sending a file
            guild_id = self._get_guild_id(event)
            if (guild_id
                    and hasattr(adapter, "play_in_voice_channel")
                    and hasattr(adapter, "is_in_voice_channel")
                    and adapter.is_in_voice_channel(guild_id)):
                await adapter.play_in_voice_channel(guild_id, actual_path)
            elif adapter and hasattr(adapter, "send_voice"):
                reply_anchor = self._reply_anchor_for_event(event)
                thread_meta = self._thread_metadata_for_source(event.source, reply_anchor)
                # Mark the auto voice reply as notify-worthy.  Mirrors the
                # final-text path in gateway/platforms/base.py which sets
                # ``notify=True`` so platform adapters that gate push
                # notifications (Telegram "important" mode) deliver the
                # final voice reply as a normal notification instead of a
                # silent message.  Clone first so we don't mutate metadata
                # shared with concurrent typing-indicator state.
                if thread_meta is not None:
                    thread_meta = dict(thread_meta)
                    thread_meta["notify"] = True
                else:
                    thread_meta = {"notify": True}
                send_kwargs: Dict[str, Any] = {
                    "chat_id": event.source.chat_id,
                    "audio_path": actual_path,
                    "reply_to": reply_anchor,
                    "metadata": thread_meta,
                }
                await adapter.send_voice(**send_kwargs)
        except Exception as e:
            logger.warning("Auto voice reply failed: %s", e, exc_info=True)
        finally:
            for p in {audio_path, actual_path} - {None}:
                try:
                    os.unlink(p)
                except OSError:
                    pass

    async def _deliver_media_from_response(
        self,
        response: str,
        event: MessageEvent,
        adapter,
        *,
        message_id: Optional[str] = None,
    ) -> None:
        """Extract MEDIA: tags and local file paths from a response and deliver them.

        Called after streaming has already sent the text to the user, so the
        text itself is already delivered — this only handles file attachments
        that the normal _process_message_background path would have caught.
        """
        from pathlib import Path
        from urllib.parse import quote as _quote, unquote as _unquote

        try:
            # Capture [[as_document]] before extract_media strips it, so the
            # dispatch partition below can route image-extension files
            # through send_document (preserving bytes) instead of
            # send_multiple_images (Telegram sendPhoto recompresses to ~1280px).
            force_document_attachments = "[[as_document]]" in response

            from gateway.platforms.base import (
                BasePlatformAdapter,
                SendResult,
                _deduplicate_delivery_paths,
                get_confirmed_message_ids,
                should_send_media_as_audio,
            )

            media_files, cleaned = adapter.extract_media(response)
            media_files = BasePlatformAdapter.filter_media_delivery_paths(media_files)
            # Chain the cleaned text through each extractor (extract_media →
            # extract_images → extract_local_files) so MEDIA: tags and image URLs
            # are removed before the bare-path auto-detect runs. Previously the
            # cleaned text from extract_media was dropped (``_``) and
            # extract_local_files scanned text that still contained MEDIA: tags,
            # producing false-positive bare-path matches with the MEDIA: prefix
            # glued on. This matches the chain order in gateway/platforms/base.py.
            images, cleaned = adapter.extract_images(cleaned)
            local_files, _ = adapter.extract_local_files(cleaned)
            local_files = BasePlatformAdapter.filter_local_delivery_paths(local_files)
            media_files, local_files = _deduplicate_delivery_paths(
                media_files,
                local_files,
            )
            delivery_results = []

            _thread_meta = self._thread_metadata_for_source(event.source, self._reply_anchor_for_event(event))

            _VIDEO_EXTS = {'.mp4', '.mov', '.avi', '.mkv', '.webm', '.3gp'}
            _IMAGE_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.gif'}

            # Partition out images so they can be sent as a single batch
            # (e.g. Signal's multi-attachment RPC). When [[as_document]] was
            # set, image-extension files skip the photo path and route to
            # send_document below — preserving original bytes.
            image_paths: list = []
            non_image_media: list = []
            for media_path, is_voice in media_files:
                ext = Path(media_path).suffix.lower()
                if (ext in _IMAGE_EXTS
                        and not is_voice
                        and not force_document_attachments):
                    image_paths.append(media_path)
                else:
                    non_image_media.append((media_path, is_voice))

            non_image_local: list = []
            for file_path in local_files:
                if (Path(file_path).suffix.lower() in _IMAGE_EXTS
                        and not force_document_attachments):
                    image_paths.append(file_path)
                else:
                    non_image_local.append(file_path)

            # Discord can add local files to the final streamed message via
            # Message.edit(attachments=...). Prefer that over a second empty
            # attachment-only message so the evidence belongs to the response.
            attach_to_message = getattr(adapter, "attach_local_files_to_message", None)
            if message_id and callable(attach_to_message):
                attach_paths = list(image_paths)
                attach_paths.extend(
                    _unquote(image_url[7:])
                    for image_url, _alt_text in images
                    if image_url.startswith("file://")
                )
                attach_paths.extend(
                    media_path
                    for media_path, is_voice in non_image_media
                    if not should_send_media_as_audio(
                        event.source.platform,
                        Path(media_path).suffix.lower(),
                        is_voice=is_voice,
                    )
                )
                attach_paths.extend(non_image_local)
                attach_paths = list(dict.fromkeys(attach_paths))
                if attach_paths:
                    attach_result = await attach_to_message(
                        chat_id=event.source.chat_id,
                        message_id=message_id,
                        file_paths=attach_paths,
                        metadata=_thread_meta,
                    )
                    if isinstance(attach_result, SendResult):
                        delivery_results.append(attach_result)
                    if attach_result is not None and (
                        attach_result.success or attach_result.retry_safe is False
                    ):
                        attached = set(attach_paths)
                        image_paths = [path for path in image_paths if path not in attached]
                        images = [
                            item
                            for item in images
                            if not (
                                item[0].startswith("file://")
                                and _unquote(item[0][7:]) in attached
                            )
                        ]
                        non_image_media = [
                            item for item in non_image_media if item[0] not in attached
                        ]
                        non_image_local = [
                            path for path in non_image_local if path not in attached
                        ]

            if images or image_paths:
                try:
                    combined_images = list(images)
                    combined_images.extend((f"file://{_quote(p)}", "") for p in image_paths)
                    deduplicated_images = []
                    seen_images = set()
                    for image_url, alt_text in combined_images:
                        key = (
                            f"file://{os.path.realpath(_unquote(image_url[7:]))}"
                            if image_url.startswith("file://")
                            else image_url
                        )
                        if key in seen_images:
                            continue
                        seen_images.add(key)
                        deduplicated_images.append((image_url, alt_text))
                    result = await adapter.send_multiple_images(
                        chat_id=event.source.chat_id,
                        images=deduplicated_images,
                        metadata=_thread_meta,
                    )
                    if isinstance(result, SendResult):
                        delivery_results.append(result)
                except Exception as e:
                    logger.warning("[%s] Post-stream image batch delivery failed: %s", adapter.name, e)
                    delivery_results.append(SendResult(success=False, error=str(e)))

            for media_path, is_voice in non_image_media:
                try:
                    ext = Path(media_path).suffix.lower()
                    if should_send_media_as_audio(event.source.platform, ext, is_voice=is_voice):
                        result = await adapter.send_voice(
                            chat_id=event.source.chat_id,
                            audio_path=media_path,
                            metadata=_thread_meta,
                        )
                    elif ext in _VIDEO_EXTS:
                        result = await adapter.send_video(
                            chat_id=event.source.chat_id,
                            video_path=media_path,
                            metadata=_thread_meta,
                        )
                    else:
                        result = await adapter.send_document(
                            chat_id=event.source.chat_id,
                            file_path=media_path,
                            metadata=_thread_meta,
                        )
                    if isinstance(result, SendResult):
                        delivery_results.append(result)
                except Exception as e:
                    logger.warning("[%s] Post-stream media delivery failed: %s", adapter.name, e)
                    delivery_results.append(SendResult(success=False, error=str(e)))

            for file_path in non_image_local:
                try:
                    ext = Path(file_path).suffix.lower()
                    if ext in _VIDEO_EXTS:
                        result = await adapter.send_video(
                            chat_id=event.source.chat_id,
                            video_path=file_path,
                            metadata=_thread_meta,
                        )
                    else:
                        result = await adapter.send_document(
                            chat_id=event.source.chat_id,
                            file_path=file_path,
                            metadata=_thread_meta,
                        )
                    if isinstance(result, SendResult):
                        delivery_results.append(result)
                except Exception as e:
                    logger.warning("[%s] Post-stream file delivery failed: %s", adapter.name, e)
                    delivery_results.append(SendResult(success=False, error=str(e)))

            failures = [result for result in delivery_results if not result.success]
            confirmed_ids = tuple(
                message_id
                for result in delivery_results
                for message_id in get_confirmed_message_ids(result)
            )
            return SendResult(
                success=not failures,
                message_id=confirmed_ids[0] if confirmed_ids else None,
                confirmed_message_ids=confirmed_ids,
                error="; ".join(str(result.error or "media delivery failed") for result in failures) or None,
                retryable=any(result.retryable for result in failures),
                retry_safe=all(result.retry_safe is not False for result in failures) if failures else False,
            )

        except Exception as e:
            logger.warning("Post-stream media extraction failed: %s", e)
            from gateway.platforms.base import SendResult
            return SendResult(success=False, error=str(e))

    async def _handle_rollback_command(self, event: MessageEvent) -> str:
        """Handle /rollback command — list or restore filesystem checkpoints."""
        from tools.checkpoint_manager import CheckpointManager, format_checkpoint_list

        # Read checkpoint config from config.yaml
        cp_cfg = {}
        try:
            import yaml as _y
            _cfg_path = _hermes_home / "config.yaml"
            if _cfg_path.exists():
                with open(_cfg_path, encoding="utf-8") as _f:
                    _data = _y.safe_load(_f) or {}
                cp_cfg = _data.get("checkpoints", {})
                if isinstance(cp_cfg, bool):
                    cp_cfg = {"enabled": cp_cfg}
        except Exception:
            pass

        if not cp_cfg.get("enabled", False):
            return t("gateway.rollback.not_enabled")

        mgr = CheckpointManager(
            enabled=True,
            max_snapshots=cp_cfg.get("max_snapshots", 50),
            max_total_size_mb=cp_cfg.get("max_total_size_mb", 500),
            max_file_size_mb=cp_cfg.get("max_file_size_mb", 10),
        )

        from gateway.session_context import get_session_env

        cwd = get_session_env("HERMES_SESSION_CWD", "") or os.getenv("TERMINAL_CWD", str(Path.home()))
        arg = event.get_command_args().strip()

        if not arg:
            checkpoints = mgr.list_checkpoints(cwd)
            return format_checkpoint_list(checkpoints, cwd)

        # Restore by number or hash
        checkpoints = mgr.list_checkpoints(cwd)
        if not checkpoints:
            return t("gateway.rollback.none_found", cwd=cwd)

        target_hash = None
        try:
            idx = int(arg) - 1
            if 0 <= idx < len(checkpoints):
                target_hash = checkpoints[idx]["hash"]
            else:
                return t("gateway.rollback.invalid_number", max=len(checkpoints))
        except ValueError:
            target_hash = arg

        result = mgr.restore(cwd, target_hash)
        if result["success"]:
            return t(
                "gateway.rollback.restored",
                hash=result["restored_to"],
                reason=result["reason"],
            )
        return t("gateway.rollback.restore_failed", error=result["error"])

    def _background_registry_parts(self) -> tuple[threading.Lock, Dict[str, Dict[str, Any]]]:
        """Return lazily initialized /background ownership state for tests too."""
        lock = self.__dict__.get("_background_agent_lock")
        if lock is None:
            lock = threading.Lock()
            self._background_agent_lock = lock
        records = self.__dict__.get("_background_agents")
        if records is None:
            records = {}
            self._background_agents = records
        return lock, records

    @staticmethod
    def _background_record_active(record: Dict[str, Any]) -> bool:
        return str(record.get("state") or "") in {"starting", "running"}

    def _prune_background_records_locked(
        self, records: Dict[str, Dict[str, Any]]
    ) -> None:
        terminal = [
            (task_id, record)
            for task_id, record in records.items()
            if not self._background_record_active(record)
        ]
        if len(terminal) <= 50:
            return
        terminal.sort(
            key=lambda item: float(
                item[1].get("completed_at") or item[1].get("started_at") or 0
            )
        )
        for task_id, _record in terminal[: len(terminal) - 50]:
            records.pop(task_id, None)

    def _register_background_record(
        self, task_id: str, session_key: str, source: SessionSource
    ) -> None:
        lock, records = self._background_registry_parts()
        with lock:
            records[task_id] = {
                "task_id": task_id,
                "session_key": str(session_key or ""),
                "platform": getattr(source.platform, "value", str(source.platform)),
                "chat_id": str(getattr(source, "chat_id", "") or ""),
                "thread_id": str(getattr(source, "thread_id", "") or ""),
                "user_id": str(getattr(source, "user_id", "") or ""),
                "outer_task": None,
                "agent": None,
                "cancel_requested": False,
                "cancel_reason": "",
                "cancel_requested_at": None,
                "started_at": time.time(),
                "completed_at": None,
                "state": "starting",
                "agent_finished": False,
                "outer_done": False,
            }
            self._prune_background_records_locked(records)

    def _bind_background_outer_task(self, task_id: str, task: asyncio.Task) -> None:
        lock, records = self._background_registry_parts()
        cancel_now = False
        with lock:
            record = records.get(task_id)
            if record is not None:
                record["outer_task"] = task
                cancel_now = bool(record.get("cancel_requested"))
        if cancel_now and not task.done():
            task.cancel()

    def _background_outer_done(self, task_id: str, task: asyncio.Task) -> None:
        background = self.__dict__.setdefault("_background_tasks", set())
        background.discard(task)
        lock, records = self._background_registry_parts()
        with lock:
            record = records.get(task_id)
            if record is None or record.get("outer_task") is not task:
                return
            record["outer_done"] = True
            if record.get("cancel_requested"):
                record["state"] = "cancelled"
            elif task.cancelled():
                record["state"] = "cancelled"
            elif task.exception() is not None:
                record["state"] = "error"
            else:
                record["state"] = "completed"
            record["completed_at"] = time.time()
            self._prune_background_records_locked(records)

    def _publish_background_agent(self, task_id: str, agent: Any) -> bool:
        """Publish the live executor-thread agent before starting inference."""
        lock, records = self._background_registry_parts()
        cancelled = True
        with lock:
            record = records.get(task_id)
            if record is not None:
                record["agent"] = agent
                cancelled = bool(record.get("cancel_requested"))
                record["state"] = "cancelled" if cancelled else "running"
        if cancelled:
            try:
                agent.interrupt("Stop requested")
            except Exception:
                logger.debug(
                    "Could not interrupt pre-cancelled background agent %s",
                    task_id,
                    exc_info=True,
                )
        return not cancelled

    def _mark_background_agent_finished(self, task_id: str, agent: Any) -> None:
        lock, records = self._background_registry_parts()
        with lock:
            record = records.get(task_id)
            if record is None or record.get("agent") is not agent:
                return
            record["agent_finished"] = True
            record["agent"] = None
            if record.get("outer_done") and record.get("completed_at") is None:
                record["completed_at"] = time.time()
            self._prune_background_records_locked(records)

    def _background_delivery_allowed(self, task_id: str) -> bool:
        lock, records = self._background_registry_parts()
        with lock:
            record = records.get(task_id)
            return bool(record is not None and not record.get("cancel_requested"))

    def _cancel_background_agents_for_session(
        self, session_key: str, *, reason: str = "Stop requested"
    ) -> Dict[str, int]:
        """Mark then cooperatively stop /background agents for one session."""
        lock, records = self._background_registry_parts()
        targets: List[tuple[str, Any, Any]] = []
        matched = 0
        now = time.time()
        with lock:
            for task_id, record in records.items():
                if (
                    str(record.get("session_key") or "") != str(session_key or "")
                    or not self._background_record_active(record)
                ):
                    continue
                matched += 1
                if record.get("cancel_requested"):
                    continue
                record["cancel_requested"] = True
                record["cancel_reason"] = str(reason or "Stop requested")[:240]
                record["cancel_requested_at"] = now
                record["state"] = "cancelled"
                targets.append((task_id, record.get("agent"), record.get("outer_task")))

        interrupted = 0
        tasks_cancelled = 0
        failures = 0
        for task_id, agent, task in targets:
            if agent is not None:
                try:
                    agent.interrupt("Stop requested")
                    interrupted += 1
                except Exception:
                    failures += 1
                    logger.debug(
                        "Could not interrupt background agent %s",
                        task_id,
                        exc_info=True,
                    )
            if task is not None and not task.done():
                try:
                    task.cancel()
                    tasks_cancelled += 1
                except Exception:
                    failures += 1
                    logger.debug(
                        "Could not cancel background delivery task %s",
                        task_id,
                        exc_info=True,
                    )
        return {
            "matched": matched,
            "newly_cancelled": len(targets),
            "agents_interrupted": interrupted,
            "tasks_cancelled": tasks_cancelled,
            "failures": failures,
        }

    def _background_session_keys_for_scope(self, source: SessionSource) -> List[str]:
        platform = getattr(source.platform, "value", str(source.platform))
        chat_id = str(getattr(source, "chat_id", "") or "")
        thread_id = str(getattr(source, "thread_id", "") or "")
        if not chat_id or not thread_id:
            return []
        lock, records = self._background_registry_parts()
        with lock:
            keys = {
                str(record.get("session_key") or "")
                for record in records.values()
                if self._background_record_active(record)
                and not record.get("cancel_requested")
                and str(record.get("platform") or "") == platform
                and str(record.get("chat_id") or "") == chat_id
                and str(record.get("thread_id") or "") == thread_id
                and str(record.get("session_key") or "")
            }
        return sorted(keys)[:32]

    async def _handle_background_command(self, event: MessageEvent) -> str:
        """Handle /background <prompt> — run a prompt in a separate background session.

        Spawns a new AIAgent in a background thread with its own session.
        When it completes, sends the result back to the same chat without
        modifying the active session's conversation history.
        """
        prompt = event.get_command_args().strip()
        if not prompt:
            return t("gateway.background.usage")

        source = event.source
        task_id = f"bg_{datetime.now().strftime('%H%M%S')}_{os.urandom(3).hex()}"
        try:
            session_key = self._session_key_for_source(source)
        except Exception:
            session_key = build_session_key(source)
        self._register_background_record(task_id, session_key, source)

        event_message_id = self._reply_anchor_for_event(event)

        # Forward image/audio attachments so the background agent can see them.
        media_urls = list(event.media_urls) if event.media_urls else []
        media_types = list(event.media_types) if event.media_types else []

        # Fire-and-forget the background task
        _task = asyncio.create_task(
            self._run_background_task(
                prompt,
                source,
                task_id,
                event_message_id=event_message_id,
                media_urls=media_urls,
                media_types=media_types,
            )
        )
        self.__dict__.setdefault("_background_tasks", set()).add(_task)
        self._bind_background_outer_task(task_id, _task)
        _task.add_done_callback(
            lambda task, owned_task_id=task_id: self._background_outer_done(
                owned_task_id, task
            )
        )

        preview = prompt[:60] + ("..." if len(prompt) > 60 else "")
        return t("gateway.background.started", preview=preview, task_id=task_id)

    async def _run_background_task(
        self,
        prompt: str,
        source: "SessionSource",
        task_id: str,
        event_message_id: Optional[str] = None,
        media_urls: Optional[List[str]] = None,
        media_types: Optional[List[str]] = None,
    ) -> None:
        """Profile-scoping wrapper around the background agent task.

        When multiplexing is active, resolve the inbound source's profile and
        run the whole task inside ``_profile_runtime_scope`` so credentials
        resolve from that profile's secret scope. Mirrors the pattern in
        ``_run_agent``.
        """
        lock, records = self._background_registry_parts()
        with lock:
            needs_record = task_id not in records
        if needs_record:
            try:
                session_key = self._session_key_for_source(source)
            except Exception:
                session_key = build_session_key(source)
            self._register_background_record(task_id, session_key, source)
        try:
            if not getattr(getattr(self, "config", None), "multiplex_profiles", False):
                return await self._run_background_task_inner(
                    prompt, source, task_id, event_message_id, media_urls, media_types,
                )

            profile_home = self._resolve_profile_home_for_source(source)
            with _profile_runtime_scope(profile_home):
                return await self._run_background_task_inner(
                    prompt, source, task_id, event_message_id, media_urls, media_types,
                )
        finally:
            if needs_record:
                lock, records = self._background_registry_parts()
                with lock:
                    record = records.get(task_id)
                    if record is not None and record.get("outer_task") is None:
                        record["outer_done"] = True
                        record["state"] = (
                            "cancelled"
                            if record.get("cancel_requested")
                            else "completed"
                        )
                        record["completed_at"] = time.time()
                        self._prune_background_records_locked(records)

    async def _run_background_task_inner(
        self,
        prompt: str,
        source: "SessionSource",
        task_id: str,
        event_message_id: Optional[str] = None,
        media_urls: Optional[List[str]] = None,
        media_types: Optional[List[str]] = None,
    ) -> None:
        """Execute a background agent task and deliver the result to the chat."""
        from run_agent import AIAgent

        media_urls = media_urls or []
        media_types = media_types or []

        adapter = self._adapter_for_source(source)
        if not adapter:
            logger.warning("No adapter for platform %s in background task %s", source.platform, task_id)
            return

        _thread_metadata = self._thread_metadata_for_source(source, event_message_id)

        try:
            user_config = _load_gateway_config()
            try:
                background_session_key = self._session_key_for_source(source)
            except Exception:
                background_session_key = ""
            model, runtime_kwargs = self._resolve_session_agent_runtime(
                source=source,
                user_config=user_config,
            )
            if not runtime_kwargs.get("api_key"):
                if self._background_delivery_allowed(task_id):
                    await adapter.send(
                        source.chat_id,
                        f"❌ Background task {task_id} failed: no provider credentials configured.",
                        metadata=_thread_metadata,
                    )
                return

            platform_key = _platform_config_key(source.platform)

            from hermes_cli.tools_config import _get_platform_tools
            enabled_toolsets = sorted(_get_platform_tools(user_config, platform_key))
            agent_cfg = user_config.get("agent") or {}
            disabled_toolsets = agent_cfg.get("disabled_toolsets") or None

            pr = self._provider_routing
            max_iterations, max_iterations_source = _current_max_iterations_with_source()
            reasoning_config = self._resolve_session_reasoning_config(source=source)
            self._reasoning_config = reasoning_config
            self._service_tier = self._load_service_tier()
            gateway_tier = _gateway_model_tier(user_config)
            background_model_override = bool(
                background_session_key
                and (getattr(self, "_session_model_overrides", {}) or {}).get(
                    background_session_key
                )
            )
            background_reasoning_override = bool(
                background_session_key
                and background_session_key
                in (getattr(self, "_session_reasoning_overrides", {}) or {})
            )
            turn_route = self._resolve_turn_agent_config(
                prompt, model, runtime_kwargs, user_config=user_config
            )

            # Enrich the prompt with image descriptions so the background
            # agent can see user-attached images (same as the main flow).
            enriched_prompt = prompt
            if media_urls:
                image_paths = []
                for i, path in enumerate(media_urls):
                    mtype = media_types[i] if i < len(media_types) else ""
                    if mtype.startswith("image/"):
                        image_paths.append(path)
                if image_paths:
                    try:
                        enriched_prompt = await self._enrich_message_with_vision(
                            prompt, image_paths,
                        )
                    except Exception as e:
                        logger.warning("Background task vision enrichment failed: %s", e)

            def run_sync():
                agent = AIAgent(
                    model=turn_route["model"],
                    **turn_route["runtime"],
                    max_iterations=max_iterations,
                    quiet_mode=True,
                    verbose_logging=False,
                    enabled_toolsets=enabled_toolsets,
                    disabled_toolsets=disabled_toolsets,
                    reasoning_config=reasoning_config,
                    service_tier=self._service_tier,
                    request_overrides=turn_route.get("request_overrides"),
                    providers_allowed=pr.get("only"),
                    providers_ignored=pr.get("ignore"),
                    providers_order=pr.get("order"),
                    provider_sort=pr.get("sort"),
                    provider_require_parameters=pr.get("require_parameters", False),
                    provider_data_collection=pr.get("data_collection"),
                    session_id=task_id,
                    platform=platform_key,
                    user_id=source.user_id,
                    user_id_alt=source.user_id_alt,
                    user_name=source.user_name,
                    chat_id=source.chat_id,
                    chat_name=source.chat_name,
                    chat_type=source.chat_type,
                    thread_id=source.thread_id,
                    session_db=self._session_db,
                    fallback_model=self._refresh_fallback_model(),
                )
                agent.max_iterations_source = max_iterations_source
                agent.max_iterations_route = f"gateway/background:{platform_key}"
                _set_gateway_runtime_audit(
                    agent,
                    model=turn_route["model"],
                    model_tier=gateway_tier,
                    runtime_route="gateway_background",
                    runtime_role="background",
                    reasoning_source=(
                        "session_override"
                        if background_reasoning_override
                        else "model_tier"
                        if gateway_tier is not None
                        else "agent_config"
                        if reasoning_config is not None
                        else "default"
                    ),
                    model_override_source=(
                        "session_override" if background_model_override else ""
                    ),
                )
                if not self._publish_background_agent(task_id, agent):
                    self._cleanup_agent_resources(agent)
                    self._mark_background_agent_finished(task_id, agent)
                    return {"cancelled": True, "final_response": ""}
                try:
                    return agent.run_conversation(
                        user_message=enriched_prompt,
                        task_id=task_id,
                    )
                finally:
                    self._cleanup_agent_resources(agent)
                    self._mark_background_agent_finished(task_id, agent)

            result = await self._run_in_executor_with_context(run_sync)

            response = result.get("final_response", "") if result else ""
            if not response and result and result.get("error"):
                response = f"Error: {result['error']}"

            # Extract media files from the response
            if response and self._background_delivery_allowed(task_id):
                media_files, response = adapter.extract_media(response)
                from gateway.platforms.base import BasePlatformAdapter
                media_files = BasePlatformAdapter.filter_media_delivery_paths(media_files)
                images, text_content = adapter.extract_images(response)

                preview = prompt[:60] + ("..." if len(prompt) > 60 else "")
                header = f'✅ Background task complete\nPrompt: "{preview}"\n\n'

                if text_content and self._background_delivery_allowed(task_id):
                    await adapter.send(
                        chat_id=source.chat_id,
                        content=header + text_content,
                        metadata=_thread_metadata,
                    )
                elif (
                    not images
                    and not media_files
                    and self._background_delivery_allowed(task_id)
                ):
                    await adapter.send(
                        chat_id=source.chat_id,
                        content=header + "(No response generated)",
                        metadata=_thread_metadata,
                    )

                # Send extracted images
                for image_url, alt_text in (images or []):
                    if not self._background_delivery_allowed(task_id):
                        break
                    try:
                        await adapter.send_image(
                            chat_id=source.chat_id,
                            image_url=image_url,
                            caption=alt_text,
                            metadata=_thread_metadata,
                        )
                    except Exception:
                        pass

                # Send media files, routing each by type so a TTS clip arrives
                # as a voice bubble and videos/images use native delivery.
                from gateway.platforms.base import (
                    should_send_media_as_audio as _should_send_media_as_audio,
                )

                _IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".gif", ".webp"}
                _VIDEO_EXTS = {".mp4", ".mov", ".avi", ".mkv", ".webm", ".3gp"}
                for media_path, _is_voice in (media_files or []):
                    if not self._background_delivery_allowed(task_id):
                        break
                    _ext = os.path.splitext(media_path)[1].lower()
                    try:
                        if _should_send_media_as_audio(source.platform, _ext, _is_voice):
                            await adapter.send_voice(
                                chat_id=source.chat_id,
                                audio_path=media_path,
                                metadata=_thread_metadata,
                            )
                        elif _ext in _VIDEO_EXTS:
                            await adapter.send_video(
                                chat_id=source.chat_id,
                                video_path=media_path,
                                metadata=_thread_metadata,
                            )
                        elif _ext in _IMAGE_EXTS:
                            await adapter.send_image_file(
                                chat_id=source.chat_id,
                                image_path=media_path,
                                metadata=_thread_metadata,
                            )
                        else:
                            await adapter.send_document(
                                chat_id=source.chat_id,
                                file_path=media_path,
                                metadata=_thread_metadata,
                            )
                    except Exception:
                        pass
            elif self._background_delivery_allowed(task_id):
                preview = prompt[:60] + ("..." if len(prompt) > 60 else "")
                await adapter.send(
                    chat_id=source.chat_id,
                    content=f'✅ Background task complete\nPrompt: "{preview}"\n\n(No response generated)',
                    metadata=_thread_metadata,
                )

        except Exception as e:
            logger.exception("Background task %s failed", task_id)
            try:
                if self._background_delivery_allowed(task_id):
                    await adapter.send(
                        chat_id=source.chat_id,
                        content=f"❌ Background task {task_id} failed: {e}",
                        metadata=_thread_metadata,
                    )
            except Exception:
                pass

    async def _handle_reasoning_command(self, event: MessageEvent) -> Optional[str]:
        """Use the upstream picker/session-aware reasoning implementation."""
        return await GatewaySlashCommandsMixin._handle_reasoning_command(self, event)

    async def _handle_fast_command(self, event: MessageEvent) -> str:
        """Use upstream's session-scoped fast mode without global leakage."""
        return await GatewaySlashCommandsMixin._handle_fast_command(self, event)

    async def _handle_yolo_command(self, event: MessageEvent) -> Union[str, EphemeralReply]:
        """Handle /yolo — toggle dangerous command approval bypass for this session only."""
        from tools.approval import (
            disable_session_yolo,
            enable_session_yolo,
            is_session_yolo_enabled,
        )

        session_key = self._session_key_for_source(event.source)
        current = is_session_yolo_enabled(session_key)
        if current:
            disable_session_yolo(session_key)
            return EphemeralReply(t("gateway.yolo.disabled"))
        else:
            enable_session_yolo(session_key)
            return EphemeralReply(t("gateway.yolo.enabled"))

    async def _handle_verbose_command(self, event: MessageEvent) -> str:
        """Handle /verbose command — cycle tool progress display mode.

        Gated by ``display.tool_progress_command`` in config.yaml (default off).
        When enabled, cycles the tool progress mode through off → new → all →
        verbose → off for the *current platform*.  The setting is saved to
        ``display.platforms.<platform>.tool_progress`` so each channel can
        have its own verbosity level independently.
        """

        config_path = _hermes_home / "config.yaml"
        platform_key = _platform_config_key(event.source.platform)

        # --- check config gate ------------------------------------------------
        try:
            user_config = _load_gateway_config()
            gate_enabled = is_truthy_value(
                cfg_get(user_config, "display", "tool_progress_command"),
                default=False,
            )
        except Exception:
            gate_enabled = False

        if not gate_enabled:
            return t("gateway.verbose.not_enabled")

        # --- cycle mode (per-platform) ----------------------------------------
        cycle = ["off", "new", "all", "verbose"]
        descriptions = {
            "off": t("gateway.verbose.mode_off"),
            "new": t("gateway.verbose.mode_new"),
            "all": t("gateway.verbose.mode_all"),
            "verbose": t("gateway.verbose.mode_verbose"),
        }

        # Read current effective mode for this platform via the resolver
        from gateway.display_config import resolve_display_setting
        current = resolve_display_setting(user_config, platform_key, "tool_progress", "all")
        if current not in cycle:
            current = "all"
        idx = (cycle.index(current) + 1) % len(cycle)
        new_mode = cycle[idx]

        # Save to display.platforms.<platform>.tool_progress
        try:
            if "display" not in user_config or not isinstance(user_config.get("display"), dict):
                user_config["display"] = {}
            display = user_config["display"]
            if "platforms" not in display or not isinstance(display.get("platforms"), dict):
                display["platforms"] = {}
            if platform_key not in display["platforms"] or not isinstance(display["platforms"].get(platform_key), dict):
                display["platforms"][platform_key] = {}
            display["platforms"][platform_key]["tool_progress"] = new_mode
            atomic_yaml_write(config_path, user_config)
            return (
                f"{descriptions[new_mode]}\n"
                + t("gateway.verbose.saved_suffix", platform=platform_key)
            )
        except Exception as e:
            logger.warning("Failed to save tool_progress mode: %s", e)
            return f"{descriptions[new_mode]}\n" + t("gateway.verbose.save_failed", error=e)

    async def _handle_footer_command(self, event: MessageEvent) -> str:
        """Handle /footer command — toggle the runtime-metadata footer.

        Usage:
            /footer           → toggle on/off
            /footer on        → enable globally
            /footer off       → disable globally
            /footer status    → show current state + fields

        The footer is saved to ``display.runtime_footer.enabled`` (global).
        Per-platform overrides under ``display.platforms.<platform>.runtime_footer``
        are respected but not modified here — edit config.yaml directly for
        per-platform control.
        """
        from gateway.runtime_footer import resolve_footer_config

        config_path = _hermes_home / "config.yaml"
        platform_key = _platform_config_key(event.source.platform)

        # --- parse argument -------------------------------------------------
        arg = ""
        try:
            text = (getattr(event, "message", None) or "").strip()
            if text.startswith("/"):
                parts = text.split(None, 1)
                if len(parts) > 1:
                    arg = parts[1].strip().lower()
        except Exception:
            arg = ""

        # --- load config ----------------------------------------------------
        try:
            user_config: dict = _load_gateway_config()
        except Exception as e:
            return t("gateway.config_read_failed", error=e)

        effective = resolve_footer_config(user_config, platform_key)

        if arg in {"status", "?"}:
            state = t("gateway.footer.state_on") if effective["enabled"] else t("gateway.footer.state_off")
            fields = ", ".join(effective.get("fields") or [])
            return t(
                "gateway.footer.status",
                state=state,
                fields=fields,
                platform=platform_key,
            )

        if arg in {"on", "enable", "true", "1"}:
            new_state = True
        elif arg in {"off", "disable", "false", "0"}:
            new_state = False
        elif arg == "":
            new_state = not effective["enabled"]
        else:
            return t("gateway.footer.usage")

        # --- write global flag ---------------------------------------------
        try:
            if not isinstance(user_config.get("display"), dict):
                user_config["display"] = {}
            display = user_config["display"]
            if not isinstance(display.get("runtime_footer"), dict):
                display["runtime_footer"] = {}
            display["runtime_footer"]["enabled"] = new_state
            atomic_yaml_write(config_path, user_config)
        except Exception as e:
            logger.warning("Failed to save runtime_footer.enabled: %s", e)
            return t("gateway.config_save_failed", error=e)

        state = t("gateway.footer.state_on") if new_state else t("gateway.footer.state_off")
        example = ""
        if new_state:
            # Show a preview using current agent state if available.
            from gateway.runtime_footer import format_runtime_footer
            preview = format_runtime_footer(
                model=_resolve_gateway_model(user_config) or None,
                context_tokens=0,
                context_length=None,
                fields=effective.get("fields") or ["model", "context_pct", "cwd"],
            )
            if preview:
                example = t("gateway.footer.example_line", preview=preview)
        return t("gateway.footer.saved", state=state, example=example)

    async def _handle_compress_command(self, event: MessageEvent) -> str:
        """Handle /compress command -- manually compress conversation context.

        Accepts an optional focus topic: ``/compress <focus>`` guides the
        summariser to preserve information related to *focus* while being
        more aggressive about discarding everything else.

        Also accepts the boundary-aware form ``/compress here [N]``:
        summarize everything except the most recent ``N`` exchanges
        (default 2), kept verbatim. Inspired by Claude Code's Rewind
        "Summarize up to here" action (v2.1.139, May 2026,
        https://code.claude.com/docs/en/whats-new/2026-w20).
        """
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)
        history = await self.async_session_store.load_transcript(session_entry.session_id)

        if not history or len(history) < 4:
            return t("gateway.compress.not_enough")

        # Parse args: either a focus topic (full compress) or the
        # boundary-aware "here [N]" form (partial compress).
        from hermes_cli.partial_compress import (
            parse_partial_compress_args,
            rejoin_compressed_head_and_tail,
            split_history_for_partial_compress,
        )
        _raw_args = (event.get_command_args() or "").strip()
        partial, keep_last, focus_topic = parse_partial_compress_args(_raw_args)

        try:
            from run_agent import AIAgent
            from agent.manual_compression_feedback import summarize_manual_compression
            from agent.model_metadata import estimate_request_tokens_rough

            session_key = self._session_key_for_source(source)
            model, runtime_kwargs = self._resolve_session_agent_runtime(
                source=source,
                session_key=session_key,
            )
            if not runtime_kwargs.get("api_key"):
                return t("gateway.compress.no_provider")

            msgs = [
                {"role": m.get("role"), "content": m.get("content")}
                for m in history
                if m.get("role") in {"user", "assistant"} and m.get("content")
            ]

            # Boundary-aware split: only the head is summarized; the most
            # recent `keep_last` exchanges are preserved verbatim. The
            # split snaps the tail to a user-turn start so the rejoined
            # transcript keeps role alternation valid.
            tail: list = []
            head = msgs
            if partial:
                head, tail = split_history_for_partial_compress(msgs, keep_last)
                if not tail:
                    # Degenerate split — fall back to full compression.
                    partial = False
                    head = msgs

            tmp_agent = AIAgent(
                **runtime_kwargs,
                model=model,
                max_iterations=4,
                quiet_mode=True,
                skip_memory=True,
                enabled_toolsets=["memory"],
                session_id=session_entry.session_id,
            )
            try:
                tmp_agent._print_fn = lambda *a, **kw: None

                # Estimate with system prompt + tool schemas included so the
                # figure reflects real request pressure, not a transcript-only
                # underestimate (#6217). Must be computed after tmp_agent is
                # built so _cached_system_prompt/tools are populated.
                _sys_prompt = getattr(tmp_agent, "_cached_system_prompt", "") or ""
                _tools = getattr(tmp_agent, "tools", None) or None
                approx_tokens = estimate_request_tokens_rough(
                    msgs, system_prompt=_sys_prompt, tools=_tools
                )

                compressor = tmp_agent.context_compressor
                if not compressor.has_content_to_compress(head):
                    return t("gateway.compress.nothing_to_do")

                loop = asyncio.get_running_loop()
                compressed, _ = await loop.run_in_executor(
                    None,
                    lambda: tmp_agent._compress_context(head, "", approx_tokens=approx_tokens, focus_topic=focus_topic, force=True)
                )

                # Re-append the verbatim tail after the compressed head,
                # guarding the seam against illegal role adjacency.
                if partial and tail:
                    compressed = rejoin_compressed_head_and_tail(compressed, tail)

                # _compress_context already calls end_session() on the old session
                # (preserving its full transcript in SQLite) and creates a new
                # session_id for the continuation.  Write the compressed messages
                # into the NEW session so the original history stays searchable.
                new_session_id = tmp_agent.session_id
                if new_session_id != session_entry.session_id:
                    session_entry.session_id = new_session_id
                    await self.async_session_store._save()
                    await asyncio.to_thread(self._sync_telegram_topic_binding, source, session_entry, reason="compress-command")

                await self.async_session_store.rewrite_transcript(new_session_id, compressed)
                # Reset stored token count — transcript changed, old value is stale
                await self.async_session_store.update_session(
                    session_entry.session_key, last_prompt_tokens=0
                )
                new_tokens = estimate_request_tokens_rough(
                    compressed, system_prompt=_sys_prompt, tools=_tools
                )
                summary = summarize_manual_compression(
                    msgs,
                    compressed,
                    approx_tokens,
                    new_tokens,
                )
                # Detect summary-generation failure so we can surface a
                # visible warning to the user even on the manual /compress
                # path (otherwise the failure is silently logged).
                # _last_compress_aborted means the aux LLM returned no
                # usable summary and the compressor preserved messages
                # unchanged (no drop, no placeholder).  force=True was
                # passed above so any active cooldown is bypassed.
                _summary_aborted = bool(getattr(compressor, "_last_compress_aborted", False))
                _summary_fallback = bool(getattr(compressor, "_last_summary_fallback_used", False))
                _summary_dropped = getattr(compressor, "_last_summary_dropped_count", 0) or 0
                _summary_err = getattr(compressor, "_last_summary_error", None)
                # Separately: did the user's CONFIGURED aux model fail
                # and we recovered via main?  Surface that as an info
                # note so they can fix their config.
                _aux_fail_model = getattr(compressor, "_last_aux_model_failure_model", None)
                _aux_fail_err = getattr(compressor, "_last_aux_model_failure_error", None)
            finally:
                # Evict cached agent so next turn rebuilds system prompt
                # from current files (SOUL.md, memory, etc.).
                self._evict_cached_agent(session_key)
                self._cleanup_agent_resources(tmp_agent)
            lines = [f"🗜️ {summary['headline']}"]
            if focus_topic:
                lines.append(t("gateway.compress.focus_line", topic=focus_topic))
            lines.append(summary["token_line"])
            if summary["note"]:
                lines.append(summary["note"])
            if _summary_aborted:
                lines.append(
                    t(
                        "gateway.compress.aborted",
                        error=(_summary_err or "unknown error"),
                    )
                )
            elif _summary_fallback:
                lines.append(
                    t(
                        "gateway.compress.summary_failed",
                        error=(_summary_err or "unknown error"),
                        count=_summary_dropped,
                    )
                )
            elif _aux_fail_model:
                lines.append(
                    t(
                        "gateway.compress.aux_failed",
                        model=_aux_fail_model,
                        error=(_aux_fail_err or "unknown error"),
                    )
                )
            return "\n".join(lines)
        except Exception as e:
            logger.warning("Manual compress failed: %s", e)
            return t("gateway.compress.failed", error=e)

    async def _get_telegram_topic_capabilities(self, source: SessionSource) -> dict:
        """Read Telegram private-topic capability flags via Bot API getMe."""
        adapter = self._adapter_for_source(source) if getattr(self, "adapters", None) else None
        bot = getattr(adapter, "_bot", None)
        if bot is None or not hasattr(bot, "get_me"):
            return {"checked": False}
        try:
            me = await bot.get_me()
        except Exception:
            logger.debug("Failed to fetch Telegram getMe topic capabilities", exc_info=True)
            return {"checked": False}

        def _field(name: str):
            if hasattr(me, name):
                return getattr(me, name)
            api_kwargs = getattr(me, "api_kwargs", None)
            if isinstance(api_kwargs, dict) and name in api_kwargs:
                return api_kwargs.get(name)
            if isinstance(me, dict):
                return me.get(name)
            return None

        return {
            "checked": True,
            "has_topics_enabled": _field("has_topics_enabled"),
            "allows_users_to_create_topics": _field("allows_users_to_create_topics"),
        }

    async def _ensure_telegram_system_topic(self, source: SessionSource) -> None:
        """Create/pin the managed System topic after /topic activation when possible."""
        adapter = self._adapter_for_source(source) if getattr(self, "adapters", None) else None
        if adapter is None or not source.chat_id:
            return

        thread_id = None
        create_topic = getattr(adapter, "_create_dm_topic", None)
        if callable(create_topic):
            try:
                thread_id = await create_topic(int(source.chat_id), "System")
            except Exception:
                logger.debug("Failed to create Telegram System topic", exc_info=True)
        if not thread_id:
            return

        message_id = None
        try:
            send_result = await adapter.send(
                source.chat_id,
                "System topic for Hermes commands and status.",
                metadata={"thread_id": str(thread_id)},
            )
            message_id = getattr(send_result, "message_id", None)
        except Exception:
            logger.debug("Failed to send Telegram System topic intro", exc_info=True)
        if not message_id:
            return

        bot = getattr(adapter, "_bot", None)
        if bot is None or not hasattr(bot, "pin_chat_message"):
            return
        try:
            await bot.pin_chat_message(
                chat_id=int(source.chat_id),
                message_id=int(message_id),
                disable_notification=True,
            )
        except Exception:
            logger.debug("Failed to pin Telegram System topic intro", exc_info=True)

    async def _send_telegram_topic_setup_image(self, source: SessionSource) -> None:
        """Send the bundled BotFather Threads Settings screenshot when available."""
        adapter = self._adapter_for_source(source) if getattr(self, "adapters", None) else None
        if adapter is None or not source.chat_id or not hasattr(adapter, "send_image_file"):
            return
        image_path = Path(__file__).resolve().parent / "assets" / "telegram-botfather-threads-settings.jpg"
        if not image_path.exists():
            return
        try:
            await adapter.send_image_file(
                chat_id=source.chat_id,
                image_path=str(image_path),
                caption="BotFather → Bot Settings → Threads Settings",
                metadata={"thread_id": str(source.thread_id)} if source.thread_id else None,
            )
        except Exception:
            logger.debug("Failed to send Telegram topic setup image", exc_info=True)

    def _sanitize_telegram_topic_title(self, title: str) -> str:
        """Return a Bot API-safe forum topic name from a generated session title."""
        cleaned = re.sub(r"\s+", " ", str(title or "")).strip()
        if not cleaned:
            return "Hermes Chat"
        # Telegram forum topic names are short (currently 1-128 chars). Keep
        # extra room for multi-byte titles and avoid trailing ellipsis churn.
        if len(cleaned) > 120:
            cleaned = cleaned[:117].rstrip() + "..."
        return cleaned

    def _is_discord_auto_thread_lane(self, source: SessionSource) -> bool:
        """Return True only for Discord threads Hermes just auto-created."""
        return (
            source.platform == Platform.DISCORD
            and source.chat_type == "thread"
            and bool(getattr(source, "auto_thread_created", False))
            and bool(source.thread_id)
            and bool(getattr(source, "auto_thread_initial_name", None))
        )

    def _sanitize_discord_thread_title(self, title: str) -> str:
        """Return a Discord-safe semantic thread title from a session title.

        Discord thread names are capped at 100 characters measured in UTF-16
        code units (emoji count double), so truncate with the UTF-16 helpers
        rather than Python code-point slices.
        """
        cleaned = re.sub(r"\s+", " ", str(title or "")).strip()
        if not cleaned:
            return "Hermes Chat"
        if utf16_len(cleaned) > 80:
            cleaned = _prefix_within_utf16_limit(cleaned, 77).rstrip() + "..."
        return cleaned

    async def _rename_discord_auto_thread_for_session_title(
        self,
        source: SessionSource,
        session_id: str,
        title: str,
    ) -> None:
        """Best-effort semantic rename of a newly auto-created Discord thread."""
        if not await asyncio.to_thread(self._is_discord_auto_thread_lane, source):
            return
        adapter = self._adapter_for_source(source) if getattr(self, "adapters", None) else None
        if adapter is None:
            return
        rename_thread = getattr(adapter, "rename_thread", None)
        if rename_thread is None:
            return
        thread_name = self._sanitize_discord_thread_title(title)
        try:
            await rename_thread(
                str(source.thread_id),
                thread_name,
                only_if_current_name=getattr(source, "auto_thread_initial_name", None),
            )
        except Exception:
            logger.debug("Failed to rename Discord auto-thread for generated session title", exc_info=True)

    def _schedule_discord_semantic_thread_rename(
        self,
        source: SessionSource,
        session_id: str,
        title: str,
    ) -> None:
        """Schedule Discord auto-thread rename from the auto-title background thread."""
        if not title or not self._is_discord_auto_thread_lane(source):
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = getattr(self, "_gateway_loop", None)
        if loop is None or loop.is_closed():
            return
        try:
            copied_source = dataclasses.replace(source)
        except Exception:
            copied_source = source
        future = safe_schedule_threadsafe(
            self._rename_discord_auto_thread_for_session_title(copied_source, session_id, title),
            loop,
            logger=logger,
            log_message="Discord semantic thread rename failed to schedule",
        )
        if future is None:
            return

        def _log_rename_failure(fut) -> None:
            try:
                fut.result()
            except Exception:
                logger.debug("Discord semantic thread rename failed", exc_info=True)

        future.add_done_callback(_log_rename_failure)

    async def _rename_telegram_topic_for_session_title(
        self,
        source: SessionSource,
        session_id: str,
        title: str,
    ) -> None:
        """Best-effort rename of a Telegram DM topic when Hermes auto-titles a session."""
        if not await asyncio.to_thread(self._is_telegram_topic_lane, source) or not source.chat_id or not source.thread_id:
            return

        # Operator can fully disable per-topic auto-rename via
        # extra.disable_topic_auto_rename. Useful when topics are managed
        # by the user (ad-hoc Threaded Mode) and auto-rename would
        # overwrite their chosen names every time the auto-title fires.
        if self._telegram_topic_auto_rename_disabled(source):
            return

        # Skip rename when the topic is operator-declared via
        # extra.dm_topics. Those topics have fixed names chosen by the
        # operator (plus optional skill binding); auto-renaming would
        # silently mutate operator config.
        #
        # Check the class, not the instance — getattr() on MagicMock
        # auto-creates attributes, so `hasattr(adapter, "_get_dm_topic_info")`
        # would return True for every test double.
        adapter = self._adapter_for_source(source) if getattr(self, "adapters", None) else None
        if adapter is not None:
            get_info = getattr(type(adapter), "_get_dm_topic_info", None)
            if callable(get_info):
                try:
                    operator_topic = get_info(adapter, str(source.chat_id), str(source.thread_id))
                except Exception:
                    operator_topic = None
                # Only treat dict-shaped returns as operator-declared; a
                # bare MagicMock or other sentinel shouldn't count.
                if isinstance(operator_topic, dict):
                    return

        session_db = getattr(self, "_session_db", None)
        if session_db is not None:
            try:
                binding = await session_db.get_telegram_topic_binding(
                    chat_id=str(source.chat_id),
                    thread_id=str(source.thread_id),
                )
                if binding and str(binding.get("session_id") or "") != str(session_id):
                    return
            except Exception:
                logger.debug("Failed to verify Telegram topic binding before rename", exc_info=True)
                return

        if adapter is None:
            return
        topic_name = self._sanitize_telegram_topic_title(title)
        try:
            rename_topic = getattr(adapter, "rename_dm_topic", None)
            if rename_topic is not None:
                await rename_topic(
                    chat_id=str(source.chat_id),
                    thread_id=str(source.thread_id),
                    name=topic_name,
                )
                return

            bot = getattr(adapter, "_bot", None)
            edit_forum_topic = getattr(bot, "edit_forum_topic", None) if bot is not None else None
            if edit_forum_topic is None:
                edit_forum_topic = getattr(bot, "editForumTopic", None) if bot is not None else None
            if edit_forum_topic is None:
                return
            try:
                await edit_forum_topic(
                    chat_id=int(source.chat_id),
                    message_thread_id=int(source.thread_id),
                    name=topic_name,
                )
            except (TypeError, ValueError):
                await edit_forum_topic(
                    chat_id=source.chat_id,
                    message_thread_id=source.thread_id,
                    name=topic_name,
                )
        except Exception:
            logger.debug("Failed to rename Telegram topic for auto-generated title", exc_info=True)

    def _telegram_topic_auto_rename_disabled(self, source: SessionSource) -> bool:
        """Return True when operator disabled per-topic auto-rename for this Telegram chat.

        Controlled via ``gateway.platforms.telegram.extra.disable_topic_auto_rename``.
        Default is False (auto-rename enabled, preserves prior behaviour).
        """
        platform_cfg = (
            self.config.platforms.get(source.platform)
            if getattr(self, "config", None) and getattr(self.config, "platforms", None)
            else None
        )
        if platform_cfg is None:
            return False
        extra = getattr(platform_cfg, "extra", None) or {}
        value = extra.get("disable_topic_auto_rename")
        if value is None:
            return False
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "on"}
        return bool(value)

    def _schedule_telegram_topic_title_rename(
        self,
        source: SessionSource,
        session_id: str,
        title: str,
    ) -> None:
        """Schedule a topic rename from the auto-title background thread."""
        if not title or not self._is_telegram_topic_lane(source):
            return
        if self._telegram_topic_auto_rename_disabled(source):
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = getattr(self, "_gateway_loop", None)
        if loop is None or loop.is_closed():
            return
        try:
            copied_source = dataclasses.replace(source)
        except Exception:
            copied_source = source
        future = safe_schedule_threadsafe(
            self._rename_telegram_topic_for_session_title(copied_source, session_id, title),
            loop,
            logger=logger,
            log_message="Telegram topic title rename failed to schedule",
        )
        if future is None:
            return
        def _log_rename_failure(fut) -> None:
            try:
                fut.result()
            except Exception:
                logger.debug("Telegram topic title rename failed", exc_info=True)

        future.add_done_callback(_log_rename_failure)

    _TELEGRAM_CAPABILITY_HINT_COOLDOWN_S = 300.0

    def _should_send_telegram_capability_hint(self, source: SessionSource) -> bool:
        """Rate-limit the BotFather Threads Settings screenshot.

        If a user sends /topic repeatedly while Threads Settings are still
        off, we shouldn't keep re-uploading the screenshot every time.
        """
        if not hasattr(self, "_telegram_capability_hint_ts"):
            self._telegram_capability_hint_ts = {}
        chat_id = str(source.chat_id or "")
        if not chat_id:
            return True
        import time as _time
        now = _time.monotonic()
        last = self._telegram_capability_hint_ts.get(chat_id, 0.0)
        if now - last < self._TELEGRAM_CAPABILITY_HINT_COOLDOWN_S:
            return False
        self._telegram_capability_hint_ts[chat_id] = now
        return True

    def _telegram_topic_help_text(self) -> str:
        return (
            "/topic — enable multi-session DM mode (one bot, many parallel chats)\n"
            "\n"
            "Usage:\n"
            "  /topic             Enable topic mode, or show status if already on\n"
            "  /topic help        Show this message\n"
            "  /topic off         Disable topic mode and clear topic bindings\n"
            "  /topic <id>        Inside a topic: restore a previous session by ID\n"
            "\n"
            "How it works:\n"
            "1. Run /topic once in this DM — Hermes checks BotFather Threads\n"
            "   Settings are enabled and flips on multi-session mode.\n"
            "2. Tap All Messages at the top of the bot and send any message.\n"
            "   Telegram creates a new topic for that message; each topic is\n"
            "   an independent Hermes session (fresh history, fresh context).\n"
            "3. The root DM becomes a system lobby — send /topic, /status,\n"
            "   /help, /usage there. Normal prompts go in a topic.\n"
            "4. /new inside a topic resets just that topic's session.\n"
            "5. /topic <id> inside a topic restores an old session into it."
        )

    async def _disable_telegram_topic_mode_for_chat(self, source: SessionSource) -> str:
        """Cleanly disable topic mode for a chat via /topic off."""
        if not self._session_db:
            from hermes_state import format_session_db_unavailable
            return format_session_db_unavailable(prefix=t("gateway.shared.session_db_unavailable_prefix"))
        chat_id = str(source.chat_id or "")
        if not chat_id:
            return "Could not determine chat ID."
        # No-op if never enabled.
        try:
            currently_enabled = await self._session_db.is_telegram_topic_mode_enabled(
                chat_id=chat_id,
                user_id=str(source.user_id or ""),
            )
        except Exception:
            currently_enabled = False
        if not currently_enabled:
            return "Multi-session topic mode is not currently enabled for this chat."
        try:
            await self._session_db.disable_telegram_topic_mode(chat_id=chat_id)
        except Exception as exc:
            logger.exception("Failed to disable Telegram topic mode")
            return f"Failed to disable topic mode: {exc}"
        # Reset per-chat debounce state so the user doesn't see a stale
        # cooldown on the next activation.
        for attr in ("_telegram_lobby_reminder_ts", "_telegram_capability_hint_ts"):
            store = getattr(self, attr, None)
            if isinstance(store, dict):
                store.pop(chat_id, None)
        return (
            "Multi-session topic mode is now OFF for this chat.\n\n"
            "Existing topics in Telegram aren't removed — they'll just stop "
            "being gated as independent sessions. The root DM works as a "
            "normal Hermes chat again. Run /topic to re-enable later."
        )

    async def _handle_topic_command(self, event: MessageEvent, args: str = "") -> str:
        """Handle /topic for Telegram DM user-managed topic sessions."""
        source = event.source
        if source.platform != Platform.TELEGRAM or source.chat_type != "dm":
            return t("gateway.topic.not_telegram_dm")
        if not self._session_db:
            from hermes_state import format_session_db_unavailable
            return format_session_db_unavailable(prefix=t("gateway.shared.session_db_unavailable_prefix"))

        # Authorization: /topic activates multi-session mode and mutates
        # SQLite side tables. Unauthorized senders (not in allowlist) must
        # not be able to do that. Gateway routes already authorize the
        # message before reaching here, but defense in depth.
        auth_fn = getattr(self, "_is_user_authorized", None)
        if callable(auth_fn):
            try:
                if not auth_fn(source):
                    return t("gateway.topic.unauthorized")
            except Exception:
                logger.debug("Topic auth check failed", exc_info=True)

        args = event.get_command_args().strip()

        # /topic help — inline usage without leaving the bot.
        if args.lower() in {"help", "?", "-h", "--help"}:
            return self._telegram_topic_help_text()

        # /topic off — clean disable path so users don't have to edit the DB.
        if args.lower() in {"off", "disable", "stop"}:
            return await self._disable_telegram_topic_mode_for_chat(source)

        if args:
            if not source.thread_id:
                return t("gateway.topic.restore_needs_topic")
            return await self._restore_telegram_topic_session(event, args)

        capabilities = await self._get_telegram_topic_capabilities(source)
        if capabilities.get("checked"):
            if capabilities.get("has_topics_enabled") is False:
                # Debounce the BotFather screenshot: don't re-send on every
                # /topic while threads are still disabled.
                if self._should_send_telegram_capability_hint(source):
                    await self._send_telegram_topic_setup_image(source)
                return t("gateway.topic.topics_disabled")
            if capabilities.get("allows_users_to_create_topics") is False:
                if self._should_send_telegram_capability_hint(source):
                    await self._send_telegram_topic_setup_image(source)
                return t("gateway.topic.topics_user_disallowed")

        try:
            await self._session_db.enable_telegram_topic_mode(
                chat_id=str(source.chat_id),
                user_id=str(source.user_id),
                has_topics_enabled=capabilities.get("has_topics_enabled"),
                allows_users_to_create_topics=capabilities.get("allows_users_to_create_topics"),
            )
        except Exception as exc:
            logger.exception("Failed to enable Telegram topic mode")
            return t("gateway.topic.enable_failed", error=exc)

        if not source.thread_id:
            await self._ensure_telegram_system_topic(source)

        if source.thread_id:
            try:
                binding = await self._session_db.get_telegram_topic_binding(
                    chat_id=str(source.chat_id),
                    thread_id=str(source.thread_id),
                )
            except Exception:
                logger.debug("Failed to read Telegram topic binding", exc_info=True)
                binding = None
            if binding:
                session_id = str(binding.get("session_id") or "")
                title = None
                try:
                    title = await self._session_db.get_session_title(session_id)
                except Exception:
                    title = None
                session_label = title or t("gateway.topic.untitled_session")
                return t(
                    "gateway.topic.bound_status",
                    label=session_label,
                    session_id=session_id,
                )
            return t("gateway.topic.thread_ready")

        return await self._telegram_topic_root_status_message(source)

    async def _telegram_topic_root_status_message(self, source: SessionSource) -> str:
        lines = [
            "Telegram multi-session topics are enabled.",
            "",
            "To create a new Hermes chat, open All Messages at the top of this "
            "bot interface and send any message there. Telegram will create a "
            "new topic for it.",
            "",
        ]
        try:
            sessions = await self._session_db.list_unlinked_telegram_sessions_for_user(
                chat_id=str(source.chat_id),
                user_id=str(source.user_id),
                limit=10,
            )
        except Exception:
            logger.debug("Failed to list unlinked Telegram sessions", exc_info=True)
            sessions = []

        if sessions:
            lines.append("Previous unlinked sessions:")
            for session in sessions:
                session_id = str(session.get("id") or "")
                title = str(session.get("title") or "Untitled session")
                preview = str(session.get("preview") or "").strip()
                line = f"- {title} — `{session_id}`"
                if preview:
                    line += f" — {preview}"
                lines.append(line)
            lines.extend([
                "",
                "To restore one:",
                "1. Create or open a topic. To create a new one, open All Messages and send any message there.",
                "2. Send /topic <session-id> inside that topic.",
                f"Example: Send /topic {sessions[0].get('id')} inside a topic.",
            ])
        else:
            lines.extend([
                "No previous unlinked Telegram sessions found.",
                "",
                "To restore a previous session later:",
                "1. Create or open a topic. To create a new one, open All Messages and send any message there.",
                "2. Send /topic <session-id> inside that topic.",
            ])
        return "\n".join(lines)

    async def _restore_telegram_topic_session(self, event: MessageEvent, raw_session_id: str) -> str:
        """Restore an existing Telegram-owned Hermes session into this topic."""
        source = event.source
        session_id = await self._session_db.resolve_session_id(raw_session_id.strip())
        if not session_id:
            return f"Session not found: {raw_session_id.strip()}"

        session = await self._session_db.get_session(session_id)
        if not session:
            return f"Session not found: {raw_session_id.strip()}"
        if str(session.get("source") or "") != "telegram":
            return "That session is not a Telegram session and cannot be restored into this topic."
        if str(session.get("user_id") or "") != str(source.user_id):
            return "That session does not belong to this Telegram user."

        linked = await self._session_db.is_telegram_session_linked_to_topic(session_id=session_id)
        current_binding = await self._session_db.get_telegram_topic_binding(
            chat_id=str(source.chat_id),
            thread_id=str(source.thread_id),
        )
        if linked:
            if not current_binding or current_binding.get("session_id") != session_id:
                return "That session is already linked to another Telegram topic."

        session_key = self._session_key_for_source(source)
        try:
            await self._session_db.bind_telegram_topic(
                chat_id=str(source.chat_id),
                thread_id=str(source.thread_id),
                user_id=str(source.user_id),
                session_key=session_key,
                session_id=session_id,
                managed_mode="restored",
            )
        except ValueError as exc:
            if "already linked" in str(exc):
                return "That session is already linked to another Telegram topic."
            raise

        title = await self._session_db.get_session_title(session_id) or session_id
        last_assistant = None
        try:
            for message in reversed(await self._session_db.get_messages(session_id)):
                if message.get("role") == "assistant" and message.get("content"):
                    last_assistant = str(message.get("content"))
                    break
        except Exception:
            last_assistant = None

        response = f"Session restored: {title}"
        if last_assistant:
            response += f"\n\nLast Hermes message:\n{last_assistant}"
        return response

    async def _handle_title_command(self, event: MessageEvent) -> str:
        """Handle /title command — set or show the current session's title."""
        source = event.source
        session_entry = await self.async_session_store.get_or_create_session(source)
        session_id = session_entry.session_id

        if not self._session_db:
            from hermes_state import format_session_db_unavailable
            return format_session_db_unavailable(prefix=t("gateway.shared.session_db_unavailable_prefix"))

        # Ensure session exists in SQLite DB (it may only exist in session_store
        # if this is the first command in a new session)
        existing_title = await self._session_db.get_session_title(session_id)
        if existing_title is None:
            # Session doesn't exist in DB yet — create it
            try:
                await self._session_db.create_session(
                    session_id=session_id,
                    source=source.platform.value if source.platform else "unknown",
                    user_id=source.user_id,
                )
            except Exception:
                pass  # Session might already exist, ignore errors

        title_arg = event.get_command_args().strip()
        if title_arg:
            # Sanitize the title before setting
            try:
                sanitized = await self._session_db.sanitize_title(title_arg)
            except ValueError as e:
                return t("gateway.shared.warn_passthrough", error=e)
            if not sanitized:
                return t("gateway.title.empty_after_clean")
            # Set the title
            try:
                if await self._session_db.set_session_title(session_id, sanitized):
                    return t("gateway.title.set_to", title=sanitized)
                else:
                    return t("gateway.title.not_found")
            except ValueError as e:
                return t("gateway.shared.warn_passthrough", error=e)
        else:
            # Show the current title and session ID
            title = await self._session_db.get_session_title(session_id)
            if title:
                return t("gateway.title.current_with_title", session_id=session_id, title=title)
            else:
                return t("gateway.title.current_no_title", session_id=session_id)

    async def _handle_resume_command(self, event: MessageEvent) -> str:
        """Handle /resume command — list or switch to a previous session."""
        if not self._session_db:
            from hermes_state import format_session_db_unavailable
            return format_session_db_unavailable(prefix=t("gateway.shared.session_db_unavailable_prefix"))

        source = event.source
        session_key = self._session_key_for_source(source)
        name = event.get_command_args().strip()

        # Strip common outer brackets/quotes users may type literally from the
        # usage hint (e.g. ``/resume <abc123>``). Mirrors the CLI behavior.
        if len(name) >= 2 and (
            (name[0] == "<" and name[-1] == ">")
            or (name[0] == "[" and name[-1] == "]")
            or (name[0] == '"' and name[-1] == '"')
            or (name[0] == "'" and name[-1] == "'")
        ):
            name = name[1:-1].strip()

        async def _list_titled_sessions() -> list[dict]:
            user_source = source.platform.value if source.platform else None
            sessions = await self._session_db.list_sessions_rich(
                source=user_source,
                limit=10,
            )
            return [s for s in sessions if s.get("title")][:10]

        if not name:
            # List recent titled sessions for this user/platform
            try:
                titled = await _list_titled_sessions()
                if not titled:
                    return t("gateway.resume.no_named_sessions")
                lines = [t("gateway.resume.list_header")]
                for idx, s in enumerate(titled[:10], start=1):
                    title = s["title"]
                    preview = s.get("preview", "")[:40]
                    preview_part = t("gateway.resume.list_preview_suffix", preview=preview) if preview else ""
                    lines.append(t("gateway.resume.list_item_numbered", index=idx, title=title, preview_part=preview_part))
                lines.append(t("gateway.resume.list_footer_numbered"))
                return "\n".join(lines)
            except Exception as e:
                logger.debug("Failed to list titled sessions: %s", e)
                return t("gateway.resume.list_failed", error=e)

        # Resolve a numbered choice or a title to a session ID.
        if name.isdigit():
            try:
                titled = _list_titled_sessions()
            except Exception as e:
                logger.debug("Failed to list titled sessions for numeric resume: %s", e)
                return t("gateway.resume.list_failed", error=e)
            index = int(name)
            if index < 1 or index > len(titled):
                return t("gateway.resume.out_of_range", index=index)
            target = titled[index - 1]
            target_id = target.get("id")
            name = target.get("title") or name
        else:
            # Try direct session ID lookup first (so `/resume <session_id>`
            # works in the gateway, not just `/resume <title>`).
            session = await self._session_db.get_session(name)
            if session:
                target_id = session["id"]
            else:
                target_id = await self._session_db.resolve_session_by_title(name)
        if not target_id:
            return t("gateway.resume.not_found", name=name)
        # Compression creates child continuations that hold the live transcript.
        # Follow that chain so gateway /resume matches CLI behavior (#15000).
        try:
            target_id = await self._session_db.resolve_resume_session_id(target_id)
        except Exception as e:
            logger.debug("Failed to resolve resume continuation for %s: %s", target_id, e)

        # Check if already on that session
        current_entry = await self.async_session_store.get_or_create_session(source)
        if current_entry.session_id == target_id:
            return t("gateway.resume.already_on", name=name)

        # Clear any running agent for this session key
        self._release_running_agent_state(session_key)

        # Switch the session entry to point at the old session
        new_entry = await self.async_session_store.switch_session(session_key, target_id)
        if not new_entry:
            return t("gateway.resume.switch_failed")
        self._clear_session_boundary_security_state(session_key)

        # Evict any cached agent for this session so the next message
        # rebuilds with the correct session_id end-to-end — mirrors
        # /branch and /reset. Without this, the cached AIAgent (and its
        # memory provider, which cached `_session_id` during initialize())
        # keeps writing into the wrong session's record. See #6672.
        self._evict_cached_agent(session_key)

        # Get the title for confirmation
        title = await self._session_db.get_session_title(target_id) or name

        # Count messages for context
        history = await self.async_session_store.load_transcript(target_id)
        msg_count = len([m for m in history if m.get("role") == "user"]) if history else 0
        if not msg_count:
            return t("gateway.resume.resumed_no_count", title=title)
        if msg_count == 1:
            return t("gateway.resume.resumed_one", title=title, count=msg_count)
        return t("gateway.resume.resumed_many", title=title, count=msg_count)

    async def _handle_branch_command(self, event: MessageEvent) -> str:
        """Handle /branch [name] — fork the current session into a new independent copy.

        Copies conversation history to a new session so the user can explore
        a different approach without losing the original.
        Inspired by Claude Code's /branch command.
        """
        import uuid as _uuid

        if not self._session_db:
            from hermes_state import format_session_db_unavailable
            return format_session_db_unavailable(prefix=t("gateway.shared.session_db_unavailable_prefix"))

        source = event.source
        session_key = self._session_key_for_source(source)

        # Load the current session and its transcript
        current_entry = await self.async_session_store.get_or_create_session(source)
        history = await self.async_session_store.load_transcript(current_entry.session_id)
        if not history:
            return t("gateway.branch.no_conversation")

        branch_name = event.get_command_args().strip()

        # Generate the new session ID
        from datetime import datetime as _dt
        now = _dt.now()
        timestamp_str = now.strftime("%Y%m%d_%H%M%S")
        short_uuid = _uuid.uuid4().hex[:6]
        new_session_id = f"{timestamp_str}_{short_uuid}"

        # Determine branch title
        if branch_name:
            branch_title = branch_name
        else:
            current_title = await self._session_db.get_session_title(current_entry.session_id)
            base = current_title or "branch"
            branch_title = await self._session_db.get_next_title_in_lineage(base)

        parent_session_id = current_entry.session_id

        # Create the new session with parent link
        try:
            await self._session_db.create_session(
                session_id=new_session_id,
                source=source.platform.value if source.platform else "gateway",
                model=(self.config.get("model", {}) or {}).get("default") if isinstance(self.config, dict) else None,
                parent_session_id=parent_session_id,
            )
        except Exception as e:
            logger.error("Failed to create branch session: %s", e)
            return t("gateway.branch.create_failed", error=e)

        # Copy conversation history to the new session
        for msg in history:
            try:
                await self._session_db.append_message(
                    session_id=new_session_id,
                    role=msg.get("role", "user"),
                    content=msg.get("content"),
                    tool_name=msg.get("tool_name") or msg.get("name"),
                    tool_calls=msg.get("tool_calls"),
                    tool_call_id=msg.get("tool_call_id"),
                    finish_reason=msg.get("finish_reason"),
                    reasoning=msg.get("reasoning"),
                    reasoning_content=msg.get("reasoning_content"),
                    reasoning_details=msg.get("reasoning_details"),
                    codex_reasoning_items=msg.get("codex_reasoning_items"),
                    codex_message_items=msg.get("codex_message_items"),
                )
            except Exception:
                pass  # Best-effort copy

        # Set title
        try:
            await self._session_db.set_session_title(new_session_id, branch_title)
        except Exception:
            pass

        # Switch the session store entry to the new session
        new_entry = await self.async_session_store.switch_session(session_key, new_session_id)
        if not new_entry:
            return t("gateway.branch.switch_failed")
        self._clear_session_boundary_security_state(session_key)

        # Evict any cached agent for this session
        self._evict_cached_agent(session_key)

        msg_count = len([m for m in history if m.get("role") == "user"])
        key = "gateway.branch.branched_one" if msg_count == 1 else "gateway.branch.branched_many"
        return t(key, title=branch_title, count=msg_count, parent=parent_session_id, new=new_session_id)

    async def _handle_usage_command(self, event: MessageEvent) -> str:
        """Compose upstream session usage with the fork's Codex plan report."""
        from hermes_cli.codex_status import build_codex_usage_report

        upstream_report = ""
        try:
            upstream_report = await GatewaySlashCommandsMixin._handle_usage_command(
                self, event
            )
        except Exception:
            logger.debug("upstream gateway usage report failed", exc_info=True)
        try:
            codex_report = await asyncio.to_thread(build_codex_usage_report)
        except Exception:
            codex_report = ""
        reports = [
            str(report).strip()
            for report in (upstream_report, codex_report)
            if str(report or "").strip()
        ]
        return "\n\n".join(reports)

    async def _handle_insights_command(self, event: MessageEvent) -> str:
        """Handle /insights command -- show usage insights and analytics."""
        args = event.get_command_args().strip()

        # Normalize Unicode dashes (Telegram/iOS auto-converts -- to em/en dash)
        args = re.sub(r'[\u2012\u2013\u2014\u2015](days|source)', r'--\1', args)

        days = 30
        source = None

        # Parse simple args: /insights 7  or  /insights --days 7
        if args:
            parts = args.split()
            i = 0
            while i < len(parts):
                if parts[i] == "--days" and i + 1 < len(parts):
                    try:
                        days = int(parts[i + 1])
                    except ValueError:
                        return t("gateway.insights.invalid_days", value=parts[i + 1])
                    i += 2
                elif parts[i] == "--source" and i + 1 < len(parts):
                    source = parts[i + 1]
                    i += 2
                elif parts[i].isdigit():
                    days = int(parts[i])
                    i += 1
                else:
                    i += 1

        try:
            from hermes_state import SessionDB
            from agent.insights import InsightsEngine

            loop = asyncio.get_running_loop()

            def _run_insights():
                db = SessionDB()
                engine = InsightsEngine(db)
                report = engine.generate(days=days, source=source)
                result = engine.format_gateway(report)
                db.close()
                return result

            return await loop.run_in_executor(None, _run_insights)
        except Exception as e:
            logger.error("Insights command error: %s", e, exc_info=True)
            return t("gateway.insights.error", error=e)

    async def _handle_reload_mcp_command(self, event: MessageEvent) -> Optional[str]:
        """Handle /reload-mcp — reconnect MCP servers and rebuild the cached agent.

        Reloading MCP tools invalidates the provider prompt cache for the
        active session (tool schemas are baked into the system prompt).  The
        next message re-sends full input tokens, which is expensive on
        long-context or high-reasoning models.

        To surface that cost, the command routes through the slash-confirm
        primitive: users get an Approve Once / Always Approve / Cancel
        prompt before the reload actually runs.  "Always Approve" persists
        ``approvals.mcp_reload_confirm: false`` so the prompt is silenced
        for subsequent reloads in any session.

        Users can also skip the confirm by flipping the config key directly.
        """
        source = event.source
        session_key = self._session_key_for_source(source)

        # Read the gate fresh from disk so a prior "always" click takes
        # effect on the next invocation without restarting the gateway.
        user_config = self._read_user_config()
        approvals = user_config.get("approvals") if isinstance(user_config, dict) else None
        confirm_required = True
        if isinstance(approvals, dict):
            confirm_required = bool(approvals.get("mcp_reload_confirm", True))

        if not confirm_required:
            return await self._execute_mcp_reload(event)

        # Route through slash-confirm.  The primitive sends the prompt and
        # stores the resume handler; the button/text response triggers
        # ``_resolve_slash_confirm`` which invokes the handler with the
        # chosen outcome.
        async def _on_confirm(choice: str) -> Optional[str]:
            if choice == "cancel":
                return t("gateway.reload_mcp.cancelled")
            if choice == "always":
                # Persist the opt-out and run the reload.
                try:
                    from cli import save_config_value
                    save_config_value("approvals.mcp_reload_confirm", False)
                    logger.info(
                        "User opted out of /reload-mcp confirmation (session=%s)",
                        session_key,
                    )
                except Exception as exc:
                    logger.warning("Failed to persist mcp_reload_confirm=false: %s", exc)
            # once / always → run the reload
            result = await self._execute_mcp_reload(event)
            if choice == "always":
                return f"{result}\n\n" + t("gateway.reload_mcp.always_followup")
            return result

        prompt_message = t("gateway.reload_mcp.confirm_prompt")
        return await self._request_slash_confirm(
            event=event,
            command="reload-mcp",
            title="/reload-mcp",
            message=prompt_message,
            handler=_on_confirm,
        )

    async def _execute_mcp_reload(self, event: MessageEvent) -> str:
        """Actually disconnect, reconnect, and notify MCP tool changes.

        Split out from ``_handle_reload_mcp_command`` so the confirmation
        wrapper can invoke the same path whether the user confirmed via
        button, text reply, or has the confirm gate disabled.
        """
        loop = asyncio.get_running_loop()
        try:
            from tools.mcp_tool import shutdown_mcp_servers, discover_mcp_tools, _servers, _lock

            # Capture old server names before shutdown
            with _lock:
                old_servers = set(_servers.keys())

            # Read new config before shutting down, so we know what will be added/removed
            # Shutdown existing connections
            await loop.run_in_executor(None, shutdown_mcp_servers)

            # Reconnect by discovering tools (reads config.yaml fresh)
            new_tools = await loop.run_in_executor(None, discover_mcp_tools)

            # Compute what changed
            with _lock:
                connected_servers = set(_servers.keys())

            added = connected_servers - old_servers
            removed = old_servers - connected_servers
            reconnected = connected_servers & old_servers

            lines = [t("gateway.reload_mcp.header")]
            if reconnected:
                lines.append(t("gateway.reload_mcp.reconnected", names=", ".join(sorted(reconnected))))
            if added:
                lines.append(t("gateway.reload_mcp.added", names=", ".join(sorted(added))))
            if removed:
                lines.append(t("gateway.reload_mcp.removed", names=", ".join(sorted(removed))))
            if not connected_servers:
                lines.append(t("gateway.reload_mcp.none_connected"))
            else:
                lines.append(t("gateway.reload_mcp.tools_available", tools=len(new_tools), servers=len(connected_servers)))

            # Refresh cached agents so existing sessions see new MCP tools on
            # their next turn — without this, the user has to `/new` (which
            # discards conversation history) to pick up tools from a server
            # that was just added or reconnected. The user has already
            # consented to the prompt-cache invalidation via the slash-confirm
            # gate in _handle_reload_mcp_command before we reach this point.
            try:
                from tools.mcp_tool import refresh_agent_mcp_tools
                _cache = getattr(self, "_agent_cache", None)
                _cache_lock = getattr(self, "_agent_cache_lock", None)
                if _cache_lock is not None and _cache:
                    with _cache_lock:
                        for _sess_key, _entry in list(_cache.items()):
                            try:
                                _agent = _entry[0] if isinstance(_entry, tuple) else _entry
                            except Exception:
                                continue
                            if _agent is None:
                                continue
                            refresh_agent_mcp_tools(_agent, quiet_mode=True)
            except Exception as _exc:
                logger.debug(
                    "Failed to update cached agent tools after MCP reload: %s",
                    _exc,
                )

            # Inject a message at the END of the session history so the
            # model knows tools changed on its next turn.  Appended after
            # all existing messages to preserve prompt-cache for the prefix.
            change_parts = []
            if added:
                change_parts.append(f"Added servers: {', '.join(sorted(added))}")
            if removed:
                change_parts.append(f"Removed servers: {', '.join(sorted(removed))}")
            if reconnected:
                change_parts.append(f"Reconnected servers: {', '.join(sorted(reconnected))}")
            tool_summary = f"{len(new_tools)} MCP tool(s) now available" if new_tools else "No MCP tools available"
            change_detail = ". ".join(change_parts) + ". " if change_parts else ""
            reload_msg = {
                "role": "user",
                "content": f"[IMPORTANT: MCP servers have been reloaded. {change_detail}{tool_summary}. The tool list for this conversation has been updated accordingly.]",
            }
            try:
                session_entry = await self.async_session_store.get_or_create_session(event.source)
                await self.async_session_store.append_to_transcript(
                    session_entry.session_id, reload_msg
                )
            except Exception:
                pass  # Best-effort; don't fail the reload over a transcript write

            return "\n".join(lines)

        except Exception as e:
            logger.warning("MCP reload failed: %s", e)
            return t("gateway.reload_mcp.failed", error=e)

    async def _handle_reload_skills_command(self, event: MessageEvent) -> str:
        """Handle /reload-skills — rescan skills dir, queue a note for next turn.

        Skills don't need to be in the system prompt for the model to use
        them (they're invoked via ``/skill-name``, ``skills_list``, or
        ``skill_view`` at runtime), so this does NOT clear the prompt cache
        — prefix caching stays intact.

        If any skills were added or removed, a one-shot note is queued on
        ``self._pending_skills_reload_notes[session_key]``. The gateway
        prepends it to the NEXT user message in this session (see the
        consumer at ~L11025 in ``_run_agent_turn``), then clears it. Nothing
        is written to the session transcript out-of-band, so message
        alternation is preserved.
        """
        loop = asyncio.get_running_loop()
        try:
            from agent.skill_commands import reload_skills

            result = await loop.run_in_executor(None, reload_skills)
            added = result.get("added", [])      # [{"name", "description"}, ...]
            removed = result.get("removed", [])  # [{"name", "description"}, ...]
            total = result.get("total", 0)

            # Let each connected adapter refresh any platform-side state
            # that cached the skill list at startup. Today that's the
            # Discord /skill autocomplete (registered once per connect);
            # without this call, new skills stay invisible in the
            # dropdown and deleted skills error out when clicked. Other
            # adapters that don't override refresh_skill_group (Telegram's
            # BotCommand menu, Slack subcommand map, etc.) are silently
            # skipped — the in-process reload above is enough for them.
            for adapter in list(self.adapters.values()):
                refresh = getattr(adapter, "refresh_skill_group", None)
                if not callable(refresh):
                    continue
                try:
                    maybe = refresh()
                    if inspect.isawaitable(maybe):
                        await maybe
                except Exception as exc:
                    logger.warning(
                        "Adapter %s refresh_skill_group raised: %s",
                        getattr(adapter, "name", adapter), exc,
                    )

            lines = [t("gateway.reload_skills.header")]
            if not added and not removed:
                lines.append(t("gateway.reload_skills.no_new"))
                lines.append(t("gateway.reload_skills.total", count=total))
                return "\n".join(lines)

            def _fmt_line(item: dict) -> str:
                nm = item.get("name", "")
                desc = item.get("description", "")
                if desc:
                    return t("gateway.reload_skills.item_with_desc", name=nm, desc=desc)
                return t("gateway.reload_skills.item_no_desc", name=nm)

            if added:
                lines.append(t("gateway.reload_skills.added_header"))
                for item in added:
                    lines.append(_fmt_line(item))
            if removed:
                lines.append(t("gateway.reload_skills.removed_header"))
                for item in removed:
                    lines.append(_fmt_line(item))
            lines.append(t("gateway.reload_skills.total", count=total))

            # Queue the one-shot note for the next user turn in this session.
            # Format matches how the system prompt renders pre-existing
            # skills (``    - name: description``) so the model reads the
            # diff in the same shape as its original skill catalog.
            sections = ["[USER INITIATED SKILLS RELOAD:"]
            if added:
                sections.append("")
                sections.append("Added Skills:")
                for item in added:
                    sections.append(_fmt_line(item))
            if removed:
                sections.append("")
                sections.append("Removed Skills:")
                for item in removed:
                    sections.append(_fmt_line(item))
            sections.append("")
            sections.append("Use skills_list to see the updated catalog.]")
            note = "\n".join(sections)

            session_key = self._session_key_for_source(event.source)
            if not hasattr(self, "_pending_skills_reload_notes"):
                self._pending_skills_reload_notes = {}
            if session_key:
                self._pending_skills_reload_notes[session_key] = note

            return "\n".join(lines)

        except Exception as e:
            logger.warning("Skills reload failed: %s", e)
            return t("gateway.reload_skills.failed", error=e)

    async def _handle_bundles_command(self, event: MessageEvent) -> str:
        """Handle /bundles — list installed skill bundles.

        Mirrors the CLI ``/bundles`` handler. Returns a single text
        message suitable for any gateway adapter; bundles are loaded by
        invoking the bundle's own ``/<slug>`` command, not by this one.
        """
        try:
            from agent.skill_bundles import list_bundles, _bundles_dir
        except Exception as exc:
            logger.warning("Bundles command unavailable: %s", exc)
            return f"Bundles subsystem unavailable: {exc}"

        bundles = list_bundles()
        if not bundles:
            return (
                "No skill bundles installed.\n"
                "Create one on the host with:\n"
                "  `hermes bundles create <name> --skill <s1> --skill <s2>`\n"
                f"Directory: `{_bundles_dir()}`"
            )

        lines = [f"**Skill Bundles** ({len(bundles)} installed):", ""]
        for info in bundles:
            skill_count = len(info.get("skills", []))
            desc = info.get("description") or f"Load {skill_count} skills"
            lines.append(
                f"• `/{info['slug']}` — {desc} _({skill_count} skills)_"
            )
            for s in info.get("skills", []):
                lines.append(f"    · {s}")
        lines.append("")
        lines.append("Invoke a bundle with `/<slug>` to load all its skills.")
        return "\n".join(lines)

    async def _handle_fable_command(self, event: MessageEvent, session_key: str) -> Optional[str]:
        """Route Fable to plan-only or Discord implementation mode."""
        raw_args = event.get_command_args().strip()
        if not raw_args:
            return "Usage: /fable <request> or /fable plan <request>"

        try:
            cfg = _load_gateway_runtime_config()
        except Exception:
            cfg = {}
        try:
            session_cwd = _resolve_gateway_session_cwd(event.source, cfg)
        except Exception:
            session_cwd = ""

        from hermes_cli.fable_planner import (
            FABLE_IMPLEMENTATION_MODE,
            FABLE_PLAN_MODE,
            FablePlanRequest,
            build_fable_implementation_instruction,
            build_fable_plan_invocation,
            fable_enabled_toolsets,
            fable_metadata,
            fable_reasoning_config,
            fable_session_model_override,
            parse_fable_command_args,
        )

        is_discord = getattr(event.source, "platform", None) == Platform.DISCORD
        mode, prompt = (
            parse_fable_command_args(raw_args)
            if is_discord
            else (FABLE_PLAN_MODE, raw_args)
        )
        if not prompt:
            return (
                "Usage: /fable plan <request>"
                if mode == FABLE_PLAN_MODE
                else "Usage: /fable <request>"
            )
        if mode == FABLE_IMPLEMENTATION_MODE and not _is_standard_discord_action_request(
            event.source,
            getattr(event, "feature_summary", None),
        ):
            return (
                "⚠️ Discord `/fable <request>` must run in a normal non-Kanban "
                "action-request thread. Use `/fable plan <request>` for a plan-only artifact."
            )

        override, error = fable_session_model_override(cfg)
        if error or not override:
            return f"⚠️ {error or 'Fable 5 route unavailable.'}"

        if mode == FABLE_IMPLEMENTATION_MODE:
            session_cwd, session_cwd_error, action_worktree_cwd = await asyncio.to_thread(
                _resolve_gateway_turn_cwd,
                event.source,
                getattr(event, "feature_summary", None),
                cfg,
                session_key,
                RuntimeMode.ACTION,
                getattr(event, "discord_pr_generation", 1),
            )
            if session_cwd_error:
                logger.error(
                    "Fable action-worktree preparation failed for session %s: %s",
                    session_key,
                    session_cwd_error,
                )
                return (
                    "⚠️ I could not start this Discord `/fable` implementation safely "
                    f"in a mutable Git worktree. {session_cwd_error}"
                )
            if action_worktree_cwd:
                repository = _gateway_repository_for_source(
                    event.source,
                    workspace_path=action_worktree_cwd,
                )
                if not repository:
                    try:
                        from hermes_cli.github_remote import github_origin_repo

                        repository = str(github_origin_repo(action_worktree_cwd) or "")
                    except Exception:
                        repository = ""
                closeout_mode, closeout_policy = _gateway_action_closeout_contract(
                    cfg,
                    repository=repository,
                    request=_gateway_action_request_text(event),
                    source="fable",
                    visual_requirement=getattr(event, "visual_qa_requirement", None),
                    visual_config=getattr(event, "visual_qa_config", None),
                )
                self._persist_action_closeout_workspace(
                    event,
                    mutable_path=action_worktree_cwd,
                    canonical_path=str(event.source.project_path or ""),
                    config=cfg,
                    source="fable",
                    mode=closeout_mode,
                    policy=closeout_policy,
                )
                source = dataclasses.replace(event.source, project_path=action_worktree_cwd)
                try:
                    event.source = source
                except Exception:
                    pass
                self._cache_session_source(session_key, source)

        original_text = str(event.text or "").strip()
        request = FablePlanRequest(
            prompt=prompt,
            session_id=session_key,
            workdir=session_cwd,
            source_text=original_text,
            platform=event.source.platform.value if event.source.platform else "",
        )
        if mode == FABLE_PLAN_MODE:
            msg = build_fable_plan_invocation(request, task_id=session_key)
            if not msg:
                return "⚠️ /fable plan requires the `plan` skill, but it is not installed or could not be loaded."
        else:
            msg = build_fable_implementation_instruction(request)

        try:
            event.text = msg
            event.invoked_skill_name = "plan" if mode == FABLE_PLAN_MODE else "fable"
            event.invoked_skill_command = "fable"
            event.fable_plan_metadata = {
                **fable_metadata(config=cfg, mode=mode),
                "session_id": session_key,
                "source_message_id": str(event.message_id or ""),
            }
            if mode == FABLE_PLAN_MODE:
                event.fable_enabled_toolsets = fable_enabled_toolsets(cfg)
            event.fable_reasoning_config = fable_reasoning_config(cfg)
            event.fable_transcript_user_message = original_text
            event.fable_implementation = mode == FABLE_IMPLEMENTATION_MODE
        except Exception:
            pass

        previous_override = self._session_model_overrides.get(session_key)
        self._session_model_overrides[session_key] = override
        try:
            self._evict_cached_agent(session_key)
        except Exception:
            pass
        try:
            event.fable_previous_model_override = previous_override
        except Exception:
            pass
        return None

